,YACP,MAAMokB,EAAQ,IAAIC,SAClBD,EAAME,OAAO,KAAM2uD,EAAQ9nE,IAC3B,IACI,MAAM6X,EAAM,6BACNvM,QAAkBnD,MAAM0P,EAAK,CAACzP,OAAQ,OAAQI,KAAMyQ,IACpD5U,QAAkBiH,EAAUC,YACX2M,IAApB7T,EAAU+U,OACThc,cAAc,UAAW,UAAWiH,EAAU+U,MAAM,IACpD+E,EAAK1kB,SAAS2B,MAAK,IAEnBgC,cAAc,QAAS,UAAWiH,EAAUzE,MAAM,IAExD,MAAOA,GACLC,QAAQC,IAAIF,QAdpB,KAoBPxC,cAAc,QAAS,UAAW,gEArCK2qE,CAAgBF,EAAWppE,OAtR/E,GCAA,MACI,GAAGzI,SAASC,cAAc,sBAAsB,CAC5C,IAAI+xE,EACJA,EAA0BruE,EAAE,2BAAmCC,UAAU6B,4BAHjF","file":"bundle.ts.js","sourcesContent":[null,"const mobilemenu = document.querySelector('#mobile-menu');  //seleccion por id\r\nconst sidebar = document.querySelector('.sidebar') as HTMLElement|null;  //seleccion por calses\r\nconst btnmenux = document.querySelector('#mobile-menux');\r\nconst barra = document.querySelector('.barra-mobile') as HTMLElement|null;\r\nconst nametop:HTMLElement|null = document.querySelector('.nametop');\r\nconst selectSucursal = document.querySelector('#selectSucursal') as HTMLSelectElement;\r\nconst sucursalSeleccionada = document.querySelector('#sucursalSeleccionada') as HTMLElement|null;\r\nconst opcionesSucursal = document.querySelectorAll('.js-sucursal-option') as NodeListOf<HTMLElement>;\r\nconst toggleSucursalMenu = document.querySelector('#toggleSucursalMenu') as HTMLElement|null;\r\nconst sucursalMenuLista = document.querySelector('#sucursalMenuLista') as HTMLElement|null;\r\nconst iconSucursalMenu = document.querySelector('#iconSucursalMenu') as HTMLElement|null;\r\ndeclare let Chart:any; //declare le indica a typescript que la variable chart viene de manera externa\r\ndeclare const Swal: any;\r\ndeclare var moment: any;\r\ndeclare let List: any; \r\ndeclare let bwipjs: any;\r\ndeclare const QRCode: any;\r\ndeclare const mediosPagoDB: MedioPago[];  //mediosPagoDB inyectada por medio de json desde la vista ventas/index.php interfaz en ventas.type.ts\r\ndeclare const clientesDB: Cliente[];\r\ndeclare let comisionTotalEmpleadosDB: number;\r\ndeclare let comisionTotalPagadaBusinessDB: number;\r\ndeclare const getParam:any;  //getParam inyectada por medio de json desde la vista ventas/index.php interfaz en ventas.type.ts\r\ndeclare const percentComisionUser:string;\r\ndeclare let deudatotalCiente:string;\r\n\r\n(window as any).POS = (window as any).POS || {};\r\n\r\n // SubmÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â³dulos\r\n  if (!(window as any).POS.gestionarDescuentos) {\r\n    (window as any).POS.gestionarDescuentos = {};\r\n  }\r\n\r\nif(mobilemenu){\r\n    mobilemenu.addEventListener('click', function(){\r\n      if (sidebar && barra) {\r\n        sidebar.classList.toggle('mostrar');\r\n        barra.classList.toggle('ocultarmenu');\r\n      }\r\n    });\r\n}\r\nif(btnmenux){\r\n    btnmenux.addEventListener('click', function(){\r\n      if (sidebar && barra) {\r\n        sidebar.classList.toggle('mostrar');\r\n        barra.classList.toggle('ocultarmenu');\r\n      }\r\n    });\r\n}\r\n/////////////////////// animacion del sidebar toggle ///////////////////////////\r\ndocument.querySelector('.sidebartoggle')!.addEventListener('click', (e)=>{\r\n  if(sidebar)sidebar.classList.toggle('sidebar-fija');\r\n});\r\n\r\n//------------------------------------------------------------------------------------------------------------------//\r\n///////////////////// OBJETO DE CONFIGURACION DEL PLUGIN DATATABLES /////////////////////\r\nconst configdatatables = {\r\n  \"paging\": true,\r\n  \"lengthChange\": true,\r\n  \"searching\": true,\r\n  \"ordering\": true,\r\n  \"info\": true,\r\n  \"autoWidth\": true,\r\n  \"responsive\": true,\r\n  \"deferRender\": true,\r\n  \"retrieve\": true,\r\n  \"processing\": true,\r\n  language: {\r\n      search: 'Busqueda',\r\n      emptyTable: 'No Hay datos disponibles',\r\n      zeroRecords:    \"No se encontraron registros coincidentes\",\r\n      lengthMenu: '_MENU_ Entradas por pagina',\r\n      info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n      infoEmpty: 'No hay entradas a mostrar',\r\n      infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n      paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n  }\r\n}\r\n\r\nconst configdatatablesToolbar = {\r\n  ...configdatatables,\r\n  dom: 'rtip'\r\n}\r\n\r\nfunction modernizarToolbarDataTable(selectorTabla:string):void{\r\n  const montarToolbar = ():void => {\r\n    const idTabla = selectorTabla.replace('#', '');\r\n    const wrapper = document.querySelector(`#${idTabla}_wrapper`) as HTMLElement|null;\r\n    const tabla = document.querySelector(selectorTabla) as HTMLTableElement|null;\r\n    const card = wrapper?.closest('.config-table-card') as HTMLElement|null;\r\n    const ocultarControlesNativos = ():void => {\r\n      card?.querySelectorAll('.dataTables_length, .dataTables_filter').forEach((control)=>{\r\n        (control as HTMLElement).remove();\r\n      });\r\n    };\r\n\r\n    if(!wrapper || !tabla || !card)return;\r\n    if(card.querySelector('.config-datatable-custom-toolbar')){\r\n      ocultarControlesNativos();\r\n      return;\r\n    }\r\n\r\n    const dataTable = ($(selectorTabla) as any).DataTable();\r\n\r\n    const toolbar = document.createElement('div');\r\n    toolbar.className = 'config-datatable-custom-toolbar';\r\n    toolbar.innerHTML = `\r\n      <div class=\"config-datatable-custom-field config-datatable-custom-field--length\">\r\n        <span class=\"config-datatable-custom-icon\"><i class=\"fa-solid fa-list\"></i></span>\r\n        <span class=\"config-datatable-custom-label\">Mostrar</span>\r\n        <div class=\"config-datatable-length-select\">\r\n          <button id=\"${idTabla}CustomLength\" type=\"button\" class=\"config-datatable-length-select__button\" aria-label=\"Entradas por pagina\" aria-expanded=\"false\">\r\n            <span>10</span>\r\n            <i class=\"fa-solid fa-chevron-down\"></i>\r\n          </button>\r\n          <div class=\"config-datatable-length-select__menu\" role=\"listbox\">\r\n            <button type=\"button\" data-value=\"10\" role=\"option\">10</button>\r\n            <button type=\"button\" data-value=\"25\" role=\"option\">25</button>\r\n            <button type=\"button\" data-value=\"50\" role=\"option\">50</button>\r\n            <button type=\"button\" data-value=\"100\" role=\"option\">100</button>\r\n          </div>\r\n        </div>\r\n        <span>entradas por pagina</span>\r\n      </div>\r\n      <div class=\"config-datatable-custom-field config-datatable-custom-field--search\">\r\n        <span class=\"config-datatable-custom-icon\"><i class=\"fa-solid fa-magnifying-glass\"></i></span>\r\n        <label for=\"${idTabla}CustomSearch\">Busqueda</label>\r\n        <input id=\"${idTabla}CustomSearch\" type=\"search\" placeholder=\"Buscar registro\" aria-label=\"Buscar registro\">\r\n      </div>\r\n    `;\r\n\r\n    card.insertBefore(toolbar, wrapper);\r\n    card.classList.add('has-custom-datatable-toolbar');\r\n\r\n    ocultarControlesNativos();\r\n\r\n    const selectLength = toolbar.querySelector(`#${idTabla}CustomLength`) as HTMLButtonElement|null;\r\n    const selectLengthText = selectLength?.querySelector('span') as HTMLSpanElement|null;\r\n    const selectLengthMenu = toolbar.querySelector('.config-datatable-length-select__menu') as HTMLElement|null;\r\n    const inputSearch = toolbar.querySelector(`#${idTabla}CustomSearch`) as HTMLInputElement|null;\r\n\r\n    if(selectLength){\r\n      const pageLength = dataTable.page.len();\r\n      if(selectLengthText)selectLengthText.textContent = String(pageLength > 0 ? pageLength : 10);\r\n\r\n      selectLength.addEventListener('click', (event)=>{\r\n        event.stopPropagation();\r\n        const abierto = toolbar.classList.toggle('is-length-open');\r\n        selectLength.setAttribute('aria-expanded', abierto ? 'true' : 'false');\r\n      });\r\n\r\n      selectLengthMenu?.querySelectorAll('button').forEach((opcion)=>{\r\n        opcion.addEventListener('click', (event)=>{\r\n          event.stopPropagation();\r\n          const valor = Number((opcion as HTMLButtonElement).dataset.value);\r\n          if(selectLengthText)selectLengthText.textContent = String(valor);\r\n          dataTable.page.len(valor).draw();\r\n          toolbar.classList.remove('is-length-open');\r\n          selectLength.setAttribute('aria-expanded', 'false');\r\n        });\r\n      });\r\n\r\n      document.addEventListener('click', ()=>{\r\n        toolbar.classList.remove('is-length-open');\r\n        selectLength.setAttribute('aria-expanded', 'false');\r\n      });\r\n    }\r\n\r\n    inputSearch?.addEventListener('input', ()=> dataTable.search(inputSearch.value).draw());\r\n    ($(selectorTabla) as any).on('draw.dt', ocultarControlesNativos);\r\n  };\r\n\r\n  montarToolbar();\r\n  window.requestAnimationFrame(montarToolbar);\r\n  window.setTimeout(montarToolbar, 100);\r\n  window.setTimeout(montarToolbar, 300);\r\n  window.setTimeout(montarToolbar, 700);\r\n}\r\n\r\n///////////////////// OBJETO DE CONFIGURACION DEL PLUGIN DATATABLES PARA 25 REGISTROS /////////////////////\r\nconst configdatatables25reg = {\r\n  pageLength: 25,\r\n  \"paging\": true,\r\n  \"lengthChange\": true,\r\n  \"searching\": true,\r\n  \"ordering\": true,\r\n  \"info\": true,\r\n  \"autoWidth\": true,\r\n  \"responsive\": true,\r\n  \"deferRender\": true,\r\n  \"retrieve\": true,\r\n  \"processing\": true,\r\n  language: {\r\n      search: 'Busqueda',\r\n      emptyTable: 'No Hay datos disponibles',\r\n      zeroRecords:    \"No se encontraron registros coincidentes\",\r\n      lengthMenu: '_MENU_ Entradas por pagina',\r\n      info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n      infoEmpty: 'No hay entradas a mostrar',\r\n      infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n      paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n  }\r\n}\r\n\r\n///////////////////// OBJETO DE CONFIGURACION DEL PLUGIN DATATABLES PARA GENERAL /////////////////////\r\nconst configdatatablesgenerico = {\r\n  layout: {\r\n        topStart: {\r\n            buttons: [\r\n              {extend: 'copyHtml5', text: 'Copia'}, \r\n              {extend: 'excelHtml5', title: 'informe'}, \r\n              {extend: 'csvHtml5', title: 'informe'}, \r\n              {extend: 'pdfHtml5', title: 'informe'}, \r\n              {extend: 'print', title: 'informe', text: 'Imprimir'},\r\n              'colvis'\r\n            ],\r\n            pageLength: 'pageLength'\r\n        }\r\n  },\r\n  pageLength: 25,\r\n  \"paging\": true,\r\n  \"lengthChange\": true,\r\n  \"searching\": true,\r\n  \"ordering\": true,\r\n  \"info\": true,\r\n  \"autoWidth\": true,\r\n  \"responsive\": true,\r\n  \"deferRender\": true,\r\n  \"retrieve\": true,\r\n  \"processing\": true,\r\n  language: {\r\n      search: 'Busqueda',\r\n      emptyTable: 'No Hay datos disponibles',\r\n      zeroRecords:    \"No se encontraron registros coincidentes\",\r\n      lengthMenu: '_MENU_ Entradas por pagina',\r\n      info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n      infoEmpty: 'No hay entradas a mostrar',\r\n      infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n      paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n  }\r\n}\r\n\r\n///////////////////// OBJETO DE CONFIGURACION DEL PLUGIN DATATABLES PARA STOCK RAPIDO /////////////////////\r\nconst configdatatablesstockrapido = {\r\n  layout: {\r\n        topStart: {\r\n            buttons: [\r\n              {extend: 'copyHtml5', text: 'Copia'}, \r\n              {extend: 'excelHtml5', exportOptions: {columns: [1, 2, 3, 4, 5]}, title: 'Stock-inventario'}, \r\n              {extend: 'csvHtml5', exportOptions: {columns: [1, 2, 3, 4, 5]}, title: 'Stock-inventario'}, \r\n              {extend: 'pdfHtml5', exportOptions: {columns: [1, 2, 3, 4, 5]}, title: 'Stock-inventario'}, \r\n              {extend: 'print', exportOptions: {columns: [1, 3, 4]}, title: 'Stock-inventario', text: 'Imprimir'},\r\n              'colvis'\r\n            ],\r\n            pageLength: 'pageLength'\r\n        }\r\n  },\r\n  pageLength: 25,\r\n  \"paging\": true,\r\n  \"lengthChange\": true,\r\n  \"searching\": true,\r\n  \"ordering\": true,\r\n  \"info\": true,\r\n  \"autoWidth\": true,\r\n  \"responsive\": true,\r\n  \"deferRender\": true,\r\n  \"retrieve\": true,\r\n  \"processing\": true,\r\n  language: {\r\n      search: 'Busqueda',\r\n      emptyTable: 'No Hay datos disponibles',\r\n      zeroRecords:    \"No se encontraron registros coincidentes\",\r\n      lengthMenu: '_MENU_ Entradas por pagina',\r\n      info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n      infoEmpty: 'No hay entradas a mostrar',\r\n      infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n      paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n  }\r\n}\r\n\r\n///////////////////// OBJETO DE CONFIGURACION DEL PLUGIN DATATABLES PARA AJUSTAR COSTOS /////////////////////\r\nconst configdatatablesajustarcostos = {\r\n  layout: {\r\n        topStart: {\r\n            buttons: [\r\n              {extend: 'copyHtml5', text: 'Copia'}, \r\n              {extend: 'excelHtml5', exportOptions: {columns: [1, 3, 4, 5, 6]}, title: 'costo por producto'}, \r\n              {extend: 'csvHtml5', exportOptions: {columns: [1, 3, 4, 5, 6]}, title: 'costo por producto'}, \r\n              {extend: 'pdfHtml5', exportOptions: {columns: [1, 3, 4, 5, 6]}, title: 'costo por producto'}, \r\n              {extend: 'print', exportOptions: {columns: [1, 3, 4, 5, 6]}, title: 'costo por producto', text: 'Imprimir'},\r\n              'colvis'\r\n            ],\r\n            pageLength: 'pageLength'\r\n        }\r\n  },\r\n  pageLength: 25,\r\n  \"paging\": true,\r\n  \"lengthChange\": true,\r\n  \"searching\": true,\r\n  \"ordering\": true,\r\n  \"info\": true,\r\n  \"autoWidth\": true,\r\n  \"responsive\": true,\r\n  \"deferRender\": true,\r\n  \"retrieve\": true,\r\n  \"processing\": true,\r\n  language: {\r\n      search: 'Busqueda',\r\n      emptyTable: 'No Hay datos disponibles',\r\n      zeroRecords:    \"No se encontraron registros coincidentes\",\r\n      lengthMenu: '_MENU_ Entradas por pagina',\r\n      info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n      infoEmpty: 'No hay entradas a mostrar',\r\n      infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n      paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n  }\r\n}\r\n\r\n///////////////////// CONFIGURACION DEL PLUGIN DATATABLES PARA CAJA/////////////////////\r\nconst configdatatablescaja = {\r\n  \"paging\": false,\r\n  \"order\": [[ 4, 'desc' ]],\r\n  \"searching\": false,\r\n  \"ordering\": true,\r\n  \"info\": true,\r\n  \"autoWidth\": true,\r\n  \"responsive\": true,\r\n  \"deferRender\": true,\r\n  \"retrieve\": true,\r\n  \"processing\": true,\r\n  language: {\r\n      search: 'Busqueda',\r\n      emptyTable: 'No Hay datos disponibles',\r\n      zeroRecords:    \"No se encontraron registros coincidentes\",\r\n      lengthMenu: '_MENU_ Entradas por pagina',\r\n      info: 'Mostrando 1 de _MAX_ registros',\r\n      infoEmpty: 'No hay entradas a mostrar',\r\n      infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n      paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n  }\r\n}\r\n\r\n\r\n///////////////////// CONFIGURACION DEL PLUGIN DATATABLES PARA STOCK BAJO/////////////////////\r\nconst configdatatablesstockbajo = {\r\n  destroy: true,\r\n  lengthChange: false,\r\n  pageLength: 25,\r\n  //responsive: true,\r\n  order: [[ 3, 'asc' ]],\r\n  language: {\r\n      search: 'Busqueda',\r\n      emptyTable: 'No Hay datos disponibles',\r\n      zeroRecords:    \"No se encontraron registros coincidentes\",\r\n      info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n      infoEmpty: 'No hay entradas a mostrar',\r\n      infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n      paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n  },\r\n  layout: {\r\n      topStart: {\r\n          buttons: [\r\n              {extend: 'excelHtml5', title: 'Stock bajo'},  \r\n              {extend: 'pdfHtml5', title: 'Stock bajo'}, \r\n              {extend: 'print', title: 'Stock bajo', text: 'Imprimir'},\r\n              'colvis'\r\n          ],\r\n          pageLength: 'pageLength'\r\n      }\r\n  }\r\n}\r\n\r\n///////////////////// FUNCION QUE IMPRIME MENSAJE TIPO ALERTA /////////////////////\r\nfunction msjAlert(tipo:string, msj:string, divmsjalerta:HTMLElement):void{\r\n  const esError = tipo === 'error';\r\n  const titulo = esError ? 'Atencion requerida' : 'Operacion exitosa';\r\n  const icono = esError ? 'fa-circle-exclamation' : 'fa-circle-check';\r\n  divmsjalerta.insertAdjacentHTML('beforeend', `<div class=\"alerta alerta__${tipo}\" role=\"alert\">\r\n      <span class=\"alerta__icono\"><i class=\"fa-solid ${icono}\"></i></span>\r\n      <span class=\"alerta__contenido\">\r\n        <strong>${titulo}</strong>\r\n        <span>${msj}</span>\r\n      </span>\r\n    </div>`\r\n  );\r\n  borrarMsjAlert(divmsjalerta);\r\n}\r\n//////////////////// BORRAR MENSAJES TIPO ALERTA /////////////////////\r\n/*(borrarMsjAlert =()=>{  //se aplica de manera global\r\n  const msj = document.querySelector('#divmsjalerta');\r\n  if(document.querySelector('.alerta'))setTimeout(()=>{ while(msj.firstChild)msj.removeChild(msj.firstChild);}, 5000);\r\n})();*/\r\nfunction borrarMsjAlert(divmsj:HTMLElement):void{  //se aplica de manera global\r\n  //const msj = document.querySelector('#divmsjalerta')!;\r\n  if(document.querySelector('.alerta'))setTimeout(()=>{ while(divmsj.firstChild)divmsj.removeChild(divmsj.firstChild);}, 5000);\r\n}\r\n//////////////////// FUNCION QUE IMPRIME UN MENSAJE FORMATO TOAST ////////////////////\r\n//msjalertToast('error', 'ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡Error!', 'debe seleccionar una imagen')\r\nfunction msjalertToast(icono:string, tipo:string, msj:string){\r\n    Swal.fire({\r\n    icon: icono,\r\n    title: tipo,\r\n    text: msj,\r\n    toast: true,\r\n    position: 'top-end',\r\n    showConfirmButton: false,\r\n    timer: 3200,\r\n    timerProgressBar: true,\r\n    showClass: {\r\n      popup: 'animate__animated animate__fadeInRight animate__faster'\r\n    },\r\n    hideClass: {\r\n      popup: 'animate__animated animate__fadeOutRight animate__faster'\r\n    },\r\n    customClass: {\r\n      popup: `j2-toast j2-toast--${icono}`,\r\n      icon: 'j2-toast__icon',\r\n      title: 'j2-toast__title',\r\n      htmlContainer: 'j2-toast__text',\r\n      timerProgressBar: 'j2-toast__progress'\r\n    }\r\n    });\r\n}\r\n\r\n/////////////////// FUNCION CONTADOR DE CARACTERES ////////////////////\r\n(function countchars():void{\r\n  const numinput = document.querySelectorAll('.count-charts') as NodeListOf<HTMLElement>;  \r\n  numinput.forEach(element =>{ //element es cada label\r\n      element.textContent = (parseInt(element.dataset.num!)-(element.previousElementSibling as HTMLInputElement).value.length).toString();\r\n      element.previousElementSibling?.addEventListener('input', (e)=>{ //seleccionamos el input o el textarea en donde se escribe y se le da el evento de teclas\r\n          element.textContent = parseInt(element.dataset.num!)-(e.target as HTMLInputElement).value.length+\"\";\r\n            \r\n          if(parseInt(element.dataset.num!)-(e.target as HTMLInputElement).value.length <= 0){\r\n              let cadena = (e.target as HTMLInputElement).value.slice(0, parseInt(element.dataset.num!));\r\n              (e.target as HTMLInputElement).value = cadena;\r\n              element.textContent =`${0}`;\r\n          }\r\n      });\r\n  });\r\n})();\r\n\r\n/////////////////// paginacion de negocio empleado, malla, config //////////////////\r\nif(document.querySelector('#tabulacion')){ // view/admin/adminconfig/index.php\r\n  const renderid = document.querySelector('#tabulacion input[type=\"radio\"]:checked')!.nextElementSibling as HTMLElement; //se selecciona el input cheked y luego su span q contiene el id de la pagina a mostrar\r\n  const mostrarPaginaConfiguracion = (idPagina:string):void => {\r\n    const paginaActiva = document.querySelector<HTMLElement>(`.${idPagina}`);\r\n    if(!paginaActiva)return;\r\n\r\n    paginas.forEach(pagina => pagina.style.display = \"none\"); ////quitamos la class mostrarseccion a todas las secciones\r\n    paginaActiva.style.display = \"block\"; //mostramos la seccion correspondiente\r\n\r\n    window.setTimeout(()=>{\r\n      try{\r\n        (($.fn as any).dataTable)?.tables({ visible: true, api: true }).columns.adjust().responsive?.recalc();\r\n      }catch(error){\r\n        console.log(error);\r\n      }\r\n    }, 0);\r\n  };\r\n  const btns_navtabs = document.querySelectorAll('.tabs span');\r\n  const paginas = document.querySelectorAll<HTMLElement>('.paginas'); //seleccionamos las secciones o paginas a mostrar\r\n  mostrarPaginaConfiguracion(renderid.id);\r\n  btns_navtabs.forEach(Element => {\r\n      Element.addEventListener('click', (e)=>{ //cada btn o enlace\r\n          const target = e.target as HTMLElement;\r\n          const tab = target.closest('span[id^=\"pagina\"]') as HTMLElement|null;\r\n          if(!tab)return;\r\n          mostrarPaginaConfiguracion(tab.id);\r\n      });\r\n  });\r\n}\r\n\r\nfunction mesyanoactual():[string, number]\r\n{\r\n  const fecha = new Date();\r\n  const mesTexto:string = fecha.toLocaleString('es-CO', { month: 'long' });\r\n  const ano:number = fecha.getFullYear();\r\n  return [mesTexto, ano];\r\n}\r\n\r\nfunction getDgv(nit: number): number {\r\n    const multiplicadores = [3, 7, 13, 17, 19, 23, 29, 37, 41, 43, 47, 53, 59, 67, 71];\r\n    const digitos = nit.toString().trim().split('').map(Number);\r\n    let suma = 0;\r\n    digitos.forEach((digito, indice) => {\r\n        const posicionMultiplicador = digitos.length - indice;\r\n        suma += digito * multiplicadores[posicionMultiplicador - 1];\r\n    }); \r\n    const modulo = suma%11;\r\n    return modulo > 1 ?(11 - modulo):modulo;\r\n}\r\n\r\n\r\nlet audioCtx: AudioContext;\r\nfunction beep(frecuencia = 800, duracion = 60) {\r\n  if (!audioCtx) audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();\r\n  const osc = audioCtx.createOscillator();\r\n  const gain = audioCtx.createGain();\r\n\r\n  osc.frequency.value = frecuencia;\r\n  osc.type = 'square';\r\n  gain.gain.value = 0.08;\r\n\r\n  osc.connect(gain);\r\n  gain.connect(audioCtx.destination);\r\n\r\n  osc.start();\r\n  osc.stop(audioCtx.currentTime + duracion / 1000);\r\n}\r\n\r\n\r\nfunction flashCantidad(element:HTMLElement, color:string) {\r\n    const clase = color === 'up'? 'bg-green-200': 'bg-red-200';\r\n    element.classList.add(clase);\r\n    setTimeout(() => element.classList.remove(clase), 120);\r\n}\r\n\r\n\r\nfunction bytesToBase64(data: string|Uint8Array) {\r\n    if (typeof data === 'string')\r\n      return btoa(data);\r\n\r\n    let binary = '';\r\n    if(data instanceof Uint8Array)\r\n      for (let i = 0; i < data.length; i++) \r\n          binary += String.fromCharCode(data[i]);\r\n    return btoa(binary);\r\n}\r\n\r\n\r\nfunction formatearMoneda(input: HTMLInputElement): void {\r\n    let valor = input.value.replace(/[^\\d,]/g, '');\r\n    //const partes = valor.split(',');\r\n    // Formatear parte entera\r\n    //partes[0] = parseInt(partes[0] || '0').toLocaleString('es-CO');\r\n\r\n    let [entera, ...decimales] = valor.split(',');\r\n    entera= parseInt(entera || '0').toLocaleString('es-CO');\r\n    /*if (partes.length > 2) {\r\n      valor = partes[0] + ',' + partes.slice(1).join('');\r\n    }*/\r\n    // MÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ximo 2 decimales\r\n    //if (partes[1])partes[1] = partes[1].substring(0, 2);\r\n    //input.value = partes.join(',');\r\n    input.value = entera+(decimales.length ? ',' + decimales.join('') : '');\r\n}\r\n\r\n\r\nfunction obtenerNumero(input: HTMLInputElement):number|null{\r\n    const valor = input.value.replace(/\\./g, '').replace(',', '.').trim();\r\n    if (valor === '')return null;\r\n    const numero = Number(valor);\r\n    return Number.isNaN(numero) ? null : numero;\r\n}\r\n\r\n\r\nfunction filtrarInsumos(productoConfigurado:Partial<productsapi>|undefined):void{\r\n  const insumos = productoConfigurado?.insumos;\r\n  if(!insumos?.length) return;\r\n\r\n  const insumosActivos = insumos.filter(insumoActual =>\r\n    insumoActual.grupos_insumos === null || insumoActual.seleccionado === \"1\"\r\n  );\r\n  insumos.splice(0, insumos.length, ...insumosActivos);\r\n}\r\n\r\n\r\nfunction cerrarMenuSucursal():void{\r\n  sucursalMenuLista?.classList.add('hidden');\r\n  iconSucursalMenu?.classList.remove('rotate-180');\r\n}\r\n\r\ntoggleSucursalMenu?.addEventListener('click', (event:MouseEvent)=>{\r\n  event.stopPropagation();\r\n  sucursalMenuLista?.classList.toggle('hidden');\r\n  iconSucursalMenu?.classList.toggle('rotate-180');\r\n});\r\n\r\nopcionesSucursal.forEach((opcion)=>{\r\n  opcion.addEventListener('click', ()=>{\r\n    const value = opcion.dataset.sucursalValue || '';\r\n    const label = opcion.dataset.sucursalLabel || opcion.textContent?.trim() || 'Cambiar de Sede';\r\n    if(selectSucursal){\r\n      selectSucursal.value = value;\r\n      selectSucursal.dispatchEvent(new Event('change', {bubbles: true}));\r\n      selectSucursal.dispatchEvent(new Event('click', {bubbles: true}));\r\n    }\r\n    if(sucursalSeleccionada){\r\n      sucursalSeleccionada.textContent = label;\r\n    }\r\n    cerrarMenuSucursal();\r\n  });\r\n\r\n  opcion.addEventListener('keydown', (event:KeyboardEvent)=>{\r\n    if(event.key === 'Enter' || event.key === ' '){\r\n      event.preventDefault();\r\n      opcion.click();\r\n    }\r\n  });\r\n});\r\n\r\ndocument.addEventListener('click', (event:MouseEvent)=>{\r\n  const target = event.target as Node;\r\n  if(sucursalMenuLista && toggleSucursalMenu && !sucursalMenuLista.contains(target) && !toggleSucursalMenu.contains(target)){\r\n    cerrarMenuSucursal();\r\n  }\r\n});\r\n\r\nfunction inicializarBuscadorParametrosSistema():void{\r\n  const buscador = document.querySelector('#buscarParametroSistema') as HTMLInputElement|null;\r\n  const limpiar = document.querySelector('#limpiarBusquedaParametroSistema') as HTMLButtonElement|null;\r\n  const resultado = document.querySelector('#resultadoBusquedaParametroSistema') as HTMLElement|null;\r\n  const contenedor = document.querySelector('.config-system-content') as HTMLElement|null;\r\n  const barra = document.querySelector('.config-param-search') as HTMLElement|null;\r\n\r\n  if(!buscador || !contenedor)return;\r\n\r\n  const sistema = contenedor.closest('.config-system') as HTMLElement|null;\r\n  const paneles = Array.from(contenedor.querySelectorAll('.accordion_tab_content')) as HTMLElement[];\r\n\r\n  const normalizarTexto = (texto:string):string => texto\r\n    .normalize('NFD')\r\n    .replace(/[\\u0300-\\u036f]/g, '')\r\n    .toLowerCase()\r\n    .trim();\r\n\r\n  const obtenerPanel = (elemento:Element):HTMLElement|null => elemento.closest('.accordion_tab_content') as HTMLElement|null;\r\n\r\n  const obtenerNumeroPanel = (panel:HTMLElement|null):string|null => {\r\n    if(!panel)return null;\r\n    const claseContenido = Array.from(panel.classList).find((clase)=>/^contenido\\d+$/.test(clase));\r\n    return claseContenido ? claseContenido.replace('contenido', '') : null;\r\n  };\r\n\r\n  const camposPorContenedor = new Map<HTMLElement, {\r\n    contenedorCampo: HTMLElement,\r\n    panel: HTMLElement,\r\n    numeroPanel: string,\r\n    textos: string[]\r\n  }>();\r\n\r\n  Array.from(contenedor.querySelectorAll('label')).forEach((label)=>{\r\n    const etiqueta = label as HTMLElement;\r\n    const fieldId = etiqueta.getAttribute('for') || '';\r\n    const input = fieldId ? document.getElementById(fieldId) as HTMLInputElement|null : null;\r\n    const contenedorCampo = (etiqueta.closest('.formulario__campo') || etiqueta.parentElement) as HTMLElement|null;\r\n    const panel = obtenerPanel(etiqueta);\r\n    const numeroPanel = obtenerNumeroPanel(panel);\r\n\r\n    if(!contenedorCampo || !panel || !numeroPanel)return;\r\n\r\n    const textoBusqueda = [\r\n      etiqueta.innerText,\r\n      input?.placeholder || '',\r\n      input?.name || '',\r\n      input?.id || ''\r\n    ].join(' ');\r\n\r\n    const campoExistente = camposPorContenedor.get(contenedorCampo);\r\n    if(campoExistente){\r\n      campoExistente.textos.push(textoBusqueda);\r\n      return;\r\n    }\r\n\r\n    camposPorContenedor.set(contenedorCampo, {\r\n      contenedorCampo,\r\n      panel,\r\n      numeroPanel,\r\n      textos: [textoBusqueda]\r\n    });\r\n  });\r\n\r\n  const campos = Array.from(camposPorContenedor.values()).map((campo)=>({\r\n    contenedorCampo: campo.contenedorCampo,\r\n    panel: campo.panel,\r\n    numeroPanel: campo.numeroPanel,\r\n    textoBusqueda: normalizarTexto([\r\n      campo.contenedorCampo.innerText,\r\n      ...campo.textos\r\n    ].join(' '))\r\n  }));\r\n\r\n  const limpiarFiltro = ():void => {\r\n    barra?.classList.remove('has-query');\r\n    sistema?.classList.remove('param-search-active');\r\n    paneles.forEach((panel)=>panel.classList.remove('config-param-panel-match'));\r\n    campos.forEach((campo)=>{\r\n      campo.contenedorCampo?.classList.remove('config-param-hidden', 'config-param-match');\r\n    });\r\n    if(resultado)resultado.textContent = '';\r\n  };\r\n\r\n  const aplicarFiltro = ():void => {\r\n    const termino = normalizarTexto(buscador.value);\r\n    if(!termino){\r\n      limpiarFiltro();\r\n      return;\r\n    }\r\n\r\n    barra?.classList.add('has-query');\r\n    sistema?.classList.add('param-search-active');\r\n    const coincidencias = campos.filter((campo)=>campo.textoBusqueda.includes(termino));\r\n    const panelesConCoincidencias = new Set(coincidencias.map((campo)=>campo.panel));\r\n\r\n    paneles.forEach((panel)=>{\r\n      panel.classList.toggle('config-param-panel-match', panelesConCoincidencias.has(panel));\r\n    });\r\n\r\n    campos.forEach((campo)=>{\r\n      const coincide = campo.textoBusqueda.includes(termino);\r\n      campo.contenedorCampo?.classList.toggle('config-param-hidden', !coincide);\r\n      campo.contenedorCampo?.classList.toggle('config-param-match', coincide);\r\n    });\r\n\r\n    const primeraCoincidencia = coincidencias[0];\r\n    if(!primeraCoincidencia || !primeraCoincidencia.numeroPanel){\r\n      if(resultado)resultado.textContent = '0 resultados';\r\n      return;\r\n    }\r\n\r\n    if(resultado){\r\n      const totalResultados = coincidencias.length;\r\n      resultado.textContent = totalResultados === 1 ? '1 resultado' : `${totalResultados} resultados`;\r\n    }\r\n\r\n    const radio = document.querySelector(`#btn${primeraCoincidencia.numeroPanel}`) as HTMLInputElement|null;\r\n    if(radio && !radio.checked){\r\n      radio.checked = true;\r\n      radio.dispatchEvent(new Event('change', {bubbles: true}));\r\n    }\r\n\r\n    window.setTimeout(()=>{\r\n      primeraCoincidencia.contenedorCampo?.scrollIntoView({behavior: 'smooth', block: 'center'});\r\n    }, 80);\r\n  };\r\n\r\n  buscador.addEventListener('input', aplicarFiltro);\r\n  sistema?.querySelectorAll('.config-system-nav .config-system-tab').forEach((tab)=>{\r\n    tab.addEventListener('click', ()=>{\r\n      if(!buscador.value)return;\r\n      buscador.value = '';\r\n      limpiarFiltro();\r\n    });\r\n  });\r\n  limpiar?.addEventListener('click', ()=>{\r\n    buscador.value = '';\r\n    buscador.focus();\r\n    limpiarFiltro();\r\n  });\r\n}\r\n\r\ninicializarBuscadorParametrosSistema();\r\n//evento para el cambio de sucursal\r\nselectSucursal.addEventListener('click', async()=>{\r\n\r\n  const datos = {\r\n      idsucursal: \"Juan\",\r\n      edad: 30,\r\n      ciudad: \"BogotÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡\"\r\n  };\r\n\r\n  const url = \"/admin/api/changeSucursal/select\";\r\n                const respuesta = await fetch(url, {\r\n                                            method: 'POST', \r\n                                            headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                            body: JSON.stringify(datos) \r\n                                        });\r\n\r\n  \r\n});\r\n","(function():void{\n  if(document.querySelector('.inicio')){\n    const formatoMoneda = new Intl.NumberFormat('es-CO', {\n      maximumFractionDigits: 0,\n      minimumFractionDigits: 0\n    });\n\n    const normalizarNumero = (valor:string | number | null | undefined):number => {\n      const numero = Number(valor ?? 0);\n      return Number.isFinite(numero) ? numero : 0;\n    };\n\n    const crearGradiente = (ctx:CanvasRenderingContext2D, colorInicio:string, colorFin:string):CanvasGradient => {\n      const gradient = ctx.createLinearGradient(0, 0, 0, 320);\n      gradient.addColorStop(0, colorInicio);\n      gradient.addColorStop(1, colorFin);\n      return gradient;\n    };\n\n    const opcionesBase = {\n      animation: {\n        duration: 750,\n        easing: 'easeOutQuart'\n      },\n      maintainAspectRatio: false,\n      responsive: true,\n      plugins: {\n        legend: {\n          labels: {\n            boxHeight: 10,\n            boxWidth: 10,\n            color: '#475569',\n            font: {\n              size: 12,\n              weight: '700'\n            },\n            padding: 14,\n            usePointStyle: true\n          }\n        },\n        tooltip: {\n          backgroundColor: '#14233b',\n          bodyColor: '#fff',\n          borderColor: 'rgba(79, 70, 229, .25)',\n          borderWidth: 1,\n          cornerRadius: 10,\n          displayColors: true,\n          padding: 12,\n          titleColor: '#e0f2fe'\n        }\n      }\n    } as any;\n\n    async function ventasgraficas($url:string, $dato:string){\n      try{\n        const respuesta = await fetch($url);\n        const resultado = await respuesta.json();\n        if($dato == 'ventasVsGastos')graficaVentasVsGastos(resultado);\n        if($dato == 'ultimos7dias')ventas7dias(resultado);\n      }catch(error){\n        console.log(error);\n      }\n    }\n\n    ventasgraficas('/admin/api/ventasVsGastos', 'ventasVsGastos');\n    ventasgraficas('/admin/api/ultimos7dias', 'ultimos7dias');\n\n    function ventas7dias(resultado:{dia:string, ventas_totales:string}[]){\n      const canvas = document.getElementById('chartIngresosDias') as HTMLCanvasElement | null;\n      const ctxIngresosDias = canvas?.getContext('2d');\n      if(!ctxIngresosDias)return;\n\n      const gradienteIngresos = crearGradiente(ctxIngresosDias, 'rgba(6, 182, 212, .92)', 'rgba(79, 70, 229, .16)');\n\n      new Chart(ctxIngresosDias, {\n        type: 'bar',\n        data: {\n          labels: resultado.map(x=>x.dia),\n          datasets: [{\n            label: 'Ingresos',\n            data: resultado.map(x=>normalizarNumero(x.ventas_totales)),\n            backgroundColor: gradienteIngresos,\n            borderColor: 'rgba(6, 182, 212, .92)',\n            borderRadius: 10,\n            borderSkipped: false,\n            borderWidth: 1,\n            hoverBackgroundColor: 'rgba(79, 70, 229, .86)',\n            maxBarThickness: 58\n          }]\n        },\n        options: {\n          ...opcionesBase,\n          plugins: {\n            ...opcionesBase.plugins,\n            legend: {display: false},\n            tooltip: {\n              ...opcionesBase.plugins.tooltip,\n              displayColors: false,\n              callbacks: {\n                label: (context:any) => `Ingresos: $${formatoMoneda.format(normalizarNumero(context.parsed.y))}`\n              }\n            }\n          },\n          scales: {\n            y: {\n              beginAtZero: true,\n              border: {display: false},\n              grid: {color: 'rgba(148, 163, 184, .16)', drawBorder: false},\n              ticks: {\n                color: '#64748b',\n                font: {size: 12, weight: '600'},\n                callback: (value:any) => formatoMoneda.format(normalizarNumero(value))\n              }\n            },\n            x: {\n              border: {display: false},\n              grid: {display: false},\n              ticks: {color: '#64748b', font: {size: 12, weight: '600'}}\n            }\n          }\n        }\n      });\n    }\n\n    function graficaVentasVsGastos(resultado:{periodo:string[], ventastotales:string[], gastostotales:string[]}){\n      const canvas = document.getElementById('chartVentasGastos') as HTMLCanvasElement | null;\n      const ctxVG = canvas?.getContext('2d');\n      if(!ctxVG)return;\n\n      const gradienteVentas = crearGradiente(ctxVG, 'rgba(79, 70, 229, .9)', 'rgba(79, 70, 229, .14)');\n      const gradienteGastos = crearGradiente(ctxVG, 'rgba(6, 182, 212, .18)', 'rgba(6, 182, 212, .02)');\n\n      new Chart(ctxVG, {\n        data: {\n          labels: resultado.periodo,\n          datasets: [\n            {\n              type: 'bar',\n              label: 'Ventas',\n              data: resultado.ventastotales.map(x=>normalizarNumero(x)),\n              backgroundColor: gradienteVentas,\n              borderColor: 'rgba(79, 70, 229, .92)',\n              borderRadius: 10,\n              borderSkipped: false,\n              borderWidth: 1,\n              maxBarThickness: 48,\n              order: 2\n            },\n            {\n              type: 'line',\n              label: 'Gastos',\n              data: resultado.gastostotales.map(x=>normalizarNumero(x)),\n              borderColor: '#06b6d4',\n              backgroundColor: gradienteGastos,\n              borderWidth: 3,\n              fill: true,\n              pointBackgroundColor: '#fff',\n              pointBorderColor: '#06b6d4',\n              pointBorderWidth: 2,\n              pointHoverRadius: 6,\n              pointRadius: 4,\n              tension: 0.35,\n              yAxisID: 'y1',\n              order: 1\n            }\n          ]\n        },\n        options: {\n          ...opcionesBase,\n          plugins: {\n            ...opcionesBase.plugins,\n            legend: {\n              ...opcionesBase.plugins.legend,\n              position: 'bottom'\n            },\n            tooltip: {\n              ...opcionesBase.plugins.tooltip,\n              callbacks: {\n                label: (context:any) => `${context.dataset.label}: $${formatoMoneda.format(normalizarNumero(context.parsed.y))}`\n              }\n            }\n          },\n          interaction: {\n            intersect: false,\n            mode: 'index'\n          },\n          scales: {\n            y: {\n              beginAtZero: true,\n              border: {display: false},\n              grid: {color: 'rgba(148, 163, 184, .16)', drawBorder: false},\n              position: 'left',\n              ticks: {\n                color: '#64748b',\n                font: {size: 12, weight: '600'},\n                callback: (value:any) => formatoMoneda.format(normalizarNumero(value))\n              },\n              title: {display: false}\n            },\n            y1: {\n              beginAtZero: true,\n              border: {display: false},\n              grid: {drawOnChartArea: false},\n              position: 'right',\n              ticks: {\n                color: '#64748b',\n                font: {size: 12, weight: '600'},\n                callback: (value:any) => formatoMoneda.format(normalizarNumero(value))\n              },\n              title: {display: false}\n            },\n            x: {\n              border: {display: false},\n              grid: {display: false},\n              ticks: {color: '#64748b', font: {size: 12, weight: '600'}}\n            }\n          }\n        }\n      });\n    }\n  }\n})();\r\n","type Align = 'left' | 'center' | 'right';\r\nconst canvas = document.createElement('canvas');\r\n\r\nclass EscPosBuilder {\r\n\r\n    protected content = '';\r\n    protected bytes: number[] = [];\r\n\r\n    protected write(...bytes: number[]) {\r\n        this.bytes.push(...bytes);\r\n    }\r\n\r\n   // Comando Reset: Limpia formatos previos\r\n    reset() {\r\n        // ESC @  version bytes\r\n        this.write(0x1B, 0x40);\r\n\r\n        this.content += '\\x1B\\x40';\r\n        this.setAlign('left');\r\n        // Bold OFF\r\n        this.boldOff();\r\n        // Tamaño normal\r\n        this.normalSize();\r\n    }\r\n\r\n    text(text: string = '') {\r\n        const encoder = new TextEncoder();\r\n        const encoded = encoder.encode(text);\r\n        this.bytes.push(...encoded);\r\n        this.write(0x0A); // salto línea\r\n\r\n        //version string\r\n        this.content += text + '\\n';\r\n    }\r\n\r\n    // Agregamos Tamaño de texto (Doble ancho y alto)\r\n    bigText(text: string, bold = false) {\r\n        if(bold)this.boldOn();\r\n        this.doubleSize();\r\n        this.text(text);\r\n        this.normalSize();\r\n        if(bold)this.boldOff();\r\n    }\r\n\r\n    line() {\r\n        this.text('-'.repeat(42));\r\n    }\r\n\r\n    // 1. Forzar que el centro sea una operación aislada y limpia\r\n    center(text: string) {\r\n        this.setAlign('center');         // Activar centro\r\n        this.text(text);                 // Escribir texto y saltar (imprime el buffer)\r\n        this.setAlign('left');           // Volver a izquierda INMEDIATAMENTE\r\n    }\r\n\r\n    setAlign(mode: 'left' | 'center' | 'right') {\r\n        const map = {\r\n            left: 0,\r\n            center: 1,\r\n            right: 2\r\n        };\r\n        // ESC a n  version bytes\r\n        this.write(0x1B, 0x61, map[mode]);\r\n        // ESC a n  version string\r\n        this.content += `\\x1B\\x61${String.fromCharCode(map[mode])}`;\r\n    }\r\n\r\n    boldOn(){\r\n        this.content += '\\x1B\\x45\\x01';  //version string\r\n        // ESC E 1\r\n        this.write(0x1B, 0x45, 0x01);  //version bytes\r\n    }\r\n\r\n    boldOff(){\r\n        this.content += '\\x1B\\x45\\x00'; //version string\r\n         // ESC E 0\r\n        this.write(0x1B, 0x45, 0x00);  //version bytes\r\n    }\r\n\r\n    bold(text: string) {\r\n        this.boldOn();\r\n        this.text(text);\r\n        this.boldOff();\r\n    }\r\n\r\n    normalSize(){\r\n        this.content += '\\x1D\\x21\\x00';  //version string\r\n        // GS ! 0\r\n        this.write(0x1D, 0x21, 0x00);  //version bytes\r\n    }\r\n\r\n    doubleHeight() {\r\n        this.content += '\\x1D\\x21\\x01';\r\n        this.write(0x1D, 0x21, 0x01);\r\n    }\r\n\r\n    doubleWidth() {\r\n        this.content += '\\x1D\\x21\\x10';\r\n        this.write(0x1D, 0x21, 0x10);\r\n    }\r\n\r\n    doubleSize() {\r\n        // GS ! 17\r\n        // doble ancho + doble alto\r\n        this.content += '\\x1D\\x21\\x11';\r\n        this.write(0x1D, 0x21, 0x11);\r\n    }\r\n\r\n    feed(lines: number = 3) {\r\n        this.content += '\\n'.repeat(lines); //version string\r\n        for(let i = 0; i < lines; i++)this.write(0x0A);  //version bytes\r\n    }\r\n\r\n    cut(feed:number = 5) {\r\n        this.feed(feed);\r\n        this.content += '\\x1D\\x56\\x00';  //version string\r\n        // GS V 0\r\n        this.write(0x1D, 0x56, 0x00);  //version bytes\r\n    }\r\n\r\n    row(left: string, right: string, width = 42) {\r\n        const spaces = width - left.length - right.length;\r\n        this.text(left+' '.repeat(Math.max(1, spaces))+right);\r\n    }\r\n\r\n    wrap(text: string, width = 42): string[] {\r\n        const words = text.split(' ');\r\n        const lines: string[] = [];\r\n        let current = '';\r\n        for(const word of words) {\r\n            if((current + word).length > width) {\r\n                lines.push(current.trim());\r\n                current = '';\r\n            }\r\n            current += word + ' ';\r\n        }\r\n        if(current.trim())lines.push(current.trim());\r\n        return lines;\r\n    }\r\n\r\n    column(text: string, width: number, align: 'left' | 'center' | 'right' = 'left'){\r\n        // evitar overflow\r\n        if(text.length > width) {\r\n            text = text.substring(0, width);\r\n        }\r\n        switch(align){\r\n            case 'left':\r\n                return text.padEnd(width, ' ');\r\n            case 'right':\r\n                return text.padStart(width, ' ');\r\n            case 'center':\r\n                const totalSpaces = width - text.length;\r\n                const left = Math.floor(totalSpaces / 2);\r\n                const right = totalSpaces - left;\r\n                return (' '.repeat(left)+text +' '.repeat(right));\r\n        }\r\n    }\r\n\r\n    row3(col1: string, col2: string, col3: string, align: Record<string, Align> = {col1: 'left', col2: 'right', col3: 'right'}, whidth:number[] = [8, 16, 18]){\r\n        const line = this.column(col1, whidth[0], align.col1) + this.column(col2, whidth[1], align.col2) + this.column(col3, whidth[2], align.col3);\r\n        this.text(line);\r\n    }\r\n\r\n\r\n    qr(data: string, size = 6, errorLevel: 'L' | 'M' | 'Q' | 'H' = 'M') { \r\n        const errorMap = { L: 48, M: 49, Q: 50, H: 51 }; \r\n        const store_len = data.length + 3; \r\n        const pL = store_len % 256; \r\n        const pH = Math.floor(store_len / 256); \r\n        //ENCODE DATA\r\n        const encoder = new TextEncoder(); \r\n        const encoded = encoder.encode(data); \r\n        /* ========================================= \r\n        TAMAÑO QR \r\n        ========================================= \r\n        */ \r\n        // GS ( k 3 0 49 67 n \r\n        // tamaño módulo \r\n        this.content +='\\x1D\\x28\\x6B\\x03\\x00\\x31\\x43'+String.fromCharCode(size); \r\n        this.write(0x1D, 0x28, 0x6B, 0x03, 0x00, 0x31, 0x43, size); //version bytes \r\n        /* ========================================= \r\n        NIVEL ERROR ========================================= \r\n        */ \r\n        // GS ( k 3 0 49 69 n \r\n        this.content +='\\x1D\\x28\\x6B\\x03\\x00\\x31\\x45'+String.fromCharCode(errorMap[errorLevel]); \r\n        this.write(0x1D, 0x28, 0x6B, 0x03, 0x00, 0x31, 0x45, errorMap[errorLevel]); //version bytes \r\n        /* ========================================= \r\n        ALMACENAR DATA \r\n        ========================================= \r\n        */ \r\n        this.content += '\\x1D\\x28\\x6B' + String.fromCharCode(pL) + String.fromCharCode(pH) + '\\x31\\x50\\x30' + data; \r\n        this.write(0x1D, 0x28, 0x6B, pL, pH, 0x31, 0x50, 0x30); //version bytes \r\n        this.bytes.push(...encoded); \r\n        /* ========================================= \r\n        IMPRIMIR QR \r\n        ========================================= \r\n        */ \r\n       this.content += '\\x1D\\x28\\x6B\\x03\\x00\\x31\\x51\\x30'; \r\n       this.write(0x1D, 0x28, 0x6B, 0x03, 0x00, 0x31, 0x51, 0x30); \r\n    }\r\n    \r\n\r\n    canvasToEscPos(canvas: HTMLCanvasElement) {\r\n        const ctx = canvas.getContext('2d')!;\r\n        const width = canvas.width;\r\n        const height = canvas.height;\r\n        const image = ctx.getImageData(0, 0, width, height);\r\n        const data = image.data;\r\n        const bytes = [];\r\n        bytes.push(0x1D, 0x76, 0x30, 0x00, width / 8, 0x00, height & 0xff, (height >> 8) & 0xff);\r\n        for (let y = 0; y < height; y++) {\r\n            for (let x = 0; x < width; x += 8) {\r\n                let byte = 0;\r\n                for (let bit = 0; bit < 8; bit++) {\r\n                    const px = x + bit;\r\n                    if (px >= width) continue;\r\n                    const i = (y * width + px) * 4;\r\n                    const r = data[i];\r\n                    const g = data[i + 1];\r\n                    const b = data[i + 2];\r\n                    const gray = r * 0.299 + g * 0.587 + b * 0.114;\r\n                    if (gray < 160) byte |= (1 << (7 - bit));\r\n                }\r\n                bytes.push(byte);\r\n            }\r\n        }\r\n        return bytes;\r\n    }\r\n\r\n\r\n    async qrRaster(text:string, correction:string = 'M'){\r\n        return new Promise<number[]>((resolve, reject)=>{\r\n             const self = this; // Guardamos la referencia\r\n            QRCode.toCanvas(\r\n                canvas,\r\n                text,\r\n                {\r\n                    width: 256,\r\n                    margin: 1,\r\n                    errorCorrectionLevel: correction\r\n                },\r\n                function (error:any) {\r\n                    if (error) {\r\n                        console.error(error);\r\n                        reject(error);\r\n                        return;\r\n                    }\r\n                    console.log('QR generado');\r\n                    const qrBytes = self.canvasToEscPos(canvas);\r\n                    resolve(qrBytes);\r\n                }\r\n            );\r\n        });\r\n    }\r\n\r\n\r\n    async image(src: string, options: { width?: number; align?: 'left' | 'center' | 'right'; } = {}){\r\n        const {\r\n            width = 256,\r\n            align = 'center'\r\n        } = options;\r\n\r\n        return new Promise<void>((resolve, reject) => {\r\n            const img = new Image();\r\n            img.crossOrigin = 'anonymous';\r\n            img.onload = () => {\r\n                // calcular alto proporcional\r\n                const ratio = img.height / img.width;\r\n                const height = Math.floor(width * ratio);\r\n                // canvas temporal\r\n                const canvas = document.createElement('canvas');\r\n                canvas.width = Math.ceil(width / 8) * 8;\r\n                canvas.height = height;\r\n                const ctx = canvas.getContext('2d');\r\n                if(!ctx){\r\n                    reject('No canvas context');\r\n                    return;\r\n                }\r\n                // fondo blanco\r\n                ctx.fillStyle = '#FFFFFF';\r\n                ctx.fillRect(0, 0, canvas.width, canvas.height);\r\n                // mejora contraste\r\n                ctx.filter = 'grayscale(100%) contrast(180%)';\r\n                // dibujar imagen\r\n                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);\r\n                // alineación\r\n                this.setAlign(align);\r\n                // convertir a ESC/POS\r\n                const imgBytes = this.canvasToEscPos(canvas);\r\n                // agregar bytes\r\n                this.bytes.push(...imgBytes);\r\n                this.feed(1);\r\n                this.setAlign('left');\r\n                resolve();\r\n            };\r\n            img.onerror = reject;\r\n            img.src = src;\r\n        });\r\n    }\r\n\r\n\r\n    build(buildBytes:boolean): string | Uint8Array  {\r\n        if(buildBytes){\r\n            return new Uint8Array(this.bytes);\r\n        }else{\r\n            return this.content;\r\n        }\r\n    }\r\n}\r\n\r\n\r\nclass InvoiceTicketBuilder extends EscPosBuilder {\r\n\r\n    private invoice: DataInvoice;\r\n    constructor(invoice: DataInvoice) {\r\n        super();\r\n        this.reset();\r\n        this.invoice = invoice;\r\n    }\r\n\r\n    async generate(buildBytes:boolean):Promise<string | Uint8Array> {\r\n        await this.header();\r\n        if(this.invoice.tipoFactura === '1')this.customer(); //solo factura electronica\r\n        this.datosFactura();\r\n        this.cliente();\r\n        this.items();\r\n        this.totals();\r\n        this.payments();\r\n        if(this.invoice.tipoFactura === '1')this.infoResolution();  //solo factura electronica\r\n        await this.footer();\r\n        this.cut();\r\n        return this.build(buildBytes);\r\n    }\r\n\r\n    private async header() {\r\n        await this.image(`/build/img/${this.invoice.logo}`, {\r\n            width: 256,\r\n            align: 'center'\r\n        });\r\n        this.boldOn();\r\n        this.center(this.invoice.negocio.toUpperCase());\r\n        this.boldOff();\r\n        this.feed(1);\r\n        this.center(`NIT: ${this.invoice.nit.trim()}`);\r\n        this.center(`SEDE: ${this.invoice.sucursal.trim().toUpperCase()}`);\r\n        this.center(this.invoice.direccion.trim());\r\n        this.center(`TEL: ${this.invoice.telefono.trim()}`);\r\n        this.feed(1);\r\n    }\r\n\r\n    private customer() { //cliente factura electronica\r\n        this.center(`Cliente: ${this.invoice.consumidorFinal.name}`);\r\n        this.center(`NIT: ${this.invoice.consumidorFinal.identification_number}`);\r\n    }\r\n\r\n    private datosFactura(){\r\n        this.boldOn();\r\n        this.center(`${this.invoice.textFactura}`);\r\n        this.boldOff();\r\n        this.bold(`Factura: ${this.invoice.prefijo.trim()}${this.invoice.consecutivo.trim()}`);\r\n        this.text(`Fecha pago: ${this.invoice.fechaPago.trim()}`);\r\n        this.text(`Forma de pago: ${this.invoice.tipoventa.trim()}`);\r\n        this.text(`Caja: ${this.invoice.caja.trim()}`);\r\n        this.text(`Vendedor: ${this.invoice.vendedor.trim()}`);\r\n        this.line();\r\n    }\r\n\r\n    private cliente(){\r\n        this.feed(1);\r\n        this.center(`Cliente: ${this.invoice.cliente.nombre.trim()} ${this.invoice.cliente.apellido.trim()}`);\r\n        this.center(`Documento: ${this.invoice.cliente.identificacion?.trim()??''}`);\r\n        this.center(`Telefono: ${this.invoice.cliente.telefono.trim()}`);\r\n        this.center(`Direccion: ${this.invoice.cliente.data1?.trim()||' - '}`);\r\n        this.feed(1);\r\n    }\r\n\r\n    private items() {\r\n        this.line();\r\n        this.feed(1);\r\n        this.boldOn();\r\n        this.row3('CANT', 'UND', 'TOTAL', {col1:'left', col2:'right', col3:'right'}, [8, 16, 18]);\r\n        this.boldOff();\r\n        for(const item of this.invoice.items) {\r\n            for(const line of this.wrap(item.nombreproducto.trim()))this.center(line);\r\n            //this.row(`${item.cantidad}  x  $${item.valorunidad.toLocaleString()}`, '$'+item.total.toLocaleString());\r\n            this.row3(item.stock?.toString()||item.cantidad.toString(), '$'+item.valorunidad.toLocaleString(), '$'+item.total.toLocaleString(), {col1:'left', col2:'right', col3:'right'}, [8, 16, 18]);\r\n        }\r\n    }\r\n\r\n    private totals() {\r\n        this.line();\r\n        this.feed(1);\r\n        this.setAlign('right');\r\n        this.text(`SUBTOTAL: $${Number(this.invoice.subtotal.trim()).toLocaleString()}`);\r\n        this.text(`IMPUESTO: $${Number(this.invoice.valorimpuestototal.trim()).toLocaleString()}`);\r\n        this.text(`DESCUENTO: $${Number(this.invoice.descuento.trim()).toLocaleString()}`);\r\n        this.bigText(`TOTAL: $${Number(this.invoice.total.trim()).toLocaleString()}`, true);\r\n    }\r\n\r\n    private payments() {\r\n        this.feed(2);\r\n        this.doubleHeight();\r\n        for(const pago of this.invoice.mediospago) {\r\n            //this.text(`${pago.mediopago}: $${pago.valor?.toLocaleString()}`);\r\n            this.row3(' ', pago.mediopago+':', ` $${pago.valor?.toLocaleString()}`, {col1:'right', col2:'right', col3:'left'}, [10, 17, 15]);\r\n        }\r\n        this.normalSize();\r\n        this.feed(1);\r\n        this.setAlign('left');\r\n        this.text(`Observacion: ${this.invoice.observacion}`);\r\n        this.line();\r\n        this.feed(2);\r\n    }\r\n\r\n    private infoResolution(){\r\n        this.setAlign('left');\r\n        this.text(`Resolucion: ${this.invoice.resolucion.resolucion}, Rango desde: ${this.invoice.resolucion.rangoinicial} hasta ${this.invoice.resolucion.rangofinal}`);\r\n        this.text(`CUFE: ${this.invoice.cufe || 'fe9c733f32770f5fcc4ef954f9ef663c54c752e6c07bdc144bb00627faadf9f648818da3e96ef8293547140fb1970d22'}`);\r\n        this.feed(2);\r\n    }\r\n\r\n    private async footer() {\r\n        this.setAlign('center');\r\n        //this.qr(this.invoice.link || 'www.j2softwarepos.com/', 8, 'M');\r\n        const qrBytes = await this.qrRaster(this.invoice.link || this.invoice.www, 'M');\r\n        this.bytes.push(...qrBytes);\r\n        this.feed(2);\r\n        this.boldOn();\r\n        this.center('GRACIAS POR SU COMPRA');\r\n        this.boldOff();\r\n        this.feed(2);\r\n        this.center(`© ${new Date().getFullYear()} J2 Software POS Multisucursal`);\r\n        this.center('www.j2softwarepos.com');\r\n    }\r\n    //copy /b ticket.bin \"\\\\localhost\\\\CAJA\"\r\n}\r\n\r\n\r\n\r\nclass InvoiceTicketBuilder2 extends EscPosBuilder {\r\n\r\n    private invoice: DataInvoice;\r\n    constructor(invoice: DataInvoice) {\r\n        super();\r\n        this.reset();\r\n        this.invoice = invoice;\r\n    }\r\n\r\n    async generate(buildBytes:boolean):Promise<string | Uint8Array> {\r\n        await this.header();\r\n        if(this.invoice.tipoFactura === '1')this.customer(); //solo factura electronica\r\n        this.datosFactura();\r\n        this.cliente();\r\n        this.items();\r\n        this.totals();\r\n        this.payments();\r\n        if(this.invoice.tipoFactura === '1')this.infoResolution();  //solo factura electronica\r\n        await this.footer();\r\n        this.cut(1);\r\n        return this.build(buildBytes);\r\n    }\r\n\r\n    private async header() {\r\n        await this.image(`/build/img/${this.invoice.logo}`, {\r\n            width: 220,\r\n            align: 'center'\r\n        });\r\n        this.boldOn();\r\n        this.center(this.invoice.negocio.toUpperCase());\r\n        this.boldOff();\r\n        this.feed(1);\r\n        this.center(`NIT: ${this.invoice.nit.trim()}`);\r\n        this.center(`SEDE: ${this.invoice.sucursal.trim().toUpperCase()}`);\r\n        this.center(this.invoice.direccion.trim());\r\n        this.center(`TEL: ${this.invoice.telefono.trim()}`);\r\n        //this.feed(1);\r\n    }\r\n\r\n    private customer() { //cliente factura electronica\r\n        this.center(`Cliente: ${this.invoice.consumidorFinal.name}`);\r\n        this.center(`NIT: ${this.invoice.consumidorFinal.identification_number}`);\r\n    }\r\n\r\n    private datosFactura(){\r\n        this.boldOn();\r\n        this.center(`${this.invoice.textFactura}`);\r\n        this.boldOff();\r\n        this.bold(`Factura: ${this.invoice.prefijo.trim()}${this.invoice.consecutivo.trim()}`);\r\n        this.text(`Fecha pago: ${this.invoice.fechaPago.trim()}`);\r\n        this.text(`Forma de pago: ${this.invoice.tipoventa.trim()}`);\r\n        //this.text(`Caja: ${this.invoice.caja.trim()}`);\r\n        this.text(`Vendedor: ${this.invoice.vendedor.trim()}`);\r\n        this.line();\r\n    }\r\n\r\n    private cliente(){\r\n        //this.feed(1);\r\n        this.center(`Cliente: ${this.invoice.cliente.nombre.trim()} ${this.invoice.cliente.apellido.trim()}`);\r\n        this.center(`Documento: ${this.invoice.cliente.identificacion?.trim()??''}`);\r\n        this.center(`Telefono: ${this.invoice.cliente.telefono.trim()}`);\r\n        this.center(`Direccion: ${this.invoice.cliente.data1?.trim()||' - '}`);\r\n        //this.feed(1);\r\n    }\r\n\r\n    private items() {\r\n        this.line();\r\n        //this.feed(1);\r\n        this.boldOn();\r\n        this.row3('CANT', 'UND', 'TOTAL', {col1:'left', col2:'right', col3:'right'}, [8, 16, 18]);\r\n        this.boldOff();\r\n        for(const item of this.invoice.items) {\r\n            for(const line of this.wrap(item.nombreproducto.trim()))this.center(line);\r\n            //this.row(`${item.cantidad}  x  $${item.valorunidad.toLocaleString()}`, '$'+item.total.toLocaleString());\r\n            this.row3(item.stock?.toString()||item.cantidad.toString(), '$'+item.valorunidad.toLocaleString(), '$'+item.total.toLocaleString(), {col1:'left', col2:'right', col3:'right'}, [8, 16, 18]);\r\n        }\r\n    }\r\n\r\n    private totals() {\r\n        this.line();\r\n        this.feed(1);\r\n        this.setAlign('right');\r\n        this.text(`SUBTOTAL: $${Number(this.invoice.subtotal.trim()).toLocaleString()}`);\r\n        this.text(`IMPUESTO: $${Number(this.invoice.valorimpuestototal.trim()).toLocaleString()}`);\r\n        this.text(`DESCUENTO: $${Number(this.invoice.descuento.trim()).toLocaleString()}`);\r\n        this.bigText(`TOTAL: $${Number(this.invoice.total.trim()).toLocaleString()}`, true);\r\n    }\r\n\r\n    private payments() {\r\n        this.feed(1);\r\n        //this.doubleHeight();\r\n        this.normalSize();\r\n        for(const pago of this.invoice.mediospago) {\r\n            //this.text(`${pago.mediopago}: $${pago.valor?.toLocaleString()}`);\r\n            this.row3(' ', pago.mediopago+':', ` $${pago.valor?.toLocaleString()}`, {col1:'right', col2:'right', col3:'left'}, [10, 17, 15]);\r\n        }\r\n        //this.normalSize();\r\n        this.feed(1);\r\n        this.setAlign('left');\r\n        this.text(`Observacion: ${this.invoice.observacion}`);\r\n        this.line();\r\n        //this.feed(2);\r\n    }\r\n\r\n    private infoResolution(){\r\n        this.setAlign('left');\r\n        this.text(`Resolucion: ${this.invoice.resolucion.resolucion}, Rango desde: ${this.invoice.resolucion.rangoinicial} hasta ${this.invoice.resolucion.rangofinal}`);\r\n        this.text(`CUFE: ${this.invoice.cufe || 'fe9c733f32770f5fcc4ef954f9ef663c54c752e6c07bdc144bb00627faadf9f648818da3e96ef8293547140fb1970d22'}`);\r\n        this.feed(2);\r\n    }\r\n\r\n    private async footer() {\r\n        this.setAlign('center');\r\n        //this.qr(this.invoice.link || 'www.j2softwarepos.com/', 8, 'M');\r\n        const qrBytes = await this.qrRaster(this.invoice.link || this.invoice.www, 'M');\r\n        this.bytes.push(...qrBytes);\r\n        this.feed(1);\r\n        this.boldOn();\r\n        this.center('GRACIAS POR SU COMPRA');\r\n        this.boldOff();\r\n        this.feed(1);\r\n        this.center(`© ${new Date().getFullYear()} J2 Software POS Multisucursal`);\r\n        this.center('www.j2softwarepos.com');\r\n    }\r\n    //copy /b ticket.bin \"\\\\localhost\\\\CAJA\"\r\n}\r\n\r\n\r\n\r\n","\r\n\r\n// const mobilemenu1 = document.querySelector('#mobile-menu1')as HTMLButtonElement;\r\n// const miDialogomenumovil = document.querySelector('#miDialogomenumovil') as any;\r\n\r\n// mobilemenu1.addEventListener('click', ()=>{\r\n//     miDialogomenumovil.showModal();\r\n//     document.addEventListener('click', cerrarDialogoExterno);\r\n// });\r\n\r\n\r\n// function cerrarDialogoExterno(event:Event){\r\n//  const f = event.target;\r\n//  if(f === miDialogomenumovil){\r\n//     miDialogomenumovil.close();\r\n//  }\r\n// }\r\nconst mobilemenu1 = document.querySelector('#mobile-menu1') as HTMLButtonElement;\r\nconst miDialogomenumovil = document.querySelector('#miDialogomenumovil') as HTMLDialogElement;\r\n\r\n// aseguramos que al cargar la página el modal esté cerrado y oculto\r\nmiDialogomenumovil.close();\r\nmiDialogomenumovil.setAttribute('hidden', 'true');\r\n\r\nmobilemenu1.addEventListener('click', () => {\r\n  miDialogomenumovil.showModal();\r\n  miDialogomenumovil.removeAttribute('hidden');\r\n  document.addEventListener('click', cerrarDialogoExterno);\r\n});\r\n\r\nfunction cerrarDialogoExterno(event: Event) {\r\n  const f = event.target;\r\n  if (f === miDialogomenumovil) {\r\n    miDialogomenumovil.close();\r\n    miDialogomenumovil.setAttribute('hidden', 'true');\r\n    document.removeEventListener('click', cerrarDialogoExterno);\r\n  }\r\n}\r\n\r\n\r\n","(()=>{\r\n    if(document.querySelector('.perfil')){\r\n      const btnCambiarEmail = document.querySelector('#btnCambiarEmail');\r\n      const miDialogoUpEmail = document.querySelector('#miDialogoUpEmail') as any;\r\n      //const btnCerrarUpDireccion = document.querySelector('#btnCerrarUpDireccion') as HTMLButtonElement;\r\n      \r\n  \r\n      btnCambiarEmail?.addEventListener('click', (e):void=>{\r\n        miDialogoUpEmail.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      }); \r\n\r\n      //btnCerrarUpDireccion.addEventListener('click', ()=>miDialogoUpDireccion.close());\r\n\r\n  \r\n      function cerrarDialogoExterno(event:Event) {\r\n        if (event.target === miDialogoUpEmail || (event.target as HTMLInputElement).value === 'salir') {\r\n          miDialogoUpEmail.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n      }\r\n    }\r\n  \r\n  })();","(()=>{\r\n    if(document.querySelector('.ajustarcostos')){\r\n        let tablaAjustarCostos:HTMLElement;\r\n\r\n        type conversionunidadesapi = {\r\n            id:string,\r\n            idproducto: string,\r\n            idsubproducto: string,\r\n            idunidadmedidabase: string,\r\n            idunidadmedidadestino: string,\r\n            nombreunidadbase: string,\r\n            nombreunidaddestino: string,\r\n            factorconversion: string,\r\n            //idservicios:{idempleado:string, idservicio:string}[]\r\n          };\r\n\r\n        let allConversionUnidades:conversionunidadesapi[] = [];\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/allConversionesUnidades\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas las conversiones de unidades\r\n                const respuesta = await fetch(url); \r\n                allConversionUnidades = await respuesta.json();\r\n                console.log(allConversionUnidades);\r\n                pirntUnidades();\r\n                tablaAjustarCostos = ($('#tablaAjustarCostos') as any).DataTable(configdatatablesajustarcostos);\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n        //tablaAjustarCostos = ($('#tablaAjustarCostos') as any).DataTable(configdatatables);\r\n        //indiceFila = (tablaAjustarCostos as any).row(1).data();\r\n\r\n        function pirntUnidades():void{\r\n            allConversionUnidades.forEach(subUnd =>{\r\n                let select = document.querySelector(`tr[data-idsubproducto=\"${subUnd.idsubproducto}\"]`)?.children[5].children[0];\r\n                if(select == undefined)select = document.querySelector(`tr[data-idproducto=\"${subUnd.idproducto}\"]`)?.children[5].children[0];\r\n                const option = document.createElement('option');\r\n                option.textContent = subUnd.nombreunidaddestino;\r\n                option.dataset.factor = subUnd.factorconversion;\r\n                select?.appendChild(option);\r\n            });\r\n        }\r\n \r\n\r\n        /*const fila = (tablaAjustarCostos as any).row((idx:number, data:any, node:HTMLElement)=>{\r\n            return node.dataset.idproducto === subUnd.idsubproducto;\r\n        }).data();*/\r\n        //console.log(fila[4]);\r\n      /*fila[4] = `<select class=\"formulario__select\" required>\r\n                        <option value=\"\" disabled selected>-Seleccionar-</option>\r\n                        <option value=\"\"> Unidad </option>\r\n                    </select>`;\r\n        (tablaAjustarCostos as any).row(2).data(fila).draw();*/\r\n\r\n        //tablaAjustarCostos = ($('#tablaAjustarCostos') as any).DataTable(configdatatables);\r\n        \r\n        document.querySelector('#tablaAjustarCostos')?.addEventListener('focusout', (e:Event)=>{\r\n            var input = e.target as HTMLInputElement;\r\n            let tipoelemento:string = '', idelemento:string = '';\r\n            if(input.classList.contains('inputAjustarCosto')){\r\n                \r\n                var tr = input.closest('tr');\r\n                const selectUnidad = tr?.querySelector('.formulario__select') as HTMLSelectElement;\r\n                const factor:number = Number(selectUnidad.options[selectUnidad.selectedIndex].dataset.factor);\r\n                \r\n                var trx = input.closest('.fila') as HTMLElement;  //fila padre\r\n                if(!trx)trx = tr?.previousSibling as HTMLElement;\r\n\r\n                if(trx.classList.contains('producto')){\r\n                    idelemento = trx.dataset.idproducto!;\r\n                    tipoelemento = '0'; //si es producto\r\n                }\r\n                else{\r\n                    idelemento = trx.dataset.idsubproducto!;\r\n                    tipoelemento = '1';  // si es un subproducto\r\n                }\r\n\r\n                ////////////// enviar datos por api para actualizar costos /////////////\r\n                if(Number(input.value) != Number(trx.dataset?.costo||0))\r\n                actualizarcostos(tipoelemento, idelemento, factor, input);\r\n            }\r\n        });\r\n\r\n\r\n        function actualizarcostos(tipoelemento:string, idelemento:string, factor:number, input:HTMLInputElement){\r\n            if(input.value=='')input.value = '0';\r\n            const costo = Number(input.value)/factor;\r\n            console.log(costo);\r\n            (async ()=>{ \r\n                const datos = new FormData();\r\n                datos.append('tipoelemento', tipoelemento); //1 = subproducto\r\n                datos.append('idelemento', idelemento);\r\n                datos.append('precio_compra', costo+'');\r\n                try {\r\n                    const url = \"/admin/api/actualizarcostos\";  //asocia el producto con el sub producto en la tabla productos_sub\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                        input.style.color = \"#02db02\";\r\n                        input.style.fontWeight = \"500\";\r\n                    }else{\r\n                      msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n        }\r\n    }\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.cambioPrecios')){\r\n        let tablaAjustarPrecios:HTMLElement;\r\n\r\n        type conversionunidadesapi = {\r\n            id:string,\r\n            idproducto: string,\r\n            idsubproducto: string,\r\n            idunidadmedidabase: string,\r\n            idunidadmedidadestino: string,\r\n            nombreunidadbase: string,\r\n            nombreunidaddestino: string,\r\n            factorconversion: string,\r\n            //idservicios:{idempleado:string, idservicio:string}[]\r\n          };\r\n\r\n        let allConversionUnidades:conversionunidadesapi[] = [];\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/allConversionesUnidades\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas las conversiones de unidades\r\n                const respuesta = await fetch(url); \r\n                allConversionUnidades = await respuesta.json();\r\n                console.log(allConversionUnidades);\r\n                pirntUnidades();\r\n                tablaAjustarPrecios = ($('#tablaAjustarPrecios') as any).DataTable(configdatatablesajustarcostos);\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n        //tablaAjustarPrecios = ($('#tablaAjustarPrecios') as any).DataTable(configdatatables);\r\n        //indiceFila = (tablaAjustarPrecios as any).row(1).data();\r\n\r\n        function pirntUnidades():void{\r\n            allConversionUnidades.forEach(subUnd =>{\r\n                let select = document.querySelector(`tr[data-idproducto=\"${subUnd.idproducto}\"]`)?.children[5].children[0];\r\n                const option = document.createElement('option');\r\n                option.textContent = subUnd.nombreunidaddestino;\r\n                option.dataset.factor = subUnd.factorconversion;\r\n                select?.appendChild(option);\r\n            });\r\n        }\r\n \r\n\r\n        /*const fila = (tablaAjustarPrecios as any).row((idx:number, data:any, node:HTMLElement)=>{\r\n            return node.dataset.idproducto === subUnd.idsubproducto;\r\n        }).data();*/\r\n        //console.log(fila[4]);\r\n      /*fila[4] = `<select class=\"formulario__select\" required>\r\n                        <option value=\"\" disabled selected>-Seleccionar-</option>\r\n                        <option value=\"\"> Unidad </option>\r\n                    </select>`;\r\n        (tablaAjustarPrecios as any).row(2).data(fila).draw();*/\r\n\r\n        //tablaAjustarPrecios = ($('#tablaAjustarPrecios') as any).DataTable(configdatatables);\r\n        \r\n        document.querySelector('#tablaAjustarPrecios')?.addEventListener('focusout', (e:Event)=>{\r\n            var input = e.target as HTMLInputElement;\r\n            let idelemento:string = '';\r\n            if(input.classList.contains('inputAjustarPrecio')){\r\n                \r\n                var tr = input.closest('tr');\r\n                const selectUnidad = tr?.querySelector('.formulario__select') as HTMLSelectElement;\r\n                const factor:number = Number(selectUnidad.options[selectUnidad.selectedIndex].dataset.factor);\r\n                \r\n                var trx = input.closest('.fila') as HTMLElement;  //fila padre\r\n                if(!trx)trx = tr?.previousSibling as HTMLElement;\r\n\r\n                if(trx.classList.contains('producto')){\r\n                    idelemento = trx.dataset.idproducto!;\r\n                }\r\n\r\n                ////////////// enviar datos por api para actualizar precios /////////////\r\n                if(Number(input.value) != Number(trx.dataset?.precio||0))\r\n                actualizarPreciosVenta(idelemento, factor, input);\r\n            }\r\n        });\r\n\r\n\r\n        function actualizarPreciosVenta(idelemento:string, factor:number, input:HTMLInputElement){\r\n            if(input.value=='')input.value = '0';\r\n            const precio = Number(input.value)/factor;\r\n            (async ()=>{ \r\n                const datos = new FormData();\r\n                datos.append('idelemento', idelemento);\r\n                datos.append('precio_venta', precio+'');\r\n                try {\r\n                    const url = \"/admin/api/actualizarPreciosVenta\";  //asocia el producto con el sub producto en la tabla productos_sub\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                        input.style.color = \"#02db02\";\r\n                        input.style.fontWeight = \"500\";\r\n                    }else{\r\n                      msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n        }\r\n    }\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.almacen')){\r\n        const btntrasladoinvnetario = document.querySelector('#btntrasladoinvnetario') as HTMLInputElement;\r\n        const btnMasOpciones = document.querySelector('#btnMasOpciones') as HTMLInputElement;\r\n        const btnviewProductsBajoStock = document.querySelector('#btnviewProductsBajoStock') as HTMLButtonElement;\r\n        const miDialogoTrasladoInvnetario = document.querySelector('#miDialogoTrasladoInvnetario') as any;\r\n        const miDialogoMasOpciones = document.querySelector('#miDialogoMasOpciones') as any;\r\n        const reinciarinv = document.querySelector('#reinciarinv') as HTMLButtonElement;\r\n        const miDialogoBajoStock = document.querySelector('#miDialogoBajoStock') as HTMLDialogElement;\r\n        const miDialogoStock = document.querySelector('#miDialogoStock') as any;\r\n        const modalStock = document.querySelector('#modalStock') as HTMLElement;\r\n        const selectStockRapidoUndmedida = document.querySelector('#selectStockRapidoUndmedida') as HTMLSelectElement;\r\n        let amount = document.querySelector('#cantidadStockRapido') as HTMLInputElement; //input cantidad de modal de stock rapido\r\n        let stockAux = document.querySelector('#stockAux') as HTMLInputElement; //input cantidad aux de modal de stock rapido\r\n\r\n        const miDialogoIngresarProduccion = document.querySelector('#miDialogoIngresarProduccion') as any;\r\n        const selectitemAproducir = document.querySelector('#itemAproducir') as HTMLSelectElement;\r\n        const btnsproduccion = document.querySelectorAll<HTMLButtonElement>('.btnproduccion');  //btns ingresar descontar ajustar produccion\r\n        const selectIngresarProduccionUnidadmedida = document.querySelector('#selectIngresarProduccionUnidadmedida') as HTMLSelectElement;\r\n        const amountProduccion = document.querySelector('#stockIngresarProduccion') as HTMLInputElement;  //input cantidad cuando se ingresa orden de produccion\r\n        let cantidadactual = 0, indiceFila=0, endponit:string='', factorC = 0, idUnidMedida:string, tipoelemento:string = '', idelemento:string = '', tablaStockRapido:HTMLElement, tablaInventarioSedes:HTMLTableElement;\r\n    \r\n        const sedes = document.querySelector('#sedes');\r\n        const tablaBajoStock = document.querySelector('#tablaBajoStock tbody') as HTMLBodyElement;\r\n\r\n        interface datosProducto { stock?: string, sku?:string, precio_compra: string, precio_venta: string }\r\n\r\n        type conversionunidadesapi = {\r\n            id:string,\r\n            idproducto:string,\r\n            idsubproducto: string,\r\n            idunidadmedidabase: string,\r\n            idunidadmedidadestino: string,\r\n            nombreunidadbase: string,\r\n            nombreunidaddestino: string,\r\n            factorconversion: string,\r\n          };\r\n\r\n          type productosXsucursal = {\r\n            productoid:string,\r\n            subproductoid: string,\r\n            nombreproducto:string,\r\n            sucursalid: string,\r\n            sucursal: string,\r\n            stock: string,\r\n          };\r\n\r\n        let allproductsXsucursal:productosXsucursal[]=[], allConversionUnidades:conversionunidadesapi[] = [];\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/allConversionesUnidades\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas las conversiones de unidades\r\n                const respuesta = await fetch(url); \r\n                allConversionUnidades = await respuesta.json();\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n        //apertura de la ventana modal para las opcionesde traslado de inventario\r\n        btntrasladoinvnetario.addEventListener('click', ()=>{\r\n            miDialogoTrasladoInvnetario.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        });\r\n\r\n        //apertura de la ventana modal para las opcionesde traslado de inventario\r\n        btnMasOpciones.addEventListener('click', ()=>{\r\n            miDialogoMasOpciones.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        });\r\n\r\n\r\n        btnviewProductsBajoStock.addEventListener('click', ()=>{\r\n            getItemsBajoStock();\r\n            miDialogoBajoStock.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno); \r\n        });\r\n\r\n        async function getItemsBajoStock(){\r\n            try {\r\n                const url = \"/admin/api/getItemsBajoStock\";\r\n                const respuesta = await fetch(url); \r\n                const resultado:{productoid:string, nombre:string, idunidadmedida:string, sku:string, stock:string, stockminimo:string, tipoproducto:string, tipoproduccion:string, unidadmedida:string, visible:string}[] = await respuesta.json();\r\n                Object.assign(configdatatablesstockbajo, {\r\n                    data: resultado,\r\n                    columns: [\r\n                        {title: 'ID', data: 'productoid'},\r\n                        {title: 'NOMBRE', data: 'nombre'},\r\n                        {\r\n                            title: 'TIPO', \r\n                            data: null,\r\n                            orderable: false,\r\n                            searchable: false,\r\n                            render: (data: any, type: any, row: any) => {return row.tipoproducto== 1?'Compuesto':'Simple'}\r\n                        },\r\n                        {title: 'STOCK ACTUAL', data: 'stock'},\r\n                        {title: 'STOCK MIN', data: 'stockminimo'},\r\n                    ],\r\n                });\r\n                ($('#tablaBajoStock') as any).DataTable(configdatatablesstockbajo); \r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        }\r\n\r\n        reinciarinv.addEventListener('click', (e)=>{\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea reiniciar el inventario a cero?',\r\n                text: \"Todos los productos e insumos del inventario se reiniciaran a cero.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n                    (async ()=>{\r\n                        try {\r\n                            const url = \"/admin/api/reiniciarinv\"; //llamado a la API REST y se trae las direcciones segun cliente elegido\r\n                            const respuesta = await fetch(url); \r\n                            const resultado = await respuesta.json();\r\n                            (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n                            if(resultado.exito !== undefined){ \r\n                                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                                setTimeout(() => {\r\n                                window.location.reload();  \r\n                                }, 1270);\r\n                            }else{\r\n                                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();\r\n                }\r\n            });\r\n        });\r\n\r\n\r\n        sedes?.addEventListener('change', (e:Event)=>{\r\n            if((e.target as HTMLInputElement).checked){\r\n                (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n                (async ()=>{\r\n                    try {\r\n                        const url = \"/admin/api/getStockproductosXsucursal\"; //llamado a la API REST en el controlador almacencontrolador para treaer todos los productos con su respectiva sucursal y stock\r\n                        const respuesta = await fetch(url); \r\n                        allproductsXsucursal = await respuesta.json();\r\n                        printstockXsucursal();\r\n                        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n                    } catch (error) {\r\n                        console.log(error);\r\n                    }\r\n                })();\r\n            }\r\n        });\r\n\r\n\r\n        /////////////////////////////////////  SOTCK RAPIDO ////////////////////////////////////////\r\n        /*document.querySelector('#stockproducto')?.addEventListener('click', (e)=>{\r\n            if((e.target as HTMLInputElement).checked){\r\n                 tablaStockRapido = ($('#tablaStockRapido') as any).DataTable(configdatatables);\r\n            }\r\n        })*/\r\n        tablaStockRapido = ($('#tablaStockRapido') as any).DataTable(configdatatablesstockrapido);\r\n\r\n        document.querySelector('#tablaStockRapido')?.addEventListener(\"click\", (e:Event)=>{ //evento click sobre toda la tabla\r\n            let options:string = '';\r\n            const target = e.target as HTMLElement;\r\n\r\n           if(target.closest('.btnsproducto')){\r\n                idelemento = target.closest('.btnsproducto')!.id;\r\n                tipoelemento = '0'; //si es producto\r\n                cantidadactual = Number((target.closest('.btnsproducto') as HTMLElement).dataset.stock);\r\n                document.querySelector('#nombreItemstockrapido')!.textContent = (target.closest('.btnsproducto') as HTMLElement).dataset.nombre!;\r\n            }\r\n            if(target.closest('.btnssubproducto')){\r\n                idelemento = target.closest('.btnssubproducto')!.id;\r\n                tipoelemento = '1'; //si es un subproducto\r\n                cantidadactual = Number((target.closest('.btnssubproducto') as HTMLElement).dataset.stock);\r\n                document.querySelector('#nombreItemstockrapido')!.textContent = (target.closest('.btnssubproducto') as HTMLElement).dataset.nombre!;\r\n            }\r\n\r\n            while(selectStockRapidoUndmedida.firstChild)selectStockRapidoUndmedida.removeChild(selectStockRapidoUndmedida.firstChild);\r\n            if(tipoelemento == '0'){\r\n                const productounidades = allConversionUnidades.filter(x => x.idproducto == idelemento); \r\n                productounidades.forEach(u=>{\r\n                    options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idproducto}\" >${u.nombreunidaddestino}</option>`;\r\n                    idUnidMedida = u.idunidadmedidabase;\r\n                });\r\n                selectStockRapidoUndmedida.insertAdjacentHTML('afterbegin', options);\r\n            }\r\n            if(tipoelemento == '1'){\r\n                const subproductounidades = allConversionUnidades.filter(x => x.idsubproducto == idelemento); \r\n                subproductounidades.forEach(u=>{\r\n                    options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idsubproducto}\" >${u.nombreunidaddestino}</option>`;\r\n                    idUnidMedida = u.idunidadmedidabase;\r\n                });\r\n                selectStockRapidoUndmedida.insertAdjacentHTML('afterbegin', options);\r\n            }\r\n            \r\n            if((e.target as HTMLElement)?.classList.contains(\"descontarStock\")||(e.target as HTMLElement).parentElement?.classList.contains(\"descontarStock\"))descontarStock(e);\r\n            if((e.target as HTMLElement)?.classList.contains(\"aumentarStock\")||(e.target as HTMLElement).parentElement?.classList.contains(\"aumentarStock\"))aumentarStock(e);\r\n            if((e.target as HTMLElement)?.classList.contains(\"ajustarStock\")||(e.target as HTMLElement).parentElement?.classList.contains(\"ajustarStock\"))ajustarStock(e);\r\n        });\r\n\r\n        //EDITAR STOCK\r\n        function descontarStock(e:Event){\r\n            modalStock.textContent = \"Descontar cantidad a inventario\"\r\n            endponit = \"descontarstock\";\r\n            indiceFila = (tablaStockRapido as any).row((e.target as HTMLElement).closest('tr')).index();\r\n            miDialogoStock.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n\r\n        function aumentarStock(e:Event){\r\n            modalStock.textContent = \"Ingresar cantidad a inventario\"\r\n            endponit = \"aumentarstock\";\r\n            indiceFila = (tablaStockRapido as any).row((e.target as HTMLElement).closest('tr')).index();\r\n            miDialogoStock.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n\r\n        function ajustarStock(e:Event){\r\n            modalStock.textContent = \"Ajustar cantidad a inventario\"\r\n            endponit = \"ajustarstock\";\r\n            indiceFila = (tablaStockRapido as any).row((e.target as HTMLElement).closest('tr')).index();\r\n            miDialogoStock.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n\r\n\r\n        document.querySelector('#formStock')?.addEventListener('submit', (e)=>{\r\n            e.preventDefault();\r\n            factorC = Number(selectStockRapidoUndmedida.options[selectStockRapidoUndmedida.selectedIndex].dataset.factor);\r\n            let info = (tablaStockRapido as any).page.info(), AmountItem:number = factorC*Number(amount.value), promediostock = 1, stockAuxiliar = Number(stockAux.value);\r\n            \r\n            if(endponit == \"descontarstock\")cantidadactual = cantidadactual-AmountItem;\r\n            if(endponit == \"aumentarstock\")cantidadactual = cantidadactual+AmountItem;\r\n            if(endponit == \"ajustarstock\")cantidadactual = AmountItem;\r\n\r\n            /*idUnidMedida === '1'\r\n                ?\r\n                (promediostock = cantidadactual>0?(stockAuxiliar/cantidadactual):0)\r\n                :\r\n                (promediostock = stockAuxiliar>0?(cantidadactual/stockAuxiliar):0);*/\r\n            promediostock = stockAuxiliar>0?(AmountItem/stockAuxiliar):0;\r\n\r\n            (async ()=>{\r\n                const datos = new FormData();\r\n                datos.append('tipoitem', tipoelemento);\r\n                datos.append('iditem', idelemento);\r\n                datos.append('cantidad', AmountItem.toString());\r\n                datos.append('stockaux', stockAuxiliar.toString());\r\n                datos.append('promediostock', promediostock.toString());\r\n                try{\r\n                    const url = \"/admin/api/\"+endponit;  //asocia el producto con el sub producto en la tabla productos_sub\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                        msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                        ////// reset form ///////\r\n                        (document.querySelector('#formStock') as HTMLFormElement)?.reset();\r\n                        //actualizar fila\r\n                        //(tablaStockRapido as any).cell(indiceFila, 3).data(cantidadactual).draw();\r\n                        //(tablaStockRapido as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                        //actualiza tabla stock rapido\r\n                        actualizarStockRapido([resultado.item[0]], tipoelemento);\r\n                    }else{\r\n                      msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                    miDialogoStock.close();\r\n                    document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                }catch(error){\r\n                    console.log(error);\r\n                }\r\n            })();//cierre de async()\r\n        });\r\n\r\n    //////////////////////////  UTILIDAD PRODUCTO  ///////////////////////////\r\n    ($('#utilidadProductos') as any).DataTable(configdatatablesstockrapido);  \r\n\r\n\r\n    //////////////////////////// SOTCK POR SUCURSAL //////////////////////\r\n    function printstockXsucursal(){\r\n        const sucursales = [...new Set(allproductsXsucursal.map(d => d.sucursal))]; //lista unica de sucursales\r\n        \r\n        // 2. Reorganizar por producto\r\n        const productos: Record<string, { nombreproducto: string; stocks: Record<string, string> }> = {};\r\n        allproductsXsucursal.forEach(d => {\r\n            if(d.productoid){\r\n                if (!productos['p'+d.productoid]) { //si el obj no es creado se crea con el nombre del producto pero el stock vacio\r\n                    productos['p'+d.productoid] = { nombreproducto: d.nombreproducto, stocks: {} };\r\n                }\r\n                productos['p'+d.productoid].stocks[d.sucursal] = d.stock; //aqui se llena el stock, que es un obj y sus propiedades son las sedes\r\n            }\r\n            if(d.subproductoid){\r\n                if (!productos['s'+d.subproductoid]) { //si el obj no es creado se crea con el nombre del producto pero el stock vacio\r\n                    productos['s'+d.subproductoid] = { nombreproducto: 'S-'+d.nombreproducto, stocks: {} };\r\n                }\r\n                productos['s'+d.subproductoid].stocks[d.sucursal] = d.stock; //aqui se llena el stock, que es un obj y sus propiedades son las sedes\r\n            }\r\n        });\r\n\r\n        // 3. Columnas dinámicas\r\n        const columnas = [{ title: \"Producto\", data: \"nombreproducto\" }];\r\n        sucursales.forEach(s => {\r\n            columnas.push({ title: s, data: s });\r\n        });\r\n\r\n        // 4. Dataset\r\n        const dataset = Object.values(productos).map(prod => {\r\n            const fila: any = { nombreproducto: prod.nombreproducto };\r\n            sucursales.forEach(s => {\r\n                fila[s] = prod.stocks[s] ?? 0; //fila es un obj, se crea la propieadad con el nombre de la sucursal y se iguala al objeto stock copn propiedad sucursal.\r\n            });\r\n            return fila;\r\n        });\r\n\r\n        tablaInventarioSedes = ($('#tablaInventarioSedes') as any).DataTable({\r\n            data: dataset,\r\n            columns: columnas,\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'copyHtml5', text: 'Copia'}, \r\n                    {extend: 'excelHtml5', title: 'InventarioXsede'}, \r\n                    {extend: 'pdfHtml5', title: 'InventarioXsede'}, \r\n                    {extend: 'print', title: 'InventarioXsede', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n            pageLength: 25,\r\n            paging: true,\r\n            lengthChange: true,\r\n            searching: true,\r\n            ordering: true,\r\n            info: true,\r\n            autoWidth: true,\r\n            responsive: true,\r\n            deferRender: true,\r\n            //retrieve: true,\r\n            processing: true,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando 1 de _MAX_ registros',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            destroy: true, // importante si recargas la tabla\r\n        });\r\n\r\n    }\r\n\r\n\r\n    ///////////////////////////// INGRESAR ORDEN DE PRODUCCION /////////////////////////////////\r\n        \r\n        //SELECT2 DE itemAproducir\r\n        ($('#itemAproducir') as any).select2({\r\n            maximumSelectionLength: 1,\r\n        });\r\n\r\n        ////// evento al select del producto a producir ////// \r\n        $(\"#itemAproducir\").on('change', (e)=>{\r\n            const idproducto = (e.target as HTMLOptionElement).value;\r\n            const selectedOption = $(\"#itemAproducir option:selected\");\r\n            if(idproducto){\r\n                const prodund = allConversionUnidades.filter(x =>x.idproducto == idproducto);\r\n                mostrarSelectUnidades(prodund);\r\n                let producto: datosProducto; //inicializamos el objeto de tipo interfaz \r\n                producto = {\r\n                    stock: selectedOption.data('stock'),\r\n                    precio_compra: selectedOption.data('precio_compra'),\r\n                    precio_venta: selectedOption.data('precio_venta')\r\n                }\r\n                mostrarInfoItem(producto);\r\n            }\r\n        });\r\n\r\n        /////////// CARGAR LAS UNIDADES DE MEDIDA EN EL SELECT unidadmedida  ////////////\r\n        function mostrarSelectUnidades(prodund:conversionunidadesapi[]):void{\r\n            while(selectIngresarProduccionUnidadmedida?.firstChild)selectIngresarProduccionUnidadmedida.removeChild(selectIngresarProduccionUnidadmedida?.firstChild);\r\n            prodund.forEach(und =>{\r\n              const option = document.createElement('option');\r\n              option.textContent = und.nombreunidaddestino;\r\n              option.value = und.id;  //und.id  =  es el id de la tabla conversionunidades\r\n              option.dataset.factor = und.factorconversion;\r\n              selectIngresarProduccionUnidadmedida.appendChild(option);\r\n            });\r\n        }\r\n\r\n        btnsproduccion.forEach((btnproduccion, index) =>{\r\n            btnproduccion.addEventListener('click', (e)=>{\r\n               if(selectitemAproducir.value){    \r\n                    document.querySelector('#nombreItemAProducir')!.textContent = selectitemAproducir.options[selectitemAproducir.selectedIndex].textContent;\r\n                    if(index === 0){\r\n                        endponit = \"aumentarstock\";\r\n                        document.querySelector('#modalIngresarProduccion')!.textContent = \"Ingresar produccion a inventario\";\r\n                    }\r\n                    if(index === 1){\r\n                        endponit = \"descontarstock\";\r\n                        document.querySelector('#modalIngresarProduccion')!.textContent = \"Descontar catnidad de inventario\";\r\n                    }\r\n                    if(index === 2){\r\n                        endponit = \"ajustarstock\";\r\n                        document.querySelector('#modalIngresarProduccion')!.textContent = \"Ajustar cantidad de inventario\";\r\n                    }\r\n                    miDialogoIngresarProduccion.showModal();\r\n                    document.addEventListener(\"click\", cerrarDialogoExterno);\r\n                }\r\n            });\r\n        });\r\n\r\n\r\n        document.querySelector('#formIngresarProduccion')?.addEventListener('submit', (e)=>{\r\n            e.preventDefault();\r\n            factorC = Number(selectIngresarProduccionUnidadmedida.options[selectIngresarProduccionUnidadmedida.selectedIndex].dataset.factor);\r\n            let AmountItemProduccion:number = factorC*Number(amountProduccion.value);\r\n\r\n            (async ()=>{\r\n                const datos = new FormData();\r\n                datos.append('tipoitem', '0'); //0 = producto,  1 = subproducto\r\n                datos.append('iditem', selectitemAproducir.value);\r\n                datos.append('cantidad', AmountItemProduccion.toString());\r\n                datos.append('construccion', '1');  //se indica al backend que es construccion y se debe descontar sus insumos\r\n                try{\r\n                    const url = \"/admin/api/\"+endponit;  //endpoint = aumentarstock para produccion, asocia el producto con el sub producto en la tabla productos_sub\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                        msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                        ////// reset form ///////\r\n                        (document.querySelector('#formIngresarProduccion') as HTMLFormElement)?.reset();\r\n                        //mostrar contaidad actual\r\n                        mostrarInfoItem(resultado.item[0]); //producto\r\n                        //actualizar tabla stock rapido\r\n                        if(resultado.insumos !== undefined)actualizarStockRapido(resultado.insumos[0], '1'); //subproductos\r\n                        //actualizar el selecto de los productos/insumos a producir\r\n                        $(\"#itemAproducir option:selected\").data('stock', resultado.item[0].stock);\r\n                        \r\n                    }else{\r\n                      msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                    miDialogoIngresarProduccion.close();\r\n                    document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                }catch(error){\r\n                    console.log(error);\r\n                }\r\n            })();//cierre de async()\r\n        });\r\n\r\n\r\n        function mostrarInfoItem(producto:{stock?:string, precio_compra:string, precio_venta:string}){\r\n            document.querySelector('#stock')!.textContent = Number(producto.stock).toLocaleString();\r\n            document.querySelector('#costoProduccion')!.textContent = \"$\"+Number(producto.precio_compra).toLocaleString();\r\n            document.querySelector('#precioVenta')!.textContent = \"$\"+Number(producto.precio_venta).toLocaleString();\r\n        }\r\n\r\n\r\n        function actualizarStockRapido(insumosProductos:{id:string, productoid:string, subproductoid:string, sucursalid:string, stock:string, stockminimo:string, stockaux?:string}[], tipoItem:string){\r\n            insumosProductos.forEach(element => {\r\n                (tablaStockRapido as any).rows().every(function (this: any){\r\n                    const rowNode = this.node() as HTMLTableRowElement;\r\n                    let id_element = element.subproductoid, idAttr = rowNode.getAttribute('data-idsubproducto');\r\n                    if(tipoItem == '0'){\r\n                        idAttr = rowNode.getAttribute('data-idproducto');\r\n                        id_element = element.productoid;\r\n                    }\r\n                    if (idAttr && idAttr === id_element){\r\n                        this.cell(this.index(), 3).data(`<div class=\"text-center px-3 py-4 rounded-lg\">${element.stock}</div>`);\r\n                        this.cell(this.index(), 5).data(`${element.stockaux}`);\r\n\r\n                        // Obtén el <td> real\r\n                        const td = (tablaStockRapido as any).cell(this.index(), 3).node() as HTMLTableCellElement;\r\n                        if(Number(element.stock) <= Number(element.stockminimo)){\r\n                            td.firstElementChild?.classList.remove('bg-cyan-50', 'text-cyan-600');\r\n                            td.firstElementChild?.classList.add('bg-red-50', 'text-red-800');\r\n                        }else{\r\n                            td.firstElementChild?.classList.remove('bg-red-50', 'text-red-800');\r\n                            td.firstElementChild?.classList.add('bg-cyan-50', 'text-cyan-600');\r\n                        }\r\n                    } \r\n                });\r\n            })\r\n        }\r\n\r\n\r\n        function cerrarDialogoExterno(event:Event) {\r\n            const f = event.target;\r\n            if (f === miDialogoTrasladoInvnetario || f === miDialogoMasOpciones || f === miDialogoStock || f === miDialogoIngresarProduccion || f===miDialogoBajoStock || (f as HTMLInputElement).value === 'salir' || (f as HTMLElement).id == 'btnXCerrarTrasladoInvnetario' || (f as HTMLElement).id == 'btnXCerrarMasOpciones' || (f as HTMLElement).id == 'btnCerrarTotalBajoStock') {\r\n                miDialogoStock.close();\r\n                miDialogoIngresarProduccion.close();\r\n                miDialogoTrasladoInvnetario.close();\r\n                miDialogoMasOpciones.close();\r\n                miDialogoBajoStock.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n            }\r\n        }\r\n\r\n\r\n        ///////////////////////////// GENERAR CODIGOS DE BARRAS /////////////////////////////////\r\n        let productoCodeBar: datosProducto|undefined;\r\n        let imagenBarcode: string | undefined;\r\n\r\n        ($('#itemCodeBar') as any).select2({\r\n            width: '100%',\r\n            maximumSelectionLength: 1,\r\n        });\r\n\r\n        ////// evento al select del producto a producir ////// \r\n        $(\"#itemCodeBar\").on('change', (e)=>{\r\n            const idproducto = (e.target as HTMLSelectElement).value;\r\n            const selectedOption = $(\"#itemCodeBar option:selected\");\r\n            if(idproducto){\r\n                productoCodeBar = {\r\n                    sku: selectedOption.data('sku'),\r\n                    precio_compra: selectedOption.data('precio_compra'),\r\n                    precio_venta: selectedOption.data('precio_venta'),\r\n                };\r\n                (document.querySelector('#codigoBarras') as HTMLInputElement).value = productoCodeBar.sku??'';\r\n            }\r\n        });\r\n\r\n        ///////btn para generar codigo de barras\r\n        document.querySelector('#formGenerarCodeBar')?.addEventListener('submit', (e)=>{\r\n            e.preventDefault();\r\n            \r\n            if(!productoCodeBar || !productoCodeBar.sku){\r\n                alert('Producto no seleccionado o no tiene codigo de barras');\r\n                return;\r\n            }\r\n\r\n            const printPrecio = document.querySelector('#precioCodeBar') as HTMLSelectElement;\r\n\r\n            const canvas = document.querySelector('#barcode') as HTMLCanvasElement;\r\n            const options:any = {\r\n                bcid: 'code128',       // tipo de código\r\n                text: productoCodeBar.sku+'',     // valor (SKU o código)\r\n                scale: 3,\r\n                height: 10,\r\n                includetext: false,\r\n                textsize: 8,\r\n                textyoffset: 2,\r\n                textxalign: 'center'\r\n            }\r\n\r\n            if(printPrecio.value == '1'){\r\n                 options.alttext = '$'+Number(productoCodeBar.precio_venta).toLocaleString();\r\n            }else{\r\n                delete options.alttext;\r\n            }\r\n\r\n            bwipjs.toCanvas(canvas, options);\r\n            imagenBarcode = canvas.toDataURL(\"image/png\");\r\n\r\n        });\r\n        \r\n\r\n        document.querySelector('#btnImprimir')?.addEventListener('click', () => {\r\n            if(!imagenBarcode){\r\n                alert('Primero genere el código de barras');\r\n                return;\r\n            }\r\n            const ventana = window.open('', '_blank');\r\n            if(ventana){\r\n                ventana?.document.write(`\r\n                    <html>\r\n                    <head>\r\n                        <title>Etiqueta</title>\r\n                        <style>\r\n                            @page {\r\n                                size: 60mm 40mm;\r\n                                margin: 0;\r\n                            }\r\n                            body{\r\n                                margin:0;\r\n                                \r\n                            }\r\n\r\n                            .etiqueta{\r\n                                text-align:center;\r\n                                width:60mm;\r\n                                height:40mm;\r\n                            }\r\n\r\n                            img{\r\n                                width:100%;\r\n                            }\r\n                        </style>\r\n                    </head>\r\n\r\n                    <body>\r\n                        <div class=\"etiqueta\">\r\n                            <img src=\"${imagenBarcode}\" />\r\n                        </div>\r\n                    </body>\r\n                    </html>\r\n                `);\r\n                ventana.document.close();\r\n                ventana.onload = ()=>{\r\n                    ventana?.focus();\r\n                    ventana?.print();\r\n                    setTimeout(() => { ventana?.close(); }, 200); // Cerrar la ventana después de unos segundos\r\n                };\r\n            }\r\n        });\r\n\r\n\r\n    }\r\n\r\n})();","(()=>{\r\n  if(document.querySelector('.categorias')){\r\n    const crearCategoria = document.querySelector('#crearCategoria');\r\n    const miDialogoCategoria = document.querySelector('#miDialogoCategoria') as any;\r\n    let indiceFila=0, control=0, tablaCategorias:HTMLElement;\r\n\r\n    type productsapi = {\r\n      id:string,\r\n      idcategoria: string,\r\n      nombre: string,\r\n      foto: string,\r\n      marca: string,\r\n      codigo: string,\r\n      descripcion: string,\r\n      peso: string,\r\n      medidas: string,\r\n      color: string,\r\n      funcion: string,\r\n      uso:string,\r\n      fabricante: string,\r\n      garantia: string,\r\n      stock: string,\r\n      categoria: string,\r\n      precio_compra: string,\r\n      precio_venta: string,\r\n      fecha_ingreso: string,\r\n      //idservicios:{idempleado:string, idservicio:string}[]\r\n    };\r\n\r\n    let products:productsapi[]=[], unproducto:productsapi;\r\n\r\n    //////////////////  TABLA //////////////////////\r\n    tablaCategorias = ($('#tablaCategorias') as any).DataTable(configdatatables25reg);\r\n\r\n    crearCategoria?.addEventListener('click', (e):void=>{\r\n      control = 0;\r\n      limpiarformdialog();\r\n      document.querySelector('#modalCategoria')!.textContent = \"Crear categoria\";\r\n      (document.querySelector('#btnEditarCrearCategoria') as HTMLInputElement).value = \"Crear\";\r\n      miDialogoCategoria.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    document.querySelector('#tablaCategorias')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarCategoria\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarCategoria\"))editarCategoria(e);\r\n      if(target?.classList.contains(\"eliminarCategoria\")||target.parentElement?.classList.contains(\"eliminarCategoria\"))eliminarCategoria(e);\r\n    });\r\n\r\n    function editarCategoria(e:Event){\r\n      control = 1;\r\n      let idcategoria = (e.target as HTMLElement).parentElement?.id!;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idcategoria = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n      //(document.querySelector('#formCrearUpdateCategoria') as HTMLFormElement).action = \"/admin/almacen/actualizar_categoria\";\r\n      document.querySelector('#modalCategoria')!.textContent = \"Actualizar categoria\";\r\n      (document.querySelector('#btnEditarCrearCategoria') as HTMLInputElement)!.value = \"Actualizar\";\r\n      (document.querySelector('#idcategoria') as HTMLInputElement).value = idcategoria;\r\n      (document.querySelector('#categoria') as HTMLInputElement).value = ((e.target as HTMLElement).closest('.acciones-btns') as HTMLElement)?.dataset.categoria!; \r\n      indiceFila = (tablaCategorias as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoCategoria.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar categoria  //////////////////////\r\n    document.querySelector('#formCrearUpdateCategoria')?.addEventListener('submit', e=>{\r\n      if(control){\r\n        e.preventDefault();\r\n        var info = (tablaCategorias as any).page.info();\r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', $('#idcategoria').val() as string);\r\n          datos.append('nombre', $('#categoria').val()as string);\r\n          try {\r\n              const url = \"/admin/api/actualizar_categoria\";\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json(); \r\n              console.log(resultado); \r\n              if(resultado.exito !== undefined){\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                ///////// cambiar la fila completa, su contenido //////////\r\n                const datosActuales = (tablaCategorias as any).row(indiceFila+=info.start).data();\r\n                /*Nombre categoria*/datosActuales[2] = $('#categoria').val();\r\n                /*data-categoria*/datosActuales[4] = `<div class=\"acciones-btns\" id=\"${$('#idcategoria').val()}\" data-categoria=\"${$('#categoria').val()}\"><button class=\"btn-md btn-turquoise editarCategoria\"><i class=\"fa-solid fa-pen-to-square\"></i></button><button class=\"btn-md btn-red eliminarCategoria\"><i class=\"fa-solid fa-trash-can\"></i></button></div>`;//$('#categoria').val();\r\n                \r\n                (tablaCategorias as any).row(indiceFila).data(datosActuales).draw();\r\n                (tablaCategorias as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n              document.addEventListener(\"click\", cerrarDialogoExterno);\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n      } //fin if(control)\r\n    });\r\n\r\n    function eliminarCategoria(e:Event){\r\n      let idcategoria = (e.target as HTMLElement).parentElement!.id, info = (tablaCategorias as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idcategoria = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n      indiceFila = (tablaCategorias as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      Swal.fire({\r\n          customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n          icon: 'question',\r\n          title: 'Desea eliminar la categoria?',\r\n          text: \"La categoria y sus productos asociados, seran eliminados definitivamente.\",\r\n          showCancelButton: true,\r\n          confirmButtonText: 'Si',\r\n          cancelButtonText: 'No',\r\n      }).then((result:any) => {\r\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idcategoria);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarCategoria\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();\r\n                      if(resultado.length || resultado.exito !== undefined){\r\n                        (tablaCategorias as any).row(indiceFila+info.start).remove().draw(); \r\n                        (tablaCategorias as any).page(info.page).draw('page'); \r\n                        Swal.fire(resultado.exito[0], '', 'success')\r\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateCategoria') as HTMLFormElement)?.reset();\r\n      (document.querySelector('#formCrearUpdateCategoria') as HTMLFormElement).action = \"/admin/almacen/crear_categoria\";\r\n      (document.querySelector('#idcategoria') as HTMLInputElement).value = '0';\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoCategoria || (event.target as HTMLInputElement).value === 'Salir' || (event.target as HTMLInputElement).value === 'Actualizar') {\r\n        miDialogoCategoria.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n  }\r\n\r\n})();","\r\n(()=>{\r\n    if(document.querySelector('.compras')){\r\n        const proveedor = document.querySelector('#proveedor') as HTMLSelectElement;\r\n        //const impuesto = document.querySelector('#inputimpuesto') as HTMLSelectElement;\r\n        const inputValorimp = document.querySelector('#valorimp') as HTMLInputElement;\r\n        const nfactura = document.querySelector('#nfactura') as HTMLInputElement;\r\n        const fecha = document.querySelector('#fecha') as HTMLDataElement;\r\n        const origenPago = document.querySelector('#origenPago') as HTMLSelectElement;\r\n        const origenCaja = document.querySelector('#origenCaja') as HTMLSelectElement;\r\n        const origenBanco = document.querySelector('#origenBanco') as HTMLSelectElement;\r\n        const formapago = document.querySelector('#formapago') as HTMLSelectElement;\r\n        const observacion = document.querySelector('#observacion') as HTMLInputElement;\r\n        const btnvaciar = document.querySelector('#btnvaciar');\r\n        const miDialogoVaciar = document.querySelector('#miDialogoVaciar') as any;\r\n        const miDialogoRegistrarcompra = document.querySelector('#miDialogoRegistrarcompra') as any;\r\n        const tablaCompras = document.querySelector('#tablaCompras tbody');\r\n\r\n        const constImp: {[key:string]: number} = {};\r\n        constImp['excluido'] = 0;\r\n        constImp['0'] = 0;  //exento de iva, tarifa 0%\r\n        constImp['5'] = 0.0476190476190476; //iva, tarifa al 5%,  Bienes/servicios al 5\r\n        constImp['8'] = 0.0740740740740741; //inc, tarifa al 8%,  impuesto nacional al consumo\r\n        constImp['16'] = 0.1379310344827586; //iva, tarifa al 16%,  contratos firmados con el estado antes de ley 1819\r\n        constImp['19'] = 0.1596638655462185; //iva, tarifa al 19%,  tarifa general\r\n\r\n        type conversionunidadesapi = {\r\n        id:string,\r\n        idproducto: string,\r\n        idsubproducto: string,\r\n        idunidadmedidabase: string,\r\n        idunidadmedidadestino: string,\r\n        nombreunidadbase: string,\r\n        nombreunidaddestino: string,\r\n        factorconversion: string,\r\n        //idservicios:{idempleado:string, idservicio:string}[]\r\n        };\r\n\r\n        let carrito:{iditem:string, idpx:string, idsx:string, tipocosto:string, tipo: string, nombreitem:string, unidad:string, stock: number, cantidad: number, cantidadcomprado: number, factor: number, impuesto: number, valorunidad: number, subtotal: number, precio_compra: number, valorcompra: number}[]=[];\r\n        let tax:number = 0, percentImp:number = 0, barcode = \"\", allConversionUnidades:conversionunidadesapi[] = [];\r\n        let filteredData: {id:string, text:string, tipo:string, sku:string, unidadmedida:string}[];   //tipo = 0 es producto simple,  1 = subproducto\r\n\r\n        function actualizarContadorProductos(): void {\r\n            const badge = document.querySelector('#contadorProductos');\r\n            if(!badge) return;\r\n            const cantidad = carrito.length;\r\n            badge.textContent = cantidad === 1? '1 producto': `${cantidad} productos`;\r\n        }\r\n\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/allConversionesUnidades\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas las conversiones de unidades\r\n                const respuesta = await fetch(url); \r\n                allConversionUnidades = await respuesta.json();\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/totalitems\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas los productos simples y subproductos\r\n                const respuesta = await fetch(url); \r\n                const resultado:{id:string, nombre:string, tipoproducto:string, tipoproduccion: string, sku:string, unidadmedida:string}[] = await respuesta.json();\r\n                console.log(resultado);\r\n                filteredData = resultado.filter(item => item.tipoproduccion=='0'||item.tipoproduccion==null).map(item => ({ id: item.id, text: item.nombre, tipo: item.tipoproducto??'1', sku: item.sku, unidadmedida: item.unidadmedida }));\r\n                activarselect2(filteredData);\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n\r\n        //impuesto?.addEventListener('input', ()=>resumen());\r\n        inputValorimp.addEventListener('input', (e)=>resumen());\r\n\r\n        function activarselect2(filteredData:{id:string, text:string, tipo:string, sku:string, unidadmedida:string}[]){\r\n            ($('#articulo') as any).select2({ \r\n                data: filteredData,\r\n                placeholder: \"Selecciona un item\",\r\n                maximumSelectionLength: 1,\r\n                /*\r\n                templateResult: function (data:{id:string, text:string, tipo:string}) {\r\n                    // Personalizar cómo se muestra cada opción en el dropdown\r\n                    if (!data.id) { return data.text; }  // Si no hay id, solo mostrar el texto\r\n                    const html = `\r\n                        <div class=\"custom-option\">\r\n                            <span class=\"item-name\">${data.text}</span> \r\n                            <span class=\"item-type\">${data.tipo}</span>  <!-- Mostrar tipo adicional -->\r\n                        </div>`;\r\n                    return $(html);  // Devolver el HTML personalizado\r\n                }*/\r\n            });\r\n        }\r\n\r\n\r\n        //////////  ELEGIR ORIGEN DEL PAGO DE LA COMPRA, CAJA O BANCO ///////////\r\n        origenPago.addEventListener('change', (e:Event)=>{\r\n            if((e.target as HTMLOptionElement).value == '0'){ //0 = origen caja\r\n                document.querySelector('#divBanco')?.classList.add('hidden');\r\n                document.querySelector('#divBanco')?.removeAttribute(\"required\");\r\n            }else{  //1 = origen banco\r\n                document.querySelector('#divBanco')?.classList.remove('hidden');\r\n                document.querySelector('#divBanco')?.setAttribute(\"required\", \"\");\r\n            }\r\n        });\r\n\r\n\r\n        window.addEventListener('keydown', (e: KeyboardEvent) => {\r\n            if (e.key === 'Control')(document.querySelector('#btnScanner') as HTMLSelectElement).focus();\r\n            if (e.key === 'Enter') {\r\n                if (barcode.length >= 3) {\r\n                    e.preventDefault();\r\n                    e.stopImmediatePropagation(); // <--- CRITICO: Detiene a Select2 y a cualquier botón\r\n                    searchBarCode(barcode);\r\n                    barcode = \"\";\r\n                    return false;\r\n                }\r\n                barcode = \"\";\r\n            } else {\r\n                barcode += e.key;\r\n            }\r\n        }, true);\r\n\r\n\r\n        function searchBarCode(barcode:string){\r\n            const itemselected = filteredData.find(x=>x.sku==barcode);\r\n            if(itemselected != undefined){\r\n                let productSelected = carrito.find(x=>x.iditem==itemselected.id&&x.tipo==itemselected.tipo);\r\n                if(productSelected != undefined){\r\n                    productSelected.cantidadcomprado  += 1;\r\n                    productSelected.cantidad = productSelected.cantidadcomprado*productSelected.factor;\r\n                    productSelected.stock = productSelected.cantidad;\r\n                    //aumentar la cantodad en los inputs\r\n                    const fila = document.querySelector<HTMLInputElement>(`TR[data-id=\"${productSelected.iditem}\"][data-tipo=\"${productSelected.tipo}\"] .inputcantidad`);\r\n                    if(fila)fila.value = productSelected.stock+'';\r\n                }else{ //itme no esta en carrito\r\n                    agregarProducto(itemselected);\r\n                }\r\n            }\r\n        }\r\n\r\n\r\n        ////// EVENTO AL SELECT ARTICULOS O ITEMS PARA SELECCIONAR EL ITEM Y AÑADIR AL CARRITO ////// \r\n        $(\"#articulo\").on('change', (e)=>{\r\n            let datos = ($('#articulo') as any).select2('data')[0];\r\n            if(datos)agregarProducto(datos);\r\n            $(\"#articulo\").val('null');\r\n        });\r\n\r\n\r\n        function agregarProducto(datos:any) {\r\n            const index = carrito.findIndex(x=>x.iditem==datos.id&&x.tipo==datos.tipo);\r\n            if(index == -1){  //si el item seleccionado no existe en el carrito, agregarlo.\r\n                const itemselected = filteredData.find(x=>x.id==datos.id&&x.tipo==datos.tipo)!; //products es el arreglo de todos los productos traido por api\r\n                const item:{iditem: string, idpx: string, idsx: string, tipocosto:string, tipo: string, nombreitem: string, unidad: string, stock: number, cantidad: number, cantidadcomprado: number, factor: number, impuesto: number, valorunidad: number, subtotal: number, precio_compra:number, valorcompra: number} = {\r\n                    iditem: itemselected?.id!,\r\n                    idpx: itemselected.tipo=='0'?itemselected.id:'NULL',\r\n                    idsx: itemselected.tipo=='1'?itemselected.id:'NULL',\r\n                    tipocosto: '1',\r\n                    tipo: itemselected.tipo,  ////tipo = 0 es producto simple,  1 = producto principal compuesto o subproducto\r\n                    nombreitem: itemselected.text,\r\n                    unidad: itemselected.unidadmedida,\r\n                    stock: 1,\r\n                    cantidad: 1,\r\n                    cantidadcomprado: 1,\r\n                    factor: 1,\r\n                    impuesto: 0,\r\n                    valorunidad: 0,\r\n                    subtotal: 0,\r\n                    precio_compra: 0,\r\n                    valorcompra: 0,\r\n                }\r\n                carrito = [...carrito, item];\r\n                actualizarContadorProductos();\r\n                if(carrito.length === 1)document.querySelector('#filaVacia')?.remove();\r\n                printItemTable(datos.id, datos.tipo, datos.unidadmedida);\r\n            }\r\n        }\r\n\r\n\r\n        function printItemTable(id:string, tipo:string, unidadmedida:string){\r\n            let options = `<option data-factor=\"1\" value=\"\" >${unidadmedida}</option>`;\r\n            const unItem = filteredData.find(x=>x.id==id&&x.tipo==tipo)!;\r\n            if(tipo=='1'){   //si es un subproducto\r\n                options = \"\";\r\n                const subproductounidades = allConversionUnidades.filter(x => x.idsubproducto == id); \r\n                subproductounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idsubproducto}\" >${u.nombreunidaddestino}</option>`);\r\n            }\r\n            if(tipo=='0'){\r\n                options = \"\";\r\n                const productounidades = allConversionUnidades.filter(x => x.idproducto == id); \r\n                productounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idproducto}\" >${u.nombreunidaddestino}</option>`);\r\n            }\r\n            const tr = document.createElement('TR');\r\n            tr.classList.add('itemselect');\r\n            tr.dataset.id = `${id}`;\r\n            tr.dataset.tipo = `${tipo}`;\r\n            tr.insertAdjacentHTML('afterbegin', `<td class=\"!px-0 !py-2 text-xl text-gray-500 leading-5\">${unItem?.text}</td> \r\n            <td class=\"!p-2 text-xl text-gray-500 leading-5\">\r\n                <select class=\"formulario__select selectunidad\">\r\n                    ${options}  \r\n                </select>\r\n            </td>\r\n            <td class=\"!px-0 !py-2\"><div class=\"flex\"><button type=\"button\"><span class=\"menos material-symbols-outlined\">remove</span></button><input type=\"text\" class=\"inputcantidad w-20 px-2 text-center\" value=\"1\" oninput=\"this.value = parseInt(this.value.replace(/[,.]/g, '')||1)\"><button type=\"button\"><span class=\"mas material-symbols-outlined\">add</span></button></div></td>\r\n            <td class=\"!p-2 text-xl text-gray-500 leading-5\"><input type=\"text\" placeholder=\"Ingresa Valor Total Producto\" class=\"inputcompra text-base sm:text-lg md:text-xl lg:text-2xl placeholder:text-sm sm:placeholder:text-base md:placeholder:text-lg lg:placeholder:text-xl bg-gray-50 border border-gray-300 text-gray-900 rounded-lg focus:border-indigo-600 block w-full p-2.5 dark:bg-gray-600 dark:border-gray-500 dark:placeholder-gray-400 dark:text-white h-14 focus:outline-none focus:ring-1\" value=\"\" oninput=\"this.value = parseInt(this.value.replace(/[,.]/g, '')||0)\"></td>\r\n            <td class=\"accionestd\"><div class=\"acciones-btns\"><button class=\"btn-md btn-red eliminarItem\"><i class=\"fa-solid fa-trash-can\"></i></button></div></td>`);\r\n            tablaCompras?.appendChild(tr);\r\n        }\r\n        \r\n\r\n        //////////////////////////////////// evento a la tabla de los productos seleccionados  ///////////////////////////////////\r\n        tablaCompras?.addEventListener('click', (e:Event)=>{\r\n            const elementItem = (e.target as HTMLElement)?.closest('.itemselect'); //seleccionamos el tr de la tabla\r\n            const iditem = (elementItem as HTMLElement).dataset.id!;\r\n            const tipoitem = (elementItem as HTMLElement).dataset.tipo!;\r\n\r\n            const itemCarrito = carrito.find(x=>x.iditem==iditem&&x.tipo==tipoitem)!;\r\n\r\n            if((e.target as HTMLElement).classList.contains('selectunidad')){\r\n                if((e.target as HTMLElement).dataset.event != \"eventSelect\"){\r\n                    e.target?.addEventListener('change', (e:Event)=>{\r\n                        const unit = e.target as HTMLSelectElement;\r\n                        itemCarrito.factor = Number(unit.options[unit.selectedIndex].dataset.factor);\r\n                    });\r\n                    (e.target as HTMLElement).dataset.event = \"eventSelect\"; //se marca al input que ya tiene evento añadido\r\n                }\r\n            }\r\n            \r\n            if((e.target as HTMLElement).classList.contains('menos')){\r\n                itemCarrito.cantidadcomprado--;\r\n                if(itemCarrito.cantidadcomprado<0)itemCarrito.cantidadcomprado = 0;\r\n            }\r\n\r\n            if((e.target as HTMLElement).classList.contains('inputcantidad')){\r\n                if((e.target as HTMLElement).dataset.event != \"eventInput\"){\r\n                    e.target?.addEventListener('input', (e:Event)=>{\r\n                        itemCarrito.cantidadcomprado = Number((e.target as HTMLInputElement).value);\r\n                        itemCarrito.cantidad = itemCarrito.cantidadcomprado*itemCarrito.factor;\r\n                        itemCarrito.stock = itemCarrito.cantidad;\r\n                    });\r\n                    (e.target as HTMLElement).dataset.event = \"eventInput\"; //se marca al input que ya tiene evento añadido\r\n                }\r\n            }\r\n\r\n            if((e.target as HTMLElement).classList.contains('mas'))itemCarrito.cantidadcomprado++;\r\n            \r\n            //////// INPUT CANTIDAD DE LA TABLA DE ITEMS DE COMPRA, SE ACTUALIZA CADA VEZ QUE SE DE CLICK EN MENOS O MAS\r\n            (tablaCompras?.querySelector(`TR[data-id=\"${iditem}\"][data-tipo=\"${tipoitem}\"] .inputcantidad`) as HTMLInputElement).value = itemCarrito?.cantidadcomprado+'';\r\n\r\n            /////// EVENTO AL INPUT VALOR DE COMPRA DE LA TABLA DE ITEMS DE COMPRA  ///////\r\n            if((e.target as HTMLElement).classList.contains('inputcompra')){\r\n                if((e.target as HTMLElement).dataset.event != \"eventInput\"){\r\n                    e.target?.addEventListener('input', (e:Event)=>{\r\n                        itemCarrito.valorcompra = Number((e.target as HTMLInputElement).value);\r\n                        itemCarrito.precio_compra = itemCarrito.valorcompra/itemCarrito.cantidad;\r\n                        resumen();\r\n                    });\r\n                    (e.target as HTMLElement).dataset.event = \"eventInput\"; //se marca al input que ya tiene evento añadido\r\n                }\r\n            }\r\n\r\n            if((e.target as HTMLElement).classList.contains('eliminarItem') || (e.target as HTMLElement).tagName == \"I\"){\r\n                carrito = carrito.filter(x=> {\r\n                    if(x.iditem==iditem){\r\n                        if(x.tipo==tipoitem){\r\n                            return false;\r\n                        }else{\r\n                            return true;\r\n                        }\r\n                    }else{\r\n                        return true;\r\n                    }\r\n                });\r\n                tablaCompras?.querySelector(`TR[data-id=\"${iditem}\"][data-tipo=\"${tipoitem}\"]`)?.remove();\r\n                actualizarContadorProductos();\r\n                resumen();\r\n            }\r\n\r\n            itemCarrito.cantidad = itemCarrito.cantidadcomprado*itemCarrito.factor;\r\n            itemCarrito.stock = itemCarrito.cantidad;\r\n        });\r\n\r\n\r\n        btnvaciar?.addEventListener('click', ()=>{\r\n            if(carrito.length){\r\n              miDialogoVaciar.showModal();\r\n              document.addEventListener(\"click\", cerrarDialogoExterno);\r\n            }\r\n        });\r\n\r\n        document.querySelector('#formComprar')?.addEventListener('submit', e=>{\r\n            e.preventDefault();\r\n            miDialogoRegistrarcompra.showModal();\r\n            (document.querySelector('#numOrden') as HTMLSpanElement).textContent = nfactura.value;\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        });\r\n\r\n  \r\n        async function procesarpedido(estado:string){\r\n            const datos = new FormData();\r\n            const valorCarrito = carrito.reduce((total, item)=>item.valorcompra+total, 0);\r\n            datos.append('idproveedor', proveedor.options[proveedor.selectedIndex].value);\r\n            //datos.append('idformapago', formapago.options[formapago.selectedIndex].value);\r\n            datos.append('idorigencaja', origenCaja.options[origenCaja.selectedIndex].value);\r\n            datos.append('idorigenbanco', origenBanco.options[origenBanco.selectedIndex].value);\r\n            datos.append('nombreproveedor', proveedor.options[proveedor.selectedIndex].textContent!);\r\n            //datos.append('formapago', formapago.options[formapago.selectedIndex].text);\r\n            datos.append('nfactura', nfactura.value);\r\n            datos.append('impuesto', (percentImp.toFixed(2))+'');\r\n            datos.append('valorimp', tax+'');\r\n            datos.append('base', valorCarrito+'');\r\n            datos.append('origenpago', origenPago.options[origenPago.selectedIndex].value); //0 = si el origen viene de la caja,  1 = banco\r\n            datos.append('nombreorigenpago', origenPago.options[origenPago.selectedIndex].textContent+''); //caja o banco\r\n            datos.append('nombreorigencaja', origenCaja.options[origenCaja.selectedIndex].textContent+'');\r\n            datos.append('nombreorigenbanco', origenBanco.options[origenBanco.selectedIndex].value?origenBanco.options[origenBanco.selectedIndex].textContent+'':'');\r\n            datos.append('cantidaditems', carrito.reduce((total, item)=>item.cantidad+total, 0)+'');\r\n            datos.append('observacion', observacion.value);\r\n            datos.append('estado', estado);\r\n            datos.append('subtotal', valorCarrito+'');\r\n            datos.append('valortotal', (valorCarrito+tax)+'');\r\n            datos.append('fechacompra', fecha.value);\r\n            datos.append('carrito', JSON.stringify(carrito));  ////arreglo de objetos de producto simple y subproducto\r\n            datos.append('subID', JSON.stringify(carrito.map(item=>{if(item.idsx){return item.idsx}}))); //envia solo los id de los subproductos\r\n            try {\r\n                const url = \"/admin/api/registrarCompra\";  //va al controlador ventascontrolador\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                const resultado = await respuesta.json();\r\n                if(resultado.exito !== undefined){\r\n                    msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                    //imprimir detalle de compra\r\n                    if((document.querySelector('#imprimirComprobanteCompra') as HTMLInputElement).checked){\r\n                        printComprobanteCompra(resultado.idcompra);\r\n                    }\r\n                    /////// reinciar campos de la compra\r\n                    vaciarcompra();\r\n                    (document.querySelector('#formComprar') as HTMLFormElement)?.reset();\r\n                }else{\r\n                    msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                }\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        }\r\n\r\n\r\n        function printComprobanteCompra(idcompra:string){\r\n            setTimeout(() => {\r\n                window.open(\"/admin/printComprobanteCompraPDF?id=\" + idcompra, \"_blank\");  //llama a printcontrolador\r\n            }, 1000);\r\n        }\r\n\r\n        function validarValorCompra():boolean{\r\n            return carrito.some(item=>Number.isNaN(item.valorcompra)||item.valorcompra==0);\r\n        }\r\n\r\n        function resumen():void{\r\n            const valorCarrito = carrito.reduce((total, item)=>item.valorcompra+total, 0);\r\n            tax = Number(inputValorimp.value);\r\n            percentImp = valorCarrito == 0 ? 0 :(100*tax)/valorCarrito;\r\n            document.querySelector('#subTotal')!.textContent = '$ '+(valorCarrito.toLocaleString());\r\n            document.querySelector('#impuesto')!.textContent = (percentImp.toFixed(2))+'%  -  $'+tax.toLocaleString();\r\n            document.querySelector('#total')!.textContent = '$ '+((valorCarrito+tax).toLocaleString());\r\n        }\r\n\r\n        function vaciarcompra():void{\r\n            carrito.length = 0;\r\n            while(tablaCompras?.firstChild)tablaCompras.removeChild(tablaCompras?.firstChild);\r\n            document.querySelector('#impuesto')!.textContent = '% 0';\r\n            document.querySelector('#total')!.textContent = '$ 0';\r\n        }\r\n\r\n        function cerrarDialogoExterno(event:Event) {\r\n            const f = event.target;\r\n            if (f === miDialogoVaciar || f === miDialogoRegistrarcompra || (f as HTMLInputElement).closest('.novaciar') || (f as HTMLInputElement).closest('.sivaciar') || (f as HTMLInputElement).closest('.nocomprar') || (f as HTMLInputElement).closest('.sicomprar')) {\r\n              miDialogoVaciar.close();\r\n              miDialogoRegistrarcompra.close();\r\n              document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n              if((f as HTMLInputElement).closest('.sicomprar')){\r\n                if(!validarValorCompra()){\r\n                    procesarpedido('paga');\r\n                }else{\r\n                    msjalertToast('error', '¡Error!', 'Verifica el valor de compra de la lista de productos');\r\n                }\r\n              }\r\n              if((f as HTMLInputElement).closest('.sivaciar'))vaciarcompra();\r\n            }\r\n        }\r\n        \r\n    }\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.conversionUnidades')){\r\n      const miDialogoConversionUnidad = document.querySelector('#miDialogoConversionUnidad') as any;\r\n      const unidadesMedidas = document.querySelector('#unidadesMedidas') as HTMLSelectElement;\r\n      const contenedor = document.querySelector('#contenedor') as HTMLDivElement;\r\n      const factor = document.querySelector('#equivalente') as HTMLInputElement;\r\n      let tablaSubProductos:HTMLElement;\r\n\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      \r\n      type subproductsapi = {\r\n        id:string,\r\n        id_unidadmedida: string,\r\n        unidadmedida: string,\r\n        nombre: string,\r\n        sku: string,\r\n        proveedor: string,\r\n        descripcion: string,\r\n        medidas: string,\r\n        color: string,\r\n        uso:string,\r\n        stock: string,\r\n        stockminimo: string,\r\n        precio_compra: string,\r\n        fecha_ingreso: string,\r\n      };\r\n\r\n      interface IunidadesMedida {\r\n        id:string,\r\n        nombre:string\r\n      }\r\n  \r\n      type conversionunidadesapi = {\r\n        id:string,\r\n        idproducto: string,\r\n        idsubproducto: string,\r\n        idunidadmedidabase: string,\r\n        idunidadmedidadestino: string,\r\n        nombreunidadbase: string,\r\n        nombreunidaddestino: string,\r\n        factorconversion: string,\r\n      };\r\n\r\n      let subproducts:subproductsapi[]=[], unsubproducto:subproductsapi, allUnidadesMedida:IunidadesMedida[]=[], allConversionUnidades:conversionunidadesapi[] = [];\r\n  \r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allsubproducts\"; //llamado a la API REST\r\n            const respuesta = await fetch(url); \r\n            subproducts = await respuesta.json(); \r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/almacen/allUnidadesMedida\"; //llamado a la API REST\r\n            const respuesta = await fetch(url); \r\n            allUnidadesMedida = await respuesta.json(); \r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allConversionesUnidades\";\r\n            const respuesta = await fetch(url); \r\n            allConversionUnidades = await respuesta.json(); \r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n  \r\n      //////////////////  TABLA //////////////////////\r\n      tablaSubProductos = ($('#tablaSubProductos') as any).DataTable(configdatatables);\r\n  \r\n  \r\n      ///////////// EVENTOS A LA TABLA SUBPRODUCTOS /////////////\r\n      document.querySelector('#tablaSubProductos')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n        const target = e.target as HTMLElement;\r\n        if(target?.classList.contains(\"editarUnidadMedida\")||target.parentElement?.classList.contains(\"editarUnidadMedida\"))editarUnidadMedida(e);\r\n      });\r\n  \r\n      function editarUnidadMedida(e:Event){\r\n        while(unidadesMedidas.firstChild)unidadesMedidas.removeChild(unidadesMedidas.firstChild);\r\n        let idsubproducto = (e.target as HTMLElement).parentElement?.id!;\r\n        if((e.target as HTMLElement)?.tagName === 'I')idsubproducto = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n        unsubproducto = subproducts.find(x=>x.id === idsubproducto)!;\r\n  \r\n        $('#nombreInsumo').text(unsubproducto?.nombre??'');\r\n        $('#unidadMedidaBase').text(unsubproducto?.unidadmedida??'');\r\n        $('#unidadMedidaBase2').val(unsubproducto?.unidadmedida??'');\r\n\r\n        const unidadesDestino = allConversionUnidades.filter(c => c.idsubproducto === unsubproducto.id).map(c => c.idunidadmedidadestino);\r\n        allUnidadesMedida.forEach(u=>{\r\n          if(!unidadesDestino.includes(u.id)){\r\n            const option = document.createElement('option');\r\n            option.value = u.id;\r\n            option.textContent = u.nombre;\r\n            unidadesMedidas.appendChild(option);\r\n          }\r\n        });\r\n        imprimirConversionesUnidades(allConversionUnidades);\r\n        miDialogoConversionUnidad.showModal();\r\n      }\r\n\r\n\r\n      function imprimirConversionesUnidades(allConversionUnidades:conversionunidadesapi[]){\r\n        const subAllUnidades = allConversionUnidades.filter(z=>z.idsubproducto===unsubproducto.id);\r\n        contenedor.innerHTML = '';\r\n        subAllUnidades.forEach(conversion => {\r\n            contenedor.innerHTML += `\r\n                <div class=\"flex items-center justify-between p-3 mb-3 bg-white border border-slate-200 rounded-lg\">\r\n                    <div class=\"flex items-center gap-6 text-lg\">\r\n                        <span>\r\n                            <span class=\"font-medium text-slate-500\">Base:</span>\r\n                            <span class=\"text-slate-900 font-medium\">${conversion.factorconversion} ${conversion.nombreunidadbase}</span>\r\n                        </span>\r\n                        <span>\r\n                            <span class=\"font-medium text-slate-500\">Equivale A:</span>\r\n                            <span class=\"text-slate-900 font-medium\">1 ${conversion.nombreunidaddestino}</span>\r\n                        </span>\r\n                    </div>\r\n                    <button\r\n                        type=\"button\"\r\n                        data-id=\"${conversion.id}\"\r\n                        data-idunidadmedidadestino=\"${conversion.idunidadmedidadestino}\"\r\n                        data-nombreunidaddestino=\"${conversion.nombreunidaddestino}\"\r\n                        class=\"btn-eliminar px-3 py-1.5 text-base font-medium text-red-600 bg-red-50 border border-red-200 rounded-md hover:bg-red-100 hover:border-red-300 transition-colors\"\r\n                    >\r\n                        Eliminar\r\n                    </button>\r\n                </div>\r\n            `;\r\n        });\r\n      }\r\n\r\n\r\n      //ELIMINAR CONVERSION DE UNIDAD\r\n      contenedor.addEventListener('click', (e) => {\r\n          const target = e.target as HTMLElement;\r\n          if(target.classList.contains('btn-eliminar')){\r\n              const id = target.dataset.id; //id de la tabla conversionunidad\r\n              const idunidadmedidadestino = target.dataset.idunidadmedidadestino;\r\n              const nombreunidaddestino = target.dataset.nombreunidaddestino;\r\n              (async ()=>{\r\n                try {\r\n                  const url = \"/admin/api/almacen/eliminarConversionUnidad?id=\"+id; //llamado a la API REST para eliminar unidad de conversion\r\n                  const respuesta = await fetch(url); \r\n                  const resultado = await respuesta.json();\r\n                  if(resultado.exito !== undefined){\r\n                    msjAlert('exito', resultado.exito, document.querySelector('#divmsjalerta1')!);\r\n                    allConversionUnidades = allConversionUnidades.filter(conversion => conversion.id != id);\r\n                    imprimirConversionesUnidades(allConversionUnidades);\r\n                    //agregar la unidad de medida al select de unidades de medida\r\n                    const option = document.createElement('option');\r\n                    if(idunidadmedidadestino&&nombreunidaddestino){\r\n                      option.value = idunidadmedidadestino;\r\n                      option.textContent = nombreunidaddestino;\r\n                      unidadesMedidas.appendChild(option);\r\n                    }\r\n                  }else{\r\n                    msjAlert('error', resultado.error, document.querySelector('#divmsjalerta1')!);\r\n                  }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n              })();       \r\n          }\r\n      });\r\n\r\n  \r\n      ////////////////////  Actualizar conversion unidad de medida  //////////////////////\r\n      document.querySelector('#formConversionUnidad')?.addEventListener('submit', e=>{\r\n          e.preventDefault();\r\n          (async ()=>{ \r\n            const datos = new FormData();\r\n            datos.append('idsubproducto', unsubproducto.id);\r\n            datos.append('idunidadmedidabase', unsubproducto.id_unidadmedida);\r\n            datos.append('idunidadmedidadestino', $('#unidadesMedidas').val()as string);\r\n            datos.append('nombreunidadbase', unsubproducto.unidadmedida);\r\n            datos.append('nombreunidaddestino', $('#unidadesMedidas option:selected').text());\r\n             datos.append('factorconversion', factor.value??'0');\r\n            try {\r\n                const url = \"/admin/api/almacen/crearNuevaConversionUnidad\";\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                const resultado = await respuesta.json(); \r\n                if(resultado.exito !== undefined){\r\n                  msjAlert('exito', resultado.exito[0], document.querySelector('#divmsjalerta1')!);\r\n                  const nuevaConversion:conversionunidadesapi = resultado.newCv;\r\n                  allConversionUnidades.push(nuevaConversion);\r\n                  imprimirConversionesUnidades(allConversionUnidades);\r\n                  //eliminar del select de unidades de medida el option\r\n                  const option = unidadesMedidas.querySelector(`option[value=\"${nuevaConversion.idunidadmedidadestino}\"]`);\r\n                  option?.remove();\r\n                  factor.value = '';\r\n                }else{\r\n                  msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                }\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n          })();\r\n\r\n      });\r\n\r\n      \r\n      function cerrarDialogoExterno(event:Event) {\r\n        if (event.target === miDialogoConversionUnidad || (event.target as HTMLInputElement).value === 'Salir' || (event.target as HTMLInputElement).value === 'Actualizar')\r\n            miDialogoConversionUnidad.close();\r\n      }\r\n    }\r\n  \r\n  })();","(()=>{\r\n    \r\n    if(document.querySelector('.ensamblaje')){\r\n        const listaSubproductos = document.querySelector('.listaSubproductos');\r\n        //const subproducto:HTMLSelectElement = document.querySelector('#subproducto')!;\r\n        const selectUnidadMedida = document.querySelector('#unidadmedida')! as HTMLSelectElement;\r\n        let amount = document.querySelector('#cantidad') as HTMLInputElement; //input cantidad\r\n\r\n        type conversionunidadesapi = {\r\n            id:string,\r\n            idsubproducto: string,\r\n            idunidadmedidabase: string,\r\n            idunidadmedidadestino: string,\r\n            nombreunidadbase: string,\r\n            nombreunidaddestino: string,\r\n            factorconversion: string,\r\n            //idservicios:{idempleado:string, idservicio:string}[]\r\n          };\r\n\r\n        let allConversionUnidades:conversionunidadesapi[] = [], factorC = 0;\r\n\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/allConversionesUnidades\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas las conversiones de unidades\r\n                const respuesta = await fetch(url); \r\n                allConversionUnidades = await respuesta.json(); \r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n        \r\n        ($('#subproducto') as any).select2({\r\n            maximumSelectionLength: 1,\r\n        });\r\n\r\n\r\n        ////// EVENTO AL SUBPRODUCTO PARA CARGAR LAS UNIDADES DE MEDIDA EQUIVALENTES ////// \r\n        $(\"#subproducto\").on('change', (e)=>{\r\n            const idsub = (e.target as HTMLOptionElement).value;\r\n            const subund = allConversionUnidades.filter(x =>x.idsubproducto == idsub);\r\n            mostrarSelectUnidades(subund);\r\n        });\r\n\r\n        /////////// CARGAR LAS UNIDADES DE MEDIDA EN EL SELECT unidadmedida  ////////////\r\n        function mostrarSelectUnidades(subund:conversionunidadesapi[]):void{\r\n            while(selectUnidadMedida?.firstChild)selectUnidadMedida.removeChild(selectUnidadMedida?.firstChild);\r\n            subund.forEach(und =>{\r\n              const option = document.createElement('option');\r\n              option.textContent = und.nombreunidaddestino;\r\n              option.value = und.id;  //und.id  =  es el id de la tabla conversionunidades\r\n              //option.dataset.idunidadmedidabase = und.idunidadmedidabase;\r\n              //option.dataset.nombreunidadbase = und.nombreunidadbase;\r\n              selectUnidadMedida.appendChild(option);\r\n            });\r\n            calcularFactor();\r\n        }\r\n\r\n        ////////// EVENTO AL SELECT DE UNIDAD DE MEDIDA ///////////\r\n        selectUnidadMedida.addEventListener('change', calcularFactor);\r\n\r\n        (document.querySelector('#cantidad') as HTMLInputElement).addEventListener('input', (e:Event)=>{\r\n            calcularFactor();\r\n        });\r\n\r\n        function calcularFactor():void{\r\n            const idConversionUnidad:string|undefined = selectUnidadMedida.options[selectUnidadMedida.selectedIndex]?.value;\r\n            const reg = allConversionUnidades.find(x=>x.id == idConversionUnidad);\r\n            factorC = Number(reg?.factorconversion);\r\n        }\r\n\r\n        //////////////  EVENTO AL INPUT RENDIMIENTO ESTANDAR /////////////////\r\n        document.querySelector('#rendimientoestandar')?.addEventListener('input', (e:Event)=>{\r\n            const inputRendimiendoEstandar = (e.target as HTMLInputElement);\r\n            (async ()=>{ \r\n                const datos = new FormData();\r\n                datos.append('id', (document.querySelector('#idproducto') as HTMLInputElement).value);\r\n                datos.append('rendimientoestandar', inputRendimiendoEstandar.value);\r\n                try {\r\n                    const url = \"/admin/api/setrendimientoestandar\";\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                        inputRendimiendoEstandar.style.color = \"#02db02\";\r\n                        inputRendimiendoEstandar.style.fontWeight = \"500\";\r\n                    }else{\r\n                      msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n        \r\n        });\r\n\r\n        ///////////////// EVENTO AL FORMULARIO ASOCIAR SUBPRODUCTO //////////////////\r\n        document.querySelector('#formAddSubproducto')?.addEventListener('submit', (e)=>{\r\n            e.preventDefault();\r\n            const subproducto = $('#subproducto').find('option:selected');\r\n            const unidadmedida:string = $('#unidadmedida').find('option:selected').text();\r\n            const tipoGrupo = (document.querySelector('#tipoGrupo') as HTMLSelectElement)?.value || '0';\r\n            const marcadoDefecto = (document.querySelector('#marcadoDefecto') as HTMLSelectElement)?.value || '1';\r\n            const permitirAumentar = (document.querySelector('#permitirAumentar') as HTMLSelectElement)?.value || '1';\r\n            let AmountSubpx:number = factorC*Number(amount.value);\r\n            (async ()=>{ \r\n                const datos = new FormData();\r\n                datos.append('id_producto', (document.querySelector('#idproducto') as HTMLInputElement).value);\r\n                datos.append('id_subproducto', $('#subproducto').val()as string);\r\n                datos.append('cantidadsubproducto', AmountSubpx.toString());\r\n                datos.append('costo', (Number(subproducto.data('costo'))*AmountSubpx)+'');\r\n                datos.append('grupos_insumos', tipoGrupo);\r\n                datos.append('seleccionado', marcadoDefecto);\r\n                datos.append('permite_aumentar', permitirAumentar);\r\n                \r\n                try {\r\n                    const url = \"/admin/api/ensamblar\";  //asocia el producto con el sub producto en la tabla productos_sub\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                      msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                        /////validar si es el mismo subproducto, y actualizar \r\n                        validarSubproducto(\r\n                          $('#subproducto').val() as string,\r\n                          unidadmedida,\r\n                          subproducto.data('subproducto'),\r\n                          tipoGrupo,\r\n                          marcadoDefecto,\r\n                          permitirAumentar\r\n                        );\r\n                        ////// reset form ///////\r\n                        ($('#subproducto') as any).val([]).trigger('change');\r\n                        //$(`#subproducto option[value=\"${$('#subproducto').val()}\"]`).remove();\r\n                        (document.querySelector('#formAddSubproducto') as HTMLFormElement)?.reset();\r\n                    }else{\r\n                      msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();//cierre de async()\r\n        });\r\n\r\n\r\n        function validarSubproducto(idsubproducto:string, unidadmedida:string, subproducto:string, tipoGrupo:string, marcadoDefecto:string, permitirAumentar:string){\r\n            const tipoGrupoText = (document.querySelector(`#tipoGrupo option[value=\"${tipoGrupo}\"]`) as HTMLOptionElement)?.textContent?.trim() || tipoGrupo;\r\n            const sub = document.querySelector(`.listaSubproductos div[id=\"${idsubproducto}\"]`);\r\n            const detailsHtml = `\r\n                <div class=\"flex-1\">\r\n                    <div class=\"mb-3\">\r\n                        <p class=\"text-2xl font-semibold text-slate-800\">\r\n                            ${subproducto}\r\n                        </p>\r\n\r\n                        <p class=\"mt-2 text-indigo-600 font-semibold text-lg\">\r\n                            ${Number(amount.value).toFixed(2)} ${unidadmedida}\r\n                        </p>\r\n                    </div>\r\n\r\n                    <div class=\"mt-4 flex flex-wrap gap-4 text-lg\">\r\n                        <span class=\"rounded-md px-4 py-1.5 bg-slate-100 text-slate-700\">\r\n                            📦 Grupo: ${tipoGrupoText}\r\n                        </span>\r\n\r\n                        <span class=\"rounded-md px-4 py-1.5 font-medium ${\r\n                            marcadoDefecto == '1'\r\n                                ? 'bg-emerald-100 text-emerald-700'\r\n                                : 'bg-rose-100 text-rose-700'\r\n                        }\">\r\n                            ${\r\n                                marcadoDefecto == '1'\r\n                                    ? '✔ Seleccionado'\r\n                                    : '✖ No seleccionado'\r\n                            }\r\n                        </span>\r\n\r\n                        <span class=\"rounded-md px-4 py-1.5 font-medium ${\r\n                            permitirAumentar == '1'\r\n                                ? 'bg-indigo-100 text-indigo-700'\r\n                                : 'bg-amber-100 text-amber-700'\r\n                        }\">\r\n                            ${\r\n                                permitirAumentar == '1'\r\n                                    ? '➕ Permite aumentar'\r\n                                    : '🚫 Cantidad fija'\r\n                            }\r\n                        </span>\r\n                    </div>\r\n                </div>\r\n            `;\r\n            if(sub){\r\n                const button = sub.querySelector('button');\r\n                sub.innerHTML = detailsHtml;\r\n                if(button) sub.appendChild(button);\r\n            }else{\r\n                listaSubproductos?.insertAdjacentHTML('beforeend', `\r\n                <div id=\"${idsubproducto}\" class=\"mb-5 flex justify-between rounded-2xl border border-slate-200 bg-white p-4 shadow-sm hover:shadow-md transition-all duration-200 items-center\"  role=\"alert\">\r\n                    ${detailsHtml}\r\n                    <button\r\n                        type=\"button\"\r\n                        class=\"self-start mt-1 rounded-full p-2 text-slate-400 transition-all duration-200 hover:bg-red-100 hover:text-red-600\">\r\n\r\n                        <span\r\n                            id=\"${idsubproducto}\"\r\n                            class=\"material-symbols-outlined\">\r\n\r\n                            close\r\n                        </span>\r\n                    </button>\r\n                </div>`\r\n                );\r\n            }\r\n        }\r\n\r\n\r\n        listaSubproductos?.addEventListener('click', (e:Event)=>{\r\n            const btn = (e.target as HTMLSpanElement);\r\n            if(btn.tagName == \"SPAN\")desasociarSubproducto((document.querySelector('#idproducto') as HTMLInputElement).value, btn.id);\r\n        });\r\n\r\n\r\n        function desasociarSubproducto(idproducto:string, idsubproducto:string){\r\n            const sub = document.querySelector(`.listaSubproductos div[id=\"${idsubproducto}\"]`);\r\n            (async ()=>{\r\n                try {\r\n                  const url = \"/admin/api/desasociarsubproducto?idproducto=\"+idproducto+\"&idsubproducto=\"+idsubproducto; //llamado a la API REST para desasociar subproducto del producto principal\r\n                  const respuesta = await fetch(url); \r\n                  const resultado = await respuesta.json();\r\n                  if(resultado.exito !== undefined){\r\n                    sub?.remove();\r\n                    msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                  }else{\r\n                    msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                  }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n        }\r\n\r\n\r\n    }\r\n\r\n})();","(():void=>{\r\n  if(document.querySelector('.gestionproveedores')){\r\n    const crearProveedor = document.querySelector('#crearProveedor') as HTMLButtonElement;\r\n    const miDialogoProveedor = document.querySelector('#miDialogoProveedor') as any;\r\n\r\n    let indiceFila=0, control=0, tablaProveedores:HTMLElement;\r\n\r\n    type proveedoresapi = {\r\n        id:string,\r\n        nit: string,\r\n        nombre: string,\r\n        telefono: string,\r\n        email: string,\r\n        direccion: string,\r\n        pais: string,\r\n        ciudad: string,\r\n        created_at: string\r\n      };\r\n  \r\n      let proveedores:proveedoresapi[]=[], unproveedor:proveedoresapi|undefined;\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allproveedores\"; //llamado a la API REST y se trae todos los proveedores\r\n            const respuesta = await fetch(url); \r\n            proveedores = await respuesta.json(); \r\n            console.log(proveedores);\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n     //////////////////  TABLA //////////////////////\r\n    tablaProveedores = ($('#tablaProveedores') as any).DataTable(configdatatables);\r\n\r\n    crearProveedor.addEventListener('click', ()=>{\r\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalProveedor')!.textContent = \"Crear proveedor\";\r\n        (document.querySelector('#btnEditarCrearProveedor') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoProveedor.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    document.querySelector('#tablaProveedores')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarProveedor\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarProveedor\"))editarProveedor(e);\r\n      if(target?.classList.contains(\"eliminarProveedor\")||target.parentElement?.classList.contains(\"eliminarProveedor\"))eliminarProveedor(e);\r\n    });\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar proveedor  //////////////////////\r\n    function editarProveedor(e:Event){\r\n      let idproveedor = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idproveedor = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n      document.querySelector('#modalProveedor')!.textContent = \"Actualizar proveedor\";\r\n      (document.querySelector('#btnEditarCrearProveedor') as HTMLInputElement)!.value = \"Actualizar\";\r\n      \r\n      unproveedor = proveedores.find(x => x.id==idproveedor); //me trae a la proveedor seleccionada\r\n      (document.querySelector('#nit')as HTMLInputElement).value = unproveedor?.nit!;\r\n      (document.querySelector('#nombreProveedor')as HTMLInputElement).value = unproveedor?.nombre!;\r\n      \r\n      indiceFila = (tablaProveedores as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoProveedor.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar proveedor  //////////////////////\r\n    document.querySelector('#formCrearUpdateProveedor')?.addEventListener('submit', e=>{\r\n      let urlApi = \"crearProveedor\";\r\n      if(control)urlApi = \"actualizarProveedor\";\r\n\r\n        e.preventDefault();\r\n        var info = (tablaProveedores as any).page.info();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unproveedor?.id?unproveedor?.id:'');\r\n          datos.append('nit', $('#nit').val()as string);\r\n          datos.append('nombre', $('#nombreProveedor').val()as string);\r\n          try {\r\n              const url = \"/admin/api/\"+urlApi;\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                miDialogoProveedor.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                if(!control){ //si es crear registro\r\n                  /// actualizar el arregle de los proveedores ///\r\n                  proveedores = [...proveedores, resultado.proveedor];\r\n                  (tablaProveedores as any).row.add([\r\n                      (tablaProveedores as any).rows().count() + 1,\r\n                      resultado.proveedor.nit,\r\n                      resultado.proveedor.nombre,\r\n                      resultado.proveedor.created_at,\r\n                      `<div class=\"acciones-btns\" id=\"${resultado.proveedor.id}\" data-proveedor=\"${resultado.proveedor.nombre}\">\r\n                          <button class=\"btn-md btn-turquoise editarProveedor\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\r\n                          <button class=\"btn-md btn-red eliminarProveedor\"><i class=\"fa-solid fa-trash-can\"></i></button>\r\n                      </div>`\r\n                  ]).draw(false); // draw(false) evita recargar toda la tabla\r\n                }else{ //si es actualizar\r\n                  /// actualizar el arregle de proveedores ///\r\n                  proveedores.forEach(a=>{if(a.id == unproveedor?.id)a = Object.assign(a, resultado.proveedor[0]);});\r\n                  const datosActuales = (tablaProveedores as any).row(indiceFila+=info.start).data();\r\n                  /*NIT*/       datosActuales[1] = resultado.proveedor[0].nit;\r\n                  /*PROVEEDOR*/ datosActuales[2] = resultado.proveedor[0].nombre;\r\n                  (tablaProveedores as any).row(indiceFila).data(datosActuales).draw();\r\n                  (tablaProveedores as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                }\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar proveedor  //////////////////////\r\n    function eliminarProveedor(e:Event){\r\n      let idproveedor = (e.target as HTMLElement).parentElement!.id, info = (tablaProveedores as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idproveedor = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n      indiceFila = (tablaProveedores as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      Swal.fire({\r\n          customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n          icon: 'question',\r\n          title: 'Desea eliminar el proveedor?',\r\n          text: \"el proveedor sera eliminado definitivamente.\",\r\n          showCancelButton: true,\r\n          confirmButtonText: 'Si',\r\n          cancelButtonText: 'No',\r\n      }).then((result:any) => {\r\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idproveedor);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarProveedor\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                        (tablaProveedores as any).row(indiceFila).remove().draw(); \r\n                        (tablaProveedores as any).page(info.page).draw('page'); \r\n                        Swal.fire(resultado.exito[0], '', 'success')\r\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoProveedor || (event.target as HTMLInputElement).value === 'Salir') {\r\n          miDialogoProveedor.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateProveedor') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n  }\r\n\r\n})();","(()=>{\r\n  if(document.querySelector('.productos')){\r\n    const crearProducto = document.querySelector('#crearProducto');\r\n    const btnUploadExcel = document.querySelector('#btnUploadExcel');\r\n    const miDialogoProducto = document.querySelector('#miDialogoProducto') as any;\r\n    const miDialogoImportarExcel = document.querySelector('#miDialogoImportarExcel') as any;\r\n    const btnXCerrarModalproducto = document.querySelector('#btnXCerrarModalproducto') as HTMLButtonElement;\r\n    const inputupImage = document.querySelector('#upImage') as HTMLInputElement;  //input para cargar el archivo imagen\r\n    const btncustomUpImage = document.querySelector('#customUpImage');\r\n    const imginputfile = document.querySelector('#imginputfile') as HTMLImageElement;  //img\r\n    const tipoproducto = document.querySelector('#tipoproducto') as HTMLSelectElement;\r\n    const contentnuevosprecios = document.querySelector('#contentnuevosprecios') as HTMLElement;\r\n    let indiceFila=0, control=0, tablaProductos:HTMLElement;\r\n    \r\n\r\n    type productsapi = {\r\n      id:string,\r\n      idcategoria: string,\r\n      idunidadmedida: string,\r\n      nombre: string,\r\n      foto: string,\r\n      impuesto: string,\r\n      marca: string,\r\n      tipoproducto: string,\r\n      tipoproduccion: string,\r\n      sku: string,\r\n      unidadmedida: string;\r\n      descripcion: string,\r\n      peso: string,\r\n      medidas: string,\r\n      color: string,\r\n      funcion: string,\r\n      uso:string,\r\n      fabricante: string,\r\n      garantia: string,\r\n      stock: string,\r\n      stockminimo: string,\r\n      categoria: string,\r\n      precio_compra: string,\r\n      precio_venta: string,\r\n      percentcomision: string,\r\n      prioridadcomision: string,\r\n      fecha_ingreso: string,\r\n      preciosadicionales: {id:string, idproductoid:string, precio:string, estado:string, created_at:string}[]\r\n      //idservicios:{idempleado:string, idservicio:string}[]\r\n    };\r\n\r\n    let products:productsapi[]=[], unproducto:productsapi;\r\n\r\n    (async ()=>{\r\n      try {\r\n          const url = \"/admin/api/allproducts\"; //llamado a la API REST y se trae todos los productos\r\n          const respuesta = await fetch(url); \r\n          products = await respuesta.json(); \r\n          console.log(products);\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();\r\n\r\n    const divAlert = document.querySelector('.divmsjalerta0') as HTMLElement;\r\n    if(divAlert)borrarMsjAlert(divAlert);\r\n\r\n    ///////// Habilita el select precio de compra, y deshabilita el select de tipo de produccion si es producto simple, si es compuesto lo deshabilita y habilita el select de tipo de produccion\r\n    tipoproducto?.addEventListener('change', (e:Event)=>{\r\n      const targetDom = e.target as HTMLSelectElement;\r\n      const preciocompra = document.querySelector('.preciocompra') as HTMLElement;\r\n      const stock = document.querySelector('.stock') as HTMLElement;\r\n      const habtipoproduccion = document.querySelector('.habtipoproduccion') as HTMLElement;\r\n      if(targetDom.value == '0'){  //  0 = simple\r\n        stock.style.display = 'flex';\r\n        preciocompra.style.display = 'flex';\r\n        habtipoproduccion.style.display = \"none\";\r\n        document.querySelector('#preciocompra')?.setAttribute(\"required\", \"\");\r\n        document.querySelector('#tipoproduccion')?.removeAttribute(\"required\");\r\n      }\r\n      else{\r\n        stock.style.display = 'none';\r\n        preciocompra.style.display = 'none';\r\n        habtipoproduccion.style.display = \"flex\";\r\n        document.querySelector('#preciocompra')?.removeAttribute(\"required\");\r\n        document.querySelector('#tipoproduccion')?.setAttribute(\"required\", \"\");\r\n      }\r\n    });\r\n\r\n\r\n    btnXCerrarModalproducto.addEventListener('click', (e)=>{\r\n        miDialogoProducto.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    //AÑADOR INPUTS PARA PRECIOS PERSONALIZADOS\r\n    const btnAddNewPrice = document.querySelector('#btnAddNewPrice') as HTMLButtonElement;\r\n    if(btnAddNewPrice){\r\n        let i=1;\r\n        btnAddNewPrice.addEventListener('click', (e:Event)=>{\r\n          let clone = (e.target as HTMLButtonElement).previousElementSibling?.cloneNode(true) as HTMLInputElement;  \r\n          //console.log(clone.children[1].name = `niveles[nombrenivel${++i}]`);\r\n          clone.removeAttribute('id');\r\n          clone.required = false;\r\n          clone.value='';\r\n          clone.name = `nuevosprecios[]`;\r\n          clone.classList.add('nuevosprecios');\r\n          contentnuevosprecios.appendChild(clone);\r\n          console.log(clone);\r\n        });\r\n    }\r\n\r\n\r\n    btnUploadExcel?.addEventListener('click', ()=>{\r\n      miDialogoImportarExcel.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    //////////////////  TABLA //////////////////////\r\n    tablaProductos = ($('#tablaProductos') as any).DataTable(configdatatables);\r\n\r\n    //btn para crear producto\r\n    crearProducto?.addEventListener('click', (e):void=>{\r\n      control = 0;\r\n      limpiarformdialog();\r\n      while(contentnuevosprecios.firstChild)contentnuevosprecios.removeChild(contentnuevosprecios.firstChild);\r\n      document.querySelector('#modalProducto')!.textContent = \"Crear producto\";\r\n      (document.querySelector('#btnEditarCrearProducto') as HTMLInputElement).value = \"Crear\";\r\n      (document.querySelector('.stock')as HTMLInputElement).style.display = \"block\";\r\n      (document.querySelector('.preciocompra')as HTMLInputElement).style.display = \"block\";\r\n      miDialogoProducto.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    //evento a la tabla\r\n    document.querySelector('#tablaProductos')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarProductos\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarProductos\"))editarProductos(e);\r\n      if(target?.classList.contains(\"bloquearProductos\")||target.parentElement?.classList.contains(\"bloquearProductos\"))bloquearProductos(e);\r\n      if(target?.classList.contains(\"eliminarProductos\")||target.parentElement?.classList.contains(\"eliminarProductos\"))eliminarProductos(e);\r\n    });\r\n\r\n    function editarProductos(e:Event){\r\n      let idproducto = (e.target as HTMLElement).parentElement?.id!;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idproducto = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n      control = 1;\r\n      document.querySelector('#modalProducto')!.textContent = \"Actualizar producto\";\r\n      (document.querySelector('#btnEditarCrearProducto') as HTMLInputElement)!.value = \"Actualizar\";\r\n      unproducto = products.find(x=>x.id === idproducto)!; //obtengo el producto.\r\n      $('#categoria').val(unproducto?.idcategoria??'');\r\n      (document.querySelector('#nombre')as HTMLInputElement).value = unproducto?.nombre!;\r\n      $('#tipoproducto').val(unproducto?.tipoproducto??'0');  //0 = simple,  1 = compuesto\r\n      $('#idunidadmedida').val(unproducto?.idunidadmedida??'1');\r\n      (document.querySelector('.stock')as HTMLInputElement).style.display = \"block\";\r\n      (document.querySelector('.preciocompra')as HTMLInputElement).style.display = \"block\";\r\n      (document.querySelector('.habtipoproduccion') as HTMLElement).style.display = \"none\";\r\n      if(unproducto?.tipoproducto == '1'){\r\n        (document.querySelector('.stock')as HTMLInputElement).style.display = \"none\";\r\n        (document.querySelector('.preciocompra')as HTMLInputElement).style.display = \"none\";\r\n        (document.querySelector('.habtipoproduccion') as HTMLElement).style.display = \"block\";\r\n        $('#tipoproduccion').val(unproducto.tipoproduccion);\r\n      }\r\n      (document.querySelector('#stock')as HTMLInputElement).value = unproducto?.stock??'';\r\n      (document.querySelector('#preciocompra')as HTMLInputElement).value = unproducto?.precio_compra??'';\r\n      (document.querySelector('#precioventa')as HTMLInputElement).value = unproducto?.precio_venta??'';\r\n      (document.querySelector('#precioventa')as HTMLInputElement).dataset.idproductoid = unproducto.id;\r\n      (document.querySelector('#percentcomision')as HTMLInputElement).value = unproducto.percentcomision;\r\n      (document.querySelector('#prioridadcomision')as HTMLInputElement).value = unproducto.prioridadcomision;\r\n      imprimirpreciosadicionales(unproducto.preciosadicionales);\r\n      (document.querySelector('#sku')as HTMLInputElement).value = unproducto?.sku??'';\r\n      (document.querySelector('#impuesto')as HTMLInputElement).value = unproducto?.impuesto??'';\r\n      (document.querySelector('#stockminimo')as HTMLInputElement).value = unproducto?.stockminimo??'';\r\n      imginputfile.src = \"/build/img/\"+unproducto?.foto;\r\n      indiceFila = (tablaProductos as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoProducto.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    function imprimirpreciosadicionales(preciosadicionales:{id:string, idproductoid:string, precio:string, estado:string, created_at:string}[]){\r\n      while(contentnuevosprecios.firstChild)contentnuevosprecios.removeChild(contentnuevosprecios.firstChild);\r\n      preciosadicionales.forEach(z =>{\r\n        contentnuevosprecios.insertAdjacentHTML('afterbegin', `<input \r\n          data-id=\"${z.id}\"\r\n          class=\"nuevosprecios bg-gray-50 border border-gray-300 text-gray-900 rounded-lg focus:border-indigo-600 block w-full p-2.5 dark:bg-gray-600 dark:border-gray-500 dark:placeholder-gray-400 dark:text-white h-14 text-xl focus:outline-none focus:ring-1\"\r\n          type=\"number\" \r\n          min=\"0\" \r\n          step=\"0.01\"\r\n          placeholder=\"Precio de venta incluido el impuesto\" \r\n          name=\"nuevosprecios[]\" \r\n          value=\"${z.precio}\" \r\n          >`);\r\n      });\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar producto  //////////////////////\r\n    document.querySelector('#formCrearUpdateProducto')?.addEventListener('submit', e=>{\r\n\r\n      let w = document.querySelectorAll<HTMLInputElement>('.nuevosprecios');\r\n      //console.log(Array.from(w).map(input=>({id: input.dataset.id, precio: parseFloat(input.value) })).filter(x=>x.precio>0));\r\n      if(control){\r\n        e.preventDefault();\r\n        var imgFile:(string|File), info = (tablaProductos as any).page.info();\r\n        imgFile=unproducto.foto;\r\n        if(!imginputfile.src.includes(unproducto.foto)){ //se lee la etiqueta img para cambio de imagen\r\n          imgFile = ((e.target as HTMLFormElement).elements.namedItem(\"upImage\") as HTMLInputElement).files?.[0]!; //obtengo el archivo\r\n          if(imgFile){\r\n            if(imgFile.type!==\"image/png\"&&imgFile.type!==\"image/jpeg\"){\r\n              msjAlert('error', 'No es un formato valido para la foto', (document.querySelector('#divmsjalerta1') as HTMLElement));\r\n              return;\r\n            }\r\n            if(imgFile.size>31000000){ //si es mayor a 31MB\r\n              msjAlert('error', 'La imagen no debe superar los 500KB', document.querySelector('#divmsjalerta1')!);\r\n              return;\r\n            }\r\n          }\r\n        }\r\n        (async ()=>{\r\n          const datos = new FormData();\r\n          datos.append('id', unproducto!.id);\r\n          datos.append('idcategoria', $('#categoria').val()as string);\r\n          datos.append('nombre', $('#nombre').val()as string);\r\n          datos.append('foto', imgFile); //en el backend no se lee con $_POST, se lee con $_FILES\r\n          datos.append('tipoproducto', $('#tipoproducto').val()as string);  //0=simple o 1=compuesto\r\n          datos.append('idunidadmedida', $('#idunidadmedida').val()as string);\r\n          datos.append('unidadmedida', $('#idunidadmedida option:selected').text());\r\n          datos.append('stock', $('#stock').val()as string);\r\n          datos.append('precio_compra', $('#preciocompra').val()as string);\r\n          datos.append('precio_venta', $('#precioventa').val()as string);\r\n          datos.append('nuevosprecios', JSON.stringify(Array.from(w).map(input=>({id: input.dataset.id, idproductoid: input.dataset.idproductoid, precio: parseFloat(input.value), estado:1 })).filter(x=>x.precio>=0)));\r\n          datos.append('idprecionsadicionales', JSON.stringify(Array.from(w).filter(input => input.dataset.id && parseFloat(input.value) > 0).map( input=>input.dataset.id ))); //solo los ids de la tabla precios_personalizados\r\n          datos.append('sku', $('#sku').val()as string);\r\n          datos.append('tipoproduccion', ($('#tipoproduccion').val()as string)==null?'0':($('#tipoproduccion').val()as string));\r\n          datos.append('impuesto', $('#impuesto').val()as string);\r\n          datos.append('stockminimo', $('#stockminimo').val()as string);\r\n          datos.append('percentcomision', $('#percentcomision').val()as string);\r\n          datos.append('prioridadcomision', $('#prioridadcomision').val() as string);\r\n          try {\r\n              const url = \"/admin/api/actualizarproducto\";\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json(); \r\n              console.log(resultado); \r\n              if(resultado.exito !== undefined){\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                /// actualizar el arregle del producto ///\r\n                products.forEach(a=>{if(a.id == unproducto.id)a = Object.assign(a, resultado.producto[0]);});\r\n                ///////// cambiar la fila completa, su contenido //////////\r\n                const datosActuales = (tablaProductos as any).row(indiceFila).data();\r\n                /*img*/datosActuales[1] = `<div class=\"text-center\"><img class=\"inline\" style=\"width: 50px;\" src=\"/build/img/${resultado.producto[0].foto}\" alt=\"\"></div>`;\r\n                /*NOMBRE*/datosActuales[2] ='<div class=\"w-80 whitespace-normal\">'+$('#nombre').val()+'</div>';\r\n                /*CATEGORIA*/datosActuales[3] = $('#categoria option:selected').text();\r\n                /*MARCA*/datosActuales[4] = '';\r\n                /*CODIGO*/datosActuales[5] = $('#sku').val();\r\n                /*PRECIOVENTA*/datosActuales[6] = $('#precioventa').val();\r\n                \r\n                (tablaProductos as any).row(indiceFila).data(datosActuales).draw();\r\n                (tablaProductos as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n              miDialogoProducto.close();\r\n              document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n      } //fin if(control)\r\n    });\r\n\r\n\r\n    function bloquearProductos(e:Event){\r\n      let reg = (e.target as HTMLElement).parentElement, info = (tablaProductos as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'SPAN')reg = (e.target as HTMLElement).parentElement!.parentElement;\r\n      indiceFila = (tablaProductos as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      (async ()=>{\r\n\r\n          const datos = new FormData();\r\n          datos.append('id', reg!.id);\r\n          try {\r\n              const url = \"/admin/api/cambiarestadoproducto\";\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                \r\n                const s1 = `<div class=\"acciones-btns my-[0.7rem]\" id=\"${reg!.id}\">\r\n                              ${resultado.tipoproducto[0] == 1?`<a class=\"btn-xs btn-blue\" title=\"Agregar Materia Prima\" href=\"/admin/almacen/componer?id=${reg!.id}\"><i class=\"fa-solid fa-subscript text-[17px] leading-none\"></i></a>`:''}\r\n                              <button class=\"btn-xs btn-lima\" title=\"Más opciones\"><i class=\"fa-solid fa-circle-plus text-[17px] leading-none\"></i></button>\r\n                              <button class=\"btn-xs btn-turquoise editarProductos\" title=\"Actualizar Producto\"><i class=\"fa-solid fa-pen-to-square text-[17px] leading-none\"></i></button>\r\n                              <button class=\"btn-xs ${resultado.estado[0]==1?'btn-light':'btn-orange'} bloquearProductos\" title=\"Bloquear Producto\"><span class=\"material-symbols-outlined text-[18px] leading-none\">hide_source</span></button>\r\n                              <button class=\"btn-xs btn-red eliminarProductos\" title=\"Eliminar Producto\"><i class=\"fa-solid fa-trash-can text-[17px] leading-none\"></i></button>\r\n                            </div>`;\r\n                            \r\n                (tablaProductos as any).cell((tablaProductos as any).row(indiceFila), 7).data(s1).draw(); //se modifica solo la columna con la fila correspondiente, y destruye la que habai antes\r\n                (tablaProductos as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n              }else{\r\n                  Swal.fire(resultado.error[0], '', 'error')\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n      })();\r\n    }\r\n\r\n    function eliminarProductos(e:Event){\r\n      let idproducto = (e.target as HTMLElement).parentElement!.id, info = (tablaProductos as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idproducto = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n      indiceFila = (tablaProductos as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      Swal.fire({\r\n          customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n          icon: 'question',\r\n          title: 'Desea eliminar el prducto?',\r\n          text: \"El prducto sera eliminado definitivamente de todas las SEDES.\",\r\n          showCancelButton: true,\r\n          confirmButtonText: 'Si',\r\n          cancelButtonText: 'No',\r\n      }).then((result:any) => {\r\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idproducto);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarProducto\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                        (tablaProductos as any).row(indiceFila).remove().draw(); \r\n                        (tablaProductos as any).page(info.page).draw('page');\r\n                        Swal.fire(resultado.exito[0], '', 'success') \r\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    //////////////////// Cargar imagen como preview  //////////////////////\r\n    btncustomUpImage?.addEventListener('click', ()=>inputupImage?.click());\r\n    inputupImage?.addEventListener('change', function(){\r\n      const file = this.files?.[0];\r\n      if(file){\r\n        const reader = new FileReader();\r\n        reader.onload = function(){\r\n          const resrult = reader.result;\r\n          if(typeof resrult == \"string\")imginputfile.src = resrult;\r\n        } \r\n        reader.readAsDataURL(file);\r\n      }\r\n    });\r\n\r\n    function limpiarformdialog():void{\r\n      (document.querySelector('#formCrearUpdateProducto') as HTMLFormElement)?.reset();\r\n      imginputfile.src = '';\r\n    }\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoImportarExcel || (event.target as HTMLInputElement).value === 'salir' || (event.target as HTMLInputElement).value === 'Cancelar') {\r\n        miDialogoProducto.close();\r\n        miDialogoImportarExcel.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n  }\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.subproductos')){\r\n      const crearSubProducto = document.querySelector('#crearSubProducto');\r\n      const btnUploadExcel = document.querySelector('#btnUploadExcel');\r\n      const miDialogoSubProducto = document.querySelector('#miDialogoSubProducto') as any;\r\n      const miDialogoImportarExcel = document.querySelector('#miDialogoImportarExcel') as HTMLDialogElement;\r\n      let indiceFila=0, control=0, tablaSubProductos:HTMLElement;\r\n      \r\n      type subproductsapi = {\r\n        id:string,\r\n        id_unidadmedida: string,\r\n        unidadmedida: string,\r\n        nombre: string,\r\n        sku: string,\r\n        proveedor: string,\r\n        descripcion: string,\r\n        medidas: string,\r\n        color: string,\r\n        uso:string,\r\n        stock: string,\r\n        stockminimo: string,\r\n        precio_compra: string,\r\n        fecha_ingreso: string,\r\n      };\r\n  \r\n      let subproducts:subproductsapi[]=[], unsubproducto:subproductsapi;\r\n  \r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allsubproducts\"; //llamado a la API REST\r\n            const respuesta = await fetch(url); \r\n            subproducts = await respuesta.json(); \r\n            console.log(subproducts);\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n      \r\n      btnUploadExcel?.addEventListener('click', ()=>{\r\n        miDialogoImportarExcel.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      });\r\n  \r\n      //////////////////  TABLA //////////////////////\r\n      tablaSubProductos = ($('#tablaSubProductos') as any).DataTable(configdatatables);\r\n  \r\n      crearSubProducto?.addEventListener('click', (e):void=>{\r\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalSubProducto')!.textContent = \"Crear insumo\";\r\n        (document.querySelector('#btnEditarCrearSubProducto') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoSubProducto.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      });\r\n  \r\n      ///////////// EVENTOS A LA TABLA SUBPRODUCTOS /////////////\r\n      document.querySelector('#tablaSubProductos')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n        const target = e.target as HTMLElement;\r\n        if(target?.classList.contains(\"editarSubProductos\")||target.parentElement?.classList.contains(\"editarSubProductos\"))editarSubProductos(e);\r\n        if(target?.classList.contains(\"eliminarSubProductos\")||target.parentElement?.classList.contains(\"eliminarSubProductos\"))eliminarSubProductos(e);\r\n      });\r\n  \r\n      function editarSubProductos(e:Event){\r\n        let idsubproducto = (e.target as HTMLElement).parentElement?.id!;\r\n        if((e.target as HTMLElement)?.tagName === 'I')idsubproducto = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n        control = 1;\r\n        document.querySelector('#modalSubProducto')!.textContent = \"Actualizar insumo\";\r\n        (document.querySelector('#btnEditarCrearSubProducto') as HTMLInputElement)!.value = \"Actualizar\";\r\n        unsubproducto = subproducts.find(x=>x.id === idsubproducto)!;\r\n        $('#unidadmedida').val(unsubproducto?.id_unidadmedida??'');\r\n        (document.querySelector('#nombre')as HTMLInputElement).value = unsubproducto?.nombre!;\r\n        (document.querySelector('#sku')as HTMLInputElement).value = unsubproducto?.sku!;\r\n        (document.querySelector('#preciocompra')as HTMLInputElement).value = unsubproducto?.precio_compra??'';\r\n        (document.querySelector('#stockminimo')as HTMLInputElement).value = unsubproducto?.stockminimo??'';\r\n        \r\n        indiceFila = (tablaSubProductos as any).row((e.target as HTMLElement).closest('tr')).index();\r\n        miDialogoSubProducto.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n  \r\n      ////////////////////  Actualizar/Editar producto  //////////////////////\r\n      document.querySelector('#formCrearUpdateSubProducto')?.addEventListener('submit', e=>{\r\n        if(control){\r\n          e.preventDefault();\r\n          var info = (tablaSubProductos as any).page.info();\r\n          \r\n          (async ()=>{ \r\n            const datos = new FormData();\r\n            datos.append('id', unsubproducto!.id);\r\n            datos.append('id_unidadmedida', $('#unidadmedida').val()as string);\r\n            datos.append('unidadmedida', $('#unidadmedida').find('option:selected').text());\r\n            datos.append('nombre', $('#nombre').val()as string);\r\n            datos.append('sku', $('#sku').val()as string);\r\n            datos.append('precio_compra', $('#preciocompra').val()as string);\r\n             datos.append('stockminimo', $('#stockminimo').val()as string);\r\n            try {\r\n                const url = \"/admin/api/actualizarsubproducto\";\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                const resultado = await respuesta.json(); \r\n                console.log(resultado); \r\n                if(resultado.exito !== undefined){\r\n                  msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                  /// actualizar el arregle del subproducto ///\r\n                  subproducts.forEach(a=>{if(a.id == unsubproducto.id)a = Object.assign(a, resultado.subproducto[0]);});\r\n                  ///////// cambiar la fila completa, su contenido //////////\r\n                  const datosActuales = (tablaSubProductos as any).row(indiceFila+=info.start).data();\r\n                  /*NOMBRE*/datosActuales[1] ='<div class=\"w-80 whitespace-normal\">'+$('#nombre').val()+'</div>';\r\n                  /*proveedor*/datosActuales[2] = '';\r\n                  /*SKU*/datosActuales[3] = $('#sku').val();\r\n                  /*UNIDADMEDIDA*/datosActuales[4] = $('#unidadmedida option:selected').text();\r\n                  /*PRECIOCOMPRA*/datosActuales[5] = '$'+Number($('#preciocompra').val())?.toLocaleString();\r\n                  (tablaSubProductos as any).row(indiceFila).data(datosActuales).draw();\r\n                  (tablaSubProductos as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                }else{\r\n                  msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                }\r\n                document.addEventListener(\"click\", cerrarDialogoExterno);\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n          })();//cierre de async()\r\n        } //fin if(control)\r\n      });\r\n  \r\n      function eliminarSubProductos(e:Event){\r\n        let idsubproducto = (e.target as HTMLElement).parentElement!.id, info = (tablaSubProductos as any).page.info();\r\n        if((e.target as HTMLElement).tagName === 'I')idsubproducto = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n        indiceFila = (tablaSubProductos as any).row((e.target as HTMLElement).closest('tr')).index();\r\n        Swal.fire({\r\n            customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n            icon: 'question',\r\n            title: 'Desea eliminar el insumo?',\r\n            text: \"El insumo sera eliminado definitivamente.\",\r\n            showCancelButton: true,\r\n            confirmButtonText: 'Si',\r\n            cancelButtonText: 'No',\r\n        }).then((result:any) => {\r\n            if (result.isConfirmed) {\r\n                (async ()=>{ \r\n                    const datos = new FormData();\r\n                    datos.append('id', idsubproducto);\r\n                    try {\r\n                        const url = \"/admin/api/eliminarSubProducto\";\r\n                        const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                        const resultado = await respuesta.json();  \r\n                        if(resultado.exito !== undefined){\r\n                          (tablaSubProductos as any).row(indiceFila).remove().draw(); \r\n                          (tablaSubProductos as any).page(info.page).draw('page');\r\n                          Swal.fire(resultado.exito[0], '', 'success') \r\n                        }else{\r\n                            Swal.fire(resultado.error[0], '', 'error')\r\n                        }\r\n                    } catch (error) {\r\n                        console.log(error);\r\n                    }\r\n                })();//cierre de async()\r\n            }\r\n        });\r\n      }\r\n\r\n  \r\n      function limpiarformdialog(){\r\n        (document.querySelector('#formCrearUpdateSubProducto') as HTMLFormElement)?.reset();\r\n        (document.querySelector('#formCrearUpdateSubProducto') as HTMLFormElement).action = \"/admin/almacen/crear_subproducto\";\r\n      }\r\n      function cerrarDialogoExterno(event:Event) {\r\n        const f = event.target;\r\n        if (f === miDialogoSubProducto || f === miDialogoImportarExcel || (f as HTMLInputElement).value === 'Cancelar' || (f as HTMLInputElement).value === 'salir' || (f as HTMLInputElement).value === 'Actualizar') {\r\n            miDialogoSubProducto.close();\r\n            miDialogoImportarExcel.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n      }\r\n    }\r\n  \r\n  })();","(()=>{\r\n\r\n    if(document.querySelector('.unidadesmedida')){\r\n        const btnCrearUnidadMedida = document.querySelector('#btnCrearUnidadMedida');\r\n        const miDialogoUnidadMedida = document.querySelector('#miDialogoUnidadMedida') as any;\r\n        let tablaUnidadesMedida:HTMLElement;\r\n\r\n        tablaUnidadesMedida = ($('#tablaUnidadesMedida') as any).DataTable(configdatatables);\r\n\r\n        ///////////////BTN PARA CREAR UNIDAD DE MEDIDA////////////////\r\n        btnCrearUnidadMedida?.addEventListener('click', (e):void=>{\r\n            limpiarformdialog();\r\n            document.querySelector('#modalUnidadMedida')!.textContent = \"Crear unidad de medida\";\r\n            (document.querySelector('#btnEditarCrearUnidadMedida') as HTMLInputElement).value = \"Crear\";\r\n            miDialogoUnidadMedida.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        });\r\n\r\n        document.querySelector('#tablaUnidadesMedida')?.addEventListener('click', (e:Event)=>{\r\n            var btn = e.target as HTMLElement;\r\n            if(btn?.classList.contains('editarUnidadMedida')||btn.parentElement?.classList.contains(\"editarUnidadMedida\"))editarUnidadMedida(e);\r\n            if(btn?.classList.contains('eliminarUnidadMedida')||btn.parentElement?.classList.contains(\"eliminarUnidadMedida\"))eliminarUnidadMedida(e);   \r\n        });\r\n\r\n\r\n        ///////////////EDITAR UNIDAD DE MEDIDA////////////////\r\n        function editarUnidadMedida(e:Event){\r\n            let idunidadmedida = (e.target as HTMLElement).parentElement?.id!;\r\n            if((e.target as HTMLElement)?.tagName === 'I')idunidadmedida = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n            (document.querySelector('#formCrearUpdateUnidad') as HTMLFormElement).action = \"/admin/almacen/editarunidademedida\";\r\n            document.querySelector('#modalUnidadMedida')!.textContent = \"Actualizar unidad de medida\";\r\n            (document.querySelector('#btnEditarCrearUnidadMedida') as HTMLInputElement)!.value = \"Actualizar\";\r\n            (document.querySelector('#idunidadmedida') as HTMLInputElement).value = idunidadmedida;\r\n            (document.querySelector('#unidad') as HTMLInputElement).value = ((e.target as HTMLElement).closest('.acciones-btns') as HTMLElement)?.dataset.unidadmedida!; \r\n            miDialogoUnidadMedida.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n\r\n\r\n        function eliminarUnidadMedida(e:Event):void{\r\n            let form = (e.target as HTMLElement).parentElement!;\r\n            if((e.target as HTMLElement).tagName === 'I')form = form.parentElement!;\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea eliminar la unidad de medida?',\r\n                text: \"La unidad de medida sera eliminado definitivamente.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed)(form as HTMLFormElement).submit();\r\n            });\r\n        }\r\n\r\n        /*document.querySelector('.eliminarUnidadMedida')?.addEventListener('submit', (e:Event)=>{\r\n            console.log(55);\r\n            e.preventDefault();\r\n        });*/\r\n\r\n        /*function eliminarUnidadMedida(e:Event):void{\r\n            let idunidadmedida = (e.target as HTMLElement).parentElement?.id!;\r\n            if((e.target as HTMLElement)?.tagName === 'I')idunidadmedida = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n            console.log(idunidadmedida);\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea eliminar la unidad de medida?',\r\n                text: \"La unidad de medida sera eliminado definitivamente.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {*/\r\n                    /*(async ()=>{ \r\n                        const datos = new FormData();\r\n                        datos.append('id', idproducto);\r\n                        try {\r\n                            const url = \"/admin/api/eliminarProducto\";\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                            const resultado = await respuesta.json();  \r\n                            if(resultado.exito !== undefined){\r\n                              (tablaProductos as any).row(indiceFila+info.start).remove().draw(); \r\n                              (tablaProductos as any).page(info.page).draw('page');\r\n                              Swal.fire(resultado.exito[0], '', 'success') \r\n                            }else{\r\n                                Swal.fire(resultado.error[0], '', 'error')\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();*///cierre de async()\r\n                /*}\r\n            });\r\n        }*/\r\n        \r\n        function limpiarformdialog(){\r\n            (document.querySelector('#formCrearUpdateUnidad') as HTMLFormElement)?.reset();\r\n            (document.querySelector('#formCrearUpdateUnidad') as HTMLFormElement).action = \"/admin/almacen/crear_unidadmedida\";\r\n        }\r\n\r\n        function cerrarDialogoExterno(event:Event) {\r\n            const f = event.target;\r\n        if (f === miDialogoUnidadMedida || (f as HTMLInputElement).value === 'Salir' || (f as HTMLInputElement).value === 'Actualizar') {\r\n            miDialogoUnidadMedida.close();\r\n            document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n        }\r\n    }\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.clientes')){\r\n      const btncrearCliente = document.querySelector('#crearCliente');\r\n      const btncrearDireccion = document.querySelector('#crearDireccion');\r\n      const miDialogoCliente = document.querySelector('#miDialogoCliente') as any;\r\n      const miDialogoCrearDireccion = document.querySelector('#miDialogoCrearDireccion') as any;\r\n      const miDialogoUpDireccion = document.querySelector('#miDialogoUpDireccion') as any;\r\n      const selectdirecciones = document.querySelector('#selectdirecciones') as HTMLSelectElement;\r\n      const btnCerrarUpDireccion = document.querySelector('#btnCerrarUpDireccion') as HTMLButtonElement;\r\n      let select2Init = false, indiceFila=0, control=0, tablaClientes:HTMLElement, filaClienteActual:any = null;\n      \r\n      type direccionesapi = {\r\n        id:string,\r\n        idcliente:string,\r\n        idtarifa:string,\r\n        tarifa:{id:string, idcliente:string, nombre:string, valor:string},\r\n        direccion:string,\r\n        ciudad:string,\r\n        departamento:string\r\n      };\r\n      let direcciones:direccionesapi[]=[];\r\n  \r\n      type clientesapi = {\r\n        id:string,\r\n        nombre: string,\r\n        apellido: string,\r\n        tipodocumento: string,\r\n        identificacion: string,\r\n        telefono: string,\r\n        email: string,\r\n        fecha_nacimiento: string,\r\n        total_compras: string,\r\n        ultima_compra: string;\r\n        data1: string,\r\n        //idservicios:{idempleado:string, idservicio:string}[]\r\n      };\r\n  \r\n      let clientes:clientesapi[]=[], uncliente:clientesapi;\r\n  \r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allclientes\"; //llamado a la API REST y se trae todos los productos\r\n            const respuesta = await fetch(url); \r\n            clientes = await respuesta.json(); \r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n  \r\n      \r\n  \r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\n      //////////////////  TABLA //////////////////////\n      tablaClientes = ($('#tablaClientes') as any).DataTable({\n        ...configdatatables,\n        dom: 'rtip',\n        order: [[0, 'desc']]\n      });\n      modernizarToolbarDataTable('#tablaClientes');\n      ocultarToolbarNativoClientes();\n      ($('#tablaClientes') as any).on('draw.dt', ocultarToolbarNativoClientes);\n  \n      btncrearCliente?.addEventListener('click', (e):void=>{\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalCliente')!.textContent = \"Crear cliente\";\r\n        (document.querySelector('#btnEditarCrearCliente') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoCliente.showModal();\r\n      });\r\n\r\n\r\n      btncrearDireccion?.addEventListener('click', (e):void=>{\r\n        control = 0;\r\n        document.querySelector('#modalDireccion')!.textContent = \"Crear direccion\";\r\n        (document.querySelector('#btnEditarCrearDireccion') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoCrearDireccion.showModal();\r\n        activarSelect2();\r\n      });\r\n\r\n\r\n      function activarSelect2(){\r\n        if(select2Init)return;\r\n        ($('#selectcliente') as any).select2({\n          dropdownParent: $('#miDialogoCrearDireccion'),\n          placeholder: \"Seleccionar el cliente\",\n          minimumResultsForSearch: Infinity,\n          width: '100%'\n        });\n        select2Init = true;\r\n      }\r\n  \r\n      document.querySelector('#tablaClientes')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n        const target = e.target as HTMLElement;\r\n        if((e.target as HTMLElement)?.classList.contains(\"editarClientes\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarClientes\"))editarClientes(e);\r\n        if(target?.classList.contains(\"eliminarClientes\")||target.parentElement?.classList.contains(\"eliminarClientes\"))eliminarClientes(e);\r\n        if(target?.classList.contains(\"editarEliminarDireccion\")||target.parentElement?.classList.contains(\"editarEliminarDireccion\"))upRemoveDir(e);\r\n      });\r\n  \r\n      function editarClientes(e:Event){\n        const target = e.target as HTMLElement;\n        let idcliente = target.parentElement?.id!;\n        if(target?.tagName === 'I')idcliente = target.parentElement?.parentElement?.id!;\n        const currentRow = target.closest('tr');\n        const dataRow = currentRow?.classList.contains('child') ? currentRow.previousElementSibling : currentRow;\n        filaClienteActual = (tablaClientes as any).row(dataRow);\n        indiceFila = filaClienteActual.index();\n        control = 1;\n        document.querySelector('#modalCliente')!.textContent = \"Actualizar cliente\";\n        (document.querySelector('#btnEditarCrearCliente') as HTMLInputElement)!.value = \"Actualizar\";\n        uncliente = clientes.find(x=>x.id === idcliente)!;\r\n        (document.querySelector('#nombre')as HTMLInputElement).value = uncliente?.nombre!;\r\n        (document.querySelector('#apellido')as HTMLInputElement).value = uncliente?.apellido!;\r\n        $('#tipodocumento').val(uncliente?.tipodocumento??'');\r\n        (document.querySelector('#identificacion')as HTMLInputElement).value = uncliente?.identificacion??'';\r\n        (document.querySelector('#telefono')as HTMLInputElement).value = uncliente?.telefono??'';\r\n        (document.querySelector('#email')as HTMLInputElement).value = uncliente?.email??'';\r\n        (document.querySelector('#fecha_nacimiento')as HTMLInputElement).value = uncliente?.fecha_nacimiento??'';\r\n        \r\n        miDialogoCliente.showModal();\r\n      }\r\n  \r\n      ////////////////////  Actualizar/Editar clientes  //////////////////////\r\n      document.querySelector('#formCrearUpdateCliente')?.addEventListener('submit', e=>{\r\n        if(control){\r\n          e.preventDefault();\r\n          var info = (tablaClientes as any).page.info();\r\n          \r\n          (async ()=>{ \r\n            const datos = new FormData();\r\n            datos.append('idcliente', uncliente!.id);\r\n            datos.append('nombre', $('#nombre').val()as string);\r\n            datos.append('apellido', $('#apellido').val()as string);\r\n            datos.append('tipodocumento', $('#tipodocumento').val()as string);\r\n            datos.append('identificacion', $('#identificacion').val()as string);\r\n            datos.append('telefono', $('#telefono').val()as string);\r\n            datos.append('email', $('#email').val()as string);\r\n            datos.append('fecha_nacimiento', $('#fecha_nacimiento').val()as string);\r\n            try {\r\n                const url = \"/admin/api/actualizarCliente\";\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                const resultado = await respuesta.json(); \r\n                if(resultado.exito !== undefined){\r\n                  msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                  /// actualizar el arreglo de clientes ///\n                  clientes = clientes.map(a => a.id == uncliente.id ? Object.assign(a, resultado.cliente?.[0] ?? {}) : a);\n                  ///////// cambiar la fila completa, su contenido //////////\n                  const filaApi = filaClienteActual || (tablaClientes as any).row(indiceFila);\n                  const datosActuales = filaApi.data();\n                  const nombre = ($('#nombre').val() as string) || '';\n                  const apellido = ($('#apellido').val() as string) || '';\n                  const identificacion = ($('#identificacion').val() as string) || '';\n                  const telefono = ($('#telefono').val() as string) || '';\n                  const email = ($('#email').val() as string) || '';\n                  filaApi.data(renderClienteRowData({\n                    id: uncliente.id,\n                    identificacion,\n                    nombre,\n                    apellido,\n                    telefono,\n                    email,\n                    acciones: datosActuales[6]\n                  })).draw(false);\n                  (tablaClientes as any).page(info.page).draw(false); //me mantiene la pagina actual\n                  try {\n                    (tablaClientes as any).columns.adjust().responsive.recalc();\n                  } catch (error) {\n                    console.log(error);\n                  }\n                }else{\r\n                  msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                }\r\n                miDialogoCliente.close();\n                filaClienteActual = null;\n                \r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n          })();//cierre de async()\r\n        } //fin if(control)\r\n      });\r\n  \r\n\r\n      function upRemoveDir(e:Event){ //actualizar o eliminar direccion\r\n        let idcliente = (e.target as HTMLElement).parentElement!.id, info = (tablaClientes as any).page.info();\r\n        if((e.target as HTMLElement).tagName === 'I')idcliente = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n        (async ()=>{\r\n          try {\r\n            const url = \"/admin/api/clientes/direccionesXcliente?id=\"+idcliente; //llamado a la API REST y se trae las direcciones segun cliente elegido\r\n            const respuesta = await fetch(url); \r\n            const resultado = await respuesta.json();\r\n            direcciones = resultado;\r\n            addDireccionSelect(resultado.direcciones);\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();\r\n        miDialogoUpDireccion.showModal();\r\n      }\r\n\r\n\r\n       ////// añade direccion al select de direcciones al miDialogoUpDireccion, cuando se desea actualizar o eliminar la direccion de un cliente\r\n      function addDireccionSelect<T extends {id:string, idcliente:string, idtarifa:string, tarifa:{id:string, idcliente:string, nombre:string, valor:string}, direccion:string, ciudad:string, departamento:string}>(addrs: T[]):void{\r\n        while(selectdirecciones?.firstChild)selectdirecciones.removeChild(selectdirecciones?.firstChild);\r\n        addrs.forEach(dir =>{\r\n          const option = document.createElement('option');\r\n          option.textContent = dir.direccion;\r\n          option.value = dir.id;\r\n          option.dataset.idcliente = dir.idcliente;\r\n          option.dataset.idtarifa = dir.idtarifa;\r\n          selectdirecciones.appendChild(option);\r\n        });\r\n        $('#uptarifa').val(addrs[0].idtarifa);\r\n        (document.querySelector('#updepartamento') as HTMLInputElement).value = addrs[0].departamento;\r\n        (document.querySelector('#upciudad') as HTMLInputElement).value = addrs[0].ciudad;\r\n        (document.querySelector('#updireccion') as HTMLInputElement).value = addrs[0].direccion;\r\n      }\r\n\r\n\r\n      ///////// Evento al select de direcciones en el modal actualizar direciones de cada cliente ////////////\r\n      selectdirecciones?.addEventListener('change', (e)=>{\r\n        const select = (e.target as HTMLSelectElement);\r\n        const idDir:string = select.options[select.selectedIndex].value;\r\n        const objDireccion = direcciones.find(x=>x.id == idDir)!;\r\n        $('#uptarifa').val(objDireccion?.idtarifa??1);\r\n        (document.querySelector('#updepartamento') as HTMLInputElement).value = objDireccion.departamento;\r\n        (document.querySelector('#upciudad') as HTMLInputElement).value = objDireccion.ciudad;\r\n        (document.querySelector('#updireccion') as HTMLInputElement).value = objDireccion.direccion;\r\n      });\r\n\r\n\r\n      document.querySelector('#formUpDireccion')?.addEventListener('submit', e=>{\r\n          e.preventDefault();\r\n          // verificar si se oprimio el btn eliminar o actualizar del modal actualizar direccion\r\n        });\r\n        \r\n\r\n      function eliminarClientes(e:Event){\n        const target = e.target as HTMLElement;\n        let idcliente = target.parentElement!.id, info = (tablaClientes as any).page.info();\n        if(target.tagName === 'I')idcliente = target.parentElement!.parentElement!.id;\n        const currentRow = target.closest('tr');\n        const dataRow = currentRow?.classList.contains('child') ? currentRow.previousElementSibling : currentRow;\n        const filaApi = (tablaClientes as any).row(dataRow);\n        const cliente = clientes.find(x=>x.id === idcliente);\n        const nombreCliente = `${cliente?.nombre ?? 'este cliente'} ${cliente?.apellido ?? ''}`.trim();\n        Swal.fire({\n            customClass: {\n              popup: 'j2-confirm j2-confirm--danger',\n              icon: 'j2-confirm__icon',\n              title: 'j2-confirm__title',\n              htmlContainer: 'j2-confirm__text',\n              actions: 'j2-confirm__actions',\n              confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n              cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n            },\n            buttonsStyling: false,\n            icon: 'question',\n            title: 'Eliminar cliente',\n            html: `Esta accion eliminara definitivamente a <strong>${escapeClienteHtml(nombreCliente)}</strong>.`,\n            showCancelButton: true,\n            confirmButtonText: 'Si, eliminar',\n            cancelButtonText: 'No',\n        }).then((result:any) => {\n            if (result.isConfirmed) {\n                (async ()=>{ \n                    const datos = new FormData();\r\n                    datos.append('id', idcliente);\r\n                    try {\r\n                        const url = \"/admin/api/eliminarCliente\";\r\n                        const respuesta = await fetch(url, {method: 'POST', body: datos}); \n                        const resultado = await respuesta.json();  \n                        if(resultado.exito !== undefined){\n                          filaApi.remove().draw(false); \n                          (tablaClientes as any).page(info.page).draw(false);\n                          clientes = clientes.filter(a => a.id !== idcliente);\n                          Swal.fire({\n                            customClass: {\n                              popup: 'j2-confirm j2-confirm--success',\n                              icon: 'j2-confirm__icon',\n                              title: 'j2-confirm__title',\n                              htmlContainer: 'j2-confirm__text',\n                              actions: 'j2-confirm__actions j2-confirm__actions--single',\n                              confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                            },\n                            buttonsStyling: false,\n                            icon: 'success',\n                            title: 'Cliente eliminado',\n                            text: resultado.exito[0],\n                            confirmButtonText: 'OK'\n                          }) \n                        }else{\n                            Swal.fire({\n                              customClass: {\n                                popup: 'j2-confirm j2-confirm--danger',\n                                icon: 'j2-confirm__icon',\n                                title: 'j2-confirm__title',\n                                htmlContainer: 'j2-confirm__text',\n                                actions: 'j2-confirm__actions j2-confirm__actions--single',\n                                confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                              },\n                              buttonsStyling: false,\n                              icon: 'error',\n                              title: 'No se pudo eliminar',\n                              text: resultado.error[0],\n                              confirmButtonText: 'OK'\n                            })\n                        }\n                    } catch (error) {\n                        console.log(error);\n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--danger',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                          },\n                          buttonsStyling: false,\n                          icon: 'error',\n                          title: 'No se pudo eliminar',\n                          text: 'Intenta nuevamente o revisa la conexion.',\n                          confirmButtonText: 'OK'\n                        })\n                    }\n                })();//cierre de async()\n            }\n        });\n      }\r\n\r\n\r\n      btnCerrarUpDireccion.addEventListener('click', ()=>miDialogoUpDireccion.close());\r\n  \r\n  \r\n      function limpiarformdialog(){\n        (document.querySelector('#formCrearUpdateCliente') as HTMLFormElement)?.reset();\n      }\n\n      function escapeClienteHtml(value:string):string{\n        return value.replace(/[&<>\"']/g, (char) => {\n          const entities:{[key:string]:string} = {\n            '&': '&amp;',\n            '<': '&lt;',\n            '>': '&gt;',\n            '\"': '&quot;',\n            \"'\": '&#039;'\n          };\n          return entities[char];\n        });\n      }\n\n      function renderClienteNombre(nombre:string):string{\n        return `<span class=\"clientes-name\"><span class=\"clientes-name__icon\"><i class=\"fa-solid fa-user\"></i></span><span>${escapeClienteHtml(nombre)}</span></span>`;\n      }\n\n      function renderClientePill(value:string, type:string):string{\n        return `<span class=\"clientes-table-pill clientes-table-pill--${type}\">${escapeClienteHtml(value)}</span>`;\n      }\n\n      function renderClienteRowData(cliente:{id:string, identificacion:string, nombre:string, apellido:string, telefono:string, email:string, acciones:string}):string[]{\n        return [\n          escapeClienteHtml(cliente.id),\n          renderClientePill(cliente.identificacion, 'document'),\n          renderClienteNombre(cliente.nombre),\n          escapeClienteHtml(cliente.apellido),\n          renderClientePill(cliente.telefono, 'phone'),\n          renderClientePill(cliente.email, 'email'),\n          cliente.acciones\n        ];\n      }\n\n      function ocultarToolbarNativoClientes():void{\n        const wrapper = document.querySelector('#tablaClientes_wrapper');\n        wrapper?.querySelectorAll('.dataTables_length, .dataTables_filter').forEach((control)=>{\n          (control as HTMLElement).remove();\n        });\n      }\n\n      function cerrarDialogoExterno(event:Event) {\n        if (event.target === miDialogoCliente || event.target === miDialogoCrearDireccion || event.target === miDialogoUpDireccion || (event.target as HTMLInputElement).value === 'salir') {\n          miDialogoCliente.close();\n          miDialogoCrearDireccion.close();\r\n          miDialogoUpDireccion.close();\r\n          \r\n        }\r\n      }\r\n    }\r\n  \r\n  })();\n","\r\n(():void=>{\r\n\r\n    if(document.querySelector('.detallecliente')){\r\n\r\n        const btnTotalCuotas = document.querySelector('#btnTotalCuotas') as HTMLButtonElement;\r\n        const btnPagoDeudaTotal = document.querySelector('#btnPagoDeudaTotal') as HTMLButtonElement;\r\n        const miDialogoTotalCuotas = document.querySelector('#miDialogoTotalCuotas') as HTMLDialogElement;\r\n        const miDialogoPagoTotal = document.querySelector('#miDialogoPagoTotal') as HTMLDialogElement;\r\n        const miDialogoAbono = document.querySelector('#miDialogoAbono') as HTMLDialogElement;\r\n        const tablaCuotas = document.querySelector('#tablaCuotas tbody') as HTMLBodyElement;\r\n\r\n        let idcredito:string|undefined, montocuota:string = '', saldopendienteCredito:string='0', indiceFila:HTMLDivElement;\r\n        let printerBT:string = getParam.impresora_principal_de_CAJA_para_Android_por_BT.valor_final;\r\n\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n\r\n        const parametrosURL = new URLSearchParams(window.location.search);\n        const id = parametrosURL.get('id');\n        inicializarSelectsDetalleCliente();\n\r\n        function clientesGraficas($url:string, $dato:string){\n            if(id!=null&&!Number.isNaN(id))\r\n                (async ()=>{\r\n                    try {\r\n                        const url = $url+id;\r\n                        const respuesta = await fetch(url); \r\n                        const resultado = await respuesta.json();\r\n                        if($dato == 'comprasXMes')comprasXMesXCliente(resultado);\r\n                        if($dato == 'ventasXCategorias')ventasXCategoriasXCliente(resultado);\r\n                    } catch (error) {\r\n                        console.log(error);\r\n                    }\r\n                })();\r\n        }\n\n        function inicializarSelectsDetalleCliente():void{\n            const selectConfig = {\n                width: '100%',\n                minimumResultsForSearch: Infinity,\n                dropdownCssClass: 'cliente-detail-select2-dropdown'\n            };\n            ($('#PagoTotal_caja') as any).select2({\n                ...selectConfig,\n                dropdownParent: $('#miDialogoPagoTotal')\n            });\n            ($('#PagoTotal_mediopago') as any).select2({\n                ...selectConfig,\n                dropdownParent: $('#miDialogoPagoTotal')\n            });\n            ($('#abono_caja') as any).select2({\n                ...selectConfig,\n                dropdownParent: $('#miDialogoAbono')\n            });\n            ($('#abono_mediopago') as any).select2({\n                ...selectConfig,\n                dropdownParent: $('#miDialogoAbono')\n            });\n        }\n\r\n        clientesGraficas('/admin/api/clientes/comprasXMesXCliente?id=', 'comprasXMes');\r\n        clientesGraficas('/admin/api/clientes/ventasXCategoriasXCliente?id=', 'ventasXCategorias');\r\n        \r\n\r\n        function comprasXMesXCliente(resultado:{periodo:string, ventas_totales:string}[]){\r\n            // Compras por mes\r\n            const ctxMes = (document.getElementById(\"chartComprasMes\") as HTMLCanvasElement).getContext('2d');\r\n            if (ctxMes) {\r\n                new Chart(ctxMes, {\r\n                type: \"line\",\r\n                data: {\r\n                    labels: resultado.map(x=>x.periodo),\r\n                    datasets: [{\r\n                    label: \"Compras\",\r\n                    data: resultado.map(x=>x.ventas_totales),\r\n                    borderColor: \"rgba(99, 102, 241, 1)\",\r\n                    backgroundColor: \"rgba(99, 102, 241, 0.2)\",\r\n                    tension: 0.4,\r\n                    fill: true,\r\n                    }]\r\n                },\r\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: {\n                        legend: {\n                            labels: {\n                                color: \"#14233b\",\n                                font: { weight: \"bold\" }\n                            }\n                        }\n                    }\n                }\n                });\r\n            }\r\n        }\r\n\r\n        function ventasXCategoriasXCliente(resultado:{categoria:string, idcategoria:string, unidades_vendidas:string, venta_total_categoria:string}[]){\r\n            // Categorías más compradas\r\n            const ctxCat = (document.getElementById(\"chartCategorias\") as HTMLCanvasElement).getContext('2d');\r\n            if (ctxCat) {\r\n                new Chart(ctxCat, {\r\n                type: \"doughnut\",\r\n                data: {\r\n                    labels: resultado.map(x=>x.categoria),\r\n                    datasets: [{\r\n                        data: resultado.map(x=>x.unidades_vendidas),\r\n                        backgroundColor: [\r\n                            \"rgba(99, 102, 241, 0.8)\",   // Indigo\r\n                            \"rgba(16, 185, 129, 0.8)\",   // Emerald\r\n                            \"rgba(249, 115, 22, 0.8)\",   // Orange\r\n                            \"rgba(107, 114, 128, 0.8)\"   // Gray\r\n                        ],\r\n                    }]\r\n                },\r\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: {\n                        legend: {\n                            position: \"bottom\",\n                            labels: {\n                                color: \"#14233b\",\n                                font: { weight: \"bold\" },\n                                padding: 16\n                            }\n                        }\n                    }\n                }\n                });\r\n            }\r\n        }\r\n\r\n\r\n        btnTotalCuotas.addEventListener('click', ()=>{\r\n            miDialogoTotalCuotas.showModal();\r\n            imprimirTotalCuotasXcliente();\r\n        });\r\n\r\n\r\n        btnPagoDeudaTotal.addEventListener('click', ()=>{\r\n            if(!Number.isNaN(deudatotalCiente) && Number(deudatotalCiente)>0){\n                miDialogoPagoTotal.showModal();\n                return;\n            }\n            Swal.fire({\n                customClass: {\n                    popup: 'j2-confirm j2-confirm--success',\n                    icon: 'j2-confirm__icon',\n                    title: 'j2-confirm__title',\n                    htmlContainer: 'j2-confirm__text',\n                    actions: 'j2-confirm__actions j2-confirm__actions--single',\n                    confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                },\n                buttonsStyling: false,\n                icon: 'info',\n                title: 'Sin deuda pendiente',\n                text: 'Este cliente no tiene saldo pendiente por pagar.',\n                confirmButtonText: 'OK'\n            });\n        });\r\n\r\n\r\n        document.querySelector('#formPagoTotalDeuda')?.addEventListener('submit', async (e:Event)=>{\r\n            e.preventDefault();\r\n            if(id!=null&&!Number.isNaN(id)){\r\n                const datos = new FormData();\r\n                datos.append('idcliente', id);\r\n                datos.append('idcaja', $('#PagoTotal_caja').val() as string);\r\n                datos.append('idmediodepago', $('#PagoTotal_mediopago').val() as string);\r\n                datos.append('valorDeudaTotal', deudatotalCiente);\r\n                try {\r\n                    const url = \"/admin/api/creditos/pagarDeudaTotal\";  //api en creditoscontrolador\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                        document.querySelector('#totalDeudaText')!.textContent = '$0';\r\n                        document.querySelectorAll<HTMLTableCellElement>('.pendiente').forEach(td=>{\r\n                            const tr = td.parentElement;\r\n                            if(tr){\r\n                                tr.children[5].textContent = '$0';\n                                tr?.children[5].classList.remove('cliente-detail-debt-cell');\n                                tr.children[6].innerHTML = '<span class=\"cliente-detail-status cliente-detail-status--1\">Finalizado</span>';\n                                tr.children[6].classList.remove('is-open', 'pendiente');\n                                tr.children[6].classList.add('is-done');\n                            }\n                        });\n                        miDialogoPagoTotal.close();\n                        Swal.fire({\n                            customClass: {\n                                popup: 'j2-confirm j2-confirm--success',\n                                icon: 'j2-confirm__icon',\n                                title: 'j2-confirm__title',\n                                htmlContainer: 'j2-confirm__text',\n                                actions: 'j2-confirm__actions j2-confirm__actions--single',\n                                confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                            },\n                            buttonsStyling: false,\n                            icon: 'success',\n                            title: 'Pago registrado',\n                            text: resultado.exito[0],\n                            confirmButtonText: 'OK'\n                        });\n                    }else{\n                        Swal.fire({\n                            customClass: {\n                                popup: 'j2-confirm j2-confirm--danger',\n                                icon: 'j2-confirm__icon',\n                                title: 'j2-confirm__title',\n                                htmlContainer: 'j2-confirm__text',\n                                actions: 'j2-confirm__actions j2-confirm__actions--single',\n                                confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                            },\n                            buttonsStyling: false,\n                            icon: 'error',\n                            title: 'No se pudo registrar',\n                            text: resultado.error[0],\n                            confirmButtonText: 'OK'\n                        });\n                    }\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            }\r\n        });\r\n\r\n\r\n\r\n        async function imprimirTotalCuotasXcliente(){\r\n            if(id!=null&&!Number.isNaN(id)){\r\n                try {\r\n                    const url = `/admin/api/totalCuotasXcliente?id=${id}`; //llamado a la API REST \r\n                    const respuesta = await fetch(url); \r\n                    const resultado:{capital:string, fechafin:string, fechainicio:string, fechapagado:string, idestadocreditos:string, interestotal:string, num_orden:string, numerocuota:string, valorpagado:string}[] = await respuesta.json();\r\n\r\n                    while(tablaCuotas.firstChild)tablaCuotas.removeChild(tablaCuotas.firstChild);\r\n                    resultado.forEach(c=>{\r\n                        const tr = document.createElement('tr') as HTMLTableRowElement;\r\n                        tr.innerHTML = `<td class=\"text-center\">${c.num_orden}</td>\r\n                                        <td class=\"text-center\">$ ${(Number(c.capital)+Number(c.interestotal)).toLocaleString()}</td>\r\n                                        <td class=\"text-center\">${c.numerocuota}</td>\r\n                                        <td class=\"text-center\">$ ${Number(c.valorpagado).toLocaleString()}</td>\r\n                                        <td class=\"text-center\">${c.fechapagado}</td>\r\n                                        <td class=\"text-center\">${c.idestadocreditos=='1'?'Finalizado':c.idestadocreditos=='2'?'Abierto':'Anulado'}</td>`;\r\n                        tablaCuotas.prepend(tr);\r\n                    });\r\n\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            }\r\n        }\r\n\r\n\r\n        ////////////// Evento a la tabla cuotas ///////////////\r\n        document.querySelector('#tablaCreditos')?.addEventListener(\"click\", (e:Event)=>{ //evento click sobre toda la tabla\r\n            const target = e.target as HTMLButtonElement;\r\n            if(target?.classList.contains(\"abonarCredito\") || target?.parentElement?.classList.contains(\"abonarCredito\") )abonarCredito(target);\r\n            if(target?.classList.contains(\"anularCredito\") || target?.parentElement?.classList.contains(\"anularCredito\"))anularCredito(target);\r\n        });\r\n\r\n\r\n        function abonarCredito(target: HTMLButtonElement){\r\n            const element = target.closest('div');\r\n            if(!element)return;\r\n            idcredito = element?.id;\r\n            montocuota = element?.dataset.montocuota||'0';\r\n            if(idcredito == undefined || Number.isNaN(idcredito))return\r\n            saldopendienteCredito = element?.dataset.saldopendiente!;\r\n            if(Number.isNaN(saldopendienteCredito) || Number(saldopendienteCredito)<=0)return;\r\n            miDialogoAbono.showModal();\r\n            document.querySelector('#numCredito')!.textContent = \"Credito No.: \"+idcredito;\n            document.querySelector('#saldopendiente')!.textContent = \"Saldo pendiente: \"+saldopendienteCredito;\r\n            indiceFila = (element.parentElement?.parentElement) as HTMLTableRowElement;\r\n        }\r\n\r\n        document.querySelector('#formrealizarAbono')?.addEventListener('submit', async (e:Event)=>{\r\n            e.preventDefault();\r\n            const imprimirAbono = document.querySelector('#imprimirAbono') as HTMLInputElement;\r\n            const valorabono = (document.querySelector('#abono') as HTMLInputElement).value;\r\n            const datos = new FormData();\r\n            datos.append('id_credito', idcredito||'');\r\n            datos.append('cajaid', $('#abono_caja').val() as string);\r\n            datos.append('mediopagoid', $('#abono_mediopago').val() as string);\r\n            datos.append('valorpagado', valorabono);\r\n            datos.append('montocuota', montocuota);\r\n            try {\r\n                const url = \"/admin/api/creditos/registrarAbonoFromCli\";  //api en creditoscontrolador\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                const resultado = await respuesta.json();\r\n                if(resultado.exito !== undefined){\r\n                    deudatotalCiente = (Number(deudatotalCiente)-Number(valorabono))+'';\r\n                    saldopendienteCredito = (Number(saldopendienteCredito)-Number(valorabono))+'';\r\n                    document.querySelector('#totalDeudaText')!.textContent = '$'+deudatotalCiente;\r\n                    indiceFila.children[5].textContent = '$'+saldopendienteCredito;\n                    if((Number(saldopendienteCredito))== 0){\n                        indiceFila.children[5].classList.remove('cliente-detail-debt-cell');\n                        indiceFila.children[6].innerHTML = '<span class=\"cliente-detail-status cliente-detail-status--1\">Finalizado</span>';\n                        indiceFila.children[6].classList.remove('is-open', 'pendiente');\n                        indiceFila.children[6].classList.add('is-done');\n                    }else{\n                        indiceFila.children[6].innerHTML = '<span class=\"cliente-detail-status cliente-detail-status--2\">Abierto</span>';\n                    }\n                    (indiceFila.children[7].children[0] as HTMLDivElement).dataset.saldopendiente = saldopendienteCredito;\n                    miDialogoAbono.close();\n                    Swal.fire({\n                        customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                        },\n                        buttonsStyling: false,\n                        icon: 'success',\n                        title: 'Abono registrado',\n                        text: resultado.exito[0],\n                        confirmButtonText: 'OK'\n                    });\n                    if(resultado.idcuota && imprimirAbono.checked)printPOSComprobanteAbono(resultado.idcuota);\n                }else{\n                    miDialogoAbono.close();\n                    Swal.fire({\n                        customClass: {\n                            popup: 'j2-confirm j2-confirm--danger',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                        },\n                        buttonsStyling: false,\n                        icon: 'error',\n                        title: 'No se pudo registrar',\n                        text: resultado.error[0],\n                        confirmButtonText: 'OK'\n                    });\n                }\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        });\r\n\r\n\r\n        async function printPOSComprobanteAbono(idabono:string|undefined){\r\n            if(idabono==undefined)return;\r\n            try{\r\n                const url = \"/admin/api/creditos/getAbono?id=\"+idabono; //llamado a la API REST - creditocontrolador \r\n                const respuesta = await fetch(url); \r\n                const resultado = await respuesta.json();\r\n                const isAndroid = /Android/i.test(navigator.userAgent);\r\n                if(printerBT === '1'){\r\n                const builder = new ticketAbonoBuilder(resultado);\r\n                const ticket = await builder.generate(true); //true para version buffer bytes\r\n                const base64 = bytesToBase64(ticket);\r\n                if(isAndroid)window.location.href = `rawbt:base64,${base64}`;\r\n                //descargar .bin a equipo\r\n                /*const blob = new Blob([ticket], { type: 'application/octet-stream' });\r\n                const url = URL.createObjectURL(blob);\r\n                const a = document.createElement('a');\r\n                a.href = url;\r\n                a.download = 'ticket.bin';\r\n                a.click();\r\n                URL.revokeObjectURL(url);*/\r\n                }\r\n            }catch(error){\r\n                console.log(error);\r\n            }\r\n\r\n            if(!isNaN(Number(idabono)))\r\n                window.open(\"/admin/printPDFAbonoCredito?id=\" + idabono, \"_blank\"); //controlador printcontrolador\r\n        }\r\n\r\n\r\n        function anularCredito(target: HTMLButtonElement){\r\n            const idabono = target.parentElement?.id;\r\n            const fila = target.closest('tr');\r\n            if(idabono==undefined)return;\n            Swal.fire({\n                customClass: {\n                    popup: 'j2-confirm j2-confirm--danger',\n                    icon: 'j2-confirm__icon',\n                    title: 'j2-confirm__title',\n                    htmlContainer: 'j2-confirm__text',\n                    actions: 'j2-confirm__actions',\n                    confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n                    cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n                },\n                buttonsStyling: false,\n                icon: 'question',\n                title: 'Anular credito',\n                html: '<strong>Esta accion no se puede deshacer.</strong><br>El credito sera anulado definitivamente.',\n                showCancelButton: true,\n                confirmButtonText: 'Si, anular',\n                cancelButtonText: 'No',\n            }).then((result:any) => {\n                if (result.isConfirmed) {\r\n                    /*(async ()=>{ \r\n                        try {\r\n                            const url = \"/admin/api/creditos/anularAbono?id=\"+idabono;\r\n                            const respuesta = await fetch(url); \r\n                            const resultado = await respuesta.json();\r\n                            if(resultado.exito !== undefined){\r\n                                fila?.remove();\r\n                                Swal.fire(resultado.exito[0], '', 'success');\r\n                            }else{\r\n                                Swal.fire(resultado.error[0], '', 'error');\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();//cierre de async()*/\r\n                }\r\n            });\r\n        }\r\n\r\n\r\n        function cerrarDialogoExterno(event:Event) {\r\n            const f = event.target;\r\n            if (f=== miDialogoTotalCuotas || f === miDialogoPagoTotal || f === miDialogoAbono || (f as HTMLElement).id === 'btnCerrarTotalCuotas' || (f as HTMLElement).id === 'btnCerrarPagoTotal' || (f as HTMLElement).id === 'btnXCerrarModalAbono' || (f as HTMLButtonElement).value == 'Salir'){\r\n                miDialogoTotalCuotas.close();\r\n                miDialogoPagoTotal.close();\r\n                miDialogoAbono.close();\r\n            }\r\n        }\r\n\r\n    }\r\n\r\n})();\n","(()=>{\r\n    \r\n    if(document.querySelector('.preciosXCliente')){\r\n        const listaProductos = document.querySelector('.listaProductos');\r\n        //const subproducto:HTMLSelectElement = document.querySelector('#subproducto')!;\r\n        let precioPersonalizado = document.querySelector('#precioPersonalizado') as HTMLInputElement; //input cantidad\r\n\r\n        \r\n\r\n        \r\n        ($('#productos') as any).select2({\r\n            width: '100%',\r\n            maximumSelectionLength: 1,\r\n        });\r\n\r\n\r\n\r\n        ///////////////// EVENTO AL FORMULARIO ASOCIAR PRODUCTO //////////////////\r\n        document.querySelector('#formAddProducto')?.addEventListener('submit', (e)=>{\r\n            e.preventDefault();\r\n            const producto = $('#productos').find('option:selected');\r\n            let valor:number = Number(precioPersonalizado.value);\r\n\r\n            (async ()=>{ \r\n                const datos = new FormData();\r\n                datos.append('idcliente', (document.querySelector('#idcliente') as HTMLInputElement).value);\r\n                datos.append('idproducto', $('#productos').val()as string);\r\n                datos.append('precioxcliente', valor.toString());\r\n                try {\r\n                    const url = \"/admin/api/clientes/preciospersonalizados\";  //asocia el precio personalizado al cliente\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                      msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                        /////validar si es el mismo subproducto, y actualizar \r\n                        validarProducto($('#productos').val()as string, producto.data('producto'));\r\n                        ////// reset form ///////\r\n                        ($('#productos') as any).val([]).trigger('change');\r\n                        //$(`#subproducto option[value=\"${$('#subproducto').val()}\"]`).remove();\r\n                        (document.querySelector('#formAddProducto') as HTMLFormElement)?.reset();\r\n                    }else{\r\n                      msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();//cierre de async()\r\n        });\r\n\r\n\r\n        function validarProducto(idproducto:string, producto:string){\n            const pro = document.querySelector(`.listaProductos div[id=\"${idproducto}\"]`);\n            if(pro){\n                pro.querySelector('strong')!.textContent = '$'+Number(precioPersonalizado.value).toLocaleString('es-CO');\n            }else{\n                listaProductos?.insertAdjacentHTML('beforeend', `\n                <div id=\"${idproducto}\" class=\"cliente-price-item\" role=\"alert\">\n                    <span class=\"cliente-price-item__icon\"><i class=\"fa-solid fa-box\"></i></span>\n                    <div class=\"cliente-price-item__content\">\n                        <strong>$${Number(precioPersonalizado.value).toLocaleString('es-CO')}</strong>\n                        <p>${escapePrecioClienteHtml(producto)}</p>\n                    </div>\n                    <button type=\"button\" class=\"cliente-price-item__remove\" title=\"Eliminar precio personalizado\">\n                        <span id=\"${idproducto}\" class=\"material-symbols-outlined\">cancel</span>\n                    </button>\n                </div>`\n                );\n            }\n        }\n\r\n\r\n        listaProductos?.addEventListener('click', (e:Event)=>{\r\n            const btn = (e.target as HTMLSpanElement); //contiene el id del producto\r\n            if(btn.tagName == \"SPAN\")eliminarPrecioPersonalizado((document.querySelector('#idcliente') as HTMLInputElement).value, btn.id);\r\n        });\r\n\r\n\r\n        function eliminarPrecioPersonalizado(idcliente:string, idproducto:string){\n            const pro = document.querySelector(`.listaProductos div[id=\"${idproducto}\"]`);\r\n            (async ()=>{\r\n                try {\r\n                  const url = \"/admin/api/clientes/eliminarPrecioPersonalizado?idcliente=\"+idcliente+\"&idproducto=\"+idproducto; //llamado a la API REST para eliminar precio personlizado a cliente\r\n                  const respuesta = await fetch(url); \r\n                  const resultado = await respuesta.json();\r\n                  if(resultado.exito !== undefined){\r\n                    pro?.remove();\r\n                    msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                  }else{\r\n                    msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                  }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n        }\n\n        function escapePrecioClienteHtml(value:string):string{\n            return value.replace(/[&<>\"']/g, (char) => {\n                const entities:{[key:string]:string} = {\n                    '&': '&amp;',\n                    '<': '&lt;',\n                    '>': '&gt;',\n                    '\"': '&quot;',\n                    \"'\": '&#039;'\n                };\n                return entities[char];\n            });\n        }\n\n\n    }\n\r\n})();\n","(():void=>{\r\n  if(document.querySelector('.caja')){\r\n    const modalGastosIngresos:any = document.querySelector(\"#gastosIngresos\");\r\n    const modalcambioMedioPago:any = document.querySelector(\"#cambioMedioPago\");\r\n    const miDialogoAbrirCaja:any = document.querySelector(\"#miDialogoAbrirCaja\");\r\n    const btnGastosingresos = document.querySelector<HTMLButtonElement>(\"#btnGastosingresos\");\r\n    const btnAbrirCajon = document.querySelector<HTMLButtonElement>(\"#btnAbrirCajon\");\r\n    const operacion = document.querySelector('#operacion') as HTMLSelectElement;\r\n    const origengasto = document.querySelectorAll<HTMLInputElement>('input[name=\"origengasto\"]');\r\n    const mediosPago = document.querySelectorAll<HTMLInputElement>('.mediopago'); //todos los medios de pago del modal\r\n    const totalPagado = document.querySelector('#totalPagado') as HTMLSpanElement;\r\n    const numfactura = document.querySelector('#numfactura') as HTMLLabelElement;\r\n    const inputAbrirCaja = document.querySelector('#inputAbrirCaja') as HTMLInputElement;\r\n    const formGastosingresos = document.querySelector('#formGastosingresos') as HTMLFormElement;\r\n    const btnEnviargastosingresos = document.querySelector('#btnEnviargastosingresos') as HTMLInputElement;\r\n\r\n    let printerBT:string = getParam.impresora_principal_de_CAJA_para_Android_por_BT.valor_final;\r\n    let tablaListaPedidos:HTMLElement;\r\n    let estadofactura:string, contentMP:HTMLElement, idfactura:string = '0';\r\n    let mediospagoDB:{id:string, idmediopago:string, id_factura:string, valor:string}[];\r\n    let nuevosMediosPago:{idmediopago:string, valor: string}[]=[];  // guardar los medios de pago a enviar a backend\r\n    const setMediosPagoDB = new Set();\r\n    const mapMediospago = new Map();\r\n    let totalpagadointerno = 0;\r\n\r\n    tablaListaPedidos = ($('#tablaListaPedidos') as any).DataTable(configdatatablescaja);\r\n\r\n\r\n    interface clavesApi {\r\n      clave:string,\r\n      valor_default:string|null,\r\n      valor_final:string|null,\r\n      valor_local:string|null\r\n    };\r\n\r\n    let claveAbrirCajon:clavesApi[];\r\n\r\n    (async ()=>{\r\n      try {\r\n          const url = \"/admin/api/getPasswords\"; //llamado a la API REST\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json(); \r\n          claveAbrirCajon = resultado;\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();\r\n\r\n\r\n    //////// clic al btn gastos/ingresos\r\n    btnGastosingresos?.addEventListener('click', ():void=>{\r\n      modalGastosIngresos.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    formGastosingresos.addEventListener('submit', (e:Event)=>{\r\n      btnEnviargastosingresos.disabled = true;\r\n      btnEnviargastosingresos.textContent = \"Enviando...\";\r\n    });\r\n\r\n    ///////// cambio de tipo de operacion si ingreso o gasto, si es gasto habilita el select de los tipos de gastos\r\n    operacion?.addEventListener('change', (e:Event)=>{\r\n      const targetDom = e.target as HTMLSelectElement;\r\n      const tipodegasto = document.querySelector('.tipodegasto') as HTMLElement;\r\n\r\n      if(targetDom.value == 'gasto'){\r\n        tipodegasto.style.display = 'flex';\r\n        document.querySelector('#tipodegasto')?.setAttribute(\"required\", \"\"); //categoria de los gastos\r\n        document.querySelector('#origengasto')?.classList.remove('hidden');  //origen del gasto ya sea por caja o banco\r\n        document.querySelector('#origengasto')?.classList.add('grid');\r\n        showCajasBancos();\r\n      }\r\n      else{ // ingreso a caja\r\n        tipodegasto.style.display = 'none';\r\n        document.querySelector('#tipodegasto')?.removeAttribute(\"required\");\r\n        document.querySelector('#origengasto')?.classList.add('hidden');\r\n        document.querySelector('#origengasto')?.classList.remove('grid');\r\n        document.querySelector('#showcajas')?.classList.remove('hidden'); //mostar caja\r\n        document.querySelector('#showbancos')?.classList.add('hidden'); //oculta banco\r\n        document.querySelector('#banco')?.removeAttribute(\"required\");\r\n      }\r\n    });\r\n\r\n    /// evento a los inputs type radio para elegir origne del gasto = caja o bancos\r\n    origengasto.forEach(element =>element.addEventListener('click', showCajasBancos));\r\n\r\n\r\n    function showCajasBancos(){\r\n      const selectorigen = document.querySelector('input[name=\"origengasto\"]:checked');\r\n      if(selectorigen?.id == 'gastocaja'){\r\n        document.querySelector('#showcajas')?.classList.remove('hidden');\r\n        document.querySelector('#showbancos')?.classList.add('hidden');\r\n        document.querySelector('#banco')?.removeAttribute(\"required\");\r\n      }else{\r\n        document.querySelector('#showbancos')?.classList.remove('hidden');\r\n        document.querySelector('#banco')?.setAttribute(\"required\", \"\");\r\n      }\r\n    }\r\n\r\n\r\n    //////// clic al btn abrir cajon monedero\r\n    btnAbrirCajon?.addEventListener('click', ():void=>{\r\n      miDialogoAbrirCaja.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    //evento al boton confirmar para eliminar orden\r\n    document.querySelector('.siAbrirCajon')?.addEventListener('click', (event:Event)=>{\r\n      const v:number = validarPasswordDcto();\r\n      if(!v)return;\r\n      if((event.target as HTMLInputElement).closest('.siAbrirCajon'))abrirCajonMonedero();\r\n    });\r\n\r\n    const abrirCajonMonedero = async():Promise<void>=>{\r\n        try {\r\n            const url = \"http://localhost:3100/api/printPOS/openCashDrawer/CAJA\";  //api llama servidor de impresion local.\r\n            const respuesta = await fetch(url);\r\n            const resultado = await respuesta.json();\r\n            console.log(resultado);\r\n            if(resultado){\r\n              msjalertToast('success', 'Â¡Ã‰xito!', 'Apertura de cajon enviada');\r\n              miDialogoAbrirCaja.close();\r\n              document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n            }else{\r\n              msjalertToast('error', 'Â¡Error!', 'Error en el cajon monedero');\r\n            }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    ////////////// Evento a la tabla lista de pedidos ///////////////\r\n    document.querySelector('#tablaListaPedidos')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if(target?.classList.contains(\"mediosdepago\")||target.parentElement?.classList.contains(\"mediosdepago\"))cambiomediopago(target);\r\n      if(target?.classList.contains(\"printPOS\")||target.parentElement?.classList.contains(\"printPOS\"))printPOS(target);\r\n      if(target?.classList.contains(\"printPDF\")||target.parentElement?.classList.contains(\"printPDF\"))printPDF(target);\r\n    });\r\n\r\n\r\n    //////////// Modal para el cambio de medio de pago ////////////\r\n    function cambiomediopago(target:HTMLElement){\r\n      idfactura = target.id;\r\n      contentMP = target;\r\n      estadofactura = target.dataset.estado??'';\r\n      totalPagado.textContent = Number(target.dataset.totalpagado??'0').toLocaleString();\r\n      if(target.tagName == \"BUTTON\"){\r\n        idfactura = target.parentElement!.id;\r\n        contentMP = target.parentElement!;\r\n        estadofactura = target.parentElement?.dataset.estado??'';\r\n        totalPagado.textContent = Number(target.parentElement!.dataset.totalpagado??'0').toLocaleString();\r\n      }\r\n      facturamediospago();     //muestra los valores de los medios de pago de cada factura\r\n\r\n      if(estadofactura == \"Eliminada\")document.querySelector('#btnEnviarCambioMedioPago')?.classList.add('!hidden');\r\n      if(estadofactura == \"Paga\")document.querySelector('#btnEnviarCambioMedioPago')?.classList.remove('!hidden');\r\n      modalcambioMedioPago.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    function resaltarMediosActuales(){\r\n        // Ocultar todas las etiquetas y quitar resaltados anteriores\r\n        document.querySelectorAll('.medio-actual').forEach(etiqueta=>{\r\n            etiqueta.classList.add('hidden');\r\n        });\r\n\r\n        document.querySelectorAll('.input-medio-pago').forEach(input=>{\r\n            input.classList.remove(\r\n                'border-indigo-500',\r\n                'ring-2',\r\n                'ring-indigo-200',\r\n                'bg-indigo-50'\r\n            );\r\n        });\r\n\r\n        // Contar cuÃ¡ntos medios tienen saldo\r\n        let cantidadConSaldo = 0;\r\n\r\n        mediosPago.forEach(input => {\r\n            const valor = parseInt(\r\n                input.value.replace(/[,.]/g, '')\r\n            );\r\n\r\n            if (valor > 0) {\r\n                cantidadConSaldo++;\r\n            }\r\n        });\r\n\r\n        // Resaltar los medios que tienen saldo\r\n        mediosPago.forEach(input=>{\r\n            const valor = parseInt(\r\n                input.value.replace(/[,.]/g,'')\r\n            );\r\n\r\n            if(valor > 0){\r\n                const contenedor = input.closest('.contenedor-medio-pago');\r\n\r\n                const etiqueta = contenedor?.querySelector('.medio-actual') as HTMLElement;\r\n\r\n                if(etiqueta){\r\n                    etiqueta.classList.remove('hidden');\r\n\r\n                    if(cantidadConSaldo === 1){\r\n                        etiqueta.textContent = 'â‘  Medio de pago actual';\r\n                    }else{\r\n                        etiqueta.textContent = 'âœ“ Pago original';\r\n                    }\r\n                }\r\n\r\n                input.classList.add(\r\n                    'border-indigo-500',\r\n                    'ring-2',\r\n                    'ring-indigo-200',\r\n                    'bg-indigo-50'\r\n                );\r\n            }\r\n        });\r\n    }\r\n\r\n    function facturamediospago(){  //muestra los valores de los medios de pago de cada factura\r\n      numfactura.textContent = 'Factura NÂ° : '+idfactura;\r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/mediospagoXfactura?id=\"+idfactura; //llamado a la API REST y se trae los medios de pago segun factura\r\n          const respuesta = await fetch(url); \r\n          mediospagoDB = await respuesta.json(); \r\n          //console.log(mediospagoDB);\r\n          //const setMediosPagoDB = new Set(mediospagoDB.map(x=>x.idmediopago));\r\n          //console.log(setMediosPagoDB);\r\n\r\n          //agrupar por idmediopago y sumar su valor\r\n          totalpagadointerno = 0;\r\n          mediospagoDB = Object.values(mediospagoDB.reduce<Record<string, {id:string, idmediopago:string, id_factura:string, valor:string}>>((obj, x)=>{\r\n            totalpagadointerno+=Number(x.valor);\r\n            const k = x.idmediopago;\r\n            if(!obj[k])obj[k] = {...x, valor: '0'}\r\n            obj[k].valor = (Number(obj[k].valor) + Number(x.valor))+'';\r\n            return obj;\r\n          }, {}));\r\n          console.log(totalpagadointerno);\r\n\r\n          mediospagoDB.forEach(x => setMediosPagoDB.add(x.idmediopago));//se llena el set con los medios de pago de la DB\r\n          mediosPago.forEach(mediopago =>{  //se llena los inputs medios de pago con los medios de pago de la DB\r\n            mediopago.value = '0';\r\n            for(let i=0; i<mediospagoDB.length; i++)\r\n              if(mediopago.id == mediospagoDB[i].idmediopago){\r\n                mediopago.value =  Number(mediospagoDB[i].valor).toLocaleString();\r\n                mapMediospago.set(mediopago.id, Number(mediospagoDB[i].valor));\r\n                break;\r\n              }\r\n          });\r\n          resaltarMediosActuales();\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n    }\r\n\r\n    mediosPago.forEach(mp =>{\r\n      mp.addEventListener('input', (e)=>{\r\n        let totalmediospago = 0;\r\n\r\n        mediosPago.forEach((item)=>{ // sumar todos los medios de pago\r\n          totalmediospago += parseInt(\r\n            (item as HTMLInputElement).value.replace(/[,.]/g, '')\r\n          );\r\n        });\r\n\r\n        if(totalmediospago <= parseInt(totalPagado.textContent!.replace(/[,.]/g, ''))){\r\n\r\n          // Guardar el Ãºltimo valor vÃ¡lido del input\r\n          mapMediospago.set(\r\n            (e.target as HTMLInputElement).id,\r\n            parseInt((e.target as HTMLInputElement).value.replace(/[,.]/g, ''))\r\n          );\r\n\r\n          // Actualizar diferencia\r\n          document.querySelector('#diferencia')!.textContent =\r\n            (\r\n              parseInt(totalPagado.textContent!.replace(/[,.]/g, ''))\r\n              - totalmediospago\r\n            ).toLocaleString();\r\n\r\n        }else{\r\n          // Restaurar el Ãºltimo valor vÃ¡lido\r\n          if(mapMediospago.has((e.target as HTMLInputElement).id)){\r\n            (e.target as HTMLInputElement).value =\r\n              mapMediospago.get((e.target as HTMLInputElement).id).toLocaleString();\r\n\r\n          }else{\r\n            (e.target as HTMLInputElement).value = '0';\r\n          }\r\n        }\r\n      });\r\n    });\r\n\r\n\r\n    async function printPOS(target: HTMLElement){\r\n      let idfactura = target.parentElement!.id;\r\n      if(target.tagName === 'I')idfactura = target.parentElement!.parentElement!.id;\r\n      //obtener factura por fetch\r\n      try{\r\n        const url = \"/admin/api/getInvoice?id=\"+idfactura; //llamado a la API REST - cajacontrolador y se trae detalle de factura \r\n        const respuesta = await fetch(url); \r\n        const resultado:DataInvoice = await respuesta.json();\r\n        const isAndroid = /Android/i.test(navigator.userAgent);\r\n        if(printerBT === '1'){\r\n          const builder = new InvoiceTicketBuilder2(resultado);\r\n          console.log(resultado);\r\n          const ticket = await builder.generate(true); //true para version buffer bytes\r\n          const base64 = bytesToBase64(ticket);\r\n          if(isAndroid)window.location.href = `rawbt:base64,${base64}`;\r\n          //descargar .bin a equipo\r\n          /*const blob = new Blob([ticket], { type: 'application/octet-stream' });\r\n          const url = URL.createObjectURL(blob);\r\n          const a = document.createElement('a');\r\n          a.href = url;\r\n          a.download = 'ticket.bin';\r\n          a.click();\r\n          URL.revokeObjectURL(url);*/\r\n        }\r\n\r\n\r\n        if(printerBT !== '1'){\r\n          const dataPrinter = {\r\n            businessId: resultado.host,\r\n            sucursal: resultado.sucursal,\r\n            printerName: 'CAJA',\r\n            tipoTicket: 'ticket',\r\n            content: resultado\r\n          };\r\n          try {\r\n            const url = \"https://servidorimpresionposws-production.up.railway.app/api/print/printJob\"; //llamado a la API server print nodejs/ts\r\n            const respuesta = await fetch(url, {\r\n              method: 'POST',\r\n              headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n              body: JSON.stringify(dataPrinter)\r\n            });\r\n            const resultado = await respuesta.json();\r\n            console.log(resultado);\r\n          } catch (error) {\r\n            console.log(error);\r\n          }\r\n        }\r\n\r\n\r\n        window.open(\"/admin/printPDFPOS?id=\" + idfactura, \"_blank\");  //controlador printcontrolador\r\n      }catch(error){\r\n        console.log(error);\r\n      }\r\n    }\r\n\r\n    function printPDF(target: HTMLElement){\r\n      let idfactura = target.parentElement!.id;\r\n      let cotizacion:string = target.parentElement?.dataset.cotizacion!;\r\n      let urlprintPDF:string = \"/printfacturacarta?id=\";\r\n      if(target.tagName === 'I'){\r\n        idfactura = target.parentElement!.parentElement!.id;\r\n        cotizacion = target.parentElement!.parentElement?.dataset.cotizacion!;\r\n      }\r\n      if(cotizacion === '1')urlprintPDF = \"/printcotizacion?id=\";\r\n      const ventana = window.open(urlprintPDF + idfactura, \"_blank\");  //cajacontrolador\r\n      if(ventana){\r\n        ventana.onload = ()=>{\r\n          ventana?.focus();\r\n          ventana?.print();\r\n          setTimeout(() => { ventana?.close(); }, 200); // Cerrar la ventana despuÃ©s de unos segundos\r\n        };\r\n      }\r\n    }\r\n\r\n    ////////////////// evento al bton para cambiar medios de pago //////////////////////\r\n    document.querySelector('#formCambioMedioPago')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      let totalotrosmedios = 0;\r\n      nuevosMediosPago.length = 0;\r\n      mediosPago.forEach((item, index)=>{ \r\n        totalotrosmedios += parseInt((item as HTMLInputElement).value.replace(/[,.]/g, '')); //sumar todos los medios de pago de los inputs\r\n        if(item.value != '0')\r\n          nuevosMediosPago = [...nuevosMediosPago, {idmediopago: item.id, valor: item.value.replace(/[,.]/g, '')}];  //obtengo los nuevos medios de pago difente a cero\r\n      });\r\n\r\n      if(totalotrosmedios != parseInt(totalPagado.textContent!.replace(/[,.]/g, '')) && totalotrosmedios!=totalpagadointerno){\r\n        msjAlert('error', 'Valor diferente al pagado', (document.querySelector('#divmsjalerta2') as HTMLElement));\r\n        return;\r\n      }\r\n      actualizarMediosPago();\r\n    });\r\n\r\n\r\n    async function actualizarMediosPago(){\r\n      const setNuevosMediosPago = new Set(nuevosMediosPago.map(x=>x.idmediopago));\r\n      ////cruzar los datos de los medios de pago de la DB y de los nuevos medios de pago////\r\n      //////// medios de pago iguales o compartidos ///////////\r\n      const mediospagocompartidos = mediospagoDB.filter(x=>setNuevosMediosPago.has(x.idmediopago));\r\n      //////// nuevos medios de pago que no estan en DB, crear o agregar\r\n      const nuevosMediosPagoNoEnDB = nuevosMediosPago.filter(x=>!setMediosPagoDB.has(x.idmediopago));\r\n      //////// medios de pago de la DB que no estan en los nuevos medios de pago, eliminar\r\n      const mediosPagoDBNoEnNuevos = mediospagoDB.filter(x=>!setNuevosMediosPago.has(x.idmediopago));\r\n\r\n      const datos = new FormData();\r\n      datos.append('id_factura', idfactura);\r\n      datos.append('efectivoDB', mediospagoDB.find(x=>x.idmediopago=='1')?.valor??'0'+'');\r\n      datos.append('nuevoEfectivo', nuevosMediosPago.find(x=>x.idmediopago=='1')?.valor??'0'+'');\r\n      datos.append('mediospagocompartidos', JSON.stringify(mediospagocompartidos));\r\n      datos.append('nuevosMediosPagoNoEnDB', JSON.stringify(nuevosMediosPagoNoEnDB));\r\n      datos.append('mediosPagoDBNoEnNuevos', JSON.stringify(mediosPagoDBNoEnNuevos));\r\n      datos.append('nuevosMediosPago', JSON.stringify(nuevosMediosPago));  \r\n      try {\r\n          const url = \"/admin/api/cambioMedioPago\";  //va al controlador ventascontrolador\r\n          const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n          const resultado = await respuesta.json();\r\n          if(resultado.exito !== undefined){\r\n            msjalertToast('success', 'Â¡Ã‰xito!', resultado.exito[0]);\r\n            updateMP(resultado.mediosPagoUpdate);\r\n          }else{\r\n            msjalertToast('error', 'Â¡Error!', resultado.error[0]);\r\n          }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n      modalcambioMedioPago.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    function updateMP(mediosPagoUpdate:{id:string, idmediopago:string, id_factura:string, valor:string, mediopago:string}[]){\r\n      while(contentMP.firstChild)contentMP.removeChild(contentMP.firstChild);\r\n      mediosPagoUpdate.forEach(btnMP=>{\r\n        const button = document.createElement('button');\r\n        button.classList.add('btn-xs', 'btn-light', 'mr-2');\r\n        button.textContent = btnMP.mediopago;\r\n        contentMP.appendChild(button);\r\n      });\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      const f = event.target;\r\n      if (f === modalGastosIngresos || f === modalcambioMedioPago || f === miDialogoAbrirCaja || (f as HTMLInputElement).closest('.noAbrirCajon') || (f as HTMLInputElement).value === 'cancelar') {\r\n          modalGastosIngresos.close();\r\n          modalcambioMedioPago.close();\r\n          miDialogoAbrirCaja.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n    \r\n    function validarPasswordDcto():number{\r\n      const clave = claveAbrirCajon.find(c => c.clave=='clave_para_abrir_cajÃ³n_monedero');\r\n      if(clave?.valor_final!==null && inputAbrirCaja.value !== clave?.valor_final){\r\n        msjAlert('error', 'El password es invalido', (document.querySelector('#divmsjalerta3') as HTMLElement));\r\n        return 0;\r\n      }\r\n      return 1;\r\n    }\r\n  }\r\n\r\n})();\r\n","(()=>{\r\n    if(document.querySelector('.categoriasgastos')){\r\n        const btnCrearCategoriaGasto = document.querySelector('#btnCrearCategoriaGasto');\r\n        const miDialogoCategoriaGasto = document.querySelector('#miDialogoCategoriaGasto') as any;\r\n        let tablaCategoriasGastos:HTMLElement;\r\n\r\n        tablaCategoriasGastos = ($('#tablaCategoriasGastos') as any).DataTable(configdatatables25reg);\r\n\r\n        ///////////////BTN PARA CREAR CATEGORIA DE GASTO////////////////\r\n        btnCrearCategoriaGasto?.addEventListener('click', (e):void=>{\r\n            limpiarformdialog();\r\n            document.querySelector('#modalCategoriaGasto')!.textContent = \"Crear categoria de gasto\";\r\n            (document.querySelector('#btnEditarCrearCategoriaGasto') as HTMLInputElement).value = \"Crear\";\r\n            miDialogoCategoriaGasto.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        });\r\n\r\n        document.querySelector('#tablaCategoriasGastos')?.addEventListener('click', (e:Event)=>{\r\n            var btn = e.target as HTMLElement;\r\n            if(btn?.classList.contains('editarCategoriaGasto')||btn.parentElement?.classList.contains(\"editarCategoriaGasto\"))editarCategoriaGasto(e);\r\n            if(btn?.classList.contains('eliminarCategoriaGasto')||btn.parentElement?.classList.contains(\"eliminarCategoriaGasto\"))eliminarCategoriaGasto(e);   \r\n        });\r\n\r\n\r\n        ///////////////EDITAR CATEGORIA DE GASTO////////////////\r\n        function editarCategoriaGasto(e:Event){\r\n            let idcategoriagasto = (e.target as HTMLElement).parentElement?.id!;\r\n            if((e.target as HTMLElement)?.tagName === 'I')idcategoriagasto = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n            (document.querySelector('#formCrearUpdateCategoriaGasto') as HTMLFormElement).action = \"/admin/caja/editarcategoriagasto\";\r\n            document.querySelector('#modalCategoriaGasto')!.textContent = \"Actualizar categoria de gasto\";\r\n            (document.querySelector('#btnEditarCrearCategoriaGasto') as HTMLInputElement)!.value = \"Actualizar\";\r\n            (document.querySelector('#idCategoriaGasto') as HTMLInputElement).value = idcategoriagasto;\r\n            (document.querySelector('#nombre') as HTMLInputElement).value = ((e.target as HTMLElement).closest('.acciones-btns') as HTMLElement)?.dataset.categoriagasto!; \r\n            miDialogoCategoriaGasto.showModal();\r\n            document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n\r\n\r\n        function eliminarCategoriaGasto(e:Event):void{\r\n            let form = (e.target as HTMLElement).parentElement!;\r\n            if((e.target as HTMLElement).tagName === 'I')form = form.parentElement!;\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea eliminar la categoria de gasto?',\r\n                text: \"La categoria de gasto sera eliminado definitivamente.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed)(form as HTMLFormElement).submit();\r\n            });\r\n        }\r\n        \r\n        function limpiarformdialog(){\r\n            (document.querySelector('#formCrearUpdateCategoriaGasto') as HTMLFormElement)?.reset();\r\n            (document.querySelector('#formCrearUpdateCategoriaGasto') as HTMLFormElement).action = \"/admin/caja/crear_categoriaGasto\";\r\n        }\r\n\r\n        function cerrarDialogoExterno(event:Event) {\r\n            const f = event.target;\r\n        if (f === miDialogoCategoriaGasto || (f as HTMLInputElement).value === 'Salir' || (f as HTMLInputElement).value === 'Actualizar') {\r\n            miDialogoCategoriaGasto.close();\r\n            document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n        }\r\n    }\r\n\r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.cerrarcaja')){\r\n    const modalArqueocaja:any = document.querySelector(\"#modalArqueocaja\");\r\n    const Modalcerrarcaja:any = document.querySelector(\"#Modalcerrarcaja\");\r\n    const modalCambiarCaja:any = document.querySelector(\"#modalCambiarCaja\");\r\n    const btnArqueocaja = document.querySelector<HTMLButtonElement>(\"#btnArqueocaja\");\r\n    const btnCerrarcaja = document.querySelector<HTMLButtonElement>(\"#btnCerrarcaja\");\r\n    const btnImprimirDetalleCaja = document.querySelector('#btnImprimirDetalleCaja') as HTMLButtonElement;\r\n    const btnCambiarCaja = document.querySelector<HTMLButtonElement>(\"#btnCambiarCaja\");\r\n    const btnVerCierreWeb = document.querySelector('#btnVerCierreWeb') as HTMLButtonElement;\r\n    const inputsmediospago = document.querySelectorAll<HTMLInputElement>('.inputmediopago');\n    const formArqueocaja = document.querySelector('#formArqueocaja') as HTMLFormElement;\n    const formCambiarCaja = document.querySelector('#formCambiarCaja') as HTMLFormElement;\n    const inputsDenominaciones = Array.from(document.querySelectorAll<HTMLInputElement>('.denominacion'));\n    const arqueoTotal = document.querySelector<HTMLElement>('#arqueoTotal');\n    const formatoPesos = new Intl.NumberFormat('es-CO', {\n      style: 'currency',\n      currency: 'COP',\n      maximumFractionDigits: 0\n    });\n\r\n    btnArqueocaja?.addEventListener('click', ():void=>{\r\n      modalArqueocaja.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    btnCerrarcaja?.addEventListener('click', ():void=>{\r\n      Modalcerrarcaja.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    btnCambiarCaja?.addEventListener('click', ():void=>{\n      modalCambiarCaja.showModal();\n      document.addEventListener(\"click\", cerrarDialogoExterno);\n    });\n\n    inputsDenominaciones.forEach(input=>{\n      input.addEventListener('input', actualizarVistaArqueo);\n    });\n    actualizarVistaArqueo();\n    \r\n\r\n    //////////////////     Arqueo de caja      //////////////////////\r\n    formArqueocaja?.addEventListener('submit', (e:Event)=>{\r\n      e.preventDefault();\r\n      sumatoriaDenominaciones();\r\n      const datos = new FormData(formArqueocaja);\r\n      datos.append('idcierrecaja', document.querySelector('#idCierrecaja')?.textContent!);\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/arqueocaja\";  //api llamada en cajacontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\r\n              modalArqueocaja.close();\r\n              document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            }else{\r\n              msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n      \r\n    });\r\n\r\n    function sumatoriaDenominaciones():void{\n      const ef = document.querySelector('#Efectivo') as HTMLInputElement;\n      const sum = inputsDenominaciones.reduce((total, denominacion)=>(Number(denominacion.dataset.moneda)*valorEntero(denominacion.value))+total, 0);\n      ef.value = sum+'';\n      const eventInput = new Event('input');  //crea un evento\n      ef.dispatchEvent(eventInput); // se dispara el evento de manera manual, --->abajo<--, es decir cuando se introduce un valor en el campo efectivo se dispara el evento.\n    }\n\n    function actualizarVistaArqueo():void{\n      const totalArqueado = inputsDenominaciones.reduce((total, input)=>{\n        const subtotal = Number(input.dataset.moneda) * valorEntero(input.value);\n        const subtotalElemento = input.closest('.arqueo-row')?.querySelector<HTMLElement>('.arqueo-row-total');\n        if(subtotalElemento) subtotalElemento.textContent = formatoPesos.format(subtotal);\n        return total + subtotal;\n      }, 0);\n\n      if(arqueoTotal) arqueoTotal.textContent = formatoPesos.format(totalArqueado);\n    }\n\n    function valorEntero(valor:string):number{\n      return Number(valor.replace(/[^\\d]/g, '')) || 0;\n    }\n\r\n    ///////////  eventos a los inputs medios de pago de declarar valores /////////////\r\n    inputsmediospago.forEach(m=>{\r\n      m.addEventListener('input', (e)=>{  \r\n        const inputmediopago = (e.target as HTMLInputElement);\r\n        const valormediopagodeclarado:number =  parseInt((e.target as HTMLInputElement).value.replace(/[,.]/g, ''));\r\n        (async ()=>{\r\n          const datos = new FormData();\r\n          datos.append('id_mediopago', inputmediopago.dataset.idmediopago+'');\r\n          datos.append('nombremediopago', inputmediopago.name);\r\n          datos.append('valordeclarado', valormediopagodeclarado+'');\r\n          datos.append('idcierrecaja', document.querySelector('#idCierrecaja')?.textContent!);\r\n          try {\r\n              const url = \"/admin/api/declaracionDinero\";  //api llamada en cajacontrolador.php\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();\r\n              if(resultado.exito !== undefined){\r\n                inputmediopago.style.color = \"#02db02\";\r\n                inputmediopago.style.fontWeight = \"500\";\r\n                actualizarAnalisis(inputmediopago.dataset.idmediopago!, valormediopagodeclarado+'', inputmediopago.name);\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();\r\n      });\r\n    });\r\n\r\n\r\n    function actualizarAnalisis(id: string, valordeclarado: string, mediopago:string):void{\r\n      const coldeclarado = document.querySelector(`.coldeclarado[data-mediopagoid=\"${id}\"]`);\r\n      if(coldeclarado){\r\n        const coldif = coldeclarado.nextElementSibling;\r\n        coldeclarado.textContent = Number(valordeclarado).toLocaleString('es-ES', { useGrouping: true });\r\n        const colsistem = coldeclarado.previousElementSibling?.textContent?.replace(/[.,]/g, '');\r\n        coldif!.textContent = ((Number(valordeclarado) - Number(colsistem))).toLocaleString('es-ES', { useGrouping: true }); \r\n      }else{\r\n        const cuerpoanalisis = document.querySelector('.cuerpoanalisis');\r\n        cuerpoanalisis?.insertAdjacentHTML('beforeend', `\r\n          <tr class=\"${mediopago=='Efectivo'?'!border-2 !border-indigo-600':''}\">\r\n            <td class=\"\">${mediopago}</td> \r\n            <td class=\"colsistem\">0</td>\r\n            <td class=\"coldeclarado\" data-mediopagoid=\"${id}\">${Number(valordeclarado).toLocaleString('es-ES', { useGrouping: true })}</td>\r\n            <td class=\"coldif\">${Number(valordeclarado).toLocaleString('es-ES', { useGrouping: true })}</td>\r\n          </tr>`\r\n        );\r\n      }\r\n    }\r\n\r\n    function confirmarcierre(){\r\n      const datos = new FormData();\r\n      \r\n      datos.append('idcierrecaja', document.querySelector('#idCierrecaja')?.textContent!);\r\n      \r\n      (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n      Modalcerrarcaja.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      (async ()=>{\r\n        try {\r\n\r\n            const url = \"/admin/api/cierrecajaconfirmado\";  //api llamada en cajacontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\r\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n              setTimeout(() => {\r\n                (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n                window.location.href = `/admin/caja/detallecierrecaja?id=${resultado.ultimocierre[0]}`;\r\n              }, 1600);\r\n            }else{\r\n              (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n              msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n    }\r\n\r\n    const idimprimircierrecaja = document.querySelector('#idCierrecaja')?.textContent;\r\n    ///////// imprimir detalle cierre\r\n    btnImprimirDetalleCaja?.addEventListener('click', ()=>{\r\n        const ventana = window.open('/printdetallecierre?id='+idimprimircierrecaja, '_blank');\r\n        if(ventana){\r\n          ventana.onload = ()=>{\r\n            ventana?.focus();\r\n            ventana?.print();\r\n            setTimeout(() => { ventana?.close(); }, 200); // Cerrar la ventana después de unos segundos\r\n          };\r\n        }\r\n    });\r\n    ///////// ver detalle cierre en web\r\n    btnVerCierreWeb?.addEventListener('click', ()=>{\r\n        const ventana = window.open('/printdetallecierre?id='+idimprimircierrecaja, '_blank');\r\n        if(ventana)ventana.onload = ()=>ventana?.focus();\r\n    });\r\n\r\n    //////////////////     Cambio de caja      //////////////////////\r\n    formCambiarCaja?.addEventListener('submit', (e:Event)=>{\r\n      e.preventDefault();\r\n      const datos = new FormData();\r\n      datos.append('idcaja', $('#CambiarCaja').val()as string); //select del modal de cambio de caja\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/datoscajaseleccionada\";  //api llamada en cajacontrolador.php para traer datos de venta de la caja seleccionada \r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\r\n              modalCambiarCaja.close();\r\n              document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n              console.log(resultado);\r\n              //cambiar el id del cierre de caja en id=\"#idCierrecaja\"\r\n              document.querySelector('#nombreCaja')!.textContent = $('#CambiarCaja option:selected').text();\r\n              document.querySelector('#idCierrecaja')!.textContent = resultado.ultimocierre.id;\r\n              //mostar datos de la caja seleccionada\r\n              printdiscriminarmediospago(resultado.discriminarmediospagos);\r\n              printindicadores(resultado.ultimocierre);\r\n              printdetalleimpuesto(resultado.discriminarimpuesto);\r\n              //printgastosdelacaja();\r\n              //printdiscriminadoabonos();\r\n              printsobrantesfaltantes(resultado.sobrantefaltante);\r\n              printventasxusuarios(resultado.ventasxusuarios);\r\n              printventas(resultado.facturas);\r\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            }else{\r\n              msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n      \r\n    });\r\n\r\n    function printdiscriminarmediospago(data: Record<string, {idmediopago:string, mediopago:string, valor:string}>){\r\n      const tbodyMediosPago = document.querySelector('#tablaMediosPago tbody') as HTMLTableElement;\r\n      while(tbodyMediosPago.firstChild)tbodyMediosPago.removeChild(tbodyMediosPago.firstChild);\r\n      \r\n      Object.values(data).forEach((row:{idmediopago:string, mediopago:string, valor:string})=>{\r\n        const tr = document.createElement('tr');\r\n        tr.innerHTML = `<td class=\"\">${row.mediopago}</td> \r\n                        <td class=\"\"><strong>$ </strong>${Number(row.valor).toLocaleString()}</td>\r\n                      `;\r\n        tbodyMediosPago.appendChild(tr);\r\n      });\r\n    }\r\n\r\n    function printindicadores(obj:{id:string, idcaja:string, id_usuario:string, nombrecaja:string, nombreusuario:string, fechainicio:string, fechacierre:string, ncambiosaventa:string, totalcotizaciones:string, totalfacturas:string, facturaselectronicas:string, facturaspos:string, valorfe:string, descuentofe:string, valorpos:string, descuentopos:string, basecaja:string, ventasenefectivo:string, creditocapital:string, creditos:string, abonostotales:string, abonosenefectivo:string, abonoscreditos:string, abonosseparados:string, gastoscaja:string, gastosbanco:string, dineroencaja:string, domicilios:string, ndomicilios:string, realencaja:string, ingresoventas:string, totaldescuentos:string, realventas:string, valorimpuestototal:string, basegravable:string, estado:string}){\r\n      const basecaja = Number(obj.basecaja);\r\n      const ventasenefectivo = Number(obj.ventasenefectivo);\r\n      const gastoscaja = Number(obj.gastoscaja);\r\n      const domicilios = Number(obj.domicilios);\r\n      const ventasContado = Number(obj.ingresoventas); //ventas de contado ya esta aplicado los descuentos\r\n      const ventasACredito = Number(obj.creditocapital); //ventas a credito, aqui ya esta aplicado los descuentos\r\n      const totaldescuentos = Number(obj.totaldescuentos);\r\n      const abonosenefectivo = Number(obj.abonosenefectivo);\r\n      const abonostotales = Number(obj.abonostotales);\r\n\r\n      document.querySelector('#basecajaResumen')!.textContent = '$'+basecaja.toLocaleString();\r\n      document.querySelector('#gastoscajaResumen')!.textContent = '$'+gastoscaja.toLocaleString();\r\n      document.querySelector('#domiciliosResumen')!.textContent = '$'+domicilios.toLocaleString();\r\n      document.querySelector('#ingresoventasResumen')!.textContent = '$'+(ventasContado+ventasACredito).toLocaleString();\r\n      document.querySelector('#totalfacturasResumen')!.textContent = obj.totalfacturas;\r\n      document.querySelector('#totalcotizacionesResumen')!.textContent = obj.totalcotizaciones;\r\n\r\n      document.querySelector('#baseIngresoCaja')!.textContent = '+ $'+basecaja.toLocaleString();\r\n      document.querySelector('#ventasEfectivo')!.textContent = '+ $'+ventasenefectivo.toLocaleString();\r\n      document.querySelector('#abonosEfectivo')!.textContent = '+ $'+abonosenefectivo.toLocaleString();\r\n      document.querySelector('#gastosCaja')!.textContent = '- $'+gastoscaja.toLocaleString();\r\n      document.querySelector('#dineroCaja')!.textContent = '= $'+(basecaja+ventasenefectivo-gastoscaja).toLocaleString();\r\n      document.querySelector('#domicilios')!.textContent = '- $'+domicilios.toLocaleString();\r\n      document.querySelector('#realCaja')!.textContent = '= $'+(basecaja+ventasenefectivo-gastoscaja-domicilios).toLocaleString();\r\n      \r\n      document.querySelector('#ingresoVentasTotal')!.textContent = '+ $'+(ventasContado).toLocaleString();\r\n      document.querySelector('#creditos')!.textContent = '+ $'+ventasACredito.toLocaleString();\r\n      document.querySelector('#totalDescuentos')!.textContent = ' $'+totaldescuentos.toLocaleString();\r\n      document.querySelector('#totaldeventas')!.textContent = ' $'+(ventasContado+ventasACredito).toLocaleString();\r\n      document.querySelector('#abonosTotales')!.textContent = '+ $'+abonostotales.toLocaleString();\r\n      document.querySelector('#ingresoCajaDelDia')!.textContent = ' $'+(ventasContado+abonostotales).toLocaleString();\r\n      document.querySelector('#totalGastosCaja')!.textContent = '- $'+gastoscaja.toLocaleString();\r\n      document.querySelector('#totalDomicilios')!.textContent = '= $'+(domicilios).toLocaleString();\r\n      document.querySelector('#realVentas')!.textContent = '= $'+(ventasContado+ventasACredito-domicilios-gastoscaja).toLocaleString();\r\n      document.querySelector('#totalBaseGravable')!.textContent = '+ $'+Number(obj.basegravable).toLocaleString();\r\n      document.querySelector('#impuestoTotal')!.textContent = '+ $'+Number(obj.valorimpuestototal).toLocaleString();\r\n      document.querySelector('#otrosGastosBancarios')!.textContent = '+ $'+Number(obj.gastosbanco).toLocaleString();\r\n      \r\n      document.querySelector('#cantidadFacturasFE')!.textContent = obj.facturaselectronicas;\r\n      document.querySelector('#cantidadFacturasPOS')!.textContent = obj.facturaspos;\r\n\r\n      document.querySelector('#abonoscreditos')!.innerHTML = `<td class=\"\"><strong>$ </strong>${Number(obj.abonoscreditos).toLocaleString()}</td>`;\r\n      document.querySelector('#abonosseparados')!.innerHTML = `<td class=\"\"><strong>$ </strong>${Number(obj.abonosseparados).toLocaleString()}</td>`;\r\n    }\r\n\r\n    function printdetalleimpuesto(data: {basegravable:string, impuestos:string, tarifa:string, valorimpuesto:string}[]){\r\n      const tablaDetalleImpuestos = document.querySelector('#tablaDetalleImpuestos tbody') as HTMLTableElement;\r\n      while(tablaDetalleImpuestos.firstChild)tablaDetalleImpuestos.removeChild(tablaDetalleImpuestos.firstChild);\r\n      data.forEach(row=>{\r\n        const tr = document.createElement('tr');\r\n        tr.innerHTML = `<td class=\"\">${row.tarifa}</td> \r\n                        <td class=\"\"><strong>$ </strong>${Number(row.basegravable).toLocaleString()}</td>\r\n                        <td class=\"\"><strong>$ </strong>${Number(row.valorimpuesto).toLocaleString()}</td>\r\n                      `;\r\n        tablaDetalleImpuestos.appendChild(tr);\r\n      });\r\n    }\r\n\r\n    function printsobrantesfaltantes(array: {id_mediopago:string, idcierrecajaid:string, nombremediopago:string, valordeclarado:number, valorsistema:number}[]){\r\n      const sobranteFaltante = document.querySelector('#sobranteFaltante tbody') as HTMLTableElement;\r\n      while(sobranteFaltante.firstChild)sobranteFaltante.removeChild(sobranteFaltante.firstChild);\r\n      array.forEach(row=>{\r\n        const tr = document.createElement('tr');\r\n        if(row.nombremediopago=='Efectivo')tr.classList.add('!border-2', '!border-indigo-600');\r\n        tr.innerHTML = `<td class=\"\">${row.nombremediopago}</td> \r\n                        <td class=\"colsistem\">${row.valorsistema.toLocaleString()}</td>\r\n                        <td class=\"coldeclarado\" data-mediopagoid=\"${row.id_mediopago}\">${row.valordeclarado.toLocaleString()}</td>\r\n                        <td class=\"coldif\">${(row.valordeclarado - row.valorsistema).toLocaleString()}</td>\r\n                      `;\r\n        sobranteFaltante.appendChild(tr);\r\n      });\r\n    }\r\n\r\n    function printventasxusuarios(array: {Nombre:string, N_ventas:string, ventas:string}[]){\r\n      const ventasxusuarios = document.querySelector('#ventasXUsuario tbody') as HTMLTableElement;\r\n      while(ventasxusuarios.firstChild)ventasxusuarios.removeChild(ventasxusuarios.firstChild);\r\n      array.forEach(row=>{\r\n        const tr = document.createElement('tr');\r\n        tr.innerHTML = `<td class=\"\">${row.Nombre}</td>\r\n                        <td class=\"\">${row.N_ventas}</td>\r\n                        <td class=\"\"><strong>$ </strong>${Number(row.ventas).toLocaleString()}</td>\r\n                      `;\r\n        ventasxusuarios.appendChild(tr);\r\n      });\r\n    }\r\n\r\n    function printventas(array: {id:string, idcliente:string, idvendedor:string, idcaja:string, idconsecutivo:string, iddireccion:string, idtarifazona:string, idcierrecaja:string, cliente:string, vendedor:string, caja:string, tipofacturador:string, mediosdepago:{id:string, id_factura:string, mediopago:string, valor:string}[], direccion:string, tarifazona:string, totalunidades:string, recibido:string, transaccion:string, tipoventa:string, cotizacion:string, estado:string, cambioaventa:string, subtotal:string, base:string, valorimpuestototal:string, dctox100:string, descuento:string, total:string, observacion:string, departamento:string, ciudad:string, entrega:string, valortarifa:string, fechacreacion:string, fechapago:string}[]){\r\n      const tablaVentas = document.querySelector('#tablaVentas tbody') as HTMLTableElement;\r\n      while(tablaVentas.firstChild)tablaVentas.removeChild(tablaVentas.firstChild);\r\n      array.forEach((row, i)=>{\r\n        const tr = document.createElement('tr');\r\n        tr.innerHTML = `<td class=\"\">${i}</td>        \n                        <td class=\"\">${row.fechapago}</td> \n                        <td class=\"\">${row.cliente}</td> \n                        <td class=\"\">${row.id}</td>\n                        <td>\n                            <div data-estado=\"${row.estado}\" data-totalpagado=\"${row.total}\" id=\"${row.id}\" class=\"mediosdepago max-w-full flex flex-wrap gap-2\">\n                                ${row.mediosdepago.map(mp=>`<button class=\"cierre-badge cierre-badge--neutral\">${mp.mediopago}</button>`).join(' ')}\n                            </div>\n                        </td>\n                        <td><span class=\"cierre-badge ${row.estado=='Paga'?'cierre-badge--success':'cierre-badge--info'}\">${row.estado}</span></td>\n                        <td class=\"cierre-number\">$ ${Number(row.subtotal).toLocaleString()}</td>\n                        <td class=\"cierre-number\">$ ${Number(row.total).toLocaleString()}</td>\n                        <td class=\"accionestd\"><div class=\"acciones-btns\" id=\"${row.id}\">\n                                <a class=\"cierre-table-action\" href=\"/admin/caja/ordenresumen?id=${row.id}\">Ver</a> <button class=\"cierre-badge cierre-badge--neutral\"><i class=\"fa-solid fa-print\"></i></button>\n                            </div>\n                        </td>\n                      `;\n        tablaVentas.appendChild(tr);\r\n      });\r\n    }\r\n\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === modalArqueocaja || event.target === Modalcerrarcaja || event.target === modalCambiarCaja || (event.target as HTMLInputElement).value === 'Cancelar' || (event.target as HTMLElement).closest('.salircerrarcaja') || (event.target as HTMLElement).closest('.finCerrarcaja')) {\r\n          modalArqueocaja.close();\r\n          Modalcerrarcaja.close();\r\n          modalCambiarCaja.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n\r\n          if((event.target as HTMLElement).closest('.finCerrarcaja')){  //Cuando se hace el cierre de caja\r\n            confirmarcierre();\r\n          }\r\n      }\r\n    }\r\n  }\r\n\r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.detallecierrecaja')){\r\n    const btnImprimirDetalleCaja = document.querySelector('#btnImprimirDetalleCaja') as HTMLButtonElement;\r\n    const btnVerCierreWeb = document.querySelector('#btnVerCierreWeb') as HTMLButtonElement;\r\n    const btnVerCierreWs = document.querySelector('#btnVerCierreWs') as HTMLButtonElement;\r\n\r\n    let printerBT:string = getParam.impresora_principal_de_CAJA_para_Android_por_BT.valor_final;\r\n    //capturar el id del cierre de caja por la url\r\n    const parametrosURL = new URLSearchParams(window.location.search);\r\n    const id:string = parametrosURL.get('id')??'';\r\n\r\n    if(id==''||id==null||isNaN(Number(id)))return;\r\n\r\n    ///////// imprimir detalle cierre\r\n    btnImprimirDetalleCaja?.addEventListener('click', ()=>{\r\n      if(id!=''){\r\n          const ventana = window.open('/printdetallecierre?id='+id, '_blank');\r\n          if(ventana){\r\n              ventana.onload = ()=>{\r\n                  ventana?.focus();\r\n                  ventana?.print();\r\n                  setTimeout(() => { ventana?.close(); }, 200); // Cerrar la ventana después de unos segundos\r\n              };\r\n          }\r\n      }else{\r\n        msjalertToast('error', '¡Error!', 'Error al generar detalle de cierre.');\r\n      }\r\n    });\r\n\r\n\r\n    ///////// ver detalle cierre en web\r\n    btnVerCierreWeb?.addEventListener('click', ()=>{\r\n        const ventana = window.open('/printdetallecierre?id='+id, '_blank');\r\n        if(ventana)ventana.onload = ()=>ventana?.focus();\r\n    });\r\n\r\n\r\n    ///////// ver y enviar detalle de cierre por whatsapp\r\n    btnVerCierreWs?.addEventListener('click', async()=>{\r\n        const url = \"/admin/api/ws/sendtextDetalleCierreCaja?id=\"+id; //llamado a la API REST para enviar detalle de cierre por ws\r\n        try {\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json();\r\n          if(resultado && resultado.code === 200 && !resultado.error){\r\n            msjalertToast('success', '¡Éxito!', 'Mensaje detalle de cierre de caja enviado');\r\n          }else{\r\n            msjalertToast('error', '¡Error!', 'Error al enviar mensaje de cierre de caja');\r\n          }\r\n        } catch (error) {\r\n          console.log(error);\r\n        }\r\n    });\r\n\r\n\r\n    ////////////// Evento a la tabla lista de pedidos ///////////////\r\n    document.querySelector('#tablaListaPedidos')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      //if(target?.classList.contains(\"mediosdepago\")||target.parentElement?.classList.contains(\"mediosdepago\"))cambiomediopago(target);\r\n      if(target?.classList.contains(\"printPOS\")||target.parentElement?.classList.contains(\"printPOS\"))printPOS(target);\r\n    });\r\n\r\n\r\n    async function printPOS(target: HTMLElement){\r\n      let idfactura = target.parentElement!.id;\r\n      if(target.tagName === 'I')idfactura = target.parentElement!.parentElement!.id;\r\n      //obtener factura por fetch\r\n      try{\r\n        const url = \"/admin/api/getInvoice?id=\"+idfactura; //llamado a la API REST - cajacontrolador y se trae detalle de factura \r\n        const respuesta = await fetch(url); \r\n        const resultado:DataInvoice = await respuesta.json();\r\n        const isAndroid = /Android/i.test(navigator.userAgent);\r\n        if(printerBT === '1'){\r\n          const builder = new InvoiceTicketBuilder(resultado);\r\n          const ticket = await builder.generate(true); //true para version buffer bytes\r\n          const base64 = bytesToBase64(ticket);\r\n          if(isAndroid)window.location.href = `rawbt:base64,${base64}`;\r\n\r\n        }else{\r\n          const dataPrinter = {\r\n            businessId: resultado.negocio,\r\n            sucursal: resultado.sucursal,\r\n            printerName: 'CAJA',\r\n            tipoTicket: 'ticket',\r\n            content: resultado\r\n          };\r\n          try {\r\n            const url = \"https://servidorimpresionposws-production.up.railway.app/api/print/printJob\"; //llamado a la API server print nodejs/ts\r\n            const respuesta = await fetch(url, {\r\n              method: 'POST',\r\n              headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n              body: JSON.stringify(dataPrinter)\r\n            });\r\n            const resultado = await respuesta.json();\r\n            console.log(resultado);\r\n          } catch (error) {\r\n            console.log(error);\r\n          }\r\n        }\r\n\r\n        window.open(\"/admin/printPDFPOS?id=\" + idfactura, \"_blank\");  //controlador printcontrolador\r\n      }catch(error){\r\n        console.log(error);\r\n      }\r\n    }\r\n\r\n  }\r\n\r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.fechazetadiario')){\r\n\r\n    const btnsmultiselect = document.querySelectorAll<HTMLElement>('.btnmultiselect');\r\n    const selectedcajas = document.querySelectorAll<HTMLLIElement>('.selectedcajas');\r\n    const consultarZDiario = document.querySelector('#consultarZDiario') as HTMLButtonElement;\r\n    const tbodyMediosPago = document.querySelector('#tablaMediosPago tbody') as HTMLTableElement;\r\n    const base = document.querySelector('#base') as HTMLElement;\r\n    const valorImpuestoTotal = document.querySelector('#valorImpuestoTotal') as HTMLElement;\r\n    const ingresoVentas = document.querySelector('#ingresoVentas') as HTMLElement;\r\n    const totalDescuentos = document.querySelector('#totalDescuentos') as HTMLElement;\r\n    const realVentas = document.querySelector('#realVentas') as HTMLElement;\r\n    const cantidadElectronicas = document.querySelector('#cantidadElectronicas') as HTMLElement;\r\n    const cantidadPOS = document.querySelector('#cantidadPOS') as HTMLElement;\r\n    const valorElectronicas = document.querySelector('#valorElectronicas') as HTMLElement;\r\n    const valorPOS = document.querySelector('#valorPOS') as HTMLElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\";\r\n\r\n    //evento a los select drop dawn para abrir y cerrar\r\n    btnsmultiselect.forEach((btnmultiselect, index) =>{\r\n      btnmultiselect.addEventListener('click', (e:Event)=>{\r\n        cerrarlosmultiselect(index);\r\n        btnmultiselect.classList.toggle('open');\r\n      });\r\n    });\r\n    function cerrarlosmultiselect(index:number){\r\n      btnsmultiselect.forEach((element, i) =>{\r\n        if(i != index || !element.classList.contains('open'))element.classList.remove('open');\r\n      });\r\n    }\r\n    document.querySelector('.fechazetadiario')?.addEventListener('click', (e:Event)=>{\r\n      if(!(e.target as HTMLElement).closest('.btnmultiselect')&&!(e.target as HTMLElement).closest('.list-items')){\r\n        const btnmultiselect = document.querySelector('.open');\r\n        if(btnmultiselect)btnmultiselect.classList.toggle('open');\r\n      }\r\n    });\r\n    // mostrar el nombre de las cajas,segun se selecciona\r\n    selectedcajas.forEach(c=>{c.addEventListener('click', cajas_seleccionadas);});\r\n\r\n    function cajas_seleccionadas(){\r\n      const inputscaja = document.querySelectorAll<HTMLInputElement>('input.selectedcajas[type=\"checkbox\"]:checked');\r\n      const cajastext = document.querySelector('#cajastext') as HTMLElement;\r\n      cajastext.textContent = \". \";\r\n      inputscaja.forEach((inputcaja, i) =>{\r\n        if(i<inputscaja.length-1){\r\n          cajastext.textContent += inputcaja.nextElementSibling?.textContent!+' - ';\r\n        }else{\r\n          cajastext.textContent += inputcaja.nextElementSibling?.textContent!;\r\n        }\r\n      });\r\n    }\r\n\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        (document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        (document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    consultarZDiario.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      const cajas = document.querySelectorAll<HTMLInputElement>('input.selectedcajas[type=\"checkbox\"]:checked');\r\n      const facturadores = document.querySelectorAll<HTMLInputElement>('input.facturador[type=\"checkbox\"]:checked');\r\n      \r\n      const valuecajas:string[] = Array.from(cajas).map(c=>c.value);\r\n      const valuefacturadores:string[] = Array.from(facturadores).map(f=>f.value);\r\n\r\n      (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n      (async ()=>{\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', fechainicio);\r\n        datos.append('fechafin', fechafin);\r\n        datos.append('cajas', JSON.stringify(valuecajas));\r\n        datos.append('facturadores', JSON.stringify(valuefacturadores));\r\n        try {\r\n            const url = \"/admin/api/consultafechazetadiario\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            console.log(resultado);\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n           reiniciarTablas();\r\n           imprimirtablaMediosPago(resultado.datosmediospago);\r\n           imprimirIngresos(resultado.datosventa);\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n    });\r\n\r\n\r\n    function imprimirtablaMediosPago(datosmediospago:{id:string, nombre:string, valor:string}[]){\r\n      datosmediospago.forEach(mp =>{\r\n        const tr = document.createElement('tr');\r\n        tr.innerHTML = `<td class=\"\">${mp.nombre}</td> \r\n                        <td class=\"\">$${Number(mp.valor).toLocaleString()}</td>`;\r\n        tbodyMediosPago.appendChild(tr);\r\n      });\r\n    }\r\n\r\n    function imprimirIngresos(datosventa:{subtotalventa:string, base:string, valorimpuestototal:string, totalventa:string, ELECTRONICAS:string, POS:string, total_ELECTRONICAS:string, total_POS:string}){\r\n      base.textContent = '$'+Number(datosventa.base).toLocaleString();\r\n      valorImpuestoTotal.textContent = '$'+Number(datosventa.valorimpuestototal).toLocaleString();\r\n      ingresoVentas.textContent = '$'+Number(datosventa.subtotalventa).toLocaleString();\r\n      totalDescuentos.textContent = '$'+(Number(datosventa.subtotalventa)-Number(datosventa.totalventa)).toLocaleString();\r\n      realVentas.textContent = '$'+Number(datosventa.totalventa).toLocaleString();\r\n      cantidadElectronicas.textContent = datosventa.ELECTRONICAS;\r\n      cantidadPOS.textContent = datosventa.POS;\r\n      valorElectronicas.textContent = '$'+Number(datosventa.total_ELECTRONICAS).toLocaleString();\r\n      valorPOS.textContent = '$'+Number(datosventa.total_POS).toLocaleString();\r\n    }\r\n\r\n    function reiniciarTablas(){\r\n      while(tbodyMediosPago.firstChild)tbodyMediosPago.removeChild(tbodyMediosPago.firstChild);\r\n      ingresoVentas.textContent = '';\r\n      totalDescuentos.textContent = \"\";\r\n      realVentas.textContent = \"\";\r\n      cantidadElectronicas.textContent = '';\r\n      cantidadPOS.textContent = '';\r\n      valorElectronicas.textContent = '';\r\n      valorPOS.textContent = '';\r\n    }\r\n\r\n  }\r\n\r\n})();","(():void=>{\r\n    if(document.querySelector('.ordenresumen')){\r\n      const POS = (window as any).POS;\r\n      const miDialogoFacturar:any = document.querySelector(\"#miDialogoFacturar\");\r\n      const miDialogoEliminarOrden = document.querySelector('#miDialogoEliminarOrden') as any;\r\n      const btnfacturar = document.querySelector<HTMLButtonElement>(\"#btnfacturar\");\r\n      const btneliminarorden = document.querySelector('#btneliminarorden') as HTMLButtonElement;\r\n      const btnEmisor = document.querySelector('#btnEmisor') as HTMLButtonElement;\r\n      const btnSelectVendedor = document.querySelector('#btnSelectVendedor') as HTMLButtonElement;\r\n      const btnCaja = document.querySelector('#caja') as HTMLSelectElement;\r\n      const btnTipoFacturador = document.querySelector('#facturador') as HTMLSelectElement;\r\n      const mediospago = document.querySelectorAll('.mediopago');\r\n      const btnsdevolverinv = document.querySelectorAll<HTMLInputElement>('input[name=\"devolverinventario\"]'); //radio buttom\r\n      const inputsInv = document.querySelectorAll<HTMLInputElement>('.inputInv');\r\n      const printcarta = document.querySelector('#printcarta');\r\n      const printcotizacion = document.querySelector('#printcotizacion');\r\n      const btnDespachar = document.querySelector<HTMLButtonElement>(\"#btnDespachar\");\r\n      const btnMasOpciones = document.querySelector('#btnMasOpciones') as HTMLInputElement;\r\n      const btnImprimirTirilla = document.querySelector('#btnImprimirTirilla') as HTMLInputElement;\r\n      const btnOrdenEnvio = document.querySelector('#btnOrdenEnvio') as HTMLInputElement;\r\n      const miDialogoMasOpciones = document.querySelector('#miDialogoMasOpciones') as any;\r\n      const numOrden = document.querySelector('#numOrden');\r\n      const referenciaFactura = document.querySelector('#referenciaFactura');\r\n      const miDialogoRemision = document.querySelector('#miDialogoRemision') as HTMLDialogElement;\r\n      const miDialogoSelectUser = document.querySelector('#miDialogoSelectUser') as HTMLDialogElement;\r\n      const miDialogoSelectEmisor = document.querySelector('#miDialogoSelectEmisor') as HTMLDialogElement;\r\n      const enviarEmail = document.querySelector('#enviarEmail') as HTMLButtonElement;\r\n      const miDialogoEnviarEmailCliente = document.querySelector('#miDialogoEnviarEmailCliente') as any;\r\n      //const miDialogoDespachar = document.querySelector('#miDialogoDespachar') as any;\r\n      const miDialogoProductoCompuesto = document.querySelector('#miDialogoProductoCompuesto') as any;\r\n      const selectEmisor = document.querySelector('#selectEmisor') as HTMLInputElement;\r\n      const inputEliminarClave = document.querySelector('#inputEliminarClave') as HTMLInputElement;\r\n      const tablaDetalleInsumos = document.querySelector('#tablaDetalleInsumos tbody') as HTMLBodyElement;\r\n\r\n      const valorTotal = {subtotal: 0, impuesto: 0, dctox100: 0, descuento: 0, idtarifa: 0, valortarifa: 0, total: 0}; //datos global de la venta\r\n      const mapMediospago = new Map();\r\n\r\n      interface clavesApi {\r\n        clave:string,\r\n        valor_default:string|null,\r\n        valor_final:string|null,\r\n        valor_local:string|null\r\n      };\r\n\r\n      let claveEliminarOrden:clavesApi[];\r\n      const idorden = (document.querySelector('#idorden') as HTMLElement).dataset.idorden;\r\n\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/getPasswords\"; //llamado a la API REST\r\n            const respuesta = await fetch(url); \r\n            const resultado = await respuesta.json(); \r\n            claveEliminarOrden = resultado;\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n  \r\n      valorTotal.subtotal = Number(document.querySelector('#subTotal')?.textContent);\r\n      valorTotal.total = Number(document.querySelector('#total')?.textContent?.replace(/[^\\d]/g, ''));\r\n      \r\n      selectFacturadorSegunCaja(btnCaja);\r\n    \r\n      btnCaja.addEventListener('change', (e:Event)=>selectFacturadorSegunCaja(e.target as HTMLSelectElement));\r\n    \r\n      function selectFacturadorSegunCaja(z:HTMLSelectElement){\r\n        $('#facturador').val(z.options[z.selectedIndex].dataset.idfacturador??'1');\r\n      }\r\n\r\n      printcarta?.addEventListener('click', ()=>{\r\n        //leer parametros de url\r\n        const parametrosURL = new URLSearchParams(window.location.search);\r\n        const id = parametrosURL.get('id');\r\n        if(id==''||id==null||isNaN(Number(id)))return;\r\n        const ventana = window.open('/printfacturacarta?id='+id, '_blank');\r\n        if(ventana){\r\n          ventana.onload = ()=>{\r\n            ventana?.focus();\r\n            ventana?.print();\r\n            setTimeout(() => { ventana?.close(); }, 200); // Cerrar la ventana después de unos segundos\r\n          };\r\n        }\r\n      });\r\n\r\n      printcotizacion?.addEventListener('click', ()=>{\r\n        //leer parametros de url\r\n        const parametrosURL = new URLSearchParams(window.location.search);\r\n        const id = parametrosURL.get('id');\r\n        if(id==''||id==null||isNaN(Number(id)))return;\r\n        const ventana = window.open('/printcotizacion?id='+id, '_blank');\r\n        if(ventana){\r\n          ventana.onload = ()=>{\r\n            ventana?.focus();\r\n            ventana?.print();\r\n            setTimeout(() => { ventana?.close(); }, 200); // Cerrar la ventana después de unos segundos\r\n          };\r\n        }\r\n      });\r\n\r\n      btnfacturar?.addEventListener('click', ()=>{\r\n        /*if(modalidadEntrega.textContent === \": Domicilio\" && (selectCliente.value =='1' || selectCliente.value =='2' || !dirEntrega.value)){\r\n          msjAlert('error', 'Cliente o direccion no seleccionado', (document.querySelector('#divmsjalerta1') as HTMLElement));\r\n          return;\r\n        }*/\r\n        /*if(carrito.length){*/\r\n          subirModalPagar();\r\n          miDialogoFacturar.showModal();\r\n        //}\r\n      });\r\n      \r\n\r\n      btneliminarorden?.addEventListener('click', ()=>{\r\n          miDialogoEliminarOrden.showModal();\r\n      });\r\n\r\n\r\n      enviarEmail?.addEventListener('click', ()=>{\r\n        miDialogoEnviarEmailCliente.showModal();\r\n      });\r\n\r\n\r\n      document.querySelector('#formEnviarEmailCliente')?.addEventListener('submit', (e:Event)=>{\r\n        e.preventDefault();\r\n        if(idorden!=null && Number(idorden)>0){\r\n          const datos = new FormData();\r\n          datos.append('id', idorden);\r\n          datos.append('email', (document.querySelector('#inputEmail') as HTMLInputElement).value);\r\n          miDialogoEnviarEmailCliente.close();\r\n          (async ()=>{\r\n            try {\r\n              const url = \"/admin/api/sendOrdenEmailToCustemer\";  //va al controlador cajacontrolador para enviar detalle de orden por email.\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos});\r\n              const resultado = await respuesta.json();\r\n              if(resultado.exito!=undefined){\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n          })();\r\n        }\r\n      });\r\n\r\n\r\n      btnDespachar?.addEventListener('click', ()=>{\r\n        if(Number.isNaN(idorden))return;\r\n        Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--dispatch',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--confirm',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          icon: 'question',\n          title: 'Desea despachar la orden?',\n          text: \"La orden sera registrada como despachada y entregada.\",\n          showCancelButton: true,\n          confirmButtonText: 'Despachar',\n          cancelButtonText: 'Cancelar',\n          buttonsStyling: false,\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n            (async ()=>{\r\n              try {\r\n                const url = \"/admin/api/caja/despacharOrden?id=\"+idorden; //llamado a la API REST\r\n                const respuesta = await fetch(url); \r\n                const resultado = await respuesta.json();\r\n                if(resultado.exito !== undefined){\r\n                  msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                  (document.querySelector('#textEstado') as HTMLParagraphElement).textContent = \"Domicilio entregado\";\r\n                }else{\r\n                  msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                }\r\n              } catch (error) {\r\n                  console.log(error);\r\n              }\r\n            })();\r\n          }\r\n        });\r\n      });\r\n\r\n\r\n      //apertura de la ventana modal para las opcionesde traslado de inventario\r\n      btnMasOpciones.addEventListener('click', ()=>{\r\n          miDialogoMasOpciones.showModal();\r\n      });\r\n\r\n\r\n      btnImprimirTirilla.addEventListener('click', ()=>{\r\n        if(Number.isNaN(idorden))return;\r\n        miDialogoMasOpciones.close();\r\n        window.open(\"/admin/printPDFPOS?id=\" + idorden, \"_blank\");  //controlador printcontrolador\r\n      });\r\n\r\n\r\n      btnOrdenEnvio?.addEventListener('click', ()=>{\r\n        miDialogoRemision.showModal();\r\n      });\r\n\r\n      /////////  CAMBIAR EMISOR  /////////////\r\n      btnEmisor.addEventListener('click', (e)=>{\r\n        miDialogoSelectEmisor.showModal();\r\n      });\r\n\r\n      /////////  CAMBIAR USUARIO VENDEDOR Y COMISION  /////////////\r\n      btnSelectVendedor.addEventListener('click', (e)=>{\r\n        miDialogoSelectUser.showModal();\r\n      });\r\n\r\n      document.querySelector('#btnEditarCrearSelectUser')?.addEventListener('submit', (e:Event)=>{\r\n        e.preventDefault();\r\n        /*try {\r\n            const url = `/admin/api/ventas/detalleProductoCompuesto?idproducto=${idproducto}&idfactura=${idventa}`; //llamado a la API REST ventascontrolador, detalle producto compuesto\r\n            const respuesta = await fetch(url); \r\n            const resultado = await respuesta.json();\r\n            detalleInsumos(resultado);\r\n          } catch (error) {\r\n              console.log(error);\r\n          }*/\r\n      });\r\n\r\n\r\n      selectEmisor.addEventListener('click', (e:Event)=>{\r\n        const target = e.target as HTMLSelectElement;\r\n        const opcion = document.querySelector(`#selectCaja option[data-emisor=\"${target.value}\"]`) as HTMLOptionElement;\r\n        if(opcion) {\r\n          (document.querySelector('#selectCaja') as HTMLSelectElement).value = opcion.value;\r\n        }\r\n      });\r\n\r\n\r\n      ////////////////////FORM PARA CAMBIAR DE EMISOR\r\n      document.querySelector('#formUpdateSelectEmisor')?.addEventListener('submit', async (e:Event)=>{\r\n        e.preventDefault();\r\n        const inputcambiarEmisor = document.querySelector('#inputcambiarEmisor') as HTMLInputElement;\r\n        const v:number = validarPassword('clave_para_cambiar_emisor_de_una_factura', 'divmsjalertaSelectEmisor', inputcambiarEmisor);\r\n        if(!v || idorden==null || Number(idorden)<=0){\r\n          return;\r\n        }\r\n        miDialogoSelectEmisor.close();\r\n        inputcambiarEmisor.value = '';\r\n        const datos = new FormData();\r\n        datos.append('id', idorden);\r\n        datos.append('idemisor', selectEmisor.value);\r\n        datos.append('idcaja', (document.querySelector('#selectCaja') as HTMLSelectElement).value);\r\n        try {\r\n          const url = \"/admin/api/caja/cambiarEmisor\";  //va al controlador cajacontrolador para cambiar el emisor en tabla creditos y facturas.\r\n          const respuesta = await fetch(url, {method: 'POST', body: datos});\r\n          const resultado = await respuesta.json();\r\n          if(resultado.exito!=undefined){\r\n            msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            (document.querySelector('#nitEmisor') as HTMLSpanElement).textContent = 'NIT: '+resultado.emisor.nit;\r\n            (document.querySelector('#nombreEmisor') as HTMLSpanElement).textContent = resultado.emisor.negocio?resultado.emisor.negocio:resultado.emisor.nombre;\r\n          }else{\r\n            msjalertToast('error', '¡Error!', resultado.error[0]);\r\n          }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      });\r\n\r\n\r\n      ///////////////////// Logica botones devolver inventario ////////////////////////\n      btnsdevolverinv.forEach(inv=>{ //evento a los radiobutton\n        inv.addEventListener('change', (e:Event)=>{\n          const devolverInventario = (e.target as HTMLInputElement).value === \"1\";\n          document.querySelector('#productsInv')?.classList.toggle('hidden', !devolverInventario);\n          if(devolverInventario){\n            document.querySelectorAll('.inputInv').forEach(x=>x.setAttribute('required', ''));\n          }else{\n            document.querySelectorAll('.inputInv').forEach(x=>x.removeAttribute('required'));\n          }\n        });\r\n      });\r\n\r\n      inputsInv.forEach(inputinv =>{\r\n        inputinv.addEventListener('input', e=>{\r\n          const qty = (e.target as HTMLInputElement);\r\n          if(qty.value != qty.parentElement?.dataset.qty){\r\n            qty.classList.add('border-2', 'border-rose-600');\r\n            if(!document.querySelector('.alerta'))\r\n              msjAlert('error', 'Cantidad diferente a devolver a inventario', (document.querySelector('#divmsjalerta1') as HTMLElement));\r\n          }else{\r\n            qty.classList.remove('border-2', 'border-rose-600');\r\n            document.querySelector('.alerta')?.remove();\r\n          }\r\n        });\r\n      });\r\n\r\n      /////////////////////  logica del modal de pago  //////////////////////////\r\n      function subirModalPagar(){\r\n        document.querySelector('#totalPagar')!.textContent = `${valorTotal.total.toLocaleString()}`;\r\n        //como se puede cerrar el modal y aumentar los productos, hay calcular los inputs\r\n        let totalotrosmedios = 0;\r\n        mediospago.forEach((item, index)=>{\r\n          if(index>0)totalotrosmedios += parseInt((item as HTMLInputElement).value.replace(/[,.]/g, ''));\r\n        });\r\n\r\n        if(valorTotal.total<totalotrosmedios){\r\n          totalotrosmedios = 0;\r\n          mapMediospago.clear();\r\n          $('.mediopago').val(0);\r\n        }\r\n        (document.querySelector('.Efectivo')! as HTMLInputElement).value =  `${(valorTotal.total-totalotrosmedios).toLocaleString()}`;\r\n        mapMediospago.set('1', valorTotal.total-totalotrosmedios);\r\n        if(valorTotal.total-totalotrosmedios == 0 && mapMediospago.has('1'))mapMediospago.delete('1');\r\n        calcularCambio(document.querySelector<HTMLInputElement>('#recibio')!.value);\r\n      }\r\n  \r\n      //eventos a los inputs medios de pago\r\n      mediospago.forEach(m=>{m.addEventListener('input', (e)=>{ calcularmediospago(e);});}); \r\n\r\n      function calcularmediospago(e:Event){\r\n        let totalotrosmedios = 0;\r\n        mediospago.forEach((item, index)=>{ //sumar todos los medios de pago menos el efectivo\r\n          if(index>0)totalotrosmedios += parseInt((item as HTMLInputElement).value.replace(/[,.]/g, ''));\r\n        });\r\n        if(totalotrosmedios<=valorTotal.total){\r\n          mapMediospago.set('1', valorTotal.total-totalotrosmedios);\r\n          if(valorTotal.total-totalotrosmedios == 0 && mapMediospago.has('1'))mapMediospago.delete('1');\r\n          mapMediospago.set((e.target as HTMLInputElement).id, parseInt((e.target as HTMLInputElement).value.replace(/[,.]/g, '')));\r\n          if((e.target as HTMLInputElement).value == '0' && mapMediospago.has((e.target as HTMLInputElement).id))mapMediospago.delete((e.target as HTMLInputElement).id);\r\n        }else{ //si la suma de los medios de pago superan el valor total, toma el ultimo input digitado y lo reestablece a su ultimo valor\r\n          if(mapMediospago.has((e.target as HTMLInputElement).id)){\r\n            (e.target as HTMLInputElement).value = mapMediospago.get((e.target as HTMLInputElement).id).toLocaleString();\r\n          }else{\r\n            (e.target as HTMLInputElement).value = '0';\r\n          }\r\n        }\r\n        (mediospago[0] as HTMLInputElement).value = (mapMediospago.get('1')??0).toLocaleString();\r\n        calcularCambio(document.querySelector<HTMLInputElement>('#recibio')!.value);\r\n      }\r\n\r\n      /////////////////////  evento al input recibido  //////////////////////////\r\n      document.querySelector<HTMLInputElement>('#recibio')?.addEventListener('input', (e)=>{\r\n        calcularCambio((e.target as HTMLInputElement).value);\r\n      });\r\n      function calcularCambio(recibido:string):void{\r\n        recibido = recibido.replace(/[,.]/g, '');\r\n        if(Number(recibido)>mapMediospago.get('1')){\r\n          (document.querySelector('#cambio') as HTMLElement).textContent = (Number(recibido)-mapMediospago.get('1')).toLocaleString()+'';\r\n          return;\r\n        }\r\n        (document.querySelector('#cambio') as HTMLElement).textContent = '0';\r\n      }\r\n\r\n\r\n      ////////////////// evento al bton pagar del modal facturar //////////////////////\r\n      document.querySelector('#formfacturarCotizacion')?.addEventListener('submit', e=>{\r\n        e.preventDefault();\r\n        procesarpedido('Guardado');\r\n      });\r\n\r\n      async function procesarpedido(estado:string){ //////PROCESAR PAGO DE COTIZACION SiN CAMBIAR DATOS DE LOS PRODUCTOS//////\r\n        const imprimir = document.querySelector('input[name=\"imprimir\"]:checked') as HTMLInputElement;\r\n        const datos = new FormData();\r\n        datos.append('id', idorden!);\r\n        datos.append('idemisor', btnCaja.selectedOptions[0].dataset.idemisor??'');\r\n        //datos.append('idcliente', (document.querySelector('#selectCliente') as HTMLSelectElement).value);\r\n        //datos.append('idvendedor', (document.querySelector('#vendedor') as HTMLInputElement).dataset.idvendedor!);\r\n        datos.append('idcaja', btnCaja.value);\r\n        datos.append('idconsecutivo', btnTipoFacturador.value);\r\n        //datos.append('iddireccion', dirEntrega.value);\r\n        //datos.append('idtarifazona', valorTotal.idtarifa+'');\r\n        //datos.append('cliente', selectCliente.options[selectCliente.selectedIndex].textContent!);\r\n        //datos.append('vendedor', (document.querySelector('#vendedor') as HTMLInputElement).value);\r\n        datos.append('caja', (document.querySelector('#caja option:checked') as HTMLSelectElement).textContent!);\r\n        datos.append('tipofacturador', btnTipoFacturador.options[btnTipoFacturador.selectedIndex].textContent!);\r\n        //datos.append('direccion', dirEntrega.options[dirEntrega.selectedIndex].text);\r\n        //datos.append('tarifazona', nombretarifa||'');\r\n        //datos.append('carrito', JSON.stringify(carrito));\r\n        //datos.append('totalunidades', totalunidades.textContent!);\r\n        //datos.append('mediosPago', JSON.stringify(Object.fromEntries(mapMediospago)));\r\n        datos.append('mediosPago', JSON.stringify(Array.from(mapMediospago, ([idmediopago, valor])=>({idmediopago, id_factura:0, valor}))));\r\n        datos.append('recibido', document.querySelector<HTMLInputElement>('#recibio')!.value);\r\n        datos.append('transaccion', '');\r\n        datos.append('estado', estado);\r\n        datos.append('cambioaventa', '1');  //cambioaventa por defecto es 0\r\n        //datos.append('subtotal', valorTotal.subtotal+'');\r\n        //datos.append('impuesto', valorTotal.impuesto+'');\r\n        //datos.append('dctox100',valorTotal.dctox100+'');\r\n        //datos.append('descuento',valorTotal.descuento+'');\r\n        //datos.append('total', valorTotal.total.toString());\r\n        datos.append('observacion', document.querySelector<HTMLTextAreaElement>('#observacion')!.value);\r\n        //datos.append('departamento', '');\r\n        //datos.append('ciudad', (document.querySelector('#ciudadEntrega') as HTMLInputElement).value);\r\n        //datos.append('entrega', modalidadEntrega.textContent!.replace(': ', ''));\r\n        //datos.append('valortarifa', valorTotal.valortarifa+'');\r\n        //datos.append('datosAdquiriente', JSON.stringify(POS.gestionarAdquiriente.datosAdquiriente));\r\n        //datos.append('opc1', '');\r\n        //datos.append('opc2', '');\r\n        try {\r\n            const url = \"/admin/api/facturarCotizacion\";  //va al controlador ventascontrolador\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\r\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n              /////// reinciar modulo de ventas\r\n              ordenpagada();\r\n              miDialogoFacturar.close();\r\n              if(resultado.idfactura && imprimir.value === '1')printTicketPOS(resultado.idfactura);\r\n              if(btnTipoFacturador.options[btnTipoFacturador.selectedIndex].dataset.idtipofacturador == '1'){ \r\n                const resDian = await POS.sendInvoiceAPI.sendInvoice(resultado.idfactura); //llama a la funcion que esta en ts/ventas/ventas.sendinvoice.ts\r\n                console.log(resDian);\r\n              }\r\n            }else{\r\n              msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      }\r\n  \r\n      function printTicketPOS(idfactura:string){\r\n        setTimeout(() => {\r\n          window.open(\"/admin/printPDFPOS?id=\" + idfactura, \"_blank\");\r\n        }, 1200);\r\n      }\r\n\r\n      function ordenpagada(){\r\n        if(btnfacturar)btnfacturar.style.display = \"none\";\r\n        (document.querySelector('#abrirOrden') as HTMLElement).style.display = \"none\";\r\n        (document.querySelector('#estadoOrden') as HTMLElement).textContent = \"Paga\";\r\n      }\r\n  \r\n      function cerrarDialogoSeguro(dialogo:HTMLDialogElement | null | undefined):void {\n        if(dialogo?.open)dialogo.close();\n      }\n\n      function cerrarDialogoExterno(event:Event) {\n        const f = event.target as HTMLElement;\n        if (f === miDialogoFacturar || f === miDialogoEliminarOrden || f === miDialogoEnviarEmailCliente || f === miDialogoMasOpciones || f === miDialogoRemision || f === miDialogoSelectEmisor || f === miDialogoSelectUser || f === miDialogoProductoCompuesto || f.id == 'btnXCerrarMasOpciones' || f.id == 'btnXCerrarRemision' || (f as HTMLInputElement).value === 'cancelar' || (f as HTMLInputElement).value === 'Salir' || f.closest('.noeliminar') || f.id == 'btnXCerrarModalProductoCompuesto' || f.id == 'btnXCerrarModalSelectUser' || f.id == 'btnXCerrarModalSelectEmisor') {\n            cerrarDialogoSeguro(miDialogoFacturar);\n            cerrarDialogoSeguro(miDialogoEliminarOrden);\n            cerrarDialogoSeguro(miDialogoEnviarEmailCliente);\n            cerrarDialogoSeguro(miDialogoMasOpciones);\n            cerrarDialogoSeguro(miDialogoRemision);\n            cerrarDialogoSeguro(miDialogoProductoCompuesto);\n            cerrarDialogoSeguro(miDialogoSelectUser);\n            cerrarDialogoSeguro(miDialogoSelectEmisor);\n        }\n      }\n\r\n      //evento al boton confirmar para eliminar orden\r\n      document.querySelector('.sieliminar')?.addEventListener('click', (event:Event)=>{\r\n        const f = event.target;\r\n        if((f as HTMLInputElement).closest('.sieliminar'))eliminarorden();\r\n      });\r\n\r\n\r\n      function eliminarorden():void{\r\n        ///////*** crear arreglo de obj de los productos y sus cantidades ***///////\r\n        type producto = {id:string, idproducto:string, nombre:string, tipoproducto:string, tipoproduccion:string, rendimientoestandar:string, cantidad: string , promediostock: string};\r\n        var products:producto[] = [];\r\n\r\n        const v:number = validarPassword('clave_para_eliminar_factura', 'divmsjalerta1', inputEliminarClave);\r\n        if(!v)return;\r\n\r\n        const devolverInventario = (document.querySelector('input[name=\"devolverinventario\"]:checked') as HTMLInputElement)?.value ?? '0';\n        if(devolverInventario === '1'){\n          inputsInv.forEach(inputinv =>{\n            const v = inputinv as HTMLInputElement;\n            products = [...products, {id: v.id, idproducto: v.id, nombre: v.dataset.nombre??'', tipoproducto: v.dataset.tipoproducto!, tipoproduccion: v.dataset.tipoproduccion!, rendimientoestandar: v.dataset.rendimientoestandar!, cantidad: v.value, promediostock: v.dataset.promediostock??'0'}];\n          });\n        }\n\n        (async ()=>{\n          const btnConfirmar = document.querySelector<HTMLButtonElement>('.sieliminar');\n          if(btnConfirmar){\n            btnConfirmar.disabled = true;\n            btnConfirmar.classList.add('opacity-70', 'cursor-not-allowed');\n          }\n          const datos = new FormData();\n          datos.append('id', idorden!); //id de la factura\n          datos.append('observacioneliminacion', (document.querySelector('#observacionEliminacion') as HTMLTextAreaElement).value);\n          datos.append('inv', JSON.stringify(products));\n          datos.append('devolverinv', devolverInventario);\n          //datos.append('domicilio', 0);\r\n          try {\r\n              const url = \"/admin/api/eliminarOrden\";  //api llamada en ventascontrolador.php\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();\r\n              if(resultado.exito !== undefined){\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                miDialogoEliminarOrden.close();\r\n                btneliminarorden.style.display = \"none\";\r\n                if(enviarEmail)enviarEmail.style.display = \"none\";\n                (document.querySelector('#estadoOrden') as HTMLElement).textContent = \"Eliminada\";\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\n              if(resultado.exito === undefined && btnConfirmar){\n                btnConfirmar.disabled = false;\n                btnConfirmar.classList.remove('opacity-70', 'cursor-not-allowed');\n              }\n          } catch (error) {\n              console.log(error);\n              msjalertToast('error', 'Error', 'No se pudo eliminar la orden. Intenta nuevamente.');\n              if(btnConfirmar){\n                btnConfirmar.disabled = false;\n                btnConfirmar.classList.remove('opacity-70', 'cursor-not-allowed');\n              }\n          }\n        })();\r\n      }\r\n\r\n\r\n      document.querySelector('#tablaDetalleProductos')?.addEventListener('click', async(e:Event)=>{\r\n        while(tablaDetalleInsumos.firstChild)tablaDetalleInsumos.removeChild(tablaDetalleInsumos.firstChild);\r\n        const target = e.target as HTMLElement;\r\n        if(target.classList.contains('productoCompuesto')){\r\n          const nombreProductoCompuesto = target.textContent;\r\n          const parametrosURL = new URLSearchParams(window.location.search);\r\n          const idventa = parametrosURL.get('id');\r\n          if(idventa==''||idventa==null||isNaN(Number(idventa)))return;\r\n          const idproducto = target.id;\r\n          document.querySelector('#nombreProducto')!.textContent = nombreProductoCompuesto;\r\n          miDialogoProductoCompuesto.showModal();\r\n          \r\n          try {\r\n            const url = `/admin/api/ventas/detalleProductoCompuesto?idproducto=${idproducto}&idfactura=${idventa}`; //llamado a la API REST ventascontrolador, detalle producto compuesto\r\n            const respuesta = await fetch(url); \r\n            const resultado = await respuesta.json();\r\n            detalleInsumos(resultado);\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        }\r\n      });\r\n\r\n\r\n      function detalleInsumos(resultado:{cantidadcalculada:string, costo:string, disponibilidad:string, nombre:string, precio_compra:string, simbolo:string, sku:string, stockminimo:string, unidadmedida:string}[]){\r\n        resultado.forEach(ins=>{\r\n          const tr = document.createElement('tr') as HTMLTableRowElement;\r\n          //tr.classList.add('productselect');\r\n          //tr.dataset.idproducto = `${item.idproducto}`;\r\n          tr.innerHTML = `<td class=\"text-center\">${ins.nombre}</td>\r\n                          <td class=\"text-center\">${ins.cantidadcalculada}</td>\r\n                          <td class=\"text-center\">${ins.unidadmedida}</td>\r\n                          <td class=\"text-center\">${ins.disponibilidad} ${ins.simbolo}</td>`;\r\n          tablaDetalleInsumos.prepend(tr);\r\n        });\r\n      }\r\n\r\n\r\n      function validarPassword(llave:string, divAlert:string, input:HTMLInputElement):number{\n        if(!claveEliminarOrden){\n          msjAlert('error', 'Las claves de seguridad aun se estan cargando. Intenta nuevamente.', (document.querySelector('#'+divAlert) as HTMLElement));\n          return 0;\n        }\n        const clave = claveEliminarOrden.find(c => c.clave==llave);\n        if(clave?.valor_final!==null && input.value !== clave?.valor_final){\r\n          msjAlert('error', 'El password es invalido', (document.querySelector('#'+divAlert) as HTMLElement));\r\n          return 0;\r\n        }\r\n        return 1;\r\n      }\r\n\r\n    }\r\n  \r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.pedidosguardados')){\r\n\r\n    let indiceFila=0, control=0, tablaPedidosGuardados:HTMLElement;\r\n/*\r\n    type cajasapi = {\r\n        id:string,\r\n        idtipoconsecutivo: string,\r\n        nombre: string,\r\n        negocio: string\r\n      };\r\n  \r\n      let cajas:cajasapi[]=[], unacaja:cajasapi|undefined;\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allcajas\"; //llamado a la API REST y se trae todos los productos\r\n            const respuesta = await fetch(url); \r\n            cajas = await respuesta.json(); \r\n            console.log(cajas);\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();*/\r\n\r\n     //////////////////  TABLA //////////////////////\r\n    tablaPedidosGuardados = ($('#tablaPedidosGuardados') as any).DataTable({\n      ...configdatatables,\n      responsive: {\n        details: false\n      },\n      columnDefs: [\n        { targets: 0, className: 'all dtr-control', responsivePriority: 1 },\n        { targets: 1, className: 'all', responsivePriority: 2 },\n        { targets: 2, responsivePriority: 3 },\n        { targets: 3, responsivePriority: 4 },\n        { targets: 4, responsivePriority: 9 },\n        { targets: 5, responsivePriority: 8 },\n        { targets: 6, responsivePriority: 5 },\n        { targets: 7, responsivePriority: 7 },\n        { targets: 8, responsivePriority: 6 },\n        { targets: 9, responsivePriority: 10, orderable: false, searchable: false }\n      ]\n    });\n\r\n    document.querySelector('#tablaPedidosGuardados')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\n      const target = e.target as HTMLElement;\n      const expandCell = target.closest('td.dtr-control') as HTMLTableCellElement|null;\n      if(expandCell && window.innerWidth <= 768){\n        const row = expandCell.closest('tr');\n        if(row){\n          const dataTableRow = (tablaPedidosGuardados as any).row(row);\n          if(dataTableRow.child.isShown()){\n            dataTableRow.child.hide();\n            row.classList.remove('parent');\n          }else{\n            const headers = Array.from(document.querySelectorAll<HTMLTableCellElement>('#tablaPedidosGuardados thead th'));\n            const cells = Array.from(row.querySelectorAll<HTMLTableCellElement>('td'));\n            const detailRows = cells.slice(2).map((cell, index) => {\n              const title = headers[index + 2]?.textContent?.trim() || '';\n              return `<li><span class=\"dtr-title\">${title}</span><span class=\"dtr-data\">${cell.innerHTML}</span></li>`;\n            }).join('');\n            dataTableRow.child(`<ul class=\"dtr-details\">${detailRows}</ul>`, 'child').show();\n            row.classList.add('parent');\n          }\n        }\n      }\n      if(target?.classList.contains(\"eliminarPedidoGuardado\")||target.parentElement?.classList.contains(\"eliminarPedidoGuardado\"))eliminarPedidoGuardado(e);\n    });\n\r\n\r\n    ////////////////////  Eliminar cotizacion por completo del sistema  //////////////////////\r\n    function eliminarPedidoGuardado(e:Event){\r\n      const target = e.target as HTMLElement;\n      const acciones = target.closest('.pg-actions, .acciones-btns') as HTMLElement|null;\n      let idpedidoguardado = acciones?.id || target.parentElement!.id, info = (tablaPedidosGuardados as any).page.info();\n      if(target.tagName === 'I' && !acciones)idpedidoguardado = target.parentElement!.parentElement!.id;\n      indiceFila = (tablaPedidosGuardados as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      Swal.fire({\r\n          customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n          icon: 'question',\r\n          title: `Desea eliminar la orden guardado #${idpedidoguardado}?`,\r\n          text: \"La orden/cotizacion guardado sera eliminado definitivamente del sistema.\",\r\n          showCancelButton: true,\r\n          confirmButtonText: 'Si',\r\n          cancelButtonText: 'No',\r\n      }).then((result:any) => {\r\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idpedidoguardado);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarPedidoGuardado\"; // llama controlador cajacontrolador.php\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                        (tablaPedidosGuardados as any).row(indiceFila).remove().draw(); \r\n                        (tablaPedidosGuardados as any).page(info.page).draw('page'); \r\n                        Swal.fire(resultado.exito[0], '', 'success')\r\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n    \r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateCaja') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n  }\r\n\r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.pendienteDespacho')){\n\n    Object.assign(configdatatables25reg, { order: [[ 1, 'desc' ]] });\n    const tablaDespachosPendientes = ($('#tabladespachosPendientes') as any).DataTable({\n      ...configdatatables25reg,\n      responsive: {\n        details: false\n      },\n      columnDefs: [\n        { targets: 0, className: 'all dtr-control', responsivePriority: 1 },\n        { targets: 1, className: 'all', responsivePriority: 2 },\n        { targets: 2, responsivePriority: 3 },\n        { targets: 3, responsivePriority: 4 },\n        { targets: 4, responsivePriority: 5 },\n        { targets: 5, responsivePriority: 6 },\n        { targets: 6, responsivePriority: 9 },\n        { targets: 7, responsivePriority: 7 },\n        { targets: 8, responsivePriority: 8 },\n        { targets: 9, responsivePriority: 10, orderable: false, searchable: false }\n      ]\n    });\n\n    document.querySelector('#tabladespachosPendientes')?.addEventListener('click', (e)=>{\n      const target = e.target as HTMLElement;\n      const expandCell = target.closest('td') as HTMLTableCellElement|null;\n      if(!expandCell || expandCell.cellIndex !== 0 || window.innerWidth > 768)return;\n\n      const row = expandCell.closest('tr');\n      if(!row)return;\n\n      const dataTableRow = (tablaDespachosPendientes as any).row(row);\n      if(dataTableRow.child.isShown()){\n        dataTableRow.child.hide();\n        row.classList.remove('parent');\n        return;\n      }\n\n      const headers = Array.from(document.querySelectorAll<HTMLTableCellElement>('#tabladespachosPendientes thead th'));\n      const cells = Array.from(row.querySelectorAll<HTMLTableCellElement>('td'));\n      const detailRows = cells.slice(2).map((cell, index) => {\n        const title = headers[index + 2]?.textContent?.trim() || '';\n        return `<li><span class=\"dtr-title\">${title}</span><span class=\"dtr-data\">${cell.innerHTML}</span></li>`;\n      }).join('');\n\n      dataTableRow.child(`<ul class=\"dtr-details\">${detailRows}</ul>`, 'child').show();\n      row.classList.add('parent');\n    });\n\n  }\n\r\n})();\n","(()=>{\r\n    if(!document.querySelector('.comisiones'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const selectEmpleado = document.querySelector('#selectEmpleado') as HTMLSelectElement;\r\n    const tipo = document.querySelector('#tipo') as HTMLSelectElement;\r\n    const comisiontotalUser = document.querySelector('#comisiontotalUser') as HTMLParagraphElement;\r\n    const comisionTotalUserPagada = document.querySelector('#comisionTotalUserPagada') as HTMLParagraphElement;\r\n    const comisionUserPendiente = document.querySelector('#comisionUserPendiente') as HTMLParagraphElement;\r\n    const btnLiquidar = document.querySelector('#btnLiquidar') as HTMLButtonElement;\r\n    const miDialogoLiquidar = document.querySelector('#miDialogoLiquidar') as HTMLDialogElement;\r\n    const miDialogoDetalleComision = document.querySelector('#miDialogoDetalleComision') as HTMLDialogElement;\r\n    const inputValorLiquidar = (document.querySelector('#valorLiquidar') as HTMLInputElement);\r\n    const origenRetiro = document.querySelectorAll<HTMLInputElement>('input[name=\"origenRetiro\"]');\r\n    let tablaMovimientosComisiones:HTMLElement, comisionPendienteUser = 0, comisionPagadaUser = 0;\r\n    const tablaItemsComision = document.querySelector('#tablaItemsComision tbody') as HTMLBodyElement;\r\n\r\n    interface ComisionTotalUser {\r\n        comisiontotal: number;\r\n    }\r\n    interface HistorialPagos {\r\n        movimientos: any[]; // mejor reemplazar por un tipo específico si lo conoces\r\n        totalPagado: number;\r\n    }\r\n    interface ResponseComision {\r\n        comisionTotaluser: ComisionTotalUser;\r\n        historialPagos: HistorialPagos;\r\n    }\r\n\r\n\r\n    document.addEventListener(\"click\", cerrarDialogoExterno);\r\n\r\n    //api para traer valores del usuario a consultar\r\n    async function callApiReporte(dateinicio:string, datefin:string){\r\n        if(selectEmpleado.value === ''){\r\n            msjalertToast('error', '¡Error!', \"Seleccionar un empleado de la lista\");\r\n            return;\r\n        }\r\n\r\n        (document.querySelector('#textNameUser') as HTMLElement).textContent = \"Detalle de Movimientos - \"+$('#selectEmpleado option:selected').text();\r\n\r\n        //(document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin);\r\n        datos.append('idempleado', selectEmpleado.value);\r\n        try {\r\n            const url = \"/admin/api/comisiones/comisionesXUser\"; //llama a la api que esta en comisionescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            printWidgetsUser(resultado);\r\n            \r\n            //(document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    function printWidgetsUser(resultado:ResponseComision){\r\n        comisionPagadaUser = resultado.historialPagos.totalPagado;\r\n        comisionPendienteUser = resultado.comisionTotaluser.comisiontotal-comisionPagadaUser;\r\n\r\n        comisiontotalUser.textContent = '$'+Number(resultado.comisionTotaluser.comisiontotal).toLocaleString('es-CO', {minimumFractionDigits:2, maximumFractionDigits:2});\r\n        comisionTotalUserPagada.textContent = '$'+comisionPagadaUser.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n        comisionUserPendiente.textContent = '$'+comisionPendienteUser.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n        printTableMovimientosComisiones(resultado.historialPagos.movimientos);\r\n    }\r\n\r\n\r\n    btnLiquidar.addEventListener('click', ()=>{ miDialogoLiquidar.showModal(); });\r\n\r\n\r\n    /// evento a los inputs type radio para elegir origne del gasto = caja o bancos\r\n    origenRetiro.forEach(element =>element.addEventListener('click', showCajasBancos));\r\n\r\n    function showCajasBancos(){\r\n      const selectorigen = document.querySelector('input[name=\"origenRetiro\"]:checked');\r\n      if(selectorigen?.id == 'gastocaja'){\r\n        document.querySelector('#showbancos')?.classList.add('hidden');\r\n        document.querySelector('#banco')?.removeAttribute(\"required\");\r\n      }else{\r\n        document.querySelector('#showbancos')?.classList.remove('hidden');\r\n        document.querySelector('#banco')?.setAttribute(\"required\", \"\");\r\n      }\r\n    }\r\n\r\n\r\n    document.querySelector('#formCrearUpdateLiquidar')?.addEventListener('submit', async(e:Event)=>{\r\n        e.preventDefault();\r\n        const imprimir = document.querySelector('input[name=\"printComprobante\"]') as HTMLInputElement;\r\n        //validar que no supere el monto total a liquidar comision del usuario\r\n        if(selectEmpleado.value === '' || Number(inputValorLiquidar.value) <= 0 || Number(inputValorLiquidar.value)>Number(comisionPendienteUser)){\r\n            msjalertToast('error', '¡Error!', \"Seleccionar un empleado de la lista o valor a liquidar no es valido\");\r\n            return;\r\n        }\r\n        const datos = new FormData();\r\n        datos.append('fkusuarioid', selectEmpleado.value);\r\n        datos.append('valor', inputValorLiquidar.value);\r\n        datos.append('mediopago', (document.querySelector('#mediopago') as HTMLInputElement).value);\r\n        datos.append('tipo', tipo.value);\r\n        datos.append('referencia', (document.querySelector('#observacion') as HTMLInputElement).value);\r\n        datos.append('origengasto', document.querySelector<HTMLInputElement>('input[name=\"origenRetiro\"]:checked')!.value);\r\n        datos.append('idcaja', document.querySelector<HTMLInputElement>('#caja')!.value);\r\n        datos.append('idbanco', document.querySelector<HTMLInputElement>('#banco')?.value??'');\r\n        try {\r\n            const url = \"/admin/api/comisiones/liquidarComision\"; //llama a la api que esta en comisionescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito != undefined){\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                const nuevoMovimiento = {\r\n                    fecha: new Date().toISOString(),\r\n                    tipo: `<div class=\"\"> ${tipo.value} <p class=\" text-slate-600 text-sm mt-2\">${(document.querySelector('#mediopago') as HTMLInputElement).value}</p></div>`,\r\n                    entrada: 0,\r\n                    salida: Number(inputValorLiquidar.value),\r\n                    id: resultado.id\r\n                };\r\n                (tablaMovimientosComisiones as any).row.add(nuevoMovimiento).draw();\r\n                //actualizar widget del usuario\r\n                comisionPagadaUser += nuevoMovimiento.salida;\r\n                comisionPendienteUser -= nuevoMovimiento.salida;\r\n                comisionTotalUserPagada.textContent = '$'+comisionPagadaUser.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n                comisionUserPendiente.textContent = '$'+comisionPendienteUser.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n                //actualizar widget business\r\n                comisionTotalPagadaBusinessDB+=nuevoMovimiento.salida;\r\n                (document.querySelector('#comisionTotalPagadaGlobal') as HTMLParagraphElement).textContent = \" - $\"+(comisionTotalPagadaBusinessDB.toLocaleString());\r\n                (document.querySelector('#comisionPendienteGlobal') as HTMLParagraphElement).textContent = \"$\"+(comisionTotalEmpleadosDB-comisionTotalPagadaBusinessDB).toLocaleString();\r\n                if(imprimir.checked)await printComprobantePago(resultado.id);\r\n                (e.target as HTMLFormElement).reset();\r\n                document.querySelector('#showbancos')?.classList.add('hidden');\r\n                document.querySelector('#banco')?.removeAttribute(\"required\");\r\n            }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n            miDialogoLiquidar.close();\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    });\r\n\r\n\r\n    function printComprobantePago(idPagoComision:string): Promise<void>{\r\n      return new Promise<void>((resolve, reject) => {\r\n        setTimeout(() => {\r\n          window.open(\"/admin/printPDFPOSPagoComision?id=\" + idPagoComision, \"_blank\");\r\n          resolve();\r\n        }, 700);\r\n      })\r\n    }\r\n\r\n\r\n    printTableMovimientosComisiones([]);\r\n    function printTableMovimientosComisiones(movimientos:any){\r\n        tablaMovimientosComisiones = ($('#tablaMovimientosComisiones') as any).DataTable({\r\n            \"responsive\": true,\r\n            pageLength: 25,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: movimientos,\r\n            order: [[0, \"desc\"]],\r\n            columns: [\r\n                {title: 'Fecha', data: 'fecha'}, \r\n                {title: 'Concepto', data: 'tipo', render: (data: any, type: any, row: any) => `<div class=\"\"> ${row.tipo}<p class=\" text-slate-600 text-sm mt-2\">${row.concepto!==undefined?row.concepto:''}</p></div>`},\r\n                {title: 'Crédito (+)', data: 'entrada', render: (data:number, type: any, row: any) => `<div class=\"${Number(row.entrada)>0?'text-green-500':''}\"><button class=\"btn-detalle\" data-idfactura=\"${row.id}\"> + $${Number(row.entrada).toLocaleString()} </button></div>`},\r\n                {title: 'Débito (-)', data: 'salida', render: (data: any, type: any, row: any) => `<div class=\"${row.salida>0?'text-red-500':''}\"> - $${row.salida.toLocaleString()}</div>`},\r\n                {title: 'Acciones', data: null, render: (data: any, type: any, row: any) => `<button class=\"btn-eliminar\" data-id=\"${row.entrada == 0&&row.salida!=0?row.id:''}\">${row.entrada == 0&&row.salida!=0?'⛔':' - '}</button>`},\r\n            ],\r\n            \r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            }\r\n        });\r\n    }\r\n\r\n\r\n    //EVENTO A LA TABLA DE MOVIMIENTOS DE COMISIONES\r\n    document.querySelector('#tablaMovimientosComisiones')?.addEventListener(\"click\", (e)=>{\r\n        const target = e.target as HTMLButtonElement;\r\n        let idmovimento = target?.dataset.id;\r\n        if(target?.classList.contains(\"btn-detalle\")){\r\n            detalleFacturaComision(target?.dataset.idfactura);\r\n            miDialogoDetalleComision.showModal();\r\n        }\r\n\r\n        if(target?.classList.contains(\"btn-eliminar\")){\r\n            if(!idmovimento || isNaN(Number(idmovimento))){\r\n                msjalertToast('error', '¡Error!', \"id del movimiento no es valido\");\r\n                return;\r\n            }\r\n            eliminarMovimientoComision(idmovimento, target);\r\n        }\r\n    });\r\n\r\n\r\n    async function detalleFacturaComision(idfactura:string|undefined){\r\n        while(tablaItemsComision.firstChild)tablaItemsComision.removeChild(tablaItemsComision.firstChild);\r\n        try {\r\n            const url = \"/admin/api/comisiones/detalleFacturaComision?id=\"+idfactura; //llamado a la API REST \r\n            const respuesta = await fetch(url);\r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){ \r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                (document.querySelector('#numFactura') as HTMLParagraphElement).textContent = `factura: ${resultado.factura.prefijo}-${resultado.factura.num_consecutivo}`;\r\n                (document.querySelector('#valorVenta') as HTMLParagraphElement).textContent = `venta: $${Number(resultado.factura.total).toLocaleString()}`;\r\n                (document.querySelector('#nombreCaja') as HTMLParagraphElement).textContent = `${resultado.factura.caja}`;\r\n                (document.querySelector('#fechaPago') as HTMLParagraphElement).textContent = `${resultado.factura.fechapago}`;\r\n                (document.querySelector('#vendedor') as HTMLParagraphElement).textContent = `${resultado.vendedor.nombre} ${(resultado.vendedor.apellido)??''}`;\r\n\r\n                resultado.productos.forEach((ins: CarritoItem)=>{\r\n                    const tr = document.createElement('tr') as HTMLTableRowElement;\r\n                    tr.innerHTML = `<td class=\"text-center\">${ins.idproducto}</td>\r\n                                    <td class=\"text-center\">${ins.nombreproducto}</td>\r\n                                    <td class=\"text-center\">${ins.cantidad}</td>\r\n                                    <td class=\"text-center\">$${Number(ins.valorunidad).toLocaleString()}</td>\r\n                                    <td class=\"text-center\">$${Number(ins.total).toLocaleString()}</td>\r\n                                    <td class=\"text-center\">${ins.percentcomision}%</td>\r\n                                    <td class=\"text-center\">$${Number(ins.valorcomision).toLocaleString()}</td>`;\r\n                    tablaItemsComision.prepend(tr);\r\n                });\r\n            }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    function eliminarMovimientoComision(idmovimento:string, target:HTMLButtonElement){\r\n        const fila = (tablaMovimientosComisiones as any).row(target.closest('tr'));\r\n        Swal.fire({\r\n            customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n            icon: 'question',\r\n            title: 'Desea eliminar el egreso de comision?',\r\n            text: \"La comision sera eliminado por completo del sistema.\",\r\n            showCancelButton: true,\r\n            confirmButtonText: 'Si',\r\n            cancelButtonText: 'No',\r\n        }).then((result:any) => {\r\n            if (result.isConfirmed) {\r\n                (async ()=>{\r\n                    try {\r\n                        const url = \"/admin/api/comisiones/eliminarMovimientoComision?id=\"+idmovimento; //llamado a la API REST en reportescontrolador para eliminar un ingreso\r\n                        const respuesta = await fetch(url);\r\n                        const resultado = await respuesta.json();\r\n                        if(resultado.exito !== undefined){ \r\n                            msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                            fila.remove().draw(false);\r\n                            //actualizar widget del usuario\r\n                            comisionPagadaUser -= Number(resultado.valor);\r\n                            comisionPendienteUser += Number(resultado.valor);\r\n                            comisionTotalUserPagada.textContent = '$'+comisionPagadaUser.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n                            comisionUserPendiente.textContent = '$'+comisionPendienteUser.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n                            //actualizar widget business\r\n                            comisionTotalPagadaBusinessDB-=Number(resultado.valor);\r\n                            (document.querySelector('#comisionTotalPagadaGlobal') as HTMLParagraphElement).textContent = \"$\"+comisionTotalPagadaBusinessDB.toLocaleString();\r\n                            (document.querySelector('#comisionPendienteGlobal') as HTMLParagraphElement).textContent = \"$\"+(comisionTotalEmpleadosDB-comisionTotalPagadaBusinessDB).toLocaleString();\r\n                        }else{\r\n                            msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                        }\r\n                    } catch (error) {\r\n                        console.log(error);\r\n                    }\r\n                })();\r\n            }\r\n        });\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n        const f = event.target;\r\n        if (f=== miDialogoLiquidar || f === miDialogoDetalleComision || (f as HTMLInputElement).value === 'salir' || (f as HTMLInputElement).value === 'Cancelar' || (f as HTMLElement).id == 'btnXCerrarModalLiquidar' || (f as HTMLElement).id == 'btnXCerrarModalDetalleComision') {\r\n            miDialogoLiquidar.close();\r\n            miDialogoDetalleComision.close();\r\n        }\r\n    }\r\n\r\n\r\n    POS.callApiReporte = callApiReporte;\r\n    \r\n})();","(function(){\r\n  if(document.querySelector('.empleados')){\r\n    const crearempleado = document.querySelector('#crearempleado') as HTMLElement;\r\n    const dialogoEmpleado:any = document.getElementById(\"miDialogoEmpleado\");\r\n    const dialogoContraseña = document.getElementById(\"miDialogoContraseña\");\r\n    const btnupImage = document.querySelector('#upImage') as HTMLInputElement;\r\n    const btncustomUpImage = document.querySelector('#customUpImage') as HTMLButtonElement;\r\n    const imginputfile = document.querySelector('#imginputfile') as HTMLImageElement;  //img\r\n\r\n    const inputNombre = document.querySelector('#nombreempleado') as HTMLInputElement;\r\n    const inputApellido = document.querySelector('#apellidoempleado') as HTMLInputElement;\r\n    const inputnickname = document.querySelector('#nicknameempleado') as HTMLInputElement;\r\n    //const inputcedula = document.querySelector('#cedulaempleado') as HTMLInputElement;\r\n    const inputpassword = document.querySelector('#passwordempleado') as HTMLInputElement;\r\n    const inputpassword2 = document.querySelector('#passwordempleado2 ') as HTMLInputElement;\r\n    const inputMovil = document.querySelector('#movilempleado ') as HTMLInputElement;\r\n    const porcentajeganancia = document.querySelector('#porcentajeganancia ') as HTMLInputElement;\r\n    //const inputEmail = document.querySelector('#emailempleado') as HTMLInputElement;\r\n    //const inputDepartamento = document.querySelector('#departamentoempleado') as HTMLInputElement;\r\n    //const inputCiudad = document.querySelector('#ciudadempleado') as HTMLInputElement;\r\n    //const inputDireccion = document.querySelector('#direccionempleado') as HTMLInputElement;\r\n    const inputPerfil = document.querySelector('#perfilempleado') as HTMLInputElement;\r\n\r\n    let indiceFila=0, control=0, tablaempleados:HTMLElement;\n    let selectPerfilEmpleadoActivo = false;\n    let cambiandoPerfilDesdeSelect2 = false;\n      \r\n    interface empleadoApi {\r\n      id:string,\r\n      nombre: string,\r\n      apellido: string,\r\n      nickname: string,\r\n      cedula: string,\r\n      movil: string,\r\n      email: string,\r\n      departamento: string,\r\n      ciudad: string,\r\n      direccion: string,\r\n      perfil: string, \r\n      porcentajeganancia:string,\r\n      img:string,\r\n      idusuariospermisos:{id:string, usuarioid:string, permisoid:string}[]\r\n      permisos:{id:string, nombre:string}[]\r\n    };\r\n\r\n    let unempleado:empleadoApi|undefined, empleadosapi:empleadoApi[];\r\n\r\n    /////////////////  traer todos los empleados con sus skills  ///////////////////\r\n    (async ()=>{\r\n      try {\r\n          const url = \"/admin/api/getAllemployee\"; //llamado a la API REST\r\n          const respuesta = await fetch(url); \r\n          empleadosapi = await respuesta.json(); \r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();\r\n\r\n    const actualizarPermisosPerfil = (perfil:string):void=>{\n      const permisosOperativos = document.querySelector('#contentpermisos') as HTMLElement;\n      const permisosAdmin = document.querySelector('#contentpermisosadmin') as HTMLElement;\n\n      if(perfil == '2' || !perfil){\n        permisosOperativos.style.display = \"none\";\n        permisosAdmin.style.display = \"none\";\n      }\n      if(perfil == '3'){\n        permisosOperativos.style.display = \"none\";\n        permisosAdmin.style.display = \"\";\n      }\n      if(perfil == '4'){\n        permisosOperativos.style.display = \"\";\n        permisosAdmin.style.display = \"none\";\n      }\n    };\n\n    inputPerfil.addEventListener('change', (e)=>{\n      if(selectPerfilEmpleadoActivo && cambiandoPerfilDesdeSelect2)return;\n      actualizarPermisosPerfil((e.target as HTMLSelectElement).value);\n    });\n\r\n    //////////////////  TABLA //////////////////////\n    tablaempleados = ($('#tablaempleados') as any).DataTable(configdatatablesToolbar);\n    modernizarToolbarDataTable('#tablaempleados');\n\n    //////////////////// ventana modal al crear empleado  //////////////////////\n    crearempleado.addEventListener('click', (e)=>{\r\n      control = 0;\r\n      limpiarformdialog();\r\n      \r\n      (document.querySelector('#campopass1') as HTMLElement).style.display = \"\";\r\n      (document.querySelector('#campopass2') as HTMLElement).style.display = \"\";\r\n      (document.querySelector('#passwordempleado') as HTMLInputElement).setAttribute('required', 'true');\r\n      (document.querySelector('#passwordempleado2') as HTMLInputElement).setAttribute('required', 'true');\r\n\r\n      document.querySelector('#modalEmpleado')!.textContent = \"Crear empleado\";\n      (document.querySelector('#btnEditarCrearEmpleado') as HTMLInputElement).value = \"Crear\";\n      dialogoEmpleado.showModal();\n      activarSelectPerfilEmpleado();\n      document.addEventListener(\"click\", cerrarDialogoExterno);\n    });\n\r\n     //////////////////// Cargar imagen como preview  //////////////////////\r\n    btncustomUpImage.addEventListener('click', ()=>btnupImage.click());\r\n    btnupImage.addEventListener('change', function(){\r\n      const file = this.files?.[0];\r\n      if(file){\r\n        const reader = new FileReader();\r\n        reader.onload = function(){\r\n          const resrult:(string | ArrayBuffer | null) = reader.result;\r\n          if(typeof resrult == \"string\")imginputfile.src = resrult;\r\n        } \r\n        reader.readAsDataURL(file);\r\n      }\r\n    });\r\n\r\n\r\n    document.querySelector('#tablaempleados')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarEmpleado\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarEmpleado\"))editarEmpleado(e);\r\n      if((e.target as HTMLElement)?.classList.contains(\"updatePassword\")||(e.target as HTMLElement).parentElement?.classList.contains(\"updatePassword\"))updatePassword(e);\r\n      if(target?.classList.contains(\"eliminarEmpleado\")||target.parentElement?.classList.contains(\"eliminarEmpleado\"))eliminarEmpleado(e);\r\n    });\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar empleado  //////////////////////\r\n    function editarEmpleado(e:Event){\r\n      let idempleado = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idempleado = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n\r\n      (document.querySelector('#campopass1') as HTMLElement).style.display = \"none\";\r\n      (document.querySelector('#campopass2') as HTMLElement).style.display = \"none\";\r\n      (document.querySelector('#passwordempleado') as HTMLInputElement).removeAttribute('required');\r\n      (document.querySelector('#passwordempleado2') as HTMLInputElement).removeAttribute('required');\r\n\r\n      document.querySelector('#modalEmpleado')!.textContent = \"Actualizar Empleado\";\r\n      (document.querySelector('#btnEditarCrearEmpleado') as HTMLInputElement)!.value = \"Actualizar\";\r\n      unempleado = empleadosapi.find(x => x.id==idempleado); //me trae al empleado seleccionado\r\n      imginputfile.src = \"/build/img/\"+unempleado?.img;\r\n      inputNombre.value = unempleado?.nombre??'';\r\n      inputApellido.value = unempleado?.apellido??'';\r\n      inputnickname.value = unempleado?.nickname??'';\r\n      //inputcedula.value = unempleado?.cedula??'';\r\n      inputMovil.value = unempleado?.movil??'';\r\n      porcentajeganancia.value = unempleado?.porcentajeganancia??'0';\r\n      //inputEmail.value = unempleado?.email??'';\r\n      //inputDepartamento.value = unempleado?.departamento??'';\r\n      //inputCiudad.value = unempleado?.ciudad??'';\r\n      //inputDireccion.value = unempleado?.direccion??'';\r\n      $('#perfilempleado').val(unempleado?.perfil??'').trigger('change');\n      actualizarPermisosPerfil(unempleado?.perfil??'');\n      printpermisos(unempleado?.permisos??[]);\r\n      indiceFila = (tablaempleados as any).row((e.target as HTMLElement).closest('tr')).index();\n      dialogoEmpleado.showModal();\n      activarSelectPerfilEmpleado();\n      document.addEventListener(\"click\", cerrarDialogoExterno);\n    }\n\r\n    function printpermisos(leave:{id:string, nombre:string}[]){\r\n      document.querySelectorAll<HTMLInputElement>('#contentpermisos input[type=\"checkbox\"]').forEach(checkbox=>{checkbox.checked=false}); //limpia los checkbox\r\n      leave.forEach(s =>{\r\n        const inputpermiso = document.querySelector(`input[value=\"${s.id}\"]`) as HTMLInputElement;\r\n        inputpermiso.checked = true;\r\n      });\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar empleado  //////////////////////\r\n    document.querySelector('#formCrearUpdateEmpleado')?.addEventListener('submit', e=>{\r\n      if(control){\r\n        e.preventDefault();\r\n        var imgFile:(string|File), info = (tablaempleados as any).page.info();\r\n        imgFile=unempleado!.img;\r\n        if(!imginputfile.src.includes(unempleado!.img)){ //cambio de imagen\r\n          imgFile = ((e.target as HTMLFormElement).elements.namedItem(\"upImage\") as HTMLInputElement).files?.[0]!; //obtengo el archivo\r\n          if(imgFile){\r\n            if(imgFile.type!==\"image/png\"&&imgFile.type!==\"image/jpeg\"){\r\n              msjAlert('error', 'No es un formato valido para la foto', (document.querySelector('#divmsjalertaempleado1') as HTMLElement));\r\n              return;\r\n            }\r\n            if(imgFile.size>550000){ //si es mayor a 550KB\r\n              msjAlert('error', 'La imagen no debe superar los 500KB', document.querySelector('#divmsjalertaempleado1')!);\r\n              return;\r\n            }\r\n          }\r\n        }\r\n\r\n        var arraypermisos:{id:string, nombre:string}[] = [];\r\n        document.querySelectorAll<HTMLInputElement>('#contentpermisos input[type=\"checkbox\"]').forEach(x=>{\r\n          if(x.checked)arraypermisos = [...arraypermisos, {id:x.value, nombre: x.nextElementSibling?.textContent??'permiso'}];\r\n        });\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unempleado!.id);\r\n          datos.append('img', imgFile); //en el backend no se lee con $_POST, se lee con $_FILES\r\n          datos.append('nombre', inputNombre.value);\r\n          datos.append('apellido', inputApellido.value);\r\n          datos.append('nickname', inputnickname.value);\r\n          //datos.append('cedula', inputcedula.value);\r\n          datos.append('password', inputpassword.value);\r\n          datos.append('password2', inputpassword2.value);\r\n          datos.append('movil', inputMovil.value);\r\n          datos.append('porcentajeganancia', porcentajeganancia.value);\r\n          //datos.append('email', inputEmail.value);\r\n          //datos.append('departamento', inputDepartamento.value);\r\n          //datos.append('ciudad', inputCiudad.value);\r\n          //datos.append('direccion', inputDireccion.value);\r\n          datos.append('perfil', inputPerfil.value);\r\n          datos.append('idpermisos', JSON.stringify(arraypermisos.map(v=>v.id)));\r\n          try {\r\n              const url = \"/admin/api/actualizarEmpleado\";\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                ///////// cambiar la fila completa, su contenido //////////\r\n                const datosActuales = (tablaempleados as any).row(indiceFila+=info.start).data();\r\n                /*NOMBRE*/datosActuales[1] = inputNombre.value +' '+inputApellido.value;\r\n                /*img*/datosActuales[2] = `<div class=\"text-center\"><img style=\"width: 40px;\" src=\"/build/img/${resultado.rutaimg}\" alt=\"\"></div>`;\r\n                /*USER*/datosActuales[3] = inputnickname.value;\r\n                /*PERFIL*/datosActuales[6] = inputPerfil.value==='1'?'root':inputPerfil.value=='2'?'Superior':inputPerfil.value == '3'?'Admin':'Asesor';\r\n                //actualizar el empleado y arreglo de permisos\r\n                empleadosapi.forEach(a=>{\r\n                  if(a.id == unempleado?.id){\r\n                    a.nombre = inputNombre.value;\r\n                    a.apellido = inputApellido.value;\r\n                    a.nickname = inputnickname.value;\r\n                    a.movil = inputMovil.value;\r\n                    a.porcentajeganancia = porcentajeganancia.value;\r\n                    a.perfil = inputPerfil.value;\r\n                    a.permisos = arraypermisos; //arreglo de permisos\r\n                    a.img = resultado.rutaimg;\r\n                  }\r\n                });\r\n\r\n                (tablaempleados as any).row(indiceFila).data(datosActuales).draw();\r\n                (tablaempleados as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n              dialogoEmpleado.close();\r\n              document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n      } //fin if(control)\r\n    });\r\n\r\n\r\n    ////////////////////  Actualizar contraseña del empleado  //////////////////////\r\n    function updatePassword(e:Event){\r\n      let idempleado = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement).tagName === 'I')idempleado = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      unempleado = empleadosapi.find(x => x.id==idempleado);\r\n      (document.querySelector('#nombreEmpleadoPass') as HTMLElement).textContent = unempleado?.nombre+\" \"+(unempleado?.apellido??'');\r\n      (dialogoContraseña as any)?.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    document.querySelector('#formContraseña')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      (async ()=>{\r\n        const datos = new FormData();\r\n        datos.append('id', unempleado!.id);\r\n        datos.append('password', (document.querySelector('#changePassword') as HTMLInputElement).value);\r\n        try {\r\n            const url = \"/admin/api/updatepassword\";\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\r\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            }else{\r\n              msjalertToast('error', '¡Error!', resultado.exito[0]);\r\n            }\r\n            (dialogoContraseña as any)?.close();\r\n            document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar el empleado  //////////////////////\r\n    function eliminarEmpleado(e:Event){\n      let idempleado = (e.target as HTMLElement).parentElement!.id, info = (tablaempleados as any).page.info();\n      if((e.target as HTMLElement).tagName === 'I')idempleado = (e.target as HTMLElement).parentElement!.parentElement!.id;\n      const empleadoEliminar = empleadosapi.find(x => x.id == idempleado);\n      const nombreEmpleado = `${empleadoEliminar?.nombre ?? 'este empleado'} ${empleadoEliminar?.apellido ?? ''}`.trim();\n      indiceFila = (tablaempleados as any).row((e.target as HTMLElement).closest('tr')).index();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          icon: 'warning',\n          title: 'Eliminar empleado',\n          html: `Esta accion eliminara definitivamente a <strong>${nombreEmpleado}</strong>.`,\n          showCancelButton: true,\n          confirmButtonText: 'Eliminar',\n          cancelButtonText: 'Cancelar',\n          buttonsStyling: false,\n          reverseButtons: true,\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idempleado);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarEmpleado\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                        (tablaempleados as any).row(indiceFila).remove().draw(); \r\n                        (tablaempleados as any).page(info.page).draw('page');\r\n                        empleadosapi = empleadosapi.filter(x=>x.id!=idempleado);\r\n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          icon: 'success',\n                          title: 'Empleado eliminado',\n                          html: resultado.exito[0],\n                          confirmButtonText: 'Aceptar',\n                          buttonsStyling: false\n                        })\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === dialogoEmpleado || event.target === dialogoContraseña || (event.target as HTMLInputElement).value === 'Cancelar') {\r\n          dialogoEmpleado.close();\r\n          (dialogoContraseña as any)?.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\n      imginputfile.removeAttribute('src');\n      (document.querySelector('#formCrearUpdateEmpleado') as HTMLFormElement)?.reset();\n      if(selectPerfilEmpleadoActivo)$('#perfilempleado').val('').trigger('change');\n      else actualizarPermisosPerfil('');\n    }\n\n    function activarSelectPerfilEmpleado(){\n      if(selectPerfilEmpleadoActivo)return;\n      ($('#perfilempleado') as any).select2({\n        dropdownParent: $('#miDialogoEmpleado'),\n        dropdownCssClass: 'config-empleado-select2-dropdown',\n        placeholder: \"-Seleccionar-\",\n        width: '100%',\n        minimumResultsForSearch: Infinity\n      });\n      $('#perfilempleado').on('select2:selecting', ()=>{\n        cambiandoPerfilDesdeSelect2 = true;\n      });\n      $('#perfilempleado').on('select2:close', ()=>{\n        if(!cambiandoPerfilDesdeSelect2)return;\n        window.setTimeout(()=>{\n          actualizarPermisosPerfil(($('#perfilempleado').val() as string) || '');\n          cambiandoPerfilDesdeSelect2 = false;\n        }, 60);\n      });\n      $('#perfilempleado').on('change', ()=>{\n        if(cambiandoPerfilDesdeSelect2)return;\n        actualizarPermisosPerfil(($('#perfilempleado').val() as string) || '');\n      });\n      selectPerfilEmpleadoActivo = true;\n    }\n\r\n  }\r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.gestionbancos')){\r\n    const crearBanco = document.querySelector('#crearBanco') as HTMLButtonElement;\r\n    const miDialogoBanco = document.querySelector('#miDialogoBanco') as any;\r\n\r\n    let indiceFila=0, control=0, tablaBancos:HTMLElement;\r\n\r\n    type bancosapi = {\r\n        id:string,\r\n        nombre: string,\r\n        numerocuenta: string,\r\n        saldo: string,\r\n        estado: string,\r\n        created_at: string\r\n      };\n  \n      let bancos:bancosapi[]=[], unbanco:bancosapi|undefined;\n\n      function escapeHtmlBanco(valor:any):string{\n        return String(valor ?? '').replace(/[&<>\"']/g, (caracter:string) => ({\n          '&': '&amp;',\n          '<': '&lt;',\n          '>': '&gt;',\n          '\"': '&quot;',\n          \"'\": '&#039;'\n        }[caracter] as string));\n      }\n\n      function renderNombreBanco(nombre:any):string{\n        return `<span class=\"config-bank-name\">\n          <span class=\"config-bank-name__icon\"><i class=\"fa-solid fa-building-columns\"></i></span>\n          <span>${escapeHtmlBanco(nombre)}</span>\n        </span>`;\n      }\n\n      function renderPillBanco(valor:any, modificador:string):string{\n        return `<span class=\"config-table-pill config-table-pill--${modificador}\">${escapeHtmlBanco(valor)}</span>`;\n      }\n\n      function filaBanco(numero:number, banco:any):any[]{\n        return [\n          numero,\n          renderNombreBanco(banco?.nombre),\n          renderPillBanco(banco?.numerocuenta, 'account'),\n          renderPillBanco(banco?.created_at, 'date'),\n          `<div class=\"acciones-btns\" id=\"${escapeHtmlBanco(banco?.id)}\" data-banco=\"${escapeHtmlBanco(banco?.nombre)}\">\n              <button class=\"btn-md btn-turquoise editarBanco\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n              <button class=\"btn-md btn-red eliminarBanco\"><i class=\"fa-solid fa-trash-can\"></i></button>\n          </div>`\n        ];\n      }\n\n      (async ()=>{\n        try {\r\n            const url = \"/admin/api/allbancos\"; //llamado a la API REST y se trae todos los bancos\r\n            const respuesta = await fetch(url); \r\n            bancos = await respuesta.json(); \r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n    //////////////////  TABLA //////////////////////\n  tablaBancos = ($('#tablaBancos') as any).DataTable(configdatatablesToolbar);\n   modernizarToolbarDataTable('#tablaBancos');\n\n    crearBanco.addEventListener('click', ()=>{\r\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalBanco')!.textContent = \"Crear banco\";\r\n        (document.querySelector('#btnEditarCrearBanco') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoBanco.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    document.querySelector('#tablaBancos')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarBanco\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarBanco\"))editarBanco(e);\r\n      if(target?.classList.contains(\"eliminarBanco\")||target.parentElement?.classList.contains(\"eliminarBanco\"))eliminarBanco(e);\r\n    });\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar banco  //////////////////////\r\n    function editarBanco(e:Event){\r\n      let idbanco = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idbanco = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n      document.querySelector('#modalBanco')!.textContent = \"Actualizar banco\";\r\n      (document.querySelector('#btnEditarCrearBanco') as HTMLInputElement)!.value = \"Actualizar\";\r\n      \r\n      unbanco = bancos.find(x => x.id==idbanco); //me trae a la banco seleccionada\r\n      (document.querySelector('#nombreBanco')as HTMLInputElement).value = unbanco?.nombre!;\r\n      (document.querySelector('#numeroCuenta')as HTMLInputElement).value = unbanco?.numerocuenta!;\r\n      \r\n      indiceFila = (tablaBancos as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoBanco.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar banco  //////////////////////\r\n    document.querySelector('#formCrearUpdateBanco')?.addEventListener('submit', e=>{\r\n      let urlApi = \"crearBanco\";\r\n      if(control)urlApi = \"actualizarBanco\";\r\n\r\n        e.preventDefault();\r\n        var info = (tablaBancos as any).page.info();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unbanco?.id?unbanco?.id:'');\r\n          datos.append('nombre', $('#nombreBanco').val()as string);\r\n          datos.append('numerocuenta', $('#numeroCuenta').val()as string);\r\n          try {\r\n              const url = \"/admin/api/\"+urlApi;\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                miDialogoBanco.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                if(!control){ //si es crear registro\r\n                  /// actualizar el arregle de la banco ///\r\n                  bancos = [...bancos, resultado.banco];\r\n                  (tablaBancos as any).row.add(filaBanco((tablaBancos as any).rows().count() + 1, resultado.banco)).draw(false); // draw(false) evita recargar toda la tabla\n                }else{ //si es actualizar\n                  /// actualizar el arregle de bancos ///\n                  bancos.forEach(a=>{if(a.id == unbanco?.id)a = Object.assign(a, resultado.banco[0]);});\n                  indiceFila += info.start;\n                  const datosActuales = (tablaBancos as any).row(indiceFila).data();\n                  const bancoActualizado = {...resultado.banco[0], created_at: resultado.banco[0].created_at ?? unbanco?.created_at};\n                  (tablaBancos as any).row(indiceFila).data(filaBanco(datosActuales[0], bancoActualizado)).draw();\n                  (tablaBancos as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                }\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar banco  //////////////////////\r\n    function eliminarBanco(e:Event){\r\n      let idbanco = (e.target as HTMLElement).parentElement!.id, info = (tablaBancos as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idbanco = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n      indiceFila = (tablaBancos as any).row((e.target as HTMLElement).closest('tr')).index();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          buttonsStyling: false,\n          icon: 'question',\n          title: 'Eliminar banco',\n          html: '<strong>Esta accion no se puede deshacer.</strong><br>El banco sera eliminado definitivamente.',\n          showCancelButton: true,\n          confirmButtonText: 'Si, eliminar',\n          cancelButtonText: 'No',\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idbanco);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarBanco\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\n                        (tablaBancos as any).row(indiceFila+info.start).remove().draw(); \n                        (tablaBancos as any).page(info.page).draw('page'); \n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          buttonsStyling: false,\n                          icon: 'success',\n                          title: 'Banco eliminado',\n                          text: resultado.exito[0],\n                          confirmButtonText: 'OK'\n                        })\n                      }else{\n                          Swal.fire({\n                            customClass: {\n                              popup: 'j2-confirm j2-confirm--danger',\n                              icon: 'j2-confirm__icon',\n                              title: 'j2-confirm__title',\n                              htmlContainer: 'j2-confirm__text',\n                              actions: 'j2-confirm__actions j2-confirm__actions--single',\n                              confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                            },\n                            buttonsStyling: false,\n                            icon: 'error',\n                            title: 'No se pudo eliminar',\n                            text: resultado.error[0],\n                            confirmButtonText: 'OK'\n                          })\n                      }\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoBanco || (event.target as HTMLInputElement).value === 'Salir') {\r\n          miDialogoBanco.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n          /*if((event.target as HTMLElement).closest('.finCerrarbanco')){  //Cuando se hace el cierre de banco\r\n            confirmarcierre();\r\n          }*/\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateBanco') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n  }\r\n\r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.gestioncajas')){\r\n    const crearCaja = document.querySelector('#crearCaja') as HTMLButtonElement;\r\n    const miDialogoCaja = document.querySelector('#miDialogoCaja') as any;\r\n\r\n    let indiceFila=0, control=0, tablaCajas:HTMLElement;\r\n\r\n    type cajasapi = {\r\n        id:string,\r\n        idemisor:string,\r\n        idtipoconsecutivo: string,\r\n        nombre: string,\r\n        negocio: string\r\n      };\r\n  \r\n      let cajas:cajasapi[]=[], unacaja:cajasapi|undefined;\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allcajas\"; //llamado a la API REST y se trae todos las cajas\r\n            const respuesta = await fetch(url); \r\n            cajas = await respuesta.json(); \r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n     //////////////////  TABLA //////////////////////\n   tablaCajas = ($('#tablaCajas') as any).DataTable(configdatatablesToolbar);\n    modernizarToolbarDataTable('#tablaCajas');\n\n    crearCaja.addEventListener('click', ()=>{\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalCaja')!.textContent = \"Crear caja\";\r\n        (document.querySelector('#btnEditarCrearCaja') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoCaja.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    document.querySelector('#tablaCajas')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarCaja\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarCaja\"))editarCaja(e);\r\n      if(target?.classList.contains(\"eliminarCaja\")||target.parentElement?.classList.contains(\"eliminarCaja\"))eliminarCaja(e);\r\n    });\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar caja  //////////////////////\r\n    function editarCaja(e:Event){\r\n      let idcaja = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idcaja = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n      document.querySelector('#modalCaja')!.textContent = \"Actualizar caja\";\r\n      (document.querySelector('#btnEditarCrearCaja') as HTMLInputElement)!.value = \"Actualizar\";\r\n      \r\n      unacaja = cajas.find(x => x.id==idcaja); //me trae a la caja seleccionada\r\n      (document.querySelector('#nombrecaja')as HTMLInputElement).value = unacaja?.nombre!;\r\n      $('#idtipoconsecutivo').val(unacaja?.idtipoconsecutivo??'');\r\n      $('#negociogestioncaja').val(1);\r\n      $('#idEmisorCaja').val(unacaja?.idemisor??'');\r\n      \r\n      indiceFila = (tablaCajas as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoCaja.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar caja  //////////////////////\r\n    document.querySelector('#formCrearUpdateCaja')?.addEventListener('submit', e=>{\r\n      let urlApi = \"crearCaja\";\r\n      if(control)urlApi = \"actualizarCaja\";\r\n\r\n        e.preventDefault();\r\n        var info = (tablaCajas as any).page.info();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unacaja?.id?unacaja?.id:'');\r\n          datos.append('idemisor', $('#idEmisorCaja').val()as string);\r\n          datos.append('idtipoconsecutivo', $('#idtipoconsecutivo').val()as string);\r\n          datos.append('nombre', $('#nombrecaja').val()as string);\r\n          datos.append('negocio', $('#negociogestioncaja').val()as string);\r\n          try {\r\n              const url = \"/admin/api/\"+urlApi;\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                miDialogoCaja.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                if(!control){ //si es crear registro\r\n                  /// actualizar el arregle de la caja ///\r\n                  cajas = [...cajas, resultado.caja];\r\n                  (tablaCajas as any).row.add([\r\n                      (tablaCajas as any).rows().count() + 1,\r\n                      resultado.caja.nombre,\r\n                      resultado.caja.nombreconsecutivo.nombre,\r\n                      resultado.caja.negocio,\r\n                      $('#idEmisorCaja option:selected').text(),\r\n                      `<div class=\"acciones-btns\" id=\"${resultado.caja.id}\" data-caja=\"${resultado.caja.nombre}\">\r\n                          <button class=\"btn-md btn-turquoise editarCaja\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\r\n                          <button class=\"btn-md btn-red eliminarCaja\"><i class=\"fa-solid fa-trash-can\"></i></button>\r\n                      </div>`\r\n                  ]).draw(false); // draw(false) evita recargar toda la tabla\r\n                }else{ //si es actualizar\r\n                  /// actualizar el arregle de cajas ///\r\n                  cajas.forEach(a=>{if(a.id == unacaja?.id)a = Object.assign(a, resultado.caja[0]);});\r\n                  const datosActuales = (tablaCajas as any).row(indiceFila+=info.start).data();\r\n                  /*CAJA*/      datosActuales[1] = resultado.caja[0].nombre;\r\n                  /*FACT AUTO*/ datosActuales[2] = $('#idtipoconsecutivo option:selected').text();\r\n                  /*SEDE*/   datosActuales[3] = $('#negociogestioncaja option:selected').text();\r\n                  /*EMISOR*/   datosActuales[4] = $('#idEmisorCaja option:selected').text();\r\n                  (tablaCajas as any).row(indiceFila).data(datosActuales).draw();\r\n                  (tablaCajas as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                }\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar caja  //////////////////////\r\n    function eliminarCaja(e:Event){\r\n      let idcaja = (e.target as HTMLElement).parentElement!.id, info = (tablaCajas as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idcaja = (e.target as HTMLElement).parentElement!.parentElement!.id;\n      indiceFila = (tablaCajas as any).row((e.target as HTMLElement).closest('tr')).index();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          buttonsStyling: false,\n          icon: 'question',\n          title: 'Eliminar caja',\n          html: '<strong>Esta accion no se puede deshacer.</strong><br>La caja sera eliminada definitivamente.',\n          showCancelButton: true,\n          confirmButtonText: 'Si, eliminar',\n          cancelButtonText: 'No',\n      }).then((result:any) => {\n          if (result.isConfirmed) {\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idcaja);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarCaja\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\n                        (tablaCajas as any).row(indiceFila+info.start).remove().draw(); \n                        (tablaCajas as any).page(info.page).draw('page'); \n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          buttonsStyling: false,\n                          icon: 'success',\n                          title: 'Caja eliminada',\n                          text: resultado.exito[0],\n                          confirmButtonText: 'OK'\n                        })\n                      }else{\n                          Swal.fire({\n                            customClass: {\n                              popup: 'j2-confirm j2-confirm--danger',\n                              icon: 'j2-confirm__icon',\n                              title: 'j2-confirm__title',\n                              htmlContainer: 'j2-confirm__text',\n                              actions: 'j2-confirm__actions j2-confirm__actions--single',\n                              confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                            },\n                            buttonsStyling: false,\n                            icon: 'error',\n                            title: 'No se pudo eliminar',\n                            text: resultado.error[0],\n                            confirmButtonText: 'OK'\n                          })\n                      }\n                  } catch (error) {\n                      console.log(error);\n                      Swal.fire({\n                        customClass: {\n                          popup: 'j2-confirm j2-confirm--danger',\n                          icon: 'j2-confirm__icon',\n                          title: 'j2-confirm__title',\n                          htmlContainer: 'j2-confirm__text',\n                          actions: 'j2-confirm__actions j2-confirm__actions--single',\n                          confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                        },\n                        buttonsStyling: false,\n                        icon: 'error',\n                        title: 'No se pudo eliminar',\n                        text: 'Intenta nuevamente o revisa la conexion.',\n                        confirmButtonText: 'OK'\n                      })\n                  }\n              })();//cierre de async()\n          }\n      });\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoCaja || (event.target as HTMLInputElement).value === 'Salir') {\r\n          miDialogoCaja.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n          /*if((event.target as HTMLElement).closest('.finCerrarcaja')){  //Cuando se hace el cierre de caja\r\n            confirmarcierre();\r\n          }*/\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateCaja') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n  }\r\n\r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.gestionEmisores')){\r\n    const crearEmisor = document.querySelector('#crearEmisor') as HTMLButtonElement;\n    const miDialogoEmisor = document.querySelector('#miDialogoEmisor') as any;\n\n    let indiceFila=0, control=0, tablaEmisores:HTMLElement;\n    let selectSucursalEmisorActivo = false;\n\r\n    type emisoresApi = {\r\n      id:string,\r\n      nombre: string,\r\n      nit: string,\r\n      datosencabezados: string,\r\n      telefono: string,\r\n      estado: string,\r\n      created_at: string\r\n    };\r\n\r\n    let emisores:emisoresApi[]=[], unEmisor:emisoresApi|undefined;\r\n    (async ()=>{\r\n      try {\r\n          const url = \"/admin/api/config/allEmisores\"; //llamado a la API REST y se trae todos los emisores\r\n          const respuesta = await fetch(url); \r\n          emisores = await respuesta.json(); \r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();\r\n\r\n     //////////////////  TABLA //////////////////////\n   tablaEmisores = ($('#tablaEmisores') as any).DataTable(configdatatablesToolbar);\n    modernizarToolbarDataTable('#tablaEmisores');\n\n    crearEmisor.addEventListener('click', ()=>{\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalEmisor')!.textContent = \"Crear nuevo emisor\";\n        (document.querySelector('#btnEditarCrearEmisor') as HTMLInputElement).value = \"Crear\";\n        miDialogoEmisor.showModal();\n        activarSelectSucursalEmisor();\n        document.addEventListener(\"click\", cerrarDialogoExterno);\n    });\n\r\n\r\n    document.querySelector('#tablaEmisores')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if(target?.classList.contains(\"stateEmisor\"))changeState(e);\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarEmisor\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarEmisor\"))editarEmisor(e);\r\n      if(target?.classList.contains(\"eliminarEmisor\")||target.parentElement?.classList.contains(\"eliminarEmisor\"))eliminarEmisor(e);\r\n    });\r\n\r\n\r\n    ///////////////  Cambiar estado del medio de pago  ////////////////\r\n    function changeState(e:Event){\r\n      const button=(e.target as HTMLButtonElement), info = (tablaEmisores as any).page.info();\r\n      indiceFila =  (tablaEmisores as any).row(button.closest('tr')).index();\r\n      (async ()=>{ \r\n        const datos = new FormData();\r\n        datos.append('id', button.id);\r\n        datos.append('estado', button.dataset.state=='0'?'1':'0');\r\n        try {\r\n            const url = \"/admin/api/config/updateStateEmisor\";\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();  \r\n            if(resultado.exito !== undefined){\r\n              const s1 = `<button id=\"${button.id}\" data-state=\"${button.dataset.state=='0'?'1':'0'}\" class=\"stateEmisor btn-xs ${button.dataset.state=='0'?'btn-lima':'btn-red'}\">${button.dataset.state=='0'?'Activo':'Inactivo'}</button>`;\r\n              (tablaEmisores as any).cell((tablaEmisores as any).row(indiceFila+=info.start), 4).data(s1).draw(); //se modifica solo la columna con la fila correspondiente, y destruye la que habai antes\r\n              (tablaEmisores as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n            }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();//cierre de async()\r\n    }\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar emisor  //////////////////////\r\n    function editarEmisor(e:Event){\r\n      let idemisor = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idemisor = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n      document.querySelector('#modalEmisor')!.textContent = \"Actualizar el emisor\";\r\n      (document.querySelector('#btnEditarCrearEmisor') as HTMLInputElement)!.value = \"Actualizar\";\r\n      \r\n      unEmisor = emisores.find(x => x.id==idemisor); //me trae el emisor seleccionado\r\n      (document.querySelector('#nombreEmisor')as HTMLInputElement).value = unEmisor?.nombre!;\r\n      (document.querySelector('#nitEmisor')as HTMLInputElement).value = unEmisor?.nit!;\r\n      (document.querySelector('#datosencabezadosEmisor')as HTMLTextAreaElement).textContent = unEmisor?.datosencabezados!;\r\n      (document.querySelector('#movilEmisor')as HTMLInputElement).value = unEmisor?.telefono!;\r\n      \r\n      indiceFila = (tablaEmisores as any).row((e.target as HTMLElement).closest('tr')).index();\n      miDialogoEmisor.showModal();\n      activarSelectSucursalEmisor();\n      document.addEventListener(\"click\", cerrarDialogoExterno);\n    }\n\r\n    ////////////////////  Crear/Editar emisor  //////////////////////\r\n    document.querySelector('#formCrearUpdateEmisor')?.addEventListener('submit', e=>{\r\n      let urlApi = \"crearEmisor\";\r\n      if(control)urlApi = \"actualizarEmisor\";\r\n\r\n        e.preventDefault();\r\n        var info = (tablaEmisores as any).page.info();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unEmisor?.id?unEmisor?.id:'');\r\n          datos.append('nombre', $('#nombreEmisor').val()as string);\r\n          datos.append('nit', $('#nitEmisor').val()as string);\r\n          datos.append('datosencabezados', $('#datosencabezadosEmisor').text());\r\n          datos.append('telefono', $('#movilEmisor').val()as string);\r\n          try {\r\n              const url = \"/admin/api/config/\"+urlApi;\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                miDialogoEmisor.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                if(!control){ //si es crear registro\r\n                  /// actualizar el arregle de las emisores ///\r\n                  emisores = [...emisores, resultado.emisor];\r\n                  (tablaEmisores as any).row.add([\r\n                      (tablaEmisores as any).rows().count() + 1,\r\n                      resultado.emisor.nombre,\r\n                      resultado.emisor.nit,\r\n                      resultado.emisor.telefono,\r\n                      `<button id=\"${resultado.emisor.id}\" data-state=\"${resultado.emisor.estado}\" class=\"stateEmisor btn-xs btn-lima\">Activo</button>`,\r\n                      `<div class=\"acciones-btns\" id=\"${resultado.emisor.id}\">\r\n                          <button class=\"btn-md btn-turquoise editarEmisor\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\r\n                          <button class=\"btn-md btn-red eliminarEmisor\"><i class=\"fa-solid fa-trash-can\"></i></button>\r\n                      </div>`\r\n                  ]).draw(false); // draw(false) evita recargar toda la tabla\r\n                }else{ //si es actualizar\r\n                  /// actualizar el arregle de emisores ///\r\n                  emisores.forEach(a=>{if(a.id == unEmisor?.id)a = Object.assign(a, resultado.emisor[0]);});\r\n                  const datosActuales = (tablaEmisores as any).row(indiceFila+=info.start).data();\r\n                  /*NOMBRE*/ datosActuales[1] = resultado.emisor[0].nombre;\r\n                  /*nit*/ datosActuales[2] = resultado.emisor[0].nit;\r\n                  /*telefono*/ datosActuales[3] = resultado.emisor[0].telefono;\r\n\r\n                  (tablaEmisores as any).row(indiceFila).data(datosActuales).draw();\r\n                  (tablaEmisores as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                }\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar emisor  //////////////////////\n    function eliminarEmisor(e:Event){\n      const accion = (e.target as HTMLElement).closest('.acciones-btns') as HTMLElement|null;\n      let idemisor = accion?.id || (e.target as HTMLElement).parentElement!.id, info = (tablaEmisores as any).page.info();\n      if((e.target as HTMLElement).tagName === 'I')idemisor = (e.target as HTMLElement).parentElement!.parentElement!.id;\n      const nombreEmisor = accion?.dataset.emisor || 'este emisor';\n      indiceFila = (tablaEmisores as any).row((e.target as HTMLElement).closest('tr')).index();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          icon: 'warning',\n          title: 'Eliminar emisor',\n          html: `Se eliminara definitivamente <strong>${nombreEmisor}</strong>. Esta accion no se puede deshacer.`,\n          showCancelButton: true,\n          confirmButtonText: 'Eliminar',\n          cancelButtonText: 'Cancelar',\n          reverseButtons: true,\n          buttonsStyling: false,\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idemisor);\r\n                  try {\r\n                      const url = \"/admin/api/config/eliminarEmisor\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                        (tablaEmisores as any).row(indiceFila+info.start).remove().draw(); \r\n                        (tablaEmisores as any).page(info.page).draw('page'); \r\n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          icon: 'success',\n                          title: 'Emisor eliminado',\n                          html: resultado.exito[0],\n                          confirmButtonText: 'Aceptar',\n                          buttonsStyling: false\n                        })\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\n      if (event.target === miDialogoEmisor || (event.target as HTMLInputElement).value === 'Salir') {\n          miDialogoEmisor.close();\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\n      (document.querySelector('#formCrearUpdateEmisor') as HTMLFormElement)?.reset();\n      if(selectSucursalEmisorActivo)($('#sucursalEmisor') as any).val('').trigger('change');\n    }\n\n    function activarSelectSucursalEmisor(){\n      if(selectSucursalEmisorActivo)return;\n      ($('#sucursalEmisor') as any).select2({\n        dropdownParent: $('#miDialogoEmisor'),\n        dropdownCssClass: 'config-emisor-select2-dropdown',\n        placeholder: \"-Seleccionar-\",\n        width: '100%',\n        minimumResultsForSearch: Infinity\n      });\n      selectSucursalEmisorActivo = true;\n    }\n\n  }\n\r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.gestionfacturadores')){\r\n    const POS = (window as any).POS;\r\n    const crearFacturador = document.querySelector('#crearFacturador') as HTMLButtonElement;\r\n    const miDialogoFacturador = document.querySelector('#miDialogoFacturador') as any;\r\n\r\n    let indiceFila=0, control=0, tablaFacturadores:HTMLElement;\r\n\r\n    type facturadoresapi = {\r\n        id:string,\r\n        id_sucursalid: string,\r\n        idtipofacturador: string,\r\n        idnegocio: string,\r\n        nombre: string\r\n        rangoinicial:string,\r\n        rangofinal: string,\r\n        siguientevalor: string,\r\n        fechainicio: string\r\n        fechafin:string,\r\n        resolucion: string,\r\n        consecutivoremplazo: string,\r\n        prefijo: string,\r\n        mostrarresolucion:string,\r\n        mostrarimpuestodiscriminado: string,\r\n        tokenfacturaelectronica: string,\r\n        electronica: string,\r\n        estado: string\r\n      };\r\n  \r\n      let facturadores:facturadoresapi[]=[], unfacturador:facturadoresapi|undefined;\n\n      function escapeHtmlFacturador(valor:any):string{\n        return String(valor ?? '').replace(/[&<>\"']/g, (caracter:string) => ({\n          '&': '&amp;',\n          '<': '&lt;',\n          '>': '&gt;',\n          '\"': '&quot;',\n          \"'\": '&#039;'\n        }[caracter] as string));\n      }\n\n      function nombreTipoFacturador(facturador:any):string{\n        const tipo = facturador?.nombretipofacturador;\n        return escapeHtmlFacturador(typeof tipo === 'object' ? tipo?.nombre : tipo);\n      }\n\n      function renderNombreFacturador(nombre:any):string{\n        return `<span class=\"config-facturador-name\">\n          <span class=\"config-facturador-name__icon\"><i class=\"fa-solid fa-receipt\"></i></span>\n          <span>${escapeHtmlFacturador(nombre)}</span>\n        </span>`;\n      }\n\n      function renderPillFacturador(valor:any, modificador:string):string{\n        return `<span class=\"config-table-pill config-table-pill--${modificador}\">${escapeHtmlFacturador(valor)}</span>`;\n      }\n\n      function renderEstadoFacturador(estado:any):string{\n        const activo = Number(estado) === 1;\n        return `<span class=\"config-table-status ${activo ? 'config-table-status--active' : 'config-table-status--expired'}\">${activo ? 'Activo' : 'Expirada'}</span>`;\n      }\n\n      function filaFacturador(numero:number, facturador:any):any[]{\n        return [\n          numero,\n          renderNombreFacturador(facturador?.nombre),\n          renderPillFacturador(nombreTipoFacturador(facturador), 'type'),\n          renderPillFacturador(`${facturador?.rangoinicial ?? ''} - ${facturador?.rangofinal ?? ''}`, 'range'),\n          renderPillFacturador(facturador?.siguientevalor, 'next'),\n          renderPillFacturador(facturador?.fechafin, 'date'),\n          renderEstadoFacturador(facturador?.estado),\n          `<div class=\"acciones-btns\" id=\"${escapeHtmlFacturador(facturador?.id)}\" data-facturador=\"${escapeHtmlFacturador(facturador?.nombre)}\">\n              <button class=\"btn-md btn-turquoise editarFacturador\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n              ${Number(facturador?.id) > 1 ? '<button class=\"btn-md btn-red eliminarFacturador\"><i class=\"fa-solid fa-trash-can\"></i></button>' : ''}\n          </div>`\n        ];\n      }\n\n      (async ()=>{\n        try {\r\n            const url = \"/admin/api/allfacturadores\"; //llamado a la API REST y se trae todos los consecutivos\r\n            const respuesta = await fetch(url); \r\n            facturadores = await respuesta.json();\r\n            POS.facturadores = facturadores;  //se expone globalmente para procesar en gestiondian.ts\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n    //////////////////  TABLA //////////////////////\n  tablaFacturadores = ($('#tablaFacturadores') as any).DataTable(configdatatablesToolbar);\n   modernizarToolbarDataTable('#tablaFacturadores');\n\n    crearFacturador.addEventListener('click', ()=>{\r\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalFacturador')!.textContent = \"Crear facturador\";\r\n        (document.querySelector('#btnEditarCrearFacturador') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoFacturador.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    document.querySelector('#tablaFacturadores')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarFacturador\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarFacturador\"))editarFacturador(e);\r\n      if(target?.classList.contains(\"eliminarFacturador\")||target.parentElement?.classList.contains(\"eliminarFacturador\"))eliminarFacturador(e);\r\n    });\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar facturador  //////////////////////\r\n    function editarFacturador(e:Event){\r\n      let idfacturador = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idfacturador = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n      document.querySelector('#modalFacturador')!.textContent = \"Actualizar facturador\";\r\n      (document.querySelector('#btnEditarCrearFacturador') as HTMLInputElement)!.value = \"Actualizar\";\r\n      \r\n      unfacturador = facturadores.find(x => x.id==idfacturador); //me trae el facturador seleccionado\r\n      (document.querySelector('#nombrefacturador')as HTMLInputElement).value = unfacturador?.nombre!;\r\n      $('#idtipofacturador').val(unfacturador?.idtipofacturador??'');\r\n      $('#rangoinicial').val(unfacturador?.rangoinicial??'');\r\n      $('#rangofinal').val(unfacturador?.rangofinal??'');\r\n      $('#siguientevalor').val(unfacturador?.siguientevalor??'');\r\n      $('#fechainicio').val(unfacturador?.fechainicio??'');\r\n      $('#fechafin').val(unfacturador?.fechafin??'');\r\n      $('#resolucion').val(unfacturador?.resolucion??'');\r\n      $('#prefijo').val(unfacturador?.prefijo??'');\r\n      $('#negociofacturador').val(1);\r\n      \r\n      indiceFila = (tablaFacturadores as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoFacturador.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar facturador  //////////////////////\r\n    document.querySelector('#formCrearUpdateFacturador')?.addEventListener('submit', e=>{\r\n      let urlApi = \"crearFacturador\";\r\n      if(control)urlApi = \"actualizarFacturador\";\r\n\r\n        e.preventDefault();\r\n        var info = (tablaFacturadores as any).page.info();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unfacturador?.id?unfacturador?.id:'');\r\n          datos.append('idtipofacturador', $('#idtipofacturador').val()as string);\r\n          datos.append('idnegocio', $('#negociofacturador').val()as string);\r\n          datos.append('nombre', $('#nombrefacturador').val()as string);\r\n          datos.append('rangoinicial', $('#rangoinicial').val()as string);\r\n          datos.append('rangofinal', $('#rangofinal').val()as string);\r\n          datos.append('siguientevalor', $('#siguientevalor').val()as string);\r\n          datos.append('fechainicio', $('#fechainicio').val()as string);\r\n          datos.append('fechafin', $('#fechafin').val()as string);\r\n          datos.append('resolucion', $('#resolucion').val()as string);\r\n          //datos.append('consecutivoremplazo', $('#negociofacturador').val()as string);\r\n          datos.append('prefijo', $('#prefijo').val()as string);\r\n          /*datos.append('mostrarresolucion', $('#negociofacturador').val()as string);\r\n          datos.append('mostrarimpuestodiscriminado', $('#nombrefacturador').val()as string);\r\n          datos.append('tokenfacturaelectronica', $('#negociofacturador').val()as string);\r\n          datos.append('electronica', $('#negociofacturador').val()as string);\r\n          datos.append('estado', $('#nombrefacturador').val()as string);*/\r\n          try {\r\n              const url = \"/admin/api/\"+urlApi;\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                miDialogoFacturador.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                if(!control){ //si es crear registro\r\n                  /// actualizar el arregle del facturador///\r\n                  facturadores = [...facturadores, resultado.facturador];\r\n                  (tablaFacturadores as any).row.add(filaFacturador((tablaFacturadores as any).rows().count() + 1, resultado.facturador)).draw(false); // draw(false) evita recargar toda la tabla\n                  crearConsecutivoGestionCaja(resultado.facturador.id, resultado.facturador.nombre);\r\n                }else{ //si es actualizar\r\n                  /// actualizar el arregle de facturadores ///\r\n                  facturadores.forEach(a=>{if(a.id == unfacturador?.id)a = Object.assign(a, resultado.facturador[0]);});\r\n                  indiceFila += info.start;\n                  const datosActuales = (tablaFacturadores as any).row(indiceFila).data();\n                  const filaActualizada = filaFacturador(datosActuales[0], resultado.facturador[0]);\n                  (tablaFacturadores as any).row(indiceFila).data(filaActualizada).draw();\n                  (tablaFacturadores as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                  actualizarConsecutivoGestionCaja(unfacturador!.id, resultado.facturador[0].nombre);\r\n                }\r\n              }else{\r\n                miDialogoFacturador.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar facturador  //////////////////////\r\n    function eliminarFacturador(e:Event){\r\n      let idfacturador = (e.target as HTMLElement).parentElement!.id, info = (tablaFacturadores as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idfacturador = (e.target as HTMLElement).parentElement!.parentElement!.id;\n      indiceFila = (tablaFacturadores as any).row((e.target as HTMLElement).closest('tr')).index();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          buttonsStyling: false,\n          icon: 'question',\n          title: 'Eliminar facturador',\n          html: '<strong>Esta accion no se puede deshacer.</strong><br>El facturador sera eliminado definitivamente.',\n          showCancelButton: true,\n          confirmButtonText: 'Si, eliminar',\n          cancelButtonText: 'No',\n      }).then((result:any) => {\n          if (result.isConfirmed) {\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idfacturador);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarFacturador\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                        (tablaFacturadores as any).row(indiceFila+info.start).remove().draw(); \n                        (tablaFacturadores as any).page(info.page).draw('page');\n                        eliminardegestioncaja(idfacturador);\n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          buttonsStyling: false,\n                          icon: 'success',\n                          title: 'Facturador eliminado',\n                          text: resultado.exito[0],\n                          confirmButtonText: 'OK'\n                        })\n                      }else{\n                          Swal.fire({\n                            customClass: {\n                              popup: 'j2-confirm j2-confirm--danger',\n                              icon: 'j2-confirm__icon',\n                              title: 'j2-confirm__title',\n                              htmlContainer: 'j2-confirm__text',\n                              actions: 'j2-confirm__actions j2-confirm__actions--single',\n                              confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                            },\n                            buttonsStyling: false,\n                            icon: 'error',\n                            title: 'No se pudo eliminar',\n                            text: resultado.error[0],\n                            confirmButtonText: 'OK'\n                          })\n                      }\n                  } catch (error) {\n                      console.log(error);\n                      Swal.fire({\n                        customClass: {\n                          popup: 'j2-confirm j2-confirm--danger',\n                          icon: 'j2-confirm__icon',\n                          title: 'j2-confirm__title',\n                          htmlContainer: 'j2-confirm__text',\n                          actions: 'j2-confirm__actions j2-confirm__actions--single',\n                          confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                        },\n                        buttonsStyling: false,\n                        icon: 'error',\n                        title: 'No se pudo eliminar',\n                        text: 'Intenta nuevamente o revisa la conexion.',\n                        confirmButtonText: 'OK'\n                      })\n                  }\n              })();//cierre de async()\n          }\n      });\r\n    }\r\n\r\n    function crearConsecutivoGestionCaja(idfacturador:string, nombre:string){\r\n      const selectConsecutivoCaja = document.querySelector('#idtipoconsecutivo') as HTMLSelectElement;\r\n      const option = document.createElement('option');\r\n      option.value = idfacturador;\r\n      option.textContent = nombre;\r\n      selectConsecutivoCaja.appendChild(option);\r\n    }\r\n\r\n    function actualizarConsecutivoGestionCaja(idfacturador:string, nombre:string){\r\n      const selectConsecutivoCaja = document.querySelector('#idtipoconsecutivo') as HTMLSelectElement;\r\n      const opcionconsecutivo = selectConsecutivoCaja.querySelector(`option[value=\"${idfacturador}\"]`) as HTMLOptionElement;\r\n      opcionconsecutivo.textContent = nombre;\r\n    }\r\n\r\n    function eliminardegestioncaja(idfacturador:string){\r\n      const selectConsecutivoCaja = document.querySelector('#idtipoconsecutivo') as HTMLSelectElement;\r\n      const opcionconsecutivo = selectConsecutivoCaja.querySelector(`option[value=\"${idfacturador}\"]`);\r\n      opcionconsecutivo?.remove();\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoFacturador || (event.target as HTMLInputElement).value === 'Salir') {\r\n          miDialogoFacturador.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateFacturador') as HTMLFormElement)?.reset();\r\n    }\r\n  }\r\n  \r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.gestionimpresoras')){\r\n    const crearImpresora = document.querySelector('#crearImpresora') as HTMLButtonElement;\r\n    const miDialogoIMpresora = document.querySelector('#miDialogoIMpresora') as any;\r\n\r\n    let indiceFila=0, control=0, tablaImpresoras:HTMLElement;\r\n\r\n    type printersApi = {\r\n      id:string,\r\n      nombre: string,\r\n      nombrecompartido: string,\n      estacion: string,\n      mm: string,\n      estado: string,\n      created_at: string\n    };\n\n    let impresoras:printersApi[]=[], unPrinter:printersApi|undefined;\n\n    function escapeHtmlImpresora(valor:any):string{\n      return String(valor ?? '').replace(/[&<>\"']/g, (caracter:string) => ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#039;'\n      }[caracter] as string));\n    }\n\n    function renderNombreImpresora(nombre:any):string{\n      return `<span class=\"config-printer-name\">\n        <span class=\"config-printer-name__icon\"><i class=\"fa-solid fa-print\"></i></span>\n        <span>${escapeHtmlImpresora(nombre)}</span>\n      </span>`;\n    }\n\n    function renderPillImpresora(valor:any, modificador:string):string{\n      return `<span class=\"config-table-pill config-table-pill--${modificador}\">${escapeHtmlImpresora(valor)}</span>`;\n    }\n\n    function renderEstadoImpresora(estado:any):string{\n      const activa = String(estado) === '1' || String(estado).toLowerCase() === 'activa' || String(estado).toLowerCase() === 'activo';\n      return `<span class=\"config-table-status ${activa ? 'config-table-status--active' : 'config-table-status--inactive'}\">${activa ? 'Activa' : 'Inactiva'}</span>`;\n    }\n\n    function filaImpresora(numero:number, impresora:any):any[]{\n      return [\n        numero,\n        renderNombreImpresora(impresora?.nombre),\n        renderPillImpresora(impresora?.nombrecompartido, 'shared'),\n        renderPillImpresora(impresora?.estacion, 'station'),\n        renderPillImpresora(`${impresora?.mm ?? ''} mm`, 'paper'),\n        renderEstadoImpresora(impresora?.estado),\n        `<div class=\"acciones-btns\" id=\"${escapeHtmlImpresora(impresora?.id)}\" data-impresora=\"${escapeHtmlImpresora(impresora?.nombre)}\">\n            <button class=\"btn-md btn-turquoise editarImpresora\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n            <button class=\"btn-md btn-red eliminarImpresora\"><i class=\"fa-solid fa-trash-can\"></i></button>\n        </div>`\n      ];\n    }\n\n    (async ()=>{\r\n      try {\r\n          const url = \"/admin/api/allPrinters\"; //llamado a la API REST y se trae todos las impresoras\r\n          const respuesta = await fetch(url); \r\n          impresoras = await respuesta.json(); \r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();\r\n\r\n    //////////////////  TABLA //////////////////////\n  tablaImpresoras = ($('#tablaImpresoras') as any).DataTable(configdatatablesToolbar);\n   modernizarToolbarDataTable('#tablaImpresoras');\n\n    crearImpresora.addEventListener('click', ()=>{\r\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalIMpresora')!.textContent = \"Crear punto de impresora\";\r\n        (document.querySelector('#btnEditarCrearImpresora') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoIMpresora.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    document.querySelector('#tablaImpresoras')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarImpresora\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarImpresora\"))editarImpresora(e);\r\n      if(target?.classList.contains(\"eliminarImpresora\")||target.parentElement?.classList.contains(\"eliminarImpresora\"))eliminarImpresora(e);\r\n    });\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar impresora  //////////////////////\r\n    function editarImpresora(e:Event){\r\n      let idimpresora = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idimpresora = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n      document.querySelector('#modalIMpresora')!.textContent = \"Actualizar punto de impresora\";\r\n      (document.querySelector('#btnEditarCrearImpresora') as HTMLInputElement)!.value = \"Actualizar\";\r\n      \r\n      unPrinter = impresoras.find(x => x.id==idimpresora); //me trae a lA impresora seleccionada\r\n      (document.querySelector('#nombreImpresora')as HTMLInputElement).value = unPrinter?.nombre!;\n      (document.querySelector('#nombreCompartido')as HTMLInputElement).value = unPrinter?.nombrecompartido!;\n      (document.querySelector('#anchoPapel')as HTMLInputElement).value = unPrinter?.mm!;\n      (document.querySelector('#estacion')as HTMLInputElement).value = unPrinter?.estacion!;\n      \r\n      indiceFila = (tablaImpresoras as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoIMpresora.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar impresora  //////////////////////\r\n    document.querySelector('#formCrearUpdateIMpresora')?.addEventListener('submit', e=>{\r\n      let urlApi = \"crearImpresora\";\r\n      if(control)urlApi = \"actualizarIMpresora\";\r\n\r\n        e.preventDefault();\r\n        var info = (tablaImpresoras as any).page.info();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unPrinter?.id?unPrinter?.id:'');\r\n          datos.append('nombre', $('#nombreImpresora').val()as string);\n          datos.append('nombrecompartido', $('#nombreCompartido').val()as string);\n          datos.append('mm', $('#anchoPapel').val()as string);\n          datos.append('estacion', $('#estacion').val()as string);\n          try {\r\n              const url = \"/admin/api/\"+urlApi;\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                miDialogoIMpresora.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                if(!control){ //si es crear registro\r\n                  /// actualizar el arregle de las impresoras ///\r\n                  impresoras = [...impresoras, resultado.printer];\r\n                  (tablaImpresoras as any).row.add(filaImpresora((tablaImpresoras as any).rows().count() + 1, resultado.printer)).draw(false); // draw(false) evita recargar toda la tabla\n                }else{ //si es actualizar\n                  /// actualizar el arregle de impresoras ///\n                  impresoras.forEach(a=>{if(a.id == unPrinter?.id)a = Object.assign(a, resultado.printer[0]);});\n                  indiceFila += info.start;\n                  const datosActuales = (tablaImpresoras as any).row(indiceFila).data();\n                  (tablaImpresoras as any).row(indiceFila).data(filaImpresora(datosActuales[0], resultado.printer[0])).draw();\n                  (tablaImpresoras as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                }\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar impresora  //////////////////////\r\n    function eliminarImpresora(e:Event){\r\n      let idimpresora = (e.target as HTMLElement).parentElement!.id, info = (tablaImpresoras as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idimpresora = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n      indiceFila = (tablaImpresoras as any).row((e.target as HTMLElement).closest('tr')).index();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          buttonsStyling: false,\n          icon: 'question',\n          title: 'Eliminar impresora',\n          html: '<strong>Esta accion no se puede deshacer.</strong><br>La impresora sera eliminada definitivamente.',\n          showCancelButton: true,\n          confirmButtonText: 'Si, eliminar',\n          cancelButtonText: 'No',\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idimpresora);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarImpresora\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\n                        (tablaImpresoras as any).row(indiceFila+info.start).remove().draw(); \n                        (tablaImpresoras as any).page(info.page).draw('page'); \n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          buttonsStyling: false,\n                          icon: 'success',\n                          title: 'Impresora eliminada',\n                          text: resultado.exito[0],\n                          confirmButtonText: 'OK'\n                        })\n                      }else{\n                          Swal.fire({\n                            customClass: {\n                              popup: 'j2-confirm j2-confirm--danger',\n                              icon: 'j2-confirm__icon',\n                              title: 'j2-confirm__title',\n                              htmlContainer: 'j2-confirm__text',\n                              actions: 'j2-confirm__actions j2-confirm__actions--single',\n                              confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                            },\n                            buttonsStyling: false,\n                            icon: 'error',\n                            title: 'No se pudo eliminar',\n                            text: resultado.error[0],\n                            confirmButtonText: 'OK'\n                          })\n                      }\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoIMpresora || (event.target as HTMLInputElement).value === 'Salir') {\r\n          miDialogoIMpresora.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateIMpresora') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n  }\r\n\r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.mediosPagos')){\r\n    const crearMedioPago = document.querySelector('#crearMedioPago') as HTMLButtonElement;\r\n    const miDialogoMedioPago = document.querySelector('#miDialogoMedioPago') as any;\r\n\r\n    let indiceFila=0, control=0, tablamediosPagos:HTMLElement;\r\n\r\n    type mediospagoapi = {\r\n        id:string,\r\n        mediopago: string,\r\n        estado: string,\r\n        nick: string\r\n      };\n  \n      let mediospagos:mediospagoapi[]=[], unmediopago:mediospagoapi|undefined;\n\n      function escapeHtmlMedioPago(valor:any):string{\n        return String(valor ?? '').replace(/[&<>\"']/g, (caracter:string) => ({\n          '&': '&amp;',\n          '<': '&lt;',\n          '>': '&gt;',\n          '\"': '&quot;',\n          \"'\": '&#039;'\n        }[caracter] as string));\n      }\n\n      function renderNombreMedioPago(nombre:any):string{\n        return `<span class=\"config-payment-name\">\n          <span class=\"config-payment-name__icon\"><i class=\"fa-solid fa-credit-card\"></i></span>\n          <span>${escapeHtmlMedioPago(nombre)}</span>\n        </span>`;\n      }\n\n      function renderEstadoMedioPago(id:any, estado:any):string{\n        if(Number(id) === 1)return '';\n        const activo = String(estado) === '1';\n        return `<button id=\"${escapeHtmlMedioPago(id)}\" data-state=\"${activo ? '1' : '0'}\" class=\"statemediopago config-table-status ${activo ? 'config-table-status--active' : 'config-table-status--inactive'}\">${activo ? 'Activo' : 'Inactivo'}</button>`;\n      }\n\n      function renderAccionesMedioPago(medioPago:any):string{\n        if(Number(medioPago?.id) === 1)return '';\n        return `<div class=\"acciones-btns\" id=\"${escapeHtmlMedioPago(medioPago?.id)}\" data-mediopago=\"${escapeHtmlMedioPago(medioPago?.mediopago)}\">\n          <button class=\"btn-md btn-turquoise editarMedioPago\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n          <button class=\"btn-md btn-red eliminarMedioPago\"><i class=\"fa-solid fa-trash-can\"></i></button>\n        </div>`;\n      }\n\n      function filaMedioPago(numero:number, medioPago:any):any[]{\n        return [\n          numero,\n          renderNombreMedioPago(medioPago?.mediopago),\n          renderEstadoMedioPago(medioPago?.id, medioPago?.estado),\n          renderAccionesMedioPago(medioPago)\n        ];\n      }\n\n      (async ()=>{\n        try {\r\n            const url = \"/admin/api/allmediospago\"; //llamado a la API REST y se trae todos las medios de pago\r\n            const respuesta = await fetch(url); \r\n            mediospagos = await respuesta.json(); \r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n    //////////////////  TABLA //////////////////////\n  tablamediosPagos = ($('#tablamediosPagos') as any).DataTable(configdatatablesToolbar);\n   modernizarToolbarDataTable('#tablamediosPagos');\n\n    crearMedioPago.addEventListener('click', ()=>{\r\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalMedioPago')!.textContent = \"Crear medio de pago\";\r\n        (document.querySelector('#btnEditarCrearMedioPago') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoMedioPago.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    document.querySelector('#tablamediosPagos')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if(target?.classList.contains(\"statemediopago\"))changeState(e);\r\n      if(target?.classList.contains(\"editarMedioPago\")||target.parentElement?.classList.contains(\"editarMedioPago\"))editarMedioPago(e);\r\n      if(target?.classList.contains(\"eliminarMedioPago\")||target.parentElement?.classList.contains(\"eliminarMedioPago\"))eliminarMedioPago(e);\r\n    });\r\n\r\n\r\n    ///////////////  Cambiar estado del medio de pago  ////////////////\r\n    function changeState(e:Event){\r\n      const button=(e.target as HTMLButtonElement), info = (tablamediosPagos as any).page.info();\r\n      indiceFila =  (tablamediosPagos as any).row(button.closest('tr')).index();\r\n      (async ()=>{ \r\n        const datos = new FormData();\r\n        datos.append('id', button.id);\r\n        datos.append('estado', button.dataset.state=='0'?'1':'0');\r\n        try {\r\n            const url = \"/admin/api/updateStateMedioPago\";\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();  \r\n            if(resultado.exito !== undefined){\r\n              const s1 = renderEstadoMedioPago(button.id, button.dataset.state=='0'?'1':'0');\n              (tablamediosPagos as any).cell((tablamediosPagos as any).row(indiceFila+=info.start), 2).data(s1).draw(); //se modifica solo la columna con la fila correspondiente, y destruye la que habai antes\r\n              (tablamediosPagos as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n            }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();//cierre de async()\r\n    }\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar medio de pago  //////////////////////\r\n    function editarMedioPago(e:Event){\r\n      let idmediopago = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idmediopago = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n      document.querySelector('#modalMedioPago')!.textContent = \"Actualizar medio de pago\";\r\n      (document.querySelector('#btnEditarCrearMedioPago') as HTMLInputElement)!.value = \"Actualizar\";\r\n      \r\n      unmediopago = mediospagos.find(x => x.id==idmediopago); //me trae el emdio de pago seleccionado\r\n      (document.querySelector('#nombreMedioPago')as HTMLInputElement).value = unmediopago?.mediopago!;\r\n      \r\n      indiceFila = (tablamediosPagos as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoMedioPago.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar medio de pago  //////////////////////\r\n    document.querySelector('#formCrearUpdateMedioPago')?.addEventListener('submit', e=>{\r\n      let urlApi = \"crearMedioPago\";\r\n      if(control)urlApi = \"actualizarMedioPago\";\r\n\r\n        e.preventDefault();\r\n        var info = (tablamediosPagos as any).page.info();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unmediopago?.id?unmediopago?.id:'');\r\n          datos.append('mediopago', $('#nombreMedioPago').val()as string);\r\n          try {\r\n              const url = \"/admin/api/\"+urlApi;\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                miDialogoMedioPago.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                if(!control){ //si es crear registro\r\n                  /// actualizar el arregle de los medios de pagos ///\r\n                  mediospagos = [...mediospagos, resultado.mediopago];\r\n                  (tablamediosPagos as any).row.add(filaMedioPago((tablamediosPagos as any).rows().count() + 1, resultado.mediopago)).draw(false); // draw(false) evita recargar toda la tabla\n                }else{ //si es actualizar\n                  /// actualizar el arregle de medios de pagos ///\n                  const medioActualizado = Array.isArray(resultado.mediopago) ? resultado.mediopago[0] : resultado.mediopago;\n                  mediospagos.forEach(a=>{if(a.id == unmediopago?.id)a = Object.assign(a, medioActualizado);});\n                  indiceFila += info.start;\n                  const datosActuales = (tablamediosPagos as any).row(indiceFila).data();\n                  (tablamediosPagos as any).row(indiceFila).data(filaMedioPago(datosActuales[0], medioActualizado)).draw();\n                  (tablamediosPagos as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                }\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar medio de pago  //////////////////////\r\n    function eliminarMedioPago(e:Event){\r\n      let idmediopago = (e.target as HTMLElement).parentElement!.id, info = (tablamediosPagos as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idmediopago = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n      indiceFila = (tablamediosPagos as any).row((e.target as HTMLElement).closest('tr')).index();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          buttonsStyling: false,\n          icon: 'question',\n          title: 'Eliminar medio de pago',\n          html: '<strong>Esta accion no se puede deshacer.</strong><br>El medio de pago sera eliminado definitivamente.',\n          showCancelButton: true,\n          confirmButtonText: 'Si, eliminar',\n          cancelButtonText: 'No',\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idmediopago);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarMedioPago\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\n                        (tablamediosPagos as any).row(indiceFila+info.start).remove().draw(); \n                        (tablamediosPagos as any).page(info.page).draw('page'); \n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          buttonsStyling: false,\n                          icon: 'success',\n                          title: 'Medio eliminado',\n                          text: resultado.exito[0],\n                          confirmButtonText: 'OK'\n                        })\n                      }else{\n                          Swal.fire({\n                            customClass: {\n                              popup: 'j2-confirm j2-confirm--danger',\n                              icon: 'j2-confirm__icon',\n                              title: 'j2-confirm__title',\n                              htmlContainer: 'j2-confirm__text',\n                              actions: 'j2-confirm__actions j2-confirm__actions--single',\n                              confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                            },\n                            buttonsStyling: false,\n                            icon: 'error',\n                            title: 'No se pudo eliminar',\n                            text: resultado.error[0],\n                            confirmButtonText: 'OK'\n                          })\n                      }\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoMedioPago || (event.target as HTMLInputElement).value === 'Salir') {\r\n          miDialogoMedioPago.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n          /*if((event.target as HTMLElement).closest('.finCerrarcaja')){  //Cuando se hace el cierre de caja\r\n            confirmarcierre();\r\n          }*/\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateMedioPago') as HTMLFormElement)?.reset();\n    }\r\n  }\r\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.tarifas')){\r\n    const crearTarifa = document.querySelector('#crearTarifa') as HTMLButtonElement;\r\n    const miDialogoTarifa = document.querySelector('#miDialogoTarifa') as any;\r\n\r\n    let indiceFila=0, control=0, tablaTarifas:HTMLElement;\r\n\r\n    type tarifasapi = {\r\n        id:string,\r\n        nombre: string,\r\n        valor: string,\r\n      };\n  \n      let tarifas:tarifasapi[]=[], unatarifa:tarifasapi|undefined;\n\n      function escapeHtmlTarifa(valor:any):string{\n        return String(valor ?? '').replace(/[&<>\"']/g, (caracter:string) => ({\n          '&': '&amp;',\n          '<': '&lt;',\n          '>': '&gt;',\n          '\"': '&quot;',\n          \"'\": '&#039;'\n        }[caracter] as string));\n      }\n\n      function formatoMonedaTarifa(valor:any):string{\n        return '$' + Number(valor ?? 0).toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\n      }\n\n      function renderNombreTarifa(nombre:any):string{\n        return `<span class=\"config-tarifa-name\">\n          <span class=\"config-tarifa-name__icon\"><i class=\"fa-solid fa-percent\"></i></span>\n          <span>${escapeHtmlTarifa(nombre)}</span>\n        </span>`;\n      }\n\n      function renderPillTarifa(valor:any, modificador:string):string{\n        return `<span class=\"config-table-pill config-table-pill--${modificador}\">${escapeHtmlTarifa(valor)}</span>`;\n      }\n\n      function filaTarifa(numero:number, tarifa:any):any[]{\n        return [\n          numero,\n          renderNombreTarifa(tarifa?.nombre),\n          renderPillTarifa(formatoMonedaTarifa(tarifa?.valor), 'money'),\n          `<div class=\"acciones-btns\" id=\"${escapeHtmlTarifa(tarifa?.id)}\" data-tarifa=\"${escapeHtmlTarifa(tarifa?.nombre)}\">\n              <button class=\"btn-md btn-turquoise editarTarifa\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n              <button class=\"btn-md btn-red eliminarTarifa\"><i class=\"fa-solid fa-trash-can\"></i></button>\n          </div>`\n        ];\n      }\n\n      (async ()=>{\n        try {\r\n            const url = \"/admin/api/alltarifas\"; //llamado a la API REST y se trae todos las tarifas\r\n            const respuesta = await fetch(url); \r\n            tarifas = await respuesta.json(); \r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n    //////////////////  TABLA //////////////////////\n  tablaTarifas = ($('#tablaTarifas') as any).DataTable(configdatatablesToolbar);\n   modernizarToolbarDataTable('#tablaTarifas');\n\n    crearTarifa.addEventListener('click', ()=>{\r\n        control = 0;\r\n        limpiarformdialog();\r\n        document.querySelector('#modalTarifa')!.textContent = \"Crear tarifa\";\r\n        (document.querySelector('#btnEditarCrearTarifa') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoTarifa.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    document.querySelector('#tablaTarifas')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if((e.target as HTMLElement)?.classList.contains(\"editarTarifa\")||(e.target as HTMLElement).parentElement?.classList.contains(\"editarTarifa\"))editarTarifa(e);\r\n      if(target?.classList.contains(\"eliminarTarifa\")||target.parentElement?.classList.contains(\"eliminarTarifa\"))eliminarTarifa(e);\r\n    });\r\n\r\n    //////////////////// ventana modal al Actualizar/Editar tarifa  //////////////////////\r\n    function editarTarifa(e:Event){\r\n      let idtarifa = (e.target as HTMLElement).parentElement?.id;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idtarifa = (e.target as HTMLElement).parentElement?.parentElement?.id;\r\n      control = 1;\r\n      document.querySelector('#modalTarifa')!.textContent = \"Actualizar tarifa\";\r\n      (document.querySelector('#btnEditarCrearTarifa') as HTMLInputElement)!.value = \"Actualizar\";\r\n      \r\n      unatarifa = tarifas.find(x => x.id==idtarifa); //me trae a la tarifa seleccionada\r\n      (document.querySelector('#nombreTarifa')as HTMLInputElement).value = unatarifa?.nombre!;\r\n      (document.querySelector('#valorTarifa')as HTMLInputElement).value = unatarifa?.valor!;\r\n      \r\n      indiceFila = (tablaTarifas as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      miDialogoTarifa.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n    ////////////////////  Actualizar/Editar tarifa  //////////////////////\r\n    document.querySelector('#formCrearUpdateTarifa')?.addEventListener('submit', e=>{\r\n      let urlApi = \"crearTarifa\";\r\n      if(control)urlApi = \"actualizarTarifa\";\r\n\r\n        e.preventDefault();\r\n        var info = (tablaTarifas as any).page.info();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          datos.append('id', unatarifa?.id?unatarifa?.id:'');\r\n          datos.append('nombre', $('#nombreTarifa').val()as string);\r\n          datos.append('valor', $('#valorTarifa').val()as string);\r\n          try {\r\n              const url = \"/admin/api/\"+urlApi;\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                miDialogoTarifa.close();\r\n                document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                if(!control){ //si es crear registro\r\n                  /// actualizar el arregle de la tarifa ///\r\n                  tarifas = [...tarifas, resultado.tarifa];\r\n                  (tablaTarifas as any).row.add(filaTarifa((tablaTarifas as any).rows().count() + 1, resultado.tarifa)).draw(false); // draw(false) evita recargar toda la tabla\n                }else{ //si es actualizar\n                  /// actualizar el arregle de tarifas ///\n                  tarifas.forEach(a=>{if(a.id == unatarifa?.id)a = Object.assign(a, resultado.tarifa[0]);});\n                  indiceFila += info.start;\n                  const datosActuales = (tablaTarifas as any).row(indiceFila).data();\n                  (tablaTarifas as any).row(indiceFila).data(filaTarifa(datosActuales[0], resultado.tarifa[0])).draw();\n                  (tablaTarifas as any).page(info.page).draw('page'); //me mantiene la pagina actual\r\n                }\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n    ////////////////////  Eliminar tarifa  //////////////////////\r\n    function eliminarTarifa(e:Event){\r\n      let idtarifa = (e.target as HTMLElement).parentElement!.id, info = (tablaTarifas as any).page.info();\r\n      if((e.target as HTMLElement).tagName === 'I')idtarifa = (e.target as HTMLElement).parentElement!.parentElement!.id;\r\n      indiceFila = (tablaTarifas as any).row((e.target as HTMLElement).closest('tr')).index();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          buttonsStyling: false,\n          icon: 'question',\n          title: 'Eliminar tarifa',\n          html: '<strong>Esta accion no se puede deshacer.</strong><br>La tarifa sera eliminada definitivamente.',\n          showCancelButton: true,\n          confirmButtonText: 'Si, eliminar',\n          cancelButtonText: 'No',\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idtarifa);\r\n                  try {\r\n                      const url = \"/admin/api/eliminarTarifa\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\n                        (tablaTarifas as any).row(indiceFila+info.start).remove().draw(); \n                        (tablaTarifas as any).page(info.page).draw('page'); \n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          buttonsStyling: false,\n                          icon: 'success',\n                          title: 'Tarifa eliminada',\n                          text: resultado.exito[0],\n                          confirmButtonText: 'OK'\n                        })\n                      }else{\n                          Swal.fire({\n                            customClass: {\n                              popup: 'j2-confirm j2-confirm--danger',\n                              icon: 'j2-confirm__icon',\n                              title: 'j2-confirm__title',\n                              htmlContainer: 'j2-confirm__text',\n                              actions: 'j2-confirm__actions j2-confirm__actions--single',\n                              confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                            },\n                            buttonsStyling: false,\n                            icon: 'error',\n                            title: 'No se pudo eliminar',\n                            text: resultado.error[0],\n                            confirmButtonText: 'OK'\n                          })\n                      }\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if (event.target === miDialogoTarifa || (event.target as HTMLInputElement).value === 'Salir') {\r\n          miDialogoTarifa.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n          /*if((event.target as HTMLElement).closest('.finCerrartarifa')){  //Cuando se hace el cierre de tarifa\r\n            confirmarcierre();\r\n          }*/\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateTarifa') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n  }\r\n\r\n})();\n","(()=>{\r\n    if(document.querySelector('.adicionarProducto')){\r\n        \r\n        const btnAddItem = document.querySelector('#btnAddItem') as HTMLButtonElement;\r\n        const tablaItems = document.querySelector('#tablaItems tbody');\r\n        const btnUpdateCreditoSeparado = document.querySelector('#btnUpdateCreditoSeparado') as HTMLButtonElement;\r\n\r\n        interface i_itemDetalle {\r\n            id:string, //id del registro de la tabla productosseparados\r\n            idcredito:string,\r\n            idproducto: string,\r\n            idunidadmedida:string,\r\n            tipoproducto:string,\r\n            tipoproduccion:string,\r\n            promediostock:number,\r\n            rendimientoestandar?:string,\r\n            factor?:number,\r\n            nombreproducto:string,\r\n            unidadmedida:string,\r\n            preciopersonalizado:string,\r\n            sku:string,\r\n            stockminimo?:string,\r\n\r\n            capital?:number,            //DATOS DEL CREDITO\r\n            abonoinicial?:number,      //abono inicial en el credito\r\n            saldopendiente?:number,\r\n            cantidadcuotas?:number,\r\n            interes?:string,           // 1 = si interes en el credito, 0 = no interes en el credito\r\n            interestotal?:number,      //interes total dlecredito en porcentaje\r\n            valorinterestotal?:number, //valor del interes total de credito\r\n            montototal?:number,\r\n            descuentocredito?:number,  //descuneto general en el credito\r\n            \r\n            costo:number,\r\n            valorunidad:number,\r\n            descuento:number,  //se calcula para productos nuevos agregados\r\n            cantidad:number,   //se calcula para productos nuevos agregados\r\n            stock?:number,\r\n            base:number,       //se calcula para productos nuevos agregados\r\n            impuesto:string,\r\n            valorimp:number,   //se calcula para productos nuevos agregados\r\n            subtotal:number,   //se calcula para productos nuevos agregados\r\n            total:number,      //se calcula para productos nuevos agregados\r\n            insumos?:insumo[];\r\n        }\r\n\r\n        /*interface i_allProducts {\r\n            id:string,  //id del producto\r\n            idunidadmedida:string, \r\n            nombre:string,\r\n            impuesto:string,\r\n            tipoproducto:string, \r\n            tipoproduccion:string, \r\n            sku:string, \r\n            unidadmedida:string,\r\n            promediostock:number,\r\n            preciopersonalizado:string,\r\n            rendimientoestandar:string, \r\n            stockminimo:string,\r\n            precio_compra:number,\r\n            precio_venta:number\r\n            habilitarventa:string, \r\n            visible:string,\r\n        }*/\r\n\r\n        interface Item {\r\n            id_impuesto: number,\r\n            facturaid: number,\r\n            basegravable: number,\r\n            valorimpuesto: number\r\n        }\r\n\r\n\r\n        let factimpuestos:Item[] = [];\r\n        let carrito:i_itemDetalle[]=[];\r\n        let allproducts:productsapi[] = [];\r\n        let filteredData: {id:string, text:string, tipo:string, tipoproducto:string, tipoproduccion:string, sku:string, unidadmedida:string, precio:string, promediostock:string}[];   //tipoproducto = 0 es producto simple,  1 = compuesto,  si no viene es subproducto, tipo=0 es producto(simple o compuesto), tipo=1 es subproducto\r\n        const valorTotal = {subtotal: 0, base: 0, valorimpuestototal: 0, dctox100: 0, descuento: 0, total: 0}; //datos global de la venta\r\n        const dataCredit = {capital:0, abonoinicial:0, saldopendiente:0, cantidadcuotas:0, interes:'0', interestotal:0, valorinterestotal:0, montototal:0, descuentocredito: 0};\r\n\r\n        const constImp: {[key:string]: number} = {};\r\n        constImp['excluido'] = 0;\r\n        constImp['0'] = 0;  //exento de iva, tarifa 0%\r\n        constImp['5'] = 0.0476190476190476; //iva, tarifa al 5%,  Bienes/servicios al 5\r\n        constImp['8'] = 0.0740740740740741; //inc, tarifa al 8%,  impuesto nacional al consumo\r\n        constImp['16'] = 0.1379310344827586; //iva, tarifa al 16%,  contratos firmados con el estado antes de ley 1819\r\n        constImp['19'] = 0.1596638655462185; //iva, tarifa al 19%,  tarifa general\r\n\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/allproducts\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas los productos simples y compuestos\r\n                const respuesta = await fetch(url);\r\n                const resultado:productsapi[] = await respuesta.json();\r\n                filteredData = resultado.filter(x=>x.habilitarventa=='1'&&x.visible=='1').map(item => ({ id: item.id, text: item.nombre, tipo:item.tipoproducto??'1', tipoproducto: item.tipoproducto, tipoproduccion: item.tipoproduccion, sku: item.sku, unidadmedida: item.unidadmedida, precio: item.precio_venta+'', promediostock: item.promediostock??'1' }));\r\n                activarselect2();\r\n                allproducts = resultado.filter(x=>x.habilitarventa=='1'&&x.visible=='1');\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n        \r\n        const parametrosURL = new URLSearchParams(window.location.search);\r\n        const idcreditoURL = parametrosURL.get('id');\r\n        if(idcreditoURL!=null && /^\\d+$/.test(idcreditoURL) && Number(idcreditoURL) >= 1){\r\n            (async ()=>{\r\n                try {\r\n                    const url = \"/admin/api/detalleProductosCredito?id=\"+idcreditoURL; //llamado a la API REST y trae el detalle de los productos de credito/separado\r\n                    const respuesta = await fetch(url); \r\n                    const resultado:i_itemDetalle[] = await respuesta.json();\r\n                    console.log(resultado);\r\n                    carrito = resultado.map(item =>{\r\n                        \r\n                        return {\r\n                            id: item.id,\r\n                            idcredito: item.idcredito,\r\n                            idproducto:item.idproducto,\r\n                            idunidadmedida: item.idunidadmedida,\r\n                            tipoproducto: item.tipoproducto, \r\n                            tipoproduccion: item.tipoproduccion,\r\n                            promediostock: Number(item.promediostock),\r\n                            rendimientoestandar: item.rendimientoestandar,\r\n                            nombreproducto: item.nombreproducto, \r\n                            unidadmedida: item.unidadmedida,\r\n                            preciopersonalizado: item.preciopersonalizado,\r\n                            sku: item.sku,\r\n                            costo: Number(item.costo),\r\n                            valorunidad: Number(item.valorunidad),\r\n                            descuento: Number(item.descuento), //descuento del producto\r\n                            cantidad: Number(item.cantidad),\r\n                            stock: Number(item.cantidad),\r\n                            base: Number(item.base),\r\n                            impuesto: item.impuesto,\r\n                            valorimp: Number(item.valorimp),\r\n                            subtotal: Number(item.subtotal),\r\n                            total: Number(item.total),\r\n                            factor: 1,\r\n                        }\r\n                    });\r\n                    carrito.forEach((c, i) =>printItemTable(c.unidadmedida, c.cantidad, c.nombreproducto, c.valorunidad, c.total, i));\r\n                    //obtener datos del credito\r\n\r\n                    dataCredit.capital = Number(resultado[0].capital);\r\n                    dataCredit.abonoinicial = Number(resultado[0].abonoinicial!);\r\n                    dataCredit.saldopendiente = Number(resultado[0].saldopendiente);\r\n                    dataCredit.cantidadcuotas = Number(resultado[0].cantidadcuotas);\r\n                    dataCredit.interes = resultado[0].interes!;\r\n                    dataCredit.interestotal = resultado[0].interestotal!;\r\n                    dataCredit.valorinterestotal = Number(resultado[0].valorinterestotal!);\r\n                    dataCredit.montototal = Number(resultado[0].montototal);\r\n                    dataCredit.descuentocredito = Number(resultado[0].descuentocredito!);\r\n                    \r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n        }\r\n        \r\n        \r\n\r\n        function activarselect2(){\n            ($('#articulo') as any).select2({ \n                width: '100%',\n                data: filteredData,\n                placeholder: \"\",\n                maximumSelectionLength: 1,\n                dropdownCssClass: 'adicionar-producto-select2-dropdown',\n            });  \n\n            const contenedorArticulo = document.querySelector('.adicionar-producto-input--select2') as HTMLElement|null;\n            contenedorArticulo?.addEventListener('click', (event)=>{\n                if((event.target as HTMLElement).closest('.select2-selection__choice__remove'))return;\n                ($('#articulo') as any).select2('open');\n            });\n\n            $('#articulo').on('select2:open', ()=>{\n                contenedorArticulo?.classList.add('is-select2-open');\n                const inputBusqueda = document.querySelector('.select2-container--open .select2-search__field') as HTMLInputElement|null;\n                inputBusqueda?.focus();\n            });\n            $('#articulo').on('select2:close', ()=> contenedorArticulo?.classList.remove('is-select2-open'));\n        }\n\r\n        $(\"#articulo\").on('change', (e)=>{\n            let datos = ($('#articulo') as any).select2('data')[0];\n            if(datos)(document.querySelector('#unidadmedida') as HTMLInputElement).value = datos.unidadmedida;\n        });\n\n        function limpiarSelectorArticulo():void{\n            ($('#articulo') as any).val(null).trigger('change');\n            (document.querySelector('#unidadmedida') as HTMLInputElement).value = '';\n            (document.querySelector('#cantidad') as HTMLInputElement).value = '1';\n            (document.querySelector('.adicionar-producto-input--select2') as HTMLElement|null)?.classList.remove('is-select2-open');\n        }\n\n        btnAddItem.addEventListener('click', (e)=>{\n            let cantidad = parseFloat((document.querySelector('#cantidad') as HTMLInputElement).value);\n            let datos = ($('#articulo') as any).select2('data')[0];\n            if(!datos)return;\n            const itemselected = allproducts.find(x=>x.id == datos.id);\n            if(itemselected){\r\n                const productoConfigurado = structuredClone(itemselected);\r\n                //filtrarInsumos(productoConfigurado);\r\n                const index = carrito.findIndex(x=>x.idproducto==datos.id /*&& x.valorunidad == Number(datos.precio) && mismaConfiguracion(x, productoConfigurado!)*/);\r\n                if(index == -1){  //si el item seleccionado no existe en el carrito, agregarlo.\r\n\r\n                    const productototal = Number(productoConfigurado.precio_venta)*cantidad;\r\n                    const productovalorimp = productototal*constImp[productoConfigurado.impuesto??'0']; //si producto.impuesto es null toma el valor de cero\r\n\r\n                    const item:i_itemDetalle = {\r\n                        id: '',\r\n                        idcredito: idcreditoURL!,\r\n                        idproducto:productoConfigurado.id,\r\n                        idunidadmedida: productoConfigurado.idunidadmedida,\r\n                        //tipo: itemselected.tipo,  ////tipo = 0 es producto (simple o compuesto produccion),  1 = subproducto\r\n                        tipoproducto: productoConfigurado.tipoproducto, \r\n                        tipoproduccion: productoConfigurado.tipoproduccion,\r\n                        promediostock: Number(productoConfigurado.promediostock),\r\n                        rendimientoestandar: productoConfigurado.rendimientoestandar,\r\n                        nombreproducto: productoConfigurado.nombre, \r\n                        unidadmedida: productoConfigurado.unidadmedida,\r\n                        preciopersonalizado: '0',\r\n                        sku: productoConfigurado.sku,\r\n                        costo: Number(productoConfigurado.precio_compra),\r\n                        valorunidad: Number(productoConfigurado.precio_venta),\r\n                        descuento: 0,\r\n                        cantidad: cantidad,\r\n                        stock: cantidad,\r\n                        base: productototal-productovalorimp,\r\n                        impuesto: productoConfigurado.impuesto,\r\n                        valorimp: productovalorimp,\r\n                        subtotal: productototal,\r\n                        total: productototal,\r\n                        factor: 1,\r\n                    }\r\n                    carrito = [...carrito, item];\r\n                    const indice = carrito.length - 1;\r\n                    printItemTable(productoConfigurado.unidadmedida, cantidad, productoConfigurado.nombre, Number(productoConfigurado.precio_venta), item.total, indice);\r\n                    valorCarritoTotal();\r\n                }else{\r\n                    carrito[index].cantidad = cantidad;\r\n                    carrito[index].stock = cantidad;\r\n                    carrito[index].subtotal = (carrito[index].valorunidad)*carrito[index].cantidad;\r\n                    carrito[index].total = carrito[index].subtotal;\r\n                    //calculo del impuesto y base por producto en el carrito deventas\r\n                    carrito[index].valorimp = parseFloat((carrito[index].total*constImp[carrito[index].impuesto??0]).toFixed(3));\r\n                    carrito[index].base = parseFloat((carrito[index].total-carrito[index].valorimp).toFixed(3));\r\n                    //calcular valores\r\n                    const tr = document.querySelector(`[data-index=\"${index}\"]`)!;\r\n                    tr.children[1].textContent = carrito[index].cantidad+'';\n                    valorCarritoTotal();\n                }\n                limpiarSelectorArticulo();\n            }\n        });\n\r\n\r\n        /*function mismaConfiguracion(productCarrito: any, producto2: productsapi):boolean {\r\n            const mapaProduct2 = new Map(producto2.insumos.map((ins:any) => [ins.id_subproducto, ins]));\r\n            // Deben ser el mismo producto\r\n            if(productCarrito.idproducto !== producto2.id)return false;\r\n\r\n            // Deben tener la misma cantidad de insumos\r\n            if(productCarrito.insumos.length !== producto2.insumos.length)return false;\r\n\r\n            for (const insumo1 of productCarrito.insumos) {\r\n                //const insumo2 = producto2.insumos.find((x:any) => x.id_subproducto == insumo1.id_subproducto);\r\n                const insumo2:any = mapaProduct2.get(insumo1.id_subproducto);\r\n                if (!insumo2)return false;\r\n                // Comparar selección\r\n                if (Number(insumo1.seleccionado) !== Number(insumo2.seleccionado))\r\n                    return false;\r\n                // Comparar cantidad\r\n                if (Number(insumo1.cantidadsubproducto) !== Number(insumo2.cantidadsubproducto))\r\n                    return false;\r\n            }\r\n            return true;\r\n        }*/\r\n\r\n        function printItemTable(unidadmedida:string, cantidad:number, nombre:string, valorunidad:number, total:number, indice:number){\r\n            const tr = document.createElement('TR');\r\n            tr.classList.add('itemselect');\r\n            tr.dataset.index = `${indice}`;\r\n            tr.insertAdjacentHTML('afterbegin', \r\n                `<td class=\"p-4\">${nombre}</td>\r\n                <td class=\"p-4\">${cantidad}</td>\r\n                <td class=\"p-4\">${unidadmedida}</td>\r\n                <td class=\"p-4\">$ ${valorunidad.toLocaleString()}</td>\r\n                <td class=\"p-4\">$ ${total.toLocaleString()}</td>\r\n                <td class=\"p-4 flex items-center justify-center gap-2\">\r\n                    <button class=\"flex items-center gap-1 px-3 py-1 text-base text-indigo-600 border border-indigo-200 rounded-lg hover:bg-indigo-50\">\r\n                        👁 Ver\r\n                    </button>\r\n                    <button class=\"eliminarItem w-11 h-11 flex items-center justify-center text-rose-600 border border-rose-200 rounded-full hover:bg-rose-50 text-xl\">❌</button>\r\n                </td>`);\r\n            tablaItems?.appendChild(tr);\r\n        }\r\n\r\n\r\n        function valorCarritoTotal(){\r\n            //calcular el impuesto discriminado por tarifa\r\n            const idimpuesto: Record<string, number> = {'0': 1, '5': 2, '16': 3, '19': 4, 'excluido': 5, '8': 6 };\r\n            const objbase:{'0':number, '5':number, '16':number, '19':number, 'excluido':number, '8':number} = {'0': 0, '5': 0, '16': 0, '19': 0, 'excluido':0, '8': 0};\r\n\r\n            const mapImpuesto = new Map();\r\n            carrito.forEach(x=>{\r\n                if(x.impuesto){\r\n                if(mapImpuesto.has(x.impuesto)){\r\n                    const valor = mapImpuesto.get(x.impuesto) + x.total*constImp[x.impuesto];\r\n                    mapImpuesto.set(x.impuesto, valor);\r\n                }else{\r\n                    mapImpuesto.set(x.impuesto, x.total*constImp[x.impuesto]);\r\n                }\r\n                }\r\n                if(x.impuesto == null)x.impuesto = \"excluido\";\r\n                objbase[x.impuesto as keyof typeof objbase] += x.base;\r\n                const impValor = mapImpuesto.get(x.impuesto)??0;\r\n                const index = factimpuestos.findIndex(Obj=>Obj.id_impuesto == idimpuesto[x.impuesto]);\r\n                if(index!=-1){ //si existe remplazar obj\r\n                    factimpuestos[index] = {id_impuesto:idimpuesto[x.impuesto], facturaid:0, basegravable:objbase[x.impuesto as keyof typeof objbase], valorimpuesto: impValor};\r\n                }else{\r\n                    factimpuestos = [...factimpuestos, {id_impuesto:idimpuesto[x.impuesto], facturaid:0, basegravable:objbase[x.impuesto as keyof typeof objbase], valorimpuesto: impValor}];\r\n                }\r\n            });\r\n\r\n            //Valor del impuesto total de todos los productos, es decir de la factura;\r\n            let valorTotalImp:number = 0;\r\n            for(let valorImp of mapImpuesto.values())valorTotalImp += valorImp;\r\n            \r\n            valorTotal.valorimpuestototal = parseFloat(valorTotalImp.toFixed(3));  //valor del impuesto total factura de todos los productos\r\n            valorTotal.subtotal = carrito.reduce((total, x)=>x.total+total, 0);\r\n            valorTotal.base = valorTotal.subtotal - valorTotal.valorimpuestototal;  //valor de la base total factura de todos los productos\r\n            valorTotal.total = valorTotal.subtotal+dataCredit.valorinterestotal-dataCredit.descuentocredito-dataCredit.abonoinicial;\r\n            //console.log(valorTotal);\r\n            //console.log(factimpuestos);\r\n            document.querySelector('#subTotal')!.textContent = '$'+valorTotal.subtotal.toLocaleString();\r\n            (document.querySelector('#impuesto') as HTMLElement).textContent = '$'+valorTotalImp.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n            document.querySelector('#total')!.textContent = '$ '+(valorTotal.total).toLocaleString(); //+ interes - descuneto - abonoinicial\r\n            \r\n        }\r\n\r\n\r\n        //////////////////////////////////// evento a la tabla de los productos seleccionados  ///////////////////////////////////\r\n        tablaItems?.addEventListener('click', (e:Event)=>{\r\n            const elementItem = (e.target as HTMLElement)?.closest('.itemselect'); //seleccionamos el tr de la tabla\r\n            const indexcarrito = Number((elementItem as HTMLElement).dataset.index!);\r\n        \r\n            if((e.target as HTMLElement).classList.contains('eliminarItem')){ //se trae todoscon true menos el que coincida con iditem y tipoitem\r\n                carrito.splice(indexcarrito, 1);\r\n                while(tablaItems.firstChild)tablaItems.removeChild(tablaItems.firstChild);\r\n                carrito.forEach((item, i) =>printItemTable(item.unidadmedida, item.cantidad, item.nombreproducto, item.valorunidad, item.total, i));\r\n                //tablaItems?.querySelector(`TR[data-id=\"${iditem}\"]`)?.remove();\r\n            }\r\n            valorCarritoTotal();\r\n            //itemCarrito.cantidad = itemCarrito.cantidadcomprado*itemCarrito.factor;\r\n        });\r\n\r\n\r\n        btnUpdateCreditoSeparado.addEventListener('click', ()=>{\r\n            //validar que el montototal no sea menor a lo abonado hasta la fecha\r\n            if(valorTotal.total< (dataCredit.montototal-dataCredit.saldopendiente)){\r\n                Swal.fire('El valor del credito es inferior de lo que se ha abonado.', '', 'error')\r\n                return;\r\n            }\r\n\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Esta seguro de actualizar la orden?',\r\n                text: \"Se procesara la orden con todos los productos del separado\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    (async ()=>{ \r\n                        const datos = new FormData();\r\n                        datos.append('idcredito', idcreditoURL!);\r\n                        datos.append('ids', JSON.stringify(carrito.map(x=>x.id)));\r\n                        datos.append('nuevosproductos', JSON.stringify(carrito));\r\n\r\n                        datos.append('factimpuestos', JSON.stringify(factimpuestos));\r\n                        datos.append('capital', valorTotal.subtotal+'');\r\n                        datos.append('saldopendiente', (dataCredit.saldopendiente+valorTotal.total-dataCredit.montototal)+'');\r\n                        datos.append('montocuota', (Math.ceil((valorTotal.total/dataCredit.cantidadcuotas)*100)/100)+'');\r\n                        datos.append('montototal', valorTotal.total+'');\r\n                        datos.append('totalunidades', carrito.reduce((total, x)=>x.cantidad+total, 0)+'');\r\n                        \r\n                        datos.append('base', valorTotal.base.toFixed(3));  //base global del credito\r\n                        datos.append('valorimpuestototal', valorTotal.valorimpuestototal+''); //valor total del impuesto dle credito. \r\n                        datos.append('dctox100', valorTotal.dctox100+'');\r\n                        datos.append('descuento', dataCredit.descuentocredito+''); //descuento global de credito\r\n                    \r\n                        try {\r\n                            const url = \"/admin/api/editarOrdenCreditoSeparado\";  //api llamada a trasladosinvcontrolador\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                            const resultado = await respuesta.json();  \r\n                            if(resultado.exito !== undefined){\r\n                                /*setTimeout(() => {\r\n                                    window.location.href = `/admin/almacen/trasladarinventario`;\r\n                                }, 1600);*/\r\n                                Swal.fire(resultado.exito[0], '', 'success') \r\n                            }else{\r\n                                Swal.fire(resultado.error[0], '', 'error')\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();//cierre de async()\r\n                }\r\n            });\r\n        });\r\n\r\n    }\r\n})();\n","(()=>{\r\n  if(document.querySelector('.detallecredito')){\r\n\r\n     \r\n    const btnajustarCredito = document.querySelector('#ajustarCredito') as HTMLButtonElement;\r\n    const btnDetalleProductos = document.querySelector('#btnDetalleProductos') as HTMLButtonElement;\r\n    const btnAbonar = document.querySelector('#btnAbonar') as HTMLButtonElement;\r\n    const btnEditarCrearAbono = document.querySelector('#btnEditarCrearAbono') as HTMLInputElement;\r\n    const btnEditarCrearPagoTotal = document.querySelector('#btnEditarCrearPagoTotal') as HTMLInputElement;\r\n    const btnPagarTodo = document.querySelector('#btnPagarTodo') as HTMLButtonElement;\r\n    const miDialogoAjustarCredito = document.querySelector('#miDialogoAjustarCredito') as any;\r\n    const miDialogoAbono = document.querySelector('#miDialogoAbono') as any;\r\n    const miDialogoPagoTotal = document.querySelector('#miDialogoPagoTotal') as any;\n    const miDialogoDetalleProducto = document.querySelector('#miDialogoDetalleProducto') as any;\n    const modalcambioMedioPago:any = document.querySelector(\"#cambioMedioPago\");\n    const selectCajaAbono = document.querySelector('#caja') as HTMLSelectElement | null;\n    const selectMedioPagoAbono = document.querySelector('#mediopago') as HTMLSelectElement | null;\n    const selectCajaPagoTotal = document.querySelector('#PagoTotal_caja') as HTMLSelectElement | null;\n    const selectMedioPagoTotal = document.querySelector('#PagoTotal_mediopago') as HTMLSelectElement | null;\n    //const pagarTodo = document.querySelector('#pagarTodo') as HTMLButtonElement;\r\n    const totalPagado = document.querySelector('#totalPagado') as HTMLSpanElement;\r\n    const numCuota = document.querySelector('#numCuota') as HTMLLabelElement;\r\n    const selectMediopago = document.querySelector('#selectMediopago') as HTMLSelectElement;\r\n    const inputPasswordAjustarCredito = document.querySelector('#inputPasswordAjustarCredito') as HTMLInputElement;\r\n    let contentMP:HTMLButtonElement, idcuota:string = '0', idcredito:string = '0', totalpagado:string = '0', idmediopago:string = '0', mediopagado:string = '0';\r\n    \r\n    let printerBT:string = getParam.impresora_principal_de_CAJA_para_Android_por_BT.valor_final;\r\n    let indiceFila=0, tablacuotas:HTMLElement;\r\n\r\n    interface clavesApi {\r\n      clave:string,\r\n      valor_default:string|null,\r\n      valor_final:string|null,\r\n      valor_local:string|null\r\n    };\r\n\r\n    let password:clavesApi[];\r\n\r\n    (async ()=>{\r\n      try {\r\n          const url = \"/admin/api/getPasswords\"; //llamado a la API REST\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json(); \r\n          password = resultado;\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();\r\n\r\n    \r\n    document.addEventListener(\"click\", cerrarDialogoExterno);\n\n    inicializarSelectsAbono();\n     \n    //////////////////  TABLA //////////////////////\n    tablacuotas = ($('#tablacuotas') as any).DataTable(configdatatablesToolbar);\n    modernizarToolbarDataTable('#tablacuotas');\n    pintarPaginadorCuotas();\n    [80, 250, 600, 1000].forEach((tiempo)=>window.setTimeout(pintarPaginadorCuotas, tiempo));\n    ($('#tablacuotas') as any).on('draw.dt', pintarPaginadorCuotas);\n\n    const autoPrintAbonoCredito = document.querySelector('#autoPrintAbonoCredito') as HTMLInputElement | null;\n    if(autoPrintAbonoCredito?.value){\n      window.setTimeout(()=>printPOSComprobanteAbono(autoPrintAbonoCredito.value), 450);\n    }\n\n\n    btnajustarCredito?.addEventListener('click', ():void=>{\n      miDialogoAjustarCredito.showModal();\r\n    });\r\n\r\n    btnDetalleProductos?.addEventListener('click', ():void=>{\r\n      miDialogoDetalleProducto.showModal();\r\n    });\r\n\r\n    //btn para abonar credito\r\n    btnAbonar?.addEventListener('click', ():void=>{\n      miDialogoAbono.showModal();\n    });\n\r\n    //btn para abonar credito\r\n    btnPagarTodo?.addEventListener('click', ():void=>{\r\n      miDialogoPagoTotal.showModal();\r\n    });\r\n\r\n\r\n    btnEditarCrearAbono.addEventListener('click', ()=>{\r\n      btnEditarCrearAbono.disabled = true;\r\n      (document.querySelector('#caja') as HTMLSelectElement).disabled = false;\r\n      (document.querySelector('#formCrearUpdateAbono') as HTMLFormElement).submit();\r\n    });\r\n    btnEditarCrearPagoTotal.addEventListener('click', ()=>{\n      btnEditarCrearPagoTotal.disabled = true;\n      (document.querySelector('#PagoTotal_caja') as HTMLSelectElement).disabled = false;\n      (document.querySelector('#formCrearUpdatePagoTotal') as HTMLFormElement).submit();\n    });\n\n    function pintarPaginadorCuotas():void{\n      const wrapper = document.querySelector('#tablacuotas_wrapper');\n      if(!wrapper || !tablacuotas)return;\n\n      const info = (tablacuotas as any).page?.info?.();\n      const paginaActual = info ? String(info.page + 1) : '1';\n      const paginador = wrapper.querySelector('.dataTables_paginate, .dt-paging, .pagination');\n      if(!paginador)return;\n\n      paginador.querySelectorAll('.detalle-paginador-current').forEach((boton)=>{\n        boton.classList.remove('detalle-paginador-current');\n      });\n\n      const botonesActuales = Array.from(paginador.querySelectorAll<HTMLElement>(\n        '.paginate_button.current, .paginate_button.active, .dt-paging-button.current, .dt-paging-button.active, [aria-current=\"page\"], .page-item.active .page-link, .page-link.active, span.current, button.current, a.current'\n      ));\n\n      if(!botonesActuales.length){\n        Array.from(paginador.querySelectorAll<HTMLElement>('a, button, span')).forEach((elemento)=>{\n          const texto = elemento.textContent?.trim();\n          const esControl = elemento.classList.contains('previous') || elemento.classList.contains('next') || elemento.classList.contains('first') || elemento.classList.contains('last');\n\n          if(texto === paginaActual && !esControl){\n            botonesActuales.push(elemento);\n          }\n        });\n      }\n\n      botonesActuales.forEach((elemento)=>{\n        elemento.classList.add('detalle-paginador-current');\n        elemento.setAttribute('aria-label', `Pagina ${paginaActual}`);\n        elemento.setAttribute('aria-current', 'page');\n\n        if(elemento.textContent?.trim() !== paginaActual){\n          elemento.textContent = paginaActual;\n        }\n      });\n    }\n\n    function inicializarSelectsAbono():void{\n      if(typeof ($ as any)?.fn?.select2 === 'undefined')return;\n\n      const opcionesSelect2Abono = {\n        dropdownCssClass: 'detalle-abono-select2-dropdown',\n        dropdownParent: $('#miDialogoAbono'),\n        minimumResultsForSearch: Infinity,\n        width: '100%'\n      };\n      const opcionesSelect2PagoTotal = {\n        ...opcionesSelect2Abono,\n        dropdownParent: $('#miDialogoPagoTotal')\n      };\n\n      if(selectCajaAbono && selectCajaAbono.dataset.select2DetalleAbono !== 'true'){\n        ($(selectCajaAbono) as any).select2({\n          ...opcionesSelect2Abono,\n          placeholder: 'Seleccionar caja'\n        });\n        selectCajaAbono.dataset.select2DetalleAbono = 'true';\n      }\n\n      if(selectMedioPagoAbono && selectMedioPagoAbono.dataset.select2DetalleAbono !== 'true'){\n        ($(selectMedioPagoAbono) as any).select2({\n          ...opcionesSelect2Abono,\n          placeholder: 'Seleccionar medio de pago'\n        });\n        selectMedioPagoAbono.dataset.select2DetalleAbono = 'true';\n      }\n\n      if(selectCajaPagoTotal && selectCajaPagoTotal.dataset.select2DetalleAbono !== 'true'){\n        ($(selectCajaPagoTotal) as any).select2({\n          ...opcionesSelect2PagoTotal,\n          placeholder: 'Seleccionar caja'\n        });\n        selectCajaPagoTotal.dataset.select2DetalleAbono = 'true';\n      }\n\n      if(selectMedioPagoTotal && selectMedioPagoTotal.dataset.select2DetalleAbono !== 'true'){\n        ($(selectMedioPagoTotal) as any).select2({\n          ...opcionesSelect2PagoTotal,\n          placeholder: 'Seleccionar medio de pago'\n        });\n        selectMedioPagoTotal.dataset.select2DetalleAbono = 'true';\n      }\n\n      habilitarAperturaSelect2Abono(selectCajaAbono);\n      habilitarAperturaSelect2Abono(selectMedioPagoAbono);\n      habilitarAperturaSelect2Abono(selectCajaPagoTotal);\n      habilitarAperturaSelect2Abono(selectMedioPagoTotal);\n    }\n\n    function habilitarAperturaSelect2Abono(select:HTMLSelectElement | null):void{\n      if(!select)return;\n      const control = select.closest('.detalle-abono-dialog__control') as HTMLElement | null;\n      if(!control || control.dataset.openSelect2 === 'true')return;\n\n      control.dataset.openSelect2 = 'true';\n      control.addEventListener('click', (event:Event):void=>{\n        const target = event.target as HTMLElement;\n        if(select.disabled || target.closest('.select2-container--disabled'))return;\n        ($(select) as any).select2('open');\n      });\n    }\n    \r\n\r\n    let saldopendiente = Number((document.querySelector('#saldopendiente') as HTMLInputElement).value || '0');\n    document.querySelector('#abonoTotalAntiguo')?.addEventListener(\"input\", (e:Event)=>{\n      const abonoTotalAntiguo = (e.target as HTMLInputElement);\n      if(Number(abonoTotalAntiguo.value)>saldopendiente)abonoTotalAntiguo.value = '';\n    });\n\r\n    ////////////// Evento a la tabla cuotas ///////////////\r\n    document.querySelector('#tablacuotas')?.addEventListener(\"click\", (e:Event)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLButtonElement;\r\n      if(target?.classList.contains(\"mediosdepago\")||target.parentElement?.classList.contains(\"mediosdepago\"))cambiomediopago(target);\r\n      if(target?.classList.contains(\"anularAbono\"))anularAbono(target);\r\n      if(target?.classList.contains(\"printPOSAbono\"))printPOSComprobanteAbono(target.parentElement?.id);\r\n    });\r\n\r\n\r\n    function cambiomediopago(target:HTMLButtonElement){\r\n      document.querySelector('#textMP')!.textContent = 'Pago por '+target.textContent+': ';\r\n      idcuota = target.id;\r\n      totalpagado = target.dataset.totalpagado??'0';\r\n      idcredito = target.dataset.idcredito??'0';\r\n      idmediopago = target.dataset.idmediopago??'0';\r\n      mediopagado = target.dataset.mediopagado??'0';\r\n      contentMP = target;\r\n      totalPagado.textContent = '$ '+Number(mediopagado).toLocaleString();\r\n      numCuota.textContent = 'Credito N° : '+idcredito;\r\n      selectMediopago.value = idmediopago;\r\n      modalcambioMedioPago.showModal();\r\n    }\r\n\r\n\r\n    document.querySelector('#formCambioMedioPago')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      actualizarMediosPago();\r\n    });\r\n\r\n\r\n    async function actualizarMediosPago(){\r\n      const datos = new FormData();\r\n      datos.append('id', idcuota);\r\n      datos.append('idmediopago', idmediopago);\r\n      datos.append('id_credito', idcredito);\r\n      datos.append('idnuevomediopago', selectMediopago.value);\r\n      datos.append('valor', mediopagado);\r\n      try {\r\n          const url = \"/admin/api/cuota/cambioMedioPagoSeparado\";  //va al controlador creditoscontrolador\r\n          const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n          const resultado = await respuesta.json();\r\n          if(resultado.exito !== undefined){\r\n            msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            updateMP(resultado.mediosPagoUpdate);\r\n          }else{\r\n            msjalertToast('error', '¡Error!', resultado.error[0]);\r\n          }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n      modalcambioMedioPago.close();\r\n    }\r\n\r\n\r\n    function updateMP(mediosPagoUpdate:{id:string, idcuota:string, mediopago_id?:string, idmediopago?:string, valor:string}){\r\n      const {mediopago_id, idmediopago} = mediosPagoUpdate;\r\n      contentMP.textContent = selectMediopago.options[selectMediopago.selectedIndex].textContent;\r\n      contentMP.dataset.idmediopago = mediopago_id??idmediopago;\r\n    }\r\n\r\n\r\n\r\n    document.querySelector('#formAjustarCredito')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      const v:number = validarPassword('divmsjalertaClaveAjustarCredito', inputPasswordAjustarCredito.value);\r\n      if(!v)return;\r\n      ajustarCreditoAntiguo();\r\n    });\r\n\r\n    function validarPassword(divAlertString:string, claveUsuario:string):number{\r\n      const clave = password.find(c => c.clave=='clave_para_ajustar_credito');\r\n      if(clave?.valor_final!==null && claveUsuario !== clave?.valor_final){\r\n        msjAlert('error', 'El password es invalido', (document.querySelector('#'+divAlertString) as HTMLElement));\r\n        return 0;\r\n      }\r\n      return 1;\r\n    }\r\n\r\n\r\n    async function ajustarCreditoAntiguo(){\r\n      const id:string = (document.querySelector('#idcredito') as HTMLInputElement).value;\r\n      const abonototalantiguo = (document.querySelector('#abonoTotalAntiguo') as HTMLInputElement).value||'0';\r\n      const recargo = (document.querySelector('#recargo') as HTMLInputElement).value||'0';\r\n      const datos = new FormData();\r\n      datos.append('id', id);\r\n      datos.append('recargo', recargo);\r\n      datos.append('abonototalantiguo', abonototalantiguo);\r\n      datos.append('fechainicio', (document.querySelector('#ajustarFechaInicio') as HTMLInputElement).value);\r\n      try {\r\n          const url = \"/admin/api/ajustarCreditoAntiguo\";  //va al controlador creditoscontrolador\r\n          const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n          const resultado = await respuesta.json();\r\n          if(resultado.exito !== undefined){\r\n            msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            ajustarIndicadores(abonototalantiguo, recargo);\r\n          }else{\r\n            msjalertToast('error', '¡Error!', resultado.error[0]);\r\n          }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n      miDialogoAjustarCredito.close();\r\n    }\r\n\r\n\r\n    function ajustarIndicadores(abonototalantiguo:string, recargo:string){\n      const capital:number = Number((document.querySelector('#capital') as HTMLInputElement).value);\n      const abonoinicial:number = Number((document.querySelector('#abonoinicial') as HTMLInputElement).value);\n      const montototal:number = Number((document.querySelector('#montototal') as HTMLInputElement).value);\n      const saldoPendienteInput = document.querySelector('#saldopendiente') as HTMLInputElement;\n      const nuevoSaldoPendiente = capital+Number(recargo)-abonoinicial-Number(abonototalantiguo);\n      document.querySelector('#abonoInicialText')!.textContent = '$ '+abonototalantiguo;\n      document.querySelector('#interesText')!.textContent = '$ '+recargo;\n      document.querySelector('#creditoTotalText')!.textContent = '$ '+(capital - abonoinicial + Number(recargo)).toLocaleString();\n      document.querySelector('#saldopendientetext')!.textContent = formatoMoneda(nuevoSaldoPendiente);\n      saldoPendienteInput.value = String(nuevoSaldoPendiente);\n      saldopendiente = nuevoSaldoPendiente;\n    }\n\n    function parseMoneda(valor:string):number{\n      const normalizado = valor.replace(/\\$/g, '').replace(/\\s/g, '').replace(/\\./g, '').replace(',', '.');\n      const numero = Number(normalizado);\n      return Number.isFinite(numero) ? numero : 0;\n    }\n\n    function formatoMoneda(valor:number):string{\n      return '$ '+valor.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\n    }\n\n    function valorPagadoFila(fila:HTMLTableRowElement | null):number{\n      const valorDataset = fila?.querySelector('.mediosdepago')?.getAttribute('data-totalpagado');\n      if(valorDataset !== null && valorDataset !== undefined)return Number(valorDataset) || 0;\n      return parseMoneda(fila?.children[3]?.textContent || '0');\n    }\n\n    function actualizarSaldoPendientePorAnulacion(valorAnulado:number):void{\n      const saldoPendienteInput = document.querySelector('#saldopendiente') as HTMLInputElement | null;\n      const saldoPendienteText = document.querySelector('#saldopendientetext') as HTMLElement | null;\n      const pagoTotalInput = document.querySelector('#PagoTotal_abono') as HTMLInputElement | null;\n      const pagoTotalText = document.querySelector('#PagoTotal_abono_text') as HTMLElement | null;\n      const saldoActual = saldoPendienteInput ? Number(saldoPendienteInput.value || '0') : parseMoneda(saldoPendienteText?.textContent || '0');\n      const nuevoSaldo = saldoActual + valorAnulado;\n      saldopendiente = nuevoSaldo;\n      if(saldoPendienteInput)saldoPendienteInput.value = String(nuevoSaldo);\n      if(pagoTotalInput)pagoTotalInput.value = String(nuevoSaldo);\n      if(saldoPendienteText)saldoPendienteText.textContent = formatoMoneda(nuevoSaldo);\n      if(pagoTotalText)pagoTotalText.textContent = formatoMoneda(nuevoSaldo);\n    }\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      const f = event.target;\r\n      if (f=== miDialogoAjustarCredito || f === miDialogoAbono || f === miDialogoDetalleProducto || f === modalcambioMedioPago || (f as HTMLInputElement).value === 'salir' || (f as HTMLInputElement).value === 'Cancelar' \n          || (f as HTMLElement).id == 'btnXCerrarModalDetalleProducto' || (f as HTMLElement).id == 'btnXCerrarModalAbono' || f === miDialogoPagoTotal\n          || (f as HTMLElement).id == 'btnXCerrarModalPagoTotal' || (f as HTMLElement).id == 'btnXCerrarModalAjustarCredito' ) {\n        miDialogoAbono.close();\r\n        miDialogoPagoTotal.close();\r\n        miDialogoDetalleProducto.close();\r\n        modalcambioMedioPago.close();\r\n        miDialogoAjustarCredito.close();\r\n      }\r\n    }\r\n\r\n\r\n    function anularAbono(target: HTMLButtonElement){\n      const idabono = target.parentElement?.id;\n      const fila = target.closest('tr');\n      if(idabono==undefined)return;\n      const claveAnularAbono = password.find(c => c.clave === 'clave_para_anular_abono');\n      const claveConfigurada = claveAnularAbono?.valor_final?.trim();\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            input: 'j2-confirm__input',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          icon: 'warning',\n          title: 'Anular abono registrado',\n          html: '<strong>Esta accion reversara el abono seleccionado.</strong><br><span>El registro quedara anulado y se actualizara el historial del credito.</span>',\n          input: 'password',\n          inputPlaceholder: claveConfigurada ? 'Ingresa la clave de anulacion' : 'Clave de autorizacion (opcional)',\n          inputAttributes: {\n            autocapitalize: 'off',\n            autocorrect: 'off'\n          },\n          showCancelButton: true,\n          confirmButtonText: 'Anular abono',\n          cancelButtonText: 'Cancelar',\n          reverseButtons: true,\n          showLoaderOnConfirm: true,\n          inputValidator: (value:string) => {\n            if(!claveConfigurada) return;\n            if(!value) return 'La clave de anulacion es obligatoria.';\n            if(value !== claveConfigurada) return 'La clave de anulacion no corresponde.';\n          },\n          preConfirm: async()=>{\n            try {\n                const url = \"/admin/api/creditos/anularAbono?id=\"+idabono;\n                const respuesta = await fetch(url); \n                const resultado = await respuesta.json();\r\n\r\n                if (!respuesta.ok || resultado.error) {\r\n                    const mensajeError = resultado.error ? resultado.error[0] : 'No se pudo procesar la solicitud.';\r\n                    throw new Error(mensajeError);\r\n                }\r\n                return resultado;\r\n            } catch (error:any) {\r\n                  console.log(error);\r\n                  Swal.showValidationMessage(error.message);\r\n            }\r\n\n          },\n          allowOutsideClick: () => !Swal.isLoading()\n      }).then((result:any) => {\n          if (result.isConfirmed && result.value) {\n              const valorAnulado = valorPagadoFila(fila as HTMLTableRowElement | null);\n              fila?.remove();\n              actualizarSaldoPendientePorAnulacion(valorAnulado);\n              Swal.fire({\n                customClass: {\n                  popup: 'j2-confirm j2-confirm--success',\n                  icon: 'j2-confirm__icon',\n                  title: 'j2-confirm__title',\n                  htmlContainer: 'j2-confirm__text',\n                  actions: 'j2-confirm__actions j2-confirm__actions--single',\n                  confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                },\n                icon: 'success',\n                title: 'Abono anulado',\n                html: '<strong>'+(result.value.exito?.[0] ?? 'El abono fue anulado correctamente.')+'</strong><br><span>El historial del credito quedo actualizado.</span>',\n                confirmButtonText: 'Entendido'\n              });\n          }\n      });\n    }\n\r\n\r\n    async function printPOSComprobanteAbono(idabono:string|undefined){\r\n      if(idabono==undefined)return;\r\n      try{\r\n        const url = \"/admin/api/creditos/getAbono?id=\"+idabono; //llamado a la API REST - creditocontrolador \r\n        const respuesta = await fetch(url); \r\n        const resultado = await respuesta.json();\r\n        const isAndroid = /Android/i.test(navigator.userAgent);\r\n        if(printerBT === '1'){\r\n          const builder = new ticketAbonoBuilder(resultado);\r\n          const ticket = await builder.generate(true); //true para version buffer bytes\r\n          const base64 = bytesToBase64(ticket);\r\n          if(isAndroid)window.location.href = `rawbt:base64,${base64}`;\r\n          //descargar .bin a equipo\r\n          /*const blob = new Blob([ticket], { type: 'application/octet-stream' });\r\n          const url = URL.createObjectURL(blob);\r\n          const a = document.createElement('a');\r\n          a.href = url;\r\n          a.download = 'ticket.bin';\r\n          a.click();\r\n          URL.revokeObjectURL(url);*/\r\n        }\r\n      }catch(error){\r\n        console.log(error);\r\n      }\r\n\r\n      if(!isNaN(Number(idabono)))\r\n        window.open(\"/admin/printPDFAbonoCredito?id=\" + idabono, \"_blank\"); //controlador printcontrolador\r\n    }\r\n  }\r\n\r\n})();\n","(()=>{\r\n  if(document.querySelector('.creditos')){\r\n\r\n    type creditsapi = {\r\n      id:string,\r\n      id_fksucursal: string,\r\n      factura_id: string,\r\n      cliente_id: string,\r\n      nombrecliente: string,\r\n      capital: string,\r\n      abonoinicial: string,\r\n      saldopendiente: string,\r\n      numcuota: string,\r\n      cantidadcuotas: string,\r\n      montocuota: string,\r\n      frecuenciapago: string,\r\n      fechainicio: string,\r\n      interes: string,\r\n      interesxcuota: string,\r\n      interestotal: string,\r\n      valorinteresxcuota: string,\r\n      valorinterestotal: string,\r\n      montototal: string,\r\n      fechavencimiento: string,\r\n      productoentregado: string,\r\n      estado: string,\r\n      created_at: string,\r\n    };\r\n    \r\n    /*interface Item {\r\n      id_impuesto: number,\r\n      facturaid: number,\r\n      basegravable: number,\r\n      valorimpuesto: number\r\n    }\r\n    let factimpuestos:Item[] = [];*/\r\n\r\n    let printerBT:string = getParam.impresora_principal_de_CAJA_para_Android_por_BT.valor_final;\r\n    let credits:creditsapi[]=[], uncredito:creditsapi;\r\n    let indiceFila=0, control=0;\r\n\r\n\r\n    /*(async ()=>{\r\n      try {\r\n          const url = \"/admin/api/allcredits\"; //llamado a la API REST y se trae todos los productos\r\n          const respuesta = await fetch(url); \r\n          credits = await respuesta.json(); \r\n          console.log(credits);\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();*/\r\n\r\n\r\n\r\n    \r\n    //////////////////  TABLA //////////////////////\r\n    let tablaCreditos = ($('#tablaCreditos') as any).DataTable({\n      ...configdatatablesgenerico,\n      dom: 'Brtip',\n      buttons: [\n        {extend: 'copyHtml5', className: 'creditos-export-button creditos-export-button--copy', text: '<span class=\"creditos-export-button__icon\"><i class=\"fa-regular fa-copy\"></i></span><span>Copiar</span>', title: 'creditos-y-separados'},\n        {extend: 'excelHtml5', className: 'creditos-export-button creditos-export-button--excel', text: '<span class=\"creditos-export-button__icon\"><i class=\"fa-regular fa-file-excel\"></i></span><span>Excel</span>', title: 'creditos-y-separados'},\n        {extend: 'csvHtml5', className: 'creditos-export-button creditos-export-button--csv', text: '<span class=\"creditos-export-button__icon\"><i class=\"fa-solid fa-file-csv\"></i></span><span>CSV</span>', title: 'creditos-y-separados'},\n        {extend: 'pdfHtml5', className: 'creditos-export-button creditos-export-button--pdf', text: '<span class=\"creditos-export-button__icon\"><i class=\"fa-regular fa-file-pdf\"></i></span><span>PDF</span>', title: 'creditos-y-separados'},\n        {extend: 'print', className: 'creditos-export-button creditos-export-button--print', text: '<span class=\"creditos-export-button__icon\"><i class=\"fa-solid fa-print\"></i></span><span>Imprimir</span>', title: 'creditos-y-separados'},\n        {extend: 'colvis', className: 'creditos-export-button creditos-export-button--columns', text: '<span class=\"creditos-export-button__icon\"><i class=\"fa-solid fa-table-columns\"></i></span><span>Columnas</span>'}\n      ],\n      order: [[ 0, 'desc' ]]\n    });\n    modernizarToolbarDataTable('#tablaCreditos');\n    modernizarBotonesExportacionCreditos(tablaCreditos);\n    ocultarToolbarNativoCreditos();\n    ($('#tablaCreditos') as any).on('draw.dt', ocultarToolbarNativoCreditos);\n\r\n\r\n    //evento a la tabla\r\n    document.querySelector('#tablaCreditos tbody')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if(target?.classList.contains(\"anularCredito\")||(e.target as HTMLElement).parentElement?.classList.contains(\"anularCredito\"))anularCredito(e);\r\n      if(target?.classList.contains(\"printPOSSeparado\"))printPOSSeparado(target.id);\r\n    });\r\n\r\n\r\n    function anularCredito(e:Event){\r\n      let idcredito = (e.target as HTMLElement).parentElement?.id!, info = (tablaCreditos as any).page.info();\r\n      if((e.target as HTMLElement)?.tagName === 'I')idcredito = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n      indiceFila = (tablaCreditos as any).row((e.target as HTMLElement).closest('tr')).index();\r\n      \r\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          buttonsStyling: false,\n          icon: 'question',\n          title: 'Desea anular el credito?',\n          text: \"El credito sera anulado definitivamente.\",\n          showCancelButton: true,\n          confirmButtonText: 'Si, anular',\n          cancelButtonText: 'Cancelar',\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idcredito);\r\n                  try {\r\n                      const url = \"/admin/api/anularSeparado\";\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();\n                      if(resultado.exito !== undefined){\n                        const datosActuales = (tablaCreditos as any).row(indiceFila).data();\n                        datosActuales[9] = '<span class=\"creditos-status creditos-status--danger\">Anulado</span>';\n                        datosActuales[10] = `<div class=\"acciones-btns\" id=\"${idcredito}\"><a class=\"creditos-action creditos-action--detail\" href=\"/admin/creditos/detallecredito?id=${idcredito}\" title=\"Ver detalle del credito\"><i class=\"fa-solid fa-chart-simple\"></i></a></div>`;\n                        (tablaCreditos as any).row(indiceFila).data(datosActuales).draw();\n                        (tablaCreditos as any).page(info.page).draw('page'); \n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          buttonsStyling: false,\n                          icon: 'success',\n                          title: 'Credito anulado',\n                          text: resultado.exito[0],\n                          confirmButtonText: 'OK'\n                        });\n                      }else{\n                          Swal.fire({\n                            customClass: {\n                              popup: 'j2-confirm j2-confirm--danger',\n                              icon: 'j2-confirm__icon',\n                              title: 'j2-confirm__title',\n                              htmlContainer: 'j2-confirm__text',\n                              actions: 'j2-confirm__actions j2-confirm__actions--single',\n                              confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                            },\n                            buttonsStyling: false,\n                            icon: 'error',\n                            title: 'No se pudo anular',\n                            text: resultado.error[0],\n                            confirmButtonText: 'OK'\n                          });\n                      }\n                  } catch (error) {\n                      console.log(error);\n                      Swal.fire({\n                        customClass: {\n                          popup: 'j2-confirm j2-confirm--danger',\n                          icon: 'j2-confirm__icon',\n                          title: 'j2-confirm__title',\n                          htmlContainer: 'j2-confirm__text',\n                          actions: 'j2-confirm__actions j2-confirm__actions--single',\n                          confirmButton: 'j2-confirm__button j2-confirm__button--danger'\n                        },\n                        buttonsStyling: false,\n                        icon: 'error',\n                        title: 'No se pudo anular',\n                        text: 'Intenta nuevamente o revisa la conexion.',\n                        confirmButtonText: 'OK'\n                      });\n                  }\n              })();//cierre de async()\n          }\n      });\n    }\n\n    function ocultarToolbarNativoCreditos():void{\n      const wrapper = document.querySelector('#tablaCreditos_wrapper');\n      wrapper?.querySelectorAll('.dataTables_length, .dataTables_filter').forEach((control)=>{\n        (control as HTMLElement).remove();\n      });\n    }\n\n    function modernizarBotonesExportacionCreditos(dataTable:any):void{\n      const wrapper = document.querySelector('#tablaCreditos_wrapper') as HTMLElement|null;\n      const botonesNativos = wrapper?.querySelector('.dt-buttons') as HTMLElement|null;\n      if(!wrapper || !botonesNativos || wrapper.querySelector('.creditos-export-toolbar'))return;\n\n      botonesNativos.classList.add('creditos-native-export-buttons');\n      botonesNativos.style.display = 'none';\n      botonesNativos.setAttribute('aria-hidden', 'true');\n\n      const acciones = [\n        {indice: 0, clase: 'copy', icono: 'fa-regular fa-copy', texto: 'Copiar'},\n        {indice: 1, clase: 'excel', icono: 'fa-regular fa-file-excel', texto: 'Excel'},\n        {indice: 2, clase: 'csv', icono: 'fa-solid fa-file-csv', texto: 'CSV'},\n        {indice: 3, clase: 'pdf', icono: 'fa-regular fa-file-pdf', texto: 'PDF'},\n        {indice: 4, clase: 'print', icono: 'fa-solid fa-print', texto: 'Imprimir'},\n        {indice: 5, clase: 'columns', icono: 'fa-solid fa-table-columns', texto: 'Columnas'}\n      ];\n\n      const toolbar = document.createElement('div');\n      toolbar.className = 'creditos-export-toolbar';\n      toolbar.innerHTML = `\n        <div class=\"creditos-export-menu\">\n          <button type=\"button\" class=\"creditos-export-trigger\" aria-expanded=\"false\">\n            <span><i class=\"fa-solid fa-download\"></i></span>\n            Exportar\n            <i class=\"fa-solid fa-chevron-down\"></i>\n          </button>\n          <div class=\"creditos-export-menu__list\">\n          ${acciones.map((accion)=>`\n            <button type=\"button\" class=\"creditos-export-chip creditos-export-chip--${accion.clase}\" data-export-index=\"${accion.indice}\">\n              <span class=\"creditos-export-chip__icon\"><i class=\"${accion.icono}\"></i></span>\n              <span>${accion.texto}</span>\n            </button>\n          `).join('')}\n          </div>\n        </div>\n      `;\n\n      botonesNativos.insertAdjacentElement('beforebegin', toolbar);\n      const trigger = toolbar.querySelector('.creditos-export-trigger') as HTMLButtonElement|null;\n      const menu = toolbar.querySelector('.creditos-export-menu') as HTMLElement|null;\n\n      trigger?.addEventListener('click', (event)=>{\n        event.stopPropagation();\n        const abierto = menu?.classList.toggle('is-open') ?? false;\n        trigger.setAttribute('aria-expanded', abierto ? 'true' : 'false');\n      });\n\n      document.addEventListener('click', ()=>{\n        menu?.classList.remove('is-open');\n        trigger?.setAttribute('aria-expanded', 'false');\n      });\n\n      toolbar.querySelectorAll('[data-export-index]').forEach((boton)=>{\n        boton.addEventListener('click', (event)=>{\n          event.stopPropagation();\n          dataTable.button(Number((boton as HTMLElement).dataset.exportIndex)).trigger();\n          menu?.classList.remove('is-open');\n          trigger?.setAttribute('aria-expanded', 'false');\n        });\n      });\n    }\n\r\n\r\n    async function printPOSSeparado(idcredito:string){\r\n      //printTicketPOS(resultado.idfactura, resultado.dataInvoice);\r\n\r\n      try{\r\n        const url = \"/admin/api/getCreditoSeparado?id=\"+idcredito; //llamado a la API REST - creditocontrolador \r\n        const respuesta = await fetch(url); \r\n        const resultado = await respuesta.json();\r\n        const isAndroid = /Android/i.test(navigator.userAgent);\r\n        if(printerBT === '1'){\r\n          const builder = new ticketCreditoSeparadoBuilder(resultado);\r\n          const ticket = await builder.generate(true); //true para version buffer bytes\r\n          const base64 = bytesToBase64(ticket);\r\n          if(isAndroid)window.location.href = `rawbt:base64,${base64}`;\r\n          //descargar .bin a equipo\r\n          /*const blob = new Blob([ticket], { type: 'application/octet-stream' });\r\n          const url = URL.createObjectURL(blob);\r\n          const a = document.createElement('a');\r\n          a.href = url;\r\n          a.download = 'ticket.bin';\r\n          a.click();\r\n          URL.revokeObjectURL(url);*/\r\n        }\r\n        //window.open(\"/admin/printPDFPOS?id=\" + idfactura, \"_blank\");  //controlador printcontrolador\r\n      }catch(error){\r\n        console.log(error);\r\n      }\r\n\r\n      if(!isNaN(Number(idcredito)))\r\n        window.open(\"/admin/printPDFPOSSeparado?id=\" + idcredito, \"_blank\"); //controlador printcontrolador\r\n    }\r\n\r\n    \r\n    async function printTicketPOS(idfactura:string, datainvoice:DataInvoice){\r\n      \r\n      /*try {\r\n        const url = \"http://localhost:3100/api/printPOS/ticket1/CAJA\"; //llamado a la API REST apidiancontrolador.php\r\n        const respuesta = await fetch(url, {\r\n          method: 'POST',\r\n          headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n          body: JSON.stringify(datainvoice)\r\n        });\r\n        const resultado = await respuesta.json();\r\n        console.log(resultado);\r\n      } catch (error) {\r\n        console.log(error);\r\n      }*/\r\n    }\r\n\r\n  }\r\n\r\n})();\n","(()=>{\r\n  if(document.querySelector('.crearseparado')){\r\n\r\n    const POS = (window as any).POS;\r\n     \r\n    const btnCrearSeparado = document.querySelector('#btnCrearSeparado');\r\n    const miDialogoFacturar = document.querySelector('#miDialogoFacturar') as any;\r\n    const tablaSeparado = document.querySelector('#tablaSeparado tbody') as HTMLBodyElement;\r\n    const btnPagar = document.getElementById('btnPagar') as HTMLInputElement;\r\n    const btnCaja = document.querySelector('#caja') as HTMLSelectElement; //select de la caja en el modal pagar\r\n\r\n\r\n    type conversionunidadesapi = {\r\n      id:string,\r\n      idproducto: string,\r\n      idsubproducto: string,\r\n      idunidadmedidabase: string,\r\n      idunidadmedidadestino: string,\r\n      nombreunidadbase: string,\r\n      nombreunidaddestino: string,\r\n      factorconversion: string,\r\n    };\r\n\r\n    interface Item {\r\n      id_impuesto: number,\r\n      facturaid: number,\r\n      basegravable: number,\r\n      valorimpuesto: number\r\n    }\r\n\r\n    let allConversionUnidades:conversionunidadesapi[] = [];\r\n    let carrito:CarritoItem[]=[];\r\n    let allproducts:productsapi[] = [];\r\n    let filteredData: {id:string, text:string, tipo:string, tipoproducto:string, tipoproduccion:string, sku:string, unidadmedida:string, precio:string}[];   //tipo = 0 es producto simple,  1 = subproducto\r\n    const valorTotal = {subtotal: 0, base: 0, valorimpuestototal: 0, dctox100: 0, descuento: 0, idtarifa: 0, valortarifa: 0, total: 0}; //datos global de la venta\r\n    let factimpuestos:Item[] = [], tipoventa:string=\"Contado\";\r\n    const mapMediospago = new Map();\r\n    \r\n    const constImp: {[key:string]: number} = {};\r\n    constImp['excluido'] = 0;\r\n    constImp['0'] = 0;  //exento de iva, tarifa 0%\r\n    constImp['5'] = 0.0476190476190476; //iva, tarifa al 5%,  Bienes/servicios al 5\r\n    constImp['8'] = 0.0740740740740741; //inc, tarifa al 8%,  impuesto nacional al consumo\r\n    constImp['16'] = 0.1379310344827586; //iva, tarifa al 16%,  contratos firmados con el estado antes de ley 1819\r\n    constImp['19'] = 0.1596638655462185; //iva, tarifa al 19%,  tarifa general\r\n\r\n    const select2Separado = {\n      allowClear: true,\n      width: '100%',\n      dropdownCssClass: 'separado-select2-dropdown'\n    };\n\n    ($('#cliente') as any).select2({ ...select2Separado, placeholder: \"Seleccionar cliente\"});\n    ($('#frecuenciapago') as any).select2({ ...select2Separado, placeholder: \"Dia de pago\"});\n    habilitarAperturaSelect2Completa('#cliente');\n    habilitarAperturaSelect2Completa('#frecuenciapago');\n    limpiarCeroAlEnfocar('#abonoinicial');\n\n     document.addEventListener(\"click\", cerrarDialogoExterno);\n\r\n    (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allproducts\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas los productos simples y subproductos\r\n            const respuesta = await fetch(url); \r\n            const resultado:productsapi[] = await respuesta.json();\r\n            filteredData = resultado.filter(x=>x.habilitarventa=='1'&&x.visible=='1').map(item => ({ id: item.id, text: item.nombre, tipo:item.tipoproducto??'1', tipoproducto: item.tipoproducto, tipoproduccion: item.tipoproduccion, sku: item.sku, unidadmedida: item.unidadmedida, precio:item.precio_venta }));\r\n            activarselect2();\r\n            allproducts = resultado.filter(x=>x.habilitarventa=='1'&&x.visible=='1');\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    })();\r\n\r\n    (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/allConversionesUnidades\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas las conversiones de unidades\r\n            const respuesta = await fetch(url); \r\n            allConversionUnidades = await respuesta.json();\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    })();\r\n\r\n    //DESACTIVADO EL CANAL DE VENTA\r\n    document.querySelector('#contenedorCanalVenta')?.classList.add('hidden');\r\n    document.querySelector('#canalVenta')?.removeAttribute('required');\r\n\r\n    function activarselect2(){\n      ($('#articulo') as any).select2({ \n          ...select2Separado,\n          data: [{ id: '', text: '' }, ...filteredData],\n          placeholder: \"Buscar articulo\",\n          /*\r\n          templateResult: function (data:{id:string, text:string, tipo:string}) {\r\n              // Personalizar cÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³mo se muestra cada opciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n en el dropdown\r\n              if (!data.id) { return data.text; }  // Si no hay id, solo mostrar el texto\r\n              const html = `\r\n                  <div class=\"custom-option\">\r\n                      <span class=\"item-name\">${data.text}</span> \r\n                      <span class=\"item-type\">${data.tipo}</span>  <!-- Mostrar tipo adicional -->\r\n                  </div>`;\r\n              return $(html);  // Devolver el HTML personalizado\r\n          }*/\r\n      });\n      $(\"#articulo\").val('').trigger('change.select2');\n      habilitarAperturaSelect2Completa('#articulo');\n    }\n\r\n    ////// EVENTO AL SELECT ARTICULOS O ITEMS PARA SELECCIONAR EL ITEM Y AÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¹Ã…â€œADIR AL CARRITO ////// \r\n    function habilitarAperturaSelect2Completa(selector:string){\n      const select = document.querySelector(selector) as HTMLSelectElement;\n      const contenedor = select?.closest('.separado-input') as HTMLElement;\n      if(!select || !contenedor || contenedor.dataset.openSelect2 === 'true')return;\n\n      contenedor.dataset.openSelect2 = 'true';\n      contenedor.addEventListener('click', (e:Event)=>{\n        const target = e.target as HTMLElement;\n        if(target.closest('.select2-selection__clear'))return;\n        if(target.closest('.select2-dropdown'))return;\n        ($(select) as any).select2('open');\n      });\n    }\n\n    function limpiarCeroAlEnfocar(selector:string){\n      const input = document.querySelector(selector) as HTMLInputElement;\n      if(!input)return;\n\n      input.addEventListener('focus', ()=>{\n        if(input.value.trim() === '0')input.value = '';\n      });\n\n      input.addEventListener('blur', ()=>{\n        if(input.value.trim() === '')input.value = '0';\n      });\n    }\n\n    $(\"#articulo\").on('change', (e)=>{\n        let datos = ($('#articulo') as any).select2('data')[0];\r\n        if(datos?.id){\n          const itemselected = allproducts.find(x=>x.id == datos.id)!\r\n          const productoConfigurado = structuredClone(itemselected);\r\n          filtrarInsumos(productoConfigurado);\r\n          actualizarCarrito(datos.id, datos.precio, productoConfigurado);\r\n          $(\"#articulo\").val('').trigger('change');\n        }\r\n    });\r\n\r\n    function actualizarCarrito(id:string, precio:number = 1, productoConfigurado:productsapi|null){\r\n      const index = carrito.findIndex(x=>x.idproducto==id && x.valorunidad == precio && mismaConfiguracion(x, productoConfigurado!));\r\n      if(index == -1){  //si el item seleccionado no existe en el carrito, agregarlo.\r\n          const productototal = Number(productoConfigurado?.precio_venta);\r\n          const productovalorimp = productototal*constImp[productoConfigurado?.impuesto??'0']; //si producto.impuesto es null toma el valor de cero\r\n          \r\n          const item:CarritoItem = {\r\n              id: '',\r\n              idproducto: productoConfigurado?.id!,\r\n              tipoproducto: productoConfigurado?.tipoproducto!,  ////tipo = 0 es producto simple,  1 = subproducto\r\n              tipoproduccion: productoConfigurado?.tipoproduccion!,\r\n              foto: '',\r\n              costo: productoConfigurado?.precio_compra!,\r\n              valorunidad: Number(productoConfigurado?.precio_venta),\r\n              nombreproducto: productoConfigurado?.nombre!,\r\n              rendimientoestandar: productoConfigurado?.rendimientoestandar!,\r\n              cantidad: 1,\r\n              stock: 1,\r\n              promediostock: Number(productoConfigurado?.promediostock),\r\n              prioridadcomision: productoConfigurado?.prioridadcomision!,\r\n              percentcomision: productoConfigurado?.percentcomision!,\r\n              valorcomision: 0,\r\n              impuesto: productoConfigurado?.impuesto!,\r\n              subtotal: productototal,\r\n              base: productototal-productovalorimp,\r\n              valorimp: productovalorimp,\r\n              descuento: 0,\r\n              total: productototal,\r\n              insumos: productoConfigurado?.insumos??[]\r\n          }\r\n          carrito = [...carrito, item];\r\n          POS.carrito = carrito;\r\n      }else{  //si ya existe en el carrito, sumar\n        sumarcantidad(carrito[index], carrito[index].cantidad+1, index);\n      }\n      printItemTable();\n      valorCarritoTotal();\n    }\n\r\n\r\n    function mismaConfiguracion(productCarrito: any, producto2: productsapi):boolean {\r\n        const mapaProduct2 = new Map(producto2.insumos.map((ins:any) => [ins.id_subproducto, ins]));\r\n        // Deben ser el mismo producto\r\n        if(productCarrito.idproducto !== producto2.id)return false;\r\n\r\n        // Deben tener la misma cantidad de insumos\r\n        if(productCarrito.insumos.length !== producto2.insumos.length)return false;\r\n\r\n        for (const insumo1 of productCarrito.insumos) {\r\n            //const insumo2 = producto2.insumos.find((x:any) => x.id_subproducto == insumo1.id_subproducto);\r\n            const insumo2:any = mapaProduct2.get(insumo1.id_subproducto);\r\n            if (!insumo2)return false;\r\n            // Comparar selecciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n\r\n            if (Number(insumo1.seleccionado) !== Number(insumo2.seleccionado))\r\n                return false;\r\n            // Comparar cantidad\r\n            if (Number(insumo1.cantidadsubproducto) !== Number(insumo2.cantidadsubproducto))\r\n                return false;\r\n        }\r\n        return true;\r\n    }\r\n\r\n\r\n    function sumarcantidad(productoCarrito:CarritoItem, cantidad:number, index:number){\r\n        if(cantidad < 0)cantidad = 0;\r\n        productoCarrito.cantidad = cantidad;\r\n        productoCarrito.stock = cantidad;\r\n        productoCarrito.subtotal = (productoCarrito.valorunidad)*productoCarrito.cantidad;\r\n        productoCarrito.total = productoCarrito.subtotal;\r\n        productoCarrito.valorcomision = (productoCarrito.subtotal*productoCarrito.percentcomision)/100;\r\n        //calculo del impuesto y base por producto en el carrito deventas\r\n        productoCarrito.valorimp = parseFloat((productoCarrito.total*constImp[productoCarrito.impuesto??0]).toFixed(3));\r\n        productoCarrito.base = parseFloat((productoCarrito.total-productoCarrito.valorimp).toFixed(3));\r\n        (tablaSeparado?.querySelector(`TR[data-indexcarrito=\"${index}\"] .inputcantidad`) as HTMLInputElement).value = carrito[index].stock+'';\r\n        (tablaSeparado?.querySelector(`TR[data-indexcarrito=\"${index}\"]`)?.children?.[3] as HTMLElement).textContent = \"$\"+productoCarrito.total.toLocaleString();\r\n        valorCarritoTotal();\r\n    }\r\n\r\n\r\n    function printItemTable(){\r\n        while(tablaSeparado.firstChild)tablaSeparado.removeChild(tablaSeparado.firstChild);\r\n        let options:string = '';\r\n        ///const productounidades = allConversionUnidades.filter(x => x.idproducto === id); \r\n        //productounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idproducto}\" >${u.nombreunidaddestino}</option>`);\r\n        carrito.forEach((item, i)=>{\r\n          const tr = document.createElement('TR') as HTMLTableRowElement;\r\n          tr.classList.add('productselect');\r\n          tr.dataset.indexcarrito = i+'';\r\n          tr.insertAdjacentHTML('afterbegin', `\n            <td><span class=\"separado-product-name\">${item.nombreproducto}</span></td>\n            <td><select class=\"separado-unit-select selectunidad\">${options}</select></td>\n            <td>\n              <div class=\"separado-qty-control\">\n                <button type=\"button\" class=\"separado-qty-btn\" aria-label=\"Restar unidad\"><span class=\"menos material-symbols-outlined\">remove</span></button>\n                <input type=\"text\" class=\"inputcantidad\" name=\"inputcantidad\" value=\"${item.stock}\">\n                <button type=\"button\" class=\"separado-qty-btn\" aria-label=\"Sumar unidad\"><span class=\"mas material-symbols-outlined\">add</span></button>\n              </div>\n            </td>\n            <td><strong class=\"separado-row-total\">$${item.total.toLocaleString()}</strong></td>\n            <td class=\"accionestd\"><div class=\"acciones-btns\"><button class=\"separado-row-action separado-row-action--danger eliminarProducto\" type=\"button\" aria-label=\"Eliminar producto\"><i class=\"fa-solid fa-trash-can\"></i></button></div></td>`);\n          tablaSeparado?.appendChild(tr);\r\n        });\r\n    }\r\n\r\n    function valorCarritoTotal(){\r\n       //calcular el impuesto discriminado por tarifa\r\n      const idimpuesto: Record<string, number> = {'0': 1, '5': 2, '16': 3, '19': 4, 'excluido': 5, '8': 6 };\r\n      const objbase:{'0':number, '5':number, '16':number, '19':number, 'excluido':number, '8':number} = {'0': 0, '5': 0, '16': 0, '19': 0, 'excluido':0, '8': 0};\r\n\r\n      const mapImpuesto = new Map();\r\n      carrito.forEach(x=>{\r\n        if(x.impuesto){\r\n          if(mapImpuesto.has(x.impuesto)){\r\n            const valor = mapImpuesto.get(x.impuesto) + x.total*constImp[x.impuesto];\r\n            mapImpuesto.set(x.impuesto, valor);\r\n          }else{\r\n            mapImpuesto.set(x.impuesto, x.total*constImp[x.impuesto]);\r\n          }\r\n        }\r\n        if(x.impuesto == null)x.impuesto = \"excluido\";\r\n          objbase[x.impuesto as keyof typeof objbase] += x.base;\r\n          const impValor = mapImpuesto.get(x.impuesto)??0;\r\n          const index = factimpuestos.findIndex(Obj=>Obj.id_impuesto == idimpuesto[x.impuesto]);\r\n          if(index!=-1){ //si existe remplazar obj\r\n            factimpuestos[index] = {id_impuesto:idimpuesto[x.impuesto], facturaid:0, basegravable:objbase[x.impuesto as keyof typeof objbase], valorimpuesto: impValor};\r\n          }else{\r\n            factimpuestos = [...factimpuestos, {id_impuesto:idimpuesto[x.impuesto], facturaid:0, basegravable:objbase[x.impuesto as keyof typeof objbase], valorimpuesto: impValor}];\r\n          }\r\n      });\r\n\r\n      //Valor del impuesto total de todos los productos, es decir de la factura;\r\n      let valorTotalImp:number = 0;\r\n      for(let valorImp of mapImpuesto.values())valorTotalImp += valorImp;\r\n      \r\n      valorTotal.valorimpuestototal = parseFloat(valorTotalImp.toFixed(3));  //valor del impuesto total factura de todos los productos\r\n      valorTotal.subtotal = carrito.reduce((total, x)=>x.total+total, 0);\r\n      valorTotal.base = valorTotal.subtotal - valorTotal.valorimpuestototal;  //valor de la base total factura de todos los productos\r\n      valorTotal.total = valorTotal.subtotal + valorTotal.valortarifa - valorTotal.descuento;\r\n      //console.log(valorTotal);\r\n      //console.log(factimpuestos);\r\n      document.querySelector('#subTotal')!.textContent = '$'+valorTotal.subtotal.toLocaleString();\r\n      (document.querySelector('#impuesto') as HTMLElement).textContent = '$'+valorTotalImp.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n      document.querySelector('#total')!.textContent = '$ '+valorTotal.total.toLocaleString();\r\n      (document.querySelector('#montocuota') as HTMLInputElement).value = valorTotal.total+'';\r\n      //valorTotal.total = Number((document.querySelector('#abonoinicial') as HTMLInputElement).value);\r\n      //POS.gestionSubirModalPagar.valoresCredito\r\n      POS.valorTotal = valorTotal;\r\n      POS.mapMediospago = mapMediospago;\r\n      //**** recalcular valores del credito\r\n      POS.gestionSubirModalPagar.calculoTasaInteres();\r\n    }\r\n\r\n\r\n    //////////////////  TABLA //////////////////////\r\n    tablaSeparado?.addEventListener('click', (e:Event)=>{\r\n      const elementProduct = (e.target as HTMLElement)?.closest('.productselect');\r\n      const idProduct = (elementProduct as HTMLElement).dataset.id!;\r\n      const precio = (elementProduct as HTMLElement).dataset.precio!;\r\n      const indexcarrito = Number((elementProduct as HTMLElement).dataset.indexcarrito!);\r\n      let productoCarrito = carrito[indexcarrito];\r\n      \r\n      if((e.target as HTMLElement).classList.contains('menos'))\r\n        sumarcantidad(productoCarrito, productoCarrito.cantidad-1, indexcarrito);\r\n      \r\n      if((e.target as HTMLElement).classList.contains('inputcantidad')){\r\n        if((e.target as HTMLElement).dataset.event != \"eventInput\"){\r\n          e.target?.addEventListener('input', (e)=>{\r\n            let val = (e.target as HTMLInputElement).value;\r\n            val = val.replace(/[^0-9.]/g, '');\r\n            const partes = val.split('.');\r\n            if(partes.length > 2)val = partes[0]+'.'+partes.slice(1).join('');\r\n            if (val.startsWith('.'))val = '1';\r\n            if (val === '' || isNaN(parseFloat(val))) val = '0';\r\n\r\n            (e.target as HTMLInputElement).value = val;\r\n            sumarcantidad(productoCarrito, Number(val), indexcarrito);\r\n          });\r\n          (e.target as HTMLElement).dataset.event = \"eventInput\"; //se marca al input que ya tiene evento aÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±adido\r\n        }\r\n      }\r\n\r\n      if((e.target as HTMLElement).classList.contains('mas'))\r\n        sumarcantidad(productoCarrito, productoCarrito.cantidad+1, indexcarrito);\r\n      \r\n      if((e.target as HTMLElement).classList.contains('eliminarProducto') || (e.target as HTMLElement).tagName == \"I\"){\r\n        carrito.splice(indexcarrito, 1);\r\n        printItemTable();\r\n        valorCarritoTotal();\r\n      }\r\n    });\r\n\r\n\r\n    //btn para abrir modal de pago\n    btnCrearSeparado?.addEventListener('click', (e)=>{\n      e.preventDefault();\n      if((document.querySelector('#cliente') as HTMLSelectElement).value === ''){\n        msjAlert('error', 'Debe seleccionar el cliente.', (document.querySelector('#divmsjalerta') as HTMLElement));\n        resaltarCampoRequerido('#cliente');\n        return;\n      }\n      if((document.querySelector('#cantidadcuotas') as HTMLSelectElement).value === ''){\r\n        msjAlert('error', 'Debe indicar la cantidad de cuotas.', (document.querySelector('#divmsjalerta') as HTMLElement));\r\n        return;\r\n      }\r\n      if(carrito.length){\r\n        document.querySelector('.Efectivo')?.removeAttribute('readonly');\r\n        //document.querySelector('#inputscreditos')?.remove();  //elimina los inputs de credito en el modal de procesar pago.\r\n        document.querySelector('#campoabonoinicial')?.remove();\r\n        document.querySelector('#campocantidadcuotas')?.remove();\r\n        document.querySelector('#campomontocuota')?.remove();\r\n        document.querySelector('#abonoTotal')?.classList.remove('hidden');\r\n        document.querySelector('#textPrint')!.textContent = '\\u00bfDesea imprimir comprobante?';\r\n        tipoventa = \"Credito\";\r\n        //mapMediospago.clear();\r\n        POS.tipoventa = tipoventa;\r\n        //POS.valorTotal = valorTotal;\r\n        //POS.mapMediospago = mapMediospago;\r\n        POS.gestionSubirModalPagar.subirModalPagar();\r\n        miDialogoFacturar.showModal();\r\n      }\n    });\n\n    function resaltarCampoRequerido(selector:string){\n      const campo = document.querySelector(selector) as HTMLElement;\n      const contenedor = campo?.closest('.separado-input') as HTMLElement;\n      if(!contenedor)return;\n\n      contenedor.classList.remove('separado-input--attention');\n      void contenedor.offsetWidth;\n      contenedor.classList.add('separado-input--attention');\n      contenedor.scrollIntoView({ behavior: 'smooth', block: 'center' });\n\n      setTimeout(()=>{\n        contenedor.classList.remove('separado-input--attention');\n      }, 2200);\n    }\n\n    function mostrarMensajeMetodosPago(){\n      const mensaje = document.querySelector('#paymentMethodsRequiredMessage') as HTMLElement;\n      if(!mensaje)return;\n\n      mensaje.classList.remove('hidden', 'payment-methods-required-message--visible');\n      void mensaje.offsetWidth;\n      mensaje.classList.add('payment-methods-required-message--visible');\n    }\n\n    function ocultarMensajeMetodosPago(){\n      const mensaje = document.querySelector('#paymentMethodsRequiredMessage') as HTMLElement;\n      if(!mensaje)return;\n\n      mensaje.classList.add('hidden');\n      mensaje.classList.remove('payment-methods-required-message--visible');\n    }\n\n    function resaltarMetodosPago(){\n      const panel = document.querySelector('.payment-methods-panel') as HTMLElement;\n      const acordeon = document.querySelector('#first') as HTMLInputElement;\n      if(!panel)return;\r\n\r\n      const alertaSuperior = document.querySelector('#divmsjalertaprocesarpago') as HTMLElement;\r\n      if(alertaSuperior)alertaSuperior.innerHTML = '';\r\n\r\n      if(acordeon)acordeon.checked = true;\n      mostrarMensajeMetodosPago();\n      panel.classList.remove('separado-input--attention', 'payment-methods-panel--attention');\n      void panel.offsetWidth;\n      panel.classList.add('separado-input--attention', 'payment-methods-panel--attention');\n      panel.scrollIntoView({ behavior: 'smooth', block: 'center' });\n\n      setTimeout(()=>{\n        panel.classList.remove('separado-input--attention', 'payment-methods-panel--attention');\n      }, 2200);\n    }\n\r\n\r\n    document.querySelector('#formfacturar')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\n      if(valorTotal.total <= 0 || valorTotal.subtotal <= 0){\n        resaltarMetodosPago();\n        return;\n      }\n      //calcular si el totoal de los medios de pago es menor al abono inicial, abortar pago...\r\n      let totalMediosPago:number = 0;\r\n      for(let value of mapMediospago.values())totalMediosPago+=value;\r\n      if(totalMediosPago<POS.gestionSubirModalPagar.valoresCredito.abonoinicial){\n        resaltarMetodosPago();\n        return;\n      }\n\r\n      ocultarMensajeMetodosPago();\n      btnPagar.disabled = true;\r\n      btnPagar.value = 'Procesando...';\r\n      procesarSeparado();\r\n    });\r\n\r\n\r\n    async function procesarSeparado(){\r\n      const imprimir = document.querySelector('input[name=\"imprimir\"]:checked') as HTMLInputElement;\r\n      const valoresCredito = POS.gestionSubirModalPagar.valoresCredito;\r\n      valoresCredito.cliente_id = (document.querySelector('#cliente') as HTMLSelectElement).value;\r\n      valoresCredito.valorpagado = valoresCredito.abonoinicial;\r\n      valoresCredito.cajaid = btnCaja.value;\r\n      valoresCredito.totalunidades = carrito.reduce((total, producto)=>producto.cantidad+total, 0)+'';\r\n      valoresCredito.base = valorTotal.base.toFixed(3);\r\n      valoresCredito.valorimpuestototal = valorTotal.valorimpuestototal+'';\r\n      valoresCredito.dctox100 = valorTotal.dctox100+'';\r\n      valoresCredito.descuento = valorTotal.descuento+'';\r\n      valoresCredito.nota = (document.querySelector('#nota') as HTMLInputElement).value;\r\n\r\n      const datos = new FormData();\r\n      datos.append('cliente_id', $('#cliente').val()as string);\r\n      datos.append('abonoinicial', $('#abonoinicial').val()as string);\r\n      datos.append('cantidadcuotas', $('#cantidadcuotas').val()as string);\r\n      datos.append('montocuota', $('#montocuota').val()as string);\r\n      datos.append('frecuenciapago', $('#frecuenciapago').val()as string);\r\n      datos.append('carrito', JSON.stringify(carrito.filter(x=>x.cantidad>0)));  //envio de todos los productos con sus cantidades\r\n      datos.append('mediospago', JSON.stringify(Array.from(mapMediospago, ([mediopago_id, valor])=>({mediopago_id, idcuota:0, valor}))));\r\n      datos.append('valorefectivo', mapMediospago.get('1')??'0');\r\n      datos.append('factimpuestos', JSON.stringify(factimpuestos));\r\n      datos.append('valoresCredito', JSON.stringify(valoresCredito));\r\n\r\n      datos.append('totalunidades', carrito.reduce((total, producto)=>producto.cantidad+total, 0)+'');\r\n      datos.append('base', valorTotal.base.toFixed(3));\r\n      datos.append('valorimpuestototal', valorTotal.valorimpuestototal+''); //valor total del impuesto. \r\n      datos.append('dctox100', valorTotal.dctox100+'');\r\n      datos.append('descuento', valorTotal.descuento+'');\r\n      //datos.append('nota', (document.querySelector('#nota') as HTMLInputElement).value);\r\n      try {\r\n          const url = \"/admin/api/crearSeparado\";  //va al controlador creditoscontrolador\r\n          const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n          const resultado = await respuesta.json();\r\n          if(resultado.exito !== undefined){\r\n            msjalertToast('success', '\\u00a1Exito!', resultado.exito[0]);\r\n            /////// reinciar modulo de ventas\r\n            //vaciarventa();\r\n            btnPagar.disabled = false;\r\n            btnPagar.value = 'Pagar';\r\n            miDialogoFacturar.close();\r\n            \r\n            if(resultado.idcredito && imprimir.value === '1')\r\n              await printTicketSeparado(resultado.idcredito);\r\n            \r\n            setTimeout(() => { window.location.href = \"/admin/creditos\"; }, 900);\r\n          }else{\r\n            msjalertToast('error', '\\u00a1Error!', resultado.error[0]);\r\n          }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    }\r\n\r\n    function printTicketSeparado(idcredito:string): Promise<void>{\r\n      return new Promise<void>((resolve, reject) => {\r\n        setTimeout(() => {\r\n          window.open(\"/admin/printPDFPOSSeparado?id=\" + idcredito, \"_blank\");\r\n          resolve();\r\n        }, 700);\r\n      })\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      const miDialogoDescuento = POS.gestionarDescuentos.miDialogoDescuento;\r\n      const f = event.target;\r\n      if (f === miDialogoFacturar || f === miDialogoDescuento || (f as HTMLInputElement).closest('.salir') || (f as HTMLInputElement).value === 'salir' || (f as HTMLInputElement).value === 'Cancelar') {\r\n        miDialogoFacturar.close();\r\n        miDialogoDescuento.close();\r\n      }\r\n    }\r\n\r\n\r\n    POS.cerrarDialogoExterno = cerrarDialogoExterno;\r\n  }\r\n\r\n})();\n\r\n","\r\nclass ticketCreditoSeparadoBuilder extends EscPosBuilder{\r\n    private invoice: creditoSeparado;\r\n    constructor(invoice: creditoSeparado) {\r\n        super();\r\n        this.reset();\r\n        this.invoice = invoice;\r\n    }\r\n\r\n    async generate(buildBytes:boolean):Promise<string | Uint8Array> {\r\n        await this.header();\r\n        //if(this.invoice.tipoFactura === '1')this.customer(); //solo factura electronica\r\n        this.datosCreditoSeparado();\r\n        this.cliente();\r\n        this.items();\r\n        this.totals();\r\n        this.payments();\r\n        //if(this.invoice.tipoFactura === '1')this.infoResolution();  //solo factura electronica\r\n        await this.footer();\r\n        this.cut();\r\n        return this.build(buildBytes);\r\n    }\r\n\r\n    private async header() {\r\n        await this.image(`/build/img/${this.invoice.logo}`, {\r\n            width: 256,\r\n            align: 'center'\r\n        });\r\n        this.boldOn();\r\n        this.center(this.invoice.negocio.toUpperCase());\r\n        this.boldOff();\r\n        this.feed(1);\r\n        this.center(`NIT: ${this.invoice.nit.trim()}`);\r\n        this.center(`SEDE: ${this.invoice.sucursal.trim().toUpperCase()}`);\r\n        this.center(this.invoice.direccion.trim());\r\n        this.center(`TEL: ${this.invoice.telefono.trim()}`);\r\n        this.center(`Email: ${this.invoice.email.trim()}`);\r\n        this.feed(1);\r\n    }\r\n\r\n    /*private customer() { //cliente factura electronica\r\n        this.center(`Cliente: ${this.invoice.consumidorfinal.name}`);\r\n        this.center(`NIT: ${this.invoice.consumidorfinal.identification_number}`);\r\n    }*/\r\n\r\n    private datosCreditoSeparado(){\r\n        this.line();\r\n        this.setAlign('center');\r\n        this.text(`Fecha inicio: ${this.invoice.fechainicio.trim()}`);\r\n        this.text(`Fcha de finalizacion: ${this.invoice.fechafin.trim()}`);\r\n        this.text(`Vendedor: ${this.invoice.usuario?.nombre.trim()} ${this.invoice.usuario?.apellido.trim()}`);\r\n        this.bold(`CREDITO No: ${this.invoice.num_orden.trim()}`);\r\n        this.line();\r\n    }\r\n\r\n    private cliente(){\r\n        this.feed(1);\r\n        this.center(`Cliente: ${this.invoice.cliente.nombre.trim()} ${this.invoice.cliente.apellido.trim()}`);\r\n        this.center(`Documento: ${this.invoice.cliente.identificacion?.trim()??''}`);\r\n        this.center(`Telefono: ${this.invoice.cliente.telefono.trim()}`);\r\n        this.center(`Direccion: ${this.invoice?.direccionCliente?.direccion?.trim()||' - '}`);\r\n        this.feed(1);\r\n    }\r\n\r\n    private items() {\r\n        this.feed(1);\r\n        this.boldOn();\r\n        this.row3('CANT', 'UND', 'TOTAL', {col1:'left', col2:'right', col3:'right'}, [8, 16, 18]);\r\n        this.boldOff();\r\n        for(const item of this.invoice.productos) {\r\n            for(const line of this.wrap(item.nombreproducto.trim()))this.center(line);\r\n            //this.row(`${item.cantidad}  x  $${item.valorunidad.toLocaleString()}`, '$'+item.total.toLocaleString());\r\n            this.row3(item.cantidad.toString(), '$'+Number(item.valorunidad).toLocaleString(), '$'+Number(item.total).toLocaleString(), {col1:'left', col2:'right', col3:'right'}, [8, 16, 18]);\r\n        }\r\n    }\r\n\r\n    private totals() {\r\n        this.line();\r\n        this.feed(1);\r\n        this.setAlign('right');\r\n        this.text(`CREDITO TOTAL: $${Number(this.invoice.capital.trim()).toLocaleString()}`);\r\n        this.text(`Interes: $${Number(this.invoice.valorinterestotal.trim()).toLocaleString()}`);\r\n        this.text(`TOTAL ABONOS: $${Number(this.invoice.abonodecuotas.trim()).toLocaleString()}`);\r\n        this.text(`Descuento: $${Number(this.invoice.descuento.trim()).toLocaleString()}`);\r\n        this.line();\r\n        this.boldOn();\r\n        this.center(`SALDO PENDIENTE: $${Number(this.invoice.saldopendiente.trim()).toLocaleString()}`);\r\n        this.boldOff();\r\n    }\r\n\r\n    private payments() {\r\n        this.feed(2);\r\n        this.setAlign('center');\r\n        this.text('PAGOS');\r\n        for(const cuota of this.invoice.cuotas)\r\n            this.text(`${cuota.fechapagado}: $${cuota.valorpagado?.toLocaleString()}`);\r\n        \r\n        this.normalSize();\r\n        this.feed(1);\r\n        this.setAlign('left');\r\n        this.text(`Observacion: ${this.invoice.nota}`);\r\n        this.feed(2);\r\n    }\r\n\r\n    /*private infoResolution(){\r\n        this.setAlign('left');\r\n        this.text(`Resolucion: ${this.invoice.resolucion.resolucion}, Rango desde: ${this.invoice.resolucion.rangoinicial} hasta ${this.invoice.resolucion.rangofinal}`);\r\n        this.text(`CUFE: ${this.invoice.cufe || 'fe9c733f32770f5fcc4ef954f9ef663c54c752e6c07bdc144bb00627faadf9f648818da3e96ef8293547140fb1970d22'}`);\r\n        this.feed(2);\r\n    }*/\r\n\r\n    private async footer() {\r\n        this.setAlign('center');\r\n        this.feed(2);\r\n        this.text('***Para poder realizar un reclamo o devolución debe de presentar este ticket ***');\r\n        this.boldOn();\r\n        this.feed(1);\r\n        this.center('GRACIAS POR SU COMPRA');\r\n        this.boldOff();\r\n        this.feed(2);\r\n    }\r\n}\r\n\r\n\r\n\r\n//////////////////  DISEÑO DE TICKET PARA COMPROBANTE DE ABONOS  ///////////////////\r\nclass ticketAbonoBuilder extends EscPosBuilder{\r\n    private invoice: creditoSeparado;\r\n    constructor(invoice: creditoSeparado) {\r\n        super();\r\n        this.reset();\r\n        this.invoice = invoice;\r\n    }\r\n\r\n    async generate(buildBytes:boolean):Promise<string | Uint8Array> {\r\n        await this.header();\r\n        this.cliente();\r\n        this.totals();\r\n        await this.footer();\r\n        return this.build(buildBytes);\r\n    }\r\n\r\n    private async header() {\r\n        await this.image(`/build/img/${this.invoice.logo}`, {\r\n            width: 256,\r\n            align: 'center'\r\n        });\r\n        this.boldOn();\r\n        this.center(this.invoice.negocio.toUpperCase());\r\n        this.boldOff();\r\n        this.feed(1);\r\n        this.center(`NIT: ${this.invoice.nit.trim()}`);\r\n        this.center(`SEDE: ${this.invoice.sucursal.trim().toUpperCase()}`);\r\n        this.center(this.invoice.direccion.trim());\r\n        this.center(`TEL: ${this.invoice.telefono.trim()}`);\r\n        this.center(`Email: ${this.invoice.email.trim()}`);\r\n        this.feed(1);\r\n        this.line();\r\n    }\r\n\r\n    private cliente(){\r\n        this.feed(1);\r\n        this.center(`Cliente: ${this.invoice.cliente.nombre.trim()} ${this.invoice.cliente.apellido.trim()}`);\r\n        this.center(`Documento: ${this.invoice.cliente.identificacion?.trim()??''}`);\r\n        this.center(`Telefono: ${this.invoice.cliente.telefono.trim()}`);\r\n        this.center(`Direccion: ${this.invoice?.direccionCliente?.direccion?.trim()||' - '}`);\r\n        this.feed(1);\r\n    }\r\n\r\n    private totals() {\r\n        this.line();\r\n        this.feed(1);\r\n        this.setAlign('center');\r\n        this.bold(`CREDITO No: ${this.invoice.num_orden.trim()}`);\r\n        this.feed(2);\r\n        for(const cuota of this.invoice.cuotas){\r\n            this.text(`${cuota.fechapagado}  -  Abono No: ${cuota.numerocuota.trim()}`);\r\n            this.text(`Valor pagado: $${cuota.valorpagado?.toLocaleString()}`);\r\n        }\r\n    }\r\n\r\n    private async footer() {\r\n        this.normalSize();\r\n        this.cut();\r\n    }\r\n\r\n}\r\n\r\n","(()=>{\r\n  if(!document.querySelector('.ventas')&&!document.querySelector('.modorapido'))return;\r\n\r\n  const POS = (window as any).POS;\r\n\r\n  interface getAdquirienteDian {\r\n    ReceiverEmail:string, \r\n    ReceiverName:string, \r\n    StatusCode:string\r\n  }\r\n\r\n  interface adquirientes {\r\n    id?:string,\r\n    type_document_identification_id:string,\r\n    identification_number:string,\r\n    business_name:string,\r\n    email:string,\r\n    address:string,\r\n    municipality_id?:string,\r\n    department_id?:string,\r\n    ciudad_nombre:string\r\n    type_organization_id:string,\r\n    type_regime_id:string,\r\n    phone:string\r\n  }\r\n\r\n  type municipalities = {\r\n        id:string,\r\n        department_id:string,\r\n        name:string,\r\n        code:string,\r\n  };\r\n  let cities:municipalities[]=[];\r\n\r\n  const facturarA = document.querySelector('#facturarA') as HTMLButtonElement;\r\n  const miDialogoFacturarA = document.querySelector('#miDialogoFacturarA') as any;\r\n  const formFacturarA = document.querySelector('#formFacturarA') as HTMLFormElement;\r\n  const documentinput = document.querySelector('#identification_number') as HTMLInputElement;\r\n  const businessNameInput = document.querySelector('#business_name') as HTMLInputElement;\r\n  const btnBuscarAdquiriente = document.querySelector('#btnBuscarAdquiriente') as HTMLButtonElement;\r\n  const selectDepartments = document.querySelector('#department_id') as HTMLSelectElement;\r\n  const selectdCities = document.querySelector('#municipality_id') as HTMLSelectElement;\r\n  let customers:adquirientes[] = [];\r\n  let customersfiltrado:adquirientes|undefined, token:string|undefined;\r\n\r\n\r\n  (async ()=>{\r\n    const url = `/admin/api/filterAdquirientes`; \r\n    const respuesta = await fetch(url);\r\n    const resultado = await respuesta.json();\r\n    customers = resultado;\r\n    //formatearponentes(resultado);\r\n  })();\r\n\r\n  //consultar token\r\n  (async ()=>{\r\n    const url = `/admin/api/getCompaniesAll`; \r\n    const respuesta = await fetch(url);\r\n    const resultado:{id:string, identification_number:string, business_name:string, idsoftware:string, token:string, estado:string}[] = await respuesta.json();\r\n    token = resultado.find(x=>x.estado==='1')?.token;\r\n  })();\r\n\r\n  btnBuscarAdquiriente.addEventListener('click', (e:Event)=>{\r\n    if(documentinput.value.trim().length > 4 && token!=undefined){\r\n      console.log(documentinput.value.trim());\r\n      GetAcquirerDian(documentinput.value.trim());\r\n    }\r\n  });\r\n\r\n  const GetAcquirerDian = async (identificationnumber: string)=>{\r\n    try {\r\n          const url = \"https://apidianj2.com/api/ubl2.1/getAcquirer/13/\"+identificationnumber;  //va al controlador ventascontrolador\r\n          const respuesta = await fetch(url, {\r\n                                    method: 'GET',\r\n                                    headers: { \r\n                                      \"Accept\": \"application/json\", \r\n                                      \"Content-Type\": \"application/json\",\r\n                                      \"Authorization\": \"Bearer \"+token\r\n                                    },\r\n                                  }); \r\n          const resultado = await respuesta.json();\r\n          const {ReceiverEmail, ReceiverName, StatusCode}:getAdquirienteDian = resultado.data.GetAcquirerResult;\r\n          if(StatusCode === '200'){\r\n            (formFacturarA['business_name'] as HTMLInputElement).value = ReceiverName;\r\n            (formFacturarA['email'] as HTMLInputElement).value = ReceiverEmail;\r\n          }else{\r\n            msjAlert('error', 'No se encontro cliente en base de datos de la Dian', document.querySelector('#divmsjalertanoclienteDian') as HTMLElement);\r\n          }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n  }\r\n\r\n\r\n\r\n  //buscar adquiriente\r\n  documentinput.addEventListener('input', buscarAquiriente);\r\n  businessNameInput.addEventListener('input', buscarAquiriente);\r\n\r\n  function buscarAquiriente(e:Event){\r\n      const input = e.target as HTMLInputElement;\r\n      const busqueda:string = input.value.toLowerCase();\r\n\r\n      if(busqueda.length<3){\r\n        customersfiltrado = undefined;\r\n        //mostrarAdquiriente();\r\n        return;\r\n      }\r\n\r\n      customersfiltrado = customers.find(adq =>{\r\n        if(input.id==='identification_number'){\r\n          return adq.identification_number.trim() === busqueda.trim();\r\n        }else{\r\n          const nombre = adq.business_name.toLowerCase();\r\n          return nombre.trim() === busqueda.trim();\r\n        }\r\n      });\r\n      \r\n      mostrarAdquiriente();\r\n  }\r\n\r\n  function mostrarAdquiriente(){\r\n    if(customersfiltrado != undefined){\r\n      $('#type_document_identification_id').val(customersfiltrado.type_document_identification_id);\r\n      documentinput.value = customersfiltrado.identification_number;\r\n      (document.querySelector('#business_name') as HTMLInputElement).value = customersfiltrado.business_name;\r\n      (document.querySelector('#email') as HTMLInputElement).value = customersfiltrado.email;\r\n      (document.querySelector('#address') as HTMLInputElement).value = customersfiltrado.address;\r\n      if(customersfiltrado.department_id){\r\n        $('#department_id').val(customersfiltrado.department_id);\r\n        imprimirCiudades(customersfiltrado.department_id);\r\n      }\r\n      //$('#municipality_id').val(customersfiltrado.municipality_id);\r\n      $('#type_organization_id').val(customersfiltrado.type_organization_id);\r\n      $('#type_regime_id').val(customersfiltrado.type_regime_id);\r\n      (document.querySelector('#phone') as HTMLInputElement).value = customersfiltrado.phone;\r\n    }else{\r\n      $('#type_document_identification_id').val(\"\");\r\n      //(document.querySelector('#business_name') as HTMLInputElement).value = '';\r\n      (document.querySelector('#email') as HTMLInputElement).value = '';\r\n      (document.querySelector('#address') as HTMLInputElement).value = '';\r\n      $('#department_id').val(\"\");\r\n      $('#municipality_id').val(\"\");\r\n      $('#type_organization_id').val(\"\");\r\n      $('#type_regime_id').val(\"\");\r\n      (document.querySelector('#phone') as HTMLInputElement).value = \"\";\r\n    }\r\n  }\r\n\r\n\r\n\r\n  /////       Obtener municipio segun departamento        ///////\r\n  selectDepartments?.addEventListener('change', (e:Event)=>{\r\n    const x:HTMLOptionElement = (e.target as HTMLOptionElement);\r\n    imprimirCiudades(x.value);\r\n  });\r\n\r\n  function imprimirCiudades(x:string){\r\n    (async ()=>{\r\n      try {\r\n        const url = \"/admin/api/citiesXdepartments?id=\"+x; //llamado a la API REST y se trae las cities segun cliente elegido\r\n        const respuesta = await fetch(url); \r\n        const resultado = await respuesta.json(); \r\n        if(resultado.error){\r\n          Swal.fire(resultado.error[0], '', 'error')\r\n        }else{\r\n          cities = resultado;\r\n          addCitiesToSelect(cities);\r\n        }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();\r\n  }\r\n  \r\n  function addCitiesToSelect<T extends {id:string, department_id:string, name:string, code:string}>(addrs: T[]):void{\r\n    while(selectdCities?.firstChild)selectdCities.removeChild(selectdCities?.firstChild);\r\n    addrs.forEach(x =>{\r\n      const option = document.createElement('option');\r\n      option.textContent = x.name;\r\n      option.value = x.id;\r\n      option.dataset.code = x.code;\r\n      option.dataset.department_id = x.department_id;\r\n      selectdCities.appendChild(option);\r\n    });\r\n    if(customersfiltrado!=undefined&&customersfiltrado.municipality_id)$('#municipality_id').val(customersfiltrado.municipality_id);\r\n  }\r\n\r\n\r\n  ///////////////////// evento al btn facturar A /////////////////////\r\n  facturarA.addEventListener('click', (e:Event)=>{\r\n    miDialogoFacturarA.showModal();\r\n    document.addEventListener(\"click\", POS.cerrarDialogoExterno);\r\n  });\r\n\r\n   \r\n  formFacturarA.addEventListener('submit', (e:Event)=>{\r\n    e.preventDefault();\r\n    const data = new FormData(formFacturarA);\r\n    const datosAdquiriente: Record<string, FormDataEntryValue> = Object.fromEntries(data.entries());\r\n    miDialogoFacturarA.close();\r\n    document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\r\n\r\n    const identification = datosAdquiriente.identification_number as string;\r\n    const requiereEmail = identification && identification!='222222222222';\r\n    // Validar email solo si identification_number es distinto de 222222222222 y no vacío\r\n    if (requiereEmail && !validarEmail(datosAdquiriente.email as string)) {\r\n        Swal.fire(\"Correo incorrecto\", \"Debe ingresar un email válido o enviar a consumidor final o generico: 222222222222\", \"error\");\r\n        return; // detiene el proceso\r\n    }\r\n\r\n    if(identification && identification!='222222222222'){\r\n      const dv = getDgv(Number(identification));\r\n      datosAdquiriente.dv = dv.toString();\r\n    }\r\n\r\n    console.log(datosAdquiriente);\r\n\r\n    POS.gestionarAdquiriente.datosAdquiriente = datosAdquiriente; //guarda en el objeto global\r\n    //guardar adquiriente en DB.\r\n    guardarAdquiriente(datosAdquiriente);\r\n  });\r\n\r\n  function validarEmail(correo: string): boolean {\r\n      const regex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\r\n      return regex.test(correo);\r\n  }\r\n\r\n\r\n  async function guardarAdquiriente(datosAdquiriente: Record<string, FormDataEntryValue>){\r\n    try {\r\n          const url = \"/admin/api/guardarAdquiriente\";  //va al controlador ventascontrolador\r\n          const respuesta = await fetch(url, {\r\n                                    method: 'POST',\r\n                                    headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                    body: JSON.stringify(datosAdquiriente)\r\n                                  }); \r\n          const resultado = await respuesta.json();\r\n          //añadir o actualizar al arreglo customers\r\n          if(resultado.tipo == \"crear\"){\r\n            customers = [...customers, resultado.obj];\r\n          }else{\r\n            /// actualizar el arregle del adquiriente o customers ///\r\n            customers.forEach(a=>{if(a.identification_number == resultado.obj.identification_number)a = Object.assign(a, resultado.obj);});\r\n          }\r\n          datosAdquiriente.id = resultado.obj.id;\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n  }\r\n  \r\n\r\n  const gestionarAdquiriente = {  //objeto a exportar\r\n    miDialogoFacturarA,\r\n    datosAdquiriente: {} //inicializar \r\n  };\r\n\r\n  POS.gestionarAdquiriente = gestionarAdquiriente;\r\n\r\n})();","(()=>{\r\n  if(!document.querySelector('.ventas')&&!document.querySelector('.modorapido'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const btnAddCliente = document.querySelector('#addcliente') as HTMLElement;\r\n    const btnAddDir = document.querySelector('#adddir') as HTMLElement;\r\n    const miDialogoAddCliente = document.querySelector('#miDialogoAddCliente') as any;\r\n    //const miDialogoAddDir = document.querySelector('#miDialogoAddDir') as any;\r\n    const selectCliente = document.querySelector('#selectCliente') as HTMLSelectElement;\r\n    const tel = document.querySelector('#telefono')! as HTMLInputElement;\n    const doc = document.querySelector('#identificacion')! as HTMLInputElement;\n    const dirEntrega = document.querySelector('#direccionEntrega')! as HTMLSelectElement;\n    const direccionPreferidaPorCliente = new Map<string, string>();\n\r\n  const gestionClientes = {\r\n    selectCliente,\r\n    dirEntrega,\r\n    miDialogoAddCliente,\r\n    //miDialogoAddDir,\r\n\r\n    clientes(){\r\n        \r\n        //////////// evento al boton añadir cliente nuevo //////////////\r\n        btnAddCliente?.addEventListener('click', (e)=>{\r\n            miDialogoAddCliente.showModal();\r\n            ($('#selectCliente') as any).select2({\r\n                dropdownParent: $('#miDialogoAddCliente'),\r\n                placeholder: \"Seleccionar el cliente\",\r\n                maximumSelectionLength: 1\r\n            });\r\n            document.addEventListener(\"click\", POS.cerrarDialogoExterno);\r\n        });\r\n        //////////// evento al boton añadir nueva direccion //////////////\r\n        /*btnAddDir?.addEventListener('click', (e)=>{\r\n            miDialogoAddDir.showModal();\r\n            document.addEventListener(\"click\", POS.cerrarDialogoExterno);\r\n        });*/\r\n        //////////// evento al btn submit del formulario add nuevo cliente //////////////\r\n        document.querySelector('#formAddCliente')?.addEventListener('submit', e=>{\n            e.preventDefault();\n            (async ()=>{\n                const direccionSeleccionada = dirEntrega.value;\n                const datos = new FormData();\n                datos.append('idcliente', selectCliente?.value??null); //id del cliente\r\n                datos.append('nombre', (document.querySelector('#nombreclientenuevo') as HTMLInputElement).value);\r\n                datos.append('apellido', (document.querySelector('#clientenuevoapellido') as HTMLInputElement).value || '  ');\r\n                datos.append('tipodocumento', (document.querySelector('#tipodocumento') as HTMLInputElement).value);\r\n                datos.append('telefono', (document.querySelector('#telefono') as HTMLInputElement).value);\r\n                datos.append('iddireccion', direccionSeleccionada);\n                //datos.append('idtarifa', (document.querySelector('#clientenuevotarifa') as HTMLSelectElement).value);\r\n                datos.append('tipodocumento', (document.querySelector('#tipodocumento') as HTMLInputElement).value);\r\n                datos.append('identificacion', (document.querySelector('#identificacion') as HTMLInputElement).value);\r\n                datos.append('email', (document.querySelector('#clientenuevoemail') as HTMLInputElement).value);\r\n                datos.append('departamento', (document.querySelector('#departamento') as HTMLInputElement).value||'No definido');\r\n                datos.append('ciudad', (document.querySelector('#ciudad') as HTMLInputElement).value || 'No definido');\r\n                datos.append('direccion', (document.querySelector('#clientenuevodireccion') as HTMLInputElement).value);\r\n                try {\r\n                    let url = \"/admin/api/apiCrearCliente\";\r\n                    if(selectCliente.value!=='')url = \"/admin/api/actualizarCliente\";\r\n\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                    msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                    const clienteGuardado = resultado.nextID || selectCliente.value;\n                    if(clienteGuardado && direccionSeleccionada)direccionPreferidaPorCliente.set(clienteGuardado, direccionSeleccionada);\n                    if(selectCliente.value=='')addClienteSelect(resultado.nextID);\n                    if(selectCliente.value!=='')$('#selectCliente').val(clienteGuardado).trigger('change');\n                    //POS.limpiarformdialog();\r\n                    }else{\r\n                    msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n            miDialogoAddCliente.close();\r\n            document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\r\n        });\r\n        /////////////// añadir cliente al select despues de crearse ///////////////////\r\n        function addClienteSelect(clienteID:string): void{\r\n            const option = document.createElement('option');\r\n            option.textContent = (document.querySelector('#nombreclientenuevo') as HTMLInputElement).value + \" \" + (document.querySelector('#clientenuevoapellido') as HTMLInputElement).value;\r\n            option.value = clienteID;\r\n            option.dataset.tipodocumento = (document.querySelector('#tipodocumento') as HTMLInputElement).value;\r\n            option.dataset.identidad = (document.querySelector('#identificacion') as HTMLInputElement).value;\r\n            selectCliente?.appendChild(option);\r\n            $('#selectCliente').val(clienteID).trigger('change'); // seleccionar el cliente nuevo, en el select y dispara evento\r\n        }\r\n        \r\n        //evento 'cambio' al selecionar cliente, tambien se ejecuta cuando se crea cliente nuevo//\r\n        $(\"#selectCliente\").on('change', (e)=>{\r\n            const idcli = (e.target as HTMLInputElement).value;\r\n            if(idcli){\r\n                (async ()=>{\r\n                    try {\r\n                        const url = \"/admin/api/clientes/direccionesXcliente?id=\"+idcli; //llamado a la API REST y se trae el cliente y sus direcciones direccionescontrolador, tambien traer sus precios personalizados\r\n                        const respuesta = await fetch(url); \r\n                        const resultado = await respuesta.json();\r\n                        (document.querySelector('#nombreclientenuevo') as HTMLInputElement).value = resultado.nombre;\r\n                        (document.querySelector('#clientenuevoapellido') as HTMLInputElement).value = resultado.apellido;\r\n                        (document.querySelector('#telefono') as HTMLInputElement).value =  resultado.telefono;\r\n                        addDireccionSelect(resultado);\r\n                        (document.querySelector('#tipodocumento') as HTMLSelectElement).value = resultado.tipodocumento;\r\n                        (document.querySelector('#identificacion') as HTMLInputElement).value = resultado.identificacion;\r\n                        (document.querySelector('#clientenuevoemail') as HTMLInputElement).value = resultado.email;\r\n                        (document.querySelector('#resumenCliente') as HTMLParagraphElement).textContent = resultado.nombre+' '+resultado.apellido;\r\n                        (document.querySelector('#badgeEstado') as HTMLParagraphElement).textContent = 'SELECCIONADO';\r\n                        (document.querySelector('#badgeEstado') as HTMLParagraphElement).classList.remove('bg-gray-100', 'text-gray-700');\r\n                        (document.querySelector('#badgeEstado') as HTMLParagraphElement).classList.add('bg-green-100', 'text-green-600');\r\n                        //mapear los precios personalizados del cliente con arreglo de los productos\r\n                        actualizarPreciosCliente(resultado.preciospersonalizados);\r\n                    } catch (error) {\r\n                        console.log(error);\r\n                    }\r\n                })();   \r\n            }else{\r\n                (document.querySelector('#resumenCliente') as HTMLParagraphElement).textContent = 'Seleccionar cliente';\r\n                (document.querySelector('#badgeEstado') as HTMLParagraphElement).textContent = 'SIN CLIENTE';\r\n                (document.querySelector('#badgeEstado') as HTMLParagraphElement).classList.remove('bg-green-100', 'text-green-600');\r\n                (document.querySelector('#badgeEstado') as HTMLParagraphElement).classList.add('bg-gray-100', 'text-gray-700');\r\n                //actualizar array de products y DOM\r\n                for(const prod of POS.products){\r\n                    const item = POS.hackerList.get('id', prod.id)[0];\r\n                    prod.precio_venta = prod.precio_original;\r\n                    if(item)item.elm.querySelector('.precioVenta').textContent = '$'+Number(prod.precio_venta).toLocaleString();\r\n                }\r\n                //actualizar el carrito de ventas con los valores originales\r\n                if(POS.carrito)\r\n                    POS.carrito.forEach((cr:CarritoItem)=>{\r\n                        cr.valorunidad = POS.products.find((p:productsapi)=>p.id==cr.idproducto)?.precio_venta??cr.valorunidad;\r\n                        cr.subtotal = cr.valorunidad * cr.stock!;\r\n                        cr.total = cr.subtotal;\r\n                        cr.valorcomision = (cr.subtotal*cr.percentcomision)/100;\r\n                        cr.base = 1/(1+(Number(cr.impuesto)/100))*cr.subtotal;\r\n                        cr.valorimp = cr.subtotal - cr.base;\r\n                    });\r\n                POS.valorCarritoTotal();\r\n            }\r\n        });\r\n\r\n        ////// añade direccion al select de direcciones, cuando se selecciona o se agrega un cliente o si se agrega un nueva direccion/////\r\n        function addDireccionSelect<T extends {id:string, nombre:string, apellido:string, telefono:string, identificacion:string, email:string, direcciones:{id:string, idcliente:string, idtarifa:string, tarifa:{id:string, idcliente:string, nombre:string, valor:string}, direccion:string, departamento:string, ciudad:string}[]}>(addrs: T):void{\n            while(dirEntrega?.firstChild)dirEntrega.removeChild(dirEntrega?.firstChild);\n            const setTarifas = new Set();\n            POS.tarifas.length = 0;\n            const direccionPreferida = direccionPreferidaPorCliente.get(addrs.id);\n            addrs.direcciones.forEach(dir =>{\n                const option = document.createElement('option');\r\n                option.textContent = dir.direccion;\r\n                option.value = dir.id;\r\n                option.dataset.idcliente = dir.idcliente;\r\n                option.dataset.idtarifa = dir.idtarifa;\r\n                option.dataset.ciudad = dir.ciudad;\r\n                dirEntrega.appendChild(option);\r\n                dir.tarifa.idcliente = dir.idcliente;\r\n                if(!setTarifas.has(dir.tarifa.id)){\r\n                POS.tarifas = [...POS.tarifas, dir.tarifa];\r\n                setTarifas.add(dir.tarifa.id);\r\n                }\n            });\n            if(direccionPreferida && addrs.direcciones.some(dir=>dir.id === direccionPreferida)){\n                dirEntrega.value = direccionPreferida;\n            }\n            setTarifas.clear();\n            POS.printTarifaEnvio();\n            POS.valorCarritoTotal();\n            const direccionActual = addrs.direcciones.find(dir=>dir.id === dirEntrega.value) || addrs.direcciones[0];\n            (document.querySelector('#departamento') as HTMLInputElement).value = direccionActual?.departamento??'No especificado';\n            (document.querySelector('#ciudad') as HTMLInputElement).value = direccionActual?.ciudad??'No especificado';\n        }\n\r\n\r\n        function actualizarPreciosCliente(preciosDelCliente:{id:string, idcliente:string, idproducto:string, precioxcliente:string}[]){\r\n            //resetar o eliminar precios personalizados de clientes anteriores\r\n            const mapaPrecios = new Map( preciosDelCliente.map(p => [p.idproducto, p.precioxcliente]) );\r\n            POS.products.forEach((prod:productsapi) => {\r\n                if(mapaPrecios.has(prod.id)){\r\n                    prod.precio_venta = mapaPrecios.get(prod.id)!;\r\n                }else{\r\n                    prod.precio_venta = prod.precio_original!;\r\n                }\r\n            });\r\n\r\n            for(const prod of mapaPrecios.entries()){\r\n                const item = POS.hackerList.get('id', prod[0])[0];\r\n                if(item)item.elm.querySelector('.precioVenta').textContent = '$'+Number(prod[1]).toLocaleString();\r\n            }\r\n        }\r\n\r\n\r\n        ///////// Evento al input de telefono para buscar cliente por telefono ////////////\r\n        tel?.addEventListener('input', (e:Event)=>{\r\n            const contact = (e.target as HTMLInputElement).value.trim();\r\n            if (contact.length < 6) return;\r\n            const cli = clientesDB.find(c => c.telefono === contact);\r\n            console.log(cli);\r\n            if(cli!=undefined)$('#selectCliente').val(cli.id).trigger('change'); \r\n        });\r\n\r\n\r\n        ///////// Evento al input de identificacion para buscar cliente por documento ////////////\r\n        doc?.addEventListener('input', (e:Event)=>{\r\n            const iD = (e.target as HTMLInputElement).value.trim();\r\n            if (iD.length < 5) return;\r\n            const cli = clientesDB.find(c => c.identificacion === iD);\r\n            console.log(cli);\r\n            if(cli!=undefined)$('#selectCliente').val(cli.id).trigger('change'); \r\n        });\r\n        \r\n\r\n        ///////// Evento al select de direcciones ////////////\r\n        dirEntrega?.addEventListener('change', (e)=>{\n            const select = (e.target as HTMLSelectElement);\n            if(selectCliente.value && select.value)direccionPreferidaPorCliente.set(selectCliente.value, select.value);\n            const x:string = select.options[select.selectedIndex].dataset.ciudad||'';\n            (document.querySelector('#ciudad') as HTMLInputElement).value = x;\r\n            POS.printTarifaEnvio();\r\n            POS.valorCarritoTotal();\r\n        });\r\n\r\n        ////////////////// evento al btn submit del formulario add direccion //////////////////////\r\n        /*document.querySelector('#formAddDir')?.addEventListener('submit', e=>{\r\n            e.preventDefault();\r\n            (async ()=>{\r\n                const datos = new FormData();\r\n                datos.append('idcliente', selectCliente.value);\r\n                datos.append('departamento', (document.querySelector('#adddepartamento') as HTMLInputElement).value);\r\n                datos.append('ciudad', (document.querySelector('#addciudad') as HTMLInputElement).value);\r\n                datos.append('direccion', (document.querySelector('#adddireccion') as HTMLInputElement).value);\r\n                datos.append('idtarifa', (document.querySelector('#tarifa') as HTMLSelectElement).value);\r\n                try {\r\n                    const url = \"/admin/api/addDireccionCliente\";  //direccionescontrolador\r\n                    const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                    const resultado = await respuesta.json();\r\n                    if(resultado.exito !== undefined){\r\n                    msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                    addDireccionSelect(resultado.direcciones);\r\n                    }else{\r\n                    msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                    }\r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n            //miDialogoAddDir.close();\r\n            //document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\r\n        });*/\r\n        \r\n    }\r\n    \r\n  };\r\n\r\n  (window as any).POS.gestionClientes = gestionClientes;\r\n\r\n\r\n})();\n","(()=>{\r\n  if(!document.querySelector('.ventas')&&!document.querySelector('.crearseparado')&&!document.querySelector('.modorapido'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    //obtener valor porcentual del interes por cuota\r\n    let tasaInteresDB:number = 0;\r\n    /*(async ()=>{\r\n      try {\r\n          const url = \"/admin/api/getParamGlobal\"; //llamado a la API REST\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json(); \r\n          tasaInteresDB = Number(resultado.tasa_de_interes_por_cuota.valor_final);\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();*/\r\n    tasaInteresDB = Number(getParam.tasa_de_interes_por_cuota.valor_final);\r\n\r\n    const mediospago = document.querySelectorAll<HTMLInputElement>('.mediopago');\r\n    const interes = document.querySelector('#interes') as HTMLSelectElement;\r\n    const abonoinicial = (document.querySelector('#abonoinicial') as HTMLInputElement);\r\n    const cantidadcuotas = (document.querySelector('#cantidadcuotas') as HTMLInputElement);\r\n    //let tipoventa:string=\"Contado\";\r\n    let valoresCredito = {capital:0, abonoinicial:0, cantidadcuotas:1, montocuota:0, frecuenciapago:1, interes:0, interestotal:0, valorinterestotal:0, valorinteresxcuota:0, montototal:0};\r\n\r\n    //eventos a los inputs medios de pago\r\n    mediospago.forEach(m=>{\r\n      m.addEventListener('input', (e)=>{ calcularmediospago(e);});\r\n      m.addEventListener('focus', ()=>{\r\n        const valorActual = parseInt(m.value.replace(/[^\\d]/g, ''))||0;\r\n        if(valorActual === 0)m.value = '';\r\n      });\r\n      m.addEventListener('blur', (e)=>{\r\n        if(m.value.trim() !== '')return;\r\n        m.value = '0';\r\n        if(!m.readOnly)calcularmediospago(e);\r\n      });\r\n    });\r\n\r\n    const botonAgregarMedioPago = document.querySelector('#btnTogglePaymentMethods') as HTMLElement|null;\r\n    const acordeonMediosPago = document.querySelector('#first') as HTMLInputElement|null;\r\n\r\n    function abrirMediosPago(){\r\n      if(acordeonMediosPago)acordeonMediosPago.checked = true;\r\n      const primerMedioEditable = Array.from(mediospago).find(input=>!input.readOnly && !input.disabled);\r\n      setTimeout(()=>primerMedioEditable?.focus(), 80);\r\n    }\r\n\r\n    botonAgregarMedioPago?.addEventListener('click', (event)=>{\r\n      event.preventDefault();\r\n      event.stopPropagation();\r\n      abrirMediosPago();\r\n    });\r\n\r\n    botonAgregarMedioPago?.addEventListener('keydown', (event)=>{\r\n      if(event.key !== 'Enter' && event.key !== ' ')return;\r\n      event.preventDefault();\r\n      abrirMediosPago();\r\n    });\r\n\r\n    /////////////////////  evento al input recibido  //////////////////////////\r\n    document.querySelector<HTMLInputElement>('#recibio')?.addEventListener('input', (e)=>{\r\n      calcularCambio((e.target as HTMLInputElement).value);\r\n    });\r\n    \r\n    const gestionSubirModalPagar = {\r\n        \r\n      subirModalPagar(){\r\n        //initvaloresCredito();\r\n        document.querySelector('#totalPagar')!.textContent = `${POS.valorTotal.total.toLocaleString()}`;\r\n        //como se puede cerrar el modal y aumentar los productos, hay calcular los inputs\r\n        let totalotrosmedios = 0;\r\n        mediospago.forEach((item, index)=>{\r\n            if(index>0)totalotrosmedios += parseInt(item.value.replace(/[,.]/g, ''))||0;\r\n        });\r\n\r\n        if(POS.valorTotal.total<totalotrosmedios){\r\n            totalotrosmedios = 0;\r\n            POS.mapMediospago.clear();\r\n            $('.mediopago').val(0);\r\n        }\r\n        if(POS.tipoventa == \"Contado\"){\r\n            (document.querySelector('.Efectivo')! as HTMLInputElement).value =  `${(POS.valorTotal.total-totalotrosmedios).toLocaleString()}`;\r\n            POS.mapMediospago.set('1', POS.valorTotal.total-totalotrosmedios); //inicialmente el valor total se establece para efectivo\r\n        }\r\n        if(POS.valorTotal.total-totalotrosmedios == 0 && POS.mapMediospago.has('1'))POS.mapMediospago.delete('1');\r\n        calcularCambio(document.querySelector<HTMLInputElement>('#recibio')!.value);\r\n        ocultarMensajeMetodosPagoSiCorresponde();\r\n        if(POS.tipoventa == \"Credito\")calculoTasaInteres();\r\n        if(POS.tipoventa == \"Contado\")initvaloresCredito();\r\n      },\r\n      calculoTasaInteres,\r\n      mostrarMensajeMetodosPago,\r\n      valoresCredito\r\n      \r\n    };\r\n\r\n\r\n    function initvaloresCredito(){\r\n      /*valoresCredito.capital = POS.valorTotal.total;  //inicializar el capital en el obj\r\n      valoresCredito.cantidadcuotas = Number(cantidadcuotas.value);\r\n      valoresCredito.montocuota = (valoresCredito.capital - valoresCredito.abonoinicial)/valoresCredito.cantidadcuotas;\r\n      valoresCredito.interes = 0;  //No aplicar interes\r\n      valoresCredito.interestotal = 0;  // 0% de interes\r\n      valoresCredito.valorinterestotal = 0; //0$ de interes total de la factura\r\n      valoresCredito.valorinteresxcuota = 0;  //0$ de interes de cada cuota\r\n      valoresCredito.montototal = valoresCredito.capital;\r\n      (document.querySelector('#montocuota') as HTMLInputElement).value = valoresCredito.montocuota+'';*/\r\n      valoresCredito.capital=0; \r\n      valoresCredito.abonoinicial=0;\r\n      valoresCredito.cantidadcuotas=1;\r\n      valoresCredito.montocuota=0;\r\n      valoresCredito.frecuenciapago=1,\r\n      valoresCredito.interes=0;  //No aplicar interes\r\n      valoresCredito.interestotal=0;  // 0% de interes\r\n      valoresCredito.valorinterestotal=0;  //0$ de interes total de la factura\r\n      valoresCredito.valorinteresxcuota=0;  //0$ de interes de cada cuota\r\n      valoresCredito.montototal=0;\r\n    }\r\n\r\n    \r\n    function ocultarMensajeMetodosPagoSiCorresponde(){\r\n      const mensaje = document.querySelector('#paymentMethodsRequiredMessage') as HTMLElement;\r\n      if(!mensaje)return;\r\n\r\n      let totalMediosPago = 0;\r\n      for(const value of POS.mapMediospago.values())totalMediosPago += Number(value);\r\n\r\n      if(totalMediosPago > 0){\r\n        mensaje.classList.add('hidden');\r\n        mensaje.classList.remove('payment-methods-required-message--visible');\r\n        document.querySelector('.payment-methods-panel')?.classList.remove('payment-methods-panel--attention', 'separado-input--attention');\r\n      }\r\n    }\r\n\r\n    function ocultarMensajeMetodosPago(){\r\n      const mensaje = document.querySelector('#paymentMethodsRequiredMessage') as HTMLElement;\r\n      if(!mensaje)return;\r\n\r\n      mensaje.classList.add('hidden');\r\n      mensaje.classList.remove('payment-methods-required-message--visible');\r\n      document.querySelector('.payment-methods-panel')?.classList.remove('payment-methods-panel--attention', 'separado-input--attention');\r\n    }\r\n    function mostrarMensajeMetodosPago(){\r\n      const alertaSuperior = document.querySelector('#divmsjalertaprocesarpago') as HTMLElement;\r\n      const mensaje = document.querySelector('#paymentMethodsRequiredMessage') as HTMLElement;\r\n      const panel = document.querySelector('.payment-methods-panel') as HTMLElement;\r\n\r\n      if(alertaSuperior)alertaSuperior.innerHTML = '';\r\n      if(acordeonMediosPago)acordeonMediosPago.checked = true;\r\n\r\n      if(mensaje){\r\n        mensaje.classList.remove('hidden', 'payment-methods-required-message--visible');\r\n        void mensaje.offsetWidth;\r\n        mensaje.classList.add('payment-methods-required-message--visible');\r\n      }\r\n\r\n      if(panel){\r\n        panel.classList.remove('payment-methods-panel--attention', 'separado-input--attention');\r\n        void panel.offsetWidth;\r\n        panel.classList.add('payment-methods-panel--attention', 'separado-input--attention');\r\n        panel.scrollIntoView({ behavior: 'smooth', block: 'center' });\r\n        setTimeout(()=>{\r\n          panel.classList.remove('payment-methods-panel--attention', 'separado-input--attention');\r\n        }, 2200);\r\n      }\r\n\r\n      const primerMedioEditable = Array.from(mediospago).find(input=>!input.readOnly && !input.disabled);\r\n      setTimeout(()=>primerMedioEditable?.focus(), 180);\r\n    }\r\n    function calcularmediospago(e:Event){\r\n        let totalotrosmedios = 0;\r\n        mediospago.forEach((item, index)=>{ //sumar todos los medios de pago menos el efectivo\r\n          if(index>0&&POS.tipoventa==\"Contado\" || POS.tipoventa==\"Credito\")totalotrosmedios += parseInt(item.value.replace(/[,.]/g, ''))||0;\r\n        });\r\n        if(totalotrosmedios<=POS.valorTotal.total&&POS.tipoventa == \"Contado\" || totalotrosmedios<=valoresCredito.abonoinicial&&POS.tipoventa == \"Credito\"){\r\n          if(POS.tipoventa == \"Contado\"){\r\n            POS.mapMediospago.set('1', POS.valorTotal.total-totalotrosmedios);\r\n            if(POS.valorTotal.total-totalotrosmedios == 0 && POS.mapMediospago.has('1'))POS.mapMediospago.delete('1'); //se elimina medio de pago efectivo\r\n          }\r\n          const valorMedioPago = parseInt((e.target as HTMLInputElement).value.replace(/[,.]/g, ''))||0;\r\n          POS.mapMediospago.set((e.target as HTMLInputElement).id, valorMedioPago);\r\n          if(valorMedioPago == 0 && POS.mapMediospago.has((e.target as HTMLInputElement).id))POS.mapMediospago.delete((e.target as HTMLInputElement).id);\r\n        }else{ //si la suma de los medios de pago superan el valor total, toma el ultimo input digitado y lo reestablece a su ultimo valor\r\n          if(POS.mapMediospago.has((e.target as HTMLInputElement).id)){\r\n            (e.target as HTMLInputElement).value = POS.mapMediospago.get((e.target as HTMLInputElement).id).toLocaleString();\r\n          }else{\r\n            (e.target as HTMLInputElement).value = '0';\r\n          }\r\n        }\r\n        if(POS.tipoventa == \"Contado\"){\r\n          mediospago[0].value = (POS.mapMediospago.get('1')??0).toLocaleString();  //medio de pago en efectivo\r\n        }\r\n        calcularCambio(document.querySelector<HTMLInputElement>('#recibio')!.value);\r\n        ocultarMensajeMetodosPagoSiCorresponde();\r\n    }\r\n\r\n    function calcularCambio(recibido:string):void{\r\n      recibido = recibido.replace(/[,.]/g, '');\r\n      if(Number(recibido)>POS.mapMediospago.get('1')){\r\n        (document.querySelector('#cambio') as HTMLElement).textContent = (Number(recibido)-POS.mapMediospago.get('1')).toLocaleString()+'';\r\n        return;\r\n      }\r\n      (document.querySelector('#cambio') as HTMLElement).textContent = '0';\r\n    }\r\n\r\n\r\n    ////////////////////  CALCULO DE VALORES DEL CREDITO  //////////////////////\r\n\r\n    interes.addEventListener('change', e=>calculoTasaInteres());\r\n    cantidadcuotas.addEventListener('input', e=>calculoTasaInteres());\r\n    abonoinicial.addEventListener('input', e=>calculoTasaInteres());\r\n\r\n    function calculoTasaInteres(){\r\n      let creditofinal = recalcularCapitalXAbono(); //capital inicial - abono\r\n      initMediosPagos();\r\n      valoresCredito.cantidadcuotas = Number(cantidadcuotas.value);\r\n      if(cantidadcuotas.value == '1' || (interes.value == '0' || interes.value == '')){\r\n        (document.querySelector('#montocuota') as HTMLInputElement).value =  (Math.ceil((creditofinal/valoresCredito.cantidadcuotas)*100)/100)+'';\r\n        //(document.querySelector('#interestotal') as HTMLInputElement).value = '0';\r\n        //(document.querySelector('#valorinteresxcuota') as HTMLInputElement).value = '0';\r\n        //(document.querySelector('#valorinterestotal') as HTMLInputElement).value = '0';\r\n        //(document.querySelector('#montototal') as HTMLInputElement).value = creditofinal.toLocaleString();\r\n        valoresCredito.montocuota = (Math.ceil((creditofinal/valoresCredito.cantidadcuotas)*100)/100);\r\n        valoresCredito.interestotal = 0;\r\n        valoresCredito.valorinteresxcuota = 0;\r\n        valoresCredito.valorinterestotal = 0;\r\n        valoresCredito.montototal = creditofinal;\r\n      }\r\n      if(cantidadcuotas.value !== '1'&&interes.value === '1'){\r\n        const valorInteres = creditofinal*(tasaInteresDB/100)*valoresCredito.cantidadcuotas;\r\n        const total = creditofinal + valorInteres;\r\n        const valorxcuota = Math.ceil((total/valoresCredito.cantidadcuotas)*100)/100;\r\n        (document.querySelector('#montocuota') as HTMLInputElement).value = valorxcuota+'';\r\n        //(document.querySelector('#interestotal') as HTMLInputElement).value = 2*valoresCredito.cantidadcuotas+''; //porcentaje de interes total\r\n        //(document.querySelector('#valorinteresxcuota') as HTMLInputElement).value = valorInteres/valoresCredito.cantidadcuotas+'';\r\n        //(document.querySelector('#valorinterestotal') as HTMLInputElement).value = valorInteres.toLocaleString();  //valor del interes total del credito\r\n        //(document.querySelector('#montototal') as HTMLInputElement).value = total.toLocaleString();  //valor total del credito\r\n        valoresCredito.interes = 1;\r\n        valoresCredito.montocuota = valorxcuota;\r\n        valoresCredito.interestotal = tasaInteresDB*valoresCredito.cantidadcuotas;\r\n        valoresCredito.valorinteresxcuota = valorInteres/valoresCredito.cantidadcuotas;\r\n        valoresCredito.valorinterestotal = valorInteres;\r\n        valoresCredito.montototal = total;\r\n      }\r\n      //(document.querySelector('#capitalinicial') as HTMLInputElement).value = capital.value.toLocaleString();\r\n      //(document.querySelector('#abono') as HTMLInputElement).value = Number(abonoinicial.value).toLocaleString();\r\n      //(document.querySelector('#capitalFinanciado') as HTMLInputElement).value = creditofinal+'';\r\n      \r\n    }\r\n\r\n    function recalcularCapitalXAbono():number{\r\n      const capital = POS.valorTotal.total;\r\n      let abono = Number(abonoinicial.value??0);\r\n      const capitalinicial:number = capital;\r\n      let creditofinal:number = capitalinicial;\r\n      if(capital>0){\r\n        if(abono < capitalinicial){\r\n          creditofinal = capitalinicial-abono;\r\n        }else{\r\n          abonoinicial.value = '0';\r\n        }\r\n      }\r\n      valoresCredito.capital = capital;\r\n      valoresCredito.abonoinicial = abono;\r\n      document.querySelector('#valorAbono')!.textContent = abono.toLocaleString();\r\n      return creditofinal;\r\n    }\r\n\r\n\r\n    function initMediosPagos(){\r\n      mediospago.forEach(z=>z.value = '0');\r\n      POS.mapMediospago.clear();\r\n      ocultarMensajeMetodosPago();\r\n    }\r\n\r\n    POS.gestionSubirModalPagar = gestionSubirModalPagar;\r\n\r\n})();\r\n\r\n","(()=>{\r\n  if(document.querySelector('.ventas') || document.querySelector('.ordenresumen') || document.querySelector('.detalleinvoice') || document.querySelector('.modorapido')){\r\n\r\n    const sendInvoiceAPI = {\r\n\r\n      async sendInvoice(x:number){\r\n        console.log(x);\r\n        try {\r\n            const url = \"/admin/api/sendInvoice\"; //llamado a la API REST apidiancontrolador.php\r\n            const respuesta = await fetch(url, {\r\n              method: 'POST', \r\n              headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n              body: JSON.stringify({id: x}) \r\n            });\r\n            \r\n            const responseDian = await respuesta.json();\r\n            /*return new Promise(resolve => {\r\n              setTimeout(() => {\r\n                  resolve('ok');\r\n              }, 4000);\r\n            }); */\r\n            return responseDian;\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      }\r\n    };\r\n  \r\n\r\n    (window as any).POS.sendInvoiceAPI = sendInvoiceAPI;\r\n  }\r\n\r\n})();","(()=>{\r\n\r\n    if(!document.querySelector('.parqueadero'))return;\r\n\r\n    const updateTarifa = document.querySelector('#updateTarifa') as HTMLInputElement;\r\n    const viewTarifa = document.querySelector('#viewTarifa') as HTMLInputElement;\r\n    const miDialogoUpdateTarifa = document.querySelector('#miDialogoUpdateTarifa') as HTMLDialogElement;\r\n    const miDialogoViewTarifa = document.querySelector('#miDialogoViewTarifa') as HTMLDialogElement;\r\n    const type_car = document.querySelector('#type_car') as HTMLSelectElement;\r\n    const tablaListaTarifas = document.querySelector('#tablaListaTarifas tbody') as HTMLBodyElement;\r\n\r\n    document.addEventListener(\"click\", cerrarDialogoExterno);\r\n\r\n    updateTarifa.addEventListener('click', ()=>miDialogoUpdateTarifa.showModal());\r\n    viewTarifa.addEventListener('click', ()=>{\r\n        miDialogoViewTarifa.showModal();\r\n        viewTarifas();\r\n    });\r\n\r\n    document.querySelector('#formTipoVehiculo')?.addEventListener('submit', async(e:Event)=>{\r\n        e.preventDefault();\r\n        \r\n        const datos = new FormData();\r\n        datos.append('id', type_car.value);\r\n        datos.append('nombre', type_car.selectedOptions[0].textContent??'');\r\n        datos.append('tarifa_hora', (document.querySelector('#tarifa_hora') as HTMLInputElement).value.replace(/\\./g, '').replace(',', '.'));\r\n        datos.append('tarifa_dia', (document.querySelector('#tarifa_dia') as HTMLInputElement).value.replace(/\\./g, '').replace(',', '.'));\r\n        try {\r\n            const url = \"/admin/api/parqueadero/createUpdateTarifa\"; //llama a la api que esta en parqueaderocontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n\r\n            if(resultado.exito != undefined){\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                \r\n            }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n            miDialogoUpdateTarifa.close();\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    });\r\n\r\n\r\n    async function viewTarifas():Promise<void> {\r\n        try {\r\n            const url = `/admin/api/parqueadero/allTarifas`; //llamado a la API REST parqueaderocontrolador, detalle tarifas\r\n            const respuesta = await fetch(url); \r\n            const resultado = await respuesta.json();\r\n            detalleTarifas(resultado);\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    function detalleTarifas(resultado:{id:string, nombre:string, tarifa_hora:string, tarifa_dia:string, estado:string}[]){\r\n        while(tablaListaTarifas.firstChild)tablaListaTarifas.removeChild(tablaListaTarifas.firstChild);\r\n        resultado.forEach(tarifa=>{\r\n          const tr = document.createElement('tr') as HTMLTableRowElement;\r\n          //tr.classList.add('productselect');\r\n          tr.innerHTML = `<td class=\"text-center\">${tarifa.nombre}</td>\r\n                          <td class=\"text-center\">$${Number(tarifa.tarifa_hora).toLocaleString()}</td>\r\n                          <td class=\"text-center\">$${Number(tarifa.tarifa_dia).toLocaleString()}</td>`;\r\n          tablaListaTarifas.prepend(tr);\r\n        });\r\n    }\r\n\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n        const f = event.target;\r\n        if (f=== miDialogoUpdateTarifa || f === miDialogoViewTarifa || (f as HTMLInputElement).value === 'salir' || (f as HTMLInputElement).value === 'Cancelar' || (f as HTMLElement).id == 'btnXCerrarModalViewTarifa' || (f as HTMLElement).id == 'btnXCerrarModalDetalleComision') {\r\n            miDialogoUpdateTarifa.close();\r\n            miDialogoViewTarifa.close();\r\n        }\r\n    }\r\n\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.modorapido')){\r\n\r\n        const POS = (window as any).POS;\r\n\r\n        interface Item {\r\n            id_impuesto: number,\r\n            facturaid: number,\r\n            basegravable: number,\r\n            valorimpuesto: number\r\n        }\r\n\r\n\r\n        const selectCliente = POS.gestionClientes.selectCliente;\r\n        const dirEntrega = POS.gestionClientes.dirEntrega;\r\n        const btnCaja = document.querySelector('#caja') as HTMLSelectElement; //select de la caja en el modal pagar\r\n        const btnTipoFacturador = document.querySelector('#facturador') as HTMLSelectElement; //select del consecutivo o facturador en el modal de pago\r\n        const btnfacturar = document.querySelector('#btnfacturar');\r\n        const btnguardar = document.querySelector('#btnguardar');\r\n        const btnPagar = document.getElementById('btnPagar') as HTMLInputElement;\r\n        const miDialogoAddCliente = POS.gestionClientes.miDialogoAddCliente;\r\n        const miDialogoGuardar = document.querySelector('#miDialogoGuardar') as any;\r\n        const miDialogoFacturarA = POS.gestionarAdquiriente.miDialogoFacturarA;\r\n        const miDialogoFacturar = document.querySelector('#miDialogoFacturar') as any;\r\n        const totalUnidades = document.querySelector('#totalUnidades') as HTMLSpanElement;\r\n        const tablaMR = document.getElementById('tablaVenta') as HTMLBodyElement;\r\n\r\n        let factimpuestos:Item[] = [];\r\n        let carrito:CarritoItem[]=[];\r\n        let allproducts:productsapi[] = [];\r\n        let filteredData: {id:string, text:string, tipo:string, tipoproducto:string, tipoproduccion:string, sku:string, unidadmedida:string, precio:string}[];   //tipoproducto = 0 es producto simple,  1 = compuesto,  si no viene es subproducto, tipo=0 es producto(simple o compuesto), tipo=1 es subproducto\r\n        const valorTotal = {porcentgananciauser: 0, valorgananciauser: 0, subtotal: 0, base: 0, valorimpuestototal: 0, dctox100: 0, descuento: 0, idtarifa: 0, valortarifa: 0, total: 0}; //datos global de la venta\r\n        let tarifas:{id:string, idcliente:string, nombre:string, valor:string}[] = [];\r\n        //const dataCredit = {capital:0, abonoinicial:0, saldopendiente:0, cantidadcuotas:0, interes:'0', interestotal:0, valorinterestotal:0, montototal:0, descuentocredito: 0};\r\n\r\n        const constImp: {[key:string]: number} = {};\r\n        constImp['excluido'] = 0;\r\n        constImp['0'] = 0;  //exento de iva, tarifa 0%\r\n        constImp['5'] = 0.0476190476190476; //iva, tarifa al 5%,  Bienes/servicios al 5\r\n        constImp['8'] = 0.0740740740740741; //inc, tarifa al 8%,  impuesto nacional al consumo\r\n        constImp['16'] = 0.1379310344827586; //iva, tarifa al 16%,  contratos firmados con el estado antes de ley 1819\r\n        constImp['19'] = 0.1596638655462185; //iva, tarifa al 19%,  tarifa general\r\n\r\n        let  tipoventa:string=\"Contado\";\r\n        const mapMediospago = new Map();\r\n\r\n        const mediosPagoDBMAP = new Map<string, string>(  //se usa para imprimir los medios de pago en el servidor de impresion\r\n            mediosPagoDB.map(m => [m.id, m.mediopago]) //mediosPagoDB se declara en app.ts el cual viene del <script> en index.php que convierte el array de medios de pago de php a js.\r\n        );\r\n\r\n        POS.gestionClientes.clientes();  //inicializa modulo de clientes\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/allproducts\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas los productos simples y compuestos\r\n                const respuesta = await fetch(url);\r\n                const resultado:productsapi[] = await respuesta.json();\r\n                filteredData = resultado.filter(x=>x.habilitarventa=='1'&&x.visible=='1').map(item => ({ id: item.id, text: item.nombre, tipo:item.tipoproducto??'1', tipoproducto: item.tipoproducto, tipoproduccion: item.tipoproduccion, sku: item.sku, unidadmedida: item.unidadmedida, precio:item.precio_venta }));\r\n                activarselect2();\r\n                allproducts = resultado.filter(x=>x.habilitarventa=='1'&&x.visible=='1');\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n        activarselect2();\r\n        function activarselect2(){\r\n            ($('#articulo') as any).select2({ \r\n                width: '100%',\r\n                data: filteredData,\r\n                placeholder: \"Buscar producto...\",\r\n                maximumSelectionLength: 1,\r\n            });  \r\n        }\r\n\r\n\r\n        let barcode = \"\";\r\n        let lastKeyTime = Date.now();\r\n        window.addEventListener('keydown', (e: KeyboardEvent) => {\r\n            let estado = true;\r\n            const currentTime = Date.now();\r\n            const target = e.target as HTMLElement;\r\n            const cobrar:boolean = miDialogoFacturar?.open;\r\n\r\n            if (e.key === 'Control')(document.querySelector('#articulo') as HTMLSelectElement).focus();\r\n            if (e.key === 'F8')(document.querySelector('#facturarA') as HTMLButtonElement).click();\r\n\r\n            // 1. FILTRO DE ENTRADA mejorado\r\n            // Si el foco está en un input que NO sea el de búsqueda de Select2, ignoramos.\r\n            // El buscador de Select2 suele tener la clase 'select2-search__field'\r\n            const isSelect2Input = $(target).hasClass('select2-search__field');\r\n            const isBody = target.tagName === 'BODY';\r\n            const isButton = target.tagName === 'BUTTON' || $(target).hasClass('btn');\r\n\r\n            // Si está escribiendo en un input normal (ej: Notas) y NO es el de Select2, salimos\r\n            if (!isSelect2Input && !isBody && !isButton && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA')) {\r\n                if (currentTime - lastKeyTime < 43 && e.key === 'Enter'){\r\n                    e.preventDefault();\r\n                    if(target.classList.contains('inputcantidad')){\r\n                        const inputcantidad = (target as HTMLInputElement);\r\n                        inputcantidad.value = '1';\r\n                        inputcantidad.dispatchEvent(new Event('input', { bubbles: true }));\r\n                    }\r\n                    return;\r\n                }\r\n                if(target.classList.contains('inputcantidad')&& e.key === 'Enter'){\r\n                    e.preventDefault();\r\n                    btnfacturar?.dispatchEvent( new Event('click'));\r\n                }\r\n            }\r\n\r\n            // 2. LÓGICA DE VELOCIDAD\r\n            if (currentTime - lastKeyTime > 43)barcode = \"\"; \r\n            lastKeyTime = currentTime;\r\n\r\n            // 3. CAPTURA DEL ENTER\r\n            if (e.key === 'Enter') {\r\n                if (barcode.length >= 3) {\r\n                    e.preventDefault();\r\n                    e.stopImmediatePropagation(); // <--- CRITICO: Detiene a Select2 y a cualquier botón\r\n                    searchBarCode(barcode);\r\n                    barcode = \"\";\r\n                    return false;\r\n                }\r\n                if(cobrar){\r\n                    e.preventDefault();\r\n                    btnPagar.click();\r\n                }\r\n                barcode = \"\";\r\n            } else {\r\n                // 4. ACUMULACIÓN\r\n                barcode += e.key;\r\n            }\r\n        }, true); // <--- El \"true\" activa el modo CAPTURA\r\n\r\n\r\n        function searchBarCode(barcode:string){\r\n            const itemselected = allproducts.find(x=>x.sku==barcode);\r\n            if(itemselected != undefined){\r\n                const productoConfigurado = structuredClone(itemselected);\r\n                filtrarInsumos(productoConfigurado);\r\n                agregarProducto(itemselected.id, Number(itemselected.precio_venta), productoConfigurado);\r\n            }\r\n        }\r\n\r\n        ////// EVENTO AL SELECT ARTICULOS O ITEMS PARA SELECCIONAR EL ITEM Y AÑADIR AL CARRITO ////// \r\n        $(\"#articulo\").on('change', (e)=>{\r\n            let datos = ($('#articulo') as any).select2('data')[0];\r\n            if(datos){\r\n                const itemselected = allproducts.find(x=>x.id == datos.id)!\r\n                const productoConfigurado = structuredClone(itemselected);\r\n                filtrarInsumos(productoConfigurado);\r\n                agregarProducto(datos.id, datos.precio, productoConfigurado);\r\n                $(\"#articulo\").val('null').trigger('change');\r\n            }\r\n        });\r\n\r\n\r\n        function agregarProducto(id:string, precio:number = 0, productoConfigurado:productsapi|null) {\r\n            const index = carrito.findIndex(x=>x.idproducto==id && x.valorunidad == precio && mismaConfiguracion(x, productoConfigurado!));\r\n\r\n            if(index == -1){  //si el item seleccionado no existe en el carrito, agregarlo.\r\n                //const itemselected = allproducts.find(x=>x.id==id)!;\r\n                const productototal = Number(productoConfigurado?.precio_venta);\r\n                const productovalorimp = productototal*constImp[productoConfigurado?.impuesto??'0']; //si producto.impuesto es null toma el valor de cero\r\n                \r\n                //varia segun la prioridad de la comision\r\n                if(productoConfigurado?.prioridadcomision === '0')  //si el porcentaje es por usuario\r\n                    productoConfigurado.percentcomision = Number(percentComisionUser);\r\n                const valorcomision:number = (productototal*productoConfigurado?.percentcomision!)/100;  \r\n\r\n                const item:CarritoItem = {\r\n                    id: '',\r\n                    idproducto: productoConfigurado?.id!,\r\n                    tipoproducto: productoConfigurado?.tipoproducto!,\r\n                    tipoproduccion: productoConfigurado?.tipoproduccion!,\r\n                    idcategoria: productoConfigurado?.idcategoria!,\r\n                    nombreproducto: productoConfigurado?.nombre!,\r\n                    rendimientoestandar: productoConfigurado?.rendimientoestandar!,\r\n                    foto: productoConfigurado?.foto!,\r\n                    costo: productoConfigurado?.precio_compra!,\r\n                    valorunidad: Number(productoConfigurado?.precio_venta),\r\n                    cantidad: 1,\r\n                    stock: 1,\r\n                    promediostock: Number(productoConfigurado?.promediostock),\r\n                    prioridadcomision: productoConfigurado?.prioridadcomision!,\r\n                    percentcomision: productoConfigurado?.percentcomision!,\r\n                    valorcomision: valorcomision,\r\n                    subtotal: productototal, //este es el subtotal del producto\r\n                    base: productototal-productovalorimp,\r\n                    impuesto: productoConfigurado?.impuesto!, //porcentaje de impuesto, es null si es excluido de iva\r\n                    valorimp: productovalorimp,\r\n                    descuento: 0,\r\n                    total: productototal, //valorunidad x cantidad\r\n                    insumos: productoConfigurado?.insumos??[]\r\n                }\r\n                carrito = [...carrito, item];\r\n            }else{ //sumar cantidad cuando el item ya existe \r\n                sumarcantidad(carrito[index], carrito[index].cantidad+1);\r\n            }\r\n            \r\n            printCarrito();\r\n            valorCarritoTotal();\r\n        }\r\n        \r\n\r\n        function mismaConfiguracion(productCarrito: any, producto2: productsapi):boolean {\r\n            const mapaProduct2 = new Map(producto2.insumos.map((ins:any) => [ins.id_subproducto, ins]));\r\n            // Deben ser el mismo producto\r\n            if(productCarrito.idproducto !== producto2.id)return false;\r\n\r\n            // Deben tener la misma cantidad de insumos\r\n            if(productCarrito.insumos.length !== producto2.insumos.length)return false;\r\n\r\n            for (const insumo1 of productCarrito.insumos) {\r\n                //const insumo2 = producto2.insumos.find((x:any) => x.id_subproducto == insumo1.id_subproducto);\r\n                const insumo2:any = mapaProduct2.get(insumo1.id_subproducto);\r\n                if (!insumo2)return false;\r\n                // Comparar selección\r\n                if (Number(insumo1.seleccionado) !== Number(insumo2.seleccionado))\r\n                    return false;\r\n                // Comparar cantidad\r\n                if (Number(insumo1.cantidadsubproducto) !== Number(insumo2.cantidadsubproducto))\r\n                    return false;\r\n            }\r\n            return true;\r\n        }\r\n\r\n\r\n        tablaMR?.addEventListener('input', e=>{\r\n            const input = e.target as HTMLInputElement;\r\n            if (!input.classList.contains('inputcantidad')) return;\r\n            const fila = input?.closest('.productselect') as HTMLTableRowElement;\r\n            const indexcarrito = fila.dataset.indexcarrito!;\r\n            const productoCarrito = carrito[Number(indexcarrito)];\r\n            \r\n            if(productoCarrito==undefined)return;\r\n                \r\n            let val = input.value;\r\n            val = val.replace(/[^0-9.]/g, '');\r\n            const partes = val.split('.');\r\n            if(partes.length > 2)val = partes[0]+'.'+partes.slice(1).join('');\r\n            if (val.startsWith('.'))val = '1';\r\n            if (val === '' || isNaN(parseFloat(val))) val = '';\r\n\r\n            input.value = val;\r\n            let cantidad = Number(val);\r\n            \r\n            if(cantidad <= 0){\r\n                cantidad = 0;\r\n                productoCarrito.total = 0;\r\n                //carrito = carrito.filter(x=>x.iditem != id);\r\n            }\r\n            fila.children[3].textContent = '$'+(productoCarrito.valorunidad*cantidad).toLocaleString();\r\n            sumarcantidad(productoCarrito, cantidad);\r\n            valorCarritoTotal();\r\n        });\r\n\r\n        function sumarcantidad(productoCarrito:CarritoItem, cantidad:number){\r\n            productoCarrito.cantidad = cantidad;\r\n            productoCarrito.stock = cantidad;\r\n            productoCarrito.subtotal = (productoCarrito.valorunidad)*productoCarrito.cantidad;\r\n            productoCarrito.total = productoCarrito.subtotal;\r\n            productoCarrito.valorcomision = (productoCarrito.subtotal*productoCarrito.percentcomision)/100;\r\n            //calculo del impuesto y base por producto en el carrito deventas\r\n            productoCarrito.valorimp = parseFloat((productoCarrito.total*constImp[productoCarrito.impuesto??0]).toFixed(3));\r\n            productoCarrito.base = parseFloat((productoCarrito.total-productoCarrito.valorimp).toFixed(3));\r\n        }\r\n\r\n\r\n        ////// EVENTO POR TECLADO DE LA TABLA MODO RAPIDO DE ITEMS SELECCIONADOS\r\n        tablaMR.addEventListener('keydown', (e: KeyboardEvent) => {\r\n            const target = e.target as HTMLElement;\r\n            if (target.classList.contains('inputcantidad')) { //Delegation al inputcantidad de la tabla\r\n                const input = target as HTMLInputElement;\r\n                if (e.key === 'ArrowUp') {\r\n                    e.preventDefault();\r\n                    input.value = String((Number(input.value) || 0) + 1);\r\n                    beep(900);\r\n                    flashCantidad(input, 'up');\r\n                    input.dispatchEvent(new Event('input', { bubbles: true })); // 🔥 reutiliza lógica\r\n                }\r\n\r\n                if (e.key === 'ArrowDown') {\r\n                    e.preventDefault();\r\n                    input.value = String(Math.max(0, (Number(input.value) || 0) - 1));\r\n                    beep(500);\r\n                    flashCantidad(input, 'down');\r\n                    input.dispatchEvent(new Event('input', { bubbles: true })); // 🔥 reutiliza lógica\r\n                }\r\n            }\r\n        });\r\n\r\n\r\n        document.querySelector('#btnScanner')?.addEventListener('click', ()=>\r\n            (document.querySelector('#articulo') as HTMLSelectElement).focus()\r\n        );\r\n\r\n\r\n        /////////////////////// evento a la tabla de productos de venta (carrito) //////////////////////////\r\n        tablaMR?.addEventListener('click', (e:Event)=>{\r\n            if((e.target as HTMLElement).classList.contains('eliminarProducto') || (e.target as HTMLElement).tagName == \"I\"){\r\n                const elementProduct = (e.target as HTMLElement)?.closest('.productselect');\r\n                const indexcarrito = Number((elementProduct as HTMLElement).dataset.indexcarrito!);\r\n                carrito.splice(indexcarrito, 1);\r\n                printCarrito();\r\n                valorCarritoTotal();\r\n            }\r\n        });\r\n\r\n\r\n        function printCarrito(){\r\n            while(tablaMR.firstChild)tablaMR.removeChild(tablaMR.firstChild);\r\n            carrito.forEach((item, i)=>{\r\n                const tr = document.createElement('tr') as HTMLTableRowElement;\r\n                tr.classList.add('productselect');\r\n                tr.dataset.indexcarrito = i+'';\r\n                tr.innerHTML = `<td class=\"py-2 pl-4\">${item.nombreproducto}</td>\r\n                                <td class=\"py-2 text-center cursor-pointer cantidad\"><input type=\"text\" class=\"inputcantidad w-20 p-2 text-center\" value=\"${item.cantidad}\"></td>\r\n                                <td class=\"py-2 text-right\">$${item.valorunidad.toLocaleString()}</td>\r\n                                <td class=\"py-2 text-right totalFila\">$${item.total.toLocaleString()}</td>\r\n                                <td class=\"text-center\"><div class=\"btn-xs btn-red eliminarProducto\"><i class=\"fa-solid fa-trash-can\"></i></div></td>`;\r\n                tablaMR.prepend(tr);\r\n            });\r\n        }\r\n\r\n        function printTarifaEnvio():void{\r\n            tarifas = POS.tarifas;\r\n            const selectDir = dirEntrega.options[dirEntrega.selectedIndex];\r\n        \r\n        }\r\n        \r\n        ////////////////////// valores finales subtotal y total ////////////////////////\r\n        function valorCarritoTotal(){\r\n            valorTotal.valorgananciauser = 0;\r\n            //calcular el impuesto discriminado por tarifa\r\n            const idimpuesto: Record<string, number> = {'0': 1, '5': 2, '16': 3, '19': 4, 'excluido': 5, '8': 6 };\r\n            const objbase:{'0':number, '5':number, '16':number, '19':number, 'excluido':number, '8':number} = {'0': 0, '5': 0, '16': 0, '19': 0, 'excluido':0, '8': 0};\r\n\r\n            const mapImpuesto = new Map();\r\n            carrito.forEach(x=>{\r\n                if(x.impuesto){\r\n                if(mapImpuesto.has(x.impuesto)){\r\n                    const valor = mapImpuesto.get(x.impuesto) + x.total*constImp[x.impuesto];\r\n                    mapImpuesto.set(x.impuesto, valor);\r\n                }else{\r\n                    mapImpuesto.set(x.impuesto, x.total*constImp[x.impuesto]);\r\n                }\r\n                }\r\n                if(x.impuesto == null)x.impuesto = \"excluido\";\r\n                objbase[x.impuesto as keyof typeof objbase] += x.base;\r\n                const impValor = mapImpuesto.get(x.impuesto)??0;\r\n                const index = factimpuestos.findIndex(Obj=>Obj.id_impuesto == idimpuesto[x.impuesto]);\r\n                if(index!=-1){ //si existe remplazar obj\r\n                    factimpuestos[index] = {id_impuesto:idimpuesto[x.impuesto], facturaid:0, basegravable:objbase[x.impuesto as keyof typeof objbase], valorimpuesto: impValor};\r\n                }else{\r\n                    factimpuestos = [...factimpuestos, {id_impuesto:idimpuesto[x.impuesto], facturaid:0, basegravable:objbase[x.impuesto as keyof typeof objbase], valorimpuesto: impValor}];\r\n                }\r\n\r\n                //calcular valor total de comision para el usuario\r\n                valorTotal.valorgananciauser += x.valorcomision;\r\n            });\r\n            \r\n            //Valor del impuesto total de todos los productos, es decir de la factura;\r\n            let valorTotalImp:number = 0;\r\n            for(let valorImp of mapImpuesto.values())valorTotalImp += valorImp;\r\n            valorTotal.valorimpuestototal = parseFloat(valorTotalImp.toFixed(3));  //valor del impuesto total factura de todos los productos\r\n            valorTotal.subtotal = carrito.reduce((total, x)=>x.total+total, 0);\r\n            valorTotal.porcentgananciauser =  (100*valorTotal.valorgananciauser)/valorTotal.subtotal;\r\n            valorTotal.base = valorTotal.subtotal - valorTotal.valorimpuestototal;  //valor de la base total factura de todos los productos\r\n            valorTotal.total = valorTotal.subtotal + valorTotal.valortarifa - valorTotal.descuento;\r\n            document.querySelector('#subTotal')!.textContent = '$'+valorTotal.subtotal.toLocaleString();\r\n            (document.querySelector('#impuesto') as HTMLElement).textContent = '$'+valorTotalImp.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n            //(document.querySelector('#valorTarifa') as HTMLElement).textContent = '$'+valorTotal.valortarifa.toLocaleString();\r\n            document.querySelector('#total')!.textContent = '$ '+valorTotal.total.toLocaleString();\r\n            // cantidad total de productos\r\n            totalUnidades.textContent = carrito.reduce((total, producto)=>producto.cantidad+total, 0)+'';\r\n\r\n            POS.carrito = carrito;\r\n        }\r\n\r\n\r\n        btnguardar?.addEventListener('click', ()=>{if(carrito.length)miDialogoGuardar.showModal();});\r\n        btnfacturar?.addEventListener('click', ()=>{\r\n            if(carrito.length){\r\n                document.querySelector('.Efectivo')?.setAttribute('readonly', 'true');\r\n                document.querySelector('#inputscreditos')?.classList.add('hidden');\r\n                document.querySelector('#inputscreditos')?.classList.remove('flex');\r\n                tipoventa = \"Contado\";\r\n                POS.tipoventa = tipoventa;\r\n                POS.gestionSubirModalPagar.subirModalPagar();\r\n                (document.querySelector('#formfacturar #first') as HTMLInputElement).checked = true;\r\n                miDialogoFacturar.showModal();\r\n            }\r\n        });\r\n\r\n\r\n        ////////////////// evento al bton pagar del modal facturar //////////////////////\r\n        document.querySelector('#formfacturar')?.addEventListener('submit', e=>{\r\n            e.preventDefault();\r\n            if(valorTotal.total <0 || valorTotal.subtotal <0){\r\n                msjAlert('error', 'No se puede procesar pago con $0', (document.querySelector('#divmsjalertaprocesarpago') as HTMLElement));\r\n                return;\r\n            }\r\n\r\n            //calcular si el totoal de los medios de pago es menor al abono inicial, abortar pago...\r\n            let totalMediosPago:number = 0;\r\n            for(let value of mapMediospago.values())totalMediosPago+=value;\r\n            if(totalMediosPago<POS.gestionSubirModalPagar.valoresCredito.abonoinicial){\r\n                POS.gestionSubirModalPagar.mostrarMensajeMetodosPago?.();\r\n                return;\r\n            }\r\n        \r\n            btnPagar.disabled = true;\r\n            btnPagar.value = 'Procesando...';\r\n            procesarpedido('Paga', '0');\r\n        });\r\n\r\n        async function procesarpedido(estado:string, ctz:string){\r\n            const imprimir = document.querySelector('input[name=\"imprimir\"]:checked') as HTMLInputElement;\r\n            const valoresCredito = POS.gestionSubirModalPagar.valoresCredito;\r\n            const datos = new FormData();\r\n            //datos.append('id', datosfactura?.id??'');\r\n            datos.append('idemisor', btnCaja.selectedOptions[0].dataset.idemisor??'');\r\n            datos.append('idcliente', (document.querySelector('#selectCliente') as HTMLSelectElement).value || '1');\r\n            datos.append('idvendedor', (document.querySelector('#vendedor') as HTMLParagraphElement).dataset.idvendedor!);\r\n            datos.append('idcaja', btnCaja.value);\r\n            datos.append('idconsecutivo', btnTipoFacturador.value);\r\n            datos.append('iddireccion', dirEntrega.value);\r\n            datos.append('idtarifazona', valorTotal.idtarifa+'');\r\n            datos.append('idcanaldeventa', (document.querySelector('#canalVenta') as HTMLSelectElement)?.value??'1');\r\n            datos.append('cliente', selectCliente.value==''?'N/A':selectCliente.options[selectCliente.selectedIndex].textContent!);\r\n            datos.append('vendedor', (document.querySelector('#vendedor') as HTMLParagraphElement).textContent!);\r\n            datos.append('caja', (document.querySelector('#caja option:checked') as HTMLSelectElement).textContent!);\r\n            datos.append('tipofacturador', btnTipoFacturador.options[btnTipoFacturador.selectedIndex].textContent!);\r\n            datos.append('direccion', dirEntrega.options[dirEntrega.selectedIndex]?.text??'');\r\n            //datos.append('tarifazona', nombretarifa||'');\r\n            datos.append('carrito', JSON.stringify(carrito.filter(x=>x.cantidad>0)));  //envio de todos los productos con sus cantidades\r\n            datos.append('totalunidades', totalUnidades.textContent!);\r\n            datos.append('mediosPago', JSON.stringify(Array.from(mapMediospago, ([idmediopago, valor])=>({idmediopago, id_factura:0, valor}))));\r\n            datos.append('factimpuestos', JSON.stringify(factimpuestos));\r\n            datos.append('recibido', document.querySelector<HTMLInputElement>('#recibio')!.value);\r\n            datos.append('transaccion', '');\r\n            datos.append('tipoventa', tipoventa);\r\n            datos.append('valoresCredito', JSON.stringify(valoresCredito));\r\n            datos.append('cotizacion', ctz);  //1= cotizacion, 0 = no cotizacion pagada.\r\n            datos.append('remision', estado=='Remision'?'1':'0');\r\n            datos.append('estado', estado);\r\n            datos.append('porcentgananciauser', valorTotal.porcentgananciauser.toFixed(2));\r\n            datos.append('valorgananciauser', valorTotal.valorgananciauser.toFixed(2));\r\n            datos.append('subtotal', valorTotal.subtotal+'');\r\n            datos.append('base', valorTotal.base.toFixed(3));\r\n            datos.append('valorimpuestototal', valorTotal.valorimpuestototal+''); //valor total del impuesto. \r\n            datos.append('dctox100',valorTotal.dctox100+'');\r\n            datos.append('descuento',valorTotal.descuento+'');\r\n            datos.append('total', valorTotal.total.toString());\r\n            datos.append('observacion', document.querySelector<HTMLTextAreaElement>('#observacion')!.value);\r\n            datos.append('departamento', '');\r\n            //datos.append('ciudad', (document.querySelector('#ciudad') as HTMLInputElement).value);\r\n            datos.append('entrega', 'Presencial');\r\n            datos.append('entregado', estado=='Paga'?'1':'0'); //si es remision no se ha entregado, si es pago y entrega a domicilio se define segun el checkbox de despachar, si es pago y entrega presencial se marca como entregado\r\n            datos.append('valortarifa', valorTotal.valortarifa+'');\r\n            datos.append('datosAdquiriente', JSON.stringify(POS.gestionarAdquiriente.datosAdquiriente));\r\n            datos.append('opc1', '');\r\n            datos.append('opc2', '');\r\n            try {\r\n                const url = \"/admin/api/facturarModorapido\";  //va al controlador ventascontrolador\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                const resultado = await respuesta.json();\r\n                console.log(resultado);\r\n\r\n                if(resultado.exito !== undefined){\r\n                    msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                    btnPagar.disabled = false;\r\n                    btnPagar.value = 'Pagar';\r\n                    miDialogoFacturar.close();\r\n\r\n                    if(estado == \"Paga\"){\r\n                        resultado.dataInvoice.items = carrito.filter(x=>x.cantidad>0);\r\n                        resultado.dataInvoice.mediospago = Array.from(mapMediospago, ([idmediopago, valor])=>({\r\n                            idmediopago,\r\n                            mediopago: mediosPagoDBMAP.get(idmediopago),\r\n                            valor,\r\n                        }));\r\n                \r\n                        //ENVIAR FACTURA A DIAN SI ES FACTURACION ELECTRONICA\r\n                        if(btnTipoFacturador.options[btnTipoFacturador.selectedIndex].dataset.idtipofacturador == '1'){\r\n                            const resDian = await POS.sendInvoiceAPI.sendInvoice(resultado.idfactura);\r\n                            POS.gestionarAdquiriente.datosAdquiriente = {}; //reiniciar datos de adquiriente cada vez que se facture electronicamente\r\n                            resultado.dataInvoice.cufe = resDian.cufe;\r\n                            resultado.dataInvoice.link = resDian.link;\r\n                            console.log(resDian);\r\n                        }\r\n                        //IMPRIMIR TICKET POS\r\n                        if(resultado.idfactura && imprimir.value === '1')printTicketPOS(resultado.idfactura, resultado.dataInvoice);\r\n                    }\r\n                    vaciarventa();\r\n                }else{\r\n                    btnPagar.disabled = false;\r\n                    btnPagar.value = 'Pagar';\r\n                    const mensajeError = resultado.error?.[0]??'No fue posible procesar la solicitud';\r\n                    msjalertToast('error', '¡Error!', mensajeError);\r\n                }\r\n            } catch (error) {\r\n                console.log(error);\r\n                btnPagar.disabled = false;\r\n                btnPagar.value = 'Pagar';\r\n                msjalertToast('error', '¡Error!', 'No fue posible comunicarse con el servidor');\r\n            }\r\n        }\r\n\r\n\r\n        async function printTicketPOS(idfactura:string, datainvoice:DataInvoice){\r\n            try {\r\n                const url = \"http://localhost:3100/api/printPOS/ticket1/CAJA\"; //llamado a la API server print nodejs/ts\r\n                const respuesta = await fetch(url, {\r\n                method: 'POST',\r\n                headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                body: JSON.stringify(datainvoice)\r\n                });\r\n                const resultado = await respuesta.json();\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n\r\n            setTimeout(() => {\r\n                window.open(\"/admin/printPDFPOS?id=\" + idfactura, \"_blank\");\r\n            }, 1000);\r\n        }\r\n\r\n\r\n        function vaciarventa():void\r\n        {\r\n            //if(datosfactura?.id)datosfactura.id = '';\r\n            (document.querySelector('#formFacturarA') as HTMLFormElement)?.reset();\r\n            (document.querySelector('#formfacturar') as HTMLFormElement)?.reset();\r\n            (document.querySelector('#formAddCliente') as HTMLFormElement).reset();\r\n            (document.querySelector('#badgeEstado') as HTMLParagraphElement).textContent = 'SIN CLIENTE';\r\n            (document.querySelector('#badgeEstado') as HTMLParagraphElement).classList.remove('bg-green-100', 'text-green-600');\r\n            (document.querySelector('#badgeEstado') as HTMLParagraphElement).classList.add('bg-gray-100', 'text-gray-700');\r\n            (document.querySelector('#resumenCliente') as HTMLParagraphElement).textContent = \"Seleccionar cliente\";\r\n            mapMediospago.clear();\r\n            $('.mediopago').val(0);\r\n            carrito.length = 0;\r\n            factimpuestos.length = 0;\r\n\r\n            history.replaceState({}, \"\", \"/admin/ventas/modorapido\");  //modificar la URL sin recargar la página.\r\n            while(tablaMR?.firstChild)tablaMR.removeChild(tablaMR?.firstChild);\r\n            //(document.querySelector('#npedido') as HTMLInputElement).value = '';\r\n            document.querySelector('#subTotal')!.textContent = '$'+0;\r\n            document.querySelector('#impuesto')!.textContent = '$'+0;\r\n            //(document.querySelector('#descuento') as HTMLElement).textContent = '$'+0;\r\n            totalUnidades.textContent = '0';\r\n            document.querySelector('#total')!.textContent = '$'+0;\r\n            //$('#selectCliente').val('').trigger('change');   //aqui tambien se reinicia la elemento del valor de la tarifa\r\n            for(const key in valorTotal)valorTotal[key as keyof typeof valorTotal] = 0; //reiniciar objeto\r\n        }\r\n\r\n\r\n        function cerrarDialogoExterno(event:Event) {\r\n            const f = event.target;\r\n            if (f=== miDialogoAddCliente || f=== miDialogoFacturarA || f === miDialogoGuardar || f === miDialogoFacturar || (f as HTMLInputElement).value === 'Cancelar' || (f as HTMLInputElement).closest('.salir') || (f as HTMLInputElement).closest('.cotizacion') || (f as HTMLInputElement).closest('.remision')) {\r\n                miDialogoFacturarA.close();\r\n                miDialogoFacturar.close();\r\n                miDialogoAddCliente.close();\r\n                miDialogoGuardar.close();\r\n                console.log(1);\r\n                if((f as HTMLInputElement).closest('.cotizacion')){\r\n                    console.log(3);\r\n                    tipoventa = \"\";\r\n                    procesarpedido('Guardado', '1');\r\n                }\r\n                if((f as HTMLInputElement).closest('.remision')){\r\n                    tipoventa = \"\";\r\n                    procesarpedido('Remision', '0');\r\n                }\r\n            }\r\n        }\r\n\r\n\r\n        POS.valorCarritoTotal = valorCarritoTotal;\r\n        POS.valorTotal = valorTotal;\r\n        POS.mapMediospago = mapMediospago;\r\n        POS.tarifas = tarifas;\r\n        POS.printTarifaEnvio = printTarifaEnvio;\r\n\r\n    }\r\n\r\n})();\r\n","(()=>{\r\n\r\n    if(\r\n        !document.querySelector('.ventasgenerales') &&\r\n        !document.querySelector('.reporteEmisores') &&\r\n        !document.querySelector('.remisiones') &&\r\n        !document.querySelector('.cuotasCreditos') &&\r\n        !document.querySelector('.movimientosinventarios') &&\r\n        !document.querySelector('.estadosfinancierosCreditos') &&\r\n        !document.querySelector('.estadosfinancierosCreditos') &&\r\n        !document.querySelector('.recibosCaja'))return;\r\n\r\n     const POS = (window as any).POS;\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\";\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    const esReporteCuotas = Boolean(document.querySelector('.cuotasCreditos'));\r\n    const esReporteVentasGenerales = Boolean(document.querySelector('.ventasgenerales'));\r\n    const usaCalendarioModerno = esReporteCuotas || esReporteVentasGenerales;\r\n    const dateRangeInput = ($('input[name=\"datetimes\"]') as any);\r\n\r\n    function resaltarBotonConsultar(){\r\n      if(!usaCalendarioModerno || !consultarFechaPersonalizada)return;\r\n\r\n      consultarFechaPersonalizada.classList.remove('report-cuotas__filter-button--attention', 'ventas-generales__filter-btn--attention');\r\n      void consultarFechaPersonalizada.offsetWidth;\r\n      consultarFechaPersonalizada.classList.add(esReporteVentasGenerales ? 'ventas-generales__filter-btn--attention' : 'report-cuotas__filter-button--attention');\r\n      consultarFechaPersonalizada.scrollIntoView({ behavior: 'smooth', block: 'center' });\r\n\r\n      setTimeout(()=>{\r\n        consultarFechaPersonalizada.classList.remove('report-cuotas__filter-button--attention', 'ventas-generales__filter-btn--attention');\r\n      }, 2400);\r\n    }\r\n\r\n    dateRangeInput.daterangepicker({\r\n      timePicker: true,\r\n      autoUpdateInput: !usaCalendarioModerno,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A',\r\n        applyLabel: 'Aplicar',\r\n        cancelLabel: 'Cancelar',\r\n        daysOfWeek: ['Do', 'Lu', 'Ma', 'Mi', 'Ju', 'Vi', 'Sa'],\r\n        monthNames: [\r\n          'Enero',\r\n          'Febrero',\r\n          'Marzo',\r\n          'Abril',\r\n          'Mayo',\r\n          'Junio',\r\n          'Julio',\r\n          'Agosto',\r\n          'Septiembre',\r\n          'Octubre',\r\n          'Noviembre',\r\n          'Diciembre'\r\n        ]\r\n      }\r\n    });\r\n\r\n    dateRangeInput.on('show.daterangepicker', function(ev: Event, picker: any) {\r\n      if(esReporteCuotas){\r\n        picker.container.addClass('report-cuotas__calendar');\r\n      }\r\n      if(esReporteVentasGenerales){\r\n        picker.container.addClass('ventas-generales__calendar');\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        if(usaCalendarioModerno){\r\n          ($(this) as any).val(`${picker.startDate.format('DD/MM/YYYY hh:mm A')} - ${picker.endDate.format('DD/MM/YYYY hh:mm A')}`);\r\n          resaltarBotonConsultar();\r\n        }\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('cancel.daterangepicker', function() {\r\n      if(usaCalendarioModerno){\r\n        ($(this) as any).val('');\r\n        fechainicio = '';\r\n        fechafin = '';\r\n      }\r\n    });\r\n\r\n    btnmesactual?.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer dÃ­a del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Ãšltimo dÃ­a del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        POS.callApiReporte(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior?.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer dÃ­a del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Ãšltimo dÃ­a del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        POS.callApiReporte(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy?.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia).substring(0, 10);\r\n        POS.callApiReporte(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer?.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // DÃ­a anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del dÃ­a anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer).substring(0, 10);\r\n        POS.callApiReporte(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const anio = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${anio}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', 'Â¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n    \r\n      POS.callApiReporte(fechainicio, fechafin);\r\n    });\r\n\r\n})();\r\n\r\n\r\n\r\n\r\n","(function(){\n  if(document.querySelector('.reportes')){\n    const graficaventa = document.querySelectorAll<HTMLButtonElement>('.graficaventa');\n    const chartventas = (document.getElementById('chartventas') as HTMLCanvasElement)?.getContext('2d');\n    const chartutilidad = (document.getElementById('chartutilidad') as HTMLCanvasElement)?.getContext('2d');\n\n    let chartVentasInstance: any | null = null;\n\n    const formatoMoneda = new Intl.NumberFormat('es-CO', {\n      maximumFractionDigits: 0,\n      minimumFractionDigits: 0\n    });\n\n    const setGraficaActiva = (botonActivo: HTMLButtonElement | null) => {\n      graficaventa.forEach((boton) => boton.classList.toggle('active', boton === botonActivo));\n    };\n\n    setGraficaActiva(document.getElementById('graficaVentaMensual') as HTMLButtonElement | null);\n    callapiventasgrafica('/admin/api/ventasGraficaMensual');\n\n    graficaventa.forEach((btngrafica, index) =>{\n      btngrafica.addEventListener('click', () =>{\n        let url:string = '/admin/api/ventasGraficaMensual';\n        if(index == 1){\n          url = '/admin/api/ventasGraficaDiario';\n        }\n        setGraficaActiva(btngrafica);\n        callapiventasgrafica(url);\n      });\n    });\n\n    async function callapiventasgrafica(url:string){\n      try {\n        const respuesta = await fetch(url);\n        const resultado = await respuesta.json();\n        graficaVentas(resultado);\n      } catch (error) {\n        console.log(error);\n      }\n    }\n\n    function graficaVentas(resultado:{label:string[], datos:string[]}){\n      if(!chartventas)return;\n      if (chartVentasInstance)chartVentasInstance.destroy();\n\n      const gradient = chartventas.createLinearGradient(0, 0, 0, 360);\n      gradient.addColorStop(0, 'rgba(79, 70, 229, .92)');\n      gradient.addColorStop(.58, 'rgba(6, 182, 212, .55)');\n      gradient.addColorStop(1, 'rgba(6, 182, 212, .16)');\n\n      chartVentasInstance = new Chart(chartventas, {\n        type: 'bar',\n        data: {\n          labels: resultado.label,\n          datasets: [{\n            label: 'Total Ventas',\n            data: resultado.datos,\n            backgroundColor: gradient,\n            borderColor: 'rgba(79, 70, 229, .95)',\n            borderRadius: 10,\n            borderSkipped: false,\n            borderWidth: 1,\n            hoverBackgroundColor: 'rgba(79, 70, 229, .95)',\n            maxBarThickness: 58\n          }]\n        },\n        options: {\n          animation: {\n            duration: 700,\n            easing: 'easeOutQuart'\n          },\n          maintainAspectRatio: false,\n          responsive: true,\n          scales: {\n            y: {\n              beginAtZero: true,\n              border: {display: false},\n              grid: {\n                color: 'rgba(148, 163, 184, .18)',\n                drawBorder: false\n              },\n              ticks: {\n                color: '#64748b',\n                font: {\n                  size: 12,\n                  weight: '600'\n                },\n                callback: (value:any) => formatoMoneda.format(Number(value))\n              }\n            },\n            x: {\n              border: {display: false},\n              grid: {display: false},\n              ticks: {\n                color: '#64748b',\n                font: {\n                  size: 12,\n                  weight: '600'\n                }\n              }\n            }\n          },\n          plugins: {\n            legend: {\n              display: false\n            },\n            tooltip: {\n              backgroundColor: '#14233b',\n              bodyColor: '#fff',\n              borderColor: 'rgba(79, 70, 229, .28)',\n              borderWidth: 1,\n              cornerRadius: 10,\n              displayColors: false,\n              padding: 12,\n              titleColor: '#e0f2fe',\n              callbacks: {\n                label: (context:any) => `Ventas: $${formatoMoneda.format(Number(context.parsed.y || 0))}`\n              }\n            }\n          }\n        }\n      });\n    }\n\n    (async ()=>{\n      try {\n        const url = '/admin/api/graficaValorInventario';\n        const respuesta = await fetch(url);\n        const resultado = await respuesta.json();\n        if(!chartutilidad)return;\n\n        new Chart(chartutilidad, {\n          type: 'doughnut',\n          data: {\n            labels: ['Ventas total', 'Costo', 'Utilidad'],\n            datasets: [{\n              label: 'Inventario',\n              data: [Number(resultado.valorventa), Number(resultado.costoinv), (Number(resultado.valorventa) - Number(resultado.costoinv))],\n              backgroundColor: ['#4f46e5', '#06b6d4', '#22c55e'],\n              borderColor: '#ffffff',\n              borderRadius: 8,\n              borderWidth: 5,\n              hoverOffset: 8\n            }]\n          },\n          options: {\n            cutout: '66%',\n            maintainAspectRatio: false,\n            responsive: true,\n            plugins: {\n              legend: {\n                align: 'center',\n                labels: {\n                  boxHeight: 10,\n                  boxWidth: 10,\n                  color: '#475569',\n                  font: {\n                    size: 12,\n                    weight: '700'\n                  },\n                  padding: 14,\n                  usePointStyle: true,\n                  generateLabels: (chart:any) => {\n                    const data = chart.data.datasets[0].data;\n                    const labels = chart.data.labels;\n                    return labels.map((label:any, i:any) => ({\n                      text: `${label} $${formatoMoneda.format(Number(data[i] || 0))}`,\n                      fillStyle: chart.data.datasets[0].backgroundColor[i],\n                      strokeStyle: chart.data.datasets[0].backgroundColor[i],\n                      index: i\n                    }));\n                  }\n                }\n              },\n              tooltip: {\n                backgroundColor: '#14233b',\n                bodyColor: '#fff',\n                borderColor: 'rgba(6, 182, 212, .25)',\n                borderWidth: 1,\n                cornerRadius: 10,\n                displayColors: true,\n                padding: 12,\n                titleColor: '#e0f2fe',\n                callbacks: {\n                  label: (context:any) => `${context.label}: $${formatoMoneda.format(Number(context.parsed || 0))}`\n                }\n              }\n            }\n          }\n        });\n      } catch (error) {\n        console.log(error);\n      }\n    })();\n  }\n})();\r\n","\r\n(()=>{\r\n    if(document.querySelector('.ventas')){\r\n\r\n      const POS = (window as any).POS;\r\n\r\n      const inputBuscar = document.querySelector<HTMLInputElement>('#buscarproducto');\r\n      const filtrocategorias = document.querySelectorAll('.filtrocategorias');  //los btns de las categorias\r\n      const btnCategorias = document.querySelector<HTMLButtonElement>('#btnCategorias');\r\n      const menuCategorias = document.querySelector<HTMLDivElement>('#menuCategorias');\r\n\r\n      var options = {\r\n        valueNames: [ 'card-producto', { data: ['id', 'categoria', 'code'] }],\r\n        page: 18,\r\n        pagination: true,\r\n      };\r\n      const productos = document.querySelectorAll<HTMLElement>('.producto');\r\n      if(productos.length)\r\n      var hackerList = new List('hacker-list', options);\r\n      POS.hackerList = hackerList;  //exportar\r\n      const setCategoriaActiva = (categoriaActiva: string) => {\n        filtrocategorias.forEach((categoriaEl) => {\n          const item = categoriaEl as HTMLElement;\n          const check = item.querySelector('i');\n          const activo = item.dataset.categoria === categoriaActiva;\n\n          item.classList.toggle('categoria-activa', activo);\n          item.classList.toggle('bg-indigo-50', activo);\n          item.classList.toggle('text-indigo-700', activo);\n          item.classList.toggle('font-semibold', activo);\n          item.classList.toggle('text-slate-700', !activo);\n          check?.classList.toggle('hidden', !activo);\n        });\n      };\n\n      POS.reiniciarCatalogoVentas = ():void => {\n        if(inputBuscar)inputBuscar.value = '';\n        const categorySelect = document.querySelector('#categorySelect');\n        if(categorySelect)categorySelect.textContent = 'Todos';\n        setCategoriaActiva('Todos');\n        if(hackerList){\n          hackerList.search('');\n          hackerList.filter();\n          hackerList.show(1, options.page);\n          hackerList.update();\n        }\n      };\n\n      filtrocategorias.forEach(element => {\n        element.addEventListener('click', (e)=>{\n          const categoriaItem = (e.target as HTMLElement).closest('.filtrocategorias') as HTMLElement | null;\n          const categoria:string = categoriaItem?.dataset.categoria || 'Todos';\n          document.querySelector('#categorySelect')!.textContent = categoria;\n          setCategoriaActiva(categoria);\n          if(hackerList)\n            hackerList.filter((item: any)=>{\n              hackerList.search('');\n              if(categoria === 'Todos')return true;\n              return item.values().categoria === categoria\n            });\n        });\n      });\r\n\r\n\r\n      inputBuscar?.addEventListener('keydown', (e) => {\r\n        if (e.key !== 'Enter') return;\r\n\r\n        e.preventDefault();\r\n\r\n        if (!hackerList) return;\r\n\r\n        const items = hackerList.visibleItems;\r\n\r\n        console.log(items);\r\n        if (!items.length) {\r\n          inputBuscar.value = '';\r\n          hackerList.search('');\r\n          return;\r\n        }\r\n\r\n        const productosku = items[0].elm as HTMLElement;\r\n        const products = POS.products as productsapi[];\r\n        const precio = products.find(x=>x.id == productosku.dataset.id)?.precio_venta;\r\n        POS.actualizarCarrito(productosku.dataset.id, 1, true, true, precio);\r\n\r\n        inputBuscar.value = '';\r\n        hackerList.search('');\r\n      });\r\n\r\n\r\n      //////--------  Apertura y cierre del btn Categorias\r\n\r\n      btnCategorias?.addEventListener('click', (e) => {\r\n        e.stopPropagation(); // evita cierre inmediato\r\n        menuCategorias?.classList.toggle('hidden');\r\n        if(!menuCategorias?.classList.contains('hidden'))document.addEventListener('click', cerrarMenuCategorias);\r\n      });\r\n      // cerrar al hacer click en una categorÃ­a\r\n      document.querySelectorAll('.filtrocategorias').forEach(el => {\r\n        el.addEventListener('click', () => {\r\n          menuCategorias?.classList.add('hidden');\r\n          document.removeEventListener('click', cerrarMenuCategorias);\r\n        });\r\n      });\r\n      // cerrar al hacer click fuera del menÃº\r\n      function cerrarMenuCategorias() {\r\n        menuCategorias?.classList.add('hidden');\r\n        document.removeEventListener('click', cerrarMenuCategorias);\r\n      }\r\n\r\n\r\n\r\n      //////---------------------------------------------------------------------------\r\n\r\n\r\n      const btnCarritoMovil = document.querySelector('#btnCarritoMovil') as HTMLButtonElement; //btn para abrir el modal del carrito de ventas en movil\r\n      const contenidocarrito = document.getElementById('contenidocarrito') as HTMLElement;\r\n      const contenedorDesktop = document.getElementById('contenedorDesktop') as HTMLDivElement;\r\n      //const miDialogoCarritoMovil = document.getElementById('miDialogoCarritoMovil') as HTMLDialogElement;\r\n      const btnCerrarCarritoMovil = document.querySelector('#btnCerrarCarritoMovil') as HTMLButtonElement;\r\n      const overlayCarrito = document.getElementById('overlayCarrito') as HTMLDivElement;\r\n      const screenWidth:number = window.innerWidth;\r\n\r\n      /*if(screenWidth<992)miDialogoCarritoMovil.appendChild(contenidocarrito);\r\n\r\n      window.addEventListener('resize', ()=>{\r\n        if (window.innerWidth >= 992) {\r\n          contenedorDesktop.appendChild(contenidocarrito);\r\n          miDialogoCarritoMovil.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        } else {\r\n          miDialogoCarritoMovil.appendChild(contenidocarrito);\r\n        }\r\n      });*/\r\n\r\n      // btn para abrir el carrito de ventas en movil\r\n      btnCarritoMovil?.addEventListener('click', (e)=>{\r\n        //miDialogoCarritoMovil.showModal();\r\n        //document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        contenedorDesktop.classList.remove('translate-x-full');\r\n        overlayCarrito.classList.remove('hidden');\r\n      });\r\n\r\n      btnCerrarCarritoMovil.addEventListener('click', ()=>{\r\n        //miDialogoCarritoMovil.close();\r\n        //document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        contenedorDesktop.classList.add('translate-x-full');\r\n        overlayCarrito.classList.add('hidden');\r\n      });\r\n\r\n      /*function cerrarDialogoExterno(event:Event) {\r\n        const f = event.target;\r\n        if (f === miDialogoCarritoMovil ) {\r\n          miDialogoCarritoMovil.close();\r\n          document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n      }*/\r\n\r\n\r\n      /*const paginador ={\r\n\r\n      }\r\n      POS.paginador = paginador;*/\r\n\r\n    }\r\n\r\n})();\n","(()=>{\r\n  if(!document.querySelector('.ventas'))return;\r\n\r\n  const productosAPI = {\r\n\r\n    async getProductosAPI(){\r\n      try {\r\n          const url = \"/admin/api/allproducts\"; //llamado a la API REST\r\n          const respuesta = await fetch(url); \r\n          const products = await respuesta.json();\r\n          return products;\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    }\r\n    \r\n  };\r\n\r\n  (window as any).POS.productosAPI = productosAPI;\r\n\r\n\r\n})();","(()=>{\r\n  if(!document.querySelector('.ventas')&&!document.querySelector('.crearseparado'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const btndescuento = document.querySelector('#btndescuento') as HTMLButtonElement;\r\n    const miDialogoDescuento = document.querySelector('#miDialogoDescuento') as any;\r\n    const tipoDescts = document.querySelectorAll<HTMLInputElement>('input[name=\"tipodescuento\"]'); //radio buttom\r\n    const inputDescuento = document.querySelector('#inputDescuento') as HTMLInputElement;\r\n    const inputDescuentoClave = document.querySelector('#inputDescuentoClave') as HTMLInputElement;\r\n    let valorMax = 0;\r\n    \r\n    interface clavesApi {\r\n      clave:string,\r\n      valor_default:string|null,\r\n      valor_final:string|null,\r\n      valor_local:string|null\r\n    };\r\n\r\n    let clavedcto:clavesApi[];\r\n\r\n    (async ()=>{\r\n      try {\r\n          const url = \"/admin/api/getPasswords\"; //llamado a la API REST\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json(); \r\n          clavedcto = resultado;\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();\r\n    \r\n    btndescuento?.addEventListener('click', ()=>{\r\n      if(POS.carrito.length){\r\n        valorMax = POS.valorTotal.subtotal;\r\n        //validar que si al reducir los productos o aumentar recalcular el porcentaje\r\n        miDialogoDescuento.showModal();\r\n        document.addEventListener(\"click\", POS.cerrarDialogoExterno);\r\n      }\r\n    });\r\n\r\n    /////////////////////  logica del descuento  //////////////////////////\r\n    tipoDescts.forEach(desc=>{ //evento a los radiobutton\r\n      desc.addEventListener('change', (e:Event)=>{\r\n        if((e.target as HTMLInputElement).value === \"porcentaje\"){\r\n          valorMax = 100;\r\n          inputDescuento.value = '';\r\n        }\r\n        if((e.target as HTMLInputElement).value === \"valor\"){\r\n          inputDescuento.value = '';\r\n          valorMax = POS.valorTotal.subtotal;\r\n        }\r\n      });\r\n    });\r\n\r\n    inputDescuento?.addEventListener('input', (e)=>{\r\n      var valorInput:number = Number((e.target as HTMLInputElement).value);\r\n      if(valorInput > valorMax){\r\n        inputDescuento.value = valorMax+'';\r\n        valorInput = valorMax; \r\n      }\r\n    });\r\n\r\n    document.querySelector('#formDescuento')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      const valorInput:number = Number(inputDescuento.value);\r\n      if(tipoDescts[0].checked){  //tipo valor\r\n        POS.valorTotal.dctox100 = Math.round((valorInput*100)/POS.valorTotal.subtotal);  // valor en porcentaje\r\n        POS.valorTotal.descuento = valorInput;  //valor del dcto\r\n      }\r\n      if(tipoDescts[1].checked){ //tipo porcentaje\r\n        POS.valorTotal.descuento = (POS.valorTotal.subtotal*valorInput)/100;  //valor descontado\r\n        POS.valorTotal.dctox100 = valorInput;  //valor en porcentaje\r\n      }\r\n      //validar en backend password\r\n      const v:number = validarPasswordDcto();\r\n      if(!v)return;\r\n      \r\n      POS.valorTotal.total = POS.valorTotal.subtotal - POS.valorTotal.descuento + POS.valorTotal.valortarifa;\n      document.querySelector('#total')!.textContent = '$ '+POS.valorTotal.total.toLocaleString();\n      (document.querySelector('#descuento') as HTMLElement).textContent = '$'+POS.valorTotal.descuento.toLocaleString();\n      POS.gestionSubirModalPagar?.calculoTasaInteres?.();\n      miDialogoDescuento.close();\n      document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\n    });\n    \r\n    function validarPasswordDcto():number{\r\n      const clave = clavedcto.find(c => c.clave=='clave_para_agregar_descuento');\r\n      if(clave?.valor_final!==null && inputDescuentoClave.value !== clave?.valor_final){\r\n        msjAlert('error', 'El password es invalido', (document.querySelector('#divmsjalertaClaveDcto') as HTMLElement));\r\n        return 0;\r\n      }\r\n      return 1;\r\n    }\r\n    \r\n    const gestionarDescuentos = { miDialogoDescuento }\r\n\r\n    POS.gestionarDescuentos = gestionarDescuentos;\r\n    \r\n\r\n})();\n","(()=>{\r\n  if(!document.querySelector('.ventas'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const btnotros = document.querySelector('#btnotros') as HTMLButtonElement;  //btn de otros\r\n    const miDialogoOtrosProductos = document.querySelector('#miDialogoOtrosProductos') as any;\r\n    let otrosproductos:{id:number, nombre:string, cantidad:number, valorunidad:number, total:number}={\r\n      id: 0,\r\n      nombre: '',\r\n      cantidad: 0,\r\n      valorunidad: 0,\r\n      total: 0\r\n    }\r\n\r\n    ///////////////////// Evento al btn Otros /////////////////////////\r\n    btnotros.addEventListener('click', (e:Event)=>{\r\n      miDialogoOtrosProductos.showModal();\r\n      document.addEventListener(\"click\", POS.cerrarDialogoExterno);\r\n    });\r\n\r\n    const gestionOtrosProductos = {\r\n      miDialogoOtrosProductos,  \r\n      otrosproductos(){\r\n\r\n        /////////////////////Evento al formulario de agregar otros productos //////////////////////\r\n        document.querySelector('#formOtrosProductos')?.addEventListener('submit', (e:Event)=>{\r\n            e.preventDefault();\r\n            const formelements = (e.target as HTMLFormElement).elements;\r\n            const impuesto = (formelements.namedItem('porcentaje_de_impuesto') as HTMLSelectElement).value;\r\n            const cantidadotros = Number((formelements.namedItem('cantidadotros') as HTMLInputElement).value);\r\n            const preciootros = Number((formelements.namedItem('preciootros') as HTMLInputElement).value);\r\n            \r\n            otrosproductos!.id += -1 ;\r\n            otrosproductos!.nombre = (formelements.namedItem('nombreotros') as HTMLInputElement).value;\r\n            otrosproductos!.cantidad = cantidadotros;\r\n            otrosproductos!.valorunidad = preciootros/cantidadotros;\r\n            otrosproductos!.total = preciootros;\r\n            \r\n            POS.products.push({\r\n                ID: otrosproductos!.id+'',\r\n                id: otrosproductos!.id+'', \r\n                idcategoria: '-1',\r\n                idunidadmedida: '1',\r\n                nombre: otrosproductos!.nombre,\r\n                foto: 'na',\r\n                impuesto: impuesto==''?null:impuesto, //impuesto en %\r\n                marca: 'na',\r\n                tipoproducto: '-1', // 0 = simple,  1 = compuesto\r\n                tipoproduccion: '-1', //0 = inmediato, 1 = construccion\r\n                codigo: '-1',\r\n                unidadmedida: 'Unidad',\r\n                descripcion: 'na',\r\n                peso: 'na',\r\n                medidas: 'na',\r\n                color: 'na',\r\n                funcion: 'na',\r\n                uso: 'na',\r\n                fabricante: 'na',\r\n                garantia: 'na',\r\n                stock: '0',\r\n                promediostock: '0',\r\n                stockminimo: '1',\r\n                categoria: 'na',\r\n                rendimientoestandar: '1',\r\n                precio_compra: '0',\r\n                precio_venta: otrosproductos!.valorunidad+'',\r\n                percentcomision: 0,\r\n                fecha_ingreso: '',\r\n                estado: '1',\r\n                visible: '1',\r\n                insumos: []\r\n            });\r\n\n            POS.actualizarCarrito(otrosproductos.id+'', cantidadotros, false, false, otrosproductos!.valorunidad+'', null);\n            POS.mostrarFeedbackCarrito?.(otrosproductos!.nombre || 'Producto personalizado', cantidadotros);\n            miDialogoOtrosProductos.close();\n            document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\n            (e.target as HTMLFormElement).reset();\n        });\r\n\r\n      }\r\n    };\r\n\r\n    (window as any).POS.gestionOtrosProductos = gestionOtrosProductos;\r\n\r\n})();\n","(()=>{\r\n  if(!document.querySelector('.ventas'))return;\r\n\r\n  const POS = (window as any).POS;\r\n\r\n  const miDialogoPreciosAdicionales = document.querySelector('#miDialogoPreciosAdicionales') as HTMLDialogElement;\r\n  const aplicarOpcionesProducto = document.querySelector('#aplicarOpcionesProducto') as HTMLButtonElement;\r\n  const inputComisionProducto = document.querySelector('#comisionproducto') as HTMLInputElement;\r\n  const inputCantidadCalculada = document.querySelector('#inputCantidadCalculada') as HTMLInputElement;\r\n  const operationSum = document.querySelector('#operationSum') as HTMLInputElement;\r\n  const operationLess = document.querySelector('#operationLess') as HTMLInputElement;\r\n  const reset = document.querySelector('#reset') as HTMLInputElement;\r\n  const textCantidadCalculada = document.querySelector('#textCantidadCalculada') as HTMLParagraphElement;\r\n  const lastOperation = document.querySelector('#lastOperation') as HTMLParagraphElement;\r\n  let cantidadTotal:number = 0;\r\n  let historialCalculadora: string[] = [];\r\n\r\n  let producto:  Partial<productsapi>|undefined = {};\r\n  let productoConfigurado: Partial<productsapi> | undefined = {};\r\n\r\n  function cargarPreciosAdicionales() {\r\n    const listaPrecios = document.querySelector('#listaPrecios') as HTMLElement;\r\n    while(listaPrecios.firstChild)listaPrecios.removeChild(listaPrecios.firstChild);\r\n    producto?.preciosadicionales?.forEach(precio=>{\r\n        const preciohtml = `\r\n        <label\r\n            class=\"group flex justify-between items-center p-5\r\n          rounded-2xl bg-white border border-slate-200 cursor-pointer transition-all duration-300 hover:border-indigo-400 hover:bg-indigo-50 hover:shadow-md hover:-translate-y-1\">\r\n\r\n            <div class=\"flex items-center gap-4\">\r\n                <input\r\n                    type=\"radio\"\r\n                    class=\"w-5 h-5 text-indigo-600 focus:ring-indigo-500 inputprecioadicional accent-indigo-600 cursor-pointer\"\r\n                    data-idproducto=\"${producto?.id}\"\r\n                    name=\"precioSeleccionado\"\r\n                    value=\"${precio.precio}\">\r\n\r\n                <div>\r\n                    <p class=\"text-sm text-slate-500 uppercase tracking-wider\">\r\n                        Precio adicional\r\n                    </p>\r\n\r\n                    <p class=\"text-xl font-bold text-slate-800\">\r\n                        $${Number(precio.precio).toLocaleString()}\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <span class=\"material-symbols-outlined\r\n           text-slate-300 text-3xl transition-all duration-300\r\n           group-hover:scale-110 group-hover:text-indigo-500 group-hover:rotate-6\">\r\n                sell\r\n            </span>\r\n        </label>\r\n        `;\r\n      listaPrecios.insertAdjacentHTML('beforeend', preciohtml);\r\n    });\r\n  }\r\n\r\n\r\n  aplicarOpcionesProducto.addEventListener('click', ()=>{\r\n    const comision = inputComisionProducto.value.trim();\r\n    const seleccionado = document.querySelector('.inputprecioadicional:checked') as HTMLInputElement;\r\n    const inputPrecioLibre = document.querySelector('#precioLibre') as HTMLInputElement;\r\n    if(producto != undefined && comision!=='' && !Number.isNaN(Number(comision))){  //ajustar porcentaje de comision a producto\r\n      producto.percentcomision = Number(comision);\r\n      //actualizar el carrito con el nuevo valor de comision\r\n      const unitem:CarritoItem|undefined = (POS.carrito as CarritoItem[])?.find(x=>x.idproducto == producto?.id);\r\n      if(unitem!=undefined)unitem.percentcomision = Number(comision);\r\n    }\r\n    miDialogoPreciosAdicionales.close();\r\n    document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\r\n    const precioLibre = obtenerNumero(inputPrecioLibre);\r\n    const prioridadValor = precioLibre!=null?precioLibre:seleccionado?.checked?seleccionado.value:producto?.precio_venta;\r\n    filtrarInsumos(productoConfigurado); //esta en app.ts\r\n    if(producto != undefined)POS.actualizarCarrito(producto.id, cantidadTotal==0?1:cantidadTotal, true, true, prioridadValor+'', productoConfigurado);\r\n  });\r\n\r\n\r\n  //****CALCULADORA\r\n  inputCantidadCalculada.addEventListener('keydown', (e: KeyboardEvent)=>{\r\n    if(e.key === '+') {\r\n      e.preventDefault();\r\n      calcular('sumar');\r\n    }\r\n    if(e.key === '-') {\r\n      e.preventDefault();\r\n      calcular('restar');\r\n    }\r\n  });\r\n\r\n  function calcular(operacion: 'sumar' | 'restar'):void{\r\n    const cantidad = Number(inputCantidadCalculada.value);\r\n    /*if(isNaN(cantidad) || inputCantidadCalculada.value === ''){\r\n      inputCantidadCalculada.focus();\r\n      return;\r\n    }*/\r\n    if(operacion === 'sumar'){\r\n      cantidadTotal += cantidad;\r\n      //lastOperation.textContent = `+${cantidad}`;\r\n      historialCalculadora.push(`+${cantidad}`);\r\n      lastOperation.textContent = historialCalculadora.join('   ');\r\n    }else{\r\n      cantidadTotal -= cantidad;\r\n      //lastOperation.textContent = `-${cantidad}`;\r\n      historialCalculadora.push(`-${cantidad}`);\r\n      lastOperation.textContent = historialCalculadora.join('   ');\r\n    }\r\n    textCantidadCalculada.textContent = cantidadTotal.toFixed(2);\r\n    inputCantidadCalculada.value = '';\r\n    inputCantidadCalculada.focus();\r\n  }\r\n\r\n  operationSum.addEventListener('click', ()=>calcular('sumar'));\r\n  operationLess.addEventListener('click', ()=>calcular('restar'));\r\n\r\n  reset.addEventListener('click', ()=>{\r\n    cantidadTotal = 0;\r\n    inputCantidadCalculada.value = '';\r\n    textCantidadCalculada.textContent = '0';\r\n    lastOperation.textContent = '0';\r\n    historialCalculadora.length = 0;\r\n  });\r\n  //****FIN CALCULADORA\r\n\r\n  \r\n\r\n  /////////// INSUMOS DINAMICAMENTE  /////////////\r\n  function cargarInsumos(){\r\n    const listaInsumos = document.querySelector('#listaInsumos') as HTMLElement;\r\n    listaInsumos.innerHTML = \"\";\r\n\r\n    const { obligatorios, insumosgrupo } = agruparInsumos();\r\n    if(insumosgrupo.size === 0 && obligatorios.length === 0){\r\n        renderVariacionesVacias(listaInsumos);\r\n        return;\r\n    }\r\n\r\n    insumosgrupo.forEach(insumogrupo =>\r\n        renderGrupo(insumogrupo, listaInsumos)\r\n    );\r\n    renderObligatorios(obligatorios, listaInsumos);\r\n    eventosCheckbox();\r\n    eventosRadio();\r\n    eventosCantidadInsumo();\r\n  }\r\n\r\n  function renderVariacionesVacias(contenedor: HTMLElement){\r\n      contenedor.insertAdjacentHTML(\r\n          \"beforeend\",\r\n          `<div class=\"rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-8 text-center\">\r\n              <span class=\"material-symbols-outlined text-indigo-500 text-5xl mb-3\">\r\n                  inventory_2\r\n              </span>\r\n              <h5 class=\"text-2xl font-bold text-slate-800\">\r\n                  Sin variaciones configuradas\r\n              </h5>\r\n              <p class=\"mt-2 text-lg text-slate-500\">\r\n                  Este producto no tiene insumos u opciones adicionales para seleccionar.\r\n              </p>\r\n          </div>`\r\n      );\r\n  }\r\n  function agruparInsumos() {\r\n    const obligatorios = producto?.insumos?.filter(i => i.grupos_insumos === null) ?? [];\r\n    \r\n    const insumosgrupo = new Map<number, insumo[]>();\r\n    producto?.insumos\r\n        ?.filter(i => i.grupos_insumos !== null)\r\n        .forEach(insumo => {\r\n            const idGrupo = Number(insumo.grupos_insumos?.id);\r\n            if (!insumosgrupo.has(idGrupo))\r\n                insumosgrupo.set(idGrupo, []);\r\n\r\n            insumosgrupo.get(idGrupo)!.push(insumo);\r\n        });\r\n\r\n    return { obligatorios, insumosgrupo };\r\n  }\r\n\r\n  function renderObligatorios(insumos:any[], contenedor:HTMLElement){\r\n      if(insumos.length===0) return;\r\n\r\n      let html = `\r\n          <div class=\"rounded-2xl border border-slate-200 bg-slate-50 p-5 mt-5\">\r\n              <div class=\"flex items-center gap-3 mb-4\">\r\n                  <span class=\"material-symbols-outlined text-emerald-600 text-3xl\">\r\n                      check_circle\r\n                  </span>\r\n\r\n                  <div>\r\n                      <h5 class=\"text-xl font-bold text-slate-800\">\r\n                          Incluidos\r\n                      </h5>\r\n\r\n                      <p class=\"text-slate-500 text-lg leading-6\">\r\n                          Estos insumos vienen incluidos con el producto.\r\n                      </p>\r\n                  </div>\r\n              </div>\r\n\r\n              <div class=\"space-y-2\">\r\n      `;\r\n\r\n      insumos.forEach(insumo=>{\r\n          html += `\r\n              <div class=\"flex items-center gap-3 rounded-xl bg-white border border-slate-200 px-4 py-3\">\r\n                  <span class=\"material-symbols-outlined text-emerald-500\">\r\n                      done\r\n                  </span>\r\n\r\n                  <span class=\"font-medium text-slate-700\">\r\n                      ${insumo.nombre}\r\n                  </span>\r\n              </div>\r\n          `;\r\n      });\r\n\r\n      html += `</div></div>`;\r\n      contenedor.insertAdjacentHTML(\"beforeend\", html);\r\n  }\r\n  //   insumos = [{idproducto:1, idsubproducto: 3, seleccionado: 1}]\r\n  function renderGrupo(insumos:any[], contenedor:HTMLElement){\r\n    const grupo = insumos[0].grupos_insumos;\r\n    const panel = document.createElement(\"div\");\r\n    panel.className = \"rounded-2xl border border-slate-200 bg-slate-50 p-5\";\r\n    panel.innerHTML = `\r\n        <div class=\"flex items-start justify-between gap-4 border-b border-slate-200 pb-4 mb-4\">\r\n            <div class=\"flex items-start gap-3\">\r\n                <span class=\"material-symbols-outlined text-indigo-600 text-3xl mt-1\">\r\n                    ${Number(grupo.tipo) === 0 ? 'radio_button_checked' : 'check_box'}\r\n                </span>\r\n\r\n                <div>\r\n                    <h3 class=\"text-2xl font-bold text-slate-800\">\r\n                        ${grupo.nombre}\r\n                    </h3>\r\n                    <p class=\"text-slate-500 text-lg leading-6 mt-1\">\r\n                        ${Number(grupo.tipo) === 0\r\n                            ? 'Seleccione solamente una opci&oacute;n.'\r\n                            : 'Puede seleccionar una o varias opciones.'}\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"space-y-3\" data-opciones-grupo></div>\r\n    `;\r\n\r\n    contenedor.appendChild(panel);\r\n    const opciones = panel.querySelector('[data-opciones-grupo]') as HTMLElement;\r\n\r\n    if(Number(grupo.tipo)===0){\r\n        renderRadios(insumos, opciones);\r\n    }else{\r\n        renderCheckbox(insumos, opciones);\r\n    }\r\n  }\r\n  function renderRadios(insumos:any[], contenedor:HTMLElement){\r\n      insumos.forEach(insumo=>{\r\n          contenedor.insertAdjacentHTML(\r\n              \"beforeend\",\r\n              `<label\r\n                  class=\"group flex items-center justify-between gap-4 rounded-2xl bg-white tarjeta-radio-insumo border border-slate-200 cursor-pointer px-4 py-4 transition-all duration-300 hover:border-indigo-300 hover:bg-indigo-50 hover:shadow-md\">\r\n\r\n                  <div class=\"flex items-center gap-4 min-w-0\">\r\n                      <input\r\n                          type=\"radio\"\r\n                          class=\"inputInsumoRadio w-6 h-6 accent-indigo-600 cursor-pointer shrink-0\"\r\n                          data-idproducto=\"${producto?.id}\"\r\n                          data-idinsumo=\"${insumo.id_subproducto}\"\r\n                          data-idgrupo=\"${insumo.grupos_insumos.id}\"\r\n                          name=\"grupo_${insumo.grupos_insumos.id}\"\r\n                          ${Number(insumo.seleccionado) ? \"checked\" : \"\"}\r\n                      >\r\n\r\n                      <p class=\"text-xl font-semibold text-slate-800 leading-6 truncate\">\r\n                          ${insumo.nombre}\r\n                      </p>\r\n                  </div>\r\n              </label>`\r\n          );\r\n      });\r\n  }\r\n  function renderCheckbox(insumos:any[], contenedor:HTMLElement){\r\n      insumos.forEach(insumo=>{\r\n        // Temporal hasta conectar con backend\r\n          insumo.precio_extra = 1600;\r\n\r\n          contenedor.insertAdjacentHTML(\r\n              \"beforeend\",\r\n              `<label\r\n                  class=\"tarjeta-checkbox-insumo block rounded-2xl border border-slate-200 bg-white p-4 cursor-pointer transition-all duration-300 hover:border-indigo-300 hover:bg-indigo-50 hover:shadow-md\">\r\n\r\n                  <div class=\"flex items-center justify-between gap-4\">\r\n                      <div class=\"flex items-center gap-4 flex-1 min-w-0\">\r\n                          <input\r\n                              type=\"checkbox\"\r\n                              class=\"inputInsumoCheckbox w-6 h-6 accent-indigo-600 cursor-pointer shrink-0\"\r\n                              data-idproducto=\"${producto?.id}\"\r\n                              data-idinsumo=\"${insumo.id_subproducto}\"\r\n                              data-idgrupo=\"${insumo.grupos_insumos.id}\"\r\n                              ${Number(insumo.seleccionado) ? \"checked\":\"\"}\r\n                          >\r\n\r\n                          <p class=\"text-xl font-semibold text-slate-800 leading-6 truncate\">\r\n                              ${insumo.nombre}\r\n                          </p>\r\n                      </div>\r\n\r\n                      ${htmlPrecioExtra(insumo)}\r\n                  </div>\r\n\r\n                  ${htmlCantidad(insumo)}\r\n              </label>`\r\n          );\r\n      });\r\n  }\r\n  function htmlPrecioExtra(insumo: insumo): string {\r\n      const precioExtra = Number(insumo.precio_extra);\r\n\r\n      if (precioExtra <= 0) return \"\";\r\n\r\n      return `\r\n          <span\r\n              class=\"badge-precio-extra inline-flex items-center gap-1.5 rounded-full bg-emerald-100 border border-emerald-200 px-3 py-1.5 text-base font-bold text-emerald-700 shadow-sm transition-transform duration-200 shrink-0\">\r\n              <span class=\"material-symbols-outlined text-base\">\r\n                  add\r\n              </span>\r\n\r\n              $${precioExtra.toLocaleString('es-CO')}\r\n          </span>\r\n      `;\r\n  }\r\n  function htmlCantidad(insumo: insumo): string {\r\n    if (Number(insumo.permite_aumentar) === 0) return \"\";\r\n\r\n    return `\r\n        <div\r\n            class=\"contenedor-cantidad overflow-hidden transition-all duration-300 ease-out ${Number(insumo.seleccionado)\r\n                ? 'max-h-40 opacity-100 mt-5 translate-y-0'\r\n                : 'max-h-0 opacity-0 mt-0 translate-y-2'}\">\r\n\r\n            <p class=\"mb-3 text-base font-semibold text-slate-600 text-center\">\r\n                Cantidad a agregar\r\n            </p>\r\n            <div class=\"flex justify-center mt-3\">\r\n                <div class=\"inline-flex items-center rounded-2xl border border-slate-300 overflow-hidden shadow-sm bg-white\">\r\n\r\n                    <button\r\n                        type=\"button\"\r\n                        class=\"btnCantidadMenos w-14 h-14 active:scale-95 transition-all duration-150 bg-indigo-50 hover:bg-indigo-100 text-indigo-600 text-2xl font-bold\">\r\n                        -\r\n                    </button>\r\n\r\n                    <input\r\n                        type=\"number\"\r\n                        value=\"1\"\r\n                        min=\"1\"\r\n                        class=\"inputCantidadInsumo w-28 h-14 text-center text-lg font-bold border-x border-slate-300 outline-none focus:ring-0\"\r\n                    >\r\n\r\n                    <button\r\n                        type=\"button\"\r\n                        class=\"btnCantidadMas w-14 h-14 active:scale-95 transition-all duration-150 bg-indigo-50 hover:bg-indigo-100 text-indigo-600 text-2xl font-bold\">\r\n                        +\r\n                    </button>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    `;\r\n}\r\n  function eventosCheckbox() {\r\n      const checkboxes = document.querySelectorAll<HTMLInputElement>(\".inputInsumoCheckbox\");\r\n\r\n      checkboxes.forEach(checkbox => {\r\n          checkbox.addEventListener(\"change\", actualizarCheckbox);\r\n\r\n          // 🔥 Pinta la tarjeta si ya viene seleccionada\r\n          if (checkbox.checked) {\r\n\r\n              checkbox\r\n                  .closest(\".tarjeta-checkbox-insumo\")\r\n                  ?.classList.add(\r\n                      \"border-indigo-400\",\r\n                      \"bg-indigo-50\",\r\n                      \"ring-2\",\r\n                      \"ring-indigo-100\",\r\n                      \"shadow-md\"\r\n                  );\r\n          }\r\n      });\r\n  }\r\n\r\n  function eventosRadio() {\r\n    const radios = document.querySelectorAll<HTMLInputElement>(\".inputInsumoRadio\");\r\n    radios.forEach(radio => radio.addEventListener(\"change\", actualizarRadio));\r\n  }\r\n\r\n  function eventosCantidadInsumo() {\r\n    const cantidades = document.querySelectorAll<HTMLInputElement>(\".inputCantidadInsumo\");\r\n    cantidades.forEach(input => input.addEventListener(\"change\", actualizarCantidadInsumo));\r\n  }\r\n\r\n  function actualizarCantidadInsumo(e: Event) {\r\n    const input = e.target as HTMLInputElement;\r\n    const idInsumo = Number(input.dataset.idinsumo);\r\n    const insumo = productoConfigurado?.insumos?.find(\r\n      item => Number(item.id_subproducto) === idInsumo\r\n    );\r\n    if(!insumo)return;\r\n\r\n    const cantidadBase = Number(\r\n      producto?.insumos?.find(item => Number(item.id_subproducto) === idInsumo)?.cantidadsubproducto ?? 0\r\n    );\r\n    const cantidad = Number(input.value);\r\n    const cantidadValida = Number.isFinite(cantidad) && cantidad >= cantidadBase\r\n      ? cantidad\r\n      : cantidadBase;\r\n\r\n    insumo.cantidadsubproducto = cantidadValida.toString();\r\n    input.value = cantidadValida.toString();\r\n  }\r\n\r\n\r\n  function actualizarCheckbox(e: Event) {\r\n    const checkbox = e.target as HTMLInputElement;\r\n    const idInsumo = Number(checkbox.dataset.idinsumo);\r\n    const insumo = productoConfigurado?.insumos?.find(\r\n        i => Number(i.id_subproducto) === idInsumo\r\n    );\r\n\r\n    if (!insumo) return;\r\n\r\n    insumo.seleccionado = checkbox.checked ? '1' : '0';\r\n\r\n    // 🔥 Obtener la tarjeta\r\n    const tarjeta = checkbox.closest(\".tarjeta-checkbox-insumo\");\r\n    const badge = tarjeta?.querySelector(\".badge-precio-extra\");\r\n    const contenedorCantidad =\r\n        tarjeta?.querySelector(\".contenedor-cantidad\");\r\n    if (!tarjeta) return;\r\n\r\n    if (checkbox.checked) {\r\n        tarjeta.classList.add(\r\n            \"border-indigo-400\",\r\n            \"bg-indigo-50\",\r\n            \"ring-2\",\r\n            \"ring-indigo-100\",\r\n            \"shadow-md\",\r\n            \"scale-[1.01]\"\r\n        );\r\n\r\n        badge?.classList.add(\"scale-110\");\r\n\r\n        setTimeout(() => {\r\n            badge?.classList.remove(\"scale-110\");\r\n        }, 150);\r\n        \r\n        contenedorCantidad?.classList.remove(\r\n            \"max-h-0\",\r\n            \"opacity-0\",\r\n            \"mt-0\"\r\n        );\r\n\r\n        contenedorCantidad?.classList.add(\r\n            \"max-h-40\",\r\n            \"opacity-100\",\r\n            \"mt-5\"\r\n        );\r\n    } else {\r\n        tarjeta.classList.remove(\r\n            \"border-indigo-400\",\r\n            \"bg-indigo-50\",\r\n            \"ring-2\",\r\n            \"ring-indigo-100\",\r\n            \"shadow-md\",\r\n            \"scale-[1.01]\"\r\n        );\r\n        contenedorCantidad?.classList.remove(\r\n            \"max-h-40\",\r\n            \"opacity-100\",\r\n            \"mt-5\"\r\n        );\r\n    \r\n        contenedorCantidad?.classList.add(\r\n            \"max-h-0\",\r\n            \"opacity-0\",\r\n            \"mt-0\"\r\n        );\r\n    }\r\n  }\r\n\r\n\r\n  function actualizarRadio(e: Event) {\r\n    const radio = e.target as HTMLInputElement;\r\n    if(!radio.checked)return;\r\n\r\n    const idGrupo = Number(radio.dataset.idgrupo);\r\n    const idInsumo = Number(radio.dataset.idinsumo);\r\n    productoConfigurado?.insumos?.forEach(insumo => {\r\n        if(Number(insumo.grupos_insumos?.id) === idGrupo)\r\n            insumo.seleccionado = '0';\r\n    });\r\n\r\n    const seleccionado = productoConfigurado?.insumos?.find(i=>Number(i.id_subproducto) === idInsumo);\r\n    if(seleccionado)seleccionado.seleccionado = '1';\r\n\r\n    document\r\n        .querySelectorAll(\".tarjeta-radio-insumo\")\r\n        .forEach(card => {\r\n            card.classList.remove(\r\n                \"border-indigo-400\",\r\n                \"bg-indigo-50\",\r\n                \"shadow-lg\"\r\n            );\r\n        });\r\n\r\n    const tarjeta = radio.closest(\".tarjeta-radio-insumo\");\r\n\r\n    tarjeta?.classList.add(\r\n        \"border-indigo-400\",\r\n        \"bg-indigo-50\",\r\n        \"shadow-lg\"\r\n    );  \r\n  }\r\n\r\n\r\n  /*function filtrarInsumos(){\r\n    const insumos = productoConfigurado?.insumos??[];\r\n    const ultimoSeleccionUnica  = insumos.filter(i=>i.grupos_insumos?.tipo === \"0\"&&i.seleccionado === \"1\").at(-1);\r\n\r\n    const nuevosElementos:insumo[] = [\r\n              ...(ultimoSeleccionUnica  ? [ultimoSeleccionUnica ] : []),\r\n              ...insumos.filter(i=>i.grupos_insumos?.tipo === \"1\" &&i.seleccionado === \"1\")\r\n    ];\r\n    insumos.splice(0, insumos.length, ...nuevosElementos);\r\n  }*/\r\n  /*\r\n  function actualizarCheckbox(e: Event) {\r\n    const checkbox = e.target as HTMLInputElement;\r\n    const idInsumo = Number(checkbox.dataset.idinsumo);\r\n    const insumo = productoConfigurado?.insumos?.find(i => Number(i.id_subproducto) === idInsumo);\r\n    if (!insumo || !productoConfigurado) return;\r\n    insumo.seleccionado = checkbox.checked ?'1':'0';\r\n\r\n    if(insumo.seleccionado == '1'){\r\n      const existe = producto?.insumos?.some(i => Number(i.id_subproducto) === idInsumo);\r\n      if (!existe)productoConfigurado?.insumos?.push(insumo);\r\n    }else{\r\n       productoConfigurado.insumos = productoConfigurado?.insumos?.filter(i => Number(i.id_subproducto) !== idInsumo);\r\n    }\r\n\r\n  }\r\n\r\n\r\n  function actualizarRadio(e: Event) {\r\n    const radio = e.target as HTMLInputElement;\r\n    if(!radio.checked)return;\r\n\r\n    const idGrupo = Number(radio.dataset.idgrupo);\r\n    const idInsumo = Number(radio.dataset.idinsumo);\r\n    productoConfigurado!.insumos = productoConfigurado?.insumos?.filter(insumo => Number(insumo.grupos_insumos?.id) !== idGrupo);\r\n\r\n    console.log(productoConfigurado);\r\n    const seleccionado = producto?.insumos?.find(\r\n        i => Number(i.id_subproducto) === idInsumo\r\n    );\r\n\r\n    if(seleccionado&&productoConfigurado){\r\n      seleccionado.seleccionado = '1';\r\n      productoConfigurado.insumos?.push(seleccionado);\r\n    }\r\n  }\r\n  */\r\n\r\n\r\n  ///////// FIN INSUMOS DINAMICOS  //////////\r\n\r\n\r\n  const gestionarPreciosAdicionales = {\r\n    miDialogoPreciosAdicionales,\r\n    abrirDialogo(elementProduct: HTMLElement) {\r\n      (document.querySelector('#textCardProduct') as HTMLParagraphElement).textContent = elementProduct.querySelector('.card-producto')?.textContent??'';\r\n      miDialogoPreciosAdicionales.showModal();\r\n        const inputPrecioLibre = document.querySelector('#precioLibre') as HTMLInputElement;\r\n\r\n        inputPrecioLibre.value = \"\";\r\n      cantidadTotal = 0;\r\n      textCantidadCalculada.textContent = '0';\r\n      lastOperation.textContent = '0';\r\n      historialCalculadora.length = 0;\r\n      const products = POS.products as productsapi[];\r\n      console.log(products);\r\n      producto = products.find(x=>x.id==elementProduct.dataset.id!);\r\n      productoConfigurado = structuredClone(producto);\r\n      cargarPreciosAdicionales();\r\n      cargarInsumos();\r\n      document.addEventListener(\"click\", POS.cerrarDialogoExterno);\r\n    },\r\n  };\r\n\r\n  POS.gestionarPreciosAdicionales = gestionarPreciosAdicionales;\r\n\r\n})();\r\n","(()=>{\r\n  if(document.querySelector('.ventas')){\r\n\r\n    const POS = (window as any).POS;\r\n     \r\n    const selectCliente = POS.gestionClientes.selectCliente;\r\n    const dirEntrega = POS.gestionClientes.dirEntrega;\r\n    const productos = document.querySelectorAll<HTMLElement>('#producto')!;\r\n    const selectVendedor = (document.querySelector('#vendedor') as HTMLSelectElement);\r\n    const valorDomicilio = document.querySelector('#valorDomicilio') as HTMLInputElement;\r\n    const contentproducts = document.querySelector('#productos');\r\n    const btnEntrega = document.querySelector('#btnEntrega') as HTMLButtonElement;\r\n    const btnPresencial = document.querySelector('#btnPresencial') as HTMLButtonElement;\r\n    const modalidadEntrega = document.querySelector('#modalidadEntrega') as HTMLElement;\r\n    const totalunidades = document.querySelector('#totalunidades') as HTMLElement;\r\n    const tablaventa = document.querySelector('#tablaventa tbody');\r\n    const carritoVacio = document.querySelector('#carritoVacio') as HTMLElement;\r\n    const btnguardar = document.querySelector('#btnguardar');\r\n    const btnfacturar = document.querySelector('#btnfacturar');\r\n    const btnaplicarcredito = document.querySelector('#btnaplicarcredito');\r\n    const btnAddCliente = document.querySelector('#addcliente') as HTMLElement;\r\n    const miDialogoAddCliente = POS.gestionClientes.miDialogoAddCliente;\r\n    //const miDialogoAddDir = POS.gestionClientes.miDialogoAddDir;\r\n    const miDialogoOtrosProductos = POS.gestionOtrosProductos.miDialogoOtrosProductos;\r\n    const miDialogoPreciosAdicionales = POS.gestionarPreciosAdicionales.miDialogoPreciosAdicionales;\r\n    const miDialogoFacturarA = POS.gestionarAdquiriente.miDialogoFacturarA;\r\n    const miDialogoDescuento = POS.gestionarDescuentos.miDialogoDescuento;\r\n    const miDialogoCredito = document.querySelector('#miDialogoCredito') as any;\r\n    const miDialogoGuardar = document.querySelector('#miDialogoGuardar') as any;\r\n    const miDialogoFacturar = document.querySelector('#miDialogoFacturar') as any;\r\n    const miDialogoCalculadora = document.querySelector('#miDialogoCalculadora') as HTMLDialogElement;\r\n    const btnCaja = document.querySelector('#caja') as HTMLSelectElement; //select de la caja en el modal pagar\r\n    const btnTipoFacturador = document.querySelector('#facturador') as HTMLSelectElement; //select del consecutivo o facturador en el modal de pago\r\n    const btnPagar = document.getElementById('btnPagar') as HTMLInputElement;\r\n    const btnCarritoMovil = document.querySelector('#btnCarritoMovil') as HTMLButtonElement|null;\r\n    const carritoMovilBadge = document.querySelector('#carritoMovilBadge') as HTMLElement|null;\r\n    const ventaCarritoToast = document.querySelector('#ventaCarritoToast') as HTMLElement|null;\r\n    const ventaCarritoToastTitle = document.querySelector('#ventaCarritoToastTitle') as HTMLElement|null;\r\n    const ventaCarritoToastMeta = document.querySelector('#ventaCarritoToastMeta') as HTMLElement|null;\r\n    \r\n    let carrito:{id:string, idproducto:string, tipoproducto:string, tipoproduccion:string, idcategoria: string, foto:string, nombreproducto: string, rendimientoestandar:string, costo:string, valorunidad: string, stock: number, promediostock: number, prioridadcomision: string, percentcomision: number, valorcomision: number, subtotal: number, base:number, impuesto:string, valorimp:number, descuento:number, total: number, insumos:insumo[]}[]=[];\r\n    const valorTotal = {porcentgananciauser: 0, valorgananciauser: 0, subtotal: 0, base: 0, valorimpuestototal: 0, dctox100: 0, descuento: 0, idtarifa: 0, valortarifa: 0, total: 0}; //datos global de la venta\r\n    let tarifas:{id:string, idcliente:string, nombre:string, valor:string}[] = []; \r\n    let indexcarrito:number, nombretarifa:string|undefined='', tipoventa:string=\"Contado\";\r\n    const promesas: Promise<any>[] = [];\r\n    let printerBT:string = getParam.impresora_principal_de_CAJA_para_Android_por_BT.valor_final;\r\n    \r\n    function resaltarSelectorCliente():void{\r\n      if(!btnAddCliente)return;\r\n      btnAddCliente.classList.remove('cliente-required-pulse');\r\n      void btnAddCliente.offsetWidth;\r\n      btnAddCliente.classList.add('cliente-required-pulse');\r\n      btnAddCliente.scrollIntoView({behavior: 'smooth', block: 'center'});\r\n      setTimeout(()=>btnAddCliente.classList.remove('cliente-required-pulse'), 3600);\r\n    }    \r\n    const constImp: {[key:string]: number} = {};\r\n    constImp['excluido'] = 0;\r\n    constImp['0'] = 0;  //exento de iva, tarifa 0%\r\n    constImp['5'] = 0.0476190476190476; //iva, tarifa al 5%,  Bienes/servicios al 5\r\n    constImp['8'] = 0.0740740740740741; //inc, tarifa al 8%,  impuesto nacional al consumo\r\n\r\n    function formatCantidadBadge(cantidad:number): string{\r\n      if(cantidad >= 1000000){\r\n        return (cantidad / 1000000).toLocaleString('es-CO', {maximumFractionDigits: 1}) + 'M';\r\n      }\r\n      if(cantidad >= 10000){\r\n        return (cantidad / 1000).toLocaleString('es-CO', {maximumFractionDigits: 1}) + 'K';\r\n      }\r\n      return cantidad.toLocaleString('es-CO');\r\n    }\r\n\r\n    function ajustarAnchoCantidad(input:HTMLInputElement, cantidad:number|string): void{\r\n      const largo = String(cantidad || 0).length;\r\n      input.style.width = `${Math.min(Math.max(largo + 2, 5), 10)}ch`;\r\n      input.title = String(cantidad || 0);\r\n    }\r\n\r\n    let ventaCarritoToastTimer:number|undefined;\r\n    function actualizarBadgeCarritoMovil(cantidad:number): void{\r\n      if(!carritoMovilBadge)return;\r\n      carritoMovilBadge.textContent = formatCantidadBadge(cantidad);\r\n      carritoMovilBadge.title = cantidad.toLocaleString('es-CO');\r\n      carritoMovilBadge.classList.toggle('is-visible', cantidad > 0);\r\n    }\r\n\r\n    function mostrarFeedbackCarrito(nombre:string, cantidadProducto:number): void{\r\n      if(window.innerWidth >= 992)return;\r\n\r\n      if(btnCarritoMovil){\r\n        btnCarritoMovil.classList.remove('carrito-feedback-pulse');\r\n        void btnCarritoMovil.offsetWidth;\r\n        btnCarritoMovil.classList.add('carrito-feedback-pulse');\r\n        setTimeout(()=>btnCarritoMovil.classList.remove('carrito-feedback-pulse'), 500);\r\n      }\r\n\r\n      if(ventaCarritoToast && ventaCarritoToastTitle && ventaCarritoToastMeta){\r\n        ventaCarritoToastTitle.textContent = `${nombre} agregado`;\r\n        ventaCarritoToastMeta.textContent = `Cantidad: ${cantidadProducto.toLocaleString('es-CO')}`;\r\n        ventaCarritoToast.classList.add('is-visible');\r\n        if(ventaCarritoToastTimer)window.clearTimeout(ventaCarritoToastTimer);\r\n        ventaCarritoToastTimer = window.setTimeout(()=>ventaCarritoToast.classList.remove('is-visible'), 1500);\r\n      }\r\n    }\r\n\r\n    function mostrarFeedbackProducto(productoEl:HTMLElement, nombre:string, cantidadProducto:number): void{\r\n      productoEl.classList.remove('producto-agregado-feedback');\r\n      void productoEl.offsetWidth;\r\n      productoEl.classList.add('producto-agregado-feedback');\r\n      setTimeout(()=>productoEl.classList.remove('producto-agregado-feedback'), 900);\r\n\r\n      mostrarFeedbackCarrito(nombre, cantidadProducto);\r\n    }\r\n    constImp['16'] = 0.1379310344827586; //iva, tarifa al 16%,  contratos firmados con el estado antes de ley 1819\r\n    constImp['19'] = 0.1596638655462185; //iva, tarifa al 19%,  tarifa general\r\n\r\n    interface Item {\r\n      id_impuesto: number,\r\n      facturaid: number,\r\n      basegravable: number,\r\n      valorimpuesto: number\r\n    }\r\n    let factimpuestos:Item[] = [];\r\n\r\n    let products:productsapi[]=[], unproducto:productsapi;\r\n    const mapMediospago = new Map();\r\n\r\n    const mediosPagoDBMAP = new Map<string, string>(  //se usa para imprimir los medios de pago en el servidor de impresion\r\n      mediosPagoDB.map(m => [m.id, m.mediopago]) //mediosPagoDB se declara en app.ts el cual viene del <script> en index.php que convierte el array de medios de pago de php a js.\r\n    );\r\n\r\n    (async ()=>{\r\n      products = await POS.productosAPI.getProductosAPI();\r\n      POS.products = products;  //Se expone globalmente\r\n      POS.gestionOtrosProductos.otrosproductos();\r\n    })();\r\n\r\n    /*productos.forEach(producto=>{\r\n      producto.addEventListener('click', (e)=>{\r\n        console.log(producto.dataset.id);\r\n      });\r\n    });*/\r\n    \r\n\r\n\r\n                       /******** *********/\r\n\r\n    selectFacturadorSegunCaja(btnCaja);\r\n    btnCaja.addEventListener('change', (e:Event)=>selectFacturadorSegunCaja(e.target as HTMLSelectElement));\r\n    function selectFacturadorSegunCaja(z:HTMLSelectElement){\r\n      $('#facturador').val(z.options[z.selectedIndex].dataset.idfacturador??'1');\r\n    }\r\n\r\n    POS.gestionClientes.clientes();  //inicializa modulo de clientes\r\n\r\n    //////////// evento al boton modalidad de entrega //////////////\r\n    function tipoEntregaActual(): string {\r\n      return modalidadEntrega.textContent!.replace(': ', '').trim();\r\n    }\r\n\r\n    function actualizarEstadoCarrito(): void {\r\n      if(carritoVacio)carritoVacio.classList.toggle('hidden', carrito.length > 0);\r\n    }\r\n\r\n    function normalizarValorDomicilio(): number {\r\n      const valor = Number(valorDomicilio.value || 0);\r\n      return Number.isFinite(valor) ? valor : 0;\r\n    }\r\n\r\n    function actualizarBotonesEntrega(): void {\r\n      const tipo = tipoEntregaActual();\r\n      const clasesActivo = ['bg-white', 'text-indigo-700', 'shadow-sm'];\r\n      const clasesInactivo = ['text-slate-600', 'hover:bg-white/70', 'hover:text-indigo-700'];\r\n      btnPresencial?.classList.remove(...clasesActivo, ...clasesInactivo);\r\n      btnEntrega?.classList.remove(...clasesActivo, ...clasesInactivo);\r\n      if(tipo === 'Domicilio'){\r\n        btnEntrega?.classList.add(...clasesActivo);\r\n        btnPresencial?.classList.add(...clasesInactivo);\r\n        valorDomicilio?.classList.add('border-indigo-500', 'ring-2', 'ring-indigo-100');\r\n      }else{\r\n        btnPresencial?.classList.add(...clasesActivo);\r\n        btnEntrega?.classList.add(...clasesInactivo);\r\n        valorDomicilio?.classList.remove('border-indigo-500', 'ring-2', 'ring-indigo-100');\r\n      }\r\n    }\r\n\r\n    function cambiarTipoEntrega(tipo: 'Presencial' | 'Domicilio'): void {\r\n      modalidadEntrega.textContent = tipo;\r\n      if(tipo === 'Domicilio' && selectCliente.value === ''){\r\n        msjalertToast('warning', 'Cliente requerido', 'Selecciona un cliente para activar el domicilio.');\r\n        resaltarSelectorCliente();\r\n      }\r\n      printTarifaEnvio();\r\n      valorCarritoTotal();\r\n      actualizarBotonesEntrega();\r\n    }\r\n\r\n    btnPresencial?.addEventListener('click', ()=> cambiarTipoEntrega('Presencial'));\r\n    btnEntrega?.addEventListener('click', ()=> cambiarTipoEntrega('Domicilio'));\r\n\r\n    valorDomicilio?.addEventListener('input', ()=>{\r\n      if(normalizarValorDomicilio() > 0 && tipoEntregaActual() !== 'Domicilio'){\r\n        cambiarTipoEntrega('Domicilio');\r\n        return;\r\n      }\r\n      printTarifaEnvio();\r\n      valorCarritoTotal();\r\n      actualizarBotonesEntrega();\r\n    });\r\n\r\n    valorDomicilio?.addEventListener('blur', ()=>{\r\n      if(tipoEntregaActual() === 'Domicilio' && normalizarValorDomicilio() <= 0){\r\n        valorDomicilio.classList.add('border-amber-400', 'ring-2', 'ring-amber-100');\r\n        setTimeout(()=> valorDomicilio.classList.remove('border-amber-400', 'ring-2', 'ring-amber-100'), 1400);\r\n      }\r\n    });\r\n\r\n    ///////// funcion que imprime el valor de la tarifa segun direccion ///////////\r\n    function printTarifaEnvio():void{\r\n      tarifas = POS.tarifas; //viene de ahelper.clientes.ts\r\n      const selectDir = dirEntrega.options[dirEntrega.selectedIndex];\r\n      document.querySelector('#confirmarDespacho')?.classList.remove('hidden');\r\n      if(tipoEntregaActual() == \"Presencial\"){\r\n        document.querySelector('#confirmarDespacho')?.classList.add('hidden');\r\n        valorTotal.valortarifa = 0;\r\n        valorTotal.idtarifa = 0;\r\n        nombretarifa = ''; \r\n        actualizarBotonesEntrega();\r\n        return; \r\n      }   \r\n\r\n      const valorManual = normalizarValorDomicilio();\r\n      if(valorManual > 0){\r\n        valorTotal.valortarifa = valorManual;\r\n        valorTotal.idtarifa = Number(selectDir?.dataset.idtarifa || 0);\r\n        const objtarifaManual = tarifas.find(tarifa => tarifa.idcliente == selectDir?.dataset.idcliente && tarifa.id == selectDir?.dataset.idtarifa);\r\n        nombretarifa = objtarifaManual?.nombre || 'Domicilio';\r\n        actualizarBotonesEntrega();\r\n        return;\r\n      }\r\n\r\n      if(dirEntrega.selectedIndex == -1){\r\n        document.querySelector('#confirmarDespacho')?.classList.add('hidden');\r\n        valorTotal.valortarifa = 0;\r\n        valorTotal.idtarifa = 0;\r\n        nombretarifa = '';\r\n        actualizarBotonesEntrega();\r\n        return;\r\n      }\r\n\r\n      if(selectDir?.dataset.idtarifa && tipoEntregaActual() == \"Domicilio\"){\r\n        const objtarifa = tarifas.find(tarifa =>{\r\n          if(tarifa.idcliente == selectDir.dataset.idcliente && tarifa.id == selectDir.dataset.idtarifa)return true;\r\n        });\r\n        valorTotal.valortarifa = Number(objtarifa?.valor || 0);\r\n        valorTotal.idtarifa = Number(objtarifa?.id || 0);\r\n        nombretarifa = objtarifa?.nombre || 'Domicilio';\r\n      }\r\n      actualizarBotonesEntrega();\r\n    }\r\n\r\n    actualizarBotonesEntrega();\r\n\r\n    //////////// evento a toda el area de los productos a seleccionar //////////////\r\n    contentproducts?.addEventListener('click', (e:Event)=>{\r\n      const elementProduct = (e.target as HTMLElement)?.closest('.producto');\r\n      if(!elementProduct)return;\r\n\r\n      if((e.target as HTMLElement).closest('#precioadicional')){\r\n        POS.gestionarPreciosAdicionales.abrirDialogo(elementProduct);  //ejecuta los precios adicionales\r\n        return;   \r\n      }\r\n\r\n      if(false && window.innerWidth < 992){\r\n        // Crear popup\r\n        const popup = document.createElement('div');\r\n        popup.className = `popup absolute z-40 right-8 top-1/3 opacity-0 translate-x-0 translate-y-0 transition-all duration-500 w-10 h-10 rounded-full text-center grid place-items-center bg-teal-400 text-white font-semibold text-lg`;\r\n        popup.innerHTML = '';\r\n        elementProduct!.appendChild(popup);\r\n        // Forzar reflow para activar transiciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n\r\n        requestAnimationFrame(() => {\r\n          popup.classList.remove(\"opacity-0\", \"translate-y-0\", \"translate-x-0\");\r\n          popup.classList.add(\"opacity-100\", \"-translate-y-14\", \"translate-x-10\");\r\n        });\r\n        const popupx = document.querySelectorAll('.popup');\r\n        setTimeout(() => {popupx.forEach(t=>{t.remove();});}, 2500);\r\n      }\r\n\r\n      const precio = products.find(x=>x.id == (elementProduct as HTMLElement).dataset.id)?.precio_venta;\r\n      const productoConfigurado = structuredClone(products.find(x=>x.id == (elementProduct as HTMLElement).dataset.id)!);\r\n      filtrarInsumos(productoConfigurado);\r\n      actualizarCarrito((elementProduct as HTMLElement).dataset.id!, 1, true, true, precio, productoConfigurado);\r\n      const productoAgregado = carrito.find(x=>x.idproducto == (elementProduct as HTMLElement).dataset.id && x.valorunidad == precio && mismaConfiguracion(x, productoConfigurado));\r\n      const nombre = (elementProduct.querySelector('.card-producto')?.textContent || 'Producto').trim();\r\n      mostrarFeedbackProducto(elementProduct as HTMLElement, nombre, productoAgregado?.stock ?? 1);\r\n    });\r\n    \r\n\r\n    function printProduct(id:string, precio:string, index:number){ //recibe el id del producto\r\n      //const indice = carrito.findIndex(x => x.idproducto == id && x.valorunidad == precio);\r\n      //const uncarrito = carrito.find(x=>x.idproducto==id&&x.valorunidad==precio)!;\r\n    \r\n      //if(indice === -1)return;\r\n      const uncarrito = carrito[index];\r\n\r\n      const tr = document.createElement('TR');\r\n      tr.classList.add(\r\n          'productselect',\r\n          'border-b',\r\n          'border-slate-100',\r\n          'hover:bg-slate-50',\r\n          'transition-colors'\r\n      );\r\n      tr.dataset.id = `${id}`;\r\n      tr.dataset.precio = precio;\r\n      tr.dataset.indexcarrito = index+'';\r\n      tr.insertAdjacentHTML('afterbegin',    \r\n        `<td class=\"pl-4 pr-3 py-3 align-middle text-left\">\r\n            <p class=\"\r\n                nombreproducto\r\n                text-xl\r\n                font-semibold\r\n                text-slate-800\r\n                leading-7\r\n                break-words\r\n                max-w-[260px]\r\n            \">\r\n                ${uncarrito?.nombreproducto}\r\n            </p>\r\n        </td>\r\n        <td class=\"px-2 py-3 align-middle w-36 min-w-[9rem]\">\r\n          <div class=\"flex items-center justify-center gap-1.5 min-w-max\">\r\n            <button type=\"button\" class=\"w-7 h-7 shrink-0 bg-indigo-700 text-white rounded-full flex items-center justify-center\">\r\n              <span class=\"menos material-symbols-outlined text-base\">remove</span>\r\n            </button>\r\n            <input\r\n              type=\"text\"\r\n              class=\"\r\n                  inputcantidad\r\n                  min-w-[6ch]\r\n                  max-w-[12ch]\r\n                  h-9\r\n                  px-2\r\n                  rounded-lg \r\n                  border\r\n                  border-slate-300\r\n                  text-center\r\n                  font-semibold\r\n                  text-xl\r\n                  outline-none \r\n                  focus:border-indigo-500\r\n              \"\r\n              value=\"${uncarrito.stock}\"\r\n              style=\"width: ${Math.min(Math.max(String(uncarrito.stock || 0).length + 2, 6), 12)}ch\"\r\n              title=\"${uncarrito.stock}\"\r\n            >\r\n            <button type=\"button\" class=\"w-7 h-7 shrink-0 bg-indigo-700 text-white rounded-full flex items-center justify-center\">\r\n              <span class=\"mas material-symbols-outlined text-base\">add</span>\r\n            </button>\r\n          </div>\r\n        </td>\r\n        <td class=\"px-2 py-3 text-center align-middle w-24 text-xl font-medium text-slate-700\">$${Number(uncarrito?.valorunidad).toLocaleString()}</td>\r\n        <td class=\"px-2 py-3 text-center align-middle w-28 text-xl font-bold text-slate-900\">$${Number(uncarrito?.total).toLocaleString()}</td>\r\n        <td class=\"px-2 py-3 text-center align-middle w-12 accionestd\">\r\n            <div class=\"flex justify-center\">\r\n                <button\r\n                    class=\"\r\n                        eliminarProducto\r\n                        flex\r\n                        items-center\r\n                        justify-center\r\n                        w-9\r\n                        h-9\r\n                        rounded-lg\r\n                        border\r\n                        border-red-200\r\n                        bg-red-50\r\n                        text-red-500\r\n                        transition-all\r\n                        duration-300\r\n                        hover:bg-red-600\r\n                        hover:text-white\r\n                        hover:border-red-600\r\n                        hover:shadow-md\r\n                    \"\r\n                >\r\n                    <i class=\"fa-solid fa-trash-can text-base\"></i>\r\n                </button>\r\n            </div>\r\n        </td>\r\n        `);\r\n      tablaventa?.appendChild(tr);\r\n      actualizarEstadoCarrito();\r\n    } //oninput=\"this.value = parseInt(this.value.replace(/[,.]/g, '')||1)\"\r\n\r\n\r\n    function actualizarCarrito(id:string, cantidad:number, control:boolean, stateinput:boolean, precio:string = '0', productoConfigurado:productsapi|null){\r\n      ///limpiar el campo de buscar producto\r\n      POS.reiniciarCatalogoVentas?.();\r\n      const index = carrito.findIndex(x=>x.idproducto==id && x.valorunidad == precio && mismaConfiguracion(x, productoConfigurado!)); //devuelve el index si el producto existe\r\n      \r\n      if(index>-1){\r\n        if(cantidad < 0 && (carrito[index].stock + cantidad)<0){\r\n          cantidad = 0;\r\n          carrito[index].stock = 0;\r\n          carrito[index].total = 0;\r\n        }\r\n        if(control){ //cuando el producto se agrega desde la lista de productos\r\n          carrito[index].stock += cantidad;\r\n        }else{ //cuando el producto se agrega por el input cantidad\r\n          carrito[index].stock = cantidad;\r\n        }\r\n       \r\n        \r\n        carrito[index].subtotal = parseInt(carrito[index].valorunidad)*carrito[index].stock;\r\n        carrito[index].total = carrito[index].subtotal;\r\n        carrito[index].valorcomision = (carrito[index].subtotal*carrito[index].percentcomision)/100;\r\n        //calculo del impuesto y base por producto en el carrito deventas\r\n        carrito[index].valorimp = parseFloat((carrito[index].total*constImp[carrito[index].impuesto??0]).toFixed(3));\r\n        carrito[index].base = parseFloat((carrito[index].total-carrito[index].valorimp).toFixed(3));\r\n\r\n        valorCarritoTotal();\r\n        const inputCantidad = tablaventa?.querySelector(`TR[data-indexcarrito=\"${index}\"] .inputcantidad`) as HTMLInputElement;\r\n        if(inputCantidad){\r\n          if(stateinput)inputCantidad.value = carrito[index].stock+'';\r\n          ajustarAnchoCantidad(inputCantidad, carrito[index].stock);\r\n        }\r\n        (tablaventa?.querySelector(`TR[data-indexcarrito=\"${index}\"]`)?.children?.[3] as HTMLElement).textContent = \"$\"+carrito[index].total.toLocaleString();\r\n      }else{  //agregar a carrito si el producto no esta agregado en carrito, se agrega por primera vez\r\n        const producto = products.find(x=>x.id==id)!; //products es el arreglo de todos los productos traido por api\r\n        if(cantidad < 0)cantidad = 0;\r\n        const productovalorimp = (Number(precio)*cantidad)*constImp[producto.impuesto??'0']; //si producto.impuesto es null toma el valor de cero\r\n        const productototal = Number(precio)*cantidad;\r\n\r\n        //varia segun la prioridad de la comision\r\n        if(producto.prioridadcomision === '0'){  //si el porcentaje es por usuario\r\n          //producto.percentcomision = Number(percentComisionUser);  ////porcentaje de comision del usuario logueado\r\n          producto.percentcomision = Number(selectVendedor.options[selectVendedor.selectedIndex].dataset.comision);\r\n        }\r\n        const valorcomision:number = (productototal*producto.percentcomision)/100;\r\n\r\n        //obtener nombre de insumo cuando es radiobutton o checkbox\r\n        let insumos = productoConfigurado?.insumos||[];\r\n        //obtener el ultimo insumo de seleccion unica\r\n        let seleccionUnica:insumo|undefined;\r\n        for(let i = insumos.length-1; i>=0; i--)\r\n          if(insumos[i].seleccionado === \"1\" &&insumos[i].grupos_insumos?.tipo === \"0\"){\r\n            seleccionUnica = insumos[i];\r\n            break\r\n          }\r\n        \r\n        var a:{id:string, idproducto:string, tipoproducto:string, tipoproduccion:string, idcategoria: string, nombreproducto: string, rendimientoestandar:string, foto:string, costo:string, valorunidad: string, stock: number, promediostock: number, prioridadcomision:string, percentcomision: number, valorcomision: number, subtotal: number, base:number, impuesto:string, valorimp:number, descuento:number, total:number, insumos:insumo[]} = {\r\n          id: '',\r\n          idproducto: producto?.id!,\r\n          tipoproducto: producto.tipoproducto,\r\n          tipoproduccion: producto.tipoproduccion,\r\n          idcategoria: producto.idcategoria,\r\n          nombreproducto:`${producto.nombre} ${seleccionUnica?.nombre?'('+seleccionUnica.nombre+')':''}`,\r\n          rendimientoestandar: producto.rendimientoestandar,\r\n          foto: producto.foto,\r\n          costo: producto.precio_compra,\r\n          valorunidad: precio,\r\n          stock: cantidad,\r\n          promediostock: Number(producto.promediostock),\r\n          prioridadcomision: producto.prioridadcomision,\r\n          percentcomision: Number(producto.percentcomision),\r\n          valorcomision: valorcomision,\r\n          subtotal: productototal, //este es el subtotal del producto\r\n          base: productototal-productovalorimp,\r\n          impuesto: producto.impuesto, //porcentaje de impuesto, es null si es excluido de iva\r\n          valorimp: productovalorimp,\r\n          descuento: 0,\r\n          total: productototal, //valorunidad x cantidad\r\n          insumos: productoConfigurado?.insumos??[]\r\n        }\r\n        \r\n        carrito = [...carrito, a];\r\n        const indice = carrito.length - 1;\r\n        valorCarritoTotal();\r\n        printProduct(id, precio, indice);\r\n        POS.carrito = carrito;\r\n      }\r\n    }\r\n\r\n\r\n    function mismaConfiguracion(productCarrito: any, producto2: productsapi):boolean {\r\n      const mapaProduct2 = new Map(producto2.insumos.map((ins:any) => [ins.id_subproducto, ins]));\r\n      // Deben ser el mismo producto\r\n      if(productCarrito.idproducto !== producto2.id)return false;\r\n\r\n      // Deben tener la misma cantidad de insumos\r\n      if(productCarrito.insumos.length !== producto2.insumos.length)return false;\r\n\r\n      for (const insumo1 of productCarrito.insumos) {\r\n        //const insumo2 = producto2.insumos.find((x:any) => x.id_subproducto == insumo1.id_subproducto);\r\n        const insumo2:any = mapaProduct2.get(insumo1.id_subproducto);\r\n        if (!insumo2)return false;\r\n        // Comparar selecciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n\r\n        if (Number(insumo1.seleccionado) !== Number(insumo2.seleccionado))\r\n            return false;\r\n        // Comparar cantidad\r\n        if (Number(insumo1.cantidadsubproducto) !== Number(insumo2.cantidadsubproducto))\r\n            return false;\r\n      }\r\n      return true;\r\n    }\r\n\r\n    //evento al select del vendedor\r\n    selectVendedor.addEventListener('change', (e:Event)=>{\r\n      const target = e.target as HTMLSelectElement;\r\n      const comisionUser:number = Number(target.selectedOptions[0].dataset.comision);\r\n      carrito.forEach(x=>{ \r\n        if(x.prioridadcomision === '0'){\r\n          x.percentcomision = comisionUser;\r\n          x.valorcomision = (x.total*comisionUser)/100;\r\n        }\r\n      });\r\n      valorCarritoTotal();\r\n    });\r\n\r\n    ////////////////////// valores finales subtotal y total ////////////////////////\r\n    function valorCarritoTotal(){\r\n      actualizarEstadoCarrito();\r\n      if(!carrito.length){\r\n        valorTotal.subtotal = 0;\r\n        valorTotal.base = 0;\r\n        valorTotal.valorimpuestototal = 0;\r\n        valorTotal.dctox100 = 0;\r\n        valorTotal.descuento = 0;\r\n        valorTotal.valortarifa = 0;\r\n        valorTotal.total = 0;\r\n        document.querySelector('#subTotal')!.textContent = '$0';\r\n        (document.querySelector('#impuesto') as HTMLElement).textContent = '$0';\r\n        (document.querySelector('#descuento') as HTMLElement).textContent = '$0';\r\n        (document.querySelector('#valorTarifa') as HTMLElement).textContent = '$0';\r\n        document.querySelector('#total')!.textContent = '$0';\r\n        totalunidades.textContent = '0';\r\n        totalunidades.title = '0';\r\n        actualizarBadgeCarritoMovil(0);\r\n        return;\r\n      }\r\n      if(tipoEntregaActual() == \"Domicilio\")printTarifaEnvio();\r\n      valorTotal.valorgananciauser = 0;\r\n      //calcular el impuesto discriminado por tarifa\r\n      const idimpuesto: Record<string, number> = {'0': 1, '5': 2, '16': 3, '19': 4, 'excluido': 5, '8': 6 };\r\n      const objbase:{'0':number, '5':number, '16':number, '19':number, 'excluido':number, '8':number} = {'0': 0, '5': 0, '16': 0, '19': 0, 'excluido':0, '8': 0};\r\n\r\n      const mapImpuesto = new Map();\r\n      carrito.forEach(x=>{\r\n        if(x.impuesto){\r\n          if(mapImpuesto.has(x.impuesto)){\r\n            const valor = mapImpuesto.get(x.impuesto) + x.total*constImp[x.impuesto];\r\n            mapImpuesto.set(x.impuesto, valor);\r\n          }else{\r\n            mapImpuesto.set(x.impuesto, x.total*constImp[x.impuesto]);\r\n          }\r\n        }\r\n        if(x.impuesto == null)x.impuesto = \"excluido\";\r\n        objbase[x.impuesto as keyof typeof objbase] += x.base;\r\n        const impValor = mapImpuesto.get(x.impuesto)??0;\r\n        const index = factimpuestos.findIndex(Obj=>Obj.id_impuesto == idimpuesto[x.impuesto]);\r\n        if(index!=-1){ //si existe remplazar obj\r\n          factimpuestos[index] = {id_impuesto:idimpuesto[x.impuesto], facturaid:0, basegravable:objbase[x.impuesto as keyof typeof objbase], valorimpuesto: impValor};\r\n        }else{\r\n          factimpuestos = [...factimpuestos, {id_impuesto:idimpuesto[x.impuesto], facturaid:0, basegravable:objbase[x.impuesto as keyof typeof objbase], valorimpuesto: impValor}];\r\n        }\r\n        \r\n        //calcular valor total de comision para el usuario\r\n        valorTotal.valorgananciauser += Number(x.valorcomision);\r\n      });\r\n     \r\n      //Valor del impuesto total de todos los productos, es decir de la factura;\r\n      let valorTotalImp:number = 0;\r\n      for(let valorImp of mapImpuesto.values())valorTotalImp += valorImp;\r\n      \r\n      valorTotal.valorimpuestototal = parseFloat(valorTotalImp.toFixed(3));  //valor del impuesto total factura de todos los productos\r\n\r\n      valorTotal.subtotal = carrito.reduce((total, x)=>x.total+total, 0);\r\n      valorTotal.porcentgananciauser =  (100*valorTotal.valorgananciauser)/valorTotal.subtotal;\r\n      valorTotal.base = valorTotal.subtotal - valorTotal.valorimpuestototal;  //valor de la base total factura de todos los productos\r\n      valorTotal.total = valorTotal.subtotal + valorTotal.valortarifa - valorTotal.descuento;\r\n      document.querySelector('#subTotal')!.textContent = '$'+valorTotal.subtotal.toLocaleString();\r\n      (document.querySelector('#impuesto') as HTMLElement).textContent = '$'+valorTotalImp.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});\r\n      (document.querySelector('#valorTarifa') as HTMLElement).textContent = '$'+valorTotal.valortarifa.toLocaleString();\r\n      document.querySelector('#total')!.textContent = '$ '+valorTotal.total.toLocaleString();\r\n      // cantidad total de productos\r\n      const cantidadTotalProductos = carrito.reduce((total, producto)=>producto.stock+total, 0);\r\n      totalunidades.textContent = formatCantidadBadge(cantidadTotalProductos);\r\n      totalunidades.title = cantidadTotalProductos.toLocaleString('es-CO');\r\n      actualizarBadgeCarritoMovil(cantidadTotalProductos);\r\n    }\r\n\r\n\r\n    /////////////////////// evento a la tabla de productos de venta (carrito) //////////////////////////\r\n    tablaventa?.addEventListener('click', (e:Event)=>{\r\n      const elementProduct = (e.target as HTMLElement)?.closest('.productselect');\r\n      if(!elementProduct)return;\r\n      const idProduct = (elementProduct as HTMLElement).dataset.id!;\r\n      const precio = (elementProduct as HTMLElement).dataset.precio!;\r\n      indexcarrito = Number((elementProduct as HTMLElement).dataset.indexcarrito!);\r\n      //const productoCarrito = carrito.find(x=>x.idproducto==idProduct && x.valorunidad==precio);\r\n      let productoCarrito = carrito[indexcarrito];\r\n\r\n      /*for (let i = 0; i < carrito.length; i++) {\r\n        const item = carrito[i];\r\n        if (item.idproducto == idProduct && item.valorunidad == precio) {\r\n            indiceCarrito = i;\r\n            productoCarrito = item;\r\n            break;\r\n        }\r\n      }*/\r\n\r\n\r\n      if((e.target as HTMLElement).classList.contains('nombreproducto')){\r\n        const inputMerma = document.querySelector('#inputMerma') as HTMLInputElement;\r\n        inputMerma.value = '';\r\n        if(getParam.activar_calculadira_de_merma_en_modulo_de_ventas.valor_final == '1'){\r\n          miDialogoCalculadora.showModal();\r\n          inputMerma.focus();\r\n          document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n      }\r\n      \r\n      if((e.target as HTMLElement).classList.contains('menos')){\r\n        editarCantidad(indexcarrito, productoCarrito!.stock-1, false, true);\r\n        //actualizarCarrito(idProduct, productoCarrito!.stock-1, false, true, productoCarrito?.valorunidad, null);\r\n      }\r\n      if((e.target as HTMLElement).classList.contains('mas')){\r\n        editarCantidad(indexcarrito, productoCarrito!.stock+1, false, true);\r\n        //actualizarCarrito(idProduct, productoCarrito!.stock+1, false, true, productoCarrito?.valorunidad, null);\r\n      }\r\n      if((e.target as HTMLElement).classList.contains('eliminarProducto') || (e.target as HTMLElement).tagName == \"I\"){\r\n        //carrito = carrito.filter(x=>x.idproducto != idProduct || x.valorunidad != precio);\r\n        carrito.splice(indexcarrito, 1);\r\n        while(tablaventa.firstChild)tablaventa.removeChild(tablaventa.firstChild);\r\n        carrito.forEach((item, i) =>printProduct(item.idproducto, item.valorunidad, i));\r\n        valorCarritoTotal();\r\n        //tablaventa?.querySelector(`TR[data-indexcarrito=\"${indexcarrito}\"]`)?.remove();\r\n      }\r\n    });\r\n\r\n\r\n    tablaventa?.addEventListener('input', e=>{\r\n      const input = e.target as HTMLInputElement;\r\n      if (!input.classList.contains('inputcantidad')) return;\r\n      const fila = input?.closest('.productselect') as HTMLTableRowElement;\r\n      const idProduct = fila.dataset.id!;\r\n      const precio = fila.dataset.precio!;\r\n      indexcarrito = Number(fila.dataset.indexcarrito!);\r\n      //const productoCarrito = carrito.find(x=>x.idproducto==idProduct && x.valorunidad==precio);\r\n\r\n      let val = input.value;\r\n      val = val.replace(/[^0-9.]/g, '');\r\n      const partes = val.split('.');\r\n      if(partes.length > 2)val = partes[0]+'.'+partes.slice(1).join('');\r\n      if (val.startsWith('.'))val = '1';\r\n      if (val === '' || isNaN(parseFloat(val))) val = '';\r\n\r\n      input.value = val;\r\n      ajustarAnchoCantidad(input, input.value || 0);\r\n      editarCantidad(indexcarrito, Number(input.value), false, false);\r\n      //actualizarCarrito(idProduct, Number(input.value), false, false,  productoCarrito?.valorunidad, null);\r\n    });\r\n\r\n\r\n    function editarCantidad(index:number, cantidad:number, control:boolean, stateinput:boolean){\r\n        if(cantidad < 0 && (carrito[index].stock + cantidad)<0){\r\n          cantidad = 0;\r\n          carrito[index].stock = 0;\r\n          carrito[index].total = 0;\r\n        }\r\n        if(control){ //cuando el producto se agrega desde la lista de productos\r\n          carrito[index].stock += cantidad;\r\n        }else{ //cuando el producto se agrega por el input cantidad\r\n          carrito[index].stock = cantidad;\r\n        }\r\n        \r\n        carrito[index].subtotal = parseInt(carrito[index].valorunidad)*carrito[index].stock;\r\n        carrito[index].total = carrito[index].subtotal;\r\n        carrito[index].valorcomision = (carrito[index].subtotal*carrito[index].percentcomision)/100;\r\n        //calculo del impuesto y base por producto en el carrito de ventas\r\n        carrito[index].valorimp = parseFloat((carrito[index].total*constImp[carrito[index].impuesto??0]).toFixed(3));\r\n        carrito[index].base = parseFloat((carrito[index].total-carrito[index].valorimp).toFixed(3));\r\n\r\n        valorCarritoTotal();\r\n        const inputCantidad = tablaventa?.querySelector(`TR[data-indexcarrito=\"${index}\"] .inputcantidad`) as HTMLInputElement;\r\n        if(inputCantidad){\r\n          if(stateinput)inputCantidad.value = carrito[index].stock+'';\r\n          ajustarAnchoCantidad(inputCantidad, carrito[index].stock);\r\n        }\r\n        (tablaventa?.querySelector(`TR[data-indexcarrito=\"${index}\"]`)?.children?.[3] as HTMLElement).textContent = \"$\"+carrito[index].total.toLocaleString();\r\n    }\r\n\r\n\r\n    //calculadora que se ejecuta cuando se da clic sobre el nombre del producto\r\n    document.querySelector('#btnMermaCantidad')?.addEventListener('click', (e:Event)=>{\r\n      const inputMerma = (document.querySelector('#inputMerma') as HTMLInputElement).value;\r\n      const {stock} = carrito[indexcarrito];\r\n      let nuevaCantidad = stock - Number(inputMerma);\r\n      if(nuevaCantidad<0)nuevaCantidad=0;\r\n      (tablaventa?.querySelector(`TR[data-indexcarrito=\"${indexcarrito}\"] .inputcantidad`) as HTMLInputElement).value = nuevaCantidad+'';\r\n      editarCantidad(indexcarrito, nuevaCantidad, false, false);\r\n      miDialogoCalculadora.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    /*btnvaciar?.addEventListener('click', ()=>{\r\n      if(carrito.length){\r\n        miDialogoVaciar.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    });*/\r\n\r\n    btnguardar?.addEventListener('click', ()=>{\r\n      if(carrito.length && valorTotal.total>0){\r\n        miDialogoGuardar.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    });\r\n\r\n    btnaplicarcredito?.addEventListener('click', ()=>{\r\n      if(tipoEntregaActual() === \"Domicilio\" && (selectCliente.value =='' || !dirEntrega.value) || selectCliente.value ==''){\r\n        msjalertToast('warning', 'Cliente requerido', 'Selecciona un cliente y una direccion antes de registrar la venta a credito.');\r\n        resaltarSelectorCliente();\r\n        return;\r\n      }\r\n      if(carrito.length && valorTotal.total>0){\r\n        document.querySelector('.Efectivo')?.removeAttribute('readonly');\r\n        document.querySelector('#inputscreditos')?.classList.add('flex');\r\n        document.querySelector('#inputscreditos')?.classList.remove('hidden');\r\n        if(tipoventa == \"Contado\"){\r\n          mapMediospago.clear();\r\n          $('.mediopago').val(0);\r\n        }\r\n        tipoventa = \"Credito\";\r\n        POS.tipoventa = tipoventa;\r\n        POS.gestionSubirModalPagar.subirModalPagar();\r\n        //miDialogoCredito.showModal();\r\n        miDialogoFacturar.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    });\r\n\r\n    btnfacturar?.addEventListener('click', ()=>{\r\n      if(tipoEntregaActual() === \"Domicilio\" && (selectCliente.value =='' || !dirEntrega.value)){\r\n        msjAlert('error', 'Cliente o direccion no seleccionado', (document.querySelector('#divmsjalerta1') as HTMLElement));\r\n        resaltarSelectorCliente();\r\n        return;\r\n      }\r\n      \r\n      if(tipoEntregaActual() == \"Domicilio\")document.querySelector('#confirmarDespacho')?.classList.remove('hidden');\r\n\r\n      if(carrito.length && valorTotal.total>0){\r\n        document.querySelector('.Efectivo')?.setAttribute('readonly', 'true');\r\n        document.querySelector('#inputscreditos')?.classList.add('hidden');\r\n        document.querySelector('#inputscreditos')?.classList.remove('flex');\r\n        tipoventa = \"Contado\";\r\n        POS.tipoventa = tipoventa;\r\n        POS.gestionSubirModalPagar.subirModalPagar();\r\n        miDialogoFacturar.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    });\r\n\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      const f = event.target;\r\n      if (f === miDialogoDescuento || f === miDialogoCredito || f === miDialogoGuardar || f === miDialogoFacturar || f === miDialogoAddCliente || f === miDialogoOtrosProductos || f === miDialogoFacturarA || /*f === miDialogoAddDir ||*/ f=== miDialogoPreciosAdicionales || f === miDialogoCalculadora || (f as HTMLInputElement).closest('.salir') || (f as HTMLInputElement).closest('.novaciar') || (f as HTMLInputElement).closest('.cotizacion') || (f as HTMLInputElement).closest('.remision') || (f as HTMLInputElement).closest('.siguardar') || (f as HTMLButtonElement).value == \"Cancelar\" || /*(f as HTMLButtonElement).value == \"Seleccionar\" ||*/ (f as HTMLButtonElement).classList.contains('btnCerrarPreciosAdicionales') ) {\r\n        miDialogoDescuento.close();\r\n        //miDialogoCredito.close();\r\n        miDialogoGuardar.close();\r\n        miDialogoFacturar.close();\r\n        miDialogoAddCliente.close();\r\n        //miDialogoAddDir.close();\r\n        miDialogoFacturarA.close();\r\n        miDialogoOtrosProductos.close();\r\n        miDialogoPreciosAdicionales.close();\r\n        miDialogoCalculadora.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        if((f as HTMLInputElement).closest('.cotizacion')){\r\n          tipoventa = \"\";\r\n          procesarpedido('Guardado', '1');\r\n        }\r\n        if((f as HTMLInputElement).closest('.remision')){\r\n          tipoventa = \"\";\r\n          procesarpedido('Remision', '0');\r\n        }\r\n        //if((f as HTMLInputElement).closest('.sivaciar'))vaciarventa();\r\n      }\r\n    }\r\n\r\n    function vaciarventa():void\r\n    {\r\n      if(datosfactura?.id)datosfactura.id = '';\r\n      (document.querySelector('#formFacturarA') as HTMLFormElement)?.reset();\r\n      (document.querySelector('#formfacturar') as HTMLFormElement)?.reset();\r\n      (document.querySelector('#formAddCliente') as HTMLFormElement).reset();\r\n      (document.querySelector('#badgeEstado') as HTMLParagraphElement).textContent = 'SIN CLIENTE';\r\n      (document.querySelector('#badgeEstado') as HTMLParagraphElement).classList.remove('bg-green-100', 'text-green-600');\r\n      (document.querySelector('#badgeEstado') as HTMLParagraphElement).classList.add('bg-gray-100', 'text-gray-700');\r\n      (document.querySelector('#resumenCliente') as HTMLParagraphElement).textContent = \"Seleccionar cliente\";\r\n      mapMediospago.clear();\r\n      $('.mediopago').val(0);\r\n      carrito.length = 0;\r\n      factimpuestos.length = 0;\r\n      for(const key in valorTotal)valorTotal[key as keyof typeof valorTotal] = 0; //reiniciar objeto\r\n\r\n      history.replaceState({}, \"\", \"/admin/ventas\");\r\n      while(tablaventa?.firstChild)tablaventa.removeChild(tablaventa?.firstChild);\r\n      actualizarEstadoCarrito();\r\n      (document.querySelector('#npedido') as HTMLInputElement).value = '';\r\n      document.querySelector('#subTotal')!.textContent = '$'+0;\r\n      document.querySelector('#impuesto')!.textContent = '$'+0;\r\n      (document.querySelector('#descuento') as HTMLElement).textContent = '$'+0;\r\n      (document.querySelector('#valorTarifa') as HTMLElement).textContent = '$'+0;\r\n      document.querySelector('#total')!.textContent = '$'+0;\r\n      valorDomicilio.value = '';\r\n      modalidadEntrega.textContent = 'Presencial';\r\n      document.querySelector('#confirmarDespacho')?.classList.add('hidden');\r\n      $('#selectCliente').val('').trigger('change');   //aqui tambien se reinicia la elemento del valor de la tarifa\r\n      (document.querySelector('#valorTarifa') as HTMLElement).textContent = '$'+0;\r\n      document.querySelector('#total')!.textContent = '$'+0;\r\n      //volver a mapear los productos con los valores originales de inventario\r\n\r\n      //actualizar DOM\r\n      for(const prod of products){\r\n          const item = POS.hackerList.get('id', prod.id)[0];\r\n          prod.precio_venta = prod.precio_original!;\r\n          if(item)item.elm.querySelector('.precioVenta').textContent = '$'+Number(prod.precio_venta).toLocaleString();\r\n      }\r\n      POS.reiniciarCatalogoVentas?.();\r\n    }\r\n\r\n\r\n    ////////////////// evento al bton pagar del modal facturar //////////////////////\r\n    document.querySelector('#formfacturar')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      if(valorTotal.total <0 || valorTotal.subtotal <0){\r\n        msjAlert('error', 'No se puede procesar pago con $0', (document.querySelector('#divmsjalertaprocesarpago') as HTMLElement));\r\n        return;\r\n      }\r\n\r\n      //calcular si el totoal de los medios de pago es menor al abono inicial, abortar pago...\r\n      let totalMediosPago:number = 0;\r\n      for(let value of mapMediospago.values())totalMediosPago+=value;\r\n      if(totalMediosPago<POS.gestionSubirModalPagar.valoresCredito.abonoinicial){\r\n        POS.gestionSubirModalPagar.mostrarMensajeMetodosPago?.();\r\n        return;\r\n      }\r\n\r\n      if(tipoventa == \"Credito\" && (isNaN(POS.gestionSubirModalPagar.valoresCredito.cantidadcuotas)||POS.gestionSubirModalPagar.valoresCredito.cantidadcuotas<=0)){\r\n        msjAlert('error', 'Plazo de cuotas no especificado', (document.querySelector('#divmsjalertaprocesarpago') as HTMLElement));\r\n        return;\r\n      }\r\n  \r\n      btnPagar.disabled = true;\r\n      btnPagar.value = 'Procesando...';\r\n      procesarpedido('Paga', '0');\r\n    });\r\n\r\n    async function procesarpedido(estado:string, ctz:string){\r\n      const imprimir = document.querySelector('input[name=\"imprimir\"]:checked') as HTMLInputElement;\r\n      const despachar = document.querySelector('#despachar') as HTMLInputElement;\r\n      const valoresCredito = POS.gestionSubirModalPagar.valoresCredito;\r\n      const tipoEntrega = tipoEntregaActual();\r\n      const datos = new FormData();\r\n      datos.append('id', datosfactura?.id??'');\r\n      datos.append('idemisor', btnCaja.selectedOptions[0].dataset.idemisor??'');\r\n      datos.append('idcliente', (document.querySelector('#selectCliente') as HTMLSelectElement).value || '1');\r\n      datos.append('idvendedor', selectVendedor.value);\r\n      datos.append('idcaja', btnCaja.value);\r\n      datos.append('idconsecutivo', btnTipoFacturador.value);\r\n      datos.append('iddireccion', dirEntrega.value);\r\n      datos.append('idtarifazona', valorTotal.idtarifa+'');\r\n      datos.append('idcanaldeventa', (document.querySelector('#canalVenta') as HTMLSelectElement)?.value??'1');\r\n      datos.append('cliente', selectCliente.value==''?'N/A':selectCliente.options[selectCliente.selectedIndex].textContent!);\r\n      datos.append('vendedor', $('#vendedor option:selected').text());\r\n      datos.append('caja', (document.querySelector('#caja option:checked') as HTMLSelectElement).textContent!);\r\n      datos.append('tipofacturador', btnTipoFacturador.options[btnTipoFacturador.selectedIndex].textContent!);\r\n      datos.append('direccion', dirEntrega.options[dirEntrega.selectedIndex]?.text??'');\r\n      datos.append('tarifazona', nombretarifa||'');\r\n      datos.append('carrito', JSON.stringify(carrito.filter(x=>x.stock>0)));  //envio de todos los productos con sus cantidades\r\n      datos.append('totalunidades', totalunidades.textContent!);\r\n      //datos.append('mediosPago', JSON.stringify(Object.fromEntries(mapMediospago)));\r\n      datos.append('mediosPago', JSON.stringify(Array.from(mapMediospago, ([idmediopago, valor])=>({idmediopago, id_factura:0, valor}))));\r\n      datos.append('factimpuestos', JSON.stringify(factimpuestos));\r\n      datos.append('recibido', document.querySelector<HTMLInputElement>('#recibio')!.value);\r\n      datos.append('transaccion', '');\r\n      datos.append('tipoventa', tipoventa);\r\n      datos.append('valoresCredito', JSON.stringify(valoresCredito));\r\n      datos.append('cotizacion', ctz);  //1= cotizacion, 0 = no cotizacion pagada.\r\n      datos.append('remision', estado=='Remision'?'1':'0');  //1= cotizacion, 0 = no cotizacion pagada.\r\n      datos.append('estado', estado);\r\n      datos.append('porcentgananciauser', valorTotal.porcentgananciauser.toFixed(2));\r\n      datos.append('valorgananciauser', valorTotal.valorgananciauser.toFixed(2));\r\n      datos.append('subtotal', valorTotal.subtotal+'');\r\n      datos.append('base', valorTotal.base.toFixed(3));\r\n      datos.append('valorimpuestototal', valorTotal.valorimpuestototal+''); //valor total del impuesto. \r\n      datos.append('dctox100',valorTotal.dctox100+'');\r\n      datos.append('descuento',valorTotal.descuento+'');\r\n      datos.append('total', valorTotal.total.toString());\r\n      datos.append('observacion', document.querySelector<HTMLTextAreaElement>('#observacion')!.value);\r\n      datos.append('departamento', '');\r\n      datos.append('ciudad', (document.querySelector('#ciudad') as HTMLInputElement).value);\r\n      datos.append('entrega', tipoEntrega);\r\n      datos.append('entregado', estado=='Paga'&&tipoEntrega=='Domicilio'?(despachar.checked?'1':'0'):estado=='Paga'&&tipoEntrega=='Presencial'?'1':'0'); //si es remision no se ha entregado, si es pago y entrega a domicilio se define segun el checkbox de despachar, si es pago y entrega presencial se marca como entregado\r\n      datos.append('valortarifa', valorTotal.valortarifa+'');\r\n      datos.append('datosAdquiriente', JSON.stringify(POS.gestionarAdquiriente.datosAdquiriente));\r\n      datos.append('opc1', '');\r\n      datos.append('opc2', '');\r\n  \r\n      try {\r\n          const url = \"/admin/api/facturar\";  //va al controlador ventascontrolador\r\n          const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n          const resultado = await respuesta.json();\r\n\r\n          if(resultado.exito !== undefined){\r\n            if(estado == \"Paga\"){\r\n              resultado.dataInvoice.items = carrito.filter(x=>x.stock>0);\r\n              resultado.dataInvoice.mediospago = Array.from(mapMediospago, ([idmediopago, valor])=>({\r\n                idmediopago,\r\n                mediopago: mediosPagoDBMAP.get(idmediopago),\r\n                valor,\r\n              }));\r\n            }\r\n\r\n            limpiarFormFacturar();\r\n            msjalertToast('success', 'Exito!', resultado.exito[0]);\r\n            //ENVIAR FACTURA A DIAN SI ES FACTURACION ELECTRONICA\r\n            if(btnTipoFacturador.options[btnTipoFacturador.selectedIndex].dataset.idtipofacturador == '1'){\r\n              const resDian = await POS.sendInvoiceAPI.sendInvoice(resultado.idfactura);\r\n              POS.gestionarAdquiriente.datosAdquiriente = {}; //reiniciar datos de adquiriente cada vez que se facture electronicamente\r\n              resultado.dataInvoice.cufe = resDian.cufe;\r\n              resultado.dataInvoice.link = resDian.link;\r\n              console.log(resDian);\r\n            }\r\n            //IMPRIMIR TICKET POS\r\n            if(resultado.idfactura && imprimir.value === '1')printTicketPOS(resultado.idfactura, resultado.dataInvoice);\r\n            vaciarventa();\r\n          }else{\r\n            limpiarFormFacturar();\r\n            msjalertToast('error', 'Error!', resultado.error[0]);\r\n          }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    }\r\n\r\n\r\n    function limpiarFormFacturar(){\r\n      btnPagar.disabled = false;\r\n      btnPagar.value = 'Pagar';\r\n      miDialogoFacturar.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      (document.getElementById('contenedorDesktop') as HTMLDivElement).classList.add('translate-x-full');\r\n      (document.getElementById('overlayCarrito') as HTMLDivElement).classList.add('hidden');\r\n    }\r\n\r\n\r\n    async function printTicketPOS(idfactura:string, datainvoice:DataInvoice){\r\n      console.log(datainvoice);\r\n      ////// cuando no es impresora CAJA por BT\r\n      const isAndroid = /Android/i.test(navigator.userAgent);\r\n\r\n      if(printerBT === '1'){  //solo aplica para impresora principal si es android\r\n        const builder = new InvoiceTicketBuilder2(datainvoice);\r\n        const ticket = await builder.generate(true); //true para version buffer bytes\r\n        \r\n        const base64 = bytesToBase64(ticket);\r\n        //const url = `intent://base64,${base64}#Intent;scheme=rawbt;package=ru.a4024.rawbtprinter;end;`;\r\n        //const url = `intent://base64,${base64}#Intent;scheme=rawbt;package=ru.a4024.rawbtprinter;end;`;\r\n        //window.location.href = url;\r\n        if (isAndroid)window.location.href = `rawbt:base64,${base64}`;\r\n\r\n        //version string\r\n          //const encoder = new TextEncoder();\r\n          //const bytes = encoder.encode(ticket);\r\n        //descargar .bin a equipo\r\n          /*const blob = new Blob([ticket], { type: 'application/octet-stream' });\r\n          const url = URL.createObjectURL(blob);\r\n          const a = document.createElement('a');\r\n          a.href = url;\r\n          a.download = 'ticket.bin';\r\n          a.click();\r\n          URL.revokeObjectURL(url);*/\r\n      }\r\n\r\n      if(printerBT !== '1'){\r\n        const dataPrinter = {\r\n          businessId: datainvoice.host,\r\n          sucursal: datainvoice.sucursal,\r\n          printerName: 'CAJA',\r\n          tipoTicket: 'ticket',\r\n          content: datainvoice\r\n        };\r\n\r\n        console.log(dataPrinter);\r\n\r\n        try {\r\n          //const url = \"http://localhost:3100/api/print/printJob\"; //llamado a la API server print nodejs/ts\r\n          const url = \"https://servidorimpresionposws-production.up.railway.app/api/print/printJob\"; //llamado a la API server print nodejs/ts\r\n          const respuesta = await fetch(url, {\r\n            method: 'POST',\r\n            headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n            body: JSON.stringify(dataPrinter)\r\n        });\r\n          const resultado = await respuesta.json();\r\n          console.log(resultado);\r\n        } catch (error) {\r\n          console.log(error);\r\n        }\r\n      }\r\n\r\n      setTimeout(() => {\r\n        window.open(\"/admin/printPDFPOS?id=\" + idfactura, \"_blank\");  //llama a printcontrolador.php\r\n      }, 1000);\r\n\r\n    }\r\n\r\n    \r\n    /////////////////////////obtener datos de cotizacion /////////////////////\r\n    const parametrosURL = new URLSearchParams(window.location.search);\r\n    const id = parametrosURL.get('id');\r\n    let datosfactura:{id:string, idcliente: string, idvendedor:string, idcaja:string, idconsecutivo:string, iddireccion:string, idtarifazona:string, idcierrecaja:string, num_orden:string, cliente:string, vendedor:string, caja:string, tipofacturador:string, direccion:string, tarifazona:string, totalunidades:string, recibido:string, transaccion:string, tipoventa:string,\r\n                      cotizacion:string, estado:string, cambioaventa:string, referencia:string, subtotal:string, base:string, valorimpuestototal:string, dctox100:string, descuento:string, total:string, observacion:string, departamento:string, ciudad:string, entrega:string, valortarifa:string, fechacreacion:string, fechapago:string, opc1:string, opc2:string};\r\n    if(id){\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/getcotizacion_venta?id=\"+id; //llamado a la API REST\r\n            const respuesta = await fetch(url); \r\n            const resultado = await respuesta.json();\r\n            datosfactura = resultado.factura;\r\n            carrito = resultado.productos;\r\n            carrito.forEach((item, i) =>printProduct(item.idproducto, item.valorunidad, i));\r\n            //valorCarritoTotal(); //recalcula impuestos de la cotizacion y valores totales\r\n            (document.querySelector('#npedido') as HTMLInputElement).value = datosfactura.num_orden;\r\n            $('#selectCliente').val(datosfactura.idcliente).trigger('change');\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formAddCliente') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n\r\n    //exponer variables y funciones globalmente\r\n    POS.limpiarformdialog = limpiarformdialog;\r\n    POS.printTarifaEnvio = printTarifaEnvio;\r\n    POS.valorCarritoTotal = valorCarritoTotal;\r\n    POS.actualizarCarrito = actualizarCarrito;\r\n    POS.mostrarFeedbackCarrito = mostrarFeedbackCarrito;\r\n    //POS.calcularCambio = calcularCambio;\r\n    POS.cerrarDialogoExterno = cerrarDialogoExterno;\r\n    POS.tarifas = tarifas;\r\n    POS.valorTotal = valorTotal;\r\n    POS.mapMediospago = mapMediospago;\r\n    POS.tipoventa = tipoventa;\r\n    //POS.carrito = carrito;\r\n    //POS.products = products;\r\n  }\r\n\r\n\r\n})();\r\n","(()=>{\r\n    if(document.querySelector('.editartrasladoinv')){\r\n        // EDITAR LOS PRODUCTOS A TRASLADOR A OTRA SEDE\r\n        const btnAddItem = document.querySelector('#btnAddItem') as HTMLButtonElement;\r\n        const tablaItems = document.querySelector('#tablaItems tbody');\r\n        const btnUpdateTrasladoInv = document.querySelector('#btnUpdateTrasladoInv') as HTMLButtonElement;\r\n        let carrito:{id: string, id_trasladoinv:string, fkproducto:string, idsubproducto_id:string, iditem:string, nombreitem:string, tipo:string, unidadmedida:string, cantidad: number, factor: number}[]=[];\r\n        let filteredData: {id:string, text:string, tipo:string, sku:string, unidadmedida:string}[];   //tipo = 0 es producto simple,  1 = subproducto\r\n\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/totalitems\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas los productos simples y subproductos\r\n                const respuesta = await fetch(url); \r\n                const resultado:{id:string, nombre:string, tipoproducto:string, sku:string, unidadmedida:string}[] = await respuesta.json(); \r\n                filteredData = resultado.map(item => ({ id: item.id, text: item.nombre, tipo: item.tipoproducto??'1', sku: item.sku, unidadmedida: item.unidadmedida }));\r\n                activarselect2(filteredData);\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n        \r\n        const parametrosURL = new URLSearchParams(window.location.search);\r\n        const id = parametrosURL.get('id');\r\n        if(id!=null && /^\\d+$/.test(id) && Number(id) >= 1){\r\n            (async ()=>{\r\n                try {\r\n                    const url = \"/admin/api/idOrdenTrasladoSolicitudInv?id=\"+id; //llamado a la API REST y trae el detalle de la orden trasladar/solicitud desde trasladarinvcontrolador.php\r\n                    const respuesta = await fetch(url); \r\n                    const resultado = await respuesta.json();\r\n                    const detalleOrden = resultado.orden[0];\r\n                    const itemsorden:{id:string, id_trasladoinv:string, fkproducto:string, idsubproducto_id:string, nombre:string, cantidad:number}[] = detalleOrden.detalletrasladoinv;\r\n                    carrito = itemsorden.map(item =>{\r\n                        const esProducto = item.fkproducto && !item.idsubproducto_id;\r\n                        return {\r\n                            id: item.id,\r\n                            id_trasladoinv: item.id_trasladoinv,\r\n                            fkproducto: item.fkproducto,\r\n                            idsubproducto_id: item.idsubproducto_id,\r\n                            iditem: esProducto?item.fkproducto:item.idsubproducto_id, \r\n                            nombreitem: item.nombre, \r\n                            tipo: esProducto?'0':'1', \r\n                            unidadmedida:'', \r\n                            cantidad: item.cantidad, \r\n                            factor: 1\r\n                        }\r\n                    });\r\n                    //printDetalleOrden(detalleOrden);\r\n                    carrito.forEach(c =>printItemTable(c.iditem, c.tipo, c.unidadmedida, c.cantidad, c.nombreitem));   \r\n                } catch (error) {\r\n                    console.log(error);\r\n                }\r\n            })();\r\n        }\r\n        \r\n        \r\n\r\n        function activarselect2(filteredData:{id:string, text:string, tipo:string, sku:string, unidadmedida:string}[]){\r\n            ($('#articulo') as any).select2({ \r\n                width: '100%',\r\n                data: filteredData,\r\n                placeholder: \"Selecciona un item\",\r\n                maximumSelectionLength: 1,\r\n            });  \r\n        }\r\n\r\n        $(\"#articulo\").on('change', (e)=>{\r\n            let datos = ($('#articulo') as any).select2('data')[0];\r\n            if(datos)(document.querySelector('#unidadmedida') as HTMLInputElement).value = datos.unidadmedida;\r\n        });\r\n\r\n        btnAddItem.addEventListener('click', (e)=>{\r\n            let cantidad = parseFloat((document.querySelector('#cantidad') as HTMLInputElement).value);\r\n            let datos = ($('#articulo') as any).select2('data')[0];\r\n            console.log(datos);\r\n            if(datos){\r\n                const index = carrito.findIndex(x=>x.iditem==datos.id&&x.tipo==datos.tipo);\r\n                if(index == -1){  //si el item seleccionado no existe en el carrito, agregarlo.\r\n                    const itemselected = filteredData.find(x=>x.id==datos.id&&x.tipo==datos.tipo)!; \r\n                    const item:{id:string, id_trasladoinv:string, fkproducto:string, idsubproducto_id:string, iditem: string, nombreitem: string, tipo: string, unidadmedida: string, cantidad: number, factor: number} = {\r\n                        id: '',\r\n                        id_trasladoinv: id!,\r\n                        fkproducto: itemselected.tipo=='0'?itemselected.id:'NULL', \r\n                        idsubproducto_id: itemselected.tipo=='1'?itemselected.id:'NULL',\r\n                        iditem: itemselected?.id!,\r\n                        nombreitem: itemselected.text,\r\n                        tipo: itemselected.tipo,  ////tipo = 0 es producto simple,  1 = subproducto\r\n                        unidadmedida: itemselected.unidadmedida,\r\n                        cantidad: cantidad,\r\n                        factor: 1,\r\n                    }\r\n                    carrito = [...carrito, item];\r\n                    printItemTable(itemselected.id, itemselected.tipo, itemselected.unidadmedida, cantidad, itemselected.text);\r\n                }else{\r\n                    carrito[index].cantidad = cantidad;\r\n                    const tr = document.querySelector(`[data-id=\"${carrito[index].iditem}\"][data-tipo=\"${carrito[index].tipo}\"]`)!;\r\n                    tr.children[1].textContent = carrito[index].cantidad+'';\r\n                }\r\n            }\r\n        });\r\n\r\n        function printItemTable(id:string, tipo:string, unidadmedida:string, cantidad:number, nombre:string){\r\n            let options = `<option data-factor=\"1\" value=\"\" >${unidadmedida}</option>`;\r\n            /*if(tipo=='1'){   //si es un subproducto\r\n                options = \"\";\r\n                const subproductounidades = allConversionUnidades.filter(x => x.idsubproducto == id); \r\n                subproductounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idsubproducto}\" >${u.nombreunidaddestino}</option>`);\r\n            }\r\n            if(tipo=='0'){\r\n                options = \"\";\r\n                const productounidades = allConversionUnidades.filter(x => x.idproducto == id); \r\n                productounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idproducto}\" >${u.nombreunidaddestino}</option>`);\r\n            }*/\r\n            const tr = document.createElement('TR');\r\n            tr.classList.add('itemselect');\r\n            tr.dataset.id = `${id}`;\r\n            tr.dataset.tipo = `${tipo}`;\r\n            tr.insertAdjacentHTML('afterbegin', \r\n                `<td class=\"p-4\">${nombre}</td>\r\n                <td class=\"p-4\">${cantidad}</td>\r\n                <td class=\"p-4 flex items-center justify-center gap-2\">\r\n                    <button class=\"flex items-center gap-1 px-3 py-1 text-base text-indigo-600 border border-indigo-200 rounded-lg hover:bg-indigo-50\">\r\n                        👁 Ver\r\n                    </button>\r\n                    <button class=\"w-11 h-11 flex items-center justify-center text-green-600 border border-green-200 rounded-full hover:bg-green-50 text-xl\">✅</button>\r\n                    <button class=\"eliminarItem w-11 h-11 flex items-center justify-center text-rose-600 border border-rose-200 rounded-full hover:bg-rose-50 text-xl\">❌</button>\r\n                </td>`);\r\n            tablaItems?.appendChild(tr);\r\n        }\r\n\r\n\r\n        /*function printDetalleOrden(detalleOrden:{id:string, sucursal_origen:string, sucursal_destino:string, tipo:string, fkusuario:string, nombreusuario:string, estado:string}){\r\n            console.log(detalleOrden);\r\n\r\n        }*/\r\n\r\n\r\n        //////////////////////////////////// evento a la tabla de los productos seleccionados  ///////////////////////////////////\r\n        tablaItems?.addEventListener('click', (e:Event)=>{\r\n            const elementItem = (e.target as HTMLElement)?.closest('.itemselect'); //seleccionamos el tr de la tabla\r\n            const iditem = (elementItem as HTMLElement).dataset.id!;\r\n            const tipoitem = (elementItem as HTMLElement).dataset.tipo!;\r\n        \r\n            if((e.target as HTMLElement).classList.contains('eliminarItem')){ //se trae todoscon true menos el que coincida con iditem y tipoitem\r\n                carrito = carrito.filter(x=> {\r\n                    if(x.iditem==iditem){\r\n                        if(x.tipo==tipoitem){\r\n                            return false;\r\n                        }else{\r\n                            return true;\r\n                        }\r\n                    }else{\r\n                        return true;\r\n                    }\r\n                });\r\n                tablaItems?.querySelector(`TR[data-id=\"${iditem}\"][data-tipo=\"${tipoitem}\"]`)?.remove();\r\n            }\r\n            //itemCarrito.cantidad = itemCarrito.cantidadcomprado*itemCarrito.factor;\r\n        });\r\n\r\n\r\n        btnUpdateTrasladoInv.addEventListener('click', ()=>{\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Esta seguro de actualizar la orden de transferencia?',\r\n                text: \"Se procesara la orden con todos los productos para la sede destino\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    (async ()=>{ \r\n                        const datos = new FormData();\r\n                        datos.append('id_trasladoinv', id!);\r\n                        datos.append('ids', JSON.stringify(carrito.map(x=>x.id)));\r\n                        datos.append('nuevosproductos', JSON.stringify(carrito));\r\n                        try {\r\n                            const url = \"/admin/api/editarOrdenTransferencia\";  //api llamada a trasladosinvcontrolador\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                            const resultado = await respuesta.json();  \r\n                            if(resultado.exito !== undefined){\r\n                                setTimeout(() => {\r\n                                    window.location.href = `/admin/almacen/trasladarinventario`;\r\n                                }, 1600);\r\n                                Swal.fire(resultado.exito[0], '', 'success') \r\n                            }else{\r\n                                Swal.fire(resultado.error[0], '', 'error')\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();//cierre de async()\r\n                }\r\n            });\r\n        });\r\n\r\n    }\r\n})();","(()=>{\r\n\r\n    if(document.querySelector('.nuevotrasladoinv')){\r\n        // PROCESO SOLICITUD DE INVENTARIO A OTRAS SEDES\r\n        const btnAnterior = document.getElementById(\"btnAnteriorTrasladoInv\") as HTMLButtonElement;\r\n        const btnSiguiente = document.getElementById(\"btnSiguienteTrasladoInv\") as HTMLButtonElement;\r\n        const steps = document.querySelectorAll<HTMLDivElement>(\".step-circle\");\r\n        const stepSections = document.querySelectorAll<HTMLElement>(\".step-section\");\r\n        const btnAddItem = document.querySelector('#btnAddItem') as HTMLButtonElement;\r\n        const tablaItems = document.querySelector('#tablaItems tbody');\r\n        const resumenSedeDestino = document.querySelector('#resumenSedeDestino') as HTMLParagraphElement;\r\n        const resumenFecha = document.querySelector('#resumenFecha') as HTMLParagraphElement;\r\n        const resumenObservaciones = document.querySelector('#resumenObservaciones') as HTMLParagraphElement;\r\n        let carrito:{iditem:string, idpx:string, idsx:string, tipo: string, nombreitem:string, unidad:string, cantidad: number, factor: number, impuesto: number, valorunidad: number, subtotal: number, precio_compra: number, valorcompra: number}[]=[];\r\n        let filteredData: {id:string, text:string, tipo:string, sku:string, unidadmedida:string}[];   //tipo = 0 es producto simple,  1 = subproducto\r\n        let currentStep = 1;\r\n        const totalSteps = 3;\r\n\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/totalitems\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas los productos simples y subproductos\r\n                const respuesta = await fetch(url); \r\n                const resultado:{id:string, nombre:string, tipoproducto:string, sku:string, unidadmedida:string}[] = await respuesta.json(); \r\n                filteredData = resultado.map(item => ({ id: item.id, text: item.nombre, tipo: item.tipoproducto??'1', sku: item.sku, unidadmedida: item.unidadmedida }));\r\n                activarselect2(filteredData);\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n\r\n        //establecer fecha por defecto\r\n        const inputFecha = document.getElementById('fecha') as HTMLInputElement;\r\n            const hoy = new Date();\r\n            const yyyy = hoy.getFullYear();\r\n            const mm = String(hoy.getMonth() + 1).padStart(2, '0'); // Mes con 2 dígitos\r\n            const dd = String(hoy.getDate()).padStart(2, '0');      // Día con 2 dígitos\r\n            inputFecha.value = `${yyyy}-${mm}-${dd}`;\r\n\r\n        function actualizarProgreso() {\r\n            // Actualizar barra de progreso\r\n            steps.forEach((step, index) => {\r\n                const stepNumber = index + 1;\r\n                if (stepNumber < currentStep) {\r\n                step.className =\r\n                    \"step-circle w-10 h-10 rounded-full bg-green-500 text-white font-semibold flex items-center justify-center\";\r\n                } else if (stepNumber === currentStep) {\r\n                step.className =\r\n                    \"step-circle w-10 h-10 rounded-full bg-indigo-600 text-white font-semibold flex items-center justify-center\";\r\n                } else {\r\n                step.className =\r\n                    \"step-circle w-10 h-10 rounded-full border-2 border-gray-300 text-gray-400 font-semibold flex items-center justify-center\";\r\n                }\r\n            });\r\n\r\n            // Mostrar solo la sección actual\r\n            stepSections.forEach((section, index) => {\r\n                if (index + 1 === currentStep) {\r\n                section.style.display = \"block\";\r\n                } else {\r\n                section.style.display = \"none\";\r\n                }\r\n            });\r\n\r\n            // Deshabilitar/activar botones si es necesario\r\n            btnAnterior.disabled = currentStep === 1;\r\n            //btnSiguiente.disabled = currentStep === totalSteps;\r\n        }\r\n\r\n        // Inicializar vista\r\n        actualizarProgreso();\r\n\r\n        // Eventos de navegación\r\n        btnSiguiente.addEventListener(\"click\", () => {\r\n            if (currentStep < totalSteps) {\r\n                currentStep++;\r\n                if(currentStep===3 && carrito.length===0){\r\n                    currentStep--;\r\n                    return;\r\n                }\r\n                if(currentStep===3 && carrito.length>0)resumen();\r\n                actualizarProgreso();\r\n            }else{\r\n                generarorden();\r\n            }\r\n            \r\n        });\r\n\r\n        btnAnterior.addEventListener(\"click\", () => {\r\n            if (currentStep > 1) {\r\n                currentStep--;\r\n                actualizarProgreso();\r\n            }\r\n        });\r\n\r\n\r\n        function activarselect2(filteredData:{id:string, text:string, tipo:string, sku:string, unidadmedida:string}[]){\r\n            ($('#articulo') as any).select2({ \r\n                width: '100%',\r\n                data: filteredData,\r\n                placeholder: \"Selecciona un item\",\r\n                maximumSelectionLength: 1,\r\n            });\r\n           \r\n        }\r\n\r\n        $(\"#articulo\").on('change', (e)=>{\r\n            let datos = ($('#articulo') as any).select2('data')[0];\r\n            if(datos)(document.querySelector('#unidadmedida') as HTMLInputElement).value = datos.unidadmedida;\r\n        });\r\n\r\n        btnAddItem.addEventListener('click', (e)=>{\r\n            let cantidad = parseFloat((document.querySelector('#cantidad') as HTMLInputElement).value);\r\n            let datos = ($('#articulo') as any).select2('data')[0];\r\n            console.log(datos);\r\n            if(datos){\r\n                const index = carrito.findIndex(x=>x.iditem==datos.id&&x.tipo==datos.tipo);\r\n                if(index == -1){  //si el item seleccionado no existe en el carrito, agregarlo.\r\n                    const itemselected = filteredData.find(x=>x.id==datos.id&&x.tipo==datos.tipo)!; //products es el arreglo de todos los productos traido por api\r\n                    const item:{iditem: string, idpx: string, idsx: string, tipo: string, nombreitem: string, unidad: string, cantidad: number, factor: number, impuesto: number, valorunidad: number, subtotal: number, precio_compra:number, valorcompra: number} = {\r\n                        iditem: itemselected?.id!,\r\n                        idpx: itemselected.tipo=='0'?itemselected.id:'NULL',\r\n                        idsx: itemselected.tipo=='1'?itemselected.id:'NULL',\r\n                        tipo: itemselected.tipo,  ////tipo = 0 es producto simple,  1 = subproducto\r\n                        nombreitem: itemselected.text,\r\n                        unidad: itemselected.unidadmedida,\r\n                        cantidad: cantidad,\r\n                        factor: 1,\r\n                        impuesto: 0,\r\n                        valorunidad: 0,\r\n                        subtotal: 0,\r\n                        precio_compra: 0,\r\n                        valorcompra: 0,\r\n                    }\r\n                    carrito = [...carrito, item];\r\n                    printItemTable(datos.id, datos.tipo, datos.unidadmedida, cantidad);\r\n                }else{\r\n                    carrito[index].cantidad = cantidad;\r\n                    const tr = document.querySelector(`[data-id=\"${carrito[index].iditem}\"][data-tipo=\"${carrito[index].tipo}\"]`)!;\r\n                    tr.children[1].textContent = carrito[index].cantidad+'';\r\n                }\r\n            }\r\n        });\r\n\r\n        function printItemTable(id:string, tipo:string, unidadmedida:string, cantidad:number){\r\n            let options = `<option data-factor=\"1\" value=\"\" >${unidadmedida}</option>`;\r\n            const unItem = filteredData.find(x=>x.id==id&&x.tipo==tipo)!;\r\n            /*if(tipo=='1'){   //si es un subproducto\r\n                options = \"\";\r\n                const subproductounidades = allConversionUnidades.filter(x => x.idsubproducto == id); \r\n                subproductounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idsubproducto}\" >${u.nombreunidaddestino}</option>`);\r\n            }\r\n            if(tipo=='0'){\r\n                options = \"\";\r\n                const productounidades = allConversionUnidades.filter(x => x.idproducto == id); \r\n                productounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idproducto}\" >${u.nombreunidaddestino}</option>`);\r\n            }*/\r\n            const tr = document.createElement('TR');\r\n            tr.classList.add('itemselect');\r\n            tr.dataset.id = `${id}`;\r\n            tr.dataset.tipo = `${tipo}`;\r\n            tr.insertAdjacentHTML('afterbegin', \r\n                `<td class=\"p-4\">${unItem?.text}</td>\r\n                <td class=\"p-4\">${cantidad}</td>\r\n                <td class=\"p-4 flex items-center justify-center gap-2\">\r\n                    <button class=\"flex items-center gap-1 px-3 py-1 text-base text-indigo-600 border border-indigo-200 rounded-lg hover:bg-indigo-50\">\r\n                        👁 Ver\r\n                    </button>\r\n                    <button class=\"w-11 h-11 flex items-center justify-center text-green-600 border border-green-200 rounded-full hover:bg-green-50 text-xl\">✅</button>\r\n                    <button class=\"eliminarItem w-11 h-11 flex items-center justify-center text-rose-600 border border-rose-200 rounded-full hover:bg-rose-50 text-xl\">❌</button>\r\n                </td>`);\r\n            tablaItems?.appendChild(tr);\r\n        }\r\n\r\n\r\n        //////////////////////////////////// evento a la tabla de los productos seleccionados  ///////////////////////////////////\r\n        tablaItems?.addEventListener('click', (e:Event)=>{\r\n            const elementItem = (e.target as HTMLElement)?.closest('.itemselect'); //seleccionamos el tr de la tabla\r\n            const iditem = (elementItem as HTMLElement).dataset.id!;\r\n            const tipoitem = (elementItem as HTMLElement).dataset.tipo!;\r\n\r\n            const itemCarrito = carrito.find(x=>x.iditem==iditem&&x.tipo==tipoitem)!;\r\n            \r\n        \r\n            if((e.target as HTMLElement).classList.contains('eliminarItem')){\r\n                carrito = carrito.filter(x=> {\r\n                    if(x.iditem==iditem){\r\n                        if(x.tipo==tipoitem){\r\n                            return false;\r\n                        }else{\r\n                            return true;\r\n                        }\r\n                    }else{\r\n                        return true;\r\n                    }\r\n                });\r\n                tablaItems?.querySelector(`TR[data-id=\"${iditem}\"][data-tipo=\"${tipoitem}\"]`)?.remove();\r\n                //resumen();\r\n            }\r\n\r\n            //itemCarrito.cantidad = itemCarrito.cantidadcomprado*itemCarrito.factor;\r\n        });\r\n\r\n        function resumen(){\r\n            const tablaproductosresumen = document.querySelector('#tablaproductosresumen tbody');\r\n            while(tablaproductosresumen?.firstChild)tablaproductosresumen.removeChild(tablaproductosresumen.firstChild);\r\n            resumenSedeDestino.textContent = (document.querySelector('#sucursaldestino') as HTMLSelectElement).selectedOptions[0].text;\r\n            resumenFecha.textContent = inputFecha.value;\r\n            resumenObservaciones.textContent = (document.querySelector('#observaciones') as HTMLTextAreaElement).value;\r\n\r\n            carrito.forEach(z=>{\r\n                const tr = document.createElement('tr');\r\n                const tdnombre = document.createElement('td');\r\n                tdnombre.textContent = z.nombreitem;\r\n                tr?.appendChild(tdnombre);\r\n                const tdcantidad = document.createElement('td');\r\n                tdcantidad.textContent = z.cantidad+'';\r\n                tr?.appendChild(tdcantidad);\r\n                const tdund = document.createElement('td');\r\n                tdund.textContent = z.unidad;\r\n                tr?.appendChild(tdund);\r\n                tablaproductosresumen?.appendChild(tr);\r\n            });\r\n        }\r\n\r\n        function generarorden(){\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Esta seguro de generar orden de transferencia?',\r\n                text: \"Se procesara la orden con todos los productos en la sede destino\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    const idsucursalorigen = document.querySelector('#sucursalorigen') as HTMLSelectElement;\r\n                    const sucursaldestino = document.querySelector('#sucursaldestino') as HTMLSelectElement;\r\n                    (async ()=>{ \r\n                        const datos = new FormData();\r\n                        datos.append('idsucursalorigen', idsucursalorigen.value);\r\n                        datos.append('idsucursaldestino', sucursaldestino.value);\r\n                        datos.append('productos', JSON.stringify(carrito));\r\n                        try {\r\n                            const url = \"/admin/api/apinuevotrasladoinv\";  //api llamada a trasladosinvcontrolador\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                            const resultado = await respuesta.json();  \r\n                            if(resultado.exito !== undefined){\r\n                                setTimeout(() => {\r\n                                    window.location.href = `/admin/almacen/trasladarinventario`;\r\n                                }, 1100);\r\n                                Swal.fire(resultado.exito[0], '', 'success') \r\n                            }else{\r\n                                Swal.fire(resultado.error[0], '', 'error')\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();//cierre de async()\r\n                }\r\n            });\r\n        }\r\n\r\n    }\r\n})();","(()=>{\r\n\r\n    if(document.querySelector('.solicitarinvnetario')){\r\n        // PROCESO SOLICITUD DE INVENTARIO A OTRAS SEDES\r\n        const btnAnterior = document.getElementById(\"btnAnteriorSolicitudInv\") as HTMLButtonElement;\r\n        const btnSiguiente = document.getElementById(\"btnSiguienteSolicitudInv\") as HTMLButtonElement;\r\n        const steps = document.querySelectorAll<HTMLDivElement>(\".step-circle\");\r\n        const stepSections = document.querySelectorAll<HTMLElement>(\".step-section\");\r\n        const btnAddItem = document.querySelector('#btnAddItem') as HTMLButtonElement;\r\n        const tablaItems = document.querySelector('#tablaItems tbody');\r\n        const resumenSedeDestino = document.querySelector('#resumenSedeDestino') as HTMLParagraphElement;\r\n        const resumenFecha = document.querySelector('#resumenFecha') as HTMLParagraphElement;\r\n        const resumenObservaciones = document.querySelector('#resumenObservaciones') as HTMLParagraphElement;\r\n        let carrito:{iditem:string, idpx:string, idsx:string, tipo: string, nombreitem:string, unidad:string, cantidad: number, factor: number, impuesto: number, valorunidad: number, subtotal: number, precio_compra: number, valorcompra: number}[]=[];\r\n        let filteredData: {id:string, text:string, tipo:string, sku:string, unidadmedida:string}[];   //tipo = 0 es producto simple,  1 = subproducto\r\n        let currentStep = 1;\r\n        const totalSteps = 3;\r\n\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/totalitems\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas los productos simples y subproductos\r\n                const respuesta = await fetch(url); \r\n                const resultado:{id:string, nombre:string, tipoproducto:string, sku:string, unidadmedida:string}[] = await respuesta.json(); \r\n                filteredData = resultado.map(item => ({ id: item.id, text: item.nombre, tipo: item.tipoproducto??'1', sku: item.sku, unidadmedida: item.unidadmedida }));\r\n                activarselect2(filteredData);\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n\r\n        //establecer fecha por defecto\r\n        const inputFecha = document.getElementById('fecha') as HTMLInputElement;\r\n            const hoy = new Date();\r\n            const yyyy = hoy.getFullYear();\r\n            const mm = String(hoy.getMonth() + 1).padStart(2, '0'); // Mes con 2 dígitos\r\n            const dd = String(hoy.getDate()).padStart(2, '0');      // Día con 2 dígitos\r\n            inputFecha.value = `${yyyy}-${mm}-${dd}`;\r\n\r\n        function actualizarProgreso() {\r\n            // Actualizar barra de progreso\r\n            steps.forEach((step, index) => {\r\n                const stepNumber = index + 1;\r\n                if (stepNumber < currentStep) {\r\n                step.className =\r\n                    \"step-circle w-10 h-10 rounded-full bg-green-500 text-white font-semibold flex items-center justify-center\";\r\n                } else if (stepNumber === currentStep) {\r\n                step.className =\r\n                    \"step-circle w-10 h-10 rounded-full bg-indigo-600 text-white font-semibold flex items-center justify-center\";\r\n                } else {\r\n                step.className =\r\n                    \"step-circle w-10 h-10 rounded-full border-2 border-gray-300 text-gray-400 font-semibold flex items-center justify-center\";\r\n                }\r\n            });\r\n\r\n            // Mostrar solo la sección actual\r\n            stepSections.forEach((section, index) => {\r\n                if (index + 1 === currentStep) {\r\n                section.style.display = \"block\";\r\n                } else {\r\n                section.style.display = \"none\";\r\n                }\r\n            });\r\n\r\n            // Deshabilitar/activar botones si es necesario\r\n            btnAnterior.disabled = currentStep === 1;\r\n            //btnSiguiente.disabled = currentStep === totalSteps;\r\n        }\r\n\r\n        // Inicializar vista\r\n        actualizarProgreso();\r\n\r\n        // Eventos de navegación\r\n        btnSiguiente.addEventListener(\"click\", () => {\r\n            if (currentStep < totalSteps) {\r\n                currentStep++;\r\n                if(currentStep===3 && carrito.length===0){\r\n                    currentStep--;\r\n                    return;\r\n                }\r\n                if(currentStep===3 && carrito.length>0)resumen();\r\n                actualizarProgreso();\r\n            }else{\r\n                generarorden();\r\n            }\r\n            \r\n        });\r\n\r\n        btnAnterior.addEventListener(\"click\", () => {\r\n            if (currentStep > 1) {\r\n                currentStep--;\r\n                actualizarProgreso();\r\n            }\r\n        });\r\n\r\n\r\n        function activarselect2(filteredData:{id:string, text:string, tipo:string, sku:string, unidadmedida:string}[]){\r\n            ($('#articulo') as any).select2({ \r\n                width: '100%',\r\n                data: filteredData,\r\n                placeholder: \"Selecciona un item\",\r\n                maximumSelectionLength: 1,\r\n            });\r\n           \r\n        }\r\n\r\n        $(\"#articulo\").on('change', (e)=>{\r\n            let datos = ($('#articulo') as any).select2('data')[0];\r\n            if(datos)(document.querySelector('#unidadmedida') as HTMLInputElement).value = datos.unidadmedida;\r\n        });\r\n\r\n        btnAddItem.addEventListener('click', (e)=>{\r\n            let cantidad = parseFloat((document.querySelector('#cantidad') as HTMLInputElement).value);\r\n            let datos = ($('#articulo') as any).select2('data')[0];\r\n            console.log(datos);\r\n            if(datos){\r\n                const index = carrito.findIndex(x=>x.iditem==datos.id&&x.tipo==datos.tipo);\r\n                if(index == -1){  //si el item seleccionado no existe en el carrito, agregarlo.\r\n                    const itemselected = filteredData.find(x=>x.id==datos.id&&x.tipo==datos.tipo)!; //products es el arreglo de todos los productos traido por api\r\n                    const item:{iditem: string, idpx: string, idsx: string, tipo: string, nombreitem: string, unidad: string, cantidad: number, factor: number, impuesto: number, valorunidad: number, subtotal: number, precio_compra:number, valorcompra: number} = {\r\n                        iditem: itemselected?.id!,\r\n                        idpx: itemselected.tipo=='0'?itemselected.id:'NULL',\r\n                        idsx: itemselected.tipo=='1'?itemselected.id:'NULL',\r\n                        tipo: itemselected.tipo,  ////tipo = 0 es producto simple,  1 = subproducto\r\n                        nombreitem: itemselected.text,\r\n                        unidad: itemselected.unidadmedida,\r\n                        cantidad: cantidad,\r\n                        factor: 1,\r\n                        impuesto: 0,\r\n                        valorunidad: 0,\r\n                        subtotal: 0,\r\n                        precio_compra: 0,\r\n                        valorcompra: 0,\r\n                    }\r\n                    carrito = [...carrito, item];\r\n                    printItemTable(datos.id, datos.tipo, datos.unidadmedida, cantidad);\r\n                }else{\r\n                    carrito[index].cantidad = cantidad;\r\n                    const tr = document.querySelector(`[data-id=\"${carrito[index].iditem}\"][data-tipo=\"${carrito[index].tipo}\"]`)!;\r\n                    tr.children[1].textContent = carrito[index].cantidad+'';\r\n                }\r\n            }\r\n        });\r\n\r\n        function printItemTable(id:string, tipo:string, unidadmedida:string, cantidad:number){\r\n            let options = `<option data-factor=\"1\" value=\"\" >${unidadmedida}</option>`;\r\n            const unItem = filteredData.find(x=>x.id==id&&x.tipo==tipo)!;\r\n            /*if(tipo=='1'){   //si es un subproducto\r\n                options = \"\";\r\n                const subproductounidades = allConversionUnidades.filter(x => x.idsubproducto == id); \r\n                subproductounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idsubproducto}\" >${u.nombreunidaddestino}</option>`);\r\n            }\r\n            if(tipo=='0'){\r\n                options = \"\";\r\n                const productounidades = allConversionUnidades.filter(x => x.idproducto == id); \r\n                productounidades.forEach(u=>options+=`<option data-factor=\"${u.factorconversion}\" value=\"${u.idproducto}\" >${u.nombreunidaddestino}</option>`);\r\n            }*/\r\n            const tr = document.createElement('TR');\r\n            tr.classList.add('itemselect');\r\n            tr.dataset.id = `${id}`;\r\n            tr.dataset.tipo = `${tipo}`;\r\n            tr.insertAdjacentHTML('afterbegin', \r\n                `<td class=\"p-4\">${unItem?.text}</td>\r\n                <td class=\"p-4\">${cantidad}</td>\r\n                <td class=\"p-4 flex items-center justify-center gap-2\">\r\n                    <button class=\"flex items-center gap-1 px-3 py-1 text-base text-indigo-600 border border-indigo-200 rounded-lg hover:bg-indigo-50\">\r\n                        👁 Ver\r\n                    </button>\r\n                    <button class=\"w-11 h-11 flex items-center justify-center text-green-600 border border-green-200 rounded-full hover:bg-green-50 text-xl\">✅</button>\r\n                    <button class=\"eliminarItem w-11 h-11 flex items-center justify-center text-rose-600 border border-rose-200 rounded-full hover:bg-rose-50 text-xl\">❌</button>\r\n                </td>`);\r\n            tablaItems?.appendChild(tr);\r\n        }\r\n\r\n\r\n        //////////////////////////////////// evento a la tabla de los productos seleccionados  ///////////////////////////////////\r\n        tablaItems?.addEventListener('click', (e:Event)=>{\r\n            const elementItem = (e.target as HTMLElement)?.closest('.itemselect'); //seleccionamos el tr de la tabla\r\n            const iditem = (elementItem as HTMLElement).dataset.id!;\r\n            const tipoitem = (elementItem as HTMLElement).dataset.tipo!;\r\n\r\n            const itemCarrito = carrito.find(x=>x.iditem==iditem&&x.tipo==tipoitem)!;\r\n            \r\n        \r\n            if((e.target as HTMLElement).classList.contains('eliminarItem')){\r\n                carrito = carrito.filter(x=> {\r\n                    if(x.iditem==iditem){\r\n                        if(x.tipo==tipoitem){\r\n                            return false;\r\n                        }else{\r\n                            return true;\r\n                        }\r\n                    }else{\r\n                        return true;\r\n                    }\r\n                });\r\n                tablaItems?.querySelector(`TR[data-id=\"${iditem}\"][data-tipo=\"${tipoitem}\"]`)?.remove();\r\n                //resumen();\r\n            }\r\n\r\n            //itemCarrito.cantidad = itemCarrito.cantidadcomprado*itemCarrito.factor;\r\n        });\r\n\r\n        function resumen(){\r\n            const tablaproductosresumen = document.querySelector('#tablaproductosresumen tbody');\r\n            while(tablaproductosresumen?.firstChild)tablaproductosresumen.removeChild(tablaproductosresumen.firstChild);\r\n            resumenSedeDestino.textContent = (document.querySelector('#sucursaldestino') as HTMLSelectElement).textContent;\r\n            resumenFecha.textContent = inputFecha.value;\r\n            resumenObservaciones.textContent = (document.querySelector('#observaciones') as HTMLTextAreaElement).value;\r\n\r\n            carrito.forEach(z=>{\r\n                const tr = document.createElement('tr');\r\n                const tdnombre = document.createElement('td');\r\n                tdnombre.textContent = z.nombreitem;\r\n                tr?.appendChild(tdnombre);\r\n                const tdcantidad = document.createElement('td');\r\n                tdcantidad.textContent = z.cantidad+'';\r\n                tr?.appendChild(tdcantidad);\r\n                const tdund = document.createElement('td');\r\n                tdund.textContent = z.unidad;\r\n                tr?.appendChild(tdund);\r\n                tablaproductosresumen?.appendChild(tr);\r\n            });\r\n        }\r\n\r\n        function generarorden(){\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Esta seguro de generar orden de solicitud?',\r\n                text: \"Se procesara la orden con todos los productos en la sede destino\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    const idsucursalorigen = document.querySelector('#sucursalorigen') as HTMLSelectElement;\r\n                    const sucursaldestino = document.querySelector('#sucursaldestino') as HTMLSelectElement;\r\n                    (async ()=>{ \r\n                        const datos = new FormData();\r\n                        datos.append('idsucursalorigen', idsucursalorigen.value);\r\n                        datos.append('idsucursaldestino', sucursaldestino.value);\r\n                        datos.append('productos', JSON.stringify(carrito));\r\n                        try {\r\n                            const url = \"/admin/api/apisolicitarinventario\";  //api llamada a trasladosinvcontrolador.php\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                            const resultado = await respuesta.json();  \r\n                            if(resultado.exito !== undefined){\r\n                                setTimeout(() => {\r\n                                    window.location.href = `/admin/almacen/solicitudesrecibidas`;\r\n                                }, 600);\r\n                                Swal.fire(resultado.exito[0], '', 'success') \r\n                            }else{\r\n                                Swal.fire(resultado.error[0], '', 'error')\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();//cierre de async()\r\n                }\r\n            });\r\n        }\r\n\r\n    }\r\n})();","(()=>{\r\n  if(document.querySelector('.solicitudesrecibidas')){\r\n    const miDialogoDetalleTrasladoSolicitud = document.querySelector('#miDialogoDetalleTrasladoSolicitud') as any;\r\n    const btnXCerrarDetalleTrasladoSolicitud = document.querySelector('#btnXCerrarDetalleTrasladoSolicitud') as HTMLButtonElement;\r\n    const numOrden = document.querySelector('#numOrden') as HTMLSpanElement;\r\n    const parrafoSedeorigen = document.querySelector('#sedeorigen') as HTMLParagraphElement;\r\n    const parrafoSededestino = document.querySelector('#sededestino') as HTMLParagraphElement;\r\n    const parrafotipo = document.querySelector('#tipo') as HTMLParagraphElement;\r\n    const textareaobservacion = document.querySelector('#observaciones') as HTMLTextAreaElement;\r\n    const tbodydetalleorden = document.querySelector('#tabladetalleorden tbody') as HTMLTableElement;\r\n    const filtroSucursal = document.getElementById('filtroSucursal') as HTMLSelectElement;\r\n    const filtroEstado = document.getElementById('filtroEstados') as HTMLSelectElement;\r\n    const filas = document.querySelectorAll<HTMLTableRowElement>('#tablaTraslados tbody tr');\r\n    \r\n    type ordenestrasladosinv = {\r\n      id:string,\r\n      id_sucursalorigen: string,\r\n      id_sucursaldestino: string,\r\n      fkusuario: string,\r\n      sucursal_origen:string,\r\n      sucursal_destino:string,\r\n      nombreusuario:string,\r\n      tipo: string,\r\n      observacion: string,\r\n      estado: string,\r\n      created_at: string,\r\n      detalletrasladoinv: {id:string, id_trasladoinv:string, fkproducto:string, idsubproducto_id:string, nombre:string, cantidad:string, unidadmedida:string, cantidadrecibida:string, cantidadrechazada:string}[]\r\n    };\r\n\r\n    let ordenes:ordenestrasladosinv[]=[], unaorden:ordenestrasladosinv;\r\n\r\n    /*(async ()=>{\r\n      try {\r\n          const url = \"/admin/api/allordenestrasladoinv\"; //llamado a la API REST y se trae todos los productos\r\n          const respuesta = await fetch(url); \r\n          ordenes = await respuesta.json(); \r\n          console.log(ordenes);\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    })();*/\r\n\r\n    const divAlert = document.querySelector('.divmsjalerta0') as HTMLElement;\r\n    if(divAlert)borrarMsjAlert(divAlert);\r\n\r\n\r\n    //evento a la tabla\r\n    document.querySelector('#tablaTraslados')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if(target?.classList.contains(\"enviar\")||target.parentElement?.classList.contains(\"enviar\"))enviar(e);\r\n      if(target?.classList.contains(\"detalle\")||target.parentElement?.classList.contains(\"detalle\"))detalle(e);\r\n      if(target?.classList.contains(\"cancelar\")||target.parentElement?.classList.contains(\"cancelar\"))cancelar(e);\r\n    });\r\n\r\n\r\n    ////// cuando se envia o recibir mercancia, pasa a estado en transito o entregada\r\n    function enviar(e:Event){\r\n      let idorden = (e.target as HTMLElement).parentElement?.id!;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idorden = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n      \r\n      let title:String = '', text:string = '', urlapi:string = '', estado:string = '';\r\n      const tr = (e.target as HTMLElement).closest('tr') as HTMLTableRowElement;\r\n      if(tr.children[4].textContent === 'Ingreso'){\r\n        title = 'Desea confirmar la recepcion de mercancia?';\r\n        text = \"La marcancia ingresara al inventario de la sucursal y no se podra modificar.\";\r\n        urlapi = 'confirmaringresoinv';\r\n        estado = 'entregada';\r\n      }\r\n      if(tr.children[4].textContent === 'Solicitud'){\r\n        title = 'Desea confirmar el envio de mercancia?';\r\n        text = \"La orden entrara en estado: 'EN TRANSITO' y sera aceptada o rechazda por la sede de destino.\";\r\n        urlapi = 'confirmarnuevotrasladoinv';\r\n        estado = 'entransito';\r\n      }\r\n      \r\n      Swal.fire({\r\n          customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n          icon: 'question',\r\n          title: title,\r\n          text: text,\r\n          showCancelButton: true,\r\n          confirmButtonText: 'Si',\r\n          cancelButtonText: 'No',\r\n      }).then((result:any) => {\r\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idorden);\r\n                  try {\r\n                      const url = \"/admin/api/\"+urlapi;  //api llamada a trasladosinvcontrolador para confirmar envio, pasa a estado en transito\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                        tr.children[5].innerHTML = `<span class=\"px-3 py-1 text-base font-semibold rounded-full ${estado=='entregada'?'bg-sky-50 text-sky-600':estado=='entransito'?'bg-yellow-100 text-yellow-700':'bg-rose-50 text-rose-600'}\">${estado}</span>`;\r\n                        Swal.fire(resultado.exito[0], '', 'success') \r\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    function detalle(e:Event){\r\n      let idorden = (e.target as HTMLElement).parentElement?.id!;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idorden = (e.target as HTMLElement).parentElement?.parentElement?.id!;  \r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/idOrdenTrasladoSolicitudInv?id=\"+idorden; //llamado a la API REST y trae el detalle de la orden trasladar/solicitud desde trasladarinvcontrolador.php\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json(); \r\n          imprimirdatos(resultado.orden[0]);\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n      //unaorden = ordenes.find(x=>x.id === idorden)!; //obtengo el producto.\r\n      miDialogoDetalleTrasladoSolicitud.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n\r\n    function cancelar(e:Event){\r\n      let idorden = (e.target as HTMLElement).parentElement?.id!;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idorden = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n      const tr = (e.target as HTMLElement).closest('tr') as HTMLTableRowElement;\r\n      Swal.fire({\r\n          customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n          icon: 'question',\r\n          title: 'Desea anular la orden de envio de mercancia?',\r\n          text: \"La orden y sus productos seran cancelados por completo y no se enviara.\",\r\n          showCancelButton: true,\r\n          confirmButtonText: 'Si',\r\n          cancelButtonText: 'No',\r\n      }).then((result:any) => {\r\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idorden);\r\n                  try {\r\n                      const url = \"/admin/api/anularnuevotrasladoinv\";  //api llamada a trasladosinvcontrolador para anular envio, pasa a estado en transito\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                          tr.remove();\r\n                          Swal.fire(resultado.exito[0], '', 'success') \r\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n\r\n    }\r\n\r\n    function imprimirdatos(detalleorden:ordenestrasladosinv){\r\n      numOrden.textContent = detalleorden.id;\r\n      parrafoSedeorigen.textContent = detalleorden.sucursal_origen;\r\n      parrafoSededestino.textContent = detalleorden.sucursal_destino;\r\n      parrafotipo.textContent = detalleorden.tipo;\r\n      textareaobservacion.textContent = detalleorden.observacion;\r\n      while(tbodydetalleorden.firstChild)tbodydetalleorden.removeChild(tbodydetalleorden.firstChild);\r\n      detalleorden.detalletrasladoinv.forEach(x=>{\r\n        const tr = document.createElement('tr');\r\n        const tdproducto = document.createElement('td');\r\n        tdproducto.classList.add('px-4', 'py-2', 'border');\r\n        tdproducto.textContent = x.nombre;\r\n        const tdcantidad = document.createElement('td');\r\n        tdcantidad.classList.add('px-4', 'py-2', 'border');\r\n        tdcantidad.textContent = x.cantidad;\r\n        const tdunidadmedida = document.createElement('td');\r\n        tdunidadmedida.classList.add('px-4', 'py-2', 'border');\r\n        tdunidadmedida.textContent = x.unidadmedida;\r\n        tr.appendChild(tdproducto);\r\n        tr.appendChild(tdcantidad);\r\n        tr.appendChild(tdunidadmedida);\r\n        tbodydetalleorden.appendChild(tr);\r\n      });\r\n    }\r\n\r\n\r\n    filtroSucursal.addEventListener('change', filtrarTabla);\r\n    filtroEstado.addEventListener('change', filtrarTabla);\r\n\r\n    function filtrarTabla() {\r\n      const sucursal:string = filtroSucursal.value.trim().toLowerCase();\r\n      const estado:string = filtroEstado.value.trim().toLowerCase();\r\n      \r\n      filas.forEach(fila => {\r\n        const textoSucursal:string = fila.cells[1].textContent!.trim().toLowerCase();\r\n        const textoEstado:string = fila.cells[5].textContent!.trim().toLowerCase();\r\n        const coincideSucursal = !sucursal || textoSucursal === sucursal;\r\n        const coincideEstado = !estado || textoEstado === estado;\r\n        fila.style.display = (coincideSucursal && coincideEstado) ? '' : 'none';\r\n      });\r\n    }\r\n\r\n    \r\n    function cerrarDialogoExterno(event:Event) {\r\n      const target = event.target;\r\n       const btnxcerrardetalleorden = (target as HTMLElement).parentElement?.id;\r\n      if (target === miDialogoDetalleTrasladoSolicitud || (target as HTMLInputElement).value === 'salir' || btnxcerrardetalleorden == 'btnXCerrarDetalleTrasladoSolicitud' || target == btnXCerrarDetalleTrasladoSolicitud) {\r\n        miDialogoDetalleTrasladoSolicitud.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n  }\r\n\r\n})();","(()=>{\r\n  if(document.querySelector('.trasladoinventario')){\r\n    const miDialogoDetalleTrasladoSolicitud = document.querySelector('#miDialogoDetalleTrasladoSolicitud') as any;\r\n    const btnXCerrarDetalleTrasladoSolicitud = document.querySelector('#btnXCerrarDetalleTrasladoSolicitud') as HTMLButtonElement;\r\n    const numOrden = document.querySelector('#numOrden') as H