ocument.querySelector('#tablaTraslados')?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if(target?.classList.contains(\"enviar\")||target.parentElement?.classList.contains(\"enviar\"))enviar(e);\r\n      if(target?.classList.contains(\"detalle\")||target.parentElement?.classList.contains(\"detalle\"))detalle(e);\r\n      if(target?.classList.contains(\"cancelar\")||target.parentElement?.classList.contains(\"cancelar\"))cancelar(e);\r\n    });\r\n\r\n\r\n    ////// cuando se envia mercancia, pasa a estado en transito, tambien aplica cuando se solicitar mercancia y en la sede destino despachan, con este btn se recepciona.\r\n    function enviar(e:Event){\r\n      let idorden = (e.target as HTMLElement).parentElement?.id!;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idorden = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n      \r\n      let title:String = '', text:string = '', urlapi:string = '', estado:string = '';\r\n      const tr = (e.target as HTMLElement).closest('tr') as HTMLTableRowElement;\r\n      console.log(tr.children[4].textContent);\r\n      if(tr.children[4].textContent === 'Solicitud'){\r\n        title = 'Desea confirmar la recepcion de la mercancia solicitada?';\r\n        text = \"La marcancia ingresara al inventario de la sucursal y no se podra modificar.\";\r\n        urlapi = 'confirmaringresoinv';\r\n        estado = 'entregada';\r\n      }\r\n      if(tr.children[4].textContent === 'Salida'){\r\n        title = 'Desea confirmar el envio de mercancia?';\r\n        text = \"La orden entrara en estado: 'EN TRANSITO' y sera aceptada o rechazda por la sede de destino.\";\r\n        urlapi = 'confirmarnuevotrasladoinv';\r\n        estado = 'entransito';\r\n      }\r\n      \r\n      Swal.fire({\r\n          customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n          icon: 'question',\r\n          title: title,\r\n          text: text,\r\n          showCancelButton: true,\r\n          confirmButtonText: 'Si',\r\n          cancelButtonText: 'No',\r\n      }).then((result:any) => {\r\n          if (result.isConfirmed) {\r\n              //Swal.fire('orden procesada', '', 'success') \r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idorden);\r\n                  try {\r\n                      const url = \"/admin/api/\"+urlapi;  //api llamada a trasladosinvcontrolador para confirmar envio, pasa a estado en transito\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                        tr.children[5].innerHTML = `<span class=\"px-3 py-1 text-base font-semibold rounded-full ${estado=='entregada'?'bg-sky-50 text-sky-600':estado=='entransito'?'bg-yellow-100 text-yellow-700':'bg-rose-50 text-rose-600'}\">${estado}</span>`;\r\n                        Swal.fire(resultado.exito[0], '', 'success') \r\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    function detalle(e:Event){\r\n      let idorden = (e.target as HTMLElement).parentElement?.id!;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idorden = (e.target as HTMLElement).parentElement?.parentElement?.id!;  \r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/idOrdenTrasladoSolicitudInv?id=\"+idorden; //llamado a la API REST y trae el detalle de la orden trasladar/solicitud desde trasladarinvcontrolador.php\r\n          const respuesta = await fetch(url);\r\n          const resultado = await respuesta.json();\r\n          imprimirdatos(resultado.orden[0]);\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n\r\n      //unaorden = ordenes.find(x=>x.id === idorden)!; //obtengo el producto.\r\n      miDialogoDetalleTrasladoSolicitud.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    }\r\n\r\n\r\n    function cancelar(e:Event){\r\n      let idorden = (e.target as HTMLElement).parentElement?.id!;\r\n      if((e.target as HTMLElement)?.tagName === 'I')idorden = (e.target as HTMLElement).parentElement?.parentElement?.id!;\r\n      const tr = (e.target as HTMLElement).closest('tr') as HTMLTableRowElement;\r\n      Swal.fire({\r\n          customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n          icon: 'question',\r\n          title: 'Desea anular la orden de envio de mercancia?',\r\n          text: \"La orden y sus productos seran cancelados por completo y no se enviara.\",\r\n          showCancelButton: true,\r\n          confirmButtonText: 'Si',\r\n          cancelButtonText: 'No',\r\n      }).then((result:any) => {\r\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', idorden);\r\n                  try {\r\n                      const url = \"/admin/api/anularnuevotrasladoinv\";  //api llamada a trasladosinvcontrolador para anular envio, pasa a estado en transito\r\n                      const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                      const resultado = await respuesta.json();  \r\n                      if(resultado.exito !== undefined){\r\n                          tr.remove();\r\n                          Swal.fire(resultado.exito[0], '', 'success') \r\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n\r\n    }\r\n\r\n    function imprimirdatos(detalleorden:ordenestrasladosinv){\r\n      numOrden.textContent = detalleorden.id;\r\n      parrafoSedeorigen.textContent = detalleorden.sucursal_origen;\r\n      parrafoSededestino.textContent = detalleorden.sucursal_destino;\r\n      parrafotipo.textContent = detalleorden.tipo;\r\n      textareaobservacion.textContent = detalleorden.observacion;\r\n      while(tbodydetalleorden.firstChild)tbodydetalleorden.removeChild(tbodydetalleorden.firstChild);\r\n      detalleorden.detalletrasladoinv.forEach(x=>{\r\n        const tr = document.createElement('tr');\r\n        const tdproducto = document.createElement('td');\r\n        tdproducto.classList.add('px-4', 'py-2', 'border');\r\n        tdproducto.textContent = x.nombre;\r\n        const tdcantidad = document.createElement('td');\r\n        tdcantidad.classList.add('px-4', 'py-2', 'border');\r\n        tdcantidad.textContent = x.cantidad;\r\n        const tdunidadmedida = document.createElement('td');\r\n        tdunidadmedida.classList.add('px-4', 'py-2', 'border');\r\n        tdunidadmedida.textContent = x.unidadmedida;\r\n        tr.appendChild(tdproducto);\r\n        tr.appendChild(tdcantidad);\r\n        tr.appendChild(tdunidadmedida);\r\n        tbodydetalleorden.appendChild(tr);\r\n      });\r\n    }\r\n\r\n    filtroSucursal.addEventListener('change', filtrarTabla);\r\n    filtroEstado.addEventListener('change', filtrarTabla);\r\n\r\n    function filtrarTabla() {\r\n      const sucursal:string = filtroSucursal.value.trim().toLowerCase();\r\n      const estado:string = filtroEstado.value.trim().toLowerCase();\r\n      \r\n      filas.forEach(fila => {\r\n        const textoSucursal:string = fila.cells[1].textContent!.trim().toLowerCase();\r\n        const textoEstado:string = fila.cells[5].textContent!.trim().toLowerCase();\r\n        const coincideSucursal = !sucursal || textoSucursal === sucursal;\r\n        const coincideEstado = !estado || textoEstado === estado;\r\n        fila.style.display = (coincideSucursal && coincideEstado) ? '' : 'none';\r\n      });\r\n    }\r\n\r\n    \r\n    function cerrarDialogoExterno(event:Event) {\r\n      const target = event.target;\r\n       const btnxcerrardetalleorden = (target as HTMLElement).parentElement?.id;\r\n      if (target === miDialogoDetalleTrasladoSolicitud || (target as HTMLInputElement).value === 'salir' || btnxcerrardetalleorden == 'btnXCerrarDetalleTrasladoSolicitud' || target == btnXCerrarDetalleTrasladoSolicitud) {\r\n        miDialogoDetalleTrasladoSolicitud.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n  }\r\n\r\n})();","(function(){\r\n  if(document.querySelector('.contenedorsetup')){\r\n\r\n    const radios = document.querySelectorAll<HTMLInputElement>('.contenedorsetup input[type=\"radio\"]');\r\n    const claves = document.querySelectorAll<HTMLInputElement>('.keyinput');\r\n    const porcentaje_de_impuesto = document.querySelector('#porcentaje_de_impuesto') as HTMLSelectElement;\r\n    const indicador_caja = document.querySelector('#indicador_caja') as HTMLSelectElement;\r\n    const medidaFuenteDatosFactura = document.querySelector('#medidaFuenteDatosFactura') as HTMLSelectElement;\n    const medidaFuenteSeccionClienteFactura = document.querySelector('#medidaFuenteSeccionClienteFactura') as HTMLSelectElement;\n    const medidaFuenteProductosFactura = document.querySelector('#medidaFuenteProductosFactura') as HTMLSelectElement;\n    const resaltarParametroGuardado = (elemento:HTMLElement|null)=>{\n      if(!elemento)return;\n      const contenedor = elemento.closest('.config-system-content .accordion_tab_content > .grid > div, .config-whatsapp-event') as HTMLElement|null;\n      const objetivo = contenedor ?? elemento;\n      objetivo.classList.remove('config-param-saved');\n      window.setTimeout(()=>objetivo.classList.add('config-param-saved'), 20);\n      window.setTimeout(()=>objetivo.classList.remove('config-param-saved'), 1800);\n    };\n\r\n    radios.forEach(radio => {\r\n      radio.addEventListener('change', () => {\r\n        // Obtenemos el grupo (name) del radio\r\n        const grupo:string = radio.name;\r\n        // Obtenemos la opción seleccionada de ese grupo\r\n        const seleccionado = document.querySelector(`input[name=\"${grupo}\"]:checked`) as HTMLInputElement;\r\n\r\n        //console.log(`${grupo}, Opción seleccionada: ${seleccionado.value}`);\r\n        cambiarparametro(grupo, seleccionado.value, seleccionado);\n      });\r\n    });\r\n\r\n    ////////////// inputs tipo radio  ////////////////\r\n    function cambiarparametro(clave:string, valor:string, elemento?:HTMLElement){\n      const datos = new FormData();\r\n      datos.append(clave, valor);\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/parametrosSistema\";  //api llamada en parametroscontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\n              resaltarParametroGuardado(elemento ?? null);\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            }else{\r\n              msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n    }\r\n\r\n    //////////  CLAVES  ////////////\r\n    ///////////  eventos a los inputs de las claves, limite de descuento, cantidad de zeta diarios etc 'Campos de entrada' /////////////\r\n    claves.forEach(c=>{\r\n      c.addEventListener('input', (e)=>{  \r\n        const inputClave = (e.target as HTMLInputElement);\r\n        const valorClave = (e.target as HTMLInputElement).value;\r\n        \r\n        (async ()=>{\r\n          const datos = new FormData();\r\n          datos.append(inputClave.name, valorClave);\r\n          try {\r\n              const url = \"/admin/api/parametrosSistemaClaves\";  //api llamada en parametroscontrolador.php\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();\r\n              if(resultado.exito !== undefined){\n                resaltarParametroGuardado(inputClave);\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();\r\n      });\r\n    });\r\n\r\n\r\n\r\n    //////////////////   campo tipo de impuesto (%)   /////////////////////\r\n    porcentaje_de_impuesto?.addEventListener('input', parametrosSistemaTipoSelect);\r\n    //////////////////   Indicadores de caja   /////////////////////\r\n    indicador_caja?.addEventListener('input', parametrosSistemaTipoSelect);\r\n    //////////////////   Indicadores de caja   /////////////////////\r\n    medidaFuenteDatosFactura?.addEventListener('input', parametrosSistemaTipoSelect);\r\n    //////////////////   Indicadores de caja   /////////////////////\r\n    medidaFuenteSeccionClienteFactura?.addEventListener('input', parametrosSistemaTipoSelect);\r\n    //////////////////   Indicadores de caja   /////////////////////\r\n    medidaFuenteProductosFactura?.addEventListener('input', parametrosSistemaTipoSelect);\r\n\r\n\r\n    function parametrosSistemaTipoSelect(e:Event){\r\n      const select = (e.target as HTMLSelectElement);\r\n      (async ()=>{\r\n          const datos = new FormData();\r\n          datos.append(select.name, select.value);\r\n          try {\r\n              const url = \"/admin/api/parametrosSistemaTipoSelect\";  //api llamada en parametroscontrolador.php\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();\r\n              if(resultado.exito !== undefined){\n                resaltarParametroGuardado(select);\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n      })();\r\n    }\r\n\r\n    \r\n  }\r\n\r\n})();\n","(():void=>{\r\n  if(document.querySelector('.configNotificationWS')){\r\n\r\n    const nombreWS = document.querySelector('#nombreWS') as HTMLInputElement;\r\n    const movilWS = document.querySelector('#movilWS') as HTMLInputElement;\r\n    const tipoWS = document.querySelector('#tipoWS') as HTMLInputElement;\r\n    const tablaNumbersWS = document.querySelector('#tablaNumbersWS tbody') as HTMLTableElement;\r\n    let indiceFila=0, control=0;\r\n\r\n    tablaNumbersWS?.addEventListener(\"click\", (e)=>{ //evento click sobre toda la tabla\r\n      const target = e.target as HTMLElement;\r\n      if(target?.classList.contains(\"test\"))sendTest(target.closest('tr')?.id);//console.log(target.closest('tr'));\r\n      if(target?.classList.contains(\"eliminarContacto\")||target.parentElement?.classList.contains(\"eliminarContacto\"))deleteContactNotificationWS(e);\r\n    });\r\n    \r\n\r\n    async function sendTest(id:string|undefined){\r\n      try {\r\n          const url = \"/admin/api/ws/notificacionWS/sendTest?id=\"+id;\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json(); \r\n          if(resultado && resultado.code === 200 && !resultado.error){\r\n            msjalertToast('success', '¡Éxito!', 'Mensaje de prueba enviado');\r\n          }else{\r\n              msjalertToast('error', '¡Error!', 'Error al enviar el test');\r\n          }\r\n      } catch (error) {\r\n          console.log(error)\r\n      }\r\n    }\r\n\r\n\r\n    ////////////////////  Eliminar contacto de notificacion de whatsapp  //////////////////////\r\n    function deleteContactNotificationWS(e:Event){\r\n      const fila = (e.target as HTMLTableRowElement).closest('tr');\r\n      if(!fila)return;\r\n\r\n      indiceFila = Number(fila.id);\r\n      if(!Number.isInteger(indiceFila))return;\r\n\r\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          icon: 'warning',\n          title: 'Eliminar contacto',\n          html: 'El destino de notificacion de WhatsApp sera eliminado definitivamente.',\n          showCancelButton: true,\n          confirmButtonText: 'Si, eliminar',\n          cancelButtonText: 'Cancelar',\n          buttonsStyling: false\n      }).then((result:any) => {\n          if (result.isConfirmed) {\r\n              (async ()=>{ \r\n                  const datos = new FormData();\r\n                  datos.append('id', indiceFila+'');\r\n                  try {\r\n                      const url = \"/admin/api/ws/notificacionWS/eliminarContacto?id=\"+indiceFila;\r\n                      const respuesta = await fetch(url); \r\n                      const resultado = await respuesta.json(); \r\n                      if(resultado.exito !== undefined){\r\n                        fila.remove();\n                        Swal.fire({\n                          customClass: {\n                            popup: 'j2-confirm j2-confirm--success',\n                            icon: 'j2-confirm__icon',\n                            title: 'j2-confirm__title',\n                            htmlContainer: 'j2-confirm__text',\n                            actions: 'j2-confirm__actions j2-confirm__actions--single',\n                            confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                          },\n                          icon: 'success',\n                          title: 'Contacto eliminado',\n                          html: resultado.exito[0] ?? 'El contacto fue eliminado correctamente.',\n                          confirmButtonText: 'OK',\n                          buttonsStyling: false\n                        })\n                      }else{\r\n                          Swal.fire(resultado.error[0], '', 'error')\r\n                      }\r\n                  } catch (error) {\r\n                      console.log(error);\r\n                  }\r\n              })();//cierre de async()\r\n          }\r\n      });\r\n    }\r\n\r\n    ////////////////////  Crear contacto para notificacion de whatsapp  //////////////////////\r\n    document.querySelector('#formCreateContactNotifcationWs')?.addEventListener('submit', e=>{\r\n        e.preventDefault();\r\n        \r\n        (async ()=>{ \r\n          const datos = new FormData();\r\n          //datos.append('id', unacaja?.id?unacaja?.id:'');\r\n          datos.append('nombre', nombreWS.value);\r\n          datos.append('movil', movilWS.value);\r\n          datos.append('tipo', tipoWS.value);\r\n          try {\r\n              const url = \"/admin/api/ws/notificacionWS/crearContacto\";\r\n              const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n              const resultado = await respuesta.json();  \r\n              if(resultado.exito !== undefined){\r\n                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                const tr = document.createElement('tr');\r\n                tr.id = resultado.data[1];\n                tr.insertAdjacentHTML('afterbegin', `\n                  <td><span class=\"config-whatsapp-contact\"><i class=\"fa-brands fa-whatsapp\"></i>${nombreWS.value}</span></td>\n                  <td><span class=\"config-whatsapp-pill config-whatsapp-pill--phone\">${movilWS.value}</span></td>\n                  <td><span class=\"config-whatsapp-pill\">${ tipoWS.value}</span></td>\n                  <td><button class=\"test config-whatsapp-action config-whatsapp-action--test\" type=\"button\">Test</button></td>\n                  <td><span class=\"config-whatsapp-status\">Activo</span></td>\n                  <td><button class=\"config-whatsapp-icon-button eliminarContacto\" type=\"button\" title=\"Eliminar contacto\"><i class=\"fa-solid fa-trash-can\"></i></button></td>`);\n                tablaNumbersWS?.appendChild(tr);\r\n                (document.querySelector('#formCreateContactNotifcationWs') as HTMLFormElement)?.reset();\r\n              }else{\r\n                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        })();//cierre de async()\r\n    });\r\n\r\n\r\n\r\n  }\r\n\r\n})();\n","(()=>{\r\n\r\n    if(document.querySelector('.configsuscripcion')){\r\n        const btnDetalleSuscriptor = document.getElementById('btnDetalleSuscriptor') as HTMLButtonElement;\r\n        const btnRegistrarPago = document.getElementById('btnRegistrarPago') as HTMLButtonElement;\r\n        const miDialogoRegistrarPago:any = document.querySelector(\"#miDialogoRegistrarPago\");\r\n        const miDialogoDetalleSuscripcion:any = document.querySelector(\"#miDialogoDetalleSuscripcion\");\r\n        const estadoText = document.querySelector('#estadoText') as HTMLParagraphElement;\r\n\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n\r\n        btnDetalleSuscriptor?.addEventListener('click',()=>{\r\n            miDialogoDetalleSuscripcion.showModal();\r\n        });\r\n        btnRegistrarPago?.addEventListener('click',()=>{\r\n            miDialogoRegistrarPago.showModal();\r\n        });\r\n\r\n\r\n        document.querySelector('#formDetalleSuscripcion')?.addEventListener('submit', async(e:Event)=>{\r\n            e.preventDefault();\r\n            const form = e.target as HTMLFormElement;\r\n            const formData = new FormData(form);\r\n            const data = Object.fromEntries(formData.entries());\r\n            const detalleSuscrip = {\r\n                idplan: data.idplan,\r\n                valorplan: Number(data.valorplan)||0,\r\n                fecha_corte: data.fecha_corte,\r\n                estado: data.estado,\r\n                descuento: Number(data.descuento)||0,\r\n                detalledescuento: data.detalle_descuento,\r\n                cargo: Number(data.cargo)||0,\r\n                detallecargo: data.detalle_cargo,\r\n            }\r\n            try {\r\n                const url = \"/admin/api/suscripcion/detalleSuscripcion\"; //llamado a la API REST suscripcioncontrolador.php actualiza la sucursal\r\n                const respuesta = await fetch(url, {\r\n                                            method: 'POST', \r\n                                            headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                            body: JSON.stringify(detalleSuscrip) \r\n                                        });\r\n                const resultado = await respuesta.json();\r\n                console.log(resultado);\r\n                if(resultado.exito != undefined){\r\n                    msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                    actualizarDetalleSuscripcion(detalleSuscrip);\r\n                }else{\r\n                    msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                }\r\n\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n           miDialogoDetalleSuscripcion.close();\r\n        });\r\n\r\n\r\n        document.querySelector('#formRegistrarPago')?.addEventListener('submit', async(e:Event)=>{\r\n            e.preventDefault();\r\n            const form = e.target as HTMLFormElement;\r\n            const formData = new FormData(form);\r\n            const data = Object.fromEntries(formData.entries());\r\n            const pago = {\r\n                cantidad_plan: data.cantidad_plan,\r\n                valor_pagado: Number(data.valor_pagado)||0,\r\n                mediopago: data.medio_pago,\r\n                descripcion: data.descripcion,\r\n            }\r\n            try {\r\n                const url = \"/admin/api/suscripcion/registrarPago\"; //llamado a la API REST suscripcioncontrolador.php\r\n                const respuesta = await fetch(url, {\r\n                                            method: 'POST', \r\n                                            headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                            body: JSON.stringify(pago) \r\n                                        });\r\n                const resultado = await respuesta.json();\r\n                console.log(resultado);\r\n                if(resultado.exito != undefined){\r\n                    msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                    actualizarDetalleSuscripcion(resultado.sucursal);\r\n                }else{\r\n                    msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                }\r\n                miDialogoRegistrarPago.close();\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n    \r\n        });\r\n\r\n\r\n        function actualizarDetalleSuscripcion(detalleSuscrip:{valorplan: number, fecha_corte: FormDataEntryValue, estado: FormDataEntryValue, descuento: number, detalledescuento: FormDataEntryValue, cargo: number, detallecargo: FormDataEntryValue}){\n            const formatoMoneda = (valor:number) => '$'+valor.toLocaleString('es-CO');\n            const total = detalleSuscrip.valorplan + detalleSuscrip.cargo - detalleSuscrip.descuento;\n            (document.querySelector('#fecha_corteText') as HTMLParagraphElement).textContent = detalleSuscrip.fecha_corte as string;\n            (document.querySelector('#valorplanText') as HTMLParagraphElement).textContent = formatoMoneda(detalleSuscrip.valorplan);\n            (document.querySelector('#valorplanResumen') as HTMLParagraphElement).textContent = formatoMoneda(detalleSuscrip.valorplan);\n            (document.querySelector('#totalSuscripcionText') as HTMLParagraphElement).textContent = formatoMoneda(total);\n            estadoText.textContent = detalleSuscrip.estado == '1'?\"Activo\":\"Suspendido\";\n            if (detalleSuscrip.estado === '1') {\n                estadoText.classList.replace('bg-red-100', 'bg-green-100');\n                estadoText.classList.replace('text-red-700', 'text-green-700');\n                estadoText.classList.remove('config-subscription-status--paused');\n                estadoText.classList.add('config-subscription-status--active');\n            } else {\n                estadoText.classList.replace('bg-green-100', 'bg-red-100');\n                estadoText.classList.replace('text-green-700', 'text-red-700');\n                estadoText.classList.remove('config-subscription-status--active');\n                estadoText.classList.add('config-subscription-status--paused');\n            }\n        }\n\r\n\r\n        function cerrarDialogoExterno(event:Event) {\r\n            const f = event.target;\r\n            if (f=== miDialogoRegistrarPago || f === miDialogoDetalleSuscripcion || (f as HTMLInputElement).value === 'Cancelar' || (f as HTMLButtonElement).closest('.btnXCerrarRegistroPago') ) {\r\n                miDialogoRegistrarPago.close();\r\n                miDialogoDetalleSuscripcion.close();\r\n            }\r\n        }\r\n        \r\n    }\r\n\r\n\r\n})();\n","(()=>{\r\n    if(!document.querySelector('.gestionDian'))return;\r\n    const POS = (window as any).POS;\r\n\r\n    const btnAdquirirCompañia = document.querySelector('#btnAdquirirCompañia') as HTMLButtonElement;\r\n    const miDialogoAdquirirCompañia = document.querySelector('#miDialogoAdquirirCompañia') as any;\r\n\r\n    btnAdquirirCompañia.addEventListener('click', ()=>{\r\n        miDialogoAdquirirCompañia.showModal();\r\n        document.addEventListener(\"click\", POS.cerrarDialogoExterno);\r\n    });\r\n\r\n    ///////    CONSULTAR COMPAÑIA POR NIT   ///////\r\n    document.querySelector('#formAdquirirCompañia')?.addEventListener('submit', async (e:Event)=>{\r\n      e.preventDefault();\r\n      const nit = (document.querySelector('#nitcompany') as HTMLInputElement).value;\r\n      const adquirirCompañiaPassword = (document.querySelector('#adquirirCompañiaPassword') as HTMLInputElement).value;\r\n      miDialogoAdquirirCompañia.close();\r\n      document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\r\n      try {\r\n        const url = `https://apidianj2.com/api/getCompany/${nit}`; //llamado a la API REST Dian-laravel para consultar la compañia por nit\r\n        const respuesta = await fetch(url);\r\n        const resultado = await respuesta.json();\r\n        const idcompany = await POS.crearCompanyJ2({ business_name:resultado.compañia.user.name, identification_number: resultado.compañia.identification_number, idsoftware: resultado.compañia.software.identifier, pinsoftware:12345, estado:1 }, resultado.compañia.user.api_token);\r\n        \r\n        /////    crear resolucion para NC    ///////\r\n        const extprefix = (resultado.compañia.user.name).match(/[a-zA-Z]/g)!;\r\n        const a:string = extprefix[0];\r\n        const b:string = extprefix[extprefix.length-1];\r\n        POS.crearResolucionNCJ2({ type_document_id: '4', prefix: 'NC'+a+b, from: '1', to: '99999999' }, resultado.compañia.identification_number, idcompany);\r\n      } catch (error) {\r\n        console.log(error);\r\n      }\r\n    });\r\n\r\n\r\n    const gestionAdquirirCompany = {  //objeto a exportar\r\n        miDialogoAdquirirCompañia,\r\n    };\r\n\r\n    POS.gestionAdquirirCompany = gestionAdquirirCompany;\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.gestionDian'))return;\r\n    const POS = (window as any).POS;\r\n\r\n    const selectDepartments = document.querySelector('#department_id') as HTMLSelectElement;\r\n    const selectdCities = document.querySelector('#municipality_id') as HTMLSelectElement;\r\n\r\n    type municipalities = {\r\n        id:string,\r\n        department_id:string,\r\n        name:string,\r\n        code:string,\r\n      };\r\n      let cities:municipalities[]=[];\r\n\r\n    /////       Obtener municipio segun departamento        ///////\r\n    selectDepartments?.addEventListener('change', (e:Event)=>{\r\n      const x:HTMLOptionElement = (e.target as HTMLOptionElement);\r\n      imprimirCiudades(x.value);\r\n    });\r\n\r\n    function imprimirCiudades(x:string){\r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/citiesXdepartments?id=\"+x; //llamado a la API REST y se trae las cities segun cliente elegido\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json(); \r\n          if(resultado.error){\r\n            Swal.fire(resultado.error[0], '', 'error')\r\n          }else{\r\n            cities = resultado;\r\n            addCitiesToSelect(cities);\r\n          }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n    }\r\n       \r\n    function addCitiesToSelect<T extends {id:string, department_id:string, name:string, code:string}>(addrs: T[]):void{\r\n      while(selectdCities?.firstChild)selectdCities.removeChild(selectdCities?.firstChild);\r\n      addrs.forEach(x =>{\r\n        const option = document.createElement('option');\r\n        option.textContent = x.name;\r\n        option.value = x.id;\r\n        option.dataset.code = x.code;\r\n        option.dataset.department_id = x.department_id;\r\n        selectdCities.appendChild(option);\r\n      });\r\n      \r\n    }\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.gestionDian'))return;\r\n    const POS = (window as any).POS;\r\n\r\n    const selectResolucioncompañia = document.querySelector('#selectResolucioncompañia') as HTMLSelectElement;\n    const miDialogoGetResolucion = document.querySelector('#miDialogoGetResolucion') as any;\n\n    function escapeHtmlDianResolution(valor:unknown):string{\n      return String(valor ?? '').replace(/[&<>\"']/g, caracter => ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#039;'\n      }[caracter] as string));\n    }\n\r\n    ///////    CONSULTAR RESOLUCIONES   ///////\r\n    document.querySelector('#formGetResolucion')?.addEventListener('submit', (e:Event)=>{\r\n      e.preventDefault();\r\n      const id:string = selectResolucioncompañia.options[selectResolucioncompañia.selectedIndex].value;\r\n      const companiesAll = POS.companiesAll as companiesDian[];\r\n      const oneC = companiesAll.find(x=>x.id == id)!;\r\n      getResolutions(oneC.id, oneC.idsoftware, oneC.token);\r\n    });\r\n\r\n    async function getResolutions(idcompany:string, idsoftware:string, token:string){\r\n      try {\r\n        const url = \"https://apidianj2.com/api/ubl2.1/numbering-range\"; //llamado a la API REST Dian-laravel para consultar las resoluciones\r\n        const respuesta = await fetch(url, {\r\n                                              method: 'POST',\r\n                                              headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\", \"Authorization\": \"Bearer \"+token },\r\n                                              body: JSON.stringify({\"IDSoftware\": idsoftware})\r\n                                            });\r\n        const resultado = await respuesta.json();\r\n        let arrayResolutions = resultado.ResponseDian.Envelope.Body.GetNumberingRangeResponse.GetNumberingRangeResult.ResponseList.NumberRangeResponse;\r\n        if(typeof arrayResolutions == 'object')arrayResolutions = [arrayResolutions];\r\n        if(arrayResolutions&&arrayResolutions.length>0)printResolutions(idcompany, arrayResolutions, token);\r\n      } catch (error) {\r\n        console.log(error);  \r\n      }\r\n    }\r\n\r\n    function printResolutions(idcompany:string, arrayResolutions:NumberRangeItem[], token:string){\r\n      const tablaListResolutions = document.querySelector('#tablaListResolutions tbody') as HTMLTableElement;\r\n      while(tablaListResolutions.firstChild)tablaListResolutions.removeChild(tablaListResolutions.firstChild);\r\n      arrayResolutions.forEach(r =>{\r\n        tablaListResolutions.insertAdjacentHTML('beforeend',\n          `<tr>\n              <td><span class=\"config-table-pill config-table-pill--invoice\">${escapeHtmlDianResolution(r.Prefix)}</span></td>\n              <td><span class=\"config-table-pill config-table-pill--document\">${escapeHtmlDianResolution(r.ResolutionNumber)}</span></td>\n              <td><span class=\"config-table-pill config-table-pill--range\">${escapeHtmlDianResolution(r.FromNumber)} - ${escapeHtmlDianResolution(r.ToNumber)}</span></td>\n              <td><span class=\"config-table-pill config-table-pill--date\">${escapeHtmlDianResolution(r.ValidDateTo)}</span></td>\n              <td class=\"accionestd\"><button class=\"downResolution\" type=\"button\" id=\"${escapeHtmlDianResolution(r.ResolutionNumber)}\" data-company=\"${escapeHtmlDianResolution(idcompany)}\" title=\"Asociar resolucion\"><i class=\"fa-solid fa-download\"></i></button></td>\n          </tr>`\n        )\n      });\r\n      tablaListResolutions.addEventListener('click', e=> descargarResolucion(e, arrayResolutions, token) );\r\n    }\r\n\r\n\r\n    async function descargarResolucion(e:Event, arrayResolutions:NumberRangeItem[], token:string){\r\n      const target = (e.target as HTMLElement).closest('.downResolution') as HTMLButtonElement | null;\n      if(target){\n        const idcompany:string = target.dataset.company!;\r\n        const numberResolution = target.id;\r\n        const resolutionSelected = arrayResolutions.find(x=>x.ResolutionNumber === numberResolution)!;\r\n        resolutionSelected.idcompany = idcompany;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        try {\r\n          const url = `/admin/api/guardarResolutionJ2`; //llamado a la API para guardar la resolucion DIAN\r\n          const respuesta = await fetch(url,  { method: 'POST',\r\n                                                headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                                body: JSON.stringify(resolutionSelected)\r\n                                              });\r\n          const resultado = await respuesta.json();\r\n\r\n          //almacenar la resolucion obtenido de la dian en la API \r\n          const resolucion = {\r\n                  type_document_id:'1', \r\n                  prefix: resolutionSelected.Prefix, \r\n                  resolution: resolutionSelected.ResolutionNumber, \r\n                  resolution_date: resolutionSelected.ResolutionDate, \r\n                  technical_key: typeof resolutionSelected.TechnicalKey === 'string'?resolutionSelected.TechnicalKey:'', \r\n                  from: resolutionSelected.FromNumber, \r\n                  to: resolutionSelected.ToNumber, \r\n                  generated_to_date:'0', \r\n                  date_from: resolutionSelected.ValidDateFrom, \r\n                  date_to: resolutionSelected.ValidDateTo\r\n              };\r\n          const sendresolToAPI = await POS.crearResolucion(resolucion, token);\r\n\r\n          (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n\r\n          if(sendresolToAPI)msjalertToast('success', '¡Éxito!', 'Resoluccion asociada exitosamnete.');\r\n\r\n\r\n          if(resultado.exito != undefined){\r\n            const existeResol:number = POS.facturadores.findIndex((x:any)=>x.id==resultado.facturador.id&&x.resolucion == resolutionSelected?.ResolutionNumber);\r\n            if(existeResol === -1){ //si no existe consecutibo imprmir\r\n              // actualizar el arreglo de facturador\r\n              POS.facturadores.push(resultado.facturador); //= [...facturadores, resultado.facturador];\r\n              //insertar en vista facturador\r\n              const tablaFacturadores = ($('#tablaFacturadores') as any).DataTable(configdatatables);\n              (tablaFacturadores as any).row.add([\n                        (tablaFacturadores as any).rows().count() + 1,\n                        `<span class=\"config-facturador-name\"><span class=\"config-facturador-name__icon\"><i class=\"fa-solid fa-receipt\"></i></span><span>${escapeHtmlDianResolution(resultado.facturador.nombre)}</span></span>`,\n                        '<span class=\"config-table-pill config-table-pill--type\">ELECTRONICA</span>',\n                        `<span class=\"config-table-pill config-table-pill--range\">${escapeHtmlDianResolution(resolutionSelected?.FromNumber)} - ${escapeHtmlDianResolution(resolutionSelected?.ToNumber)}</span>`,\n                        '<span class=\"config-table-pill config-table-pill--next\">1</span>',\n                        `<span class=\"config-table-pill config-table-pill--date\">${escapeHtmlDianResolution(resolutionSelected?.ValidDateTo)}</span>`,\n                        '<span class=\"config-table-status config-table-status--active\">Activo</span>',\n                        `<div class=\"acciones-btns\" id=\"${resultado.facturador.id}\" data-facturador=\"${resultado.facturador.nombre}\">\r\n                            <button class=\"btn-md btn-turquoise editarFacturador\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\r\n                            <button class=\"btn-md btn-red eliminarFacturador\"><i class=\"fa-solid fa-trash-can\"></i></button>\r\n                        </div>`\r\n                    ]).draw(false);\r\n              //insertar facturador en caja para seleccionar\r\n              crearConsecutivoGestionCaja(resultado.facturador.id, resultado.facturador.nombre);\r\n            }\r\n          }\r\n        } catch (error) {\r\n          console.log(error);\r\n        }\r\n        miDialogoGetResolucion.close();\r\n        document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\r\n      }//fin button\r\n    }//fin funcion descargarResolucion\r\n\r\n    \r\n    function crearConsecutivoGestionCaja(idfacturador:string, nombre:string){\r\n      const selectConsecutivoCaja = document.querySelector('#idtipoconsecutivo') as HTMLSelectElement;\r\n      const option = document.createElement('option');\r\n      option.value = idfacturador;\r\n      option.textContent = nombre;\r\n      selectConsecutivoCaja.appendChild(option);\r\n    }\r\n\r\n    const gestionarGetResolutions = {  //objeto a exportar\r\n        miDialogoGetResolucion,\r\n        selectResolucioncompañia,\r\n    };\r\n\r\n    POS.gestionarGetResolutions = gestionarGetResolutions;\r\n\r\n})();\n","(()=>{\r\n    if(!document.querySelector('.gestionDian'))return;\r\n    const POS = (window as any).POS;\r\n\r\n    const miDialogosetpruebas = document.querySelector('#miDialogosetpruebas') as any;\r\n    const selectSetCompañia = document.querySelector('#selectSetCompañia') as HTMLSelectElement;\r\n\r\n    ///////   ENVIAR SET DE PRUEBAS    ///////\r\n    document.querySelector('#formSetPruebas')?.addEventListener('submit', async(e:Event)=>{\r\n      e.preventDefault();\r\n      const id = selectSetCompañia.options[selectSetCompañia.selectedIndex]?.value;\r\n      const test = document.querySelector('#idsetpruebas') as HTMLInputElement;\r\n\r\n      const companiesAll = POS.companiesAll as companiesDian[];\r\n\r\n      const oneC = companiesAll.find(x=>x.id == id)!;\r\n      const token = oneC.token;\r\n\r\n      const date = new Date().toLocaleDateString('sv-SE');\r\n      const number = 992500000 + (Math.floor(Math.random()*500000)+1);  //rango de 1 a 500000\r\n\r\n      const factura = {\r\n        prefix: \"SETP\",\r\n        number, // dinámico\r\n        type_document_id: \"1\",\r\n        date,   // dinámico\r\n        time: \"00:00:01\",\r\n        resolution_number: \"18760000001\",\r\n        sendmail: false,\r\n        notes: \"Factura Electrónica de pruebas Auto\",\r\n        payment_form: {\r\n          payment_form_id: \"1\",\r\n          payment_method_id: \"10\",\r\n          payment_due_date: date,\r\n          duration_measure: \"0\"\r\n        },\r\n        customer: {\r\n          identification_number: \"222222222222\",\r\n          name: \"Consumidor Final\",\r\n          phone: null,\r\n          address: null,\r\n          type_document_identification_id: 3,\r\n          type_organization_id: 1,\r\n          municipality_id: null\r\n        },\r\n        invoice_lines: [\r\n          {\r\n            unit_measure_id: \"70\",\r\n            invoiced_quantity: \"1.00\",\r\n            line_extension_amount: \"2000.00\",\r\n            free_of_charge_indicator: false,\r\n            tax_totals: [\r\n              {\r\n                tax_id: 1,\r\n                tax_amount: \"0.00\",\r\n                taxable_amount: \"2000.00\",\r\n                percent: \"0\"\r\n              }\r\n            ],\r\n            description: \"Producto Prueba\",\r\n            code: \"155\",\r\n            type_item_identification_id: \"4\",\r\n            price_amount: \"2000.00\",\r\n            base_quantity: \"1\"\r\n          }\r\n        ],\r\n        legal_monetary_totals: {\r\n          line_extension_amount: \"2000\",\r\n          tax_exclusive_amount: \"2000\",\r\n          tax_inclusive_amount: \"2000\",\r\n          allowance_total_amount: \"0\",\r\n          charge_total_amount: \"0\",\r\n          payable_amount: \"2000\"\r\n        },\r\n        tax_totals: [\r\n          {\r\n            tax_id: 1,\r\n            tax_amount: \"0.00\",\r\n            percent: \"0\",\r\n            taxable_amount: \"2000.00\"\r\n          }\r\n        ]\r\n      };\r\n\r\n      try {\r\n        const url = \"https://apidianj2.com/api/ubl2.1/invoice/\"+test.value; //llamado a la API REST Dianlaravel\r\n        const respuesta = await fetch(url, {\r\n                                              method: 'POST',\r\n                                              headers: {\r\n                                                \"Accept\": \"application/json\",\r\n                                                \"Content-Type\": \"application/json\",\r\n                                                \"Authorization\": \"Bearer \"+token\r\n                                              },\r\n                                              body: JSON.stringify(factura)\r\n                                            });\r\n        const resultado = await respuesta.json();\r\n        modoproduccion(token);\r\n        miDialogosetpruebas.close();\r\n        document.removeEventListener(\"click\", POS.cerrarDialogoExterno);\r\n        return resultado.success;\r\n      } catch (error) {\r\n        console.log(error);\r\n        return false;\r\n      }\r\n    });\r\n\r\n    ///////    ENVIOREMNET MODO PRUEBAS - PRODUCCION    ///////\r\n    async function modoproduccion(token?:string){\r\n      try {\r\n        const url = \"https://apidianj2.com/api/ubl2.1/config/environment\"; //llamado a la API REST Dian-laravel\r\n        const respuesta = await fetch(url, {\r\n                                              method: 'PUT',\r\n                                              headers: {\r\n                                                \"Accept\": \"application/json\",\r\n                                                \"Content-Type\": \"application/json\",\r\n                                                \"Authorization\": \"Bearer \"+token\r\n                                              },\r\n                                              body: JSON.stringify({\"type_environment_id\": 1, \"payroll_type_environment_id\": 2})\r\n                                            });\r\n        const resultado = await respuesta.json();\r\n        msjalertToast('success', '¡Éxito!', 'Modo de producción activado correctamente.');\r\n        return resultado.success;\r\n      } catch (error) {\r\n        console.log(error);\r\n        return false;\r\n      }\r\n\r\n    }\r\n\r\n    const gestionarSetPruebas = {  //objeto a exportar\r\n        miDialogosetpruebas,\r\n        selectSetCompañia,\r\n    };\r\n\r\n  POS.gestionarSetPruebas = gestionarSetPruebas;\r\n\r\n})();","(():void=>{\r\n  if(document.querySelector('.gestionDian')){\r\n    const POS = (window as any).POS;\r\n    const btnCrearCompañia = document.querySelector('#btnCrearCompañia') as HTMLButtonElement;\r\n    const btnObtenerresolucion = document.querySelector('#btnObtenerresolucion') as HTMLButtonElement;\n    const BtnSetpruebas = document.querySelector('#BtnSetpruebas') as HTMLButtonElement;\n    const btnDocumentos = document.querySelector('#btnDocumentos') as HTMLButtonElement;\n    const formCrearUpdateCompañia = document.querySelector('#formCrearUpdateCompañia') as HTMLFormElement;\n    const miDialogoAdquirirCompañia = POS.gestionAdquirirCompany.miDialogoAdquirirCompañia\r\n    const miDialogoCompañia = document.querySelector('#miDialogoCompañia') as any;\n    const miDialogoRecepcionDocumentos = document.querySelector('#miDialogoRecepcionDocumentos') as any;\n    const miDialogoGetResolucion = POS.gestionarGetResolutions.miDialogoGetResolucion\r\n    const miDialogosetpruebas = POS.gestionarSetPruebas.miDialogosetpruebas;\r\n    const selectResolucioncompañia = POS.gestionarGetResolutions.selectResolucioncompañia;\r\n    const selectSetCompañia = POS.gestionarSetPruebas.selectSetCompañia;\r\n\r\n    interface configCompany {\r\n      success:boolean,\r\n      message:string,\r\n      password:string,\r\n      token:string,\r\n      company: {\r\n        address: string,\r\n        country_id: number,\r\n        created_at: string,\r\n        dv: string,\r\n        eqdocs_type_environment_id: number,\r\n        id: number,\r\n        identification_number: string,\r\n        language_id: number,\r\n        merchant_registration: string,\r\n        municipality_id: number,\r\n        payroll_type_environment_id: 2,\r\n        phone: string,\r\n        state: number,\r\n        tax_id: number,\r\n        type_currency_id: number,\r\n        type_document_identification_id: number,\r\n        type_environment_id: number,\r\n        type_liability_id: number,\r\n        type_operation_id: number,\r\n        type_organization_id: number,\r\n        type_regime_id: number,\r\n        updated_at: string,\r\n        user: {\r\n          email: string,\r\n          name: string,\r\n          updated_at: string,\r\n          created_at: string\r\n        }\r\n      }\r\n    }\r\n\r\n\r\n    //Resolucion a almacenar en API\r\n    interface resolconfig {\r\n      idcompany?:string,\r\n      type_document_id:string, \r\n      prefix:string, \r\n      resolution?:string, \r\n      resolution_date?:string, \r\n      technical_key?:string,   //para la nota credito invoice se usa como identification_number de la compañia\r\n      from:string,\r\n      to:string, \r\n      generated_to_date?:string, \r\n      date_from?:string, \r\n      date_to?:string\r\n    }\r\n\r\n\r\n    //  Obtener compañias\r\n    async function getCompañiasLocal<T>():Promise<T[]> {\r\n      try {\r\n          const url = \"/admin/api/getCompaniesAll\"; //llamado a la API REST y se trae las cities segun cliente elegido\r\n          const respuesta = await fetch(url); \r\n          const resultado:T[]= await respuesta.json(); \r\n          return resultado;\r\n        } catch (error) {\r\n            console.log(error);\r\n            return [];\r\n        }\r\n    }\r\n    \r\n    let companiesAll:companiesDian[];\n\n    function escapeHtmlDian(valor:unknown):string{\n      return String(valor ?? '').replace(/[&<>\"']/g, caracter => ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#039;'\n      }[caracter] as string));\n    }\n\n    function filaCompañiaDian(id:string, businessName:unknown, identificationNumber:unknown, idsoftware:unknown):string{\n      const idSeguro = escapeHtmlDian(id);\n      const nombreSeguro = escapeHtmlDian(businessName);\n      const documentoSeguro = escapeHtmlDian(identificationNumber);\n      const softwareSeguro = escapeHtmlDian(idsoftware);\n\n      return `\n        <tr id=\"company${documentoSeguro}\">\n          <td>${idSeguro}</td>\n          <td>\n            <span class=\"config-dian-company-name\">\n              <span class=\"config-dian-company-name__icon\"><i class=\"fa-solid fa-building-user\"></i></span>\n              <span>${nombreSeguro}</span>\n            </span>\n          </td>\n          <td><span class=\"config-table-pill config-table-pill--document\">${documentoSeguro}</span></td>\n          <td><span class=\"config-table-pill config-table-pill--software\">${softwareSeguro}</span></td>\n          <td class=\"accionestd\">\n            <div class=\"acciones-btns\">\n              <button id=\"${idSeguro}\" class=\"config-dian-delete\" type=\"button\" title=\"Eliminar compañia\">\n                <span class=\"material-symbols-outlined eliminarcompañia\">delete</span>\n              </button>\n            </div>\n          </td>\n        </tr>`;\n    }\n\n    (async()=>{\n      companiesAll = await getCompañiasLocal<{id:string, identification_number:string, business_name:string, idsoftware:string, token:string}>();\n      POS.companiesAll = companiesAll; //exponer globalmente\n    })();\r\n\r\n\r\n\r\n    ///////////////////-------    crear compañia     --------///////////////////\r\n    btnCrearCompañia.addEventListener('click', ()=>{\r\n        limpiarformdialog();\r\n        document.querySelector('#modalCompañia')!.textContent = \"Crear compañia\";\r\n        (document.querySelector('#btnEditarCrearCompañia') as HTMLInputElement).value = \"Crear\";\r\n        miDialogoCompañia.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    btnObtenerresolucion.addEventListener('click', ()=>{\r\n        limpiarformdialog();\r\n        miDialogoGetResolucion.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    BtnSetpruebas.addEventListener('click', async ()=>{\n        limpiarformdialog();\n        //const r = await getCompañiasLocal();\n\n        miDialogosetpruebas.showModal();\n        document.addEventListener(\"click\", cerrarDialogoExterno);\n    });\n\n    btnDocumentos?.addEventListener('click', ()=>{\n        (document.querySelector('#formRecepcionDocumentos') as HTMLFormElement)?.reset();\n        miDialogoRecepcionDocumentos?.showModal();\n        document.addEventListener(\"click\", cerrarDialogoExterno);\n    });\n\n    document.querySelector('#formRecepcionDocumentos')?.addEventListener('submit', (e:Event)=>{\n      e.preventDefault();\n      msjalertToast('info', 'Formulario preparado', 'El cargue de documentos queda listo para conectar al guardado.');\n    });\n\r\n\r\n    formCrearUpdateCompañia.addEventListener('submit', async(e:Event)=>{\r\n      e.preventDefault();\r\n      const datos = new FormData(formCrearUpdateCompañia);\r\n      const archivoP12 = datos.get('certificate') as File;\r\n      const datoscompañia = Object.fromEntries(datos.entries());\r\n      datoscompañia.merchant_registration = \"0000000-00\";\r\n\r\n      const nit = datoscompañia.identification_number as string;\r\n      if(!/^\\d+$/.test(nit)){\r\n        alert('Numero del Nit no es valido');\r\n        return;\r\n      }\r\n      \r\n      if(archivoP12 && archivoP12.size>0){\r\n        if(!archivoP12.name.toLocaleLowerCase().endsWith('.p12')){\r\n          alert('Por favor seleccione un archivo formato .p12 valido');\r\n          return;\r\n        }\r\n        try {\r\n          const base64String = await base64(archivoP12);\r\n          datoscompañia.certificadop12base64 = base64String;\r\n          crearCompanyAPI(datoscompañia);\r\n        } catch (error) {\r\n          alert('Error durante el procesamiento del certificado .p12');\r\n          return;\r\n        }\r\n      }\r\n    });\r\n\r\n\r\n    async function crearCompanyAPI(datoscompañia: Record<string, FormDataEntryValue>){\r\n      const { identification_number, certificadop12base64, password, idsoftware, pinsoftware } = datoscompañia;\r\n        const dv = getDgv(Number(identification_number));\r\n        try{\r\n            const url = `https://apidianj2.com/api/ubl2.1/config/${identification_number}/${dv}`; //llamado a la API REST Dianlaravel\r\n            const respuesta = await fetch(url,  {\r\n                                                  method: 'POST',\r\n                                                  headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                                  body: JSON.stringify(datoscompañia)\r\n                                                });\r\n            const resultado = await respuesta.json();\r\n            if(resultado.success){\r\n              miDialogoCompañia.close();\r\n              document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n              \r\n              const cert = await configCertificado(resultado.token, certificadop12base64+'', password+'');\r\n              if(cert == undefined){\r\n                //eliminar usuario de la api\r\n                sendDeleteCompany('', identification_number+'', resultado.token);\r\n                msjalertToast('error', '¡Error!', 'Error en la obtencion del certificado digital.');\r\n                return;\r\n              }\r\n              const soft = await configSoftware(resultado.token, idsoftware+'', pinsoftware+'');\r\n              if(soft == undefined){\r\n                //eliminar usuario de la api\r\n                sendDeleteCompany('', identification_number+'', resultado.token);\r\n                msjalertToast('error', '¡Error!', 'Error en la configuracion del software.');\r\n                return;\r\n              }\r\n              const resolprueba:resolconfig = {\r\n                type_document_id:'1', \r\n                prefix:'SETP', \r\n                resolution:'18760000001', \r\n                resolution_date:'2019-01-19', \r\n                technical_key: 'fc8eac422eba16e22ffd8c6f94b3f40a6e38162c', \r\n                from: '990000000', \r\n                to: '995000000', \r\n                generated_to_date:'0', \r\n                date_from:'2019-01-19', \r\n                date_to: '2030-01-19'\r\n              };\r\n              const resol = await crearResolucion(resolprueba, resultado.token);\r\n              if(resol == undefined){\r\n                //eliminar usuario de la api\r\n                sendDeleteCompany('', identification_number+'', resultado.token);\r\n                msjalertToast('error', '¡Error!', 'Error en la configuracion de la resolucion.');\r\n                return;\r\n              }\r\n              /////    crear resolucion para NC    ///////\r\n              const extprefix = (datoscompañia.business_name as string).match(/[a-zA-Z]/g)!;\r\n              const a:string = extprefix[0];\r\n              const b:string = extprefix[extprefix.length-1];\r\n              const resolNC:resolconfig = {\r\n                type_document_id:'4', \r\n                prefix:'NC'+a+b, \r\n                from: '1', \r\n                to: '99999999', \r\n              };\r\n              \r\n              const resResolNC = await crearResolucion(resolNC, resultado.token); //crear resolucion nota credito invoice en la api\r\n              if(resResolNC == undefined){\r\n                //eliminar usuario de la api\r\n                sendDeleteCompany('', identification_number+'', resultado.token);\r\n                msjalertToast('error', '¡Error!', 'Error en la configuracion de la resolucion de NC.');\r\n                return;\r\n              }\r\n\r\n              const idcompany = await crearCompanyJ2(datoscompañia, resultado.token);\r\n              //crear resolucion nota credito invoice de forma local\r\n              if(idcompany!=undefined){\r\n                const resResolNCJ2 = crearResolucionNCJ2(resolNC, datoscompañia.identification_number+'', idcompany);\r\n              }\r\n      \r\n            }else{\r\n              msjalertToast('error', '¡Error!', 'No se pudo crear la compañia de facturacion.');\r\n            }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n    }\r\n\r\n\r\n    ///////    CREAR CERTIFICADO EN LA API DIAN    ///////\r\n    async function configCertificado(token:string, certificado:string, password:string):Promise<boolean|undefined> {\r\n      try{\r\n          const url = \"https://apidianj2.com/api/ubl2.1/config/certificate\"; //llamado a la API REST Dianlaravel\r\n          const respuesta = await fetch(url, {\r\n                                                method: 'PUT',\r\n                                                headers: {\r\n                                                  \"Accept\": \"application/json\",\r\n                                                  \"Content-Type\": \"application/json\",\r\n                                                  \"Authorization\": \"Bearer \"+token\r\n                                                },\r\n                                                body: JSON.stringify({\"certificate\": certificado, \"password\":password})\r\n                                              });\r\n          const resultado = await respuesta.json();\r\n          return resultado.success;\r\n        } catch (error) {\r\n            console.log(error);\r\n            return false;\r\n        }\r\n    }\r\n\r\n    \r\n    ///////    CREAR SOFTWARE EN LA API DIAN    ////////\r\n    async function configSoftware(token:string, idsoftware:string, pinsoftware:string):Promise<boolean|undefined>\r\n    {\r\n      try {\r\n        const url = \"https://apidianj2.com/api/ubl2.1/config/software\"; //llamado a la API REST Dianlaravel\r\n        const respuesta = await fetch(url, {\r\n                                              method: 'PUT',\r\n                                              headers: {\r\n                                                \"Accept\": \"application/json\",\r\n                                                \"Content-Type\": \"application/json\",\r\n                                                \"Authorization\": \"Bearer \"+token\r\n                                              },\r\n                                              body: JSON.stringify({\"id\": idsoftware, \"pin\":pinsoftware})\r\n                                            });\r\n        const resultado = await respuesta.json();\r\n        return resultado.success;\r\n      } catch (error) {\r\n        console.log(error);\r\n        return false;\r\n      }\r\n    }\r\n\r\n\r\n    ///////    CREAR RESOLUCIONES EN LA API    ////////\r\n    async function crearResolucion(resolition:resolconfig, token:string)\r\n    {\r\n      try {\r\n        const url = \"https://apidianj2.com/api/ubl2.1/config/resolution\"; //llamado a la API REST Dian-laravel\r\n        const respuesta = await fetch(url, {\r\n                                              method: 'PUT',\r\n                                              headers: {\r\n                                                \"Accept\": \"application/json\",\r\n                                                \"Content-Type\": \"application/json\",\r\n                                                \"Authorization\": \"Bearer \"+token\r\n                                              },\r\n                                              body: JSON.stringify(resolition)\r\n                                            });\r\n        const resultado = await respuesta.json();\r\n        return resultado.success;\r\n      } catch (error) {\r\n        console.log(error);\r\n        return false;\r\n      }\r\n      \r\n    }\r\n\r\n\r\n    //////// CREAR RESOLUCION NC PARA INVOICE EN J2 LOCALMENTE ////////////\r\n    async function crearResolucionNCJ2(resolNC:resolconfig, identification_number:string, idcompany:string){\r\n      resolNC.technical_key = identification_number;\r\n      resolNC.idcompany = idcompany;\r\n      try {\r\n          const url = `/admin/api/guardarNCInvoiceJ2`; //llamado a la API para guardar la resolucion NC DIAN de forma local\r\n          const respuesta = await fetch(url,  { method: 'POST',\r\n                                                headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                                body: JSON.stringify(resolNC)\r\n                                              });\r\n          const resultado = await respuesta.json();\r\n          return resultado;\r\n      } catch (error) {\r\n        console.log(error);\r\n      }\r\n    }\r\n\r\n\r\n    ///////    CREAR COMPAÑIA EN J2    ////////\r\n    async function crearCompanyJ2(datoscompañia: Record<string, FormDataEntryValue>, token:string):Promise<string|undefined>{\r\n      datoscompañia.token = token;\r\n      try {\r\n            const url = `/admin/api/crearCompanyJ2`; //llamado a la API para crear la compañia en j2\r\n            const respuesta = await fetch(url,  { method: 'POST',\r\n                                                  headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                                  body: JSON.stringify(datoscompañia)\r\n                                                });\r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\r\n              const tablaCompañias = document.querySelector('#tablaCompañias tbody');\r\n\r\n              const tr = tablaCompañias?.querySelector('tr[id=\"company'+datoscompañia.identification_number+'\"]');\r\n              if(tr){\r\n                tr.remove();\r\n              }\r\n\r\n              tablaCompañias?.insertAdjacentHTML('beforeend', filaCompañiaDian(resultado.id, datoscompañia.business_name, datoscompañia.identification_number, datoscompañia.idsoftware));\n\r\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n              // añadir a los selects de obtener compañia para resoluciones y de set pruebas\r\n              SetCompañiaToSelect(resultado.id, token, datoscompañia.business_name+'');\r\n              companiesAll.push({id:resultado.id, identification_number:datoscompañia.identification_number+'', business_name:datoscompañia.business_name+'', idsoftware:datoscompañia.idsoftware+'', token});\r\n              return resultado.id;\r\n            }else{\r\n              msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n    }\r\n    \r\n    //Tabla lista de compañias\r\n    document.querySelector('#tablaCompañias tbody')?.addEventListener('click', (e:Event)=>{\r\n      const target = e.target as HTMLElement;\r\n      if(target?.classList.contains(\"eliminarcompañia\")){\r\n        const id = target.parentElement?.id;\r\n        const oneC = companiesAll.find(x=>x.id == id)!;\r\n        eliminarCompañia(id!, oneC?.identification_number, oneC.token);\r\n      }\r\n    });\r\n\r\n    ///////    ELIMINAR COMPAÑIA    ///////\n    function eliminarCompañia(id:string, identification_number:string, token:string){\n      Swal.fire({\n          customClass: {\n            popup: 'j2-confirm j2-confirm--danger',\n            icon: 'j2-confirm__icon',\n            title: 'j2-confirm__title',\n            htmlContainer: 'j2-confirm__text',\n            actions: 'j2-confirm__actions',\n            confirmButton: 'j2-confirm__button j2-confirm__button--danger',\n            cancelButton: 'j2-confirm__button j2-confirm__button--cancel'\n          },\n          icon: 'question',\n          title: 'Desea eliminar la compañia?',\n          html: \"La compañia sera eliminada definitivamente de la configuracion DIAN.\",\n          showCancelButton: true,\n          confirmButtonText: 'Si',\n          cancelButtonText: 'No',\n          buttonsStyling: false,\n      }).then((result:any) => {\n          if (result.isConfirmed) {\n            sendDeleteCompany(id, identification_number, token)\n          }\n      });\r\n    }\r\n\r\n\r\n    function sendDeleteCompany(id:string, identification_number:string, token:string){\r\n      (async ()=>{ \r\n        try {\r\n          const url = \"https://apidianj2.com/api/ubl2.1/config/deleteCompany\"; //llamado a la API REST Dianlaravel\r\n          const respuesta = await fetch(url, {\r\n                                                method: 'DELETE',\r\n                                                headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\", \"Authorization\": \"Bearer \"+token },\r\n                                                body: JSON.stringify({\"identification_number\": identification_number})\r\n                                              });\r\n          const resultado = await respuesta.json();\r\n          if(resultado.message){\r\n            const urlX = \"/admin/api/eliminarCompanyLocal?id=\"+identification_number; // para eliminar compañia localmente\r\n            const respuestaLocal = await fetch(urlX); \r\n            const resultadoLocal = await respuestaLocal.json(); \n            if(!isNaN(Number(id)) && resultadoLocal.exito !== undefined){\n              document.querySelector('#company'+identification_number)?.remove();\n              deleteFromCompany(id);\n              Swal.fire({\n                customClass: {\n                  popup: 'j2-confirm j2-confirm--success',\n                  icon: 'j2-confirm__icon',\n                  title: 'j2-confirm__title',\n                  htmlContainer: 'j2-confirm__text',\n                  actions: 'j2-confirm__actions j2-confirm__actions--single',\n                  confirmButton: 'j2-confirm__button j2-confirm__button--confirm'\n                },\n                icon: 'success',\n                title: 'Compañia eliminada',\n                html: resultado.message || 'La compañia fue eliminada correctamente.',\n                confirmButtonText: 'OK',\n                buttonsStyling: false,\n              });\n            }\n          }else{\r\n            msjalertToast('error', '¡Error!', 'Error intentalo nuevamente');\r\n          }\r\n        } catch (error) {\r\n          console.log(error);\r\n          return false;\r\n        }\r\n      })();\r\n    }\r\n\r\n\r\n    ///////  eliminar de los select de obtener resolucion y enviar set de pruebas  ///////\r\n    function deleteFromCompany(id:string){\r\n      selectResolucioncompañia.querySelector(`option[value=${id}]`)?.remove();\r\n      selectSetCompañia.querySelector(`option[value=${id}]`)?.remove();\r\n    }\r\n\r\n\r\n    ///////    Set compañia en los select    ///////\r\n    function SetCompañiaToSelect(id:string, token:string, business_name:string){\r\n      selectResolucioncompañia.insertAdjacentHTML('afterbegin', `<option data-token=\"\" value=\"${id}\" >${business_name}</option>`);\r\n      selectSetCompañia.insertAdjacentHTML('afterbegin', `<option data-token=\"${token}\" value=\"${id}\" >${business_name}</option>`);\r\n    }\r\n    \r\n\r\n    function base64(archivo: File):Promise<string>{\r\n      return new Promise((resolve, reject) => {\r\n        const reader = new FileReader();\r\n        reader.onload = () => {\r\n            const base64Completo = reader.result as string;\r\n            const base64Puro = base64Completo.split(',')[1];\r\n            resolve(base64Puro);\r\n        };\r\n        reader.onerror = () => reject(new Error('Error al leer el archivo'));\r\n        reader.readAsDataURL(archivo);\r\n      });\r\n    }\r\n\r\n    /*function getDgv(nit: number): number {\r\n        const multiplicadores = [3, 7, 13, 17, 19, 23, 29, 37, 41, 43, 47, 53, 59, 67, 71];\r\n        const digitos = nit.toString().trim().split('').map(Number);\r\n        let suma = 0;\r\n        digitos.forEach((digito, indice) => {\r\n            const posicionMultiplicador = digitos.length - indice;\r\n            suma += digito * multiplicadores[posicionMultiplicador - 1];\r\n        }); \r\n        const modulo = suma%11;\r\n        return modulo > 1 ?(11 - modulo):modulo;\r\n    }*/\r\n\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      if(event.target === miDialogoAdquirirCompañia || event.target === miDialogoCompañia || event.target === miDialogosetpruebas || event.target === miDialogoGetResolucion || event.target === miDialogoRecepcionDocumentos || (event.target as HTMLInputElement).value === 'Salir' || (event.target as HTMLInputElement).value === 'Cancelar') {\n        miDialogoAdquirirCompañia.close();  \n        miDialogoCompañia.close();\n        miDialogoGetResolucion.close();\n        miDialogosetpruebas.close();\n        miDialogoRecepcionDocumentos?.close();\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\n      }\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateCompañia') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n\r\n    POS.cerrarDialogoExterno = cerrarDialogoExterno;\r\n    POS.crearResolucion = crearResolucion;\r\n    POS.crearCompanyJ2 = crearCompanyJ2;\r\n    POS.crearResolucionNCJ2 = crearResolucionNCJ2;\r\n  }\r\n\r\n})();\n","(()=>{\r\n    if(document.querySelector('.creditosAnulados')){\r\n        let tablaCreditosAnulados:HTMLElement;\r\n        tablaCreditosAnulados = ($('#tablaCreditosAnulados') as any).DataTable(configdatatablesgenerico);\r\n    }\r\n    if(document.querySelector('.creditosFinalizados')){\r\n        let tablaCreditosFinalizados:HTMLElement;\r\n        tablaCreditosFinalizados = ($('#tablaCreditosFinalizados') as any).DataTable(configdatatablesgenerico);\r\n    }\r\n\r\n})();","(()=>{\n    if(!document.querySelector('.cuotasCreditos'))return;\n\n    const POS = (window as any).POS;\n    const tablaCuotasCreditos = ($('#tablaCuotasCreditos') as any);\n    const spinner = document.querySelector('.content-spinner1') as HTMLElement;\n    const totalRegistros = document.querySelector('#cuotasCreditosTotalRegistros') as HTMLElement;\n    const totalValor = document.querySelector('#cuotasCreditosTotalValor') as HTMLElement;\n    const periodoReporte = document.querySelector('#cuotasCreditosPeriodo') as HTMLElement;\n\n    interface i_cuotasCreditos {\n        fechapagado:string,\n        idtipofinanciacion:string,\n        cliente:string,\n        credito:string,\n        numerocuota:string,\n        valorpormedio:string,\n        mediopago:string,\n        idestadocreditos:string,\n    } \n\n    let cuotasCreditos:i_cuotasCreditos[] = [];\n\n    async function callApiReporte(dateinicio:string, datefin:string){\n        spinner.style.display = \"grid\";\n        const datos = new FormData();\n        const fechainicioConsulta = normalizarFechaConsulta(dateinicio, 'inicio');\n        const fechafinConsulta = normalizarFechaConsulta(datefin, 'fin');\n        datos.append('fechainicio', fechainicioConsulta);\n        datos.append('fechafin', fechafinConsulta);\n\n        try {\n            const url = \"/admin/api/reportes/creditos/cuotasCreditos\";\n            const respuesta = await fetch(url, {method: 'POST', body: datos});\n            const resultado = await respuesta.json();\n            cuotasCreditos = Array.isArray(resultado) ? resultado : [];\n            actualizarResumen(fechainicioConsulta, fechafinConsulta);\n            printCuotasCreditos();\n            spinner.style.display = \"none\";\n        } catch (error) {\n            console.log(error);\n            spinner.style.display = \"none\";\n        }\n    }\n\n    function monedaCOP(valor:number|string){\n        return '$'+Number(valor || 0).toLocaleString('es-CO');\n    }\n\n    function normalizarFechaConsulta(fecha:string, tipo:'inicio'|'fin'){\n        const fechaLimpia = (fecha || '').trim();\n        if(!fechaLimpia)return '';\n\n        if(fechaLimpia.includes(':'))return fechaLimpia;\n\n        return tipo === 'inicio' ? `${fechaLimpia} 00:00:00` : `${fechaLimpia} 23:59:59`;\n    }\n\n    function formatearPeriodo(fecha:string){\n        return fecha.replace(' ', ' - ');\n    }\n\n    function actualizarResumen(dateinicio:string = '', datefin:string = ''){\n        const total = cuotasCreditos.reduce((acum, cuota)=>acum + Number(cuota.valorpormedio || 0), 0);\n        if(totalRegistros)totalRegistros.textContent = cuotasCreditos.length.toLocaleString('es-CO');\n        if(totalValor)totalValor.textContent = monedaCOP(total);\n        if(periodoReporte)periodoReporte.textContent = dateinicio && datefin ? `${formatearPeriodo(dateinicio)} - ${formatearPeriodo(datefin)}` : 'Sin periodo consultado';\n    }\n\n    printCuotasCreditos();\n    actualizarResumen();\n\n    function printCuotasCreditos(){\n        tablaCuotasCreditos.DataTable({\n            destroy: true,\n            data: cuotasCreditos,\n            pageLength: 25,\n            order: [[0, 'desc']],\n            columns: [\n                {title: 'Fecha', data: 'fechapagado', className: 'report-cuotas__date'},\n                {\n                    title: 'Tipo',\n                    data: 'idtipofinanciacion',\n                    render: (data:number) => `<span class=\"report-cuotas__pill ${data==1?'report-cuotas__pill--credit':'report-cuotas__pill--separado'}\">${data==1?'Credito':'Separado'}</span>`\n                },\n                {\n                    title: 'Cliente',\n                    data: 'cliente',\n                    render: (data:string) => `<span class=\"report-cuotas__client\"><i class=\"fa-solid fa-user\"></i>${data || 'Sin cliente'}</span>`\n                },\n                {title: 'Credito', data: 'credito', render: (data:string) => `<span class=\"report-cuotas__document\">${data || '-'}</span>`},\n                {title: 'No. cuota', data: 'numerocuota', render: (data:string) => `<strong>${data || '0'}</strong>`},\n                {title: 'Valor', data: 'valorpormedio', render: (data:number) => `<strong class=\"report-cuotas__money\">${monedaCOP(data)}</strong>`},\n                {title: 'Medio de pago', data: 'mediopago', render: (data:string) => `<span class=\"report-cuotas__method\">${data || 'No indicado'}</span>`},\n                {\n                    title: 'Estado',\n                    data: 'idestadocreditos',\n                    render: (data: any, type: any, row: any) => {\n                        const estado = row.idestadocreditos=='1'?'Finalizado':row.idestadocreditos=='2'?'Abierto':'Anulado';\n                        const clase = row.idestadocreditos=='1'?'report-cuotas__status--success':row.idestadocreditos=='2'?'report-cuotas__status--warning':'report-cuotas__status--danger';\n                        return `<span class=\"report-cuotas__status ${clase}\">${estado}</span>`;\n                    }\n                }\n            ],\n            language: {\n                search: 'Busqueda',\n                emptyTable: 'No hay datos disponibles',\n                zeroRecords: \"No se encontraron registros coincidentes\",\n                lengthMenu: '_MENU_ Entradas por pagina',\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\n                infoEmpty: 'No hay entradas a mostrar',\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\n            },\n            layout: {\n                topStart: {\n                    buttons: [\n                        {extend: 'excelHtml5', title: 'cuotas creditos'},\n                        {extend: 'pdfHtml5', title: 'cuotas creditos'},\n                        {extend: 'print', title: 'cuotas creditos', text: 'Imprimir'},\n                        'colvis'\n                    ],\n                    pageLength: 'pageLength'\n                }\n            },\n        });\n    }\n\n    POS.callApiReporte = callApiReporte;\n})();\n","(():void=>{\r\n\r\n  if(document.querySelector('.detalleinvoice')){\r\n    const POS = (window as any).POS;\r\n    const btnEnvarDian = document.querySelector('#btnEnvarDian') as HTMLButtonElement;\r\n    const btnModalNotaCredito = document.querySelector('#btnModalNotaCredito') as HTMLButtonElement;\r\n    const btnNuevaFactura = document.querySelector('#btnNuevaFactura') as HTMLButtonElement;\r\n    const tipoConsecutivo = document.querySelectorAll<HTMLButtonElement>('input[name=\"tipoConsecutivo\"]');\r\n    const selectSetConsecutivo = document.querySelector('#selectSetConsecutivo') as HTMLSelectElement;\r\n    const miDialogoNC = document.querySelector('#miDialogoNC') as any;\r\n\r\n    const facturarA = document.querySelector('#facturarA') as HTMLButtonElement;  //btn para asignar adquiriente\r\n    const miDialogoFacturarA = document.querySelector('#miDialogoFacturarA') as any;\r\n    const modalNuevaFactura = document.querySelector('#modalNuevaFactura') as HTMLDialogElement;\r\n    const modalEditarResolution = document.querySelector('#modalEditarResolution') as HTMLDialogElement;\r\n    const formFacturarA = document.querySelector('#formFacturarA') as HTMLFormElement;\r\n    const documentinput = document.querySelector('#identification_number') as HTMLInputElement;\r\n    const selectDepartments = document.querySelector('#department_id') as HTMLSelectElement;\r\n    const selectdCities = document.querySelector('#municipality_id') as HTMLSelectElement;\r\n    let isElectronica = false, idfeEditarResolution:string;\r\n    let customers:adquirientes[] = [];\r\n    let customersfiltrados:adquirientes[] = [];\r\n\r\n\r\n    interface document {\r\n      id:string,\r\n      id_estadoelectronica:string,\r\n      consecutivo_id:string,\r\n      id_facturaid:string,\r\n      id_adquiriente:string,\r\n      id_estadonota:string,\r\n      numero:string,\r\n      num_factura:string,\r\n      prefijo:string\r\n      filename:string,\r\n      identificacion:string\r\n      nombre?:string,\r\n      email?:string,\r\n      link:string,\r\n      nota_credito:string,\r\n      prefixnc:string,\r\n      num_nota:string,\r\n      linknc:string,\r\n      filenamenc:string,\r\n      fecha_factura:string,\r\n      fecha_nota:string\r\n    }\r\n\r\n    interface adquirientes {\r\n      id?:string,\r\n      type_document_identification_id:string,\r\n      identification_number:string,\r\n      business_name:string,\r\n      email:string,\r\n      address:string,\r\n      municipality_id?:string,\r\n      department_id?:string,\r\n      ciudad_nombre:string\r\n      type_organization_id:string,\r\n      type_regime_id:string,\r\n      phone:string\r\n    }\r\n\r\n    type municipalities = { id:string, department_id:string, name:string, code:string };\r\n    let cities:municipalities[]=[];\r\n\r\n\r\n    (async ()=>{\r\n      const url = `/admin/api/filterAdquirientes`; \r\n      const respuesta = await fetch(url);\r\n      const resultado = await respuesta.json();\r\n      customers = resultado;\r\n    })();\r\n\r\n\r\n    //buscar adquiriente con el numero de indentificacion que esta en el modal de adquiriente\r\n    documentinput.addEventListener('input', buscarAquiriente);\r\n\r\n    function buscarAquiriente(e:Event){\r\n        const busqueda:string = (e.target as HTMLInputElement).value;\r\n        if(busqueda.length > 3 && /^\\d+$/.test(busqueda)){\r\n            //const expresionregular = new RegExp(busqueda, \"i\");\r\n            customersfiltrados = customers.filter(document => { \r\n                if(document.identification_number.trim() === busqueda.trim()){\r\n                    return document;\r\n                }\r\n            });   \r\n        }else{\r\n            customersfiltrados = [];\r\n        }\r\n        mostrarAdquiriente();\r\n    }\r\n\r\n    function mostrarAdquiriente(){\r\n      if(customersfiltrados.length>0){\r\n        $('#type_document_identification_id').val(customersfiltrados[0].type_document_identification_id);\r\n        (document.querySelector('#identification_number') as HTMLInputElement).value = customersfiltrados[0].identification_number;\r\n        (document.querySelector('#business_name') as HTMLInputElement).value = customersfiltrados[0].business_name;\r\n        (document.querySelector('#email') as HTMLInputElement).value = customersfiltrados[0].email;\r\n        (document.querySelector('#address') as HTMLInputElement).value = customersfiltrados[0].address;\r\n        if(customersfiltrados[0].department_id){\r\n          $('#department_id').val(customersfiltrados[0].department_id);\r\n          imprimirCiudades(customersfiltrados[0].department_id);\r\n        }\r\n        //$('#municipality_id').val(customersfiltrados[0].municipality_id);\r\n        $('#type_organization_id').val(customersfiltrados[0].type_organization_id);\r\n        $('#type_regime_id').val(customersfiltrados[0].type_regime_id);\r\n        (document.querySelector('#phone') as HTMLInputElement).value = customersfiltrados[0].phone;\r\n      }else{\r\n        $('#type_document_identification_id').val(\"\");\r\n        (document.querySelector('#business_name') as HTMLInputElement).value = '';\r\n        (document.querySelector('#email') as HTMLInputElement).value = '';\r\n        (document.querySelector('#address') as HTMLInputElement).value = '';\r\n        $('#department_id').val(\"\");\r\n        $('#municipality_id').val(\"\");\r\n        $('#type_organization_id').val(\"\");\r\n        $('#type_regime_id').val(\"\");\r\n        (document.querySelector('#phone') as HTMLInputElement).value = \"\";\r\n      }\r\n    }\r\n\r\n\r\n\r\n    /////       Obtener municipio segun departamento        ///////\r\n    selectDepartments?.addEventListener('change', (e:Event)=>{\r\n      const x:HTMLOptionElement = (e.target as HTMLOptionElement);\r\n      imprimirCiudades(x.value);\r\n    });\r\n\r\n    function imprimirCiudades(x:string){\r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/citiesXdepartments?id=\"+x; //llamado a la API REST y se trae las cities segun cliente elegido\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json(); \r\n          if(resultado.error){\r\n            Swal.fire(resultado.error[0], '', 'error')\r\n          }else{\r\n            cities = resultado;\r\n            addCitiesToSelect(cities);\r\n          }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n    }\r\n    \r\n    function addCitiesToSelect<T extends {id:string, department_id:string, name:string, code:string}>(addrs: T[]):void{\r\n      while(selectdCities?.firstChild)selectdCities.removeChild(selectdCities?.firstChild);\r\n      addrs.forEach(x =>{\r\n        const option = document.createElement('option');\r\n        option.textContent = x.name;\r\n        option.value = x.id;\r\n        option.dataset.code = x.code;\r\n        option.dataset.department_id = x.department_id;\r\n        selectdCities.appendChild(option);\r\n      });\r\n      if(customersfiltrados.length>0&&customersfiltrados[0].municipality_id)$('#municipality_id').val(customersfiltrados[0].municipality_id);\r\n    }\r\n\r\n    ///////////////////// Enviar a DIAN //////////////////////\r\n    btnEnvarDian.addEventListener('click', async ()=>{\r\n      const idfactura:string = (document.querySelector('#idfactura') as HTMLInputElement).value;\r\n      const idfe:string = (document.querySelector('#idfe') as HTMLInputElement).value;\r\n      const idfeState:string = (document.querySelector('#idfeState') as HTMLInputElement).value;\r\n      (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n      if(idfeState != '2'){\r\n        const resDian = await POS.sendInvoiceAPI.sendInvoice(idfactura);\r\n        const filaDoc = document.querySelector(`#detalleDocumentos tr[data-idfe=\"${idfe}\"]`);\r\n        if(resDian.exito !== undefined){\r\n          document.querySelector('#estadoFactura')!.textContent = 'Aceptada DIAN';\r\n          document.querySelector('#estadoFactura')?.classList.remove('bg-slate-100', 'text-gray-700', 'bg-yellow-100', 'text-yellow-700');\r\n          document.querySelector('#estadoFactura')?.classList.add('bg-green-500', 'text-white');\r\n          msjalertToast('success', '¡Éxito!', resDian.exito[0]);\r\n          if(filaDoc)filaDoc.children[3].children[1].innerHTML = `<a class=\"btn-xs btn-lima\" href=\"${resDian.link}\" target=\"_blank\"> Aceptada </a>`;\r\n        }else{\r\n          document.querySelector('#estadoFactura')!.textContent = 'Error';\r\n          document.querySelector('#estadoFactura')?.classList.remove('bg-slate-100', 'g-green-500', 'text-gray-700', 'bg-yellow-100', 'text-yellow-700');\r\n          document.querySelector('#estadoFactura')?.classList.add('bg-red-500', 'text-white');\r\n          msjalertToast('error', '¡Error!', resDian.error[0]);\r\n          if(filaDoc)filaDoc.children[3].children[1].innerHTML = `<a class=\"btn-xs btn-red\" href=\"/\" target=\"_blank\"> Error </a>`;\r\n        }\r\n      }else{\r\n        msjalertToast('error', '¡Error!', 'Factura electronica aceptada por la Dian, no se puede volver a enviar');\r\n      }\r\n      (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n    });\r\n\r\n\r\n    ///////////////////// btn nueva factura //////////////////////\r\n    btnNuevaFactura.addEventListener('click', ()=>{\r\n      modalNuevaFactura.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    ///////////////////// evento al btn facturar A - adquiriente /////////////////////\r\n    facturarA.addEventListener('click', (e:Event)=>{\r\n      miDialogoFacturarA.showModal();\r\n      document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    //tipoConsecutivo es para generar nueva factura electronica\r\n    tipoConsecutivo.forEach(radio=>{\r\n      radio.addEventListener('change', (e:Event)=>{\r\n        const targetDom = e.target as HTMLInputElement;\r\n        if(targetDom.value == 'manual'){\r\n          document.querySelector('#consecutivoManual')?.classList.remove('hidden');\r\n          document.querySelector('#consecutivoManual')?.setAttribute(\"required\", \"\");\r\n        }else{\r\n          document.querySelector('#consecutivoManual')?.classList.add('hidden');\r\n          document.querySelector('#consecutivoManual')?.removeAttribute(\"required\");\r\n          (document.querySelector('#consecutivoManual') as HTMLInputElement).value = '';\r\n        }\r\n      })\r\n    });\r\n\r\n    /////////// Generar nueva facutura /////////\r\n    document.querySelector('#formNuevaFactura')?.addEventListener('submit', async e=>{\r\n      e.preventDefault();\r\n      const idResolution = (document.querySelector('#selectResolucion') as HTMLInputElement).value;\r\n      const datos = new FormData();\r\n      datos.append('idfactura', (document.querySelector('#idfactura') as HTMLInputElement).value);\r\n      datos.append('idResolution', idResolution);\r\n      datos.append('numConsecutivoManual', (document.querySelector('#consecutivoManual') as HTMLButtonElement)?.value || '');\r\n      modalNuevaFactura.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      (async ()=>{\r\n        try {\r\n            const url = \"/admin/api/crearFacturaPOSaElectronica\";  //api llamada en parametroscontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\r\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n              (document.querySelector('#idfe') as HTMLInputElement).value = resultado.facturaelectronica.id;\r\n              (document.querySelector('#idfeState') as HTMLInputElement).value = resultado.facturaelectronica.id_estadoelectronica;\r\n              document.querySelector('#prefixNumber')!.textContent = `Factura #${resultado.facturaelectronica.num_factura}`;\r\n              document.querySelector('#estadoFactura')!.textContent = 'Pendiente DIAN';\r\n              document.querySelector('#estadoFactura')?.classList.remove('bg-slate-100', 'text-gray-700', 'bg-green-500', 'text-white');\r\n              document.querySelector('#estadoFactura')?.classList.add('bg-yellow-100', 'text-yellow-700');\r\n              isElectronica = true;  //condicion para que el adquiriente se aguarde y se asocie al documento\r\n              printDocumentInTable(resultado.facturaelectronica);\r\n              insertInModalNC(resultado.facturaelectronica);\r\n              customersfiltrados = customers.filter(x=>x.id == resultado.facturaelectronica.id_adquiriente);\r\n              mostrarAdquiriente();\r\n              document.querySelector('#nombreAdquiriente')!.textContent = customersfiltrados[0].business_name;\r\n              document.querySelector('#identificacionAdquiriente')!.textContent = customersfiltrados[0].identification_number;\r\n              document.querySelector('#emailAdquiriente')!.textContent = customersfiltrados[0].email;\r\n            }else{\r\n              msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n    });\r\n\r\n    function printDocumentInTable(facturaelectronica:document){\r\n      document.querySelector('#detalleDocumentos')?.insertAdjacentHTML('beforeend', `\r\n        <tr data-idfe=\"${facturaelectronica.id}\">\r\n          <td class=\"py-3 px-4\">${facturaelectronica.id}</td>\r\n          <td class=\"text-center\">N° ${facturaelectronica.id_facturaid}</td> \r\n          <td class=\"text-center\">${facturaelectronica.num_factura}${facturaelectronica.id_estadonota == '2' ? ` / ${facturaelectronica.prefixnc} - ${facturaelectronica.num_nota}` : ''}</td>\r\n          <td class=\"text-center\">\r\n            <div class=\"btn-xs ${facturaelectronica.id_estadoelectronica == '2' ?'btn-lima':(facturaelectronica.id_estadoelectronica == '1'?'btn-blue':'btn-red')}\"> ${facturaelectronica.id_estadoelectronica == '2'?'Aceptada':(facturaelectronica.id_estadoelectronica == '1'?'Pendiente':'Error')} </div>\r\n            <div class=\"btn-xs ${facturaelectronica.id_estadonota == '2' ?'btn-orange':(facturaelectronica.id_estadonota == '1'?'btn-blue':'btn-red')}\"> ${facturaelectronica.id_estadonota == '2' && facturaelectronica.nota_credito == '1' ?'Aceptada NC':(facturaelectronica.id_estadonota == '1' && facturaelectronica.nota_credito == '1'?'Pendiente NC':facturaelectronica.id_estadonota == '3' && facturaelectronica.nota_credito == '1'?'Error NC':'')} </div>\r\n          </td>\r\n          <td class=\"text-center\">${facturaelectronica.id_estadoelectronica != '2' ?'<span class=\"cursor-pointer material-symbols-outlined eliminarFactura\">delete</span>':''}</td>\r\n        </tr>`\r\n      );\r\n    }\r\n\r\n    function insertInModalNC(facturaelectronica:document){\r\n      const selectInvoice = document.querySelector('#selectInvoice') as HTMLSelectElement;\r\n      const option = document.createElement('option');\r\n      option.value = facturaelectronica.id;\r\n      option.textContent = facturaelectronica.num_factura;\r\n      selectInvoice.appendChild(option);\r\n    }\r\n    \r\n    /////////// Guardar adquiriente /////////\r\n    formFacturarA.addEventListener('submit', (e:Event)=>{\r\n      e.preventDefault();\r\n      const data = new FormData(formFacturarA);\r\n      const datosAdquiriente: Record<string, FormDataEntryValue> = Object.fromEntries(data.entries());\r\n      \r\n      miDialogoFacturarA.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      \r\n      const identification = datosAdquiriente.identification_number as string;\r\n      const requiereEmail = identification && identification!='222222222222';\r\n      // Validar email solo si identification_number es distinto de 222222222222 y no vacío\r\n      if (requiereEmail && !validarEmail(datosAdquiriente.email as string)) {\r\n          Swal.fire(\"Correo incorrecto\", \"Debe ingresar un email válido o enviar a consumidor final o generico: 222222222222\", \"error\");\r\n          return; // detiene el proceso\r\n      }\r\n      if(isElectronica){\r\n        document.querySelector('#nombreAdquiriente')!.textContent = datosAdquiriente.business_name as string;\r\n        document.querySelector('#identificacionAdquiriente')!.textContent = datosAdquiriente.identification_number as string;\r\n        document.querySelector('#emailAdquiriente')!.textContent = datosAdquiriente.email as string;\r\n        //guarda y asigna adquiriente en DB.\r\n        asignarAdquirienteAFactura(datosAdquiriente);\r\n      }else{\r\n        msjalertToast('error', '¡Error!', 'Se debe generar nueva factura electronica para asignarle un adquiriente.');\r\n      }\r\n    });\r\n\r\n    function validarEmail(correo: string): boolean {\r\n        const regex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\r\n        return regex.test(correo);\r\n    }\r\n\r\n\r\n    //asigna adquiriente a la ultima factura electronica.\r\n    async function asignarAdquirienteAFactura(datosAdquiriente: Record<string, FormDataEntryValue>){\r\n      datosAdquiriente.idfactura = (document.querySelector('#idfactura') as HTMLInputElement).value;  ////id de la factura general\r\n      datosAdquiriente.idfe = (document.querySelector('#idfe') as HTMLInputElement).value;\r\n      try {\r\n            const url = \"/admin/api/asignarAdquirienteAFactura\";\r\n            const respuesta = await fetch(url, {\r\n                                      method: 'POST',\r\n                                      headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                                      body: JSON.stringify(datosAdquiriente)\r\n                                    }); \r\n            const resultado = await respuesta.json();\r\n            if(resultado.exito !== undefined){\r\n              msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n              document.querySelector('#nombreAdquiriente')!.textContent = datosAdquiriente.business_name as string;\r\n              document.querySelector('#identificacionAdquiriente')!.textContent = datosAdquiriente.identification_number as string;\r\n              document.querySelector('#emailAdquiriente')!.textContent = datosAdquiriente.email as string;\r\n              if(resultado.tipo == \"crear\"){\r\n                customers = [...customers, resultado.obj];\r\n              }else{\r\n                /// actualizar el arregle del adquiriente o customers ///\r\n                customers.forEach(a=>{if(a.identification_number == resultado.obj.identification_number)a = Object.assign(a, resultado.obj);});\r\n              }\r\n            }else{\r\n              msjalertToast('error', '¡Error!', resultado.error[0]);\r\n            }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    }\r\n\r\n\r\n    ///////////////////-------    Btn NC     --------///////////////////\r\n    btnModalNotaCredito.addEventListener('click', ()=>{\r\n        limpiarformdialog();\r\n        miDialogoNC.showModal();\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    ///////// Habilita el campo de consecutivo personalizado\r\n    selectSetConsecutivo?.addEventListener('change', (e:Event)=>{\r\n      const targetDom = e.target as HTMLSelectElement;\r\n      const habilitaconsecutivo = document.querySelector('.habilitaconsecutivo') as HTMLElement;\r\n      if(targetDom.value == '0'){  //  Siguiente consecutivo automatico\r\n        habilitaconsecutivo.style.display = \"none\";\r\n        document.querySelector('#consecutivoPersonalizado')?.removeAttribute(\"required\");\r\n        (document.querySelector('#consecutivoPersonalizado') as HTMLInputElement).value = '';\r\n      }\r\n      else{  //consecutivo personalizado\r\n        habilitaconsecutivo.style.display = \"flex\";\r\n        document.querySelector('#consecutivoPersonalizado')?.setAttribute(\"required\", \"\");\r\n      }\r\n    });\r\n\r\n    document.querySelector('#formNC')?.addEventListener('submit', async e=>{\r\n        e.preventDefault();\r\n        const idfactura:string = (document.querySelector('#idfactura') as HTMLInputElement).value;  //id de la factura general\r\n        const idInvoice:string = (document.querySelector('#selectInvoice') as HTMLSelectElement).value;\r\n        const idfeState:string = (document.querySelector('#idfeState') as HTMLInputElement).value;\r\n        const consecutivo = (document.querySelector('#consecutivoPersonalizado') as HTMLInputElement).value;\r\n        miDialogoNC.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n        if(idfeState == '2'){\r\n          try {\r\n              const url = \"/admin/api/sendNc\"; //llamado a la API REST apidiancontrolador.php\r\n              const respuesta = await fetch(url, {\r\n                  method: 'POST', \r\n                  headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n                  body: JSON.stringify({id: idInvoice, idfactura, consecutivo})  //si consecutivo es vacio '', es siguiente consecutivo\r\n              });\r\n              const responseDian = await respuesta.json(); \r\n              console.log(responseDian);\r\n              const filaDoc = document.querySelector(`#detalleDocumentos tr[data-idfe=\"${idInvoice}\"]`);\r\n              if(filaDoc)filaDoc.children[2].textContent = filaDoc.children[2].textContent+' / '+responseDian.notacredito.prefixnc+' - '+responseDian.notacredito.num_nota;\r\n              if(responseDian.exito !== undefined){\r\n                msjalertToast('success', '¡Éxito!', responseDian.exito[0]);\r\n                //actualizar tabla de detalle de documentos electronicos\r\n                if(filaDoc){\r\n                  const enlace = filaDoc.children[3].children[1] as HTMLAnchorElement;\r\n                  enlace.innerHTML = `Aceptada NC`;\r\n                  enlace.classList.remove('btn-blue', 'btn-red');\r\n                  enlace.classList.add('btn-orange');\r\n                  enlace.href = responseDian.notacredito.linknc;\r\n                }\r\n                //quitar el documento del select de la modal NC\r\n                eliminarOptionSelectNC(idInvoice);\r\n              }else{\r\n                msjalertToast('error', '¡Error!', responseDian.error[0]);\r\n                //actualizar tabla de detalle de documentos electronicos\r\n                if(filaDoc){\r\n                  const enlace = filaDoc.children[3].children[1] as HTMLAnchorElement;\r\n                  enlace.innerHTML = `Error NC`;\r\n                  enlace.classList.remove('btn-blue', 'btn-orange');\r\n                  enlace.classList.add('btn-red');\r\n                  enlace.href = responseDian.notacredito.linknc;\r\n                }\r\n              }\r\n          } catch (error) {\r\n              console.log(error);\r\n          }\r\n        }else{\r\n          msjalertToast('error', '¡Error!', 'Error, la factura electronica no esta aceptada por la Dian o ya se genero nota credito.');\r\n        }\r\n    });\r\n\r\n    //eliminar option 'documento electronico' del select de la modal NC\r\n    function eliminarOptionSelectNC(idInvoice:string){\r\n      const selectInvoice = document.querySelector('#selectInvoice') as HTMLSelectElement;\r\n      const optionsToRemove = selectInvoice.querySelector(`option[value=\"${idInvoice}\"]`);\r\n      if(optionsToRemove)optionsToRemove.remove();\r\n    }\r\n\r\n\r\n    /////////  ENVENTO A LA TABLA DE DETALLE DE DOCUMENTOS  ///////////\r\n    document.querySelector('#detalleDocumentos')?.addEventListener('click', e=>{\r\n      const evento = e.target;\r\n      const tr:string|undefined = (evento as HTMLSpanElement).closest('tr')?.dataset.idfe;\r\n      if((evento as HTMLSpanElement).classList.contains('eliminarFactura'))\r\n        if(tr != undefined)eliminarFacturaElectronica(tr);\r\n      if((evento as HTMLSpanElement).classList.contains('editarResolution'))\r\n        if(tr != undefined){\r\n          idfeEditarResolution = tr;\r\n          modalEditarResolution.showModal();\r\n          document.addEventListener(\"click\", cerrarDialogoExterno);\r\n        }\r\n    });\r\n\r\n    document.querySelector('#formEditarResolution')?.addEventListener('submit', async e=>{\r\n        e.preventDefault();\r\n        try {\r\n        const url = \"/admin/api/editarResolutionFE\"; //llamado a la API REST apidiancontrolador.php\r\n        const respuesta = await fetch(url, {\r\n            method: 'POST', \r\n            headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n            body: JSON.stringify({\r\n                                    idfe: idfeEditarResolution,\r\n                                    idresolution: (document.querySelector('#selectEditarResolucion') as HTMLInputElement).value,\r\n                                    consecutivo: (document.querySelector('#consecutivoEditarResolution') as HTMLInputElement).value\r\n                                  })\r\n        });\r\n        const resultado = await respuesta.json();\r\n        if(resultado.exito !== undefined){\r\n            msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            const filaDoc = document.querySelector(`#detalleDocumentos tr[data-idfe=\"${idfeEditarResolution}\"]`) as HTMLTableRowElement;\r\n            filaDoc.children[2].textContent = resultado.prefijoNum;\r\n             document.querySelector('#prefixNumber')!.textContent = `Factura #${resultado.prefijoNum}`;\r\n          }else{\r\n            msjalertToast('error', '¡Error!', resultado.error[0]);\r\n          }\r\n      } catch (error) {\r\n        console.log(error);\r\n      }\r\n    });\r\n\r\n    async function eliminarFacturaElectronica(idfe:string){\r\n      try {\r\n          const url = \"/admin/api/eliminarFacturaElectronica\"; //llamado a la API REST apidiancontrolador.php\r\n          const respuesta = await fetch(url, {\r\n              method: 'POST', \r\n              headers: { \"Accept\": \"application/json\", \"Content-Type\": \"application/json\" },\r\n              body: JSON.stringify({id: idfe})\r\n          });\r\n          const resultado = await respuesta.json(); \r\n          console.log(resultado);\r\n          const filaDoc = document.querySelector(`#detalleDocumentos tr[data-idfe=\"${idfe}\"]`);\r\n          if(resultado.exito !== undefined){\r\n            msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n            if(filaDoc)filaDoc.remove();\r\n            eliminarOptionSelectNC(idfe);\r\n          }else{\r\n            msjalertToast('error', '¡Error!', resultado.error[0]);\r\n          }\r\n      } catch (error) {\r\n          console.log(error);\r\n      }\r\n    }\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      const f = event.target;\r\n      if( f === miDialogoNC || f === modalNuevaFactura || f === miDialogoFacturarA || f === modalEditarResolution || (f as HTMLInputElement).value === 'Salir' || (f as HTMLInputElement).value === 'Cancelar') {\r\n        miDialogoNC.close();\r\n        modalNuevaFactura.close();\r\n        miDialogoFacturarA.close();\r\n        modalEditarResolution.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n\r\n    function limpiarformdialog(){\r\n      (document.querySelector('#formCrearUpdateCompañia') as HTMLFormElement)?.reset();\r\n    }\r\n\r\n  }\r\n\r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.facturaselectronicas')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaFacturasElectronicas:HTMLElement;\r\n\r\n    interface invoice {\r\n        id:string,     //id de la factura_electronica\r\n        orden:string,  //id de la factura\r\n        prefijo:string,\r\n        numero:string, //numero del consecutivo de la factura electronica\r\n        resolucion:string,\r\n        cufe:string,\r\n        identificacion:string,\r\n        nombre:string,\r\n        tipoventa:string,\r\n        base:string,\r\n        valorimpuestototal:string,\r\n        total:string,\r\n        created_at: string\r\n    }\r\n\r\n    let facturaselectronicas:invoice[] = [];\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiInvoice(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiInvoice(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/facturaselectronicas\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            facturaselectronicas = resultado;\r\n            printTableFacturasPagas();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableFacturasPagas();\r\n    function printTableFacturasPagas(){\r\n        tablaFacturasElectronicas = ($('#tablaFacturasElectronicas') as any).DataTable({\r\n            \"responsive\": true,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: facturaselectronicas,\r\n            columns: [\r\n                        {title: 'Orden', data: 'orden'}, \r\n                        {title: 'Prefijo', data: 'prefijo'}, \r\n                        {title: 'Num', data: 'numero'},\r\n                        { \r\n                            title: 'Abrir', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<a class=\"btn-ver btn-xs btn-light\" target=\"_blank\" href=\"/admin/reportes/detalleInvoice?id=${row.orden}\" data-id=\"${row.orden}\">Abrir</a>`}\r\n                        },\r\n                        {\r\n                            title: 'Abrir Dian', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<a class=\"btn-ver btn-xs btn-lima\" data-id=\"${row.id}\" target=\"_blank\" href=\"${row.link}\">Abrir Dian</a>`}\r\n                        }, \r\n                        {title: 'Identificacion', data: 'identificacion'}, \r\n                        {title: 'Nombre', data: 'nombre'}, \r\n                        {title: 'Tipo venta', data: 'tipoventa'},\r\n                        {title: 'Prefijo NC', data: 'prefixnc'},\r\n                        {title: 'Nun NC', data: 'num_nota'},\r\n                        {title: 'Abrir NC',\r\n                                data: null, \r\n                                orderable: false, \r\n                                searchable: false, \r\n                                render: (data: any, type: any, row: any) => {return row.id_estadonota==2&&row.nota_credito == 1?`<a class=\"btn-ver btn-xs btn-orange\" target=\"_blank\" href=\"${row.linknc}\">Abrir NC</a>`:row.id_estadonota==1&&row.nota_credito == 1?'<button class=\"btn-xs btn-blue\">pendiente NC</button>':row.id_estadonota==3&&row.nota_credito == 1?'<button class=\"btn-xs btn-red\">Error NC</button>':''}\r\n                        },\r\n                        {title: 'Base', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Valor imp', data: 'valorimpuestototal', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Total', data: 'total', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Fecha', data: 'created_at'},\r\n                        {\r\n                            title: 'Archivos', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `\r\n                                                                                <a class=\"mr-4 text-3xl\" target=\"_blank\" href=\"https://apidianj2.com/j2softwarepos/download/${row.filename}\"><i class=\"fa-solid fa-file-pdf text-red-600\"></i></a>` \r\n                                                                                +(row.nota_credito == 1?` <a class=\" text-3xl\" target=\"_blank\" href=\"https://apidianj2.com/j2softwarepos/download/${row.filenamenc}\"><i class=\"fa-solid fa-file-pdf text-blue-400\"></i></a>`:'')\r\n                                                                        }\r\n                        }, \r\n                    ],\r\n            pageLength: 25,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                        {extend: 'excelHtml5', title: 'facturas procesadas'},  \r\n                        {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                        {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n  }\r\n\r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.electronicaspendientes')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaelectronicasPendientes:HTMLElement;\r\n\r\n    interface invoice {\r\n        id:string,     //id de la factura_electronica\r\n        orden:string,  //id de la factura\r\n        prefijo:string,\r\n        numero:string, //numero del consecutivo de la factura electronica\r\n        resolucion:string,\r\n        cufe:string,\r\n        identificacion:string,\r\n        nombre:string,\r\n        tipoventa:string,\r\n        base:string,\r\n        valorimpuestototal:string,\r\n        total:string,\r\n        created_at: string\r\n    }\r\n\r\n    let facturaselectronicaspendientes:invoice[] = [];\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiInvoice(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiInvoice(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin);\r\n        try {\r\n            const url = \"/admin/api/electronicaspendientes\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            facturaselectronicaspendientes = resultado;\r\n            printTableFacturasPagas();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableFacturasPagas();\r\n    function printTableFacturasPagas(){\r\n        tablaelectronicasPendientes = ($('#tablaelectronicasPendientes') as any).DataTable({\r\n            \"responsive\": true,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: facturaselectronicaspendientes,\r\n            columns: [\r\n                        {title: 'Orden', data: 'orden'}, \r\n                        {title: 'Prefijo', data: 'prefijo'}, \r\n                        {title: 'Numero', data: 'numero'},\r\n                        { \r\n                            title: 'Abrir', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<a class=\"btn-ver btn-xs btn-light\" target=\"_blank\" href=\"/admin/reportes/detalleInvoice?id=${row.orden}\" data-id=\"${row.orden}\">Abrir</a>`}\r\n                        },\r\n                        {title: 'Identificacion', data: 'identificacion'}, \r\n                        {title: 'Nombre', data: 'nombre'}, \r\n                        {title: 'Tipo venta', data: 'tipoventa'}, \r\n                        {title: 'Base', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Valor imp', data: 'valorimpuestototal', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Total', data: 'total', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Fecha', data: 'created_at'}\r\n                    ],\r\n            pageLength: 25,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'copyHtml5', text: 'Copia'}, \r\n                    {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'csvHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n  }\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.estadosfinancierosCreditos'))return;\r\n        const POS = (window as any).POS;\r\n\r\n        let tablaEstdosFinancierosCreditos:HTMLElement;\r\n        let estadosFinancierosCreditos:[] = [];\r\n\r\n\r\n        async function callApiReporte(dateinicio:string, datefin:string){\r\n            document.querySelector('#fecha1')!.textContent = dateinicio;\r\n            document.querySelector('#fecha2')!.textContent = datefin;\r\n            (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n            const datos = new FormData();\r\n            datos.append('fechainicio', dateinicio);\r\n            datos.append('fechafin', datefin);\r\n            try {\r\n                const url = \"/admin/api/reportes/creditos/estadosFinancieros\"; //llama a la api que esta en reportescontrolador.php\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                estadosFinancierosCreditos = await respuesta.json();\r\n                printTableEstadosFinancierosCreditos();\r\n            (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        }\r\n\r\n\r\n        printTableEstadosFinancierosCreditos();\r\n        function printTableEstadosFinancierosCreditos(){\r\n            tablaEstdosFinancierosCreditos = ($('#tablaEstdosFinancierosCreditos') as any).DataTable({\r\n                \"responsive\": true,\r\n                pageLength: 25,\r\n                destroy: true, // importante si recargas la tabla\r\n                data: estadosFinancierosCreditos,\r\n                columns: [\r\n                    {title: 'N°', data: 'num_orden'},\r\n                    {title: 'Emisor', data: 'nombreEmisor', render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data??'Negocio'}</div>`},\r\n                    {title: 'Fecha', data: 'fechainicio'},\r\n                    {title: 'Credito', data: 'capitalTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Costo', data: 'costo_total', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Utl. Comercial', data: 'utilidad_comercial', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Utl. Proyectada', data: 'utilidad_proyectada', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Pagado', data: 'valor_pagado', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Utl Realizada', data: 'utilidad_realizada', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {\r\n                        title: 'Estado',\r\n                        data: 'estado',\r\n                        render: (data: any, type: any, row: any) => {return `<a class=\"btn-xs ${row.estado=='2'?'btn-blue':row.estado=='1'?'btn-lima':'btn-light'}\" target=\"_blank\" href=\"/admin/creditos/detallecredito?id=${row.id}\">${row.estado=='1'?'Finalizado':'Abierto'}</a>`}\r\n                    },\r\n                ],\r\n                \r\n                \r\n                language: {\r\n                    search: 'Busqueda',\r\n                    emptyTable: 'No Hay datos disponibles',\r\n                    zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                    lengthMenu: '_MENU_ Entradas por pagina',\r\n                    info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                    infoEmpty: 'No hay entradas a mostrar',\r\n                    infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                    paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n                },\r\n                layout: {\r\n                    topStart: {\r\n                        buttons: [\r\n                        {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                        {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                        {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                        ],\r\n                        pageLength: 'pageLength'\r\n                    }\r\n                }\r\n            });\r\n        }\r\n\r\n        POS.callApiReporte = callApiReporte;\r\n    \r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.facturasprocesadas')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaFacturasProcesadas:HTMLElement;\r\n\r\n    interface facturaspagas {\r\n        id:string,\r\n        idvendedir:string,\r\n        idcaja:string,\r\n        idconsecutivo:string,\r\n        num_orden:string,\r\n        num_consecutivo:string,\r\n        vendedor:string,\r\n        valorgananciauser:string,\r\n        caja:string,\r\n        tipofacturador:string,\r\n        totalunidades:string,\r\n        recibido:string,\r\n        cambio:string,\r\n        tipoventa:string,\r\n        estado:string,\r\n        cambioaventa:string,\r\n        subtotal:string,\r\n        base:string,\r\n        valorimpuesto:string,\r\n        descuento:string,\r\n        total:string,\r\n        fechapago:string\r\n    } \r\n\r\n    let datosFacturasPagas:facturaspagas[] = [];\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiFacturasPagas(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiFacturasPagas(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/facturaspagas\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosFacturasPagas = resultado;\r\n            printTableFacturasPagas();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableFacturasPagas();\r\n    function printTableFacturasPagas(){\r\n        tablaFacturasProcesadas = ($('#tablaFacturasProcesadas') as any).DataTable({\r\n            \"responsive\": true,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosFacturasPagas,\r\n            columns: [\r\n                {title: 'Orden', data: 'num_orden'},\r\n                {title: 'Fecha Pago', data: 'fechapago', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data}</div>`},\r\n                {\r\n                    title: 'N° Factura', \r\n                    data: null,\r\n                    orderable: false, \r\n                    searchable: false,\r\n                    render: (data: any, type: any, row: any) => {return `${row.prefijo}${row.num_consecutivo}`}\r\n                },\r\n                {title: 'Tipo', data: 'tipofacturador', render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\r\n                {title: 'Tipo Venta', data: 'tipoventa'},\r\n                {\r\n                    title: 'Abrir', \r\n                    data: null, \r\n                    orderable: false, \r\n                    searchable: false, \r\n                    render: (data: any, type: any, row: any) => {return `<a class=\"btn-ver btn-xs btn-light\" target=\"_blank\" href=\"/admin/caja/ordenresumen?id=${row.id}\" data-id=\"${row.id}\">Abrir</a>`}\r\n                },\r\n                {title: 'T. Unds', data: 'totalunidades'},\r\n                {title: 'B. gravable', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                {title: 'Imp', data: 'valorimpuestototal'}, \r\n                {title: 'Descuento', data: 'descuento'}, \r\n                {title: 'Total', data: 'total', render: (data: number, type: string) => {\r\n                                                                                            if (type === 'display') {\r\n                                                                                            return `$${Number(data).toLocaleString('es-CO')}`;\r\n                                                                                            }\r\n                                                                                            return data; // para export, sort, filter\r\n                                                                                        }}, \r\n                {title: 'Vendedor', data: 'vendedor'},\r\n                {title: 'Comision', data: 'valorgananciauser', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                {title: 'Caja', data: 'caja'}],\r\n            pageLength: 25,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'copyHtml5', text: 'Copia'}, \r\n                    {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'csvHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n  }\r\n\r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.facturasanuladas')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaFacturasAnuladas:HTMLElement;\r\n\r\n    interface factuarasanuladas {\r\n        id:string,\r\n        idvendedir:string,\r\n        idcaja:string,\r\n        idconsecutivo:string,\r\n        num_orden:string,\r\n        num_consecutivo:string,\r\n        vendedor:string,\r\n        caja:string,\r\n        tipofacturador:string,\r\n        totalunidades:string,\r\n        recibido:string,\r\n        cambio:string,\r\n        tipoventa:string,\r\n        estado:string,\r\n        cambioaventa:string,\r\n        subtotal:string,\r\n        base:string,\r\n        valorimpuesto:string,\r\n        descuento:string,\r\n        total:string,\r\n        fechapago:string\r\n    } \r\n\r\n    let datosFacturasAnuladas:factuarasanuladas[] = [];\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiFacturasPagas(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiFacturasPagas(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin);\r\n        try {\r\n            const url = \"/admin/api/facturasanuladas\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosFacturasAnuladas = resultado;\r\n            printTableFacturasPagas();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableFacturasPagas();\r\n    function printTableFacturasPagas(){\r\n        tablaFacturasAnuladas = ($('#tablaFacturasAnuladas') as any).DataTable({\r\n            \"responsive\": true,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosFacturasAnuladas,\r\n            columns: [{title: 'Orden', data: 'num_orden'}, {title: 'N° Factura', data: 'num_consecutivo'}, {title: 'Tipo', data: 'tipofacturador'}, {title: 'Cant vendida', data: 'totalunidades'}, {title: 'B. gravable', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`}, {title: 'Imp', data: 'valorimpuestototal'}, {title: 'Descuento', data: 'descuento'}, {title: 'Total', data: 'total', render: (data:number) => `$${Number(data).toLocaleString()}`}, {title: 'Vendedor', data: 'vendedor'}, {title: 'Caja', data: 'caja'}],\r\n            pageLength: 25,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'copyHtml5', text: 'Copia'}, \r\n                    {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'csvHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n  }\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.recibosCaja'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const tablaRecibosCaja = ($('#tablaRecibosCaja') as any);\r\n\r\n    interface i_ingresosEmisores {\r\n        id: string,\r\n        num_orden:string,\r\n        fecha:string,\r\n        concepto:string,\r\n        numero_documento:string,\r\n        tercero:string,\r\n        mediopago:string,\r\n        observacion:string,\r\n        cajero:string,\r\n        caja: string,\r\n        valor:string,\r\n        valormediopago:string,\r\n        emisor:string\r\n    }\r\n\r\n\r\n\r\n    let ingresosEmisores:i_ingresosEmisores[] = [];\r\n\r\n\r\n\r\n    async function callApiReporte(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/reportes/recibosCaja\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            ingresosEmisores = resultado;\r\n            console.log(ingresosEmisores);\r\n            reporteRecibosCaja();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n    \r\n    reporteRecibosCaja();\r\n    function reporteRecibosCaja(){\r\n        tablaRecibosCaja.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: ingresosEmisores,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Num', data: 'num_orden'},\r\n                        {title: 'Fecha', data: 'fecha', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Concepto', data: 'concepto', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Documento', data: 'documento'},\r\n                        {title: 'Tercero', data: 'tercero', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Medio Pago', data: 'mediopago'},\r\n                        {title: 'Cajero', data: 'cajero'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Valor pagado', data: 'valormediopago', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Emisor', data: 'emisor', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data==null?'Negocio':data}</div>`},\r\n                        {title: 'Observacion', data: 'observacion', render: (data:string) => `<div class=\"w-52 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Estado', data: 'estadoMov', render: (data:number) => `<div class=\"\">${data==1?'Registrado':'Anulado'}</div>`}\r\n            ],\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                        {extend: 'excelHtml5', title: 'emisores procesadas'},  \r\n                        {extend: 'pdfHtml5', title: 'emisores procesadas'}, \r\n                        {extend: 'print', title: 'emisores procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n    POS.callApiReporte = callApiReporte;\r\n\r\n})();","(()=>{\n    if(!document.querySelector('.remisiones'))return;\n\n    const POS = (window as any).POS;\n\n    const tablaRemisiones = ($('#tablaRemisiones') as any);\n\n    interface i_remisiones {\n        id:string,\n        fechacreacion:string,\n        fechaentrega?:string,\n        vendedor:string,\n        cliente:string,\n        num_orden:string,\n        entrega:string,\n        entregado:string,\n    }\n\n    let remisiones:i_remisiones[] = [];\n    const labelsRemisiones = ['Id', 'Fecha', 'Fecha entrega', 'Usuario', 'Cliente', 'Orden', 'Entrega', 'Estado', 'Acciones'];\n\n\n    async function callApiReporte(dateinicio:string, datefin:string){\n        document.querySelector('#fecha1')!.textContent = dateinicio;\n        document.querySelector('#fecha2')!.textContent = datefin;\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\n        const datos = new FormData();\n        datos.append('fechainicio', dateinicio);\n        datos.append('fechafin', datefin+' 23:59:59');\n        try {\n            const url = \"/admin/api/reportes/remisiones\"; //llama a la api que esta en reportescontrolador.php\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \n            const resultado = await respuesta.json();\n            remisiones = resultado;\n            printRemisiones();\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\n        } catch (error) {\n            console.log(error);\n        }\n    }\n\n    \n    printRemisiones();\n    function printRemisiones(){\n        const dataTableRemisiones = tablaRemisiones.DataTable({\n            destroy: true, // importante si recargas la tabla\n            data: remisiones,\n            pageLength: 25,\n            order: [[ 1, 'desc' ]],\n            responsive: {\n                details: false\n            },\n            columns: [\n                        {title: 'Id', data: 'id', className: 'all dtr-control', responsivePriority: 1},\n                        {title: 'Fecha', data: 'fechacreacion', className: 'all', responsivePriority: 2, render: (data:string) => `<div class=\"w-36 whitespace-normal\">${data}</div>`},\n                        {title: 'Fecha Entrega', data: 'fechaentrega', responsivePriority: 7, render: (data:string) => `<div class=\"text-center\">${data??'-'}</div>`},\n                        {title: 'Usuario', data: 'vendedor', responsivePriority: 8, render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\n                        {title: 'Cliente', data: 'cliente', responsivePriority: 4, render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\n                        {title: 'Orden', data: 'num_orden', responsivePriority: 3},\n                        {title: 'Entrega', data: 'entrega', responsivePriority: 5, render: (data:string) => `<span class=\"rm-delivery\">${data || '-'}</span>`},\n                        {title: 'Estado', data: 'entregado', responsivePriority: 6, render: (data:string) => {\n                            const entregado = data == '1';\n                            return `<span class=\"rm-status ${entregado ? 'rm-status--done' : 'rm-status--pending'}\">${entregado ? 'Despachado' : 'Pendiente'}</span>`;\n                        }},\n                        { \n                            title: 'Acciones', \n                            data: null, \n                            responsivePriority: 9,\n                            orderable: false, \n                            searchable: false, \n                            render: (data: any, type: any, row: any) => {return `<a class=\"rm-action-open\" target=\"_blank\" href=\"/admin/caja/ordenresumen?id=${row.id}\" data-id=\"${row.id}\">Abrir</a>`}\n                        },        \n            ],\n            createdRow: function(row: HTMLTableRowElement) {\n                labelsRemisiones.forEach((label, index) => {\n                    row.children[index]?.setAttribute('data-rm-label', label);\n                });\n            },\n            drawCallback: function() {\n                document.querySelector('.rm-table-card')?.classList.add('rm-remisiones-mobile');\n            },\n            language: {\n                search: 'Busqueda',\n                emptyTable: 'No Hay datos disponibles',\n                zeroRecords:    \"No se encontraron registros coincidentes\",\n                lengthMenu: '_MENU_ Entradas por pagina',\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\n                infoEmpty: 'No hay entradas a mostrar',\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\n            },\n            layout: {\n                topStart: {\n                    buttons: [\n                        {extend: 'excelHtml5', title: 'facturas procesadas'},  \n                        {extend: 'pdfHtml5', title: 'facturas procesadas'}, \n                        {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\n                        'colvis'\n                    ],\n                    pageLength: 'pageLength'\n                }\n            },\n        });\n\n        const tablaRemisionesEl = document.querySelector('#tablaRemisiones') as HTMLTableElement|null;\n        if(tablaRemisionesEl){\n            tablaRemisionesEl.onclick = (e:MouseEvent)=>{\n                const target = e.target as HTMLElement;\n                const expandCell = target.closest('td') as HTMLTableCellElement|null;\n                if(!expandCell || expandCell.cellIndex !== 0 || window.innerWidth > 768)return;\n\n                const row = expandCell.closest('tr');\n                if(!row)return;\n\n                const dataTableRow = dataTableRemisiones.row(row);\n                if(dataTableRow.child.isShown()){\n                    dataTableRow.child.hide();\n                    row.classList.remove('parent');\n                    return;\n                }\n\n                const cells = Array.from(row.querySelectorAll<HTMLTableCellElement>('td'));\n                const detailRows = cells.slice(2).map((cell, index) => {\n                    const title = labelsRemisiones[index + 2] || '';\n                    return `<li><span class=\"dtr-title\">${title}</span><span class=\"dtr-data\">${cell.innerHTML}</span></li>`;\n                }).join('');\n\n                dataTableRow.child(`<ul class=\"dtr-details\">${detailRows}</ul>`, 'child').show();\n                row.classList.add('parent');\n            };\n        }\n    }\n\n\n    POS.callApiReporte = callApiReporte;\n\n})();\n","(()=>{\r\n    if(!document.querySelector('.reporteEmisores'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const tablaReporteEmisores = ($('#tablaReporteEmisores') as any);\r\n    const tablaventasXemisor = ($('#tablaventasXemisor') as any);\r\n\r\n    interface i_ingresosEmisores {\r\n        emisor:string,\r\n        numventas:string,\r\n        subtotal:string,\r\n        base:string,\r\n        impuesto:string,\r\n        descuento:string,\r\n        totalventas:string,\r\n        ingresos:string\r\n    }\r\n\r\n    interface i_ventasXEmisor {\r\n        num_orden:string,\r\n        fechapago:string,\r\n        prefijo:string,\r\n        num_consecutivo:string,\r\n        tipofacturador:string,\r\n        tipoventa:string,\r\n        subtotal:string,\r\n        base:string,\r\n        valorimpuestototal:string,\r\n        descuento:string,\r\n        total:string,\r\n        vendedor:string,\r\n        caja:string\r\n    } \r\n\r\n\r\n    let f1:string = '', f2:string = '', idemisor:string = '', ingresosEmisores:i_ingresosEmisores[] = [], ventasXEmisor:i_ventasXEmisor[] = [];\r\n\r\n\r\n    ($('#selectEmisor') as any).select2({ \r\n        placeholder: \"Selecciona un item\",\r\n        maximumSelectionLength: 1,\r\n    });\r\n\r\n\r\n    $(\"#selectEmisor\").on('change', (e)=>{\r\n            idemisor = (e.target as HTMLInputElement).value;\r\n            if(f1!=''&&f2!='')callApiReporte(f1, f2);\r\n    });\r\n\r\n\r\n    async function callApiReporte(dateinicio:string, datefin:string){\r\n        f1 = dateinicio;\r\n        f2 = datefin;\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        datos.append('idemisor', idemisor);\r\n        try {\r\n            const url = \"/admin/api/reportes/reporteEmisores\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            ingresosEmisores = resultado.ingresos;\r\n            ventasXEmisor = resultado.ventasXEmisor;\r\n            reporteEmisores();\r\n            printVentasXEmisor();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n    \r\n    reporteEmisores();\r\n    function reporteEmisores(){\r\n        tablaReporteEmisores.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: ingresosEmisores,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Emisor', data: 'emisor', render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\r\n                        {title: 'N° ventas', data: 'numventas'},\r\n                        {title: 'Subtotal', data: 'subtotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Base gravable', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Impuesto', data: 'impuesto', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Descuento', data: 'descuento', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total', data: 'totalventas', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Ingresos', data: 'ingresos', render: (data:number) => `<p class=\"m-0 font-semibold\"> $${Number(data).toLocaleString()} </p>`}\r\n            ],\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                        {extend: 'excelHtml5', title: 'emisores procesadas'},  \r\n                        {extend: 'pdfHtml5', title: 'emisores procesadas'}, \r\n                        {extend: 'print', title: 'emisores procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n    printVentasXEmisor();\r\n    function printVentasXEmisor(){\r\n        tablaventasXemisor.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: ventasXEmisor,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Orden', data: 'num_orden'},\r\n                        {title: 'Fecha Pago', data: 'fechapago'},\r\n                        {\r\n                            title: 'N° Factura', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false,\r\n                            render: (data: any, type: any, row: any) => {return `${row.prefijo}${row.num_consecutivo}`}\r\n                        },\r\n                        {title: 'Tipo', data: 'tipofacturador', render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Tipo Venta', data: 'tipoventa'},\r\n                        { \r\n                            title: 'Abrir', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<a class=\"btn-ver btn-xs btn-light\" target=\"_blank\" href=\"/admin/caja/ordenresumen?id=${row.id}\" data-id=\"${row.id}\">Abrir</a>`}\r\n                        },\r\n                        {title: 'Subtotal', data: 'subtotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'B. Gravable', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Imp', data: 'valorimpuestototal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Descuento', data: 'descuento', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total', data: 'total', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Vendedor', data: 'vendedor'},\r\n                        {title: 'Caja', data: 'caja'}\r\n            ],\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                        {extend: 'excelHtml5', title: 'emisores procesadas'},  \r\n                        {extend: 'pdfHtml5', title: 'emisores procesadas'}, \r\n                        {extend: 'print', title: 'emisores procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n    POS.callApiReporte = callApiReporte;\r\n\r\n})();","\r\n(()=>{\r\n\r\n    if(!document.querySelector('.ventasgenerales'))return;\r\n\r\n    const POS = (window as any).POS;\n    const dataTablesLanguage = {\n        search: 'Busqueda',\n        emptyTable: 'No Hay datos disponibles',\n        zeroRecords: 'No se encontraron registros coincidentes',\n        lengthMenu: '_MENU_ Entradas por pagina',\n        info: 'Mostrando pagina _PAGE_ de _PAGES_',\n        infoEmpty: 'No hay entradas a mostrar',\n        infoFiltered: ' (filtrado desde _MAX_ registros)',\n        paginate: { first: '<<', last: '>>', next: '>', previous: '<' }\n    };\r\n\r\n    const tablaProductosVendidos = ($('#tablaProductosVendidos') as any);\r\n    const tablaMediosPagos = ($('#tablaMediosPagos') as any);\r\n    const tablacreditosSeparados = ($('#tablacreditosSeparados') as any);\r\n    const tablaGastos = ($('#tablaGastos') as any);\r\n    const tablaIngresoCanalventa = ($('#tablaIngresoCanalventa') as any);\r\n    const tablaVentasXUsuario = ($('#tablaVentasXUsuario') as any);\r\n    const tablaResumenVentas = ($('#tablaResumenVentas') as any);\r\n    const tablaResumenCreditos = document.querySelector('#tablaResumenCreditos tbody');\r\n    const printBalance = document.querySelector('#printBalance') as HTMLButtonElement;\r\n    \r\n    interface i_productosVendidos {\r\n        idproducto:string,\r\n        cantidadrefencia:string,\r\n        nombreproducto:string,\r\n        totalProductosVendidos:string,\r\n        valorunidad:string,\r\n        valorTotal:string\r\n    }\r\n\r\n    interface i_mediosPagos {\r\n        idmediopago:string,\r\n        cantidadMP:string,\r\n        mediopago:string,\r\n        valor:string\r\n    }\r\n\r\n    interface i_creditosSeparados {\r\n        idestadocreditos:string,\r\n        estado:string\r\n        carteraTotal:string,\r\n        carteraXCobrar:string,\r\n        totalAbonado:string,\r\n        total:string,\r\n    }\r\n\r\n    interface i_canaldeVenta {\r\n        canaldeventa:string,\r\n        transacciones:string,\r\n        valor:string,\r\n    }\r\n\r\n\r\n    interface i_ventasEmpleados {\r\n        empleado:string,\r\n        ventasRealizadas:string,\r\n        totalVentas:string,\r\n        porcentaje:string,\r\n        valorComision:string,\r\n    }\r\n\r\n    interface i_gastos {\r\n        descripcion:string,\r\n        tipogasto:string,\r\n        valor:string,\r\n    }\r\n    \r\n    interface i_resumenVentas {\r\n        ventas:string,\r\n        total_ventas:string,\r\n        total_costo:string,\r\n        ganancia:string,\r\n        margenutilidad:string,\r\n    }\r\n\r\n    interface i_resumenCreditos {\r\n        creditos:string,\r\n        capitalTotal:string,\r\n        costo_total:string,\r\n        utilidad_comercial:string,\r\n        utilidad_proyectada:string,\r\n        valor_pagado:string,\r\n        utilidad_realizada:string\r\n    }\r\n\r\n    let productosVendidos:i_productosVendidos[] = [], mediosPagos:i_mediosPagos[] = [], creditosSeparados:i_creditosSeparados[] = [], ventasEmpleados:i_ventasEmpleados[]=[], gastos:i_gastos[]=[], canalVenta:i_canaldeVenta[]=[], resumenVentas:i_resumenVentas[]=[], resumenCreditos:i_resumenCreditos[]=[];\r\n    let totalabonos:number = 0, dateStart = '', dateEnd = '';\r\n    //tablaProductosVendidos.DataTable(configdatatables25reg);\r\n\r\n\r\n    async function callApiReporte(dateinicio:string, datefin:string){\r\n        dateStart = dateinicio;\r\n        dateEnd = datefin;\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        \r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/reportes/reportesGenerales\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            productosVendidos = resultado.productosVendidos;\r\n            mediosPagos = resultado.mediosPagos;\r\n            creditosSeparados = resultado.separados;\r\n            ventasEmpleados = resultado.ventasXusuario;\r\n            gastos = resultado.gastos;\r\n            canalVenta = resultado.canalVenta;\r\n            resumenCreditos = resultado.resumenCreditos;\r\n            resumenVentas = resultado.resumenVentas;\r\n            printProductosVendidos();\r\n            printMediosPagos();\r\n            printCreditosSeparados();\r\n            printVentasUsuarios();\r\n            printGastos();\r\n            printCanalVenta();\r\n            totalabonos = Number(resultado.totalabonos);\r\n            printResumen(Number(resultado.totalDescuentos[0].total_descuentos));\r\n            document.querySelector('#totalDescto')!.textContent = '$'+Number(resultado.totalDescuentos[0].total_descuentos).toLocaleString();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printProductosVendidos();\r\n    function printProductosVendidos(){\r\n        tablaProductosVendidos.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: productosVendidos,\r\n            pageLength: 25,\r\n            language: dataTablesLanguage,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Producto', data: 'nombreproducto'},\r\n                        {title: 'Cantidad Vendida', data: 'totalProductosVendidos'},\r\n                        {title: 'V. Unidad', data: 'valorunidad', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total Ventas', data: 'valorTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Costo Total', data: 'costoTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Utilidad', data: 'utilidad', render: (data:number) => `$${Number(data).toLocaleString()}`}\r\n                    ],\r\n        });\r\n    }\r\n\r\n    printMediosPagos();\r\n    function printMediosPagos(){\r\n        tablaMediosPagos.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: mediosPagos,\r\n            pageLength: 25,\r\n            language: dataTablesLanguage,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Medio de Pago', data: 'mediopago'},\r\n                        {title: 'Transacciones', data: 'cantidadMP'},\r\n                        {title: 'Total Ventas', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });\r\n    }\r\n\r\n    printCreditosSeparados();\r\n    function printCreditosSeparados(){\r\n        tablacreditosSeparados.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: creditosSeparados,\r\n            pageLength: 25,\r\n            language: dataTablesLanguage,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {\r\n                            title: 'Estado', \r\n                            data: 'estado', \r\n                            render: (data: any, type: any, row: any) => {return `<button class=\"btn-xs ${row.estado=='Abierto'?'btn-blue':row.estado=='Finalizado'?'btn-lima':'btn-light'}\">${row.estado}</button>`}\r\n                        },\r\n                        {title: 'Cartera Total', data: 'carteraTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Cartera Por Cobrar', data: 'carteraXCobrar', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total Abonado', data: 'totalAbonado', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total', data: 'total'}\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printCanalVenta();\r\n    function printCanalVenta(){\r\n        tablaIngresoCanalventa.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: canalVenta,\r\n            pageLength: 25,\r\n            language: dataTablesLanguage,\r\n            order: [[ 1, 'asc' ]],\r\n            columns: [\r\n                        {title: 'Canal De Venta', data: 'canalVenta'},\r\n                        {title: 'Transacciones', data: 'transacciones'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printVentasUsuarios();\r\n    function printVentasUsuarios(){\r\n        tablaVentasXUsuario.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: ventasEmpleados,\r\n            pageLength: 25,\r\n            language: dataTablesLanguage,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Empleado', data: 'empleado'},\r\n                        {title: 'Ventas Realizadas', data: 'ventasRealizadas'},\r\n                        {title: 'Total Ventas', data: 'totalVentas', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Porcentaje', data: 'porcentaje'},\r\n                        {title: 'Valor comision', data: 'valorComision', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printGastos();\r\n    function printGastos(){\r\n        tablaGastos.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: gastos,\r\n            pageLength: 25,\r\n            language: dataTablesLanguage,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Descripcion', data: 'descripcion'},\r\n                        {title: 'Tipo Gasto', data: 'tipogasto'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printResumen(0);\r\n    function printResumen(dscto:number){\r\n\r\n        const contentUtilidadRF = document.querySelector('#contentUtilidadRF') as HTMLSpanElement;\r\n        const textUtilidadRF = document.querySelector('#textUtilidadRF') as HTMLSpanElement;\r\n        const utilidadRF = document.querySelector('#utilidadRF') as HTMLSpanElement;\r\n\r\n        const ventaBruta = Number(resumenVentas[0]?.total_ventas??0);\r\n        const ventaNeta = ventaBruta - dscto;\r\n        const totalIngreso = ventaNeta+totalabonos;\r\n        const totalEgreso = Number(gastos.at(-1)?.valor ?? 0);\r\n        const utilidadTotal = totalIngreso - totalEgreso;\r\n        const margenUtilidadTotal = totalIngreso > 0 ? (utilidadTotal / totalIngreso) * 100 : 0;\r\n        const rentabilidadTotal = totalEgreso > 0 ? (utilidadTotal / totalEgreso) * 100 : 0;\r\n\r\n        //cards\r\n        (document.querySelector('#IngresoTotalCard') as HTMLElement).textContent = '$'+totalIngreso.toLocaleString();\r\n        (document.querySelector('#utilidadCard') as HTMLElement).textContent = '$'+utilidadTotal.toLocaleString();\r\n        (document.querySelector('#totalAbonosCard') as HTMLElement).textContent = '$'+totalabonos.toLocaleString();\r\n        (document.querySelector('#carteraPendienteCard') as HTMLElement).textContent = '$'+Number(creditosSeparados[1]?.carteraXCobrar??0).toLocaleString();\r\n\r\n        //tabla de resumen financiero\r\n        (document.querySelector('#ventaBrutaRF') as HTMLSpanElement).textContent = '$'+ventaBruta.toLocaleString();\r\n        (document.querySelector('#descuentosRF') as HTMLSpanElement).textContent = '-$'+dscto.toLocaleString();\r\n        (document.querySelector('#ventaNetaRF') as HTMLSpanElement).textContent =  '$'+ventaNeta.toLocaleString();\r\n        (document.querySelector('#totalAbonosRF') as HTMLSpanElement).textContent = '$'+totalabonos.toLocaleString();\r\n        (document.querySelector('#ingresoTotalRF') as HTMLSpanElement).textContent = '$'+totalIngreso.toLocaleString();\r\n        (document.querySelector('#egresosRF') as HTMLSpanElement).textContent = '-$'+totalEgreso.toLocaleString();\r\n        (document.querySelector('#margenUtilidadRF') as HTMLSpanElement).textContent = margenUtilidadTotal.toLocaleString()+'%';\r\n        utilidadRF.textContent = '$'+utilidadTotal.toLocaleString();\r\n        if(utilidadTotal>=0){\r\n            contentUtilidadRF.classList.add('bg-emerald-500/10', 'border-emerald-500/20');\r\n            textUtilidadRF.classList.add('text-emerald-700');\r\n            utilidadRF.classList.add('text-emerald-600');\r\n            contentUtilidadRF.classList.remove('bg-red-500/10', 'border-red-500/20');\r\n            textUtilidadRF.classList.remove('text-red-700');\r\n            utilidadRF.classList.remove('text-red-600');\r\n        }else{\r\n            contentUtilidadRF.classList.remove('bg-emerald-500/10', 'border-emerald-500/20');\r\n            textUtilidadRF.classList.remove('text-emerald-700');\r\n            utilidadRF.classList.remove('text-emerald-600');\r\n            contentUtilidadRF.classList.add('bg-red-500/10', 'border-red-500/20');\r\n            textUtilidadRF.classList.add('text-red-700');\r\n            utilidadRF.classList.add('text-red-600');\r\n        }\r\n\r\n\r\n\r\n        //resumen financiero total de ventas\r\n        tablaResumenVentas.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: resumenVentas,\r\n            pageLength: 25,\r\n            language: dataTablesLanguage,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Ventas', data: 'ventas'},\r\n                        {title: 'Total Ventas Productos', data: 'total_ventas', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total Costo Productos', data: 'total_costo', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Ganancia', data: 'ganancia', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Margen Utilidad', data: 'margenutilidad', render: (data:number) => `${Number(data).toLocaleString()}%`},\r\n                    ],\r\n        });\r\n\r\n        //resumen financiero total creditos\r\n        /*tablaResumenCreditos.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: resumenCreditos,\r\n            pageLength: 25,\r\n            language: dataTablesLanguage,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Creditos', data: 'creditos'},\r\n                        {title: 'Credito Total', data: 'capitalTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Costo Total', data: 'costo_total', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Utilidad Comercial', data: 'utilidad_comercial', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Utilidad Proyectada', data: 'utilidad_proyectada', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Pago total', data: 'valor_pagado', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Utilidad Realizada', data: 'utilidad_realizada', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });*/\r\n\r\n\r\n        //tabla resumen financiero de creditos\r\n        const tr = document.createElement('tr') as HTMLTableRowElement;\r\n        while(tablaResumenCreditos?.firstChild)tablaResumenCreditos.removeChild(tablaResumenCreditos.firstChild);\r\n        tr.insertAdjacentHTML('afterbegin', `\r\n          <td class=\"\">${resumenCreditos[0]?.creditos??0}</td> \r\n          <td class=\"\">$${Number(resumenCreditos[0]?.capitalTotal??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.costo_total??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.utilidad_comercial??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.utilidad_proyectada??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.valor_pagado??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.utilidad_realizada??0).toLocaleString()}</td>`);\r\n        tablaResumenCreditos?.appendChild(tr);\r\n\r\n        //tabla rentabilidad\r\n        (document.querySelector('#ingresoTotal') as HTMLElement).textContent = '$'+totalIngreso.toLocaleString();\r\n        (document.querySelector('#egreso') as HTMLElement).textContent = '$'+totalEgreso.toLocaleString();\r\n        (document.querySelector('#utilidadTotal') as HTMLElement).textContent = '$'+utilidadTotal.toLocaleString();\r\n        (document.querySelector('#margenUtilidadTotal') as HTMLElement).textContent = margenUtilidadTotal.toFixed(2) + '%';\r\n        (document.querySelector('#rentabilidadTotal') as HTMLElement).textContent = rentabilidadTotal.toFixed(2) + '%';\r\n    }\r\n\r\n\r\n    printBalance.addEventListener('click', ()=>{\r\n      const contentBalanceGeneral = document.querySelector('#contentBalanceGeneral') as HTMLElement;\r\n\r\n      const ventana = window.open('', '_blank', 'width=900,height=700');\r\n      if(ventana){\r\n        ventana?.document.write(`\r\n            <html>\r\n                <head>\r\n                    <title>Balance</title>\r\n                    <link rel=\"stylesheet\" href=\"/build/css/tailwindapp.css\">\r\n                    <link rel=\"stylesheet\" href=\"/build/css/app.css\">\r\n                </head>\r\n                <body class=\"p-6\">\r\n                    <div class=\"my-8 p-6\">\r\n                        <h2 class=\"text-gray-600 text-3xl font-semibold my-12 pb-4 text-center\">ðŸ“Š Balance financiero General</h2>\r\n                        <p class=\"text-2xl text-gray-600 mb-0\">PERIODO, <span class=\"text-gray-900 font-semibold ml-8\">Inicio: ${dateStart} - Fin: ${dateEnd}</span></p>    \r\n                    </div>\r\n                    ${contentBalanceGeneral.innerHTML}\r\n                </body>\r\n            </html>\r\n        `);\r\n\r\n        ventana.document.close();\r\n        ventana.onload = ()=>{\r\n            ventana?.focus();\r\n            ventana?.print();\r\n            setTimeout(() => { ventana?.close(); }, 200); // Cerrar la ventana despuÃ©s de unos segundos\r\n        };\r\n      }\r\n    });\r\n\r\n\r\n    POS.callApiReporte = callApiReporte;\r\n\r\n})();\r\n","(()=>{\r\n  if(document.querySelector('.ventasxtransaccion')){\r\n\r\n    const btnmensual = document.querySelector('#btnmensual') as HTMLButtonElement;\r\n    const btndiario = document.querySelector('#btndiario') as HTMLButtonElement;\r\n    const miDialogoMes = document.querySelector('#miDialogoMes') as any;\r\n    const miDialogoDiario = document.querySelector('#miDialogoDiario') as any;\r\n    let tablaTransaccioneXVenta:HTMLTableElement;\r\n\r\n    interface transacciones {\r\n      fecha:string,\r\n      total_venta:string,\r\n      num_transacciones:string,\r\n      promedio_transaccion:string,\r\n      transaccion_mas_alta:string,\r\n      transaccion_mas_baja:string\r\n    }\r\n    let datatransacciones:transacciones[] = [];\r\n\r\n    btnmensual?.addEventListener('click', ()=>{\r\n        miDialogoMes.showModal(); //seleccionar año\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    btndiario?.addEventListener('click', ()=>{\r\n        miDialogoDiario.showModal();  //seleccionar mes\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    //seleccionar año, transacciones mes acumulado de un año\r\n    document.querySelector('#formMes')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      const inputselectaño = document.querySelector('#inputselectaño') as HTMLInputElement;\r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/ventasxtransaccionanual?x=\"+inputselectaño.value; //llamado a la API REST en reportescontrolador.php\r\n          const respuesta = await fetch(url);\r\n          const resultado = await respuesta.json();\r\n          datatransacciones = resultado;\r\n          console.log(resultado);\r\n          printTableTranscciones()\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n      miDialogoMes.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    //seleccionar mes, transacciones acumuladas por dia durante un mes y año elejido\r\n    document.querySelector('#formDiario')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      const inputselectmesyaño = document.querySelector('#inputselectmesyaño') as HTMLInputElement;\r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/ventasxtransaccionmes?x=\"+inputselectmesyaño.value; //llamado a la API REST en reportescontrolador.php\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json();\r\n          datatransacciones = resultado;\r\n          printTableTranscciones()\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n      miDialogoDiario.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    printTableTranscciones();\r\n    function printTableTranscciones(){\r\n\r\n        tablaTransaccioneXVenta = ($('#tablaTransaccioneXVenta') as any).DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datatransacciones,\r\n            columns: [{title: 'Fecha', data: 'fecha'}, {title: 'Toal venta', data: 'total_venta', render: (data: number) => `$${Number(data).toLocaleString()}`}, {title: 'Numero de transacciones', data: 'num_transacciones'}, {title: 'Promedio por transacción', data: 'promedio_transaccion'}, {title: 'Transacción mas alta', data: 'transaccion_mas_alta'}, {title: 'Transacción mas baja', data: 'transaccion_mas_baja'}],\r\n        });\r\n    }\r\n\r\n\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      const f = event.target;\r\n      if (f === miDialogoMes || f === miDialogoDiario || (f as HTMLInputElement).closest('.salir')) {\r\n        miDialogoMes.close();\r\n        miDialogoDiario.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n\r\n  }\r\n\r\n\r\n})();\r\n   ","(():void=>{\r\n\r\n  if(document.querySelector('.ventasxcliente')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaVentasXCliente:HTMLElement;\r\n\r\n    interface ventaxcliente {\r\n        id:string,\r\n        nombre:string,\r\n        cantidad_facturas:string,\r\n        total_ventas:string\r\n    } \r\n\r\n    let datosVentaXCliente:ventaxcliente[] = [];\r\n\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiVentasXCliente(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiVentasXCliente(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiVentasXCliente(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiVentasXCliente(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiVentasXCliente(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiVentasXCliente(dateinicio:string, datefin:string){\r\n        console.log(dateinicio, datefin);\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/ventasxcliente\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosVentaXCliente = resultado;\r\n            printTableVentasXCliente();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableVentasXCliente();\r\n    function printTableVentasXCliente(){\r\n        tablaVentasXCliente = ($('#tablaVentasXCliente') as any).DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosVentaXCliente,\r\n            columns: [{title: 'Nombre', data: 'nombre'}, {title: 'Cantidad_facturas', data: 'cantidad_facturas'}, {title: 'Total ventas', data: 'total_ventas', render: (data:number) => `$${Number(data).toLocaleString()}`}],\r\n        });\r\n    }\r\n\r\n  }\r\n\r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.detallecompra')){\r\n\r\n    const btnPrintCompra = document.querySelector('#btnPrintCompra') as HTMLButtonElement;\r\n\r\n    //capturar el id de la compra por la url\r\n    const parametrosURL = new URLSearchParams(window.location.search);\r\n    const id:string = parametrosURL.get('id')??'';\r\n    ///////// imprimir detalle de compra\r\n    btnPrintCompra.addEventListener('click', ()=>{\r\n      if(id!='' || !isNaN(Number(id))){\r\n        //const ventana = window.open('/printDetalleCompra?id='+id, '_blank');\r\n        const ventana = window.open('/admin/printComprobanteCompraPDF?id='+id, '_blank');\r\n        if(ventana){\r\n            ventana.onload = ()=>{\r\n                ventana?.focus();\r\n                ventana?.print();\r\n            };\r\n        }\r\n      }else{\r\n        msjalertToast('error', '¡Error!', 'Error al generar impresion.');\r\n      }\r\n    });\r\n\r\n  }\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.inventarioxproducto')){\r\n        let  tablaStockRapido:HTMLElement;\r\n        tablaStockRapido = ($('#tablaStockRapido') as any).DataTable(configdatatablesstockrapido);\r\n    }\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.movimientosinventarios'))return;\r\n\r\n        const POS = (window as any).POS;\r\n\r\n        let tablaMovimientosInventarios:HTMLElement;\r\n        let datosMovimientosInventarios:[] = [];\r\n        //const mesyaño:[string, number] = mesyañoactual();\r\n\r\n\r\n        ///////   productos y subproductos en el select\r\n        let filteredData: {id:string, text:string, tipo:string, sku:string, unidadmedida:string}[];   //tipo = 0 es producto simple,  1 = subproducto\r\n        (async ()=>{\r\n            try {\r\n                const url = \"/admin/api/totalitems\"; //llamado a la API REST en el controlador almacencontrolador para treaer todas los productos simples y subproductos\r\n                const respuesta = await fetch(url); \r\n                const resultado:{id:string, nombre:string, preciopersonalizado:string, tipoproducto:string, sku:string, unidadmedida:string}[] = await respuesta.json();\r\n                filteredData = resultado.map(item => ({ id: item.id, text: item.nombre, tipo: item.preciopersonalizado?'0':'1', sku: item.sku, unidadmedida: item.unidadmedida }));\r\n                activarselect2(filteredData);\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        })();\r\n\r\n        function activarselect2(filteredData:{id:string, text:string, tipo:string, sku:string, unidadmedida:string}[]){\r\n            ($('#item') as any).select2({ \r\n                data: filteredData,\r\n                placeholder: \"Selecciona un item\",\r\n                maximumSelectionLength: 1,\r\n                /*\r\n                templateResult: function (data:{id:string, text:string, tipo:string}) {\r\n                    // Personalizar cómo se muestra cada opción en el dropdown\r\n                    if (!data.id) { return data.text; }  // Si no hay id, solo mostrar el texto\r\n                    const html = `\r\n                        <div class=\"custom-option\">\r\n                            <span class=\"item-name\">${data.text}</span> \r\n                            <span class=\"item-type\">${data.tipo}</span>  <!-- Mostrar tipo adicional -->\r\n                        </div>`;\r\n                    return $(html);  // Devolver el HTML personalizado\r\n                }*/\r\n            });\r\n        }\r\n\r\n\r\n        async function callApiReporte(dateinicio:string, datefin:string){\r\n            document.querySelector('#fecha1')!.textContent = dateinicio;\r\n            document.querySelector('#fecha2')!.textContent = datefin;\r\n            let datosItem = ($('#item') as any).select2('data')[0];\r\n            if(datosItem === undefined){\r\n                msjalertToast('error', '¡Error!', \"Seleccionar un item de la lista\");\r\n                return;\r\n            }\r\n\r\n            (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n            const datos = new FormData();\r\n            datos.append('fechainicio', dateinicio);\r\n            datos.append('fechafin', datefin+' 23:59:59');\r\n            datos.append('tipo', datosItem.tipo);\r\n            datos.append('iditem', datosItem.id);\r\n            try {\r\n                const url = \"/admin/api/movimientoInventario\"; //llama a la api que esta en reportescontrolador.php\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                const resultado = await respuesta.json();\r\n                datosMovimientosInventarios = resultado;\r\n                console.log(datosMovimientosInventarios);\r\n                printTableMovimientoInventario();\r\n            (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        }\r\n\r\n\r\n        printTableMovimientoInventario();\r\n        function printTableMovimientoInventario(){\r\n            tablaMovimientosInventarios = ($('#tablaMovimientosInventarios') as any).DataTable({\r\n                \"responsive\": true,\r\n                pageLength: 25,\r\n                destroy: true, // importante si recargas la tabla\r\n                data: datosMovimientosInventarios,\r\n                order: [[8, \"desc\"]],\r\n                columns: [\r\n                    {title: 'id', data: 'id'}, \r\n                    {title: 'Usuario', data: 'usuario'},\r\n                    {title: 'Producto', data: 'nombre'},\r\n                    {title: 'Unidad', data: 'unidadmedida'},\r\n                    {\r\n                        title: 'tipo', \r\n                        data: null, \r\n                        orderable: false, \r\n                        searchable: false, \r\n                        render: (data: any, type: any, row: any) => {return `<button class=\"btn-xs ${row.tipo=='venta'?'btn-lima':row.tipo=='compra'?'btn-blue':row.tipo=='ajuste'?'btn-turquoise':(row.tipo=='descuento de unidades' || row.tipo=='descuento por produccion')?'btn-bluelight':row.tipo=='salida por traslado'?'btn-yellow':row.tipo=='devolucion'?'btn-red':'btn-blueintense'}\">${row.tipo}</button>`}\r\n                    },\r\n                    {title: 'Cantidad', data: 'cantidad'},\r\n                    {title: 'Stock anterior', data: 'stockanterior'},\r\n                    {title: 'Stock', data: 'stocknuevo'},\r\n                    {title: 'Fecha', data: 'created_at'},\r\n                    {title: 'Referencia', data: 'referencia'},\r\n                ],\r\n                \r\n                \r\n                language: {\r\n                    search: 'Busqueda',\r\n                    emptyTable: 'No Hay datos disponibles',\r\n                    zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                    lengthMenu: '_MENU_ Entradas por pagina',\r\n                    info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                    infoEmpty: 'No hay entradas a mostrar',\r\n                    infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                    paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n                },\r\n                layout: {\r\n                    topStart: {\r\n                        buttons: [\r\n                        {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                        {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                        {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                        ],\r\n                        pageLength: 'pageLength'\r\n                    }\r\n                }\r\n            });\r\n        }\r\n\r\n        POS.callApiReporte = callApiReporte;\r\n    \r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.reportescompras')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaReportesCompras:HTMLElement;\r\n\r\n    interface compras {\r\n        id:string,\r\n        formapago:string,\r\n        nfactura:string,\r\n        impuesto:string,\r\n        cantidaditems:string,\r\n        observacion:string,\r\n        estado:string,\r\n        subtotal:string,\r\n        valortotal:string,\r\n        fechacompra:string,\r\n        nombreusuario:string,\r\n        nombreproveedor:string,\r\n        nombrecaja:string\r\n        estadocierrecaja:string\r\n    } \r\n\r\n    let datosCompras:compras[] = [];\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiCompras(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiCompras(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiCompras(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiCompras(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiCompras(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiCompras(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/reportecompras\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosCompras = resultado;\r\n            console.log(datosCompras);\r\n            printTableCompras();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableCompras();\r\n    function printTableCompras(){\r\n        tablaReportesCompras = ($('#tablaReportesCompras') as any).DataTable({\r\n            \"responsive\": true,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosCompras,\r\n            columns: [\r\n                {title: 'id', data: 'id'}, \r\n                {title: 'usuario', data: 'nombreusuario'},\r\n                {title: 'proveedor', data: 'nombreproveedor'},\r\n                {title: 'caja', data: null, render: (data:compras)=>{ const x = data.estadocierrecaja == '0'?'Abierta':'Cerrada'; return `${data.nombrecaja} - ${x}`; }},\r\n                {title: 'formapago', data: 'formapago'}, \r\n                {title: 'nfactura', data: 'nfactura'},\r\n                {title: 'cantidaditems', data: 'cantidaditems'},\r\n                {title: 'valortotal', data: 'valortotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                {title: 'fechacompra', data: 'fechacompra'},\r\n                { \r\n                    title: 'Acciones', \r\n                    data: null, \r\n                    orderable: false, \r\n                    searchable: false, \r\n                    render: (data: any, type: any, row: any) => {return `<button class=\"btn-ver mr-4\" data-id=\"${row.id}\">✳️​</button> <button class=\"btn-eliminar\" data-id=\"${row.id}\">⛔​</button>`}\r\n                }\r\n            ],\r\n            \r\n            /*pageLength: 25,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'copyHtml5', text: 'Copia'}, \r\n                    {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'csvHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },*/\r\n        });\r\n    }\r\n\r\n\r\n    //evento click sobre toda la tabla compras\r\n    document.querySelector('#tablaReportesCompras')?.addEventListener(\"click\", (e)=>{\r\n      const target = e.target as HTMLButtonElement;\r\n      let idcompra = target?.dataset.id;\r\n      if((e.target as HTMLButtonElement)?.classList.contains(\"btn-ver\"))verCompra(idcompra);\r\n      if(target?.classList.contains(\"btn-eliminar\"))eliminarCompra(idcompra, target);\r\n    });\r\n\r\n    function verCompra(idcompra:string|undefined){\r\n        const compra = datosCompras.find(x=>x.id==idcompra);\r\n        if(compra?.id != null)window.location.href = '/admin/reportes/detallecompra?id='+compra.id;\r\n    }\r\n\r\n    function eliminarCompra(idcompra:string|undefined, target:HTMLButtonElement){\r\n        const compra = datosCompras.find(x=>x.id==idcompra);\r\n        const fila = (tablaReportesCompras as any).row(target.closest('tr'));\r\n        if(compra?.estadocierrecaja === '0'){\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea eliminar la compra del sistema?',\r\n                text: \"La compra sera eliminado por completo de la aplicacion.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    (async ()=>{\r\n                        const datos = new FormData();\r\n                        datos.append('id', compra.id);\r\n                        try {\r\n                            const url = \"/admin/api/eliminarcompra\"; //llamado a la API REST en reportescontrolador para eliminar la compra\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos});\r\n                            const resultado = await respuesta.json();\r\n                            if(resultado.exito !== undefined){ \r\n                                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                                fila.remove().draw(false);\r\n                            }else{\r\n                                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();\r\n                }\r\n            });\r\n        }else{\r\n             msjalertToast('error', '¡Error!', 'No se puede eliminar la compra, porque la caja esta cerrada');\r\n        }\r\n    }\r\n\r\n\r\n  }\r\n\r\n})();","(():void=>{\r\n  if(document.querySelector('.gastoseingresos')){\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaGastos:HTMLTableElement, tablaIngresos:HTMLTableElement;\r\n\r\n    interface apigastos {\r\n        Id:string,\r\n        id_compra:string,\r\n        idg_cierrecaja:string,\r\n        nombrecaja:string,\r\n        nombrebanco:string,\r\n        nombre:string,\r\n        operacion:string,\r\n        categoriagasto:string,\r\n        estado:string,\r\n        valor:string,\r\n        descripcion:string,\r\n        imgcomprobante:string,\r\n        fecha:string\r\n    }\r\n\r\n    interface apiingresos {\r\n        id:string,\r\n        operacion:string,\r\n        valor:string,\r\n        fecha:string,\r\n        nombrecaja:string,\r\n        estado:string,\r\n        nombreusuario:string\r\n    }\r\n\r\n    let datosGastos:apigastos[] = [], datosIngresos:apiingresos[] = [];\r\n\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiGastosIngresos(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiGastosIngresos(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiGastosIngresos(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiGastosIngresos(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiGastosIngresos(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiGastosIngresos(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/gastoseingresos\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosGastos = resultado.gastos;\r\n            datosIngresos = resultado.ingresos;\r\n            console.log(resultado);\r\n            printTableGastos();\r\n            printTableIngresos();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n    \r\n\r\n\r\n    printTableGastos();\r\n    function printTableGastos(){\r\n        tablaGastos = ($('#tablaGastos') as any).DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosGastos,\r\n            columns: [\r\n                        {title: 'id', data: 'Id'}, \r\n                        {   \r\n                            title: 'Caja', \r\n                            data: null, render: (data: apigastos) => { \r\n                                            const x = data.estado == '0'?'Abierta':'Cerrada';\r\n                                            return `${data.nombrecaja} - ${x}`;\r\n                                        } \r\n                        },\r\n                        {title: 'Banco', data: 'nombrebanco'},\r\n                        {title: 'Usuario', data: 'nombre'},\r\n                        {title: 'Operacion', data: 'operacion'},\r\n                        {title: 'Tipo Gasto', data: 'categoriagasto'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Fecha', data: 'fecha'},\r\n                        { \r\n                            title: 'Acciones', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => { \r\n                                    return `<button class=\"btn-ver\" data-id=\"${row.Id}\">✳️​</button>\r\n                                            <button class=\"btn-imgcomprobante\" data-id=\"${row.Id}\">🧾​</button>\r\n                                            <button class=\"btn-eliminar\" data-id=\"${row.Id}\">⛔​</button>`}\r\n                        },\r\n                        {title: 'Descripcion', data: 'descripcion'},\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printTableIngresos();\r\n    function printTableIngresos(){\r\n        tablaIngresos = ($('#tablaIngresos') as any).DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosIngresos,\r\n            columns: [\r\n                        {title: 'id', data: 'id'}, \r\n                        {   \r\n                            title: 'Caja', \r\n                            data: null, render: (data: apiingresos) => { \r\n                                            const x = data.estado == '0'?'Abierta':'Cerrada';\r\n                                            return `${data.nombrecaja} - ${x}`;\r\n                                        } \r\n                        },\r\n                        {title: 'Usuario', data: 'nombreusuario'},\r\n                        {title: 'Operacion', data: 'operacion'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Fecha', data: 'fecha'},\r\n                        { \r\n                            title: 'Acciones', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<button class=\"btn-eliminar\" data-id=\"${row.id}\">⛔​</button>`}\r\n                        }\r\n                    ],\r\n        });\r\n    }\r\n    \r\n\r\n    //evento click sobre toda la tabla gastos\r\n    document.querySelector('#tablaGastos')?.addEventListener(\"click\", (e)=>{\r\n      const target = e.target as HTMLButtonElement;\r\n      let idgasto = target?.dataset.id;\r\n      if((e.target as HTMLButtonElement)?.classList.contains(\"btn-ver\"))verGasto(idgasto);\r\n      if(target?.classList.contains(\"btn-imgcomprobante\"))imgcomprobante(idgasto);\r\n      if(target?.classList.contains(\"btn-eliminar\"))eliminarGasto(idgasto, target);\r\n    });\r\n\r\n    //solo aplica para gastos de tipo compra\r\n    function verGasto(idgasto:string|undefined){\r\n        const gasto = datosGastos.find(x=>x.Id==idgasto);\r\n        if(gasto?.id_compra != null)window.location.href = '/admin/reportes/detallecompra?id='+gasto.id_compra;\r\n    }\r\n\r\n    function imgcomprobante(idgasto:string|undefined){\r\n        const gasto = datosGastos.find(x=>x.Id==idgasto);\r\n        if(gasto?.imgcomprobante)window.open(\"/build/img/\"+gasto?.imgcomprobante, \"_blank\");\r\n    }\r\n\r\n    function eliminarGasto(idgasto:string|undefined, target:HTMLButtonElement){\r\n        const gasto = datosGastos.find(x=>x.Id==idgasto);\r\n        const fila = (tablaGastos as any).row(target.closest('tr'));\r\n        if(gasto?.estado === '0'){\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea eliminar el gasto de la caja?',\r\n                text: \"El gasto sera eliminado por completo de la caja.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    (async ()=>{\r\n                        const datos = new FormData();\r\n                        datos.append('id', gasto.Id);\r\n                        try {\r\n                            const url = \"/admin/api/eliminargasto\"; //llamado a la API REST en reportescontrolador para eliminar el gasto\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos});\r\n                            const resultado = await respuesta.json();\r\n                            if(resultado.exito !== undefined){ \r\n                                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                                fila.remove().draw(false);\r\n                            }else{\r\n                                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();\r\n                }\r\n            });\r\n        }else{\r\n             msjalertToast('error', '¡Error!', 'No se puede eliminar el gasto, porque la caja esta cerrada');\r\n        }\r\n    }\r\n\r\n\r\n    //evento click sobre toda la tabla ingresos\r\n    document.querySelector('#tablaIngresos')?.addEventListener(\"click\", (e)=>{\r\n      const target = e.target as HTMLButtonElement;\r\n      let idingreso = target?.dataset.id;\r\n      if(target?.classList.contains(\"btn-eliminar\"))eliminarIngreso(idingreso, target);\r\n    });\r\n\r\n    function eliminarIngreso(idingreso:string|undefined, target:HTMLButtonElement){\r\n        const ingreso = datosIngresos.find(x=>x.id==idingreso);\r\n        const fila = (tablaIngresos as any).row(target.closest('tr'));\r\n        if(ingreso?.estado === '0'){\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea eliminar el ingreso de la caja?',\r\n                text: \"El ingreso sera eliminado por completo de la caja.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    (async ()=>{\r\n                        const datos = new FormData();\r\n                        datos.append('id', ingreso.id);\r\n                        try {\r\n                            const url = \"/admin/api/eliminaringreso\"; //llamado a la API REST en reportescontrolador para eliminar un ingreso\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos});\r\n                            const resultado = await respuesta.json();\r\n                            if(resultado.exito !== undefined){ \r\n                                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                                fila.remove().draw(false);\r\n                            }else{\r\n                                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();\r\n                }\r\n            });\r\n        }else{\r\n             msjalertToast('error', '¡Error!', 'No se puede eliminar el ingreso, porque la caja esta cerrada');\r\n        }\r\n    }\r\n\r\n  }\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.utilidadxproducto')){\r\n        let tablaUtilidadXProducto:HTMLElement;\r\n        tablaUtilidadXProducto = ($('#tablaUtilidadXProducto') as any).DataTable(configdatatablesgenerico);\r\n    }\r\n\r\n})();"]}
