string,  //id de la factura\r\n        prefijo:string,\r\n        numero:string, //numero del consecutivo de la factura electronica\r\n        resolucion:string,\r\n        cufe:string,\r\n        identificacion:string,\r\n        nombre:string,\r\n        tipoventa:string,\r\n        base:string,\r\n        valorimpuestototal:string,\r\n        total:string,\r\n        created_at: string\r\n    }\r\n\r\n    let facturaselectronicaspendientes:invoice[] = [];\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiInvoice(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiInvoice(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiInvoice(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin);\r\n        try {\r\n            const url = \"/admin/api/electronicaspendientes\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            facturaselectronicaspendientes = resultado;\r\n            printTableFacturasPagas();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableFacturasPagas();\r\n    function printTableFacturasPagas(){\r\n        tablaelectronicasPendientes = ($('#tablaelectronicasPendientes') as any).DataTable({\r\n            \"responsive\": true,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: facturaselectronicaspendientes,\r\n            columns: [\r\n                        {title: 'Orden', data: 'orden'}, \r\n                        {title: 'Prefijo', data: 'prefijo'}, \r\n                        {title: 'Numero', data: 'numero'},\r\n                        { \r\n                            title: 'Abrir', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<a class=\"btn-ver btn-xs btn-light\" target=\"_blank\" href=\"/admin/reportes/detalleInvoice?id=${row.orden}\" data-id=\"${row.orden}\">Abrir</a>`}\r\n                        },\r\n                        {title: 'Identificacion', data: 'identificacion'}, \r\n                        {title: 'Nombre', data: 'nombre'}, \r\n                        {title: 'Tipo venta', data: 'tipoventa'}, \r\n                        {title: 'Base', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Valor imp', data: 'valorimpuestototal', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Total', data: 'total', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                        {title: 'Fecha', data: 'created_at'}\r\n                    ],\r\n            pageLength: 25,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'copyHtml5', text: 'Copia'}, \r\n                    {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'csvHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n  }\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.estadosfinancierosCreditos'))return;\r\n        const POS = (window as any).POS;\r\n\r\n        let tablaEstdosFinancierosCreditos:HTMLElement;\r\n        let estadosFinancierosCreditos:[] = [];\r\n\r\n\r\n        async function callApiReporte(dateinicio:string, datefin:string){\r\n            document.querySelector('#fecha1')!.textContent = dateinicio;\r\n            document.querySelector('#fecha2')!.textContent = datefin;\r\n            (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n            const datos = new FormData();\r\n            datos.append('fechainicio', dateinicio);\r\n            datos.append('fechafin', datefin);\r\n            try {\r\n                const url = \"/admin/api/reportes/creditos/estadosFinancieros\"; //llama a la api que esta en reportescontrolador.php\r\n                const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n                estadosFinancierosCreditos = await respuesta.json();\r\n                printTableEstadosFinancierosCreditos();\r\n            (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n            } catch (error) {\r\n                console.log(error);\r\n            }\r\n        }\r\n\r\n\r\n        printTableEstadosFinancierosCreditos();\r\n        function printTableEstadosFinancierosCreditos(){\r\n            tablaEstdosFinancierosCreditos = ($('#tablaEstdosFinancierosCreditos') as any).DataTable({\r\n                \"responsive\": true,\r\n                pageLength: 25,\r\n                destroy: true, // importante si recargas la tabla\r\n                data: estadosFinancierosCreditos,\r\n                columns: [\r\n                    {title: 'N°', data: 'num_orden'},\r\n                    {title: 'Emisor', data: 'nombreEmisor', render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data??'Negocio'}</div>`},\r\n                    {title: 'Fecha', data: 'fechainicio'},\r\n                    {title: 'Credito', data: 'capitalTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Costo', data: 'costo_total', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Utl. Comercial', data: 'utilidad_comercial', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Utl. Proyectada', data: 'utilidad_proyectada', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Pagado', data: 'valor_pagado', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {title: 'Utl Realizada', data: 'utilidad_realizada', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    {\r\n                        title: 'Estado',\r\n                        data: 'estado',\r\n                        render: (data: any, type: any, row: any) => {return `<a class=\"btn-xs ${row.estado=='2'?'btn-blue':row.estado=='1'?'btn-lima':'btn-light'}\" target=\"_blank\" href=\"/admin/creditos/detallecredito?id=${row.id}\">${row.estado=='1'?'Finalizado':'Abierto'}</a>`}\r\n                    },\r\n                ],\r\n                \r\n                \r\n                language: {\r\n                    search: 'Busqueda',\r\n                    emptyTable: 'No Hay datos disponibles',\r\n                    zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                    lengthMenu: '_MENU_ Entradas por pagina',\r\n                    info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                    infoEmpty: 'No hay entradas a mostrar',\r\n                    infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                    paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n                },\r\n                layout: {\r\n                    topStart: {\r\n                        buttons: [\r\n                        {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                        {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                        {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                        ],\r\n                        pageLength: 'pageLength'\r\n                    }\r\n                }\r\n            });\r\n        }\r\n\r\n        POS.callApiReporte = callApiReporte;\r\n    \r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.facturasprocesadas')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaFacturasProcesadas:HTMLElement;\r\n\r\n    interface facturaspagas {\r\n        id:string,\r\n        idvendedir:string,\r\n        idcaja:string,\r\n        idconsecutivo:string,\r\n        num_orden:string,\r\n        num_consecutivo:string,\r\n        vendedor:string,\r\n        valorgananciauser:string,\r\n        caja:string,\r\n        tipofacturador:string,\r\n        totalunidades:string,\r\n        recibido:string,\r\n        cambio:string,\r\n        tipoventa:string,\r\n        estado:string,\r\n        cambioaventa:string,\r\n        subtotal:string,\r\n        base:string,\r\n        valorimpuesto:string,\r\n        descuento:string,\r\n        total:string,\r\n        fechapago:string\r\n    } \r\n\r\n    let datosFacturasPagas:facturaspagas[] = [];\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiFacturasPagas(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiFacturasPagas(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/facturaspagas\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosFacturasPagas = resultado;\r\n            printTableFacturasPagas();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableFacturasPagas();\r\n    function printTableFacturasPagas(){\r\n        tablaFacturasProcesadas = ($('#tablaFacturasProcesadas') as any).DataTable({\r\n            \"responsive\": true,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosFacturasPagas,\r\n            columns: [\r\n                {title: 'Orden', data: 'num_orden'},\r\n                {title: 'Fecha Pago', data: 'fechapago', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data}</div>`},\r\n                {\r\n                    title: 'N° Factura', \r\n                    data: null,\r\n                    orderable: false, \r\n                    searchable: false,\r\n                    render: (data: any, type: any, row: any) => {return `${row.prefijo}${row.num_consecutivo}`}\r\n                },\r\n                {title: 'Tipo', data: 'tipofacturador', render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\r\n                {title: 'Tipo Venta', data: 'tipoventa'},\r\n                {\r\n                    title: 'Abrir', \r\n                    data: null, \r\n                    orderable: false, \r\n                    searchable: false, \r\n                    render: (data: any, type: any, row: any) => {return `<a class=\"btn-ver btn-xs btn-light\" target=\"_blank\" href=\"/admin/caja/ordenresumen?id=${row.id}\" data-id=\"${row.id}\">Abrir</a>`}\r\n                },\r\n                {title: 'T. Unds', data: 'totalunidades'},\r\n                {title: 'B. gravable', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`}, \r\n                {title: 'Imp', data: 'valorimpuestototal'}, \r\n                {title: 'Descuento', data: 'descuento'}, \r\n                {title: 'Total', data: 'total', render: (data: number, type: string) => {\r\n                                                                                            if (type === 'display') {\r\n                                                                                            return `$${Number(data).toLocaleString('es-CO')}`;\r\n                                                                                            }\r\n                                                                                            return data; // para export, sort, filter\r\n                                                                                        }}, \r\n                {title: 'Vendedor', data: 'vendedor'},\r\n                {title: 'Comision', data: 'valorgananciauser', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                {title: 'Caja', data: 'caja'}],\r\n            pageLength: 25,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'copyHtml5', text: 'Copia'}, \r\n                    {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'csvHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n  }\r\n\r\n})();","(():void=>{\r\n\r\n  if(document.querySelector('.facturasanuladas')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaFacturasAnuladas:HTMLElement;\r\n\r\n    interface factuarasanuladas {\r\n        id:string,\r\n        idvendedir:string,\r\n        idcaja:string,\r\n        idconsecutivo:string,\r\n        num_orden:string,\r\n        num_consecutivo:string,\r\n        vendedor:string,\r\n        caja:string,\r\n        tipofacturador:string,\r\n        totalunidades:string,\r\n        recibido:string,\r\n        cambio:string,\r\n        tipoventa:string,\r\n        estado:string,\r\n        cambioaventa:string,\r\n        subtotal:string,\r\n        base:string,\r\n        valorimpuesto:string,\r\n        descuento:string,\r\n        total:string,\r\n        fechapago:string\r\n    } \r\n\r\n    let datosFacturasAnuladas:factuarasanuladas[] = [];\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiFacturasPagas(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiFacturasPagas(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiFacturasPagas(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin);\r\n        try {\r\n            const url = \"/admin/api/facturasanuladas\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosFacturasAnuladas = resultado;\r\n            printTableFacturasPagas();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableFacturasPagas();\r\n    function printTableFacturasPagas(){\r\n        tablaFacturasAnuladas = ($('#tablaFacturasAnuladas') as any).DataTable({\r\n            \"responsive\": true,\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosFacturasAnuladas,\r\n            columns: [{title: 'Orden', data: 'num_orden'}, {title: 'N° Factura', data: 'num_consecutivo'}, {title: 'Tipo', data: 'tipofacturador'}, {title: 'Cant vendida', data: 'totalunidades'}, {title: 'B. gravable', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`}, {title: 'Imp', data: 'valorimpuestototal'}, {title: 'Descuento', data: 'descuento'}, {title: 'Total', data: 'total', render: (data:number) => `$${Number(data).toLocaleString()}`}, {title: 'Vendedor', data: 'vendedor'}, {title: 'Caja', data: 'caja'}],\r\n            pageLength: 25,\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                    {extend: 'copyHtml5', text: 'Copia'}, \r\n                    {extend: 'excelHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'csvHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                    {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                    'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n  }\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.recibosCaja'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const tablaRecibosCaja = ($('#tablaRecibosCaja') as any);\r\n\r\n    interface i_ingresosEmisores {\r\n        id: string,\r\n        num_orden:string,\r\n        fecha:string,\r\n        concepto:string,\r\n        numero_documento:string,\r\n        tercero:string,\r\n        mediopago:string,\r\n        observacion:string,\r\n        cajero:string,\r\n        caja: string,\r\n        valor:string,\r\n        valormediopago:string,\r\n        emisor:string\r\n    }\r\n\r\n\r\n\r\n    let ingresosEmisores:i_ingresosEmisores[] = [];\r\n\r\n\r\n\r\n    async function callApiReporte(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/reportes/recibosCaja\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            ingresosEmisores = resultado;\r\n            console.log(ingresosEmisores);\r\n            reporteRecibosCaja();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n    \r\n    reporteRecibosCaja();\r\n    function reporteRecibosCaja(){\r\n        tablaRecibosCaja.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: ingresosEmisores,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Num', data: 'num_orden'},\r\n                        {title: 'Fecha', data: 'fecha', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Concepto', data: 'concepto', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Documento', data: 'documento'},\r\n                        {title: 'Tercero', data: 'tercero', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Medio Pago', data: 'mediopago'},\r\n                        {title: 'Cajero', data: 'cajero'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Valor pagado', data: 'valormediopago', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Emisor', data: 'emisor', render: (data:string) => `<div class=\"w-44 whitespace-normal\">${data==null?'Negocio':data}</div>`},\r\n                        {title: 'Observacion', data: 'observacion', render: (data:string) => `<div class=\"w-52 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Estado', data: 'estadoMov', render: (data:number) => `<div class=\"\">${data==1?'Registrado':'Anulado'}</div>`}\r\n            ],\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                        {extend: 'excelHtml5', title: 'emisores procesadas'},  \r\n                        {extend: 'pdfHtml5', title: 'emisores procesadas'}, \r\n                        {extend: 'print', title: 'emisores procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n    POS.callApiReporte = callApiReporte;\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.remisiones'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const tablaRemisiones = ($('#tablaRemisiones') as any);\r\n\r\n    interface i_remisiones {\r\n        id:string,\r\n        fechacreacion:string,\r\n        fechaentrega?:string,\r\n        vendedor:string,\r\n        cliente:string,\r\n        num_orden:string,\r\n        entrega:string,\r\n        entregado:string,\r\n    }\r\n\r\n    let remisiones:i_remisiones[] = [];\r\n    const labelsRemisiones = ['Id', 'Fecha', 'Fecha entrega', 'Usuario', 'Cliente', 'Orden', 'Entrega', 'Estado', 'Acciones'];\r\n\r\n\r\n    async function callApiReporte(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/reportes/remisiones\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            remisiones = resultado;\r\n            printRemisiones();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n    \r\n    printRemisiones();\r\n    function printRemisiones(){\r\n        const dataTableRemisiones = tablaRemisiones.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: remisiones,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            responsive: {\r\n                details: false\r\n            },\r\n            columns: [\r\n                        {title: 'Id', data: 'id', className: 'all dtr-control', responsivePriority: 1},\r\n                        {title: 'Fecha', data: 'fechacreacion', className: 'all', responsivePriority: 2, render: (data:string) => `<div class=\"w-36 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Fecha Entrega', data: 'fechaentrega', responsivePriority: 7, render: (data:string) => `<div class=\"text-center\">${data??'-'}</div>`},\r\n                        {title: 'Usuario', data: 'vendedor', responsivePriority: 8, render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Cliente', data: 'cliente', responsivePriority: 4, render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Orden', data: 'num_orden', responsivePriority: 3},\r\n                        {title: 'Entrega', data: 'entrega', responsivePriority: 5, render: (data:string) => `<span class=\"rm-delivery\">${data || '-'}</span>`},\r\n                        {title: 'Estado', data: 'entregado', responsivePriority: 6, render: (data:string) => {\r\n                            const entregado = data == '1';\r\n                            return `<span class=\"rm-status ${entregado ? 'rm-status--done' : 'rm-status--pending'}\">${entregado ? 'Despachado' : 'Pendiente'}</span>`;\r\n                        }},\r\n                        { \r\n                            title: 'Acciones', \r\n                            data: null, \r\n                            responsivePriority: 9,\r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<a class=\"rm-action-open\" target=\"_blank\" href=\"/admin/caja/ordenresumen?id=${row.id}\" data-id=\"${row.id}\">Abrir</a>`}\r\n                        },        \r\n            ],\r\n            createdRow: function(row: HTMLTableRowElement) {\r\n                labelsRemisiones.forEach((label, index) => {\r\n                    row.children[index]?.setAttribute('data-rm-label', label);\r\n                });\r\n            },\r\n            drawCallback: function() {\r\n                document.querySelector('.rm-table-card')?.classList.add('rm-remisiones-mobile');\r\n            },\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                        {extend: 'excelHtml5', title: 'facturas procesadas'},  \r\n                        {extend: 'pdfHtml5', title: 'facturas procesadas'}, \r\n                        {extend: 'print', title: 'facturas procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n\r\n        const tablaRemisionesEl = document.querySelector('#tablaRemisiones') as HTMLTableElement|null;\r\n        if(tablaRemisionesEl){\r\n            tablaRemisionesEl.onclick = (e:MouseEvent)=>{\r\n                const target = e.target as HTMLElement;\r\n                const expandCell = target.closest('td') as HTMLTableCellElement|null;\r\n                if(!expandCell || expandCell.cellIndex !== 0 || window.innerWidth > 768)return;\r\n\r\n                const row = expandCell.closest('tr');\r\n                if(!row)return;\r\n\r\n                const dataTableRow = dataTableRemisiones.row(row);\r\n                if(dataTableRow.child.isShown()){\r\n                    dataTableRow.child.hide();\r\n                    row.classList.remove('parent');\r\n                    return;\r\n                }\r\n\r\n                const cells = Array.from(row.querySelectorAll<HTMLTableCellElement>('td'));\r\n                const detailRows = cells.slice(2).map((cell, index) => {\r\n                    const title = labelsRemisiones[index + 2] || '';\r\n                    return `<li><span class=\"dtr-title\">${title}</span><span class=\"dtr-data\">${cell.innerHTML}</span></li>`;\r\n                }).join('');\r\n\r\n                dataTableRow.child(`<ul class=\"dtr-details\">${detailRows}</ul>`, 'child').show();\r\n                row.classList.add('parent');\r\n            };\r\n        }\r\n    }\r\n\r\n\r\n    POS.callApiReporte = callApiReporte;\r\n\r\n})();\r\n","(():void=>{\r\n  if(document.querySelector('.gastoseingresos')){\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaGastos:HTMLTableElement, tablaIngresos:HTMLTableElement;\r\n\r\n    interface apigastos {\r\n        Id:string,\r\n        id_compra:string,\r\n        idg_cierrecaja:string,\r\n        nombrecaja:string,\r\n        nombrebanco:string,\r\n        nombre:string,\r\n        operacion:string,\r\n        categoriagasto:string,\r\n        estado:string,\r\n        valor:string,\r\n        descripcion:string,\r\n        imgcomprobante:string,\r\n        fecha:string\r\n    }\r\n\r\n    interface apiingresos {\r\n        id:string,\r\n        operacion:string,\r\n        valor:string,\r\n        fecha:string,\r\n        nombrecaja:string,\r\n        estado:string,\r\n        nombreusuario:string\r\n    }\r\n\r\n    let datosGastos:apigastos[] = [], datosIngresos:apiingresos[] = [];\r\n\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiGastosIngresos(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiGastosIngresos(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiGastosIngresos(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiGastosIngresos(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiGastosIngresos(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiGastosIngresos(dateinicio:string, datefin:string){\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/gastoseingresos\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosGastos = resultado.gastos;\r\n            datosIngresos = resultado.ingresos;\r\n            console.log(resultado);\r\n            printTableGastos();\r\n            printTableIngresos();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n    \r\n\r\n\r\n    printTableGastos();\r\n    function printTableGastos(){\r\n        tablaGastos = ($('#tablaGastos') as any).DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosGastos,\r\n            columns: [\r\n                        {title: 'id', data: 'Id'}, \r\n                        {   \r\n                            title: 'Caja', \r\n                            data: null, render: (data: apigastos) => { \r\n                                            const x = data.estado == '0'?'Abierta':'Cerrada';\r\n                                            return `${data.nombrecaja} - ${x}`;\r\n                                        } \r\n                        },\r\n                        {title: 'Banco', data: 'nombrebanco'},\r\n                        {title: 'Usuario', data: 'nombre'},\r\n                        {title: 'Operacion', data: 'operacion'},\r\n                        {title: 'Tipo Gasto', data: 'categoriagasto'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Fecha', data: 'fecha'},\r\n                        { \r\n                            title: 'Acciones', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => { \r\n                                    return `<button class=\"btn-ver\" data-id=\"${row.Id}\">✳️​</button>\r\n                                            <button class=\"btn-imgcomprobante\" data-id=\"${row.Id}\">🧾​</button>\r\n                                            <button class=\"btn-eliminar\" data-id=\"${row.Id}\">⛔​</button>`}\r\n                        },\r\n                        {title: 'Descripcion', data: 'descripcion'},\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printTableIngresos();\r\n    function printTableIngresos(){\r\n        tablaIngresos = ($('#tablaIngresos') as any).DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosIngresos,\r\n            columns: [\r\n                        {title: 'id', data: 'id'}, \r\n                        {   \r\n                            title: 'Caja', \r\n                            data: null, render: (data: apiingresos) => { \r\n                                            const x = data.estado == '0'?'Abierta':'Cerrada';\r\n                                            return `${data.nombrecaja} - ${x}`;\r\n                                        } \r\n                        },\r\n                        {title: 'Usuario', data: 'nombreusuario'},\r\n                        {title: 'Operacion', data: 'operacion'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Fecha', data: 'fecha'},\r\n                        { \r\n                            title: 'Acciones', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<button class=\"btn-eliminar\" data-id=\"${row.id}\">⛔​</button>`}\r\n                        }\r\n                    ],\r\n        });\r\n    }\r\n    \r\n\r\n    //evento click sobre toda la tabla gastos\r\n    document.querySelector('#tablaGastos')?.addEventListener(\"click\", (e)=>{\r\n      const target = e.target as HTMLButtonElement;\r\n      let idgasto = target?.dataset.id;\r\n      if((e.target as HTMLButtonElement)?.classList.contains(\"btn-ver\"))verGasto(idgasto);\r\n      if(target?.classList.contains(\"btn-imgcomprobante\"))imgcomprobante(idgasto);\r\n      if(target?.classList.contains(\"btn-eliminar\"))eliminarGasto(idgasto, target);\r\n    });\r\n\r\n    //solo aplica para gastos de tipo compra\r\n    function verGasto(idgasto:string|undefined){\r\n        const gasto = datosGastos.find(x=>x.Id==idgasto);\r\n        if(gasto?.id_compra != null)window.location.href = '/admin/reportes/detallecompra?id='+gasto.id_compra;\r\n    }\r\n\r\n    function imgcomprobante(idgasto:string|undefined){\r\n        const gasto = datosGastos.find(x=>x.Id==idgasto);\r\n        if(gasto?.imgcomprobante)window.open(\"/build/img/\"+gasto?.imgcomprobante, \"_blank\");\r\n    }\r\n\r\n    function eliminarGasto(idgasto:string|undefined, target:HTMLButtonElement){\r\n        const gasto = datosGastos.find(x=>x.Id==idgasto);\r\n        const fila = (tablaGastos as any).row(target.closest('tr'));\r\n        if(gasto?.estado === '0'){\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea eliminar el gasto de la caja?',\r\n                text: \"El gasto sera eliminado por completo de la caja.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    (async ()=>{\r\n                        const datos = new FormData();\r\n                        datos.append('id', gasto.Id);\r\n                        try {\r\n                            const url = \"/admin/api/eliminargasto\"; //llamado a la API REST en reportescontrolador para eliminar el gasto\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos});\r\n                            const resultado = await respuesta.json();\r\n                            if(resultado.exito !== undefined){ \r\n                                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                                fila.remove().draw(false);\r\n                            }else{\r\n                                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();\r\n                }\r\n            });\r\n        }else{\r\n             msjalertToast('error', '¡Error!', 'No se puede eliminar el gasto, porque la caja esta cerrada');\r\n        }\r\n    }\r\n\r\n\r\n    //evento click sobre toda la tabla ingresos\r\n    document.querySelector('#tablaIngresos')?.addEventListener(\"click\", (e)=>{\r\n      const target = e.target as HTMLButtonElement;\r\n      let idingreso = target?.dataset.id;\r\n      if(target?.classList.contains(\"btn-eliminar\"))eliminarIngreso(idingreso, target);\r\n    });\r\n\r\n    function eliminarIngreso(idingreso:string|undefined, target:HTMLButtonElement){\r\n        const ingreso = datosIngresos.find(x=>x.id==idingreso);\r\n        const fila = (tablaIngresos as any).row(target.closest('tr'));\r\n        if(ingreso?.estado === '0'){\r\n            Swal.fire({\r\n                customClass: {confirmButton: 'sweetbtnconfirm', cancelButton: 'sweetbtncancel'},\r\n                icon: 'question',\r\n                title: 'Desea eliminar el ingreso de la caja?',\r\n                text: \"El ingreso sera eliminado por completo de la caja.\",\r\n                showCancelButton: true,\r\n                confirmButtonText: 'Si',\r\n                cancelButtonText: 'No',\r\n            }).then((result:any) => {\r\n                if (result.isConfirmed) {\r\n                    (async ()=>{\r\n                        const datos = new FormData();\r\n                        datos.append('id', ingreso.id);\r\n                        try {\r\n                            const url = \"/admin/api/eliminaringreso\"; //llamado a la API REST en reportescontrolador para eliminar un ingreso\r\n                            const respuesta = await fetch(url, {method: 'POST', body: datos});\r\n                            const resultado = await respuesta.json();\r\n                            if(resultado.exito !== undefined){ \r\n                                msjalertToast('success', '¡Éxito!', resultado.exito[0]);\r\n                                fila.remove().draw(false);\r\n                            }else{\r\n                                msjalertToast('error', '¡Error!', resultado.error[0]);\r\n                            }\r\n                        } catch (error) {\r\n                            console.log(error);\r\n                        }\r\n                    })();\r\n                }\r\n            });\r\n        }else{\r\n             msjalertToast('error', '¡Error!', 'No se puede eliminar el ingreso, porque la caja esta cerrada');\r\n        }\r\n    }\r\n\r\n  }\r\n\r\n})();","(()=>{\r\n    if(document.querySelector('.utilidadxproducto')){\r\n        let tablaUtilidadXProducto:HTMLElement;\r\n        tablaUtilidadXProducto = ($('#tablaUtilidadXProducto') as any).DataTable(configdatatablesgenerico);\r\n    }\r\n\r\n})();","(()=>{\r\n    if(!document.querySelector('.reporteEmisores'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const tablaReporteEmisores = ($('#tablaReporteEmisores') as any);\r\n    const tablaventasXemisor = ($('#tablaventasXemisor') as any);\r\n\r\n    interface i_ingresosEmisores {\r\n        emisor:string,\r\n        numventas:string,\r\n        subtotal:string,\r\n        base:string,\r\n        impuesto:string,\r\n        descuento:string,\r\n        totalventas:string,\r\n        ingresos:string\r\n    }\r\n\r\n    interface i_ventasXEmisor {\r\n        num_orden:string,\r\n        fechapago:string,\r\n        prefijo:string,\r\n        num_consecutivo:string,\r\n        tipofacturador:string,\r\n        tipoventa:string,\r\n        subtotal:string,\r\n        base:string,\r\n        valorimpuestototal:string,\r\n        descuento:string,\r\n        total:string,\r\n        vendedor:string,\r\n        caja:string\r\n    } \r\n\r\n\r\n    let f1:string = '', f2:string = '', idemisor:string = '', ingresosEmisores:i_ingresosEmisores[] = [], ventasXEmisor:i_ventasXEmisor[] = [];\r\n\r\n\r\n    ($('#selectEmisor') as any).select2({ \r\n        placeholder: \"Selecciona un item\",\r\n        maximumSelectionLength: 1,\r\n    });\r\n\r\n\r\n    $(\"#selectEmisor\").on('change', (e)=>{\r\n            idemisor = (e.target as HTMLInputElement).value;\r\n            if(f1!=''&&f2!='')callApiReporte(f1, f2);\r\n    });\r\n\r\n\r\n    async function callApiReporte(dateinicio:string, datefin:string){\r\n        f1 = dateinicio;\r\n        f2 = datefin;\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        datos.append('idemisor', idemisor);\r\n        try {\r\n            const url = \"/admin/api/reportes/reporteEmisores\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            ingresosEmisores = resultado.ingresos;\r\n            ventasXEmisor = resultado.ventasXEmisor;\r\n            reporteEmisores();\r\n            printVentasXEmisor();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n    \r\n    reporteEmisores();\r\n    function reporteEmisores(){\r\n        tablaReporteEmisores.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: ingresosEmisores,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Emisor', data: 'emisor', render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\r\n                        {title: 'N° ventas', data: 'numventas'},\r\n                        {title: 'Subtotal', data: 'subtotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Base gravable', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Impuesto', data: 'impuesto', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Descuento', data: 'descuento', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total', data: 'totalventas', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Ingresos', data: 'ingresos', render: (data:number) => `<p class=\"m-0 font-semibold\"> $${Number(data).toLocaleString()} </p>`}\r\n            ],\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                        {extend: 'excelHtml5', title: 'emisores procesadas'},  \r\n                        {extend: 'pdfHtml5', title: 'emisores procesadas'}, \r\n                        {extend: 'print', title: 'emisores procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n    printVentasXEmisor();\r\n    function printVentasXEmisor(){\r\n        tablaventasXemisor.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: ventasXEmisor,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Orden', data: 'num_orden'},\r\n                        {title: 'Fecha Pago', data: 'fechapago'},\r\n                        {\r\n                            title: 'N° Factura', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false,\r\n                            render: (data: any, type: any, row: any) => {return `${row.prefijo}${row.num_consecutivo}`}\r\n                        },\r\n                        {title: 'Tipo', data: 'tipofacturador', render: (data:string) => `<div class=\"w-48 whitespace-normal\">${data}</div>`},\r\n                        {title: 'Tipo Venta', data: 'tipoventa'},\r\n                        { \r\n                            title: 'Abrir', \r\n                            data: null, \r\n                            orderable: false, \r\n                            searchable: false, \r\n                            render: (data: any, type: any, row: any) => {return `<a class=\"btn-ver btn-xs btn-light\" target=\"_blank\" href=\"/admin/caja/ordenresumen?id=${row.id}\" data-id=\"${row.id}\">Abrir</a>`}\r\n                        },\r\n                        {title: 'Subtotal', data: 'subtotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'B. Gravable', data: 'base', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Imp', data: 'valorimpuestototal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Descuento', data: 'descuento', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total', data: 'total', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Vendedor', data: 'vendedor'},\r\n                        {title: 'Caja', data: 'caja'}\r\n            ],\r\n            language: {\r\n                search: 'Busqueda',\r\n                emptyTable: 'No Hay datos disponibles',\r\n                zeroRecords:    \"No se encontraron registros coincidentes\",\r\n                lengthMenu: '_MENU_ Entradas por pagina',\r\n                info: 'Mostrando pagina _PAGE_ de _PAGES_',\r\n                infoEmpty: 'No hay entradas a mostrar',\r\n                infoFiltered: ' (filtrado desde _MAX_ registros)',\r\n                paginate: {\"first\": \"<<\", \"last\": \">>\", \"next\": \">\", \"previous\": \"<\"}\r\n            },\r\n            layout: {\r\n                topStart: {\r\n                    buttons: [\r\n                        {extend: 'excelHtml5', title: 'emisores procesadas'},  \r\n                        {extend: 'pdfHtml5', title: 'emisores procesadas'}, \r\n                        {extend: 'print', title: 'emisores procesadas', text: 'Imprimir'},\r\n                        'colvis'\r\n                    ],\r\n                    pageLength: 'pageLength'\r\n                }\r\n            },\r\n        });\r\n    }\r\n\r\n\r\n    POS.callApiReporte = callApiReporte;\r\n\r\n})();","\r\n(()=>{\r\n\r\n    if(!document.querySelector('.ventasgenerales'))return;\r\n\r\n    const POS = (window as any).POS;\r\n\r\n    const tablaProductosVendidos = ($('#tablaProductosVendidos') as any);\r\n    const tablaMediosPagos = ($('#tablaMediosPagos') as any);\r\n    const tablacreditosSeparados = ($('#tablacreditosSeparados') as any);\r\n    const tablaGastos = ($('#tablaGastos') as any);\r\n    const tablaIngresoCanalventa = ($('#tablaIngresoCanalventa') as any);\r\n    const tablaVentasXUsuario = ($('#tablaVentasXUsuario') as any);\r\n    const tablaResumenVentas = ($('#tablaResumenVentas') as any);\r\n    const tablaResumenCreditos = document.querySelector('#tablaResumenCreditos tbody');\r\n    const printBalance = document.querySelector('#printBalance') as HTMLButtonElement;\r\n    \r\n    interface i_productosVendidos {\r\n        idproducto:string,\r\n        cantidadrefencia:string,\r\n        nombreproducto:string,\r\n        totalProductosVendidos:string,\r\n        valorunidad:string,\r\n        valorTotal:string\r\n    }\r\n\r\n    interface i_mediosPagos {\r\n        idmediopago:string,\r\n        cantidadMP:string,\r\n        mediopago:string,\r\n        valor:string\r\n    }\r\n\r\n    interface i_creditosSeparados {\r\n        idestadocreditos:string,\r\n        estado:string\r\n        carteraTotal:string,\r\n        carteraXCobrar:string,\r\n        totalAbonado:string,\r\n        total:string,\r\n    }\r\n\r\n    interface i_canaldeVenta {\r\n        canaldeventa:string,\r\n        transacciones:string,\r\n        valor:string,\r\n    }\r\n\r\n\r\n    interface i_ventasEmpleados {\r\n        empleado:string,\r\n        ventasRealizadas:string,\r\n        totalVentas:string,\r\n        porcentaje:string,\r\n        valorComision:string,\r\n    }\r\n\r\n    interface i_gastos {\r\n        descripcion:string,\r\n        tipogasto:string,\r\n        valor:string,\r\n    }\r\n    \r\n    interface i_resumenVentas {\r\n        ventas:string,\r\n        total_ventas:string,\r\n        total_costo:string,\r\n        ganancia:string,\r\n        margenutilidad:string,\r\n    }\r\n\r\n    interface i_resumenCreditos {\r\n        creditos:string,\r\n        capitalTotal:string,\r\n        costo_total:string,\r\n        utilidad_comercial:string,\r\n        utilidad_proyectada:string,\r\n        valor_pagado:string,\r\n        utilidad_realizada:string\r\n    }\r\n\r\n    let productosVendidos:i_productosVendidos[] = [], mediosPagos:i_mediosPagos[] = [], creditosSeparados:i_creditosSeparados[] = [], ventasEmpleados:i_ventasEmpleados[]=[], gastos:i_gastos[]=[], canalVenta:i_canaldeVenta[]=[], resumenVentas:i_resumenVentas[]=[], resumenCreditos:i_resumenCreditos[]=[];\r\n    let totalabonos:number = 0, dateStart = '', dateEnd = '';\r\n    //tablaProductosVendidos.DataTable(configdatatables25reg);\r\n\r\n\r\n    async function callApiReporte(dateinicio:string, datefin:string){\r\n        dateStart = dateinicio;\r\n        dateEnd = datefin;\r\n        document.querySelector('#fecha1')!.textContent = dateinicio;\r\n        document.querySelector('#fecha2')!.textContent = datefin;\r\n        \r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/reportes/reportesGenerales\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            productosVendidos = resultado.productosVendidos;\r\n            mediosPagos = resultado.mediosPagos;\r\n            creditosSeparados = resultado.separados;\r\n            ventasEmpleados = resultado.ventasXusuario;\r\n            gastos = resultado.gastos;\r\n            canalVenta = resultado.canalVenta;\r\n            resumenCreditos = resultado.resumenCreditos;\r\n            resumenVentas = resultado.resumenVentas;\r\n            printProductosVendidos();\r\n            printMediosPagos();\r\n            printCreditosSeparados();\r\n            printVentasUsuarios();\r\n            printGastos();\r\n            printCanalVenta();\r\n            totalabonos = Number(resultado.totalabonos);\r\n            printResumen(Number(resultado.totalDescuentos[0].total_descuentos));\r\n            document.querySelector('#totalDescto')!.textContent = '$'+Number(resultado.totalDescuentos[0].total_descuentos).toLocaleString();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printProductosVendidos();\r\n    function printProductosVendidos(){\r\n        tablaProductosVendidos.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: productosVendidos,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Producto', data: 'nombreproducto'},\r\n                        {title: 'Cantidad Vendida', data: 'totalProductosVendidos'},\r\n                        {title: 'V. Unidad', data: 'valorunidad', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total Ventas', data: 'valorTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Costo Total', data: 'costoTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Utilidad', data: 'utilidad', render: (data:number) => `$${Number(data).toLocaleString()}`}\r\n                    ],\r\n        });\r\n    }\r\n\r\n    printMediosPagos();\r\n    function printMediosPagos(){\r\n        tablaMediosPagos.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: mediosPagos,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Medio de Pago', data: 'mediopago'},\r\n                        {title: 'Transacciones', data: 'cantidadMP'},\r\n                        {title: 'Total Ventas', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });\r\n    }\r\n\r\n    printCreditosSeparados();\r\n    function printCreditosSeparados(){\r\n        tablacreditosSeparados.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: creditosSeparados,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {\r\n                            title: 'Estado', \r\n                            data: 'estado', \r\n                            render: (data: any, type: any, row: any) => {return `<button class=\"btn-xs ${row.estado=='Abierto'?'btn-blue':row.estado=='Finalizado'?'btn-lima':'btn-light'}\">${row.estado}</button>`}\r\n                        },\r\n                        {title: 'Cartera Total', data: 'carteraTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Cartera Por Cobrar', data: 'carteraXCobrar', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total Abonado', data: 'totalAbonado', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total', data: 'total'}\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printCanalVenta();\r\n    function printCanalVenta(){\r\n        tablaIngresoCanalventa.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: canalVenta,\r\n            pageLength: 25,\r\n            order: [[ 1, 'asc' ]],\r\n            columns: [\r\n                        {title: 'Canal De Venta', data: 'canalVenta'},\r\n                        {title: 'Transacciones', data: 'transacciones'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printVentasUsuarios();\r\n    function printVentasUsuarios(){\r\n        tablaVentasXUsuario.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: ventasEmpleados,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Empleado', data: 'empleado'},\r\n                        {title: 'Ventas Realizadas', data: 'ventasRealizadas'},\r\n                        {title: 'Total Ventas', data: 'totalVentas', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Porcentaje', data: 'porcentaje'},\r\n                        {title: 'Valor comision', data: 'valorComision', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printGastos();\r\n    function printGastos(){\r\n        tablaGastos.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: gastos,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Descripcion', data: 'descripcion'},\r\n                        {title: 'Tipo Gasto', data: 'tipogasto'},\r\n                        {title: 'Valor', data: 'valor', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });\r\n    }\r\n\r\n\r\n    printResumen(0);\r\n    function printResumen(dscto:number){\r\n\r\n        const contentUtilidadRF = document.querySelector('#contentUtilidadRF') as HTMLSpanElement;\r\n        const textUtilidadRF = document.querySelector('#textUtilidadRF') as HTMLSpanElement;\r\n        const utilidadRF = document.querySelector('#utilidadRF') as HTMLSpanElement;\r\n\r\n        const ventaBruta = Number(resumenVentas[0]?.total_ventas??0);\r\n        const ventaNeta = ventaBruta - dscto;\r\n        const totalIngreso = ventaNeta+totalabonos;\r\n        const totalEgreso = Number(gastos.at(-1)?.valor ?? 0);\r\n        const utilidadTotal = totalIngreso - totalEgreso;\r\n        const margenUtilidadTotal = totalIngreso > 0 ? (utilidadTotal / totalIngreso) * 100 : 0;\r\n        const rentabilidadTotal = totalEgreso > 0 ? (utilidadTotal / totalEgreso) * 100 : 0;\r\n\r\n        //cards\r\n        (document.querySelector('#IngresoTotalCard') as HTMLElement).textContent = '$'+totalIngreso.toLocaleString();\r\n        (document.querySelector('#utilidadCard') as HTMLElement).textContent = '$'+utilidadTotal.toLocaleString();\r\n        (document.querySelector('#totalAbonosCard') as HTMLElement).textContent = '$'+totalabonos.toLocaleString();\r\n        (document.querySelector('#carteraPendienteCard') as HTMLElement).textContent = '$'+Number(creditosSeparados[1]?.carteraXCobrar??0).toLocaleString();\r\n\r\n        //tabla de resumen financiero\r\n        (document.querySelector('#ventaBrutaRF') as HTMLSpanElement).textContent = '$'+ventaBruta.toLocaleString();\r\n        (document.querySelector('#descuentosRF') as HTMLSpanElement).textContent = '-$'+dscto.toLocaleString();\r\n        (document.querySelector('#ventaNetaRF') as HTMLSpanElement).textContent =  '$'+ventaNeta.toLocaleString();\r\n        (document.querySelector('#totalAbonosRF') as HTMLSpanElement).textContent = '$'+totalabonos.toLocaleString();\r\n        (document.querySelector('#ingresoTotalRF') as HTMLSpanElement).textContent = '$'+totalIngreso.toLocaleString();\r\n        (document.querySelector('#egresosRF') as HTMLSpanElement).textContent = '-$'+totalEgreso.toLocaleString();\r\n        (document.querySelector('#margenUtilidadRF') as HTMLSpanElement).textContent = margenUtilidadTotal.toLocaleString()+'%';\r\n        utilidadRF.textContent = '$'+utilidadTotal.toLocaleString();\r\n        if(utilidadTotal>=0){\r\n            contentUtilidadRF.classList.add('bg-emerald-500/10', 'border-emerald-500/20');\r\n            textUtilidadRF.classList.add('text-emerald-700');\r\n            utilidadRF.classList.add('text-emerald-600');\r\n            contentUtilidadRF.classList.remove('bg-red-500/10', 'border-red-500/20');\r\n            textUtilidadRF.classList.remove('text-red-700');\r\n            utilidadRF.classList.remove('text-red-600');\r\n        }else{\r\n            contentUtilidadRF.classList.remove('bg-emerald-500/10', 'border-emerald-500/20');\r\n            textUtilidadRF.classList.remove('text-emerald-700');\r\n            utilidadRF.classList.remove('text-emerald-600');\r\n            contentUtilidadRF.classList.add('bg-red-500/10', 'border-red-500/20');\r\n            textUtilidadRF.classList.add('text-red-700');\r\n            utilidadRF.classList.add('text-red-600');\r\n        }\r\n\r\n\r\n\r\n        //resumen financiero total de ventas\r\n        tablaResumenVentas.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: resumenVentas,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Ventas', data: 'ventas'},\r\n                        {title: 'Total Ventas Productos', data: 'total_ventas', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Total Costo Productos', data: 'total_costo', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Ganancia', data: 'ganancia', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Margen Utilidad', data: 'margenutilidad', render: (data:number) => `${Number(data).toLocaleString()}%`},\r\n                    ],\r\n        });\r\n\r\n        //resumen financiero total creditos\r\n        /*tablaResumenCreditos.DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: resumenCreditos,\r\n            pageLength: 25,\r\n            order: [[ 1, 'desc' ]],\r\n            columns: [\r\n                        {title: 'Creditos', data: 'creditos'},\r\n                        {title: 'Credito Total', data: 'capitalTotal', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Costo Total', data: 'costo_total', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Utilidad Comercial', data: 'utilidad_comercial', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Utilidad Proyectada', data: 'utilidad_proyectada', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Pago total', data: 'valor_pagado', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                        {title: 'Utilidad Realizada', data: 'utilidad_realizada', render: (data:number) => `$${Number(data).toLocaleString()}`},\r\n                    ],\r\n        });*/\r\n\r\n\r\n        //tabla resumen financiero de creditos\r\n        const tr = document.createElement('tr') as HTMLTableRowElement;\r\n        while(tablaResumenCreditos?.firstChild)tablaResumenCreditos.removeChild(tablaResumenCreditos.firstChild);\r\n        tr.insertAdjacentHTML('afterbegin', `\r\n          <td class=\"\">${resumenCreditos[0]?.creditos??0}</td> \r\n          <td class=\"\">$${Number(resumenCreditos[0]?.capitalTotal??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.costo_total??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.utilidad_comercial??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.utilidad_proyectada??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.valor_pagado??0).toLocaleString()}</td>\r\n          <td class=\"\">$${Number(resumenCreditos[0]?.utilidad_realizada??0).toLocaleString()}</td>`);\r\n        tablaResumenCreditos?.appendChild(tr);\r\n\r\n        //tabla rentabilidad\r\n        (document.querySelector('#ingresoTotal') as HTMLElement).textContent = '$'+totalIngreso.toLocaleString();\r\n        (document.querySelector('#egreso') as HTMLElement).textContent = '$'+totalEgreso.toLocaleString();\r\n        (document.querySelector('#utilidadTotal') as HTMLElement).textContent = '$'+utilidadTotal.toLocaleString();\r\n        (document.querySelector('#margenUtilidadTotal') as HTMLElement).textContent = margenUtilidadTotal.toFixed(2) + '%';\r\n        (document.querySelector('#rentabilidadTotal') as HTMLElement).textContent = rentabilidadTotal.toFixed(2) + '%';\r\n    }\r\n\r\n\r\n    printBalance.addEventListener('click', ()=>{\r\n      const contentBalanceGeneral = document.querySelector('#contentBalanceGeneral') as HTMLElement;\r\n\r\n      const ventana = window.open('', '_blank', 'width=900,height=700');\r\n      if(ventana){\r\n        ventana?.document.write(`\r\n            <html>\r\n                <head>\r\n                    <title>Balance</title>\r\n                    <link rel=\"stylesheet\" href=\"/build/css/tailwindapp.css\">\r\n                    <link rel=\"stylesheet\" href=\"/build/css/app.css\">\r\n                </head>\r\n                <body class=\"p-6\">\r\n                    <div class=\"my-8 p-6\">\r\n                        <h2 class=\"text-gray-600 text-3xl font-semibold my-12 pb-4 text-center\">📊 Balance financiero General</h2>\r\n                        <p class=\"text-2xl text-gray-600 mb-0\">PERIODO, <span class=\"text-gray-900 font-semibold ml-8\">Inicio: ${dateStart} - Fin: ${dateEnd}</span></p>    \r\n                    </div>\r\n                    ${contentBalanceGeneral.innerHTML}\r\n                </body>\r\n            </html>\r\n        `);\r\n\r\n        ventana.document.close();\r\n        ventana.onload = ()=>{\r\n            ventana?.focus();\r\n            ventana?.print();\r\n            setTimeout(() => { ventana?.close(); }, 200); // Cerrar la ventana después de unos segundos\r\n        };\r\n      }\r\n    });\r\n\r\n\r\n    POS.callApiReporte = callApiReporte;\r\n\r\n})();","(()=>{\r\n  if(document.querySelector('.ventasxtransaccion')){\r\n\r\n    const btnmensual = document.querySelector('#btnmensual') as HTMLButtonElement;\r\n    const btndiario = document.querySelector('#btndiario') as HTMLButtonElement;\r\n    const miDialogoMes = document.querySelector('#miDialogoMes') as any;\r\n    const miDialogoDiario = document.querySelector('#miDialogoDiario') as any;\r\n    let tablaTransaccioneXVenta:HTMLTableElement;\r\n\r\n    interface transacciones {\r\n      fecha:string,\r\n      total_venta:string,\r\n      num_transacciones:string,\r\n      promedio_transaccion:string,\r\n      transaccion_mas_alta:string,\r\n      transaccion_mas_baja:string\r\n    }\r\n    let datatransacciones:transacciones[] = [];\r\n\r\n    btnmensual?.addEventListener('click', ()=>{\r\n        miDialogoMes.showModal(); //seleccionar año\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n    btndiario?.addEventListener('click', ()=>{\r\n        miDialogoDiario.showModal();  //seleccionar mes\r\n        document.addEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    //seleccionar año, transacciones mes acumulado de un año\r\n    document.querySelector('#formMes')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      const inputselectaño = document.querySelector('#inputselectaño') as HTMLInputElement;\r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/ventasxtransaccionanual?x=\"+inputselectaño.value; //llamado a la API REST en reportescontrolador.php\r\n          const respuesta = await fetch(url);\r\n          const resultado = await respuesta.json();\r\n          datatransacciones = resultado;\r\n          console.log(resultado);\r\n          printTableTranscciones()\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n      miDialogoMes.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    //seleccionar mes, transacciones acumuladas por dia durante un mes y año elejido\r\n    document.querySelector('#formDiario')?.addEventListener('submit', e=>{\r\n      e.preventDefault();\r\n      const inputselectmesyaño = document.querySelector('#inputselectmesyaño') as HTMLInputElement;\r\n      (async ()=>{\r\n        try {\r\n          const url = \"/admin/api/ventasxtransaccionmes?x=\"+inputselectmesyaño.value; //llamado a la API REST en reportescontrolador.php\r\n          const respuesta = await fetch(url); \r\n          const resultado = await respuesta.json();\r\n          datatransacciones = resultado;\r\n          printTableTranscciones()\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n      })();\r\n      miDialogoDiario.close();\r\n      document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n    });\r\n\r\n\r\n    printTableTranscciones();\r\n    function printTableTranscciones(){\r\n\r\n        tablaTransaccioneXVenta = ($('#tablaTransaccioneXVenta') as any).DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datatransacciones,\r\n            columns: [{title: 'Fecha', data: 'fecha'}, {title: 'Toal venta', data: 'total_venta', render: (data: number) => `$${Number(data).toLocaleString()}`}, {title: 'Numero de transacciones', data: 'num_transacciones'}, {title: 'Promedio por transacción', data: 'promedio_transaccion'}, {title: 'Transacción mas alta', data: 'transaccion_mas_alta'}, {title: 'Transacción mas baja', data: 'transaccion_mas_baja'}],\r\n        });\r\n    }\r\n\r\n\r\n\r\n    function cerrarDialogoExterno(event:Event) {\r\n      const f = event.target;\r\n      if (f === miDialogoMes || f === miDialogoDiario || (f as HTMLInputElement).closest('.salir')) {\r\n        miDialogoMes.close();\r\n        miDialogoDiario.close();\r\n        document.removeEventListener(\"click\", cerrarDialogoExterno);\r\n      }\r\n    }\r\n\r\n  }\r\n\r\n\r\n})();\r\n   ","(():void=>{\r\n\r\n  if(document.querySelector('.ventasxcliente')){\r\n\r\n    const consultarFechaPersonalizada = document.querySelector('#consultarFechaPersonalizada') as HTMLButtonElement;\r\n    const btnmesactual = document.querySelector('#btnmesactual') as HTMLButtonElement;\r\n    const btnmesanterior = document.querySelector('#btnmesanterior') as HTMLButtonElement;\r\n    const btnhoy = document.querySelector('#btnhoy') as HTMLButtonElement;\r\n    const btnayer = document.querySelector('#btnayer') as HTMLButtonElement;\r\n    let fechainicio:string = \"\", fechafin:string = \"\", tablaVentasXCliente:HTMLElement;\r\n\r\n    interface ventaxcliente {\r\n        id:string,\r\n        nombre:string,\r\n        cantidad_facturas:string,\r\n        total_ventas:string\r\n    } \r\n\r\n    let datosVentaXCliente:ventaxcliente[] = [];\r\n\r\n\r\n    // SELECTOR DE FECHAS DEL CALENDARIO\r\n    ($('input[name=\"datetimes\"]')as any).daterangepicker({\r\n      timePicker: true,\r\n      //startDate: moment().startOf('hour'),\r\n      //endDate: moment().startOf('hour').add(32, 'hour'),\r\n      startDate: moment().set({ hour: 0, minute: 0, second: 1 }),\r\n      endDate: moment().set({ hour: 23, minute: 59, second: 59 }),\r\n      locale: {\r\n        format: 'M/DD hh:mm A'\r\n      }\r\n    });\r\n\r\n    $('input[name=\"datetimes\"]').on('apply.daterangepicker', function(ev, picker) {\r\n        var startDate = picker.startDate.format('YYYY-MM-DD HH:mm:ss');\r\n        var endDate = picker.endDate.format('YYYY-MM-DD HH:mm:ss');\r\n        fechainicio = startDate;\r\n        fechafin = endDate;\r\n        //(document.querySelector('#fechainicio') as HTMLParagraphElement).textContent = fechainicio;\r\n        //(document.querySelector('#fechafin') as HTMLParagraphElement).textContent = fechafin;\r\n    });\r\n\r\n    btnmesactual.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        // Primer día del mes actual\r\n        const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\r\n        // Último día del mes actual\r\n        const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\r\n        const fechainiciobtn:string = primerDia.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDia.toISOString().split('T')[0];\r\n        callApiVentasXCliente(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n\r\n    btnmesanterior.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Primer día del mes anterior\r\n        const primerDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);\r\n        // Último día del mes anterior\r\n        const ultimoDiaMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);\r\n        const fechainiciobtn:string = primerDiaMesAnterior.toISOString().split('T')[0];\r\n        const fechafinbtn:string = ultimoDiaMesAnterior.toISOString().split('T')[0];\r\n        callApiVentasXCliente(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnhoy.addEventListener('click', (e:Event)=>{\r\n        const hoy = new Date();\r\n        const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 0, 0, 0);\r\n        const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioDia);\r\n        const fechafinbtn:string = formatoFecha(finDia);\r\n        callApiVentasXCliente(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    btnayer.addEventListener('click', (e:Event)=>{\r\n        // Fecha actual\r\n        const hoy = new Date();\r\n        // Día anterior\r\n        const ayer = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() - 1);\r\n        // Inicio y fin del día anterior\r\n        const inicioAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 0, 0, 0);\r\n        const finAyer = new Date(ayer.getFullYear(), ayer.getMonth(), ayer.getDate(), 23, 59, 59);\r\n        const fechainiciobtn:string = formatoFecha(inicioAyer);\r\n        const fechafinbtn:string = formatoFecha(finAyer);\r\n        callApiVentasXCliente(fechainiciobtn, fechafinbtn);\r\n    });\r\n\r\n    function formatoFecha(fecha: Date): string {\r\n        const año = fecha.getFullYear();\r\n        const mes = String(fecha.getMonth() + 1).padStart(2, \"0\");\r\n        const dia = String(fecha.getDate()).padStart(2, \"0\");\r\n        const hora = String(fecha.getHours()).padStart(2, \"0\");\r\n        const minuto = String(fecha.getMinutes()).padStart(2, \"0\");\r\n        const segundo = String(fecha.getSeconds()).padStart(2, \"0\");\r\n        return `${año}-${mes}-${dia} ${hora}:${minuto}:${segundo}`;\r\n    }\r\n\r\n\r\n    ////// consulta por fecha personalizada\r\n    consultarFechaPersonalizada.addEventListener('click', ()=>{\r\n      if(fechainicio == '' || fechafin == ''){\r\n         msjalertToast('error', '¡Error!', \"Elegir fechas a consultar\");\r\n         return;\r\n      }\r\n      callApiVentasXCliente(fechainicio, fechafin);\r\n    });\r\n\r\n    async function callApiVentasXCliente(dateinicio:string, datefin:string){\r\n        console.log(dateinicio, datefin);\r\n        (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"grid\";\r\n        const datos = new FormData();\r\n        datos.append('fechainicio', dateinicio);\r\n        datos.append('fechafin', datefin+' 23:59:59');\r\n        try {\r\n            const url = \"/admin/api/ventasxcliente\"; //llama a la api que esta en reportescontrolador.php\r\n            const respuesta = await fetch(url, {method: 'POST', body: datos}); \r\n            const resultado = await respuesta.json();\r\n            datosVentaXCliente = resultado;\r\n            printTableVentasXCliente();\r\n           (document.querySelector('.content-spinner1') as HTMLElement).style.display = \"none\";\r\n        } catch (error) {\r\n            console.log(error);\r\n        }\r\n    }\r\n\r\n\r\n    printTableVentasXCliente();\r\n    function printTableVentasXCliente(){\r\n        tablaVentasXCliente = ($('#tablaVentasXCliente') as any).DataTable({\r\n            destroy: true, // importante si recargas la tabla\r\n            data: datosVentaXCliente,\r\n            columns: [{title: 'Nombre', data: 'nombre'}, {title: 'Cantidad_facturas', data: 'cantidad_facturas'}, {title: 'Total ventas', data: 'total_ventas', render: (data:number) => `$${Number(data).toLocaleString()}`}],\r\n        });\r\n    }\r\n\r\n  }\r\n\r\n})();"]}
